P.entries["quest:962"] = {n="Зміїцвіт",s="«Зміїцвіт» — завдання зі збирання від Аптекарки Замах, посланниці Королівського Аптекарського Товариства в Тандер Блафі. Замах шукає зразки рідкісної трави, що росте в підземних глибинах Печер Стогонів, щоб допомогти дослідженням Відступників.",h="«Зміїцвіт» — завдання зі збирання від Аптекарки Замах, посланниці Королівського Аптекарського Товариства в...",kw={"зміїцвіт","аптекарка замах","королівське аптекарське товариство","печери стогонів","узвишшя духів","відступники"},ang={["faction:Horde"]="Це завдання скріплює ранній робочий союз Андерсіті з племенами Калімдору, що діляться ресурсами й рідкісними реагентами через океан.",["profession:Herbalism"]="Спотворене довкілля Печер Стогонів плекає унікальну флору, якої більше ніде не знайти на випаленій сонцем поверхні Пусток.",["race:Tauren"]="Гостинність до аптекарів-Відступників на Узвишші Духів відбиває дух Орди, хоча їхня зацікавленість смертельними сумішами різко контрастує з традиційним зціленням землі.",["race:Undead"]="Добуваючи зміїцвіт, ви прямо підтримуєте алхімічні починання Королівського Аптекарського Товариства в Лордероні за наказом Темної Леді."},sec={{t="Очі аптекарів",b="На Узвишші Духів у Тандер Блафі Аптекарка Замах представляє Королівське Аптекарське Товариство з Андерсіті. Поки господарі-таурени дбають про духовну рівновагу й зцілення пораненої землі, увага Замах прикута до рідкісних і отруйних матеріалів. Виділивши зразок незвичайної рослини — зміїцвіту, вона прагне отримати його у великих обсягах, щоб просунути дослідження, яких вимагають Леді Сильвана Віндраннер і Відступники."},{t="Глибини печер",b="Зміїцвіт не росте під відкритим сонцем Пусток — він буяє у вогких, звивистих гротах Печер Стогонів. Він виростає у вологому підземному кліматі, спотвореному сплюндрованими Друїдами Ікла, тож дістатися до нього важко, а стережуть його люті змієві мешканці печер. Замах відверто визнає, що чимало розвідників, яких посилали раніше, не повернулися, тож далі збирати зміїцвіт доведеться загартованим шукачам пригод."}},faq={{q="Хто така Аптекарка Замах?",a="Аптекарка Замах — дослідниця Королівського Аптекарського Товариства з Андерсіті. Вона перебуває в Тандер Блафі на Узвишші Духів і підтримує зв'язок між алхіміками Відступників і рештою Калімдору.",al={"замах","переказ про аптекарку замах","хто дає зміїцвіт"}},{q="Навіщо Королівському Аптекарському Товариству Зміїцвіт?",a="Замах вважає, що ця трава, якщо очищати її у великих кількостях, має значний прихований хімічний потенціал. Товариство невтомно шукає по всьому Калімдору рідкісні сильнодійні рослини, що можуть стати в пригоді в алхімічних дослідах Відступників.",al={"навіщо зміїцвіт","дослідження трав відступників","призначення зміїцвіту"}},{q="Де росте Зміїцвіт?",a="Зміїцвіт росте лише в підземних глибинах Печер Стогонів — у вогких кам'яних коридорах і ходах, вимитих під північними Пустками.",al={"де росте зміїцвіт","місце зміїцвіту"}},{q="Чому попередні розвідники не повернулися?",a="Печери Стогонів кишать здичавілими звірами, рапторами й зіпсованими скверною Друїдами Ікла. Менш досвідчених збирачів, яких посилали в заплутані тунелі, швидко здолали хижі мешканці печер і їхні отруйні захисники.",al={"зниклі розвідники","розвідники замах","чи печери стенань небезпечні"}},{q="Чи схвалюють таурени дослідження Замах?",a="Таурени Тандер Блафа дали Відступникам прихисток зі співчуття й бажання їх зцілити, але алхімічні практики Королівського Аптекарського Товариства часто балансують на межі неприродних дослідів, що непокоїть традиційних шаманів і друїдів.",al={"реакція тауренів","аптекарі підйому духів"}},{q="Чи потрібне травництво, щоб збирати Зміїцвіт?",a="Ні. Хоч це й рослина, будь-який шукач пригод, що наважиться спуститися в глибини Печер Стогонів, може зірвати її просто з долівки печери без жодної підготовки з травництва.",al={"чи потрібне травництво","збирання зміїцвіту професія"}}},fp="12,259,22.448.0,25.436.0,24.230.0,56.226.0,29.188.0,37.240.0,42.259.0,54.188.0"}
P.entries["quest:963"] = {n="Заради вічного кохання",s="«Заради вічного кохання» — трагічне завдання, яке дає Сереллеан Вайтклоу в Обердайні. Переслідуваний спогадами про втрачену кохану, Анаю Донраннер, Сереллеан просить шукача пригод вирушити до розбитих руїн Амет'Арана й звільнити її неспокійний дух від вічної муки.",h="«Заради вічного кохання» — трагічне завдання, яке дає Сереллеан Вайтклоу в Обердайні.",kw={"заради вічного кохання","сереллеан вайтклоу","аная донраннер","амет'аран","обердайн","підвіска"},ang={["class:Druid"]="Доля Сереллеана відбиває особисту ціну, яку заплатили друїди, що поринули в тисячолітній сон поруч із шан'до Стормрейджем, — і прокинулися у світі, досі позначеному їхніми давніми втратами.",["faction:Alliance"]="Допомагаючи Сереллеанові, герої Альянсу зазирають у трагічні, тисячолітні життя своїх союзників — нічних ельфів, — що звикають до світу наяву.",["race:NightElf"]="Для нічних ельфів Темного Узбережжя допомога Сереллеанові — щемке нагадування про незагоєні шрами Великого Розколу й падіння їхніх давніх міст."},sec={{t="Сон, повний горя",b="Десять тисяч років тому, під час Війни Прадавніх, катастрофа довкола Колодязя Вічності розірвала давній Калімдор. Серед жертв було й місто Амет'Аран, де Сереллеан Вайтклоу втратив кохану, Анаю Донраннер. Убитий відчаєм, Сереллеан пішов за шан'до Малфуріоном Стормрейджем у довгу сплячку друїдів, сподіваючись, що тисячоліття мандрів Смарагдовим Сном угамують його зболене серце. Натомість смуток не відпускав і йшов за ним крізь віки."},{t="Привид Амет'Арана",b="Прокинувшись нещодавно, Сереллеан блукав Темним Узбережжям у заціпенінні, доки ноги не привели його назад до сумних руїн Амет'Арана. Там, серед давнього каміння, він побачив змучений привид Анаї. Не в змозі підняти зброю на жінку, яку кохав, він благає мандрівників знищити її зболену подобу, забрати її підвіску й нарешті дати її неспокійній душі спокій."},{t="Прощання крізь завісу",b="When Anaya's pendant is returned to Auberdine, a spectral remnant of Anaya appears before Cerellean one last time. Freed from the lingering anguish that bound her to the ruins, she shares a brief farewell before fading away into the ether, leaving the grieving druid to weep in bittersweet solace by the seaside."}},faq={{q="Хто такий Сереллеан Вайтклоу?",a="Сереллеан Вайтклоу — друїд нічних ельфів, що перебуває в Обердайні. Утративши кохану Анаю під час Розколу десять тисяч років тому, він поринув у довгий друїдський сон разом із Шан'до Малфуріоном Стормрейджем і проніс свою незагоєну скорботу крізь тисячоліття.",al={"сереллеан","хто дає заради вічного кохання","переказ про сереллеана"}},{q="Хто така Аная Донраннер?",a="Аная Донраннер — нічна ельфійка, що жила в місті Амет'Аран до Великого Розколу. Вона загинула, коли місто впало після Війни Прадавніх, і відтоді її привид ув'язнений у руїнах.",al={"аная донраннер","хто така аная","аная темне узбережжя"}},{q="Де дух Анаї?",a="Її дух блукає давніми руїнами Амет'Арана, де кишать привиди, — на півдні Темного Узбережжя, на схід від головної дороги.",al={"місце анаї","де аная донраннер","місце підвіски анаї"}},{q="Чому Сереллеан не міг сам звільнити Анаю?",a="Навіть за десять тисяч років любов Сереллеана до Анаї була такою глибокою, що в нього не підіймалася рука вдарити її примару чи застосувати проти неї чари — навіть щоб покласти край її стражданням.",al={"чому сереллеан не звільнить анаю","чому сереллеан просить допомоги"}},{q="Що сталося з Амет'Араном?",a="Амет'Аран — давнє поселення нічних ельфів, зруйноване десять тисячоліть тому під час Розколу, що настав після Війни Прадавніх. Його руїни на Темному Узбережжі досі повні привидів і відлунь тайної магії.",al={"історія амет'арана","падіння амет'арана","що таке амет'аран"}},{q="Що станеться, коли повернути підвіску Анаї?",a="Звільнивши неспокійний дух Анаї, принесіть її підвіску Сереллеанові в Обердайн. Чим це скінчиться, стане відомо, коли ви повернетеся.",al={"здати підвіску анаї","кінець сереллеана","кінець вічного кохання"}}},fp="16,272,23.504.0,23.431.0,23.312.1,27.264.0,25.241.0,32.126.0,42.217.0,28.223.0,45.138.1"}
P.entries["quest:96390"] = {n="Задушити в зародку",s="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в Дун Мороґ. Таємних агентів помітили біля Поселення Айронбенда, і вони загрожують безпеці батьківщини Бронзбірдів.",h="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в...",kw={"темне залізо","шпигуни","фарсен","айронбенд","дун мороґ","карта"},ang={["faction:Alliance"]="Знешкодження ворожих розвідників у Дун Мороґу береже важливі шляхи постачання Айронфорджа й довколишні застави від диверсій.",["race:Dwarf"]="Для дворфів Бронзбірдів вичистити лазутчиків Темного Заліза з гір предків — справа захисту дому й давньої кланової помсти."},sec={{t="Очі на морозі",b="Дун Мороґ здавна був укріпленим прихистком дворфів Айронфорджа, та давня ворожнеча між дворфійськими кланами ніколи не спить по-справжньому. Лазутчики Темного Заліза прослизнули через високі перевали й засніжені скелі та підозріло скрадаються біля важливих розкопок і поселень. Провидець Землі Фарсен розуміє: навіть кілька прихованих спостерігачів можуть провіщати нищівний удар, — і кличе стійких захисників Альянсу викорінити їх, перш ніж їхні задуми вкореняться."},{t="Загроза біля Поселення Айронбенда",b="Шпигуни зосередили свої виправи довкола Поселення Айронбенда — важливого місця на сході Дун Мороґу. Хоч Фарсен спершу не може розгадати їхніх точних намірів, знищення таємних агентів дає речовий доказ їхнього більшого задуму. В обшуканих розвідників знаходять Карту Підземелля, і стає ясно: їхнє вторгнення — не просто розвідка, а підготовка, пов'язана з давніми підземними таємницями, як-от Зала Танів."}},faq={{q="Хто дає завдання «Задушити в зародку»?",a="Завдання дає Провидець Землі Фарсен після завдання «Спостереження Фарсена»: він просить допомогти впоратися з непроханими гостями в Дун Мороґу.",al={"хто дає задушити в зародку","видавець задушити в зародку","завдання фарсена"}},{q="Чому в Дун Мороґу шпигуни Темного Заліза?",a="Клан Темного Заліза постійно плете інтриги проти своїх родичів Бронзбірдів. Проникнувши на схід Дун Мороґу, їхні агенти можуть стежити за поселеннями й розкопувати чи розвідувати приховані підземні ходи біля Поселення Айронбенда.",al={"чому шпигуни темного заліза","що роблять темні залізні в дун мороґу","шпигуни айронбенд"}},{q="Де шпигуни Темного Заліза?",a="Вони зосередилися на сході, біля Поселення Айронбенда в східному Дун Мороґу, і чатують на засніжених околицях.",al={"місце шпигунів","де шпигуни темного заліза","де знайти шпигунів"}},{q="Що веде до цього доручення?",a="Це доручення йде після доповіді в завданні «Спостереження Фарсена»: оборона переходить від простого спостереження до активного знищення ворога.",al={"попереднє завдання","що перед задушити в зародку","передумова задушити в зародку"}},{q="Що вдається знайти, полюючи на шпигунів?",a="Зі вбитих шпигунів випадає Карта Темного Заліза, яка починає завдання «Карта Підземелля» й веде до глибших таємниць, пов'язаних із Залою Танів.",al={"що випадає зі шпигунів","карта темного заліза","наступне завдання після задушити в зародку"}},{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — уважний дворф у Дун Мороґу, що стежить за незвичними поштовхами в надрах і пересуваннями ворожих кланів у засніжених горах.",al={"хто такий фарсен","переказ про провидця землі фарсена"}}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Карта Підземелля",s="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів, прокопаних до коренів Айронфорджа. Її зубчасті руни Темного Заліза окреслюють прихований підземний шлях, що пронизує гору просто до давніх покоїв під нею. Доставити її Провидцю Землі Фарсену — перший крок до розкриття навислого вторгнення знизу.",h="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів...",kw={"карта підземелля","темне залізо","тунелі","айронфордж","фарсен","шпигуни"},ang={["class:Shaman"]="Легкий порив вітру, що веде вас до Провидця Землі Фарсена, натякає на духів стихій, які застерігають про неприродні підземні розкопки під Дун Мороґом.",["faction:Alliance"]="Знешкодити цей підземний шлях проникнення конче потрібно, щоб зберегти безпеку Айронфорджа — північного якоря Альянсу.",["race:Dwarf"]="Для дворфів Бронзбірдів виявлення тунелів Темного Заліза, прорубаних просто до підвалин Айронфорджа, — грубе порушення недоторканності столиці."},sec={{t="Креслення проникнення",b="The parchment recovered from Dark Iron spies near Ironband's Compound displays an intricate maze of subterranean roads. Inscribed in harsh, jagged runes unique to the Dark Iron clan, the diagrams map deep underground passages that converge directly beneath Ironforge. The converging passages suggest a possible threat beneath the Bronzebeard capital, but the map's Dark Iron annotations remain uncertain."},{t="Шепіт на вітрі",b="Коли ви вивчаєте грубу картографію, неприродний порив вітру доносить ледь чутний шепіт дворфійського голосу, що закликає діяти негайно. Містичний знак ясно вказує, хто має почути про це першим: Провидець Землі Фарсен. Доповідь про ці відомості викриває перші кроки до давніх зал, запечатаних глибоко під містом, і загрозу прихистку гірського королівства."}},faq={{q="Звідки взялася ця підземна карта?",a="Карту носять шпигуни Темного Заліза, що розвідують околиці Поселення Айронбенда в Дун Мороґу. Її можна знайти, розбираючись із їхніми розвідниками в передгір'ї.",al={"випадіння карти","де знайти карту","як отримати підземну карту"}},{q="Що показує карта?",a="It outlines a complex network of underground highways and tunnels snaking through the earth, all converging directly beneath the city of Ironforge.",al={"що на карті","деталі карти","призначення карти темного заліза"}},{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — дворф-провидець з Орлиного Піку, що відчуває глибинні скелі й духів гори. Відчувши неприродний рух під землею, він потребує карти, щоб оцінити прорив під Айронфорджем.",al={"де фарсен","хто такий фарсен","провидець землі"}},{q="Чому дворфи Темного Заліза копають під Айронфорджем?",a="The map suggests a possible route beneath Ironforge, but its Dark Iron annotations have not been deciphered. Earthseer Farsen needs to examine it before the plan can be established.",al={"чому темні залізні копають","задум темного заліза в дун мороґу"}},{q="До чого веде це завдання?",a="Доставивши карту Провидцеві Землі Фарсену, ви починаєте розслідування в глибинах під містом, що веде просто до «Вторгнення у Старий Айронфордж» і відкриває шлях до Зали Танів.",al={"продовження підземної карти","наступне завдання після підземної карти"}},{q="Якою мовою написані руни на карті?",a="The map uses the jagged runic script of the Dark Iron dwarves. The person who finds it cannot be sure what the annotations say.",al={"руни на карті","мова темного заліза"}}},fp="15,383,27.404.0,20.344.1,41.165.0,23.147.0,24.216.0,49.181.0,29.201.1,45.127.0"}
P.entries["quest:96392"] = {n="Спостереження Фарсена",s="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану Вайлдгаммерів, що розташувався високо над Кар'єром Гол'Болар. Завдяки шаманському далекозору провидця шукачі пригод на власні очі бачать, як дворфи Темного Заліза дедалі глибше проникають у серце Дун Мороґу. Цей важливий огляд — ранній крок на шляху до Зали Танів.",h="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану...",kw={"фарсен","провидець землі","вайлдгаммер","гол'болар","темне залізо","далекозір","шаман"},ang={["class:Shaman"]="Провидці землі з клану Вайлдгаммерів показують земний і духовний зір своєї традиції — погляд на дворфійський шаманізм, вкорінений у скелях Орлиного Піку.",["faction:Alliance"]="Викриття змов Темного Заліза в Дун Мороґу життєво важливе для безпеки Айронфорджа та довколишніх гірських перевалів для всіх подорожніх Альянсу.",["race:Dwarf"]="Для захисників Бронзбірдів попередження від родича з Орлиного Піку показує, якою зухвалою стала інфільтрація Темного Заліза на їхню батьківщину."},sec={{t="Очі над хребтом",b="Умостившись над заметеними снігом розкопками Кар'єру Гол'Болар, Провидець Землі Фарсен пильно стежить за нижніми землями Дун Мороґу. Прибувши з півночі, зі скель Орлиного Піку, гість із клану Вайлдгаммерів приносить гостре духовне чуття в землі, які зазвичай патрулюють горяни Айронфорджа. Замість покладатися на простих розвідників, Фарсен уживає традиційні мистецтва свого клану, щоб стежити за підземним гуркотом і несподіваним рухом на схилах."},{t="Позичений зір",b="Щоб переконати мандрівників у близькій небезпеці, Фарсен позичає їм свій далекозір — шаманський дар, що переносить свідомість на величезні відстані. Крізь духовну лінзу стає очевидно: біди Дун Мороґу сягають далеко за неслухняних трогів і диких звірів. Дворфи Темного Заліза підібралися впритул до промислового серця Айронфорджа й окопуються для операції, яку треба зупинити негайно, доки вона не вкоренилася."}},faq={{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — дворф із Вайлдгаммерів, що прибув до Дун Мороґу з Орлиного Піку в Пригір'ї. Як провидець землі, він володіє шаманською магією, що дає змогу відчувати збурення в землі й бачити загрози здалеку.",al={"провидець землі фарсен","хто такий фарсен","фарсен вайлдхаммер"}},{q="Де відбувається це спостереження?",a="Провидець Землі Фарсен стоїть над Кар'єром Гол'Болар — важливими розкопками Бронзбірдів на сході Дун Мороґу.",al={"місце спостереження фарсена","де фарсен","огляд кар'єру"}},{q="Яку загрозу розкриває Фарсен?",a="Своїм шаманським далекобаченням Фарсен з'ясовує, що вороже налаштовані дворфи Темного Заліза закріпилися поблизу й становлять реальну й небезпечну загрозу для краю.",al={"що показує далекозорість","загроза темного заліза","видіння фарсена"}},{q="Як це пов'язано із Залою Танів?",a="Розслідування присутності Темного Заліза, виявленої під час спостереження Фарсена, починає довший ланцюжок завдань для шукачів пригод, які прагнуть потрапити до Зали Танів.",al={"настройка на залу танів","ланцюжок зали танів"}},{q="Чому дворф із Вайлдгаммерів бере участь в обороні Дун Мороґу?",a="Вайлдгаммери живуть у Пригір'ї, але кровні зв'язки й спільна ворожнеча до Темного Заліза часом приводять мандрівників на кшталт Фарсена до родових земель Бронзбірдів у Дун Мороґу.",al={"чому вайлдхаммер тут","дворф з орлиного піку в дун мороґу"}},{q="Що йде одразу після «Спостереження Фарсена»?",a="Коли ви побачите через його видіння, як проникає Темне Залізо, Фарсен підганяє вас далі — у завдання «Задушити в зародку», щоб дати відсіч ворогові, який підступає.",al={"наступне завдання","що після спостереження фарсена","задушити в зародку"}}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Вторгнення у Старий Айронфордж",s="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися глибоко під Айронфорджем. За вказівкою Провидця Землі Фарсена герої спускаються в давню Залу Танів під Старим Айронфорджем, щоб знищити ворожого командира Дурґена Дерджгаммера й доповісти про загрозу особисто Королю Маґні Бронзбірду.",h="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися...",kw={"старий айронфордж","зала танів","дерджгаммер","темне залізо","фарсен","король маґні"},ang={["faction:Alliance"]="Зупинивши вторгнення, ви запобігаєте нищівному раптовому удару по головній твердині Альянсу у Східних Королівствах.",["race:Dwarf"]="Для Бронзбірдів лазутчики Темного Заліза, що причаїлися в забутих склепіннях під Високим Престолом, — нестерпне осквернення фортеці предків."},sec={{t="Прорив у склепіння",b="Після знахідки підземної карти, що розкрила пересування Темного Заліза, Провидець Землі Фарсен визначає натхненника підземного вторгнення. Глибоко в давніх кам'яних залах Старого Айронфорджа лежить вхід до Зали Танів. Поки верхнє місто клопочеться поверхневими справами, підступні сили прослизнули в ці заснулі печери просто під ногами королівства."},{t="Дурґен Дерджгаммер",b="Переклад захоплених документів Темного Заліза, зроблений Фарсеном, указує на єдиного командира, що керує операцією: Дурґена Дерджгаммера. Засівши глибоко в нижніх склепіннях, Дерджгаммер становить пряму загрозу серцю гірського королівства Бронзбірдів. Щоб зламати хребет вторгненню, шукачі пригод мають пірнути в глибини, здолати його і віднести його відрубану голову нагору, Королю Маґні Бронзбірду."},{t="Аудієнція в короля",b="Голова Дурґена Дерджгаммера, піднесена Королю Маґні Бронзбірду, підтверджує похмуру правду про загрозу Темного Заліза, що повзе крізь давнє коріння міста. Принісши і моторошний доказ перемоги, і особисте вітання від його давнього друга Фарсена, шукачі пригод офіційно завершують розслідування і впевнюються, що Маґні знає, що чаїться внизу."}},faq={{q="Що таке «Вторгнення у Старий Айронфордж»?",a="Це фінал ланцюжка завдань про діяльність Темного Заліза під Дун Мороґом. Його дає Провидець Землі Фарсен: гравцям треба спуститися до Зали Танів під Старим Айронфорджем і вбити командира Темного Заліза Дурґена Дерджгаммера.",al={"завдання вторгнення у старий айронфордж","завдання дурґена дерджгаммера"}},{q="Де відбувається це завдання?",a="Доручення веде шукачів пригод до Зали Танів — давньої підземної зали під Старим Айронфорджем, глибоко в скельній основі під гірською столицею.",al={"де зала танів","місце зали танів"}},{q="Хто такий Дурґен Дерджгаммер?",a="Дурґен Дерджгаммер — командир Темного Заліза, що веде підземне вторгнення до Зали Танів під Старим Айронфорджем. Провидець Землі Фарсен дізнається його ім'я із захоплених документів Темного Заліза.",al={"хто такий дерджгаммер","дурґен дерджгаммер"}},{q="Хто дає завдання і кому його здавати?",a="Завдання дає Провидець Землі Фарсен після того, як здобуто Карту Підземелля. Здавати його треба самому Королю Маґні Бронзбірду в Айронфорджі.",al={"хто дає вторгнення у старий айронфордж","кому здати вторгнення у старий айронфордж"}},{q="Як почати ланцюжок завдань, що веде до цього?",a="Ланцюжок починається із завдання «Гість у Дун Мороґу», яке дає Белдін Стілґрілл біля Хараноса в Дун Мороґу.",al={"як почати ланцюжок зали танів","початок для гостя в дун мороґу"}},{q="Що пов'язує Провидця Землі Фарсена й Короля Маґні?",a="Провидець Землі Фарсен вважає себе давнім другом Короля Маґні Бронзбірда й просить шукачів пригод передати йому особисте вітання, коли ті принесуть до тронної зали голову Дурґена Дерджгаммера.",al={"фарсен і маґні","переказ про провидця землі фарсена"}}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96395"] = {n="Давня ворожнеча",s="Глибоко в історичній Залі Танів примарний слуга благає покласти край мукам полеглого правителя. Дух Фалдріма Анвілмара досі не відійшов, поглинутий давньою образою й позбавлений вічного спокою. Шукачам пригод доручено вгамувати неспокійного тана.",h="Глибоко в історичній Залі Танів примарний слуга благає покласти край мукам полеглого правителя.",kw={"давня ворожнеча","фалдрім анвілмар","зала танів","привид","тан","завдання"},ang={["class:Paladin"]="Дати спокій змученій душі — урочистий обов'язок святих воїнів, що присягнули нести мир стражденним мерцям.",["class:Priest"]="Жерці знають, що незгасна образа й неспокутуване горе можуть прикувати дух смертного до світу живих ще довго після того, як тіло обернулося на порох.",["race:Dwarf"]="Для дворфів зустріч із неспокійним таном власного народу — тверезе нагадування, що давня образа може пережити саму смерть."},sec={{t="Благання з-за могили",b="У кам'яних склепах Зали Танів смерть не дає швидкого перепочинку. Там досі блукає примарний слуга Фалдріма Анвілмара, якому ледве вистачає сили промовити крізь завісу смерті. Він не шукає волі для себе: його турбує лише господар, тож він благає мандрівників угамувати буремний дух тана."},{t="Тягар минулого",b="Смерть не звільнила Фалдріма Анвілмара від минулого. Прикутий до світу живих усепоглинною давньою образою, привид Фалдріма лишається збуреним і ворожим і не знайде спочинку, доки його не звільнять силою."}},faq={{q="Хто такий Фалдрім Анвілмар?",a="Фалдрім Анвілмар був таном дворфів, чия неспокійна примара тепер блукає Залою Танів. Його Примарний Прислужник каже, що Фалдріма пожирає давня ворожнеча й він не знаходить спокою. Більше про його життя чи рід у завданні нічого не сказано.",al={"переказ про фалдріма анвілмара","хто такий фалдрім","тан анвілмар"}},{q="Де Зала Танів?",a="Зала Танів — у печерах під Старим Айронфорджем, у межах дворфійської столиці Айронфордж.",al={"місце зали танів","де зала танів","вхід до зали танів"}},{q="Чому привид Фалдріма Анвілмара ворожий?",a="За словами примарного прислужника, колишнього тана пожирає давня ворожнеча. Історія дворфів просякнута століттями чвар між кланами, і невгасима ненависть Фалдріма не дає його духові відійти до мирного сну.",al={"чому фалдрім злий","чому тан нападає","пояснення давньої ворожнечі"}},{q="Хто дає завдання «Давня ворожнеча»?",a="Завдання дає Примарний Прислужник у Залі Танів. Прикутий до служби навіть після смерті, прислужник прагне лише спокою для свого колишнього господаря.",al={"хто починає давню ворожнечу","завдання привидного служки","видавець"}},{q="Що треба зробити, щоб виконати завдання?",a="Треба зустрітися з духом Фалдріма Анвілмара в Залі Танів, здолати в бою його неспокійний привид, щоб звільнити від мук, і доповісти Примарному Прислужникові.",al={"як закінчити давню ворожнечу","упокоїти фалдріма","мета давньої ворожнечі"}},{q="Чи пов'язаний Фалдрім із містечком Анвілмар?",a="Поки що невідомо. Ім'я Фалдріма збігається з назвою поселення Анвілмар у Долині Холодного Хребта, але в завданні нічого не сказано ні про його родину, ні про зв'язок із містечком.",al={"чи фалдрім з анвілмара","зв'язок анвілмара з колдрідж","родина анвілмар"}}},fp="17,276,21.348.0,22.214.1,24.233.0,36.102.0,45.234.0,38.168.0,39.186.0,43.166.0"}
P.entries["quest:96408"] = {n="Гість у Дун Мороґу",s="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса. Горяни доповіли про незнайоме багаття високо на скелях над Кар'єром Гол'Болар, і треба розвідати, чи не загрожує чужинець місцевим дворфам.",h="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса.",kw={"гість","дун мороґ","фарсен","стілґрілл","гол'болар","багаття","харанос"},ang={["class:Shaman"]="Зустріч із Провидцем Землі Фарсеном напряму пов'язана з духовним єднанням із гірським камінням — рідкісне видовище на засніжених висотах Дун Мороґу.",["faction:Alliance"]="Допомога місцевим горянам біля Хараноса гарантує, що шляхи постачання й робітники кар'єру лишаться в безпеці від непередбачених загроз.",["race:Dwarf"]="Для дворфів Бронзбірдів нагляд за непроханими спостерігачами над великими копальнями, як-от Гол'Болар, — звичайна безпекова справа для захисту кордонів Каз Модану."},sec={{t="Стовп диму на висотах",b="Горяни Дун Мороґу пильно стежать за скелями й засніженими долинами довкола Айронфорджа. Коли високо над Кар'єром Гол'Болар раптом з'явилося багаття, в Хараносі здивовано звели брови. Белдін Стілґрілл, стривожений незвичним табором просто над важливою дворфійською копальнею, наймає мандрівників, щоб ті вибралися на гребені й з'ясували, хто цей таємничий незнайомець — мирний подорожній чи зайда."},{t="Зустріч із провидцем землі",b="Розвідка гребеня показує, що мандрівник — це Провидець Землі Фарсен, містик, який розбив табір на продутих вітрами висотах. Далеко не мародер-трог і не відверто ворожий шпигун, цей таємничий спостерігач має глибокий духовний зв'язок із землею. Його присутність на кручі над кар'єром починає шлях до розкриття глибших заворушень, прихованих під Каз Моданом, що зрештою сплітається з таємницею Зали Танів."}},faq={{q="Хто посилає вас з'ясувати, що за гість?",a="Белдін Стілґрілл, що стоїть біля Хараноса в Дун Мороґу, дає завдання після того, як горяни повідомили про незнайоме вогнище на пагорбах.",al={"хто дає це завдання","початок завдання","завдання белдіна стілґрила"}},{q="Де загадковий табір?",a="Вогнище горить високо на засніжених хребтах на схід від Хараноса, просто над розкопками Кар'єру Гол'Болар.",al={"місце табору","де гість","місце гостя"}},{q="Хто цей гість, що дивиться на кар'єр?",a="Гість — Провидець Землі Фарсен, духовний спостерігач, що отаборився у відлюдному місці на висотах над кар'єром.",al={"хто такий фарсен","хто гість","провидець землі фарсен"}},{q="Чому дворфам здалося підозрілим вогнище?",a="Кар'єр Гол'Болар — важливі дворфійські розробки, які й так потерпають від місцевих трогів. Будь-який невідомий табір високо над котлованом цілком міг належати розвідникам чи ворожим силам, що стежать за пересуваннями дворфів.",al={"чому підозріло","чому розслідувати","чому посилають мене"}},{q="До чого веде це завдання?",a="Доповідь Провидцеві Землі Фарсену веде просто до завдання «Спостереження Фарсена» й стає першим кроком ланцюжка доступу до Зали Танів.",al={"що далі","наступне завдання","вступ до зали танів"}},{q="Чи треба битися з незнайомцем у таборі?",a="Ні. Белдін Стілґрілл готує вас до можливої сутички, але гість — Провидець Землі Фарсен, мирний спостерігач, що охоче з вами поговорить.",al={"чи гість ворожий","чи вбивати гостя","бій з гостем"}}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:965"] = {n="Вежа Альталакса",s="Вартова Елісса Старбріз, відповідальна за оборону Обердайна, підозрює лихі справи в давніх руїнах на півночі. Вона доручає шукачам пригод знайти Балтула Шедовстрайка — розвідника, якого послали стежити за загадковою Вежею Альталакса і який вчасно не доповів.",h="Вартова Елісса Старбріз, відповідальна за оборону Обердайна, підозрює лихі справи в давніх руїнах на півночі.",kw={"вежа альталакса","вартова елісса старбріз","балтул шедовстрайк","розвідник","обердайн","темне узбережжя"},ang={["faction:Alliance"]="Обердайн — головні ворота Альянсу на північ Калімдору, тож захист навколишніх доріг і кордонів важливий для всіх союзників, що сюди прибувають.",["race:NightElf"]="Руїни Альталакса — нагадування про занепале минуле Високородних давнього Калімдору, і вберегти Обердайн від порчі, що гноїться в тому камінні, — важливий обов'язок Вартових нічних ельфів."},sec={{t="Зниклий розвідник",b="Auberdine's sentinels must remain ever watchful over Darkshore's creeping perils. Sentinel Elissa Starbreeze noticed suspicious activity stirring around the Tower of Althalaxx in the northern reaches of the forest. She sent Balthule Shadowstrike to survey the ancient ruin. Days have passed without word from the scout, prompting Elissa to seek a willing traveler to journey north, locate Balthule, and ensure he has not met an untimely end."},{t="Очі над руїнами",b="Дорога на північ з Обердайна минає давні руїни калдореїв і перетинає Річку Скельного Джерела, перш ніж вийти до тінистих нетрів довкола вежі. Хоч Балтул і не міг передати звістку до Обердайна, він пережив свою першу розвідку. Коли його знаходять у навколишніх лісах, він підтверджує, що чуття не підвело Еліссу: в обваленій кам'яній вежі відбуваються темні й тривожні події."}},faq={{q="Хто така Вартова Елісса Старбріз?",a="Елісса Старбріз — Вартова нічних ельфів в Обердайні. Їй доручено захищати поселення від зовнішніх загроз по всьому Темному Узбережжю, і вона стежить за небезпеками в окрузі, як-от за Вежею Альталакса.",al={"елісса старбріз","хто дає завдання","видавець оберіжина"}},{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — розвідник, якого Вартова Елісса Старбріз послала стежити за загадковою діяльністю довкола Вежі Альталакса. Він чатує біля руїн, пильнуючи ворожі сили.",al={"балтул","хто розвідник","балтул шедовстрайк"}},{q="Де Вежа Альталакса?",a="Вежа — на північному сході Темного Узбережжя. Щоб дістатися до неї, вирушайте з Обердайна на схід, ідіть північною дорогою повз Башал'Аран і перейдіть міст через Річку Скельного Джерела, доки не побачите шпиль.",al={"місце вежі альталакса","де вежа","як знайти альталакса"}},{q="Навіщо взагалі послали розвідника до вежі?",a="Elissa sent Balthule to observe strange happenings around the Tower of Althalaxx while carrying out her charge to protect Auberdine.",al={"навіщо стежити за вежею","що не так в альталаксі","чому послали балтула"}},{q="Чому Балтул не повернувся до Обердайна?",a="Елісса не отримала донесення від Балтула й просить вас довідатися, що з ним. Коли ви його знайдете, Балтул сам пояснить, у якому він становищі.",al={"чому балтул зник","чи балтул в пастці","чому балтул лишився"}},{q="Чи має цей ланцюжок завдань продовження?",a="Так. Знайшовши Балтула Шедовстрайка, ви починаєте розслідування з кількох частин — про темні сили, що захопили Вежу Альталакса, та їхні зловісні задуми на Темному Узбережжі.",al={"чи це ланцюжок","яке завдання далі","ланцюжок альталакса"}}},fp="22,285,23.441.0,18.424.1,34.211.0,29.214.0,40.228.0,53.132.0,42.125.0,31.166.0"}
P.entries["quest:966"] = {n="Вежа Альталакса",s="Розслідуючи підозрілу діяльність довкола Вежі Альталакса на півночі Темного Узбережжя, розвідник Балтул Шедовстрайк шукає помічників, щоб дізнатися більше про чорнокнижників, які там гуртуються. За покинутими клаптиками пергаменту, відібраними у фанатиків, що отаборилися біля руїн, він намагається з'ясувати, хто такі ці культисти і яка їхня зловісна мета.",h="Розслідуючи підозрілу діяльність довкола Вежі Альталакса на півночі Темного Узбережжя, розвідник Балтул...",kw={"вежа альталакса","балтул шедовстрайк","культ темного берега","зношений пергамент","делґрен очищувач","чорнокнижники"},ang={["class:Paladin"]="Виявлення згуртованого темного культу на півночі Темного Узбережжя безпосередньо допомагає хрестовому походові Делґрена Очищувача — союзника, що присвятив себе вичищенню скверни й демонічної порчі.",["class:Warlock"]="Культ Темного Берега доводить, що незалежні ковени захоплюють давні руїни, щоб чинити свої викликання подалі від цікавих очей влади і Альянсу, і Орди.",["race:NightElf"]="Осквернення Вежі Альталакса людьми-культистами й демонами — ще одна наруга над давньою ельфійською спадщиною на берегах Калімдору."},sec={{t="Очі на мілинах",b="Балтул Шедовстрайк стоїть на варті на імлистому березі півночі Темного Узбережжя й пильно стежить за давніми руїнами, відомими як Вежа Альталакса. Його послали наглядати за цим місцем для Обердайна й попереджати Делґрена Очищувача про будь-яку небезпеку, але Балтул не наважувався покинути пост, щоб доповісти. Боячись проґавити важливі рухи темних чаклунів, що засіли в камінні, він натомість покладається на мандрівників, які розвідають табори довкола."},{t="Розгадати культ",b="Нижчі послідовники, що блукають зруйнованими околицями, носять уривки сувоїв і записок. Склавши докупи кілька зношених пергаментів, відібраних у цих зовнішніх культистів, Балтул натрапляє на тривожну назву — Культ Темного Берега. Ця тіньова секта йому зовсім невідома, і розвідник розуміє: небезпека куди організованіша, ніж звичайна зграя свавільних чорнокнижників, тож Делґрена треба попередити негайно."}},faq={{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — розвідник Альянсу, що стоїть на дорозі біля Вежі Альталакса на півночі Темного Узбережжя. Його послали стежити за підозрілими зібраннями біля вежі за дорученням проводу Обердайна й паладина Делґрена Очищувача.",al={"переказ про балтула шедовстрайка","хто такий балтул","балтул темне узбережжя"}},{q="Що таке Вежа Альталакса?",a="Вежа Альталакса — давні ельфійські руїни на півночі Темного Узбережжя. Останнім часом підступні чорнокнижники та їхні раби-культисти захопили околиці й саму вежу та правлять там темні обряди далеко від очей Обердайна.",al={"вежа альталакса","що таке альталакс","зруйнована вежа темного узбережжя"}},{q="Хто ці культисти довкола вежі?",a="Вони належать до Культу Темного Берега — таємної організації чорнокнижників і фанатиків, що зібралися в давніх ельфійських руїнах, щоб проводити темні обряди закликання.",al={"хто чорнокнижники","культ темного берега","фанатики темного берега"}},{q="Чому Балтул застерігає від того, щоб заходити у вежу?",a="Балтул зауважує, що чорнокнижники у верхній частині вежі набагато могутніші й небезпечніші за фанатиків, які отаборилися довкола серед руїн. Він радить спершу зібрати відомості на околицях, а вже тоді штурмувати твердиню.",al={"чи можна входити у вежу","чорнокнижники вежі небезпечні","всередині вежі"}},{q="Що розкривають пошарпані пергаменти?",a="Клаптики, які носять фанатики культу, вперше чітко підтверджують назву угруповання — Культ Темного Берега — і показують Балтулові, що захопники вежі — організована секта, чия присутність становить безпосередню загрозу краю.",al={"що на пергаментах","переказ про пошарпаний пергамент","записи культу"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — паладин Альянсу на Посту Маестри в Ашенвалі, що вичищає демонічний і зіпсований скверною вплив. Він запідозрив, що у Вежі Альталакса вкорінюється щось лихе, і покладається на розвідників на кшталт Балтула.",al={"делґрен","хто такий делґрен","делґрен очищувач"}}},fp="22,337,20.454.0,20.404.1,29.253.0,31.250.0,43.171.0,50.247.0,35.255.0,28.265.0"}
P.entries["quest:96607"] = {n="Широкі простори",s="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому Азероту. Присівши на хвилину біля теплого багаття, новачки дізнаються, як добрий відпочинок і підготовка зберігають життя шукачеві пригод поза міськими мурами. Це перший крок до опанування виживання в дикій природі й облаштування польових таборів.",h="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому...",kw={"широкі простори","виживання","багаття","табір","відпочинок","ремесла","азерот"},ang={["faction:Alliance"]="У безпечному Лісі Елвінн люди-мандрівники засвоюють ці основи виживання від досвідчених подорожніх, перш ніж зіткнутися з суворішими загрозами, що чигають у Вестфолі й Редріджі.",["faction:Horde"]="Чи то перетинаючи посушливі рівнини Дуротару, чи обвітрені плато Малгору, знавці виживання Орди прищеплюють кожному молодому воїнові вміння розводити вогонь і дисципліну життя просто неба.",["profession:Cooking"]="Кожен табір у глушині починається з вогню, тож кулінарія — природна супутниця виживання просто неба. Після цього уроку майстри табірної справи одразу спрямовують вас на придорожню науку куховарства."},sec={{t="Уроки дороги",b="Хоч який гострий ваш клинок і хоч яка могутня магія, нетрі Азерота швидко стирають на порох кожного, хто нехтує основами виживання. Бувалі мандрівники, що стоять біля придорожніх галявин, дають цей простий урок подорожнім, які вирушають із рідних долин. Відпочинок біля багаття не лише дає перепочити натрудженим ногам — він заспокоює розум і готує дух до суворої дороги попереду. Лише ті, хто опанував дисципліну регулярного відпочинку й підготовки, мають шанс прожити досить довго, щоб здобути багатство й славу."},{t="Дім далеко від дому",b="Щойно шукач пригод усвідомлює цінність тріскучого вогню й доброго відпочинку, наставники відсилають його просто до міських ремісників. Табір у полі рідко обмежується жаринкою й постіллю; виживання вимагає практичних ремесел. Чи то кувати запасні заклепки, чи готувати похідні харчі, чи зашивати порване спорядження під зорями — кожне ремесло дає особливі табірні речі, що перетворюють голий схил на самодостатню стоянку."}},faq={{q="Хто дає цей урок новим мандрівникам?",a="Залежно від того, де ви перебуваєте, цю науку дають різні бувалі мандрівники. У Лісі Елвінн за неї береться досвідчений мандрівник Сем Сарсапарілла, а деінде своїм досвідом життя в нетрях діляться Ерік Брайтгаммер, Лайріна Даскблейд, Бракк, Елеанор Шеклтон, Каґа Вайлдгуф і Раан Вайлдвінд.",al={"хто дає широкі простори","хто починає широкі простори","видавець широких просторів"}},{q="Навіщо сидіти біля вогнища?",a="Тихо посидівши біля палахкого вогнища, шукач пригод переводить подих і отримує ефект «Посилений відпочинок». Свідомо відпочивати в дорозі вкрай важливо, щоб не втрачати сил у довгих мандрах нетрями.",al={"навіщо сидіти біля вогнища","що робить багаття","баф відпочинку"}},{q="Куди веде це навчання далі?",a="Коли ви відпочинете біля вогню, наставник посилає вас до найближчих поселень опановувати практичні ремесла. Звідти ви починаєте «Табірну науку 101: кулінарія», а також окремі уроки польового табору, пов'язані з тією професією, яку ви оберете.",al={"що після широких просторів","наступне завдання широких просторів","табірні завдання"}},{q="Чи можуть шукачі пригод з Орди теж узятися за цей урок?",a="Так. Виживати в суворих нетрях доводиться всім, хоч би кому ти служив. Бувалі наставники й Альянсу, і Орди — як-от Бракк, Елеанор Шеклтон і Каґа Вайлдгуф — навчають новачків своєї фракції тих самих основ табірного вміння.",al={"чи це лише для альянсу","широкі простори орда","чи орки можуть це"}},{q="Чому наставники радять звернутися до наставників ремесел?",a="Щоб вижити, мало просто сидіти біля вогню — шукачеві пригод потрібна самостійність. Наставники ремесел навчать вас виготовляти особливе табірне облаштування для вашого ремесла, хай то куховарство в дорозі, лагодження обладунків чи варіння ліків просто неба.",al={"чому вчитися професій","табірні приладдя наставники ремесел","зв'язок професій і табору"}},{q="Який досвід потрібен, перш ніж узятися за це завдання?",a="Зазвичай цей урок шукачі пригод отримують одразу після завдання «Шукач пригод», коли вже довели свою рішучість і вийшли з початкових осель у ширший край.",al={"вимоги широких просторів","як відкрити широкі простори","перед широкими просторами"}}},fp="18,359,20.539.0,21.445.0,40.310.0,47.231.0,35.262.0,52.261.0,61.278.0,59.186.0"}
P.entries["quest:96627"] = {n="Шукач пригод",s="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу. Визнавши вашу ранню вправність, Макбрайд посилає вас за межі відлюдних земель абатства до Ґолдшира — придивитися до новоприбулого на ім'я Сем Сарсапарілла.",h="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу.",kw={"шукач пригод","маршал макбрайд","сем сарсапарілла","ґолдшир","нортшир","дороговказ"},ang={["faction:Alliance"]="Для свіжих новобранців Альянсу, що завершують службу в Нортширі, це перший офіційний крок у ширше королівство Лісу Елвінн.",["race:Human"]="Захисники з людей, виходячи з Абатства Нортшира, роблять перші кроки до Ґолдшира — гамірного серця Елвінну."},sec={{t="Прощання з долиною",b="Щойно новобранці очищають Долину Нортширу від найближчих загроз — місцевих Дефіас і шкідників, — Маршал Макбрайд починає дивитися далі дорогою. Регулярні сили Стормвінда розтягнуті по всьому королівству, тож місцевий гарнізон мусить покладатися на перспективних бійців, щоб наглядати за подорожніми й мандрівниками, які блукають довколишніми лісами."},{t="Цікавий новачок",b="Замість військового наказу чи полювання за винагороду Макбрайд дає вам незвичне доручення: перевірити одного нового шукача пригод, поміченого біля Ґолдшира, на ім'я Сем Сарсапарілла. Це прохання стає переходом із відлюдної долини Нортширу в ширші й небезпечніші простори Лісу Елвінн."}},faq={{q="Хто дає мені це доручення?",a="Маршал Макбрайд, командир гарнізону Стормвінда в Долині Нортширу, дає це доручення, щойно ви доведете свою звитягу, боронячи абатство.",al={"хто дає завдання","хто дає шукача пригод","завдання маршала макбрайда"}},{q="Хто такий Сем Сарсапарілла?",a="Сем Сарсапарілла — шукач пригод, що затримався біля дороги поблизу Ґолдшира. Маршал Макбрайд прочуває про нього й просить вас з'ясувати, що той замислив.",al={"сем сарсапарілла","хто такий сем","шукач пригод у ґолдширі"}},{q="Де знайти Сема Сарсапаріллу?",a="Він біля головної дороги, що веде з Нортширу до містечка Ґолдшир у Лісі Елвінн.",al={"місце сема сарсапарілли","де сем","знайти сема сарсапаріллу"}},{q="Чому Маршала Макбрайда цікавить якийсь випадковий шукач пригод?",a="Нортшир і досі насторожі через розбійників і непроханих гостей. Макбрайд воліє пильно стежити за незнайомими найманцями й мандрівниками, що проходять краєм, і доручає надійним місцевим першими виходити з ними на зв'язок.",al={"чому посилати мене","мотиви макбрайда","чому шукати сема"}},{q="Чи треба покидати Долину Нортширу, щоб виконати це?",a="Так. Доручення веде вас крізь південну браму Долини Нортширу на лісову дорогу до Ґолдшира.",al={"за межами нортширу","чи покидати нортшир","йти до ґолдшира"}},{q="Чи це звичайне доручення військового командування Стормвінда?",a="Хоч його й дає офіцер Стормвінда, Макбрайд прямо називає його незвичним, а не звичайною вартовою службою: він покладається на вашу розважливість як незалежного захисника, а не на військовий статут.",al={"військо стормвінда","чи це стандартна служба","службова справа"}}},fp="14,244,18.338.0,18.303.0,26.159.0,24.165.0,33.105.0,56.225.0,52.129.0,63.210.0"}
P.entries["quest:96628"] = {n="Шукач пригод",s="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу. Перш ніж пропустити мандрівників гірським тунелем до Хараноса, Талос просить віднести пакунок припасів Еріку Брайтгаммеру — новоприбулому, що отаборився одразу за селищем.",h="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу.",kw={"шукач пригод","талос","брайтгаммер","харанос","припаси","горянин","дун мороґ"},ang={["faction:Alliance"]="Горяни покладаються на новобранців Альянсу, щоб ті носили важливі припаси крижаними дорогами і союзники-мандрівники за Хараносом не лишалися без провізії.",["race:Dwarf"]="Для юних дворфів, що покидають Долину Холодного Хребта, доставка провізії Еріку Брайтгаммеру — перша спільна справа з горянами у ширшому краї Дун Мороґу."},sec={{t="Послуга для горян",b="Охорона високих перевалів і тунелів між Долиною Холодного Хребта та ширшими сніговими просторами Дун Мороґу — важка праця для горян Айронфорджа. Стоячи на прикордонній брамі, Горянин Талос пильнує і місцеві небезпеки, і мандрівників на втоптаній стежці. Коли на пост доходить звістка про самотнього шукача пригод, що прибув до Хараноса, Талос просить надійних перехожих віднести потрібні припаси далі, щоб підтримати новачків, які вирушають у замерзлі скелі."},{t="Припаси для Хараноса",b="Дорога, що спускається з південного перевалу, в'ється до селища Харанос — головного осередку дворфійського ремесла й подорожей у центральному Дун Мороґу. Ерік Брайтгаммер нещодавно облаштувався одразу на околиці селища. Доставивши йому пакунок провізії від горян, мандрівники допомагають налагодити важливий зв'язок між вартовими на далеких гребенях і тими, хто мандрує нетрями."}},faq={{q="Хто дає завдання «Шукач пригод»?",a="Це завдання дає Горянин Талос. Він стоїть на варті біля брами гірського перевалу, що з'єднує стежку з Долини Холодного Хребта з рештою Дун Мороґу.",al={"видавець","хто дає шукача пригод","завдання талоса"}},{q="Хто такий Ерік Брайтгаммер?",a="Ерік Брайтгаммер — шукач пригод, що нещодавно прибув під дворфійське містечко Харанос. Горянин Талос посилає мандрівників віднести йому необхідний згорток припасів.",al={"де ерік брайтгаммер","хто шукач пригод","брайтгаммер"}},{q="Куди треба доставити припаси?",a="Доставка — під самим Хараносом у Дун Мороґу, на північ від тунелю Перевалу Холодного Кряжа, де стоїть Горянин Талос.",al={"куди доставити припаси","місце еріка брайтгаммера","куди нести згорток"}},{q="Чому Горянин Талос посилає припаси?",a="Горяни стежать за мандрівниками по всьому Дун Мороґу. Коли Талос дізнається, що біля Хараноса отаборився шукач пригод, він організовує, щоб йому віднесли харчі й підтримали на морозі.",al={"чому талос посилає припаси","мета талоса","причина згортка"}},{q="Що ви несете?",a="Ви несете Згорток Припасів, який Горянин Талос особисто передав для Еріка Брайтгаммера.",al={"які припаси","предмет згортка"}},{q="Чи доступне це завдання гравцям Орди?",a="Ні. Горянин Талос — дворфійський вартовий Альянсу в Дун Мороґу, тож це завдання лише для Альянсу.",al={"чи орда може це","чи це лише для альянсу","шукач пригод орда"}}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96630"] = {n="Шукач пригод",s="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах. Простий записник оповідає про скромні мандри й ночівлі під відкритим небом невідомого мандрівника; його належить доставити Ліріні Даскблейд поблизу Доланаара.",h="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах.",kw={"шукач пригод","щоденник","ліріна даскблейд","доланаар","тельдрассил"},ang={["faction:Alliance"]="Для новачків Альянсу, що лише освоюються під Світовим Деревом, повернення загублених речей місцевим розвідникам допомагає підтримувати лад у гаях.",["race:NightElf"]="Юні нічні ельфи, що патрулюють Тельдрассил, часто знаходять сліди мандрівників і передають загублені особисті речі вартовим, як-от Ліріні Даскблейд."},sec={{t="Щоденник мандрівника",b="Серед густого гілля й сплетеного коріння Тельдрассила мандрівники часом натрапляють на покинуті особисті речі. Цей простий щоденник оповідає про непримітні, але щирі блукання безіменного шукача пригод. Замість великих подвигів чи небезпечних полювань на чудовиськ більшість його сторінок захоплено описує прості радощі ночівлі під сутінковою кроною."},{t="Доставка до Доланаара",b="Замість лишити особисту пам'ятку мокнути у вологих хащах, той, хто її знайшов, відчуває потяг віднести її до Доланаара. Ліріна Даскблейд, що стоїть на посту біля поселення нічних ельфів, приймає загублені сторінки — можливо, щоб дати завершення цій історії або з'ясувати, чиї мандри лишилися позаду."}},faq={{q="Що за щоденник згадано в завданні?",a="Це простий особистий записник, знайдений у нетрях Тельдрассила. Його записи розповідають про тихе життя й мандри незнайомої людини — про звичайні пригоди й незмінну любов до ночівлі просто неба.",al={"загублений щоденник","що за книга","щоденник шукача пригод"}},{q="Хто така Лайріна Даскблейд?",a="Лайріна Даскблейд — нічна ельфійка, що перебуває біля Доланаара. Саме їй має дістатися загублений щоденник, знайдений у лісі.",al={"лайріна","де лайріна даскблейд","кому здати"}},{q="Де відбувається це завдання?",a="Завдання відбувається на Тельдрассилі — великій гілці нічних ельфів, у нетрях довкола села Доланаар.",al={"де шукач пригод","зона завдання"}},{q="Чи описує щоденник небезпечних чудовиськ або битви?",a="Ні. Написаний він доволі просто й розповідає про скромне життя й мандри невідомої особи, особливо наголошуючи, як приємно ночувати в таборі.",al={"переказ про щоденник","що в щоденнику","що в ньому написано"}},{q="Хто може виконати це доручення?",a="Це доручення лише для членів Альянсу, що мандрують початковими землями Тельдрассила, — передусім для молодих нічних ельфів поблизу Доланаара.",al={"чи орда може це","завдання альянсу"}},{q="Чому щоденник треба віднести до Доланаара?",a="Доланаар — головне місце зустрічей і перехрестя цієї частини Тельдрассила, тож саме сюди найрозумніше приносити загублені особисті речі; до того ж неподалік на щоденник чекає Лайріна Даскблейд.",al={"чому доланаар","чому лайріна"}}},fp="14,259,20.373.0,20.307.0,43.220.0,25.128.0,33.135.0,56.177.0,27.153.0,36.218.0"}
P.entries["quest:96638"] = {n="Шукач пригод",s="«Шукач пригод» — вступне мандрівне завдання на Острові Зефрас. Його дає Етін Вітрів у Тендальському Гаю: мандрівників, що вже набралися досвіду, вона скеровує на південний захід, до Села Шен'дар, — зустрітися з Рааном Вайлдвіндом, бувалим мандрівником, що знає глушину.",h="«Шукач пригод» — вступне мандрівне завдання на Острові Зефрас.",kw={"шукач пригод","раан вайлдвінд","етін вітрів","село шен'дар","тендальський гай","острів зефрас"},ang={["race:Skyborne"]="Для юних Небороджених, що виходять із-під захищеного пологу Тендальського Гаю, зустріч із Рааном Вайлдвіндом — перший справжній крок у ширші, неприборкані простори рідного острова."},sec={{t="Прощання з гаєм",b="Тендальський Гай дає прихисток і тиху відраду, але ширші простори Острова Зефрас лишаються дикими й небезпечними. Етін Вітрів наглядає за посвячуваними й бачить, коли майбутній мандрівник готовий переступити знайомі межі. Тим, хто шукає слави, статків чи мети, вже замало лишатися за захищеними межами гаю."},{t="Провідник у дорозі",b="На південний захід від гаю, при дорозі до Села Шен'дар, уже отаборився інший мандрівник. Раан Вайлдвінд чимало часу провів, долаючи небезпеки за межами безпечного прихистку. Розшукавши його, молоді мандрівники отримують практичне знайомство з виживанням за межами Тендальського Гаю й учаться в того, хто вже ходив відкритими стежками."}},faq={{q="Хто посилає вас до Раана Вайлдвінда?",a="Завдання дає Етін Вітрів у Тендальському Гаю. Коли ви проявите себе в навколишніх лісах, вона радить знайти когось, хто на власні очі бачив решту острова.",al={"хто дає шукача пригод","хто починає шукача пригод","завдання етін"}},{q="Де знайти Раана Вайлдвінда?",a="Раан Вайлдвінд отаборився на південний захід від Тендальського Гаю, просто біля головної дороги до Села Шен'дар.",al={"місце раана вайлдвінда","де раан","як знайти раана"}},{q="Навіщо це доручення?",a="Воно правує за дороговказ: виводить мандрівників із безпечного Тендальського Гаю й знайомить із наставниками та викликами глибше на Острові Зефрас.",al={"навіщо шукач пригод","мета шукача пригод","чого вчить раан"}},{q="Що треба виконати, перш ніж отримати це завдання?",a="Спершу треба виконати для Етін Вітрів завдання про Лиху матріархиню — лише тоді вона спрямує вас дорогою до Раана Вайлдвінда.",al={"передумова шукача пригод","вимоги до шукача пригод"}},{q="Чи безпечне Село Шен'дар для мандрівників?",a="Село Шен'дар лежить далі на південний захід, за табором Раана. Це помітне поселення острова, але на дорогах і в нетрях довкола молодим шукачам пригод слід бути обережними.",al={"чи шен'дар безпечне","що таке село шен'дар"}},{q="Хто такий Раан Вайлдвінд?",a="Раан Вайлдвінд — завзятий мандрівник, що вирушив за межі Тендальського Гаю й отаборився біля Села Шен'дар; він дає поради й доручення новачкам, що йдуть цією дорогою.",al={"переказ про раана","хто такий раан вайлдвінд"}}},fp="14,245,17.355.0,19.347.0,36.193.0,31.125.0,33.169.0,64.136.0,39.184.0,21.182.0"}
P.entries["quest:96652"] = {n="Шукач пригод",s="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі мандри незнайомої постаті. Його сторінки тепло оповідають про життя просто неба й ночівлі під зорями; щоденник чекає, щоб його віднесли Бракку біля Гострого Пагорба.",h="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі...",kw={"щоденник","бракк","гострий пагорб","мандрівник","табір","дуротар"},ang={["class:Hunter"]="Мисливці, що все життя живуть із дарів землі, легко зрозуміють теплі записи щоденника, що раз у раз повертаються до радощів ночівлі в дикій природі.",["faction:Horde"]="Посушливими стежками Дуротару ходить багато новобранців; повернення загублених речей і доповідь розвідникам біля Гострого Пагорба допомагають тримати лад на центральному рубежі."},sec={{t="Нотатки мандрівника",b="Дуротар — суворий край, де виживання зазвичай важливіше за неквапливі подорожі, тож знайти книгу мандрівного літописця — незвична річ. Скромний щоденник, що лежав без нагляду в червоній пилюці, містить роздуми й пригоди когось геть невідомого героям Орди. Замість кривавих битв чи великих походів його сторінки зупиняються на простих радощах: спати під відкритим небом і розбивати табір у дикій природі."},{t="Доставка Бракку",b="Хто б не писав ці записи, він лишив досить вражень — чи зв'язків, — щоб вони вказували на Бракка, орка біля поселення Гострий Пагорб. Віднести особисті речі загублених подорожніх тутешнім розвідникам і робітникам табору — часто єдиний спосіб, щоб розсіяні мандрівники колись знову з'єдналися зі своїм майном або принаймні щоб їх пам'ятали ті, хто пильнує запилені дороги."}},faq={{q="Що в загубленому щоденнику?",a="Книжка напрочуд звичайна: у ній щоденні записи про тихі пригоди маловідомого шукача пригод. Особливо часто він згадує прості радощі й утіху від того, щоб розбити табір у нетрях.",al={"що каже щоденник","вміст загубленого щоденника","текст щоденника"}},{q="Хто написав щоденник?",a="На знайдених сторінках автор не названий; щоденник описує життя й мандри когось, про кого ви ніколи не чули, доки не натрапили на книжку в нетрях.",al={"хто шукач пригод","автор загубленого щоденника","хто написав цю книгу"}},{q="Хто такий Бракк?",a="Бракк — орк, що перебуває біля Гострого Пагорба в центрі Дуротара; саме йому віддають загублений щоденник.",al={"бракк разор гілл","хто такий бракк","де бракк"}},{q="Де знаходять щоденник?",a="Простий щоденник лежить покинутий десь на просторах Дуротара й чекає, доки його підбере перехожий мандрівник з Орди.",al={"де знайти щоденник","місце загубленого щоденника","початок шукача пригод"}},{q="Чому Бракка цікавить цей щоденник?",a="Бракк стоїть під самим Гострим Пагорбом, на жвавих стежках Дуротара, тож до нього стікаються речі, донесення й мандрівні справи, що проходять серцем земель Орди.",al={"чому нести бракку","мета бракка","щоденник бракка"}},{q="Чи загрожує небезпека шукачеві пригод, що його написав?",a="На знайдених сторінках немає жодних ознак лиха — лише теплі спогади про ночівлі в таборі. Утім, той, хто лишив свій дорожній щоденник у червоному пилу Дуротара, або загубив його ненароком, або несподівано подався далі.",al={"чи автор живий","чи шукач пригод помер","стан загубленого шукача пригод"}}},fp="14,268,18.468.0,17.374.0,32.220.0,22.178.0,13.98.0,27.130.0,39.185.0,41.252.0"}
P.entries["quest:96656"] = {n="Шукач пригод",s="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за межами Похоронного Подзвону. Довівши надійність в ударах по Багряному Хрестовому Походу, ви вирушаєте дорогою до Брілла — розвідати, що за незнайомка крутиться біля поселення. Замість чергової шпигунки-фанатички завдання знайомить вас з Елеанор Шеклтон — незалежною мандрівницею, яка радо навчить практичних навичок виживання в дикій природі.",h="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за...",kw={"шукач пригод","елеанор шеклтон","аррен","мандрівниця","виживання","брілл"},ang={["faction:Horde"]="Поки Екзекутор Аррен стереже молоді кордони володінь Відступників, мирний діалог із мандрівними виживальниками дає новачкам Орди цінні практичні навички.",["race:Undead"]="Для свіжих Відступників, що виходять за межі Похоронного Подзвону, зустріч із нейтральними мандрівниками на кшталт Елеанор — ранній урок: не кожен живий смертний у Лордероні одразу здіймає зброю на повернутих мерців."},sec={{t="Підозріла варта",b="Екзекутор Аррен пильно стежить за Похоронним Подзвоном і підступами до нього. Поки Багряний Хрестовий Похід активно шпигує в краї та просочується на північ Лордерону, кожен новоприбулий, помічений біля Брілла, заслуговує негайної перевірки. Побачивши вашу відданість у знищенні загроз від хрестоносців уздовж кордону, Аррен доручає вам тихо розвідати про невідому постать і з'ясувати, чи не становить вона прихованої небезпеки для Відступників."},{t="Мандрівниця в лісі",b="Коли ви знаходите Елеанор Шеклтон на узбіччі дороги біля Брілла, її наміри виявляються дуже далекими і від фанатичних змов Хрестового Походу, і від некромантії Погибелі. Незалежна мандрівниця, що перепочиває перед наступною подорожжю в дику глушину, Елеанор не має жодної ворожості до повсталих мерців. Натомість вона впізнає іскру шукача пригод у тих, кого послали її перевірити, і пропонує поділитися практичними основами виживання у відкритій глушині й облаштування табору."}},faq={{q="Чому Екзекутор Аррен хоче, щоб перевірили Елеанор?",a="Похоронному Подзвону й Бріллу постійно загрожують лазутчики Багряного Хрестового Походу й ворожі шпигуни. Кожного незнайомця, що никає біля великої дороги, вважають підозрілим, доки не з'ясується, що він має добрі наміри.",al={"чому перевіряти елеанор","хто послав мене до елеанор","завдання аррена про елеанор"}},{q="Хто така Елеанор Шеклтон?",a="Елеанор Шеклтон — незалежна шукачка пригод, що отаборилася біля дороги поблизу Брілла. Вона не має жодного стосунку до Багряного Хрестового Походу й захоплена лише мандрами нетрями та тим, щоб ділитися з іншими мандрівниками секретами виживання.",al={"хто така елеанор","переказ про елеанор шеклтон","хто шукач пригод"}},{q="Чи пов'язана Елеанор з Багряним Хрестовим Походом?",a="Ні. Щойно ви прибудете до її табору, Елеанор одразу пояснює, що не має нічого спільного із фанатичними хрестоносцями, які загрожують Галявинам Тірісфалю.",al={"чи елеанор з багряного хрестового походу","елеанор ворог","чи елеанор шпигунка"}},{q="Куди веде це завдання?",a="Доповідь Елеанор відкриває завдання «Широкі простори», у якому вона починає вчити вас основ виживання в нетрях і облаштування табору.",al={"що після шукача пригод","наступне завдання після шукача пригод","продовження елеанор шеклтон"}},{q="Де знайти Елеанор Шеклтон?",a="Вона отаборилася трохи осторонь головної дороги, що веде на схід до містечка Брілл на Галявинах Тірісфалю.",al={"місце елеанор","де елеанор шеклтон","табір елеанор у тірисфалі"}},{q="Чому Екзекутор Аррен обрав для цього доручення саме вас?",a="Ви здобули довіру Аррена, успішно викорінюючи агентів і гінців Багряного Хрестового Походу біля Похоронного Подзвону, і довели, що вам можна доручити делікатну розвідку.",al={"чому саме я","довіра аррена","чому аррен посилає мене"}}},fp="14,455,18.461.0,23.448.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Табірна наука 101: кулінарія",s="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати вогонь і готувати їжу в дикій природі. Цей урок, доступний у початкових поселеннях і Альянсу, і Орди, знайомить із багаттям як головною опорою будь-якого похідного табору просто неба.",h="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати...",kw={"табірна наука","кулінарія","багаття","табір","виживання","вогонь"},ang={["faction:Alliance"]="Новачків, що покидають Нортшир, Дун Мороґ чи Тельдрассил, ведуть до таких містечок, як Ґолдшир, Харанос і Доланаар, — учитися самостійності, перш ніж іти в нетрі.",["faction:Horde"]="Виживання для Орди — друга натура, і молодих бійців у Дуротарі, Малгорі та Тірісфалі одразу спрямовують до багать у Гострому Пагорбі, Селі Бладгуф і Бріллі.",["profession:Cooking"]="Кулінарія — буквально іскра табірного життя: вона дає і життєво важливу їжу для відновлення сил, і центральне багаття, без якого не розбити стоянку просто неба."},sec={{t="Вогнище глушини",b="To survive outside fortified walls, every traveler must know how to build a fire. Beyond boiling water and roasting meat, a basic campfire serves as the vital foundation for pitching a camp in uncharted terrain. A basic campfire anchors the campsite this lesson introduces."},{t="Від жарин до таборів",b="Кухарі-підмайстри здатні підтримувати лише скромний вогонь із мінімальним облаштуванням, а опанування кулінарного мистецтва дає змогу розпалювати більші вогнища, здатні підтримувати складніші табори. Ба більше, шукачі пригод, що беруться й за інші практичні ремесла, відкривають способи виготовляти корисні речі, які доповнюють їхні стоянки."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує нових шукачів пригод до місцевого наставника з кулінарії в найближчому поселенні, щоб вони опанували основи куховарства й навчилися розпалювати вогнище — осердя табору просто неба.",al={"навіщо табірна наука 101","мета табірної кулінарії","що робить це завдання"}},{q="Хто дає це завдання мандрівникам?",a="Цю науку в обох фракціях дають різні досвідчені провідники й шукачі пригод, серед них Елеанор Шеклтон, Ерік Брайтгаммер, Лайріна Даскблейд, Сем Сарсапарілла, Бракк, Каґа Вайлдгуф і Раан Вайлдвінд.",al={"хто дає табірну науку 101","видавець табірного завдання"}},{q="Куди здають завдання гравці Альянсу?",a="Шукачі пригод з Альянсу звертаються до таких наставників, як Томас у Ґолдширі, Ґремлок Пілснор у Хараносі чи Заррін у Доланаарі, — залежно від рідного краю.",al={"де здати за альянс","наставник кулінарії альянсу"}},{q="Куди здають завдання гравці Орди?",a="Шукачі пригод з Орди можуть пройти навчання в одного з наставників: Кухар Торка на Гострому Пагорбі, Вільям Пікман у Бріллі або Пайалл Сайлентстрайд у Селі Бладгуф.",al={"наставник кулінарії орди","де здати за орду"}},{q="Чи можна згодом збільшити табір?",a="Yes. As you increase your cooking skill, you can learn to light larger fires that can support more camp furnishings in the wilderness.",al={"більше багаття","покращити табір"}},{q="Чи можуть інші професії стати в пригоді в таборі?",a="Так. Вогнище — осердя табору — дає кулінарія, але й інші наставники ремесел навчать вас виготовляти корисне облаштування для табору, якщо ви опанували їхнє ремесло.",al={"табірні професії","обладнання табору"}}},fp="20,286,28.273.0,26.338.0,34.189.0,35.222.0,39.155.0,36.144.0,36.134.0,44.181.0"}
P.entries["quest:96659"] = {n="Шукач пригод",s="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд просить їх про останню послугу. Він довіряє їм клунок необхідних припасів для Каґи Вайлдгуф — досвідченої мандрівниці, що отаборилася біля Села Бладгуф і колись допомогла вождеві в його минулому.",h="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд...",kw={"шукач пригод","каґа вайлдгуф","вождь гоквінд","припаси","плато червоної хмари","село бладгуф","малгор"},ang={["faction:Horde"]="Вождь Гоквінд дбає, щоб мандрівні союзники Орди, покидаючи стартове плато, рано зав'язували стосунки з досвідченими мандрівниками й заставами Малгору.",["race:Tauren"]="Для молодих тауренів, що вперше виходять за межі Табору Нарачі, віддати борг честі Гоквінда Казі Вайлдгуф — перше служіння родичам на широких рівнинах Малгору."},sec={{t="Борг вождя",b="Перш ніж мандрівники зійдуть стежкою з плато на широкі рівнини Малгору, Вождь Гоквінд зупиняється, щоб залагодити незакриті особисті борги. Задовго до того, як він узявся вести нові покоління мисливців і шаманів у Таборі Нарачі, Гоквінд перетнувся з Каґою Вайлдгуф. Вождь каже про неї як про досвідчену шукачку пригод: Вайлдгуф надала вкрай потрібну допомогу, коли він найбільше її потребував. Почувши, що вона розбила табір одразу за Селом Бладгуф, Гоквінд користається відходом щойно випробуваних новачків, щоб послати харчі своїй давній добродійниці."},{t="Прощання з плато",b="Це доручення — ключовий обряд посвяти для молодих звитяжців Орди, що покидають Плато Червоної Хмари. Стежка вниз із плато веде просто до Села Бладгуф — культурного й господарського серця центрального Малгору. Несучи клунок із припасами через рівнини, ви з'єднуєте затишне навчальне життя плато з ширшою, дикішою боротьбою Об'єднаних Племен Тауренів."}},faq={{q="Хто така Каґа Вайлдгуф?",a="Каґа Вайлдгуф — бувала шукачка пригод із тауренів, що нещодавно отаборилася під самим Селом Бладгуф. Її пов'язує давня дружба з Вождем Гоквіндом: колись вона дуже йому допомогла.",al={"каґа вайлдгуф","хто такий вайлдгуф","де каґа"}},{q="Чому Вождь Гоквінд посилає ці припаси?",a="Гоквінд вважає, що молоді звитяжці, які вирушають до Села Бладгуф, — чудова нагода віддячити Вайлдгуф за давню послугу й подбати, щоб його подруга-мандрівниця мала свіжі припаси в дорогу.",al={"борг гоквінда","чому надсилати припаси","призначення згортка припасів"}},{q="Де табір Каґи Вайлдгуф?",a="Її табір — на рівнині під самим Селом Бладгуф, унизу звивистої південної стежки, що веде з Плато Червоної Хмари в центр Малгору.",al={"місце табору каґи","знайти каґу","табір села бладгуф"}},{q="Коли стає доступним це завдання?",a="Вождь Гоквінд дає це доручення, щойно мандрівник доведе свою звитягу на Плато Червоної Хмари й буде готовий вирушити на ширші простори Малгору.",al={"коли я отримаю шукача пригод","час завдання гоквінда","завдання виходу з плато"}},{q="Чи виводить це завдання з Табору Нарачі?",a="Так. Доставка припасів прямо спонукає покинути Табір Нарачі й вирушити стежкою до Села Бладгуф.",al={"вихід із плато червоної хмари","подорож до бладгуфа"}},{q="Що в Згортку Припасів?",a="У згортку — найнеобхідніші харчі, зібрані племенами Табору Нарачі, щоб шукач пригод міг вижити поза облаштованими поселеннями.",al={"що за припаси","вміст згортка припасів"}}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:967"] = {n="Вежа Альталакса",s="Це завдання пов'язує розслідування діяльності культу Темного Берега на півночі Темного Узбережжя з ширшою обороною півночі Калімдору. Балтул Шедовстрайк посилає кур'єра Альянсу на південь, до Посту Маестри в Ашенвалі, щоб попередити свого наставника Делґрена Очищувача про зловісне зібрання культу у Вежі Альталакса.",h="Це завдання пов'язує розслідування діяльності культу Темного Берега на півночі Темного Узбережжя з ширшою...",kw={"вежа альталакса","балтул шедовстрайк","делґрен очищувач","пост маестри","культ темного берега","паладин"},ang={["class:Paladin"]="Зустріч із Делґреном дає паладинам надихаючий приклад їхнього святого покликання в незнайомих землях: хрестоносець-людина, що орудує Світлом, здобуває глибоку довіру потайних нічних ельфів Калімдору.",["faction:Alliance"]="Співпраця Балтула на Темному Узбережжі й Делґрена в Ашенвалі показує, які важливі лінії зв'язку пов'язують розкидані гарнізони Альянсу на півночі Калімдору.",["race:NightElf"]="Для нічних ельфів ця місія свідчить про дедалі міцніше практичне партнерство між їхніми Вартовими й східними народами, що прийшли допомогти вичистити демонічні рештки з їхніх лісів."},sec={{t="Благання про підкріплення",b="Після перших сутичок із культистами Темного Берега довкола Вежі Альталакса розвідник із нічних ельфів Балтул Шедовстрайк розуміє, що загроза перевершує його самотню варту. Щоб дати рішучу відсіч, він пише докладне донесення й довіряє його посланцеві Альянсу для свого наставника — Делґрена Очищувача. Заклиначі культу сміливішають щогодини, тож звістка має дійти до досвідченого проводу, здатного очолити їх викорінення."},{t="Дорога до Ашенвалю",b="Щоб доставити донесення Балтула, доведеться пройти все Темне Узбережжя — довгим прибережним трактом на південь, з імли, через лісистий кордон до Ашенвалю. Делґрен Очищувач, що стоїть на Посту Маестри біля західної дороги, присвятив себе вичищенню демонів і нежиті, що досі блукають лісом. Хоч паладин-людина спершу не знав звичаїв нічних ельфів, він здобув глибоку взаємну повагу Вартових як незамінний союзник."},{t="Пробудження святого воїна",b="Делґрен отримує нагальний лист Балтула з похмурою рішучістю. Як воїн, відданий Святому Світлу, він вважає присутність темних культистів, порчі душ і демонічних потвор у цих давніх лісах нестерпною пошестю. Прочитавши, як міцно Темний Берег закріпився у зруйнованій вежі Високородних, Делґрен негайно готується очолити операцію й завдати удару у відповідь."}},faq={{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — паладин із людей, що перебуває на Посту Маестри в Ашенвалі. Відданий Святому Світлу, він ділиться своєю бойовою й духовною майстерністю з Вартовими нічних ельфів, щоб очищати їхні прадавні ліси від демонів і нежиті.",al={"делґрен очищувач","хто такий делґрен","переказ про делґрена"}},{q="Чому Балтул Шедовстрайк посилає гінця до Ашенвалю?",a="Балтул — розвідник біля Вежі Альталакса, що вивчає культ Темного Берега. Розуміючи, що темних обрядів культу й самих культистів стрімко більшає, він надсилає свої відомості наставникові Делґрену, щоб той організував удар.",al={"чому балтул надсилає листа до ашенвалю","причина листа балтула"}},{q="Що пов'язує Балтула й Делґрена?",a="Делґрен — наставник Балтула. Паладин із людей навчив нічного ельфа бойового мистецтва й познайомив його з ученням Святого Світла, і між ними, попри культурні відмінності, склалися незвично тісні узи.",al={"балтул і делґрен","як балтул і делґрен знайомі"}},{q="Де Пост Маестри?",a="Пост Маестри — застава Альянсу на заході Ашенвалю, біля головної дороги, що веде на південь із Темного Узбережжя. Це перший вартовий пункт для мандрівників між Темним Узбережжям і глибинами лісу.",al={"місце поста маестри","де пост маестри"}},{q="Що культ Темного Берега робить біля Вежі Альталакса?",a="Темний Берег — культ, що діє з руїн Вежі Альталакса, колишньої оселі Високородних на півночі Темного Узбережжя. Культисти практикують темні мистецтва, знаються з демонічними силами й загрожують наслати скверну на все узбережжя.",al={"культ темного берега альталакс","культисти вежі альталакса"}},{q="Як Делґрен ставиться до союзу з нічними ельфами?",a="Делґрен визнав, що, тільки прибувши до Калімдору, ніяк не міг звикнути до звичаїв і способу життя нічних ельфів. Але з часом, стоячи пліч-о-пліч із ними проти спільного зла, він пройнявся глибокою повагою до Вартових.",al={"делґрен і нічні ельфи","людський паладин і нічні ельфи"}}},fp="22,322,25.469.0,21.486.0,23.383.1,28.252.0,62.264.0,54.217.0,24.221.0,61.223.0,56.246.0"}
P.entries["quest:968"] = {n="Сили з глибин",s="Це завдання Альянсу дає Тундріс Віндвівер в Обердайні. Мандрівників посилають на південь, у розбиті руїни Амет'Арана, щоб вирвати магічні реліквії з рук неспокійних примар Високородних. Мета проста: повернути ці давні артефакти, доки їхнє приспане чаклунство не наробило Калімдору ще більше лиха.",h="Це завдання Альянсу дає Тундріс Віндвівер в Обердайні.",kw={"реліквія високородних","тундріс віндвівер","амет'аран","привиди","високородні","темне узбережжя"},ang={["class:Druid"]="Очищаючи Амет'Аран від зіпсованих тайних решток, ви допомагаєте загоїти духовні рани, що порушують природний спокій нетрів Темного Узбережжя.",["class:Mage"]="Суспільство калдореїв зі страху прагне розбити ці артефакти, але вчені тайних мистецтв бачать у них рідкісні, бездоганні зразки ремесла Високородних доби до Розколу.",["faction:Alliance"]="Допомагаючи нічним ельфам убезпечити їхні примарні землі, ви зміцнюєте присутність і згуртованість Альянсу в давніх лісах півночі Калімдору.",["race:NightElf"]="Для калдореїв зустріч із привидами Амет'Арана — сумне нагадування про пиху предків і катастрофічний розкол їхньої давньої імперії."},sec={{t="Відлуння в руїнах",b="На південь від Обердайна, на схід від прибережного тракту, лежать зарослі кам'яні фундаменти Амет'Арана. Десять тисяч років тому це поселення було оплотом Високородних — привілейованої знаті давньої імперії нічних ельфів. Коли їхні неприборкані тайні забави завершилися Розколом світу, Амет'Аран розлетівся на друзки. Та його мешканці так і не пішли по-справжньому. Вартові, що патрулюють Темне Узбережжя, доповідають: привиди цих аристократів досі блукають запалими площами, стискаючи зачаровані знаряддя й дрібнички, якими володіли за життя."},{t="Очистити тайне минуле",b="Для сучасного суспільства калдореїв тайна магія — не просто заборонене знання, а екзистенційна небезпека, що мало не знищила життя в Азероті. Тундріс Віндвівер розуміє: лишити ці знаряддя Високородних у примарних руках — означає лишити порчі відчинені двері. Посилаючи шукачів пригод вирвати реліквії в неспокійних духів, Тундріс хоче остаточно їх знищити, щоб приспане зіпсоване чаклунство більше ніколи не живило нового лиха."}},faq={{q="Де знайти реліквії Високородних?",a="Реліквії — у руїнах Амет'Арана, на південь від Обердайна, на схід від головної дороги Темним Узбережжям. Ці давні знаряддя носять духи, що блукають зруйнованими кам'яними дворами.",al={"де реліквії","місце амет'арана","де знайти реліквії"}},{q="Хто такий Тундріс Віндвівер?",a="Тундріс Віндвівер — учений і старійшина нічних ельфів у портовому Обердайні. Тісно співпрацюючи з місцевими Вартовими, він організовує захист Темного Узбережжя від залишків магічної скверни й давніх прокльонів, що лишилися по Розколу.",al={"тундріс віндвівер","хто дає знаряддя високородних"}},{q="Чому Тундріс хоче знищити ці реліквії?",a="Суспільство нічних ельфів суворо відкидає тайну магію через нищівний Великий Розкол, спричинений безрозсудним чародійством Високородних. Тундріс боїться, що тайна сила, яка досі жевріє в цих предметах, може пробудити приспане зло, якщо її не стримати.",al={"чому знищити реліквії","мета знарядь високородних"}},{q="Які духи блукають в Амет'Арані?",a="Це примарні рештки знаті Високородних, що загинула у Війні Прадавніх. Навіть по смерті вони чіпляються за колишню гордість, владу й магічні артефакти, знову й знову переживаючи своє зблякле життя серед зруйнованого каміння.",al={"привиди амет'арана","що за духи"}},{q="Чому Високородні досі прикуті до руїн?",a="Раптова, катастрофічна руїна під час Розколу прокотилася імперією з такою магічною люттю, що безліч душ лишилися в пастці — прикуті потрясінням і тайним відлунням до руїн своїх колишніх домівок.",al={"чому вони привиди","прокляття високородних"}},{q="Що стається з реліквіями, коли ви їх здаєте?",a="Тундріс Віндвівер забирає зібрані реліквії, маючи твердий намір розібрати й знищити їх назавжди, щоб їхню приспану тайну скверну ніколи більше не можна було ні використати, ні вивільнити.",al={"що тундріс робить із реліквіями","доля реліквій"}}},fp="22,360,19.561.0,23.480.0,37.224.0,27.257.0,46.238.0,38.236.0,47.216.0,50.202.0"}
P.entries["quest:97"] = {n="Легенда про Сталвана",s="Цей етап розслідування нарешті підтверджує зловісну правду, що пов'язує невловимого вчителя із записами Даркшира. Писар Долтрі встановлює, що почерк на знайдених документах належить Сталванові Містмантлу, і про це негайно доповідають Командирові Алтеї Ебонлок. Саме тоді підозри Нічної Варти тверднуть у незаперечний факт.",h="Цей етап розслідування нарешті підтверджує зловісну правду, що пов'язує невловимого вчителя із записами...",kw={"легенда про сталвана","писар долтрі","алтея ебонлок","сталван містмантл","нічна варта","даркшир"},ang={["faction:Alliance"]="Для слідчих Альянсу розплутування сліду Сталвана показує, наскільки важлива співпраця між знесиленим проводом Даркшира й мандрівними шукачами пригод, щоб уберегти південні землі королівства.",["race:Human"]="Люди бачать тут відображення трагічного занепаду власного суспільства: і шановані вчителі, і сільські містечка тихо зісковзують від цивілізації в божевілля й самотність."},sec={{t="Збіг у записах",b="Після пошуків у далеких маєтках, корчмах і міських архівах людських королівств розпорошений слід повертається до ратуші Даркшира. Писар Долтрі оглядає знайдені зразки почерку й порівнює їх із місцевими реєстрами. Висновок однозначний: почерк належить Сталванові Містмантлу. Будь-які сумніви в тому, чи справді вчитель бував у Сутінколіссі, розвіюються, і Нічна Варта отримує вагомий доказ, щоб узятися до справи як до нагальної місцевої загрози."},{t="Підозри Нічної Варти",b="Командир Алтея Ебонлок від самого початку розслідування мала похмурі передчуття щодо Сталвана. Сутінколісся й так прогинається під тягарем диких воргенів, кістяної нежиті й причаєних некромантів; невідомий убивця, що ховається в тінях лісу, — небезпека, яку вона не може ігнорувати. Підтвердження від Долтрі справджує її найчорніші побоювання, і Нічна Варта береться розшукати й знешкодити відлюдника раз і назавжди."}},faq={{q="Що з'ясував Писар Долтрі?",a="Писар Долтрі порівняв записи, зібрані вами в мандрах, з офіційними документами й підтвердив, що почерк точно збігається з почерком Сталвана Містмантла. Це довело, що підозрюваний — той самий учитель, який колись жив у містечку.",al={"що з'ясував долтрі","збіг почерку долтрі","доказ почерку сталвана"}},{q="Чому Командир Алтея Ебонлок так переймається Сталваном?",a="Командир Алтея Ебонлок очолює Нічну Варту — знесилену ополченську варту Даркширу. У краї, де й так повно жахіть, вона не може дозволити, щоб жорстока темна постать із лихим минулим вільно й безкарно розгулювала в межах Сутінколісся.",al={"чому алтея дбає","розслідування ебонлок","нічна варта сталван"}},{q="Де відбувається цей етап?",a="Увесь цей етап відбувається в містечку Даркшир. Писар Долтрі — у ратуші, а Командир Алтея Ебонлок патрулює неподалік, на центральних вулицях містечка.",al={"де цей етап","місце завдання","здача сталвана в даркширі"}},{q="Що буде після доповіді про збіг почерку?",a="Щойно Командир Ебонлок отримає підтвердження від Писаря Долтрі, розслідування переходить до активних пошуків Сталвана в моторошних нетрях Сутінколісся.",al={"що після збігу почерку","після долтрі","наступний крок ланцюжка сталвана"}},{q="Ким спершу був Сталван Містмантл?",a="Сталван Містмантл був шкільним учителем і домашнім наставником, родом із Сутінколісся. Подавшись шукати роботу на чужині, він пережив темний і трагічний злам, що зрештою повернув його в рідні ліси небезпечним відлюдником.",al={"ким був сталван","минуле сталвана","історія сталвана містмантла"}},{q="Навіщо знадобилося порівнювати почерк?",a="Події й звинувачення, пов'язані зі Сталваном, відбувалися в різних краях, зокрема в Мунбруку й Ґолдширі, тож офіційні записи були розрізнені. А в міських книгах Даркширу зберігалися перевірені місцеві зразки, що могли остаточно пов'язати чужі сліди саме з цією людиною.",al={"навіщо порівнювати почерк","чому долтрі перевіряв почерк","доказ особи сталвана"}}},fp="21,363,22.508.0,28.456.1,31.246.0,63.241.0,32.202.0,51.186.0,38.225.0,39.282.0"}
P.entries["quest:970"] = {n="Вежа Альталакса",s="Це завдання — переломний момент у розслідуванні зловісного Культу Темного Берега: переслідування переходить від зруйнованої Вежі Альталакса на Темному Узбережжі через кордон до Посту Маестри в Ашенвалі. Делґрен Очищувач посилає шукачів пригод у сусідні табори культистів, щоб здобути могутній Сяйливий Самоцвіт Душі. Розгадавши цей артефакт, можна побачити похмуре чаклунство, що живить вплив культу на північні ліси.",h="Це завдання — переломний момент у розслідуванні зловісного Культу Темного Берега: переслідування переходить...",kw={"вежа альталакса","культ темного берега","делґрен очищувач","самоцвіт душі","сарґат","ордил'аран"},ang={["class:Paladin"]="Очищати темні вмістища душ і рубати спотворених культистів — саме те, до чого покликаний паладин, що викорінює нечестиву порчу зі світу.",["class:Priest"]="Дослідження темного вмістища душі перегукується з покликанням жерця — протистояти порчі й нести розраду змученим душам.",["faction:Alliance"]="Злагоджені дії застав на Темному Узбережжі й в Ашенвалі убезпечують північний рубіж від темних чаклунів, що загрожують мандрівникам Альянсу.",["race:NightElf"]="Мерзенні культисти, що оскверняють давні руїни на кшталт Ордил'Арана й нівечать північні ліси, роблять знищення Культу Темного Берега нагальною справою для кожного нічного ельфа."},sec={{t="Благання через кордон",b="Після того як довкола Вежі Альталакса на півночі Темного Узбережжя виявили зловісну діяльність, донесення повели просто на південь, до Ашенвалю, — до Делґрена Очищувача. Перебуваючи на Посту Маестри, Делґрен давно протистоїть Культові Темного Берега, що вдирається в давні ельфійські ліси. Розуміючи, що загроза культу охоплює обидва краї, Делґрен вирішує вдарити в саме серце їхнього мерзенного чаклунства."},{t="Таємниці Ордил'Арана",b="На північний схід від Посту Маестри лежать Руїни Ордил'Аран, які тепер заполонили фанатичні культисти Темного Берега. Делґрен з'ясовує, що їхні посланці носять сяйливі самоцвіти душі — темні вмістища, зачаровані зловісною магією, що підтримує силу культу. Вистеживши культистів серед руїн і здобувши один із цих самоцвітів, Делґрен хоче зламати їхні чари й викрити справжнє джерело їхнього лиховісного обряду."},{t="Ув'язнений дух",b="Розгадавши мерзенні чари, вплетені в сяйливий самоцвіт душі, Делґрен знаходить не лише темні заклинання — він розплутує вмістище муки. Зламавши захист самоцвіту, він вивільняє дух Сарґата — одного з ельфів Амет'Арана, якого Атрікус Нарассін під час Розколу ув'язнив у самоцвіті душі й відтоді повільно висмоктує. Примара називає ім'я помічника Атрікуса — Ілкруда Маґтрулла, чий фоліант може розкрити, де зберігаються решта самоцвітів душі."}},faq={{q="Де знайти Сяйливий Самоцвіт Душі?",a="Сяйливий Самоцвіт Душі — у членів Культу Темного Берега, що засіли на північний схід від Посту Маестри, у Руїнах Ордил'Аран в Ашенвалі. Його носять різні культисти, що чаяться в руїнах, хоча, щоб його здобути, доведеться трохи потрудитися.",al={"де сяйливий самоцвіт душі","звідки випадає самоцвіт душі","самоцвіт душі темного берега"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри на півночі Ашенвалю. Він завзято бореться з лихими силами, що вдерлися в ліс, і передусім вистежує й нищить Культ Темного Берега.",al={"делґрен","хто такий делґрен"}},{q="Що таке Культ Темного Берега?",a="Культ Темного Берега — лиха секта, що діє з Вежі Альталакса на Темному Узбережжі й давніх ельфійських руїн на кшталт Ордил'Арана в Ашенвалі. Її члени практикують темне чаклунство, ув'язнення душ і некромантичні обряди.",al={"культ темного берега","хто темний берег"}},{q="Чому завдання з Темного Узбережжя посилає мене в Ашенваль?",a="Розслідування починається біля Вежі Альталакса на Темному Узбережжі, але мережа культу тягнеться на південь, за межу, в Ашенваль. А Делґрен Очищувач на Посту Маестри знає, як протидіяти чарам культу, що ув'язнюють душі.",al={"чому пост маестри","чому йти в ашенваль"}},{q="Що станеться, коли самоцвіт душі буде розгадано?",a="Делґрен збирається розгадати темні чари на Сяйливому Самоцвіті Душі. Що він знайде, з'ясується, коли ви принесете йому самоцвіт.",al={"що в самоцвіті душі","привид самоцвіту душі"}},{q="Де Ордил'Аран?",a="Ордил'Аран — давні ельфійські руїни трохи на північний схід від Посту Маестри на півночі Ашенвалю, що їх нині заполонив Культ Темного Берега.",al={"місце ордил'арана","де ордил'аран"}}},fp="22,428,24.417.0,25.426.0,16.471.1,37.251.0,28.239.0,36.222.0,49.245.0,45.132.1,28.151.0"}
P.entries["quest:97005"] = {n="Чол'арук Пожирач",s="Чол'арук Пожирач — страхітлива потворна гидота, що ховається в печері на Тернистому Пагорбі в Пустках. Місцеві Гостромани звуть її Чол'аруком, тобто «Пожирачем», а чутки кажуть, що ця істота така велика, що може проковтнути орка цілком. Бейнгем прагне здобути її відтяту голову, щоб помститися за товаришів, загиблих від подібних жахіть.",h="Чол'арук Пожирач — страхітлива потворна гидота, що ховається в печері на Тернистому Пагорбі в Пустках.",kw={"чол'арук пожирач","тернистий пагорб","бейнгем","гидота","гостромани","пустки"},ang={["class:Hunter"]="Зустрітися з легендарним верховним хижаком, про якого кажуть, що він ковтає воїнів у повних обладунках цілком, — найвище випробування вправності й нервів слідопита.",["class:Warrior"]="Прохання Бейнгема промовляє просто до кодексу воїна: помститися за полеглих товаришів, кинувши виклик височенному жахіттю в його підземному лігві.",["faction:Horde"]="Чудовиська, що безкарно никають високими плато, загрожують мандрівникам і караванам, які пробираються через Пустки, тож знищення звіра — питання безпеки всього краю."},sec={{t="Жах Тернистого Пагорба",b="На північний захід від того місця, де в Пустках чекає Бейнгем, лежить плато, відоме як Тернистий Пагорб, — за нього здавна змагаються місцеві племена Гостроманів. Останнім часом пошепки ширяться чутки про жахливу присутність, що засіла в одній із його печер: потворну гидоту, яку Гостромани звуть Чол'аруком, тобто «Пожирачем». Багато мандрівників вважають розповіді про звіра, здатного одним ковтком проковтнути орка в обладунках, байками біля вогнища, але ті, хто на власні очі бачив різанину, знають, що загроза цілком реальна."},{t="Сплачений рахунок",b="Для Бейнгема Чол'арук — аж ніяк не міф. Він уже стикався з подібними жахіттями, носить на собі шрами й оплакує товаришів, що загинули від таких звірів. Знаючи, яку небезпеку становить ненажерлива гидота для всіх, хто мандрує саваною, він доручає досвідченим звитяжцям піднятися на плато, прорватися в підземне лігво, убити Чол'арука й забрати його величезну голову."}},faq={{q="Що за істота Чол'арук?",a="Чол'арук — страхітлива потвора, що чаїться в печері на Тернистому Пагорбі. Кажуть, вона така велетенська, що може проковтнути дорослого орка цілком, тож місцеві Гостромани прозвали її моторошним ім'ям «Пожирач».",al={"що за істота чол'арук","тип чудовиська чол'арука","хто пожирач"}},{q="Де лігво Чол'арука?",a="Чол'арук влаштував лігво в печері на високому плато Тернистого Пагорба, на північному заході Пусток.",al={"де чол'арук","місце чол'арука","печера терновий пагорб"}},{q="Хто такий Бейнгем і чому він хоче смерті Чол'арука?",a="Бейнгем, якого можна зустріти в Пустках, уже має досвід боротьби з такими звірами. Колись він утратив соратників через подібних потвор, тож прагне смерті Чол'арука заради честі й помсти за полеглих товаришів.",al={"хто дає чол'арука","чому вбити чол'арука","переказ про бейнгема"}},{q="Що означає «Пожирач»?",a="Місцеві шипогриви Гостромани дали Чол'арукові це ім'я через його ненаситну, ненажерливу вдачу: за чутками, він без вагань ковтає дорослих воїнів цілком.",al={"значення пожирача","чому називають пожирачем","гостромани і чол'арук"}},{q="Шипогриви Гостромани шанують Чол'арука чи бояться його?",a="Поки що невідомо. Гостромани називають цю істоту Чол'аруком або «Пожирачем», але в завданні не сказано, чи вони бояться страхітливої потвори, що ховається в печері на Тернистому Пагорбі, чи поклоняються їй.",al={"чи вепролюди люблять чол'арука","гостромани та чол'арук"}},{q="Який доказ потрібен, щоб підтвердити смерть Чол'арука?",a="Бейнгем просить принести відрубану голову Чол'арука — незаперечний доказ того, що потвору знищено.",al={"здати чол'арука","що принести бейнгему"}}},fp="21,309,20.512.0,15.379.0,35.232.0,34.114.0,51.209.0,29.172.0,52.195.0,52.125.0"}
P.entries["quest:971"] = {n="Знання в глибинах",s="«Знання в глибинах» — завдання Альянсу, яке дає Ґерріґ Боунґріп у Покинутій Печері Айронфорджа. Він посилає шукачів пригод за море, до затоплених руїн Чорноглибинних Печер в Ашенвалі, по давній Рукопис Лорґаліса. Під личиною вченого Боунґріп приховує зловісні наміри, пов'язані з темними сутностями й пророцтвами про кінець світу.",h="«Знання в глибинах» — завдання Альянсу, яке дає Ґерріґ Боунґріп у Покинутій Печері Айронфорджа.",kw={"ґерріґ боунґріп","рукопис лорґаліса","айронфордж","покинута печера","чорноглибинні печери","ті, що сплять"},ang={["class:Warlock"]="Боунґріп діє пліч-о-пліч із чорнокнижниками, що ховаються в Покинутій Печері Айронфорджа, і поділяє їхній голод до заборонених текстів, які розхитують межі світів.",["faction:Alliance"]="Допомога вченому з Альянсу здається нешкідливою, але справжні мотиви Боунґріпа та його темні спільники натякають на лихі задуми просто в стінах Айронфорджа."},sec={{t="Учений у тінях",b="Сховавшись у сирих закутках Покинутої Печери Айронфорджа, Ґерріґ Боунґріп видає себе за відданого збирача давніх текстів. Та в його наукових пошуках виразно бринить щось лиховісне. Звичайна історія чи міські хроніки Боунґріпа не цікавлять: він відверто полює на забуті знання, здатні відчинити двері й пробудити «Тих, Що Сплять». Його балачки про те, як вижити після «останніх днів», видають у ньому або дивака, або небезпечного прихильника темних сил, що дрімають."},{t="Затонулі руїни Лорґаліса",b="Bonegrip directs seekers halfway across Azeroth to the shadowed shores of Ashenvale, where the ancient night elven sanctuary of Blackfathom Deeps lies drowned. Before the Great Sundering tore Kalimdor apart, night elven scholars gathered immense magical knowledge in their coastal temples. Amidst the flooded corridors, now crawling with naga, satyrs, and Twilight's Hammer cultists, rests the Lorgalis Manuscript—a text of forbidden lore kept in a Pitted Iron Chest."},{t="Брати й сестри",b="When presented with the watersoaked manuscript, Bonegrip makes no effort to file it in Ironforge's Hall of Explorers. Instead, he openly rejoices that duplicates will be produced and disseminated among his mysterious 'brothers and sisters.' While grateful to the Alliance adventurer who retrieved it, Bonegrip's loyalties clearly lie with a clandestine sect eager to utilize the recovered lore for esoteric, world-altering rites. Bonegrip is associated with the Twilight's Hammer, whose followers seek forbidden knowledge of the Old Gods."}},faq={{q="Хто дає завдання «Знання в глибинах»?",a="Завдання дає Ґерріґ Боунґріп — дворф-шукач давніх знань, що мешкає в тьмяній Покинутій Печері в дворфійському гірському місті Айронфордж.",al={"хто дає знання в глибинах","де взяти завдання","хто починає знання в глибинах"}},{q="Що таке Рукопис Лорґаліса?",a="The Lorgalis Manuscript is a text Gerrig Bonegrip wants recovered from Blackfathom Deeps. It is kept in a Pitted Iron Chest among the flooded ruins.",al={"що таке рукопис лорґаліса","переказ про лорґаліса","яку книгу знайти"}},{q="Де Рукопис Лорґаліса?",a="Рукопис лежить глибоко в підземеллі Чорноглибинні Печери на Зорамському Узмор'ї, на північно-західному узбережжі Ашенвалю в Калімдорі.",al={"місце рукопису лорґаліса","де книга в чорноглибинних печерах","місце книги в печерах"}},{q="Хто такі «Ті, що Сплять», про яких згадує Ґерріґ Боунґріп?",a="Bonegrip uses this cryptic name for the slumbering powers described in the forbidden lore he collects. The quest's protected sections explore his darker connections.",al={"ті, що сплять","про кого говорить боунґріп","чому поклоняється ґерріґ"}},{q="Хто ці «брати й сестри», з якими Ґерріґ хоче поділитися рукописом?",a="Bonegrip's associates share his interest in forbidden lore. Recovering the manuscript can reveal more about whom he serves.",al={"брати й сестри ґерріґа","на кого працює ґерріґ","фракція боунґріпа"}},{q="Чому завдання з Айронфорджа посилає гравців аж до Ашенвалю?",a="Покинута Печера в Айронфорджі приваблює магів без дозволу, чорнокнижників і розбійників, що шукають таємниць, прихованих від світла. Боунґріп збирає давні могутні знання, а Рукопис Лорґаліса, якого він прагне, за чутками, лежить на дні Чорноглибинних Печер в Ашенвалі — давній оселі давно загиблих ельфів, що володіли великими знаннями.",al={"чому йти в ашенваль","завдання з айронфорджа до печер","подорож до чорноглибинних печер"}}},fp="22,354,24.495.0,27.469.0,20.538.1,43.154.0,32.148.0,41.146.0,55.165.0,77.123.1,68.325.0"}
P.entries["quest:972"] = {n="Водяна Сапта",s="«Водяна Сапта» — перехідне доручення, яке дає молодим шаманам Орди Іслен Вотерсір на узбережжі Пусток. Отримавши обрядовий напій, шаман вирушає за Велике море, у сплюндровані землі Срібнолісся, щоб зустрітися з оскверненим джерелом.",h="«Водяна Сапта» — перехідне доручення, яке дає молодим шаманам Орди Іслен Вотерсір на узбережжі Пусток.",kw={"водяна сапта","сапта","іслен вотерсір","срібнолісся","тотем води","шаман"},ang={["class:Shaman"]="Водяна Сапта — важливий поворот у ваших стихійних випробуваннях: вона відкриває вам очі на світ духів, перш ніж ви здобудете владу над цілющим Тотемом Води.",["faction:Horde"]="Випробування показує міжконтинентальну єдність нової Орди: новачків посилають із вибілених сонцем рівнин Калімдору в примарні ліси Лордерону."},sec={{t="Видіння води",b="У стихійних традиціях шаманів Орди сапта — алхімічний напій, створений, щоб налаштувати чуття просто на духів світу. Звичайні очі бачать лише спокійні струмки чи стоячі ставки, а сапта пронизує завісу фізичного світу й відкриває стихійних істот, що живуть у течії."},{t="Дорога до Срібнолісся",b="Шаман, що довів свою відданість духам, отримує напій просто з рук Іслен Вотерсір — самітниці, що живе на пустельних берегах на південь від Раджета. Замість того щоб випробувати сапту в посушливих долинах Калімдору, Іслен велить новачкові вирушити далеко за Велике море, у похмурі, покинуті ліси Срібнолісся, щоб протистояти стихійній скверні, що отруює струмки Лордерону."}},faq={{q="Що таке водяна сапта?",a="Сапта — обрядовий еліксир, який готують шаманські наставники. Випита, вона загострює духовне чуття, і той, хто її скуштував, може бачити духів стихій, незримих для смертного ока, й говорити з ними.",al={"що таке водяна сапта","значення водяної сапти","що робить сапта"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — майстриня-шаманка, що живе в самотніх роздумах на східному узбережжі Пусток, на південь від Торгового Узбережжя. Вона веде молодих шаманів Орди тяжким шляхом єднання зі стихією води.",al={"переказ про іслен вотерсір","хто така іслен"}},{q="Чому шаман мусить вирушити до Срібнолісся?",a="Духи стихії води в Срібноліссі тяжко потерпають від скверни. Щоб завершити посвяту, шаман має перевезти сапту через море, на власні очі побачити зіпсоване джерело води й очистити його від скверни.",al={"чому срібнолісся","чому східні королівства"}},{q="Що станеться, коли випити сапту?",a="Випивши водяну сапту, шаман бачить зіпсованих водяних елементалів, що чаяться в отруєних озерцях Срібнолісся, і може зустрітися з джерелом тління.",al={"випити сапту","дія сапти"}},{q="Чи обов'язкове це випробування для всіх шаманів Орди?",a="Так. Шамани-орки, таурени й тролі однаково мусять відгукнутися на «Поклик води» й отримати цю сапту як неодмінний обряд посвяти, перш ніж здобути свій Тотем Води.",al={"хто бере це завдання","чи це класове завдання"}},{q="Де в Срібноліссі зіпсоване озерце?",a="Зіпсоване джерело — на узбережжі Срібнолісся, на захід від Гробниці.",al={"місце озерця срібнолісся","де водяне озерце"}}},fp="11,256,17.335.0,22.426.0,22.231.0,23.239.0,48.240.0,38.177.0,44.162.0,50.86.0"}
P.entries["quest:97279"] = {n="Заблукала зброя",s="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек. Молоді воїни прибувають юрбами, щоб служити Орді, і зброї не вистачає. Щоб довести свою дисципліну й підтримати табір, новобранці обшукують чагарі, збираючи спорядження, покинуте менш здібними попередниками.",h="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек.",kw={"заблукала зброя","ґорнек","кзан торнслеш","зброяр","долина випробувань","новобранці"},ang={["class:Warrior"]="Повага до зброї — основа для будь-якого воїна. Збирання зброї, яку покидали невдалі новобранці, наголошує на дисципліні й самостійності ще до справжнього бою.",["faction:Horde"]="Орда виживає в Дуротарі завдяки впертості й кмітливості, відмовляючись марнувати зброю навіть тоді, коли її покинули ті, хто не гідний її носити.",["profession:Blacksmithing"]="У Дуротарі на вагу золота кожен клапоть металу. Допомога Кзанові зібрати зіпсоване спорядження відображає обов'язок коваля повертати залізо й перековувати побиті леза на придатні знаряддя війни."},sec={{t="Озброїти нову кров",b="Долина Випробувань — кузня, де сирих новобранців гартують суворі червоні пустки Дуротару. Безліч претендентів виходить уперед, щоб присягнути своїми клинками вождю, і запаси зброї в таборі напружені до краю. Зброяр Кзан Торнслеш ледве встигає за попитом, особливо коли перші уроки виявляються смертельними або принизливими для неготових."},{t="Випробування кмітливості",b="Наглядач Ґорнек обертає цю нестачу на практичне випробування. Замість марнувати новий метал, він посилає новоприбулих збирати покинуті клинки й тупу тренувальну зброю, залишену невдахами, що впали або втекли в пилюці. Доставка зібраної зброї Кзанові дає ковалеві змогу полагодити й загартувати її для наступної хвилі, а новачків навчає: виживання в Орді вимагає не лише махати сталлю, а й збирати її."}},faq={{q="Чому довкола стільки покинутої навчальної зброї?",a="Не кожен охочий, що ступає в Долину Випробувань, має силу й рішучість, яких вимагає Орда. Боязкі чи недбалі новобранці раз у раз кидають спорядження в паніці або гинуть від місцевих кабанів і скорпідів, і видана їм зброя валяється в пилюці.",al={"чому тут стільки зброї","покинута зброя дуротару","зброя невдалих новобранців"}},{q="Хто такий Кзан Торнслеш?",a="Кзан Торнслеш — місцевий зброяр у Лігві в Долині Випробувань. Він споряджає новобранців, лагодить пошарпане навчальне спорядження й дбає про військові запаси Орди в початковій долині.",al={"кзан торнслеш","хто такий кзан","зброяр кзан"}},{q="Хто дає це доручення?",a="Це доручення дає Ґорнек — наглядач, що стоїть біля Лігва. Він стежить за новоприбулими охочими, оцінює їхні здібності й посилає розв'язувати нагальні справи на випробувальних землях.",al={"хто дає заблукалу зброю","завдання ґорнека"}},{q="Що Кзан зробить із цією підібраною зброєю?",a="Кзан лагодить, гострить і відновлює потовчену навчальну зброю. Ресурсів у Дуротарі обмаль, а новобранці прибувають безперестанку, тож підібране залізо й дерево мусять знову послужити наступній хвилі.",al={"що кзан робить зі зброєю","ремонт зброї кзаном"}},{q="Де відбувається це завдання?",a="Воно відбувається в Долині Випробувань — відлюдному каньйоні на півдні Дуротара, де молоді орки й тролі Темного Спису починають свій шлях воїнів Орди.",al={"місце долини випробувань","де заблукала зброя"}},{q="Чому Орда просто не викує зовсім нову зброю?",a="Дуротар — суворий, посушливий край, де мало легкодоступних покладів заліза, а молода Орда не може дозволити собі марнотратства. Перероблені навчальні клинки невдах дають змогу зберегти метал для військ на передовій.",al={"чому не викувати нову","нестача металу в дуротарі"}}},fp="15,323,20.384.0,25.431.0,62.279.0,23.243.0,21.204.0,46.201.0,33.160.0,54.215.0"}
P.entries["quest:973"] = {n="Вежа Альталакса",s="Це завдання — п'ятий розділ розслідування у Вежі Альталакса, що веде шукачів пригод Альянсу з Темного Узбережжя на південь, до Ашенвалю. Делґрен Очищувач посилає вас убити Ілкруда Маґтрулла, орка-чорнокнижника, що засів у спотвореному Святилищі Вогняного Шраму, і забрати його езотеричний фоліант.",h="Це завдання — п'ятий розділ розслідування у Вежі Альталакса, що веде шукачів пригод Альянсу з Темного...",kw={"вежа альталакса","ілкруд маґтрулл","святилище вогняного шраму","делґрен очищувач","чорнокнижник","ашенваль"},ang={["class:Paladin"]="Діяти пліч-о-пліч із Делґреном Очищувачем, знищуючи викликачів Скверни й конфіскуючи зіпсовані фоліанти, — класичне покликання Святого Світла проти демонічної порчі.",["class:Warlock"]="Двобій з Ілкрудом Маґтруллом зводить вас із побратимом по темних мистецтвах, який стереже свої нечестиві тексти викликаними сукубами й блукачами Порожнечі.",["faction:Alliance"]="Це завдання виводить шукачів пригод Альянсу з безпечного Темного Узбережжя вглиб уражених демонами закутків Ашенвалю, щоб очистити їх від дедалі грізнішої темної загрози.",["race:NightElf"]="Святилище Вогняного Шраму — мерзенне осквернення давніх лісів Ашенвалю, тож знищити Ілкруда — означає боронити священні землі предків."},sec={{t="Полювання в Ашенвалі",b="Ідучи слідом темної діяльності культистів, виявленої у Вежі Альталакса на Темному Узбережжі, святий воїн Делґрен Очищувач упізнає почерк небезпечного чаклуна — орка-чорнокнижника Ілкруда Маґтрулла. Діючи з демонічної виразки, відомої як Святилище Вогняного Шраму, на південному заході Ашенвалю, Ілкруд своїми темними оборудками загрожує поширити мерзенну магію чистими ельфійськими лісами. Делґрен доручає вам убити чорнокнижника й забрати його гримуар, щоб викрити задуми його господаря."},{t="Лігво чорнокнижника",b="Святилище Вогняного Шраму — понівечені Скверною руїни, що кишать демонічними невільниками. На кам'янистому підйомі до святилища стоять зловісні червоні стовпи, а в ньому живе Ілкруд разом із викликаним сукубом і вартовими-вбивцями Скверни. Здолавши орка в самому серці його володінь Скверни, Делґрен може перешукати фоліант Ілкруда в пошуках темних знань і наказів, що ведуть до зловісних обрядів в Альталаксі."}},faq={{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри, заставі нічних ельфів на межі Темного Узбережжя й Ашенвалю. Він керує боротьбою з демонічною скверною й культистами, що діють у краї.",al={"делґрен","переказ про делґрена","хто починає завдання"}},{q="Хто такий Ілкруд Маґтрулл?",a="Ілкруд Маґтрулл — грізний орк-чорнокнижник, що влаштував лігво в Святилищі Вогняного Шраму на південному заході Ашенвалю. Спершу Делґрен вважав його дрібною прикрістю, але зв'язок Ілкруда з темними обрядами у Вежі Альталакса робить його важливою ціллю.",al={"ілкруд","хто такий ілкруд маґтрулл","орк-чорнокнижник ашенваль"}},{q="Де Святилище Вогняного Шраму?",a="Святилище — на південному заході Ашенвалю, на південь від Святилища Аессіни й на захід від Астранаару. Це осквернена обитель, де кишать демони, а шлях до вівтаря Ілкруда обрамлюють два помітні червоні стовпи.",al={"місце святилища вогняного шраму","де ілкруд","як дістатися ілкруда"}},{q="Навіщо Делґренові фоліант Ілкруда Маґтрулла?",a="У фоліанті Ілкруда — його темні обряди й листування. Делґрен хоче розшифрувати записи, щоб з'ясувати, яка лиха змова пов'язує орка-чорнокнижника з культистами, що засіли біля Вежі Альталакса.",al={"навіщо фоліант","що у фоліанті ілкруда","призначення фоліанта"}},{q="Як це завдання пов'язує Темне Узбережжя з Ашенвалем?",a="Історія починається з розслідування біля Вежі Альталакса на північному узбережжі Темного Узбережжя. Що глибша таємниця, то далі мережа культистів веде шукачів пригод — через усе Темне Узбережжя до спірних лісів Ашенвалю.",al={"зв'язок темного узбережжя й ашенвалю","ланцюжок альталакса"}},{q="Що буде, коли фоліант здобуто?",a="Делґрен вивчає текст, щоб розгадати глибші задуми культистів біля Вежі Альталакса, — це веде до останніх сутичок ланцюжка.",al={"що після фоліанта","що йде після альталакса 5"}}},fp="22,305,21.502.0,18.385.1,28.227.0,24.253.0,38.211.0,46.206.0,51.230.0,39.167.0"}
P.entries["quest:976"] = {n="Припаси для Обердайна",s="«Припаси для Обердайна» — завдання на супровід, у якому шукачі пригод з Альянсу захищають Фіро Айронгенда, поки той везе важливі припаси й донесення з Посту Маестри на північ, до Темного Узбережжя. Через дедалі більшу загрозу, що йде від Вежі Альталакса, і ворожих лазутчиків в Ашенвалі безпечний шлях аж ніяк не гарантований.",h="«Припаси для Обердайна» — завдання на супровід, у якому шукачі пригод з Альянсу захищають Фіро Айронгенда...",kw={"припаси для обердайна","фіро айронгенд","пост маестри","супровід","темне узбережжя","ашенваль"},ang={["faction:Alliance"]="Захищаючи цей шлях, ви дбаєте, щоб застави Ашенвалю лишалися пов'язаними з осередком постачання в Обердайні, і бережете хиткі позиції Альянсу на півночі Калімдору.",["race:Human"]="Фіро Айронгенд уособлює готовність людей підтримувати союзників-калдореїв глибоко в незнайомих, небезпечних прадавніх лісах.",["race:NightElf"]="Припаси й донесення, що йдуть на північ, безпосередньо допомагають вартовим в Обердайні протистояти темряві, що густішає по всьому Темному Узбережжю та на межі з Ашенвалем."},sec={{t="Небезпечна дорога на північ",b="Пост Маестри стоїть на західному прикордонні Ашенвалю — тиха застава між неспокійними хащами лісу та стривоженими землями Темного Узбережжя. Після розслідування зловісних подій довкола Вежі Альталакса Делґрен Очищувач збирає важливі припаси й донесення для Вартової Старбріз в Обердайні. Замість ризикувати самотніми гінцями застава покладається на озброєний супровід, що йде разом із Фіро Айронгендом лісовою дорогою."},{t="Тіні вздовж стежки",b="Подорож показує, наскільки небезпечною стала глушина довкола дороги. На шляху Фіро чекають злагоджені засідки. Сектанти Темного Берега прагнуть не пропустити жодного донесення про свої демонічні обряди, розвідники Відступників чатують у лісовому підліску, а люті ватажки — Балізар Похмурий, Аліґар Мучитель і Кедакар Лютий — намагаються знищити обоз, перш ніж він дістанеться кордону."}},faq={{q="Хто такий Фіро Айронгенд?",a="Фіро Айронгенд — кур'єр-людина на Посту Маестри на заході Ашенвалю. Делґрен Очищувач доручив йому доставити до Обердайна важливі послання й припаси, але Фіро достатньо обережний, щоб не вирушати в дорогу без надійних охоронців.",al={"фіро","фіро айронгенд","хто дворф-супровід"}},{q="Навіщо Обердайну ці припаси?",a="Темному Узбережжю й півночі Ашенвалю дедалі більше загрожують скверна й демонічні культисти, що діють із Вежі Альталакса. Вартовим нічних ельфів в Обердайні, яких на місці очолюють такі постаті, як Вартова Старбріз, потрібні свіжі припаси й найновіші відомості, щоб і далі боронити узбережжя.",al={"навіщо припаси оберіжину","припаси для оберіжина","вартова старбріз"}},{q="Хто нападає на Фіро в дорозі?",a="Фіро застерігає, що лісом никають небезпечні вороги, і просить охорони. Хто саме нападає, з'ясується під час супроводу.",al={"хто нападає на фіро","нападники на фіро","хто нападає на дорозі"}},{q="What is the connection to the Tower of Althalaxx?",a="Delgren the Purifier has been orchestrating efforts to uncover and disrupt the dark rituals of the cultists at the Tower of Althalaxx. This escort is the culmination of that investigative chain, ensuring that intelligence and vital support reach the Night Elf leadership in Auberdine.",al={"althalaxx connection","tower of althalaxx","delgren connection"}},{q="Where do I report after protecting Feero?",a="After seeing Feero safely through the ambushes in Ashenvale, you report back to Delgren the Purifier at Maestra's Post to confirm the delivery succeeded.",al={"turn in supplies to auberdine","where do i go after escorting feero","quest turn in"}}},fp="21,347,21.488.0,23.428.1,22.248.0,39.317.0,33.151.0,49.284.0,41.153.0"}
P.entries["quest:97894"] = {n="Справи в Обердайні",s="«Справи в Обердайні» — доручення від дворфа-торговця Борґуса Стілгенда в Стормвінді. Борґус просить мандрівників, що пливуть на захід, навідати його брата Ґорболда, який нещодавно взявся торгувати в портовому містечку нічних ельфів Обердайні. Це завдання поєднує гамірні доки людської столиці з туманними берегами північного Калімдору.",h="«Справи в Обердайні» — доручення від дворфа-торговця Борґуса Стілгенда в Стормвінді.",kw={"обердайн","борґус стілгенд","ґорболд стілгенд","темне узбережжя","гавань стормвінда","торгівля"},ang={["faction:Alliance"]="Пряме морське сполучення між Гаванню Стормвінда й Обердайном зміцнює торгові та військові зв'язки людського королівства із землями калдореїв на півночі Калімдору.",["race:Dwarf"]="Дворфійська торгівля сягає далеко за гори Каз Модану: заповзятливі купці на кшталт Стілгендів відкривають прилавки навіть у тихих, оповитих тінню поселеннях нічних ельфів."},sec={{t="Дворф далеко від дому",b="Родина Стілгендів славиться гострим розумом і чесною торгівлею, і Борґус охоче за неї ручається. Його брат, Ґорболд Стілгенд, нещодавно перетнув Велике Море, щоб тримати торговий прилавок в Обердайні. Постачати кораблі, що заходять до Темного Узбережжя, здавалося легким шляхом до багатства, але тижні цілковитої тиші непокоять Борґуса: як насправді ведеться його братові так далеко від Айронфорджа й Стормвінда?"},{t="Морський шлях",b="Колись, щоб доплисти зі Східних Королівств до дикого Калімдору, доводилося вирушати заплутаними шляхами через Гавань Менетіл чи нейтральні гоблінські порти на кшталт Буті Бей. Борґус скеровує мандрівників до корабля біля найпівденнішого причалу Гавані Стормвінда — прямого морського сполучення з довгими дерев'яними пірсами Обердайна."}},faq={{q="Хто такий Борґус Стілгенд?",a="Борґус Стілгенд — дворф-крамар у Стормвінді. Пишаючись славою своєї родини як чесних торгівців, він шукає перехожих шукачів пригод, щоб передати вісточку братові Ґорболду за море.",al={"борґус","хто дає справи в оберіжині","борґус стілгенд"}},{q="Де Ґорболд Стілгенд?",a="Ґорболд Стілгенд — в Обердайні, головному портовому поселенні Темного Узбережжя на північно-західному березі Калімдору. Він тримає крамничку для кораблів, що прибувають.",al={"де ґорболд","знайти ґорболда стілгенда","місце ґорболда"}},{q="Як дістатися зі Стормвінда до Обердайна?",a="Корабель відпливає просто з найпівденнішого причалу Гавані Стормвінда й перевозить пасажирів через Велике Море до доків Обердайна на Темному Узбережжі.",al={"корабель до оберіжина","як дістатися темного узбережжя зі стормвінда","корабель зі стормвінда до оберіжина"}},{q="Чому Борґус тривожиться за брата?",a="Кілька тижнів тому Ґорболд поїхав до крамнички в Обердайні, сподіваючись добре заробити на постачанні морських суден. Але відтоді він не надіслав додому жодної звістки, тож Борґус просить мандрівників з'ясувати, що сталося.",al={"чому перевіряти ґорболда","що сталося з ґорболдом"}},{q="Що за поселення Обердайн?",a="Обердайн — прибережний прихисток, збудований і заселений здебільшого нічними ельфами. Розташований на Темному Узбережжі, він — головний морський вузол Альянсу й переправа між північчю Калімдору та острівним краєм Тельдрассил.",al={"що таке оберіжин","містечко оберіжин"}},{q="Чим славиться родина Стілгендів?",a="Стілгенди — дворфійська купецька родина, що живе з торгівлі й крамничок і хвалиться тим, що завжди пропонує чесну угоду і мандрівникам, і портовим робітникам.",al={"родина стілгендів","стілгенди"}}},fp="21,329,21.430.0,18.345.0,24.185.0,35.169.0,42.162.0,40.238.0,37.232.0,39.163.0"}
P.entries["quest:97914"] = {n="Розширення обріїв",s="«Розширення обріїв» — дипломатичне доручення гінця, що починається на Темному Узбережжі й напряму пов'язує поселення нічних ельфів Обердайн із людським королівством Стормвінд. На прохання Тундріса Віндвівера шукач пригод везе через океан офіційне листування Міському Архітекторові Баросу Алекстону, щоб зміцнити зв'язки й торгівлю між двома далекими землями Альянсу.",h="«Розширення обріїв» — дипломатичне доручення гінця, що починається на Темному Узбережжі й напряму пов'язує...",kw={"обердайн","тундріс віндвівер","барос алекстон","міський архітектор","темне узбережжя","морський шлях"},ang={["faction:Alliance"]="Це доручення показує, якої щоденної, практичної праці потребує, щоб злютувати різні народи двох континентів в єдину дієву фракцію.",["race:Human"]="Повернення до Стормвінда з печаткою калдорейської гавані показує, як широко сягає вплив відбудованого королівства.",["race:NightElf"]="Для калдореїв відкриття морських шляхів до Східних Королівств — докорінний розрив із десятьма тисячами років відлюдництва, що нерозривно пов'язує ваш народ із людською цивілізацією."},sec={{t="Міст між двома півкулями",b="Тисячоліттями нічні ельфи жили в лісах Калімдору, відгороджені від Східних Королівств. Після Третьої війни їхній вступ до Великого Альянсу потребував справжніх зв'язків — не лише ідейних, а й торгових та морських. Обердайн — головний північний порт калдорейського материка, проте він довго лишався в тіні прадавніх зруйнованих міст, як-от Амет'Аран і Башал'Аран. Тепер, коли між Обердайном і Стормвіндом проклали прямий морський шлях, місцеві провідники прагнуть закріпити нові судноплавні маршрути й вплести свою прибережну громаду в ширшу мережу Альянсу."},{t="Послання Міському Архітекторові",b="Листування, яке везуть через Велике Море, адресоване особисто Баросу Алекстону, Міському Архітекторові Стормвінда. Як головний будівничий, відповідальний за відбудову людської столиці та її господарство, Алекстон опікується великими громадськими спорудами й постачанням. Мета ж самого Тундріса простіша: він хоче, щоб праця Обердайна дістала визнання, а про його дім дізналися."}},faq={{q="Хто дає вам це завдання?",a="Це доручення дає мандрівникам Тундріс Віндвівер, впливовий нічний ельф з Обердайна. Відчуваючи, що Обердайн обділяють увагою і високі гілки Дарнасуса, і далекі союзники за океаном, він прагне налагодити офіційний зв'язок із людським королівством.",al={"хто дає розширення обріїв","видавець розширення обріїв","завдання тундріса"}},{q="Хто такий Барос Алекстон?",a="Барос Алекстон — Міський Архітектор Стормвінда. Шанований міський будівничий і колишній член Гільдії Каменярів, що лишився вірним короні, він наглядає за будівництвом і утриманням споруд по всій столиці.",al={"переказ про бароса алекстона","хто такий барос","архітектор стормвінда"}},{q="Чому Обердайн звертається до Стормвінда?",a="Обердайн хоче, щоб його гавань визнали важливими воротами для припасів, торгівлі й подорожей Альянсу. Відколи відкрилися нові морські шляхи між Темним Узбережжям і Східними Королівствами, місцеві очільники сподіваються зміцнити господарські й транспортні зв'язки з людським королівством.",al={"чому оберіжин пише до стормвінда","зв'язок оберіжина і стормвінда","чому звертатися до людей"}},{q="Як подорожувати між Обердайном і Стормвіндом?",a="Тепер Обердайн з'єднує з королівством Стормвінд нове судно: воно перетинає Велике Море й заходить просто в Гавань Стормвінда, привозячи на береги Обердайна життя й припаси.",al={"корабель до стормвінда","як дістатися стормвінда з оберіжина"}},{q="Що таке Амет'Аран і Башал'Аран?",a="Це були квітучі міста Високородних на давньому Темному Узбережжі, доки Великий Розкол десять тисяч років тому не розтрощив континент. Нині вони лежать у руїнах, де блукають привиди, і в історії калдореїв їх згадують куди частіше, ніж живі поселення на кшталт Обердайна.",al={"переказ про амет'аран","башал'аран","давні міста темного узбережжя"}},{q="Чому лист треба віднести архітекторові, а не Королю Андуїну чи Болварові?",a="У завданні не сказано, чому Тундріс обрав саме його. Тундріс просто просить, щоб лист дістався людині на ім'я Барос Алекстон, Міському Архітекторові Стормвінда, аби праця Обердайна дістала визнання.",al={"чому барос алекстон","чому не болвар","чому не верховний лорд болвар"}}},fp="18,372,24.620.0,31.370.0,28.266.0,22.231.0,43.263.0,53.180.0,36.261.0,66.187.0"}
P.entries["quest:97919"] = {n="Табірна наука 101: перша допомога",s="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним мистецтвом виживання — польовою медициною. Урок спрямовує мандрівників до Мішель Белль у Ґолдширі, щоб навчитися готувати Аптечку для таборів у глушині.",h="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним...",kw={"табірна наука","перша допомога","аптечка","мішель белль","ґолдшир","бинти"},ang={["class:Rogue"]="Діючи в тіні, далеко від підтримки, розбійники залежать від польової медицини: перев'язати кровоточиві рани, перш ніж рушити до наступної цілі.",["class:Warrior"]="Не маючи вроджених цілющих заклять, бійці передової значною мірою покладаються на бинти й польові аптечки, щоб пережити тривалі походи в дикій природі.",["faction:Alliance"]="Ґолдшир лишається ключовим перехрестям для мандрівників Альянсу, що починають свій шлях із Нортширу в ширше королівство Елвінну."},sec={{t="Польова медицина в дорозі",b="Шукачі пригод, що мандрують Лісом Елвінн, швидко дізнаються: бої й суворе виживання в дикій природі дорого коштують. Міські цілителі й корчми дають перепочинок, та подорож небезпечними землями часто вимагає негайної самостійної допомоги. Перша допомога — практичний засіб від кровотеч і травм, що дає змогу гоїти рани, не покладаючись на чародійські ритуали чи святі молитви."},{t="Припаси для табору",b="Надійний табір — це більше, ніж вогонь і постіль; це тимчасовий прихисток від небезпек глушини. Навчаючись у Мішель Белль у ґолдширській Корчмі «Лев'яча Гордість», вправні цілителі вчаться збирати спеціальні аптечки. Медичні припаси під рукою в таборі дають утомленому загону змогу обробити поранення й відновити сили, перш ніж зустріти небезпеки попереду."}},faq={{q="Навіщо це завдання?",a="Це завдання скеровує шукачів пригод, що опанували основи Першої допомоги, до Мішель Белль у Ґолдшир. Вона навчає, як виготовити Аптечку, щоб табір у нетрях завжди мав необхідні засоби для лікування.",al={"мета табірної першої допомоги","що робить це завдання","навіщо табірна наука 101 перша допомога"}},{q="З ким треба поговорити в Ґолдширі?",a="Вам треба поговорити з Мішель Белль — наставницею в Ґолдширі. Щойно ви покажете достатню майстерність у Першій допомозі, вона поділиться прийомами виготовлення табірного приладдя для польової медицини.",al={"з ким говорити в ґолдширі","хто така мішель бель","наставник табору ґолдшира"}},{q="Чому Перша допомога важлива для мандрівників?",a="У мандрах завжди є ризик зазнати поранень від звірів, розбійників і суворої негоди. Перша допомога дає кожному — хай він володіє божественною магією, тайною чи жодною — змогу перев'язати рани й відновитися між сутичками.",al={"чому перша допомога важлива","чи перша допомога корисна","переказ про першу допомогу"}},{q="Де Ґолдшир?",a="Ґолдшир — головне селище Лісу Елвінн, трохи на південь від Стормвінда, на головному торговому шляху. Тут можна поповнити припаси, знайти місцевих наставників і відпочити в Корчмі «Лев'яча Гордість».",al={"де ґолдшир","місце ґолдшира","як знайти мішель бель"}},{q="Чи потрібна попередня підготовка, щоб виконати це доручення?",a="Так. Мішель Белль вимагає, щоб ви показали вправність у Першій допомозі, перш ніж вона навчить вас виготовляти табірні набори для цієї професії.",al={"вимоги табірної науки 101","потрібна перша допомога","передумови"}},{q="Яке місце Аптечка посідає в таборі?",a="Табір у нетрях дає безпечне місце для відновлення сил, а Аптечка в ньому гарантує, що поранені мандрівники матимуть під рукою бинти й ліки, потрібні, щоб рятувати життя далеко від міських цілителів.",al={"вжиток табірної аптечки","предмет табору перша допомога","навіщо аптечка"}}},fp="22,239,26.409.0,25.391.0,34.232.0,41.207.0,41.226.0,27.208.0,47.151.0,42.221.0"}
P.entries["quest:97920"] = {n="Табірна наука 101: риболовля",s="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в глушині й облаштування табору. Розшукавши місцевого знавця риболовлі Лі Брауна біля Ґолдшира, мандрівники вчаться застосовувати рибальські знання для виготовлення затишних дрібниць для стоянки — як-от декоративного акваріума, що підбадьорює шукачів пригод.",h="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в...",kw={"табірна наука","риболовля","лі браун","акваріум","ґолдшир","табір"},ang={["faction:Alliance"]="Люди-мандрівники, що починають свої пригоди в Лісі Елвінн, можуть покластися на знайомі води Ґолдшира, щоб опанувати основи самостійного життя в глушині."},sec={{t="Табірне ремесло для рибалок",b="Риболовлю часто вважають самотньою розвагою для тихих берегів озер і річок, та бувалі знавці виживання розуміють: табірне життя потребує більшого, ніж їжа й дах. Затишні речі на кшталт акваріума приносять легкість і бадьорість утомленим мандрівникам, що відпочивають між вилазками, і підтверджують переконання: ясний розум і високий дух гартують грізних бійців."},{t="Досвід Лі Брауна",b="Бувалий рибалка Лі Браун, що оселився біля води за Ґолдширом, допомагає рибалкам-новачкам, які прагнуть розширити своє ремесло. Тих, хто виявив достатню вправність із вудкою й волосінню, направляють до нього — навчитися, як простий улов і базові матеріали перетворити на корисні поліпшення для табору."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує охочих рибалок до Лі Брауна поблизу Ґолдшира. Щойно ви покажете базову вправність у риболовлі, він навчить вас виготовляти особливі табірні речі, як-от акваріум, щоб зробити придорожній табір затишнішим.",al={"навіщо табірна риболовля","що дає табірна наука 101","мета завдання"}},{q="Хто такий Лі Браун?",a="Лі Браун — обізнаний наставник рибалок, що стоїть біля Кришталевого Озера під самим Ґолдширом у Лісі Елвінн. Він навчає вудіння й розповідає, як змайструвати табірне приладдя для рибалок.",al={"де лі браун","хто навчає риболовлі в таборі","лі браун"}},{q="Що Акваріум дає табору?",a="Акваріум — табірна окраса, що дарує затишок і радість шукачам пригод на привалі. Приємна атмосфера в таборі підносить дух, і шукачі пригод почуваються готовими й спроможними протистояти небезпекам нетрів.",al={"ефект акваріума","що робить акваріум","навіщо акваріум"}},{q="Де відбувається навчання?",a="Завдання відбувається в Лісі Елвінн і веде гравців до водойм довкола Ґолдшира, де збираються місцеві рибалки.",al={"місце завдання","куди йти","наставник табору елвінн"}},{q="Чи потрібна попередня майстерність у риболовлі, щоб виконати це?",a="Так. Лі Браун навчає лише тих мандрівників, що вже набили руку в закиданні вудки й показали базову вправність у рибальському ремеслі.",al={"вимога риболовлі","чи потрібна риболовля","вимога майстерності"}},{q="Чи допомагає табір у бою?",a="Так. Доглянутий табір дарує затишок, що зміцнює тілесну й душевну готовність шукача пригод, а це прямо позначається на його витривалості й бойовій вправності в полі.",al={"чи табір допомагає в бою","баффи табору","навіщо табір"}}},fp="20,358,21.392.0,21.312.0,34.220.0,17.215.0,40.218.0,36.123.0,50.138.0,29.187.0"}
P.entries["quest:97957"] = {n="Табірна наука 101: травництво",s="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому Азероту — як-от до Фарузи у Бріллі, — щоб опанувати виготовлення Ароматичних Свічок. Ці запашні вироби дають життєво важливу відновлювальну підтримку заклиначам, які відпочивають у таборах серед дикої природи.",h="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому...",kw={"табірна наука","травництво","фаруза","ароматичні свічки","табір","елеанор шеклтон"},ang={["class:Mage"]="Заклиначі цінують травників, які виготовляють Ароматичні Свічки: їхній заспокійливий дим допомагає відновити зосередженість і дух далеко від затишку таверни.",["profession:Herbalism"]="Замість просто варити зілля чи продавати стебла, травники можуть прямо підтримувати загони шукачів пригод, виготовляючи запашні Ароматичні Свічки для багаття.",["race:Undead"]="Мандрівники з Відступників, що діють із Похоронного Подзвону та Брілла, вчаться у Фарузи робити практичні похідні речі з усохлої рослинності Тірісфалю."},sec={{t="Зілля для табору",b="Травництво зазвичай мають за підґрунтя алхімії, та практичне виживання в полі не менше залежить від зібраних коренів і квітів. Досвідчені мандрівники скеровують охочих збирачів до майстрів-травників краю — навчитися готувати Ароматичні Свічки. У Галявинах Тірісфалю Елеанор Шеклтон посилає перспективних збирачів до Фарузи у Бріллі, щойно ті покажуть базову вправність."},{t="Пожива для розуму",b="Життя в дорозі тяжко виснажує розум заклиначів і духовників. Ароматичні Свічки виділяють відновлювальні пахощі, покликані підняти дух і заспокоїти втомлений розум. Насичуючи свічки сушеними рослинами, збирачі дають важливу підтримку цілителям і магам, чиї магічні запаси вичерпуються в тривалих мандрах, — варто лише розбити табір і запалити свічку."}},faq={{q="Навіщо це завдання?",a="Завдання спонукає травників досягти базової вправності, щоб наставник із травництва навчив їх виготовляти Ароматичні Свічки. Ці свічки підтримують і допомагають заклиначам під час відпочинку в нетрях.",al={"навіщо табірне травництво","що дає табірна наука 101","мета табірного травництва"}},{q="Хто дає це завдання на Галявинах Тірісфалю?",a="На Галявинах Тірісфалю цю пораду травникам дає Елеанор Шеклтон, скеровуючи їх до Фарузи в сусідньому Бріллі.",al={"хто дає табірне травництво тірисфаль","завдання елеанор шеклтон"}},{q="Що дає Ароматична Свічка?",a="Ароматичні Свічки наповнюють табір благодатною атмосферою: підносять дух і допомагають цілителям та чарівникам відновити зосередженість під час відпочинку в полі.",al={"ефект ароматичної свічки","навіщо ароматичні свічки"}},{q="Хто навчає рецепта Ароматичної Свічки?",a="Шукачів пригод, що мають достатню вправність, навчають місцеві наставники з травництва. На Галявинах Тірісфалю цим займається Фаруза в Бріллі, а в інших містах і містечках — наставники на кшталт Джанді в Оргріммарі, Рейни Стоунбренч в Айронфорджі й Малорна Блейдліфа в Доланаарі.",al={"хто навчає ароматичної свічки","де здати табірне травництво"}},{q="Чи можуть узятися за це завдання члени інших фракцій і рас?",a="Так. Елеанор Шеклтон і Фаруза опікуються мандрівниками на Галявинах Тірісфалю, а інші дарувальники завдань і наставники дають таку саму науку травникам по всьому Калімдору й Східних Королівствах.",al={"чи це лише для орди","табірне травництво альянс"}},{q="Яка майстерність потрібна, щоб пройти навчання?",a="Травники мають показати справжню вправність у своєму ремеслі, досягнувши майстерності травництва двадцять, — лише тоді наставник навчить рецепта свічки.",al={"скільки травництва потрібно","рівень майстерності табірної науки"}}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Табірна наука 101: білування",s="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і по всьому Азероту. Вона скеровує білувальників, що вже попрактикувалися у своєму ремеслі, до майстрів краю — навчитися робити міцний похідний стілець із добутих шкур.",h="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і...",kw={"табірна наука","білування","ранд робарт","стілець","шкури","табір"},ang={["faction:Horde"]="Мисливці й збирачі Орди використовують кожен клапоть убитого звіра, щоб ніщо не пропало марно на безжальній дорозі.",["race:Undead"]="Навіть Відступники, вільні від смертної втоми, бачать практичну користь у впорядкованому похідному таборі, полюючи на зачумлених звірів Тірісфалю."},sec={{t="Затишок у глушині",b="Виживання в глушині вимагає більшого, ніж гострий клинок: треба вміти берегти сили між випробуваннями. Шукачі пригод на кшталт Елеанор Шеклтон наголошують, що звірині шкури дають більше, ніж просто крам на продаж. Опанувавши базові польові навички, білувальники можуть робити з вичинених шкур необхідні табірні вигоди — як-от стільці, — щоб утомлені мандрівники могли як слід відпочити й відновитися перед наступною небезпечною зустріччю."},{t="Опанування ремесла",b="У Галявинах Тірісфалю молодих білувальників з Відступників, що досягли початкової вправності, скеровують до Ранда Робарта, який веде своє ремесло при дорозі між Бріллом і руїнами Столиці над Андерсіті. Робарт ділиться практичними прийомами перетворення грубої шкіри на зручне табірне сидіння — мистецтво, яке повторюють майстри білування по всіх землях і Орди, і Альянсу."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує молодих білувальників до вправного наставника ремесла, який навчить їх змайструвати табірне крісло зі здобутих шкур тварин.",al={"що дає табірне білування","навіщо табірна наука білування","нагорода табірної науки 101"}},{q="Хто дає цю науку на Галявинах Тірісфалю?",a="На Галявинах Тірісфалю завдання дає Елеанор Шеклтон, скеровуючи нових білувальників до Ранда Робарта на великій дорозі між Бріллом і Андерсіті.",al={"хто дає цю науку тірисфаль","завдання елеанор шеклтон"}},{q="Яка майстерність потрібна, щоб виконати це доручення?",a="Вам треба підняти майстерність білування щонайменше до 20, — лише тоді наставник визнає вас досить досвідченим, щоб навчити виготовляти табірне спорядження.",al={"який рівень білування потрібен","вимоги табірного білування","потрібна майстерність білування"}},{q="Де знайти Ранда Робарта?",a="Ранд Робарт стоїть біля головної дороги, що йде на південь від Брілла до входу в Андерсіті на Галявинах Тірісфалю.",al={"де ранд робарт","місце ранда робарта","ранд робарт тірисфаль"}},{q="Чи можуть члени інших фракцій навчитися цього прийому?",a="Так. Відступники вчаться в Ранда Робарта, а такі самі наставники навчають білувальників у Ґолдширі, Айронфорджі, Доланаарі, Оргріммарі, Селі Бладгуф і Селі Шен'дар.",al={"чи це лише для орди","чи альянс може табірне білування","табірне крісло альянсу"}},{q="Чим корисне табірне крісло?",a="Табірне крісло дає зручне місце, щоб посидіти й відновити сили в нетрях, тож шукач пригод лишається відпочилим і пильним перед новими боями.",al={"навіщо табірне крісло","що робить крісло"}}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:981"] = {n="Вежа Альталакса",s="Це доручення — тріумфальне завершення кампанії проти Культу Темного Берега у Вежі Альталакса. Знищивши провід культу в зловісних руїнах Темного Узбережжя, шукач пригод несе звістку на південь, до Ашенвалю, Делґренові Очищувачу. Це важлива перемога Альянсу у вичищенні демонічної порчі з давніх кордонів нічних ельфів.",h="Це доручення — тріумфальне завершення кампанії проти Культу Темного Берега у Вежі Альталакса.",kw={"вежа альталакса","культ темного берега","делґрен очищувач","балтул шедовстрайк","пост маестри","перемога"},ang={["class:Paladin"]="Донесення Делґренові Очищувачу особливо важливе для паладинів, які поділяють його святу місію — очищати світ від демонічної порчі й лихих культів.",["faction:Alliance"]="Знищення культу захищає суходільну дорогу між Темним Узбережжям і Ашенвалем, і розвідники та мандрівники Альянсу можуть не боятися демонічних засідок.",["race:NightElf"]="Для нічних ельфів очищення Вежі Альталакса прибирає мерзенну пошесть із давніх руїн Високородних, розкиданих їхніми священними прибережними лісами."},sec={{t="Загрозу обірвано",b="Тижнями Вежа Альталакса була гнійною раною на півночі Темного Узбережжя, яку захопили фанатики Культу Темного Берега та їхні тіньові господарі. Невтомне стеження, збирання відомостей і запеклі сутички крок за кроком розібрали діяльність культу. Коли його чаклунів убито, а темні обряди зірвано, нагальну загрозу демонічного проникнення на Темне Узбережжя нарешті відвернуто."},{t="Донесення на Пост Маестри",b="Після смерті ватажка культу Балтул Шедовстрайк посилає переможця на південь, до Посту Маестри під кронами Ашенвалю. Там чекає Делґрен Очищувач — відданий воїн Святого Світла, що керував хрестовим походом проти лиходіїв Альталакса. Звістка про падіння культу заспокоює захисників краю й приносить звитяжцеві незмінне благословення та заслужену вдячність Делґрена."}},faq={{q="Яка мета цього завдання?",a="Це завдання — остаточна здача довгого сюжету про Вежу Альталакса. Вам треба лише вирушити з околиць вежі на Пост Маестри в Ашенвалі й доповісти Делґренові Очищувачу про вирішальну перемогу.",al={"мета вежі альталакса","здати вежу альталакса","де здати завдання 981"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри на півночі Ашенвалю. Володіючи Святим Світлом, він присвятив себе викоріненню скверни й боротьбі з демонічними загрозами на кшталт Культу Темного Берега по всій півночі Калімдору.",al={"хто такий делґрен","переказ про делґрена","делґрен очищувач"}},{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — агент Альянсу, що перебуває біля Вежі Альталакса на Темному Узбережжі. Тісно співпрацюючи з Делґреном, він стежить за пересуваннями культу й допомагає шукачам пригод зруйнувати темну зграю зсередини.",al={"балтул","переказ про балтула","хто балтул шедовстрайк"}},{q="Що Культ Темного Берега робив біля вежі?",a="Культ Темного Берега захопив давні руїни Вежі Альталакса, щоб правити темні обряди, закликати демонічних сутностей і поширювати свій лихий вплив прибережними землями Темного Узбережжя.",al={"культ темного берега","що сталося в альталаксі","переказ про вежу альталакса"}},{q="Де Пост Маестри?",a="Пост Маестри — застава Альянсу на північному заході Ашенвалю, трохи на південь від переходу межі з Темним Узбережжям на головній дорозі.",al={"місце поста маестри","де пост маестри","місце делґрена"}},{q="Чи Культ Темного Берега знищено цілком?",a="Його провід у Вежі Альталакса страчено, а головний обряд зірвано, але розпорошені культисти й рештки секти досі тиняються відлюдними закутками Калімдору. Утім, організовану загрозу на Темному Узбережжі розгромлено.",al={"чи культ зник","чи темний берег знищено","чи ми вбили культ"}}},fp="22,390,16.431.0,24.418.0,31.228.0,28.247.0,29.233.0,56.205.0,32.143.0,52.238.0"}
P.entries["quest:98190"] = {n="Друг родини",s="«Друг родини» — нагальне доручення гінця з Гавані Менетіл у Багнокраї. Побоюючись місцевих загроз, як-от орків Драконячої Пащі, влада гавані доручає шукачеві пригод доставити безцінну Статуетку Менетіла просто Верховному Лордові Болвару Фордрагону у Фортецю Стормвінда.",h="«Друг родини» — нагальне доручення гінця з Гавані Менетіл у Багнокраї.",kw={"друг родини","статуетка менетіла","болвар фордрагон","фортеця стормвінда","драконяча паща","гавань менетіл"},ang={["class:Paladin"]="Ім'я Менетіла нагадує про покровителя-засновника Лицарів Срібної Длані, тож збереження цієї реліквії — урочистий обов'язок для кожного святого воїна.",["faction:Alliance"]="Доставлена реліквія вшановує історичний північний Альянс і не дає безцінному символу потрапити в лапи клану Драконячої Пащі.",["race:Human"]="Для людей збереження артефакту династії Менетілів — це збереження гордої й трагічної пам'яті про загиблий Лордерон і утвердження обов'язку Стормвінда як останнього великого людського королівства."},sec={{t="Хитка гавань",b="Гавань Менетіл — важлива морська брама, що пов'язує північ Східних Королівств із півднем. Названий на честь покійного короля Лордерона Теренаса Менетіла II, порт стоїть відрізаним серед підступних боліт і войовничих ворогів. Коли місцеві загрози наростають, провід гавані розуміє: безцінні реліквії загиблого північного королівства не можуть лишатися в безпеці на такій відкритій заставі."},{t="Загроза Драконячої Пащі",b="Багнокрай досі кишить рештками клану Драконячої Пащі — лютими орками, відомими своїм темним минулим і безжальним пристосуванством. З огляду на їхню близькість і жагу завоювань, захисники гавані бояться, що Драконяча Паща ні перед чим не спиниться, аби пограбувати такі історичні скарби, як Статуетка Менетіла, — а то й осквернити такий символ чи обернути його собі на зброю."},{t="Просто до Верховного Лорда",b="Щоб не ризикувати затримками у звичайних бюрократичних чи військових ланках, гінцеві наказано оминути весь ланцюг командування. Реліквію відсилають просто у Фортецю Стормвінда, до рук Верховного Лорда Болвара Фордрагона, регента при юному королі Андуїні Рінні, вірячи, що провід столиці найкраще вбереже частку спадщини Лордерона."}},faq={{q="Що таке Статуетка Менетіла?",a="Статуетка Менетіла — цінна родинна реліквія, пов'язана з королівським родом Лордерона й Королем Теренасом Менетілом II. Вона уособлює історичні узи між північним королівством і Альянсом, тож на неї полюють мародери й вороги.",al={"реліквія менетіла","що за статуетка","переказ про статуетку"}},{q="Чому статуетка не може лишитися в Гавані Менетіл?",a="Гавань Менетіл відрізана від світу й оточена ворожими болотами, дворфами Темного Заліза, мурлоками й ворожими орками. Гарнізон вважає поселення надто вразливим, щоб надійно вберегти таку значущу реліквію.",al={"чому статуетку забирають","чи гавань менетіл небезпечна"}},{q="Хто такі Драконяча Паща і навіщо їм статуетка?",a="Клан Драконячої Пащі — угруповання орків, що окопалося в Багнокраї. Посадовці гавані бояться, що вони охоче пожертвують воїнами, аби пограбувати шановані реліквії Альянсу й, можливо, осквернити їх чи використати на зло.",al={"драконяча паща","навіщо оркам статуетка"}},{q="Чому реліквію треба доставити просто Болварові Фордрагону?",a="Як регент Стормвінда й захисник юного Короля Андуїна, Верховний Лорд Болвар Фордрагон має найвищу владу в столиці. Якщо віддати реліквію просто йому, вона мине бюрократичну тяганину й опиниться під найнадійнішою охороною.",al={"чому болвар","чому в обхід ланцюга командування"}},{q="Де знайти Верховного Лорда Болвара Фордрагона?",a="Верховний Лорд Болвар Фордрагон стоїть у тронній залі Фортеці Стормвінда, поруч із хлопчиком-королем Андуїном Рінном.",al={"місце болвара","де болвар"}},{q="Як Гавань Менетіл пов'язана з Королем Теренасом?",a="Гавань Менетіл назвали на честь Короля Теренаса Менетіла II, який правив Лордероном і підтримував Альянс Лордерона в Другій війні, доки не загинув трагічною смертю в Третій.",al={"чому гавань менетіл","зв'язок теренаса менетіла"}}},fp="22,291,19.430.0,20.362.0,24.373.0,31.240.0,48.205.0,46.226.0,51.236.0,43.118.0,49.192.0"}
P.entries["quest:98191"] = {n="Друг родини",s="Верховний Лорд Болвар Фордрагон доручає шукачеві пригод доставити рідкісну Статуетку Менетіла до Собору Світла. Ця реліквія, що зображує покійного короля Лордерону Теренаса Менетіла II, почала вбирати святу силу. Її передають Лордові Ґрейсонові Шедовбрейкеру на вічне зберігання в духовному серці Стормвінда.",h="Верховний Лорд Болвар Фордрагон доручає шукачеві пригод доставити рідкісну Статуетку Менетіла до Собору...",kw={"статуетка менетіла","теренас менетіл","болвар фордрагон","ґрейсон шедовбрейкер","собор світла","паладин"},ang={["class:Paladin"]="Для паладина берегти реліквію короля Теренаса, якої відчутно торкнулося Світло, — вияв глибокої шани до правителя, що колись благословив заснування Лицарів Срібної Длані.",["class:Priest"]="Свята енергія, що зібралася в простій різьбленій подобі, підтверджує: духовна спадщина вірних Лордерону живе й після того, як саме королівство зруйноване.",["faction:Alliance"]="Король Теренас Менетіл II був наріжним каменем Альянсу Лордерону, тож будь-який пов'язаний із ним артефакт — дорогоцінний символ єдності й пам'яті."},sec={{t="Рідкісна пам'ятка",b="Король Теренас Менетіл II був творцем Великого Альянсу під час Другої війни й людиною глибокої побожності. Попри свою величезну вагу серед людських королівств, Теренас був надзвичайно скромним і, як відомо, не любив пам'ятників на свою честь. Через цю його неохоту замовили дуже мало його зображень, і ще менше з них уціліло під час жахливого спустошення й навали Погибелі, що захлиснула Лордерон."},{t="Дотик благодаті",b="Оглянувши вцілілу Статуетку Менетіла, Верховний Лорд Болвар Фордрагон бачить у ній щось значно більше, ніж просто майстерну різьбу. Саме Святе Світло почало збиратися в різьбленій фігурці, наповнюючи її тихим духовним відгомоном. Вирішивши, що королівський палац у Фортеці Стормвінда — не належне святилище для такої священної речі, Болвар велить перенести її через місто до Собору Світла й передати в надійні руки наставника паладинів Лорда Ґрейсона Шедовбрейкера."}},faq={{q="Хто такий Король Теренас Менетіл II?",a="Король Теренас Менетіл II був улюбленим правителем королівства Лордерон. Під час Другої війни він згуртував розрізнені людські держави разом із дворфами, гномами й високими ельфами у Великий Альянс, який зрештою розгромив Орду орків. Він загинув, коли впало його королівство.",al={"теренас менетіл","хто такий теренас","король лордерона"}},{q="Чому статуї Короля Теренаса такі рідкісні?",a="Попри величезний авторитет і любов народу, Король Теренас славився особистою скромністю й не любив пишних пам'ятників на свою честь. Його подобу вирізьбили в небагатьох статуях і пам'ятних знаках, і майже жоден із них не пережив руйнування Лордерона Погибеллю.",al={"чому мало статуй","рідкість статуетки теренаса","чому мало пам'ятників"}},{q="Чому Статуетка Менетіла сяє Світлом?",a="Bolvar notices that the Light seems to have coalesced in the statuette. He speaks of Terenas as a good and devout man, but does not explain why this particular likeness has gathered holy power.",al={"чому статуетка світиться","свята статуетка","світло що збирається"}},{q="Хто такий Лорд Ґрейсон Шедовбрейкер?",a="Лорд Ґрейсон Шедовбрейкер — бувалий паладин із людей, лицар Срібної Длані й шанований наставник Собору Світла. Він перебуває на Соборній Площі, навчає майбутніх паладинів і опікується святими справами вірян Стормвінда.",al={"хто такий шедовбрейкер","роль лорда ґрейсона"}},{q="Чому Верховний Лорд Болвар відсилає статуетку до Собору?",a="Болвар шанує Теренаса як батька Альянсу, але статуетка помітно набралася святої сили. Він вважає, що таке вмістилище Світла належить не придворним урядовцям у Фортеці Стормвінда, а Соборові Світла під опікою святих орденів.",al={"чому відсилати до собору","чому не лишити у фортеці"}},{q="Де Собор Світла?",a="Собор Світла височіє над Соборною Площею в самому серці Стормвінда, між Дворфійським Кварталом, Торговим Кварталом і Кварталом магів. Це головне святилище й осередок богослужінь Церкви Святого Світла в південних королівствах.",al={"де собор світла","місце соборної площі"}}},fp="22,330,18.456.0,16.505.0,33.294.0,40.275.0,53.193.0,34.252.0,61.275.0,40.275.0"}
P.entries["quest:982"] = {n="Глибокий океан, безкрає море",s="«Глибокий океан, безкрає море» — завдання Альянсу, яке дає Ґорболд Стілгенд в Обердайні. Шукачі пригод мають пірнути у води на північ від селища й дістати особисті скриньки з двох затонулих кораблів нічних ельфів — «Срібної Зорі» та «Туманної Завіси». На обидва кораблі напали прибережні мурлоки, і вцілілі члени команди прагнуть хоч якоїсь розради.",h="«Глибокий океан, безкрає море» — завдання Альянсу, яке дає Ґорболд Стілгенд в Обердайні.",kw={"глибокий океан безкрає море","ґорболд стілгенд","срібна зоря","туманна завіса","мурлоки","обердайн"},ang={["faction:Alliance"]="Спільне горе команди в Обердайні показує тісну морську співпрацю дворфів і нічних ельфів на узбережжі Калімдору.",["race:Dwarf"]="Ґорболд Стілгенд показує типовий для дворфів порив ушановувати полеглих товаришів і підтримувати побратимів-моряків у чужих портах.",["race:NightElf"]="Загиблі капітани були мореплавцями з нічних ельфів, що служили морській торгівлі Обердайна, тож повернення їхніх речей — справа честі предків."},sec={{t="Трагедія біля берега",b="Води біля Темного Узбережжя стають дедалі небезпечнішими — не лише через підступні течії й природні рифи, а й через агресивні прибережні племена. Кораблі «Срібна Зоря» й «Туманна Завіса» заходили до порту Обердайн, коли на них навалилися зграї мурлоків. Жоден корабель не вцілів — обидва пішли на дно на мілині на північ від поселення. Уцілілі члени команди дісталися берега, але втрата кораблів і капітанів кинула на порт важку тінь."},{t="Повернути втрачену пам'ять",b="Ґорболд Стілгенд, дворф, що працює в Обердайні, береться вшанувати загиблих капітанів — нічних ельфів. Хоча кораблі тепер — підводні руїни, які місцеві мурлоки привласнили як трофеї й гнізда, капітанські скриньки досі лежать замкнені в затоплених трюмах. Повернення журналів і особистих речей дасть уцілілим морякам в Обердайні змогу гідно оплакати своїх командирів і упокоїти їхні душі."}},faq={{q="Де затонулі кораблі?",a="Уламки «Срібної Зорі» й «Туманної Завіси» лежать під водою біля Темного Узбережжя, просто на північ від доків Обердайна.",al={"де затонулі кораблі","місце уламків","де срібна зоря"}},{q="Що сталося зі «Срібною Зорею» й «Туманною Завісою»?",a="Обидва кораблі потрапили в засідку мурлоків, коли пливли морем до Обердайна. Команди не встояли, обидва капітани загинули, а кораблі затонули й лягли на морське дно.",al={"як потонули кораблі","чому кораблі розбилися","що потопило туманну завісу"}},{q="Хто такий Ґорболд Стілгенд?",a="Ґорболд Стілгенд — дворф, що мешкає в портовому Обердайні нічних ельфів. Він опікується вцілілими моряками в місті й доручає шукачам пригод повернути речі загиблих капітанів.",al={"хто дає глибокий океан","переказ про ґорболда стілгенда"}},{q="Що в скриньках?",a="У скриньках — особисті речі й журнали загиблих капітанів із нічних ельфів, дорогі серцю вцілілих членів команд, які врятувалися з корабельної аварії.",al={"що в скриньках","вміст скриньки капітана"}},{q="Чому вцілілі так дорожать цими речами?",a="Капітани були шанованими мореплавцями з нічних ельфів. Повернути їхні журнали й речі означає дати вцілілій команді змогу попрощатися, і, як вірять, це допоможе духам капітанів знайти спокій.",al={"чому вцілілі дорожать речами","чому допомагати капітанам"}},{q="Які істоти тепер живуть на затонулих кораблях?",a="Уламки захопили мурлоки: вони вважають розбиті корпуси своїми трофеями й никають у водах довкола.",al={"хто охороняє кораблі","істоти біля затонулих кораблів"}}},fp="20,359,21.488.0,24.426.0,35.143.0,54.185.0,25.193.0,29.164.0,54.177.0,42.115.0"}
P.entries["quest:983"] = {n="Дзижчалка 827",s="«Дзижчалка 827» — перша ланка дослідної мережі зв'язку, яку гном Візбанґ Кранктоґґл збудував уздовж берегів Темного Узбережжя. Ці цікаві механічні пристрої постійно ламаються й мають ексцентричну конструкцію: для польового ремонту їм потрібні частини місцевих тварин. Відновивши замовклу машину, Візбанґ може випробувати свою мережу голосового зв'язку на великі відстані просто з Обердайна.",h="«Дзижчалка 827» — перша ланка дослідної мережі зв'язку, яку гном Візбанґ Кранктоґґл збудував уздовж берегів...",kw={"дзижчалка 827","візбанґ кранктоґґл","нога повзуна","повзуни","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Органічний хітин і кінцівки членистоногих замість литих латунних шестерень — квінтесенція гномської імпровізації, що міняє довговічність на матеріали, які можна знайти просто під ногами.",["race:Gnome"]="Пристрій Візбанґа — класична гномська амбіція: спроба принести технологічний зв'язок у давній, дикий край, що не бачив ні телефону, ні радіо.",["race:NightElf"]="Брязкітливі, задимлені дзижчалки — дивне більмо на оці священних, похмурих берегів Калімдору, хоча нічні ельфи Обердайна терплять експерименти майстра."},sec={{t="Гномські винаходи на давніх берегах",b="Перебуваючи в Обердайні, ексцентричний гном-інженер Візбанґ Кранктоґґл задумав подолати великі відстані дикого узбережжя низкою звукових ретрансляторів далекої дії — дзижчалок. Призначені передавати голос на великі відстані, ці пристрої, обвішані важелями, різко контрастують із давніми руїнами й похмурими лісами Темного Узбережжя. Та, як і багато амбітних гномських винаходів, вони хронічно нестабільні й потребують майже постійного догляду, щоб їхні шестерні не спинялися."},{t="Екологічне обслуговування",b="Замість тягати нетрями виточені залізні шестерні й мідні шпильки Візбанґ вдався до нестандартного рішення: кожну дзижчалку він зробив так, щоб її можна було обслуговувати деталями, здобутими з місцевих звірів. Дзижчалка 827, що стоїть трохи на південь від Обердайна на імлистому березі, сконструйована працювати з міцними, членистими ногами місцевих припливних і рифових повзунів. Щойно ноги потрапляють у приймальний бункер, машина сама себе складає й оживає, транслюючи з гучномовців далекий голос Візбанґа."}},faq={{q="Що таке Дзижчалка?",a="Дзижчалка — машина для голосового зв'язку на великій відстані, яку винайшов гном Візбанґ Кранктоґґл. Оснащена важелями й внутрішнім механізмом, вона має передавати голоси через дикі простори Темного Узбережжя, щоб люди могли говорити за багато миль.",al={"що робить дзижчалка","призначення дзижчалки","гномський ящик темного узбережжя"}},{q="Навіщо металевій машині крабові лапи?",a="Візбанґ навмисно сконструював кожну Дзижчалку так, щоб вона працювала на органічних деталях від місцевих тварин як на підручних запчастинах. Поставивши Дзижчалку 827 біля пляжу, де водяться повзуни, він подбав, щоб мандрівники могли полагодити механізм у скрутну хвилину хітиновими кінцівками замість рідкісного обробленого металу.",al={"навіщо крабові лапи","ремонт крабовими лапами","чому годувати лапами"}},{q="Де Дзижчалка 827?",a="Дзижчалка 827 стоїть на березі Темного Узбережжя, недалеко на південь від прибережного Обердайна.",al={"місце дзижчалки 827","де дзижчалка 827","знайти дзижчалку 827"}},{q="Хто такий Візбанґ Кранктоґґл?",a="Візбанґ Кранктоґґл — гном-винахідник, що зупинився на верхньому поверсі корчми в Обердайні. Честолюбний і заповзятливий, він намагається збудувати мережу зв'язку по всьому Темному Узбережжю, хоч його дослідні зразки раз у раз ламаються.",al={"візбанґ кранктоґґл","хто зробив дзижчалку","гном оберіжина"}},{q="Де взяти Лапи Повзуна для ремонту?",a="Лапи Повзуна можна здобути з карликових припливних повзунів і молодих рифових повзунів, що снують піском і мілинами пляжу Темного Узбережжя трохи на південь від Обердайна.",al={"місце лап повзуна","як отримати лапи повзуна","карликовий приливний повзун"}},{q="Що буде, коли Дзижчалку 827 полагоджено?",a="Коли Лапи Повзуна закинуто в приймач, машина перемелює їх і вставляє на місце, знову оживає з гудінням і передає голос Візбанґа з Обердайна. Утішений успіхом, він одразу просить вас вирушити далі вздовж узбережжя й полагодити наступний пристрій у мережі — Дзижчалку 411.",al={"після дзижчалки 827","далі ланцюжок дзижчалки","завершення дзижчалки 827"}}},fp="11,384,36.502.0,22.539.0,18.258.0,47.302.0,29.121.0,27.256.0,45.164.0,42.278.1"}
P.entries["quest:98362"] = {n="До Тандер Блафа",s="«До Тандер Блафа» — тріумфальне повернення молодого друїда-таурена з Місячного Гаю, де він зустрівся з Колом Кенарія. Здобувши прихильність Великого Духа Кота, учень повертається до Турака Рунтотема на Узвишші Старійшин, щоб опанувати мистецтво перевтілення в кота.",h="«До Тандер Блафа» — тріумфальне повернення молодого друїда-таурена з Місячного Гаю, де він зустрівся з Колом...",kw={"друїд","котяча подоба","турак рунтотем","місячний гай","великий дух кота","дендрит старблейз","коло кенарія"},ang={["class:Druid"]="Цей обряд пробуджує ваші хижі інстинкти й дарує владу над скраданням і пазурами — так, як навчає Турак Рунтотем.",["faction:Horde"]="Хоч Коло Кенарія зберігає нейтралітет, друїди Орди мусять повертатися до своєї столиці, щоб їхня зростаюча сила служила захистові рідних.",["race:Tauren"]="Ця подорож показує, як таурени відновлюють зв'язок із традиціями Кенарія, несучи науку священного Місячного Гаю назад на Узвишшя Старійшин у Тандер Блафі."},sec={{t="Повернення з Місячного Гаю",b="Довівши свою проникливість і гідність перед Дендритом Старблейзом і Великим Духом Кота серед священних дерев Місячного Гаю, молодий друїд має принести благословення духа назад до Малгора. Єднання з такими первісними силами — переломна мить у навчанні друїда: воно поєднує давні вчення нічних ельфів із власною земною спадщиною тауренів."},{t="Опанувати котячу подобу",b="На вас чекає Турак Рунтотем — високо на Узвишші Старійшин у Тандер Блафі. Дендрит допоміг поєднатися з самим духом, а от провести тілесне перевтілення випадає Туракові. Коли благословення Великого Духа Кота визнано, старий наставник передає священне знання, потрібне, щоб прибрати стрімку, хижу котячу подобу."}},faq={{q="Де починається й закінчується це завдання?",a="Завдання дає Дендрит Старблейз у священному прихистку Місячний Гай. Воно відсилає мандрівника назад на Узвишшя Старійшин у Тандер Блафі, до Турака Рунтотема.",al={"де здати завдання","хто починає до тандер блафа","здати до тандер блафа"}},{q="Навіщо це завдання?",a="Це завершальний перехід друїдського випробування кота. Отримавши благословення Великого Духу Кота в Місячному Гаю, новачок має повернутися до свого наставника в Тандер Блафі, щоб нарешті навчитися приймати Котячу подобу.",al={"навіщо до тандер блафа","що дає до тандер блафа","завдання форми кота"}},{q="Хто такий Турак Рунтотем?",a="Турак Рунтотем — шанований старійшина друїдів-тауренів на Узвишші Старійшин у Тандер Блафі. Він опікується навчанням і посвятою молодих друїдів Орди, що прагнуть жити в гармонії з природою й опанувати свої подоби.",al={"переказ про турака рунтотема","хто такий турак"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — нічний ельф, хранитель із Кола Кенарія, що наставляє друїдів-гостей у Нічному Притулку в Місячному Гаю. Він єднає давні традиції калдореїв і практики тауренів, хай яка напруга між фракціями.",al={"роль дендрита старблейза","нічний ельф у місячному гаю"}},{q="Що таке Великий Дух Кота?",a="Великий Дух Кота — давня первісна сутність, яку шанують друїди: він уособлює хижацький інстинкт, скрадливість і спритність. Кожен друїд, що прагне прийняти котячу подобу, мусить пройти випробування, щоб здобути його благословення й збагнути його подвійну натуру — грайливу й смертоносну.",al={"переказ про духа кота","дух кота"}},{q="Чи мають друїди Альянсу подібне завдання?",a="Так. Друїди нічних ельфів проходять подібний обряд у Місячному Гаю, але повертаються до свого наставника в Дарнасус, а не на обвітрені плато Малгору.",al={"версія для альянсу до тандер блафа","повернення нічного ельфа форми кота"}}},fp="16,278,21.359.0,22.359.0,36.169.0,34.235.0,23.236.0,26.240.0,29.262.0,43.168.0"}
P.entries["quest:98389"] = {n="Світло в темряві",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати новопідняту нежить, що потрапила в пастку в Лощині Нічної Павутини. Воно висвітлює делікатні стосунки між носіями Святого Світла з нежиті та людом, який їм глибоко не довіряє. Допомагаючи полеглим родичам, ці носії святої сили сподіваються довести свою вірність Сильвані та справі Відступників.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати...",kw={"світло в темряві","араміс гаммергенд","лощина нічної павутини","павуки","порятунок","святе світло"},ang={["class:Priest"]="Для Відступників, які спрямовують святу енергію, ця місія ілюструє тонку линву між залишковою смертною вірою і суворою дійсністю нежиття.",["race:Undead"]="Це завдання показує складну внутрішню боротьбу Відступників — те, як окремі з них долають упередження серед власного щойно повсталого народу."},sec={{t="Хистка віра",b="Святе Світло горезвісно болісне й небезпечне для нежиті, та дехто з Відступників зберігає зв'язок зі священною магією, якою володів за життя. У Похоронному Подзвоні такі постаті, як Араміс Гаммергенд, прагнуть довести, що їхня віра не обернула їх проти власного народу. Щоб розвіяти підозру, нібито носії святої сили повернуться проти іншої нежиті як проти потвор, вони діяльно використовують свої вміння й співчуття, щоб захищати родичів."},{t="Лощина Нічної Павутини",b="На північний захід від Похоронного Подзвону лежить Лощина Нічної Павутини — вогка печера, що кишить лютими павуками. Свіжопіднята нежить, ще спантеличена пробудженням і не здатна себе захистити, раз у раз забрідає в лощину й опиняється в коконах липкого павутиння. Порятунок цих нещасних Відступників служить подвійній меті: зберегти новобранців для Темної Леді й довести очільникам на кшталт Екзекутора Аррена, що носії Світла — віддані слуги Відступників."}},faq={{q="Хто дає завдання «Світло в темряві»?",a="Завдання дає Араміс Гаммергенд — служитель Світла, що перебуває в Похоронному Подзвоні на Галявинах Тірісфалю.",al={"видавець","хто починає світло в темряві","завдання араміса гаммергенда"}},{q="Де Западина Нічного Павутиння?",a="Западина Нічного Павутиння — на північний захід від Похоронного Подзвону, серед пагорбів Галявин Тірісфалю.",al={"місце западини нічного павутиння","де обплутані жертви","де печера"}},{q="Чому Відступники не довіряють тим, хто володіє Світлом?",a="Святе Світло пече й небезпечне для плоті нежиті. Чимало Відступників бояться, що кожен, хто володіє святою силою, може побачити в них потвор, яких треба знищити, а не братів, яких треба прийняти.",al={"чому боятися світла","чому відступники ненавидять паладинів","святий страх відступників"}},{q="Хто ці жертви, обплутані павутинням?",a="У коконах — щойно пробуджені шукачі пригод із Відступників, що необачно забрели в павучі печери, ще не встигнувши освоїтися.",al={"хто обплутаний","що всередині павутиння","жертви в пастці"}},{q="Хто такий Екзекутор Аррен і чому Араміс хоче справити на нього враження?",a="Екзекутор Аррен відповідає за військовий і громадський лад у Похоронному Подзвоні. Здобути його довіру вкрай важливо для тих, хто володіє святою силою й хоче безболісно влитися до лав Відступників.",al={"хто такий екзекутор аррен","чому аррен важливий"}},{q="Чи справді нежить може володіти Святим Світлом?",a="Так: завдяки неймовірній силі волі й відданості дехто з нежиті зберігає зв'язок зі Світлом, хоча спрямовувати його нестерпно боляче, а власне суспільство дивиться на таких із підозрою.",al={"чи нежить володіє світлом","переказ про світло нежиті"}}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98397"] = {n="До Дарнасуса",s="«До Дарнасуса» — завершення подорожі друїда нічних ельфів до єднання з Великим Духом Кота. Довівши свою гідність Дендритові Старблейзу в Місячному Гаю, ви повертаєтеся до Ценаріонського Анклаву, щоб опанувати мистецтво перетворення на кота.",h="«До Дарнасуса» — завершення подорожі друїда нічних ельфів до єднання з Великим Духом Кота.",kw={"до дарнасуса","великий дух кота","котяча подоба","дендрит старблейз","матренґіл берволкер","ценаріонський анклав","друїд"},ang={["class:Druid"]="Це завдання знаменує ваш перехід до полювання з тіні: ви отримуєте змогу спрямовувати силу Великого Духа Кота просто через котячу подобу.",["faction:Alliance"]="Друїди Альянсу повертаються з нейтральних земель Місячного Гаю до Дарнасуса й зміцнюють магічний захист своєї батьківщини.",["race:NightElf"]="Повернення до Дарнасуса вшановує традиції нічних ельфів, які Коло Кенарія береже під Світовим Древом Тельдрассилом."},sec={{t="Повернення до Анклаву",b="Поєднавшись із Великим Духом Кота під проводом Дендрита Старблейза в Місячному Гаю, молодий друїд нічних ельфів має повернутися на Тельдрассил. Старблейз визнає, що ви довели себе гідним учнем, і скеровує вас назад до вашого головного наставника — Матренґіла Берволкера, що чекає під гіллям Ценаріонського Анклаву в Дарнасусі."},{t="Природа кота",b="Коли ви прибуваєте до Дарнасуса, Матренґіл Берволкер визнає, що ви увібрали мудрість Великого Духа Кота. На його думку, кожне покоління друїдів проходить випробування, яке визначає ця прадавня сутність — така ж грайлива, як і смертоносна. Тепер, коли зв'язок налагоджено, а дух готовий, Матренґіл передає вам останні обряди, потрібні, щоб прийняти граційну котячу подобу."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує ваше випробування Великим Духом Кота. Коли ви виконаєте доручення Дендрита Старблейза в Місячному Гаю, воно скерує вас назад до Матренґіла Берволкера в Дарнасус, щоб той навчив вас приймати котячу подобу.",al={"навіщо це завдання","мета до дарнасуса","завдання форми кота"}},{q="Хто посилає вас назад до Дарнасуса?",a="Дендрит Старблейз — старший друїд, що мешкає в Нічному Притулку у священному прихистку Місячний Гай, — дає вам це завдання, коли ви отримаєте благословення Великого Духу Кота.",al={"хто починає це завдання","видавець"}},{q="Де знайти Матренґіла Берволкера?",a="Матренґіл Берволкер — у Ценаріонському Анклаві, друїдській святині в північно-західній частині Дарнасуса на Тельдрассилі.",al={"місце матренґіла","де берволкер"}},{q="Що означає Великий Дух Кота?",a="Великий Дух Кота — давній дикий дух природи, що уособлює спритних і смертоносних хижаків. Друїди мусять здобути його прихильність і збагнути його подвійну натуру — грайливість і смертоносність, — перш ніж їм дозволять приймати його подобу.",al={"переказ про духа кота","що таке великий дух кота"}},{q="Чи всі друїди проходять однакове випробування?",a="За словами Матренґіла Берволкера, усі друїди мусять пройти випробування Великого Духу Кота, щоб опанувати його подобу, але саме випробування від покоління до покоління буває різним.",al={"чи випробування друїдів однакові","випробування поколінь"}},{q="Чи можуть узятися за це завдання не нічні ельфи?",a="Саме це завдання — для друїдів-нічних ельфів Альянсу, що повертаються до Дарнасуса. Друїди-таурени мають власний шлях: побувавши в Місячному Гаю, вони доповідають своїм наставникам у Тандер Блафі.",al={"чи це лише для альянсу","чи таурени можуть це"}}},fp="12,246,21.359.0,21.391.0,34.229.0,32.172.0,39.143.0,49.232.0,44.180.0,36.193.0"}
P.entries["quest:984"] = {n="Наскільки велика загроза?",s="«Наскільки велика загроза?» — завдання Альянсу, яке дає Терентіс в Обердайні. Побачивши, як божевілля фурболгів укорінюється на Тельдрассилі, друїд посилає розвідників дослідити місцеві поселення фурболгів на Темному Узбережжі, щоб з'ясувати, чи та сама темна скверна перетнула море.",h="«Наскільки велика загроза?» — завдання Альянсу, яке дає Терентіс в Обердайні.",kw={"наскільки велика загроза","терентіс","фурболги","тельдрассил","амет'аран","обердайн"},ang={["class:Druid"]="Фурболгів пов'язують глибокі узи з природою й давніми духами нетрів, тож їхнє раптове падіння в порчу — тяжка тривога для друїдів, покликаних відновлювати рівновагу Калімдору.",["faction:Alliance"]="Обердайн — головні ворота Альянсу на материкову північ Калімдору, тож захистити його від загроз із нетрів украй важливо для безпеки й постачання краю.",["race:NightElf"]="Для калдореїв бачити, як давні союзники на кшталт фурболгів так скоро після Третьої війни піддаються безглуздій темряві, — і гірка трагедія, і пряма небезпека для священних земель."},sec={{t="Тіні за морем",b="Нічні ельфи півночі Калімдору здавна підтримували приязні чи мирні стосунки з місцевими племенами фурболгів. Та після Третьої війни дивна порча почала затьмарювати розум фурболгів на Тельдрассилі, і це обернулося жорстокими викраденнями й дикими нападами на колишніх союзників. Друїд Терентіс, що перебуває в Обердайні, боїться, що ця зловісна недуга не обмежилася Світовим Деревом, а вже шириться серед материкових племен на імлистих берегах Темного Узбережжя."},{t="Буря, що насувається",b="Розвідка табору фурболгів біля руїн Амет'Арана підтверджує найгірші підозри Терентіса. Тамтешні фурболги виявляють безладну, ворожу агресію й несуть явні ознаки тієї самої порчі, що вразила північ. Через близькість до Обердайна вони вже не мирні сусіди з нетрів, а нагальна загроза для поселення Альянсу."}},faq={{q="Хто такий Терентіс?",a="Терентіс — друїд нічних ельфів у прибережному прихистку Обердайн. Не маючи спокою через розповіді про нічних ельфів, на яких нападали й яких брали в полон навіжені фурболги на Тельдрассилі, він стежить за новими загрозами на Темному Узбережжі й придушує їх.",al={"видавець терентіс","хто дає наскільки велика загроза","терентіс оберіжин"}},{q="Чому фурболги на Темному Узбережжі стають ворожими?",a="Terenthis has seen hints of corruption in Darkshore and suspects the furbolgs may be affected, as some on Teldrassil were. He asks for their camps to be investigated because he has not yet established widespread signs.",al={"чому фурболги ворожі","осквернені фурболги темного узбережжя","осквернення фурболгів"}},{q="Де табір зіпсованих скверною фурболгів?",a="Табір — у глибині суходолу в центрі Темного Узбережжя, трохи на північ від давніх руїн Високородних Амет'Арана й на південний схід від Обердайна.",al={"місце табору","де табір фурболгів","місце загрози"}},{q="Як це пов'язано з подіями на Тельдрассилі?",a="На Тельдрассилі кілька зіпсованих скверною фурболгів викрали й поранили Вартових і мирних нічних ельфів. Терентіс згадує ці недавні рятувальні вилазки, коли намагається з'ясувати, чи не спіткала така сама біда материкове Темне Узбережжя.",al={"зв'язок з тельдрассилом","фурболги тельдрассила","чому терентіс згадує тельдрассил"}},{q="Що буде після доповіді Терентісові?",a="Report any signs of corruption to Terenthis in Auberdine. His response to the findings is revealed when you return.",al={"наступне завдання","що після наскільки велика загроза","продовження завдання"}},{q="Чому нічних ельфів так непокоять табори фурболгів біля Обердайна?",a="Обердайн — головний порт Альянсу й життєво важливий шлях постачання на материку. Глибоко зіпсовані скверною ворожі племена, що оселилися на відстані удару, роблять торговельні шляхи, розвідувальні загони й саме містечко вразливими до раптових нападів.",al={"загроза оберіжину","чому турбують фурболги"}}},fp="17,284,22.502.0,17.381.1,17.245.0,50.218.0,42.141.0,45.214.0,47.115.0,68.246.0"}
P.entries["quest:98407"] = {n="Демонстрація сили",s="Демонстрація сили — оборонне завдання Альянсу в Горах Редріджу від Помічника Фелдона. Щоб зупинити зграї гнолів, які підступають до Лейкширу, шукачів пригод посилають полювати на гнолів-трощителів і збирати їхні нашийники з шипами — щоб відбити гнолам охоту вдиратися в людські поселення.",h="Демонстрація сили — оборонне завдання Альянсу в Горах Редріджу від Помічника Фелдона.",kw={"демонстрація сили","помічник фелдон","гноли","нашийники з шипами","лейкшир","редрідж"},ang={["class:Warrior"]="Гноли поступаються лише прямому, нищівному насильству, тож чесна дисципліна передової — найкращий спосіб зламати їхні лави.",["faction:Alliance"]="Лейкшир — один із найсхідніших бастіонів Альянсу на півдні Східних Королівств; захистити його кордони від навали звіролюдей вкрай важливо для спокою всього краю.",["race:Human"]="Хуторяни й містяни Редріджу — такі самі піддані Стормвінда, залишені небезпечно беззахисними; вони покладаються на одноплемінників, щоб відбити диких мародерів."},sec={{t="Зухвалий наступ",b="Гори Редріджу здавна були прихистком диких племен гнолів, але останнім часом вони дедалі зухвалішають. Замість того щоб сидіти високо в скелястих пагорбах, ватаги гнолів-грабіжників отаборилися тривожно близько до Лейкширу й віддалених людських хуторів. Військо Стормвінда розпорошене й не може виділити підкріплення для сільського прикордоння, тож місцева влада мусить покладатися на мандрівних шукачів пригод, щоб захистити околиці, перш ніж ці ватаги наберуться духу вдарити по самому містечку."},{t="Говорити їхньою мовою",b="Помічник Фелдон розуміє, що гноли — жорстокі, неорганізовані створіння, які поважають лише грубу силу. Щоб загнати їх назад у глушину, дипломатичні заклики чи напівзаходи марні. Фелдон хоче вдарити по їхньому найлютішому авангарду — гнолах-трощителях — і забрати їхні нашийники з шипами як похмурий доказ переваги. Розбивши їхніх передових бійців і виставивши напоказ трофеї їхньої поразки, захисники Лейкширу сподіваються залякати решту зграй і змусити їх відступити назад у високогір'я."}},faq={{q="Хто дає це завдання і де він?",a="Завдання дає Помічник Фелдон — міський вартовий, що стоїть на околиці біля Лейкшира в Горах Редріджу.",al={"хто дає завдання","місце помічника фелдона","видавець демонстрації сили"}},{q="Чому гноли підступають так близько до Лейкшира?",a="Гноли — агресивні пристосуванці, що раз у раз перевіряють межі дозволеного. Лейкширу бракує оборонців, а військової допомоги від Стормвінда — обмаль, тож гноли так осміліли, що влаштовують мисливські табори просто під землями, заселеними людьми.",al={"чому гноли так близько","чому гноли нападають","загроза гнолів реджридж"}},{q="Яких ворогів треба здолати в цьому дорученні?",a="Ціль — гноли-трощителі, найнебезпечніші й найагресивніші ударні бійці місцевих зграй, що носять важкі шипасті нашийники.",al={"які гноли","яких мобів убивати","гноли-побивачі"}},{q="Чому Помічникові Фелдону потрібні саме шипасті нашийники?",a="У гнолів панує жорстока ієрархія й сила. Забрати шипасті нашийники їхніх трощителів — пряма демонстрація сили, яка має налякати вцілілих гнолів і змусити їх відступити назад у пагорби.",al={"чому шипасті нашийники","призначення нашийників","навіщо забирати нашийники"}},{q="Чи може Стормвінд прислати солдатів, щоб упоратися з гнолами?",a="Стормвінд здебільшого полишив Редрідж боронитися самотужки. Серед внутрішньої непевності й браку військ по всьому королівству столиця майже не надсилає підкріплень, тож місцеві помічники мусять покладатися на незалежних звитяжців.",al={"допомога стормвінда реджриджу","чому немає армії стормвінда","де вартові"}},{q="Де в Редріджі зазвичай таборують гноли?",a="Табори гнолів розкидані по пагорбах і невисоких хребтах довкола Озера Незрушного та вздовж доріг, що ведуть на схід до Кам'яної Варти.",al={"табори гнолів","де знайти гнолів","місця гнолів реджридж"}}},fp="13,284,19.520.0,23.530.0,49.120.0,49.244.0,50.136.0,56.214.0,55.228.0,52.149.0"}
P.entries["quest:985"] = {n="Наскільки велика загроза?",s="«Наскільки велика загроза?» — завдання Альянсу, яке дає нічний ельф Терентіс в Обердайні. Після розвідки ворожого табору фурболгів Чорнолісся на південь від містечка шукачів пригод посилають знищити зіпсованих слідопитів і вітромовців, перш ніж їхній шал загрожуватиме поселенню.",h="«Наскільки велика загроза?» — завдання Альянсу, яке дає нічний ельф Терентіс в Обердайні.",kw={"наскільки велика загроза","терентіс","фурболги чорнолісся","похмурий кіготь","мох скверни","обердайн"},ang={["class:Druid"]="Друїди гостро відчувають цю трагедію, бо біда фурболгів віддзеркалює безупинні страждання лісу під порчею моху Скверни.",["faction:Alliance"]="Обердайн — важливий портовий оплот Альянсу на Темному Узбережжі, тож знищення ворожих таборів поблизу украй важливе для безпеки краю.",["race:NightElf"]="Для нічних ельфів проріджувати Чорнолісся — гірке горе: століття спорідненості з фурболгами розбила демонічна пошесть, що лишилася після Третьої війни."},sec={{t="Необхідне проріджування",b="Після першої розвідки на південь від Обердайна Вартові дійшли висновку, що фурболги Чорнолісся становлять пряму загрозу для біженців і захисників Темного Узбережжя. Терентіс доручає мандрівникам, здатним до бою, вдарити просто по їхньому табору й знищити слідопитів і вітромовців Чорнолісся, щоб зламати їхній наступальний порив."},{t="Трагедія зіпсованих",b="Нічні ельфи здавна вважають фурболгів духовною ріднею й давніми союзниками в нетрях. Та злоякісне поширення моху Скверни й демонічної порчі на півночі Калімдору звело плем'я Чорнолісся з розуму. Ліків, що повернули б фурболгам розум, не знають, тож захисники Обердайна вважають насильство похмурою необхідністю, щоб уберегти невинних від загибелі."},{t="Прихід Похмурого кігтя",b="Коли мандрівник доповідає Терентісові про виконане, до Обердайна вбігає білий ведмідь на ім'я Похмурий кіготь і мчить до нічного ельфа. Його поява віщує нагальні новини про звірів і порчу, що спустошують узбережжя, і запускає наступний етап оборони Обердайна."}},faq={{q="Чому Терентіс хоче знищити фурболгів Чорнолісся?",a="Плем'я Чорнолісся на південь від Обердайна піддалося скверні й стало жорстоким і нерозсудливим. Їхній табір прямо загрожує поселенню, а ліків від їхньої скверни поки не знайдено, тож Терентіс наказує завдати випереджального удару, щоб уберегти Обердайн.",al={"чому вбивати фурболгів чорнолісся","причина винищення фурболгів","завдання терентіса про фурболгів"}},{q="Де табір фурболгів Чорнолісся?",a="Табір — трохи на південь від Обердайна, у прибережному лісі Темного Узбережжя, серед зіпсованих скверною дерев, де зібралося плем'я Чорнолісся.",al={"місце фурболгів чорнолісся","де слідопити й вітрогуди","табір фурболгів темне узбережжя"}},{q="Хто такий Похмурий кіготь?",a="Похмурий кіготь — білий ведмідь, пов'язаний із розслідуваннями в нетрях Темного Узбережжя.",al={"білий ведмідь оберіжин","похмурий кіготь ведмідь"}},{q="Що доводить фурболгів до божевілля?",a="Фурболгів отруїли мох Скверни й рештки демонічної скверни, що лишилися після Третьої війни. Темна енергія, яка спустошує Темне Узбережжя, спотворює і розум, і тіло, доводячи мирні племена до некерованої агресії.",al={"чому фурболги шаленіють","осквернення фурболгів темного узбережжя","що осквернило чорноліссе"}},{q="Чому нічним ельфам так не хочеться вбивати фурболгів?",a="Фурболгів і нічних ельфів тисячі років єднали дружба й шанування природи. Вбивати їх для нічних ельфів — усе одно що різати власних братів із дикого лісу, але скверна не лишає іншого вибору.",al={"нічні ельфи й фурболги","чому оплакувати фурболгів"}},{q="Чим різняться перше й друге завдання «Наскільки велика загроза?»?",a="Перше завдання перевіряє вміння розвідувати: вам треба знайти табір Чорнолісся й спостерігати за ним. Друге — пряме бойове доручення: коли загрозу підтверджено, треба проредити слідопитів і вітромовців табору.",al={"частини наскільки велика загроза","різниця між завданнями"}}},fp="17,277,16.332.0,24.358.0,18.281.1,54.277.0,44.150.0,16.84.1,39.227.0,47.250.0,79.225.0"}
P.entries["quest:98576"] = {n="Гліфічний Пергамент",s="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань. Передане через Ґорнека, письмове послання веде новачків до Май'ї, наставниці магів-тролів біля Лігва, щоб розпочати їхню дисципліну в таємній магії.",h="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань.",kw={"маг","май'а","гліфічний пергамент","долина випробувань","таємна магія","ґорнек"},ang={["class:Mage"]="Це послання знаменує ваше офіційне визнання учнем таємної магії й скеровує вас до Май'ї, щоб почати вчитися й розширювати свою книгу заклинань.",["faction:Horde"]="Наставництво в Долині Випробувань дбає, щоб навіть такі мінливі мистецтва, як таємна магія, плекалися з дисципліною на зміцнення майбутнього Орди.",["race:Troll"]="Май'а втілює дедалі міцніші традиції таємної магії Темного Списа: вона ділиться своїм космічним знанням, щоб вести і тролів-одноплемінників, і новобранців-союзників."},sec={{t="Виклик до навчання",b="Поки нові новобранці доводять свою тілесну стійкість у сутичках із тутешніми шкідниками Дуротару, ті, хто має хист до таємної магії, не можуть покладатися лише на грубу силу. Ґорнек передає письмове повідомлення, списане рунами, яке велить чарівникам-початківцям розшукати Май'ю — вона наглядає за першим магічним навчанням найновіших новобранців Орди."},{t="Шлях таємної магії",b="Стоячи одразу біля входу до Лігва, Май'а стримує амбіції молодих чарівників. Замість безоглядно жбурляти сире чаклунство, вона наголошує на терпінні, вчасності й виваженому розумі. Під її проводом новачки вчаться бачити всесвіт як тонкі нитки, які треба ткати, а не як буремну стихію, яку треба спустити з ланцюга."}},faq={{q="Хто надсилає Гліфічний Пергамент?",a="Пергамент надсилає Май'а — наставниця магів, що стоїть біля Лігва в Долині Випробувань. Лист у Ґорнека, і він віддає його, щойно молодий маг починає свої випробування.",al={"хто писав гліфічний пергамент","хто надіслав","автор пергаменту"}},{q="Де знайти Май'а?",a="Май'а — у Долині Випробувань у Дуротарі, просто біля входу в Лігво, разом з іншими класовими наставниками.",al={"де май'а","місце май'а","знайти май'а"}},{q="Навіщо це завдання?",a="Воно знайомить молодих магів з їхньою класовою наставницею. Розмова з Май'а починає ваше справжнє навчання тайних мистецтв і відкриває доступ до нових заклять і основ вишколу.",al={"що робить гліфічний пергамент","навіщо це завдання","мета завдання"}},{q="Як Май'а дивиться на магію?",a="Май'а вчить, що тайна магія вимагає розуму, стриманості й виваженого терпіння. Справжній маг не діє зопалу, а уважно спостерігає й завдає удару в точно вибрану мить, відповідаючи так, як годиться.",al={"чого вчить май'а","переказ про май'а"}},{q="Чому в Долині Випробувань магів навчає троль?",a="Долина Випробувань приймає і молодих орків, і тролів Темного Спису, що вступають до лав Орди. Заклиначі Темного Спису на кшталт Май'а діляться мудрістю й майстерністю володіння космічними силами, навчаючи новачків.",al={"чому троль-маг","тролі й аркана","наставник-троль у землях орків"}},{q="Хто передає пергамент гравцеві?",a="Ґорнек — головний наглядач випробувань у центральному таборі Долини Випробувань — передає пергамент, коли ви повертаєтеся до нього під час перших доручень.",al={"хто дає гліфічний пергамент","завдання ґорнека"}}},fp="17,250,18.345.0,21.326.0,32.183.0,26.132.0,34.186.0,37.221.0,54.209.0,41.159.0"}
P.entries["quest:986"] = {n="Зниклий господар",s="«Зниклий господар» доручає шукачеві пригод Альянсу зібрати матеріали для пошуків Волкора — нічного ельфа, що зник у нетрях Темного Узбережжя. Терентіс в Обердайні пропонує виткати зачарований маскувальний плащ, щоб захистити рятівника, але для цього потрібні шкури найлютіших місячних скрадачів узбережжя.",h="«Зниклий господар» доручає шукачеві пригод Альянсу зібрати матеріали для пошуків Волкора — нічного ельфа, що...",kw={"зниклий господар","волкор","терентіс","похмурий кіготь","шкура місячного хижака","місячні скрадачі"},ang={["class:Druid"]="Друїди оцінять шану Терентіса до природної потайності місячних скрадачів: їхню дику сутність він обертає на захисне маскування.",["class:Hunter"]="Мисливці впізнають зв'язок між Волкором і Похмурим кігтем, а також майстерність, потрібну, щоб вистежити й вполювати матріархів і вожаків Темного Узбережжя.",["race:NightElf"]="Пошуки Волкора відбивають обов'язок нічних ельфів берегти своїх родичів і диких супутників у неприборканих куточках Темного Узбережжя."},sec={{t="Пошуки в нетрях",b="Стежачи за загрозами на берегах Темного Узбережжя, Терентіс в Обердайні непокоїться за долю Волкора та його товариша — Похмурого кігтя. Південні околиці краю славляться небезпекою через агресивних хижаків і зіпсованих звірів. Замість посилати розвідника без захисту Терентіс вигадує план: виткати захисний плащ, сповнений чарів дикої ілюзії."},{t="Шкури зграї",b="Щоб виткати плащ, здатний збити з пантелику звірів Темного Узбережжя, звичайних шкур не досить. Терентісові потрібні вишукані шкури, здобуті саме зі старих вожаків чи матріархів місячних скрадачів. Ці грізні великі коти нишпорять лісами на південь від Обердайна біля Річки Дикого Закруту й аж до лісистого кордону з Ашенвалем."},{t="Делікатна магія",b="Готове вбрання з хутра місячних скрадачів і чарів природи дає власникові змогу безперешкодно проходити ворожими землями, шукаючи Волкора. Проте Терентіс попереджає, що ілюзія крихка: будь-яке важке зусилля чи бій розвіюють чари й лишають шукача беззахисним."}},faq={{q="Хто такий Волкор?",a="Волкор — нічний ельф, розвідник чи слідопит, що зник у нетрях на півдні Темного Узбережжя. Його супутник Похмурий кіготь і Терентіс в Обердайні шукають, де він, — так і починаються пошуки.",al={"хто такий волкор","переказ про волкора","зниклий господар волкор"}},{q="Хто дає це доручення?",a="Терентіс — нічний ельф з Обердайна на Темному Узбережжі — дає завдання, після того як шукачі пригод допоможуть йому з попередніми місцевими клопотами.",al={"видавець завдання","де взяти зниклого господаря","місце терентіса"}},{q="Де водяться вожаки й матріархині місячних скрадачів?",a="Ці дорослі місячні скрадачі никають півднем Темного Узбережжя, особливо біля берегів Річки Дикого Закруту й далі на південь, ближче до межі з Ашенвалем.",al={"місця шкур місячних скрадачів","де місячні скрадачі","коти вайлдбенд"}},{q="Навіщо потрібен плащ?",a="Терентіс хоче зробити зачарований плащ, що ховає власника від ворожих звірів Темного Узбережжя, — так можна буде шукати Волкора, не наражаючись раз у раз на напади.",al={"що робить плащ","плащ терентіса","зачарування плаща"}},{q="Чому Терентісові потрібні саме ці шкури?",a="Звичайні шкури не мають сили й природної потуги, щоб утримати маскувальні чари. Витримати зачарування можуть лише товсті, міцні шкури вожаків і матріархинь.",al={"чому вожаки й матріархині","чому саме ці шкури"}},{q="Чи має маскувальний плащ обмеження?",a="Так. Терентіс попереджає, що чари крихкі. Говорити з іншими можна, але різкі дії чи бій швидко розвіють ілюзію.",al={"чи плащ має обмеження","чи ілюзія зникає"}}},fp="13,298,23.399.0,18.341.0,14.304.0,14.185.0,21.154.0,49.157.0,30.179.0,39.181.0,43.157.0"}
P.entries["quest:98601"] = {n="Важкий шлях",s="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні. Упоравшись із безтямною нежиттю, що повстає зі склепів, щойно пробуджені поборники Світла отримують наказ з'явитися до Араміса Гаммергенда в сільській церкві, щоб зіткнутися з болісною дійсністю володіння святою енергією в нежитті.",h="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні.",kw={"важкий шлях","араміс гаммергенд","паладин","освячений сувій","сарвіс","горнило"},ang={["class:Paladin"]="Це завдання — засадниче випробування паладина Відступників: свята сила тут не легке благословення, а болісне горнило дисципліни й витривалості.",["race:Undead"]="Для Відступників звернення до Світла доводить, що відданість і дисципліна здатні пережити фізичну смерть, навіть якщо магія діяльно спалює посудину, яка її спрямовує."},sec={{t="Смердючий сувій",b="Коли щойно пробуджений паладин Відступників закінчує винищувати здичавілу нежить біля склепу, Жрець Тіні Сарвіс вручає несподівану посилку. Освячений Сувій випромінює святу енергію так потужно, що жрець тіні помітно сахається й прямо просить носія відійти. Для адепта тіні й тління сама аура Святого Світла — як відкритий вогонь."},{t="Горнило святого вогню",b="В оскверненій церкві Похоронного Подзвону чекає Араміс Гаммергенд, наставник паладинів Відступників. Там, де інші раси володіють Світлом природно й радісно, нежить, що звертається до нього, зазнає пекучих, нутряних мук. Араміс не пом'якшує удару: спрямовувати святу силу крізь гниючу посудину — чиста мука, та він вимагає, щоб його учні приймали біль, а не сахалися від нього, і використовували його як горнило, що гартує їхню новознайдену рішучість."}},faq={{q="Чому Жерцеві Тіні Сарвісу не подобається сувій?",a="Жрець Тіні Сарвіс відданий магії тіні й дбає про своїх братів-нежить. Освячений Сувій випромінює чисту святу енергію, яка від природи ворожа плоті нежиті й глибоко непокоїть тих, хто служить Тіні.",al={"чому сарвіс не любить сувій","святий сувій сарвіса","реакція жреця тіні на сувій"}},{q="Чи можуть Відступники справді володіти Святим Світлом і не гинути?",a="Відступники можуть володіти Світлом завдяки самій лише силі волі й вірі, але це завдає їм пекучого болю всередині й знову розпалює мертві нервові закінчення, тож вони відчувають власне тління. Щоб спрямовувати Світло, потрібна величезна душевна витривалість.",al={"переказ про паладинів відступників","нежить і світло","чи світло шкодить відступникам"}},{q="Хто такий Араміс Гаммергенд?",a="Араміс Гаммергенд — наставник паладинів у каплиці Похоронного Подзвону. Він веде щойно піднятих паладинів із Відступників, навчаючи їх витримувати муки, яких завдає Світло нежиті, і кувати з нього дієву зброю.",al={"хто такий араміс гаммергенд","наставник паладинів похоронного подзвону","роль араміса"}},{q="Де відбувається це завдання?",a="Завдання починається в Жерця Тіні Сарвіса на центральній галявині Похоронного Подзвону й закінчується за кілька кроків, у зруйнованій сільській каплиці, де перебуває Араміс Гаммергенд.",al={"де важкий шлях","місце завдання","де церква похоронного подзвону"}},{q="Чи треба читати Освячений Сувій, щоб виконати завдання?",a="Ні, читати сувій не обов'язково: ваше навчання просунеться, щойно ви поговорите з Арамісом Гаммергендом у церкві.",al={"читати освячений сувій","чи обов'язково читати сувій","пропустити читання сувою"}},{q="Чому шлях називають «важким»?",a="Ця назва відбиває суворий шлях паладина з Відступників. Інші воїни Світла знаходять у вірі розраду й утіху, а паладин-нежить мусить терпіти пекучий святий вогонь, що струменить мертвою плоттю щоразу, як він благословляє чи завдає удару.",al={"чому важкий шлях","значення назви"}}},fp="16,322,16.384.0,25.449.0,49.238.0,54.230.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:99"] = {n="Безумство Аруґала",s="«Безумство Аруґала» досягає вершини в небезпечному розслідуванні прокляття, що тримає Село Пайрвуд. Далар Донвівер доручає агентам Орди здобути зачаровані кайдани з селян, щоб розгадати викривлену роботу Архімага Аруґала. Розплутування цих пут відкриває трагічну магію, що тримає поселення в тіні воргенів.",h="«Безумство Аруґала» досягає вершини в небезпечному розслідуванні прокляття, що тримає Село Пайрвуд.",kw={"безумство аруґала","село пайрвуд","кайдани пайрвуда","далар донвівер","воргени","мунрейдж","прокляття"},ang={["class:Mage"]="Для знавців чарівної магії Аруґалові кайдани — похмуре нагадування про те, як чаклунство Кірін-Тору може скотитися в божевілля, коли змішується з викликаними потойбічними звірами.",["faction:Horde"]="Здобувши ці кайдани, ви ламаєте містичну хватку Аруґала над дорогою, що веде на південь, до Стіни Ґреймейна.",["race:Undead"]="Відступники дивляться на Село Пайрвуд з холодною зацікавленістю й безжальним прагматизмом і прагнуть розібрати Аруґалові чари, щоб убезпечити південне Срібнолісся."},sec={{t="Подвійне життя Пайрвуда",b="На південь від Гробниці лежить Село Пайрвуд — поселення, що застрягло в моторошному стані. За денного сонця його мешканці живуть як звичайні людські селяни — полохливі й відлюдні. Та щойно на ліс спадають сутінки, їхні людські тіла розриваються, і вони обертаються на диких воргенів Мунрейдж, що блукають вулицями під владою Аруґала. Далар Донвівер прагне розгадати чарівні пута, що спричиняють цей щодобовий жах."},{t="Розбити кайдани",b="Щоб дослідити чари, які тримають Пайрвуд у неволі, Донвіверу потрібні зачаровані Кайдани Пайрвуда, зняті просто з перетворених селян. Це не просто залізо: ці пута гудуть залишковим чаклунством невдалих Аруґалових захисних чарів. Вивчаючи їхню чарівну будову, маг-Відступник сподівається збагнути механізми звірячого перетворення й знайти спосіб нарешті повалити архімага-ренегата з Фортеці Шадовфенг."}},faq={{q="Чому мешканці Села Пайрвуд уночі перетворюються на воргенів?",a="Архімаг Аруґал наклав на Село Пайрвуд спотворені чари. Удень його закляття підтримують ілюзію людської подоби чи приспаний людський стан, а з настанням ночі селяни перетворюються на воргенів Мунрейджів, підвладних йому.",al={"пайрвуд день ніч","прокляття пайрвуда","чому людина а потім вовк"}},{q="Що таке Кайдани Пайрвуда?",a="Це зачаровані пута, які носять прокляті мешканці Села Пайрвуд. Аруґал використовував їх у своїх чарах над селом, а Далар Донвівер вивчає прокляття за їхньою залишковою енергією.",al={"кайдани пайрвуда","кайдани аруґала"}},{q="Хто такий Далар Донвівер?",a="Далар Донвівер — маг із Відступників у Гробниці в Срібноліссі. Він очолює магічне розслідування Відступників щодо воргенів, яких закликав Архімаг Аруґал.",al={"далар донвівер","хто видавець гробниці"}},{q="Чи зцілює це завдання Село Пайрвуд?",a="Ні. Здобуті кайдани дають Даларові Донвіверу змогу зрозуміти Аруґалову магію, але прокляття й далі тримає Пайрвуд у нескінченних муках.",al={"чи можна вилікувати пайрвуд","чи зцілять людей пайрвуда"}},{q="Як Аруґал керує селянами?",a="Безрозсудними чарами й зачарованими кайданами Аруґал підкорив селян своїй волі, змусивши їх набути звірячої подоби й стерегти підступи до його володінь у Фортеці Шадовфенг.",al={"аруґал і пайрвуд","як аруґал керує ними"}},{q="Що буде після ланцюжка «Безумство Аруґала»?",a="Це доручення — останній розділ ланцюжка «Безумство Аруґала». Зібрані знання дають Відступникам змогу повністю оцінити загрозу Фортеці Шадовфенг і спланувати падіння Аруґала.",al={"після безумства аруґала","фінал безумства аруґала"}}},fp="14,342,26.434.0,23.448.1,64.222.0,31.198.0,24.175.0,48.176.1,38.183.0,61.185.1"}
P.entries["quest:990"] = {n="Похід до Ашенвалю",s="«Похід до Ашенвалю» — завдання-мандрівка для Альянсу, що посилає досвідчених шукачів пригод на південь із Темного Узбережжя в первісні ліси Ашенвалю. Вартова Селарін, що прибула до Обердайна по допомогу, посилає мандрівників доповісти Рейн Вульфраннер у містечку Астранаар, де вартові борються з порчею, що ширшає.",h="«Похід до Ашенвалю» — завдання-мандрівка для Альянсу, що посилає досвідчених шукачів пригод на південь із...",kw={"похід до ашенвалю","вартова селарін","обердайн","рейн вульфраннер","астранаар","завдання"},ang={["faction:Alliance"]="Як звитяжець Альянсу, відгукнувшись на заклик Астранаару, ви зміцнюєте зв'язки з нічними ельфами й головну опору свого союзу на півночі Калімдору.",["race:NightElf"]="Для нічних ельфів ця мандрівка — повернення в священне серце Калімдору: ви відгукуєтеся на заклик своїх сестер захистити прадавні святі землі від протиприродної гнилі."},sec={{t="Прощання з узбережжям",b="Відгукнувшись на заклик Вартової Селарін в Обердайні, мандрівники залишають позаду похмурі сірі пляжі й затінені руїни узбережжя. Вартова впізнає вправних бійців і розвідників, здатних постояти за себе, і посилає їх просто в серце лісових земель нічних ельфів. Із місцевими загрозами Темного Узбережжя покінчено, тож увага звертається до значно більших небезпек, що насуваються з півдня."},{t="Дорога до Астранаару",b="Шлях на південь пролягає прадавньою дорогою нічних ельфів, що в'ється крізь густі прадавні крони Ашенвалю. Рейн Вульфраннер, ватажок вартових в Астранаарі, терміново кличе підкріплення. Демонічна скверна, шалені звірі й вторгнення чужинців на родові землі — вартові в Астранаарі розпорошені до краю й потребують допомоги ззовні, щоб утримати священний ліс."}},faq={{q="Хто посилає вас у цей похід?",a="Вартова Селарін — нічна ельфійка, яку Рейн Вульфраннер послала до Обердайна по допомогу, — скеровує вас на південь, до Астранаару.",al={"видавець","хто починає похід до ашенвалю","селарін"}},{q="Хто така Рейн Вульфраннер?",a="Рейн Вульфраннер — очільниця Вартових в Астранаарі, що організовує оборону Ашенвалю й спрямовує зусилля, щоб зупинити скверну, яка вражає ліс.",al={"рейн","вульфраннер","керівниця астранаара"}},{q="Чому шукачів пригод посилають до Ашенвалю?",a="Прадавні ліси Ашенвалю піддаються скверні, що поширюється, і дедалі більшим загрозам ззовні. Місцеві Вартові нічних ельфів не дають ради й нагально потребують вправних союзників, які допомогли б мешканцям і захисникам Астранаару.",al={"чому ашенваль","що відбувається в ашенвалі","осквернення ашенвалю"}},{q="Чи безпечна дорога між Темним Узбережжям і Ашенвалем?",a="Вартова Селарін окремо радить триматися дороги. Хто зійде зі стежки в лісову гущавину, наразиться на агресивних хижаків, сатирів і ворожі сили, що никають дикими прикордонними землями.",al={"безпека дороги","чи безпечна дорога до ашенвалю"}},{q="Що робити, коли я дістануся Астранаару?",a="Коли ви доповісте Рейн Вульфраннер, вона порадить поговорити з іншими мешканцями й захисниками Астранаару, адже багатьом із них потрібна негайна допомога з місцевими бідами.",al={"що робити в астранаарі","прибуття до астранаара"}},{q="Для якого рівня шукачів пригод це призначено?",a="Зазвичай ця подорож знаменує завершення пригод на Темному Узбережжі десь на 19 рівні й переводить шукачів пригод середнього рівня на ширше й запекліше спірне прикордоння Ашенвалю.",al={"який рівень","вимога рівня"}}},fp="17,339,17.409.0,21.425.0,27.126.0,24.193.0,44.232.0,49.209.0,44.192.0,46.171.0"}
P.entries["quest:991"] = {n="Очищення Рейн",s="«Очищення Рейн» починається, коли Рейн Вульфраннер просить шукача пригод розшукати її зниклого друга Тероніса. Шукаючи спосіб зупинити шалену агресію фурболгів по всьому Ашенвалю, Тероніс вирушив до Озера Фалатім, щоб здобути чарівний самоцвіт.",h="«Очищення Рейн» починається, коли Рейн Вульфраннер просить шукача пригод розшукати її зниклого друга Тероніса.",kw={"очищення рейн","рейн вульфраннер","тероніс","озеро фалатім","мурлоки","завдання"},ang={["faction:Alliance"]="Новобранці Альянсу, що прибувають до Астранаару, швидко дізнаються: священні гаї Ашенвалю в облозі ворожих диких звірів, фурболгів і загарбників-мурлоків.",["race:NightElf"]="Зникнення Тероніса — ще один гіркий удар для нічних ельфів, чиї сили й так розпорошені на зцілення Ашенвалю й захист святилищ від порчі."},sec={{t="Тривога за друга",b="Рейн Вульфраннер служить разом із вартовими в Астранаарі, боронячи Ашенваль від дедалі більших загроз. Одним із її найближчих товаришів був Тероніс, який сам узявся знайти могутній захист від дедалі жорстокіших племен фурболгів. Коли минали дні, а він не повертався, Рейн дуже стривожилася: вона не могла покинути свій пост, але боялася найгіршого."},{t="Пошуки жезла",b="Тероніс ішов за чутками про могутній жезл, викуваний покійним лихим чарівником, вірячи, що його магія може вгамувати лють фурболгів. Щоб відновити артефакт, йому був потрібен зачарований самоцвіт, схований в ельфійському святилищі на Озері Фалатім, біля гір на заході. На лихо, тихі води нещодавно захопили агресивні племена мурлоків."},{t="Трагедія на Озері Фалатім",b="Слід Тероніса до острова посеред Озера Фалатім відкриває похмуре видовище. Тероніс так і не вибрався з вод живим: його тіло лежить у святилищі, вкрите глибокими ранами від мурлоцької зброї та пазурів, — передчасний кінець його пошуків."}},faq={{q="Хто така Рейн Вульфраннер?",a="Рейн Вульфраннер — нічна ельфійка, союзниця Вартових Ашенвалю, що перебуває в Астранаарі. Вона керує обороною лісу від ворогів, що наступають.",al={"хто така рейн","рейн вульфраннер","видавець"}},{q="Хто такий Тероніс?",a="Тероніс був близьким другом Рейн Вульфраннер і шукав давніх магічних способів урятувати ліс. Вірячи, що зачарований жезл може заспокоїти зіпсованих скверною фурболгів, він сам вирушив здобувати складники для нього.",al={"хто такий тероніс","історія тероніса","зниклий друг"}},{q="Де зник Тероніс?",a="Тероніс зник біля Озера Фалатім — водойми біля підніжжя західних гір Ашенвалю, яку заполонили ворожі мурлоки.",al={"де тероніс","місце тероніса","озеро фалатім"}},{q="Навіщо Тероніс шукав самоцвіт?",a="Самоцвіт був необхідним складником, щоб наснажити магічний жезл, створений покійним лихим чарівником. Тероніс сподівався використати силу жезла, щоб зупинити напади розлючених фурболгів.",al={"який самоцвіт","навіщо самоцвіт","самоцвіт тероніса"}},{q="Що сталося з Теронісом?",a="Рейн не має від нього звісток відтоді, як він подався до Озера Фалатім. Ідучи його слідом, ви дізнаєтеся, що з ним сталося.",al={"як помер тероніс","хто вбив тероніса","убивця тероніса"}},{q="Чому фурболги нападають в Ашенвалі?",a="Фурболги Ашенвалю після Третьої війни піддалися демонічній скверні й шаленству, і колись мирні племена невпинно й жорстоко нападають на своїх давніх союзників.",al={"напади фурболгів","чому фурболги агресивні","божевілля фурболгів"}}},fp="17,245,18.364.0,21.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99134"] = {n="Послух",s="Послух — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю. Невдоволений вправністю місцевого гарнізону Вартових Смерті, Зиґанд наймає сторонніх шукачів пригод, щоб ті фізично покарали розледачілих вартових-нежить.",h="Послух — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю.",kw={"послух","зиґанд","дисципліна","вартові смерті","спонукач екзекутора","покарання"},ang={["faction:Horde"]="Похмурі методи командирів Відступників показують сувору, безжальну дійсність життя й управління в північних володіннях Орди.",["race:Undead"]="Для Відступників військова дисципліна — питання виживання виду. Вартові, що піддаються апатії, наражають на небезпеку всю територію Галявин Тірісфалю."},sec={{t="Порядок у нежитті",b="Вартові Смерті — військовий хребет Відступників по всьому Лордерону, та свобода від залізної волі Короля-Ліча приносить власні ускладнення: апатію, втому й недбалість. Наглядачі на кшталт Екзекутора Зиґанда не терплять послаблення дисципліни, надто коли Багряний Хрестовий Похід і Погибель нишпорять кордонами Тірісфалю. Щоб тримати війська в тонусі, офіцери покладаються на тупі знаряддя й жорсткий нагляд заради бойової готовності."},{t="Реєстр Екзекутора",b="Екзекутор Зиґанд навмисно залучає до покарань незалежних виконавців, а не бійців із самого гарнізону. За допомогою Спонукача Екзекутора сторонні нагадують недбалим Вартовим Смерті, що виживання на службі Темній Леді вимагає цілковитої пильності. Ті, хто нехтує обов'язками, швидко засвоюють: нежиття не дає прихистку від наслідків."}},faq={{q="Хто дає завдання «Послух»?",a="Завдання «Послух» дає Екзекутор Зиґанд — вимогливий офіцер Відступників на Галявинах Тірісфалю, що відповідає за оборону краю й вимагає від своїх військ суворого послуху.",al={"хто дає послух","видавець послуху","завдання екзекутора зиґанда"}},{q="Чому Екзекутор Зиґанд хоче покарати Вартових Смерті?",a="Зиґанд вважає підлеглих йому Вартових Смерті нездарами, яким бракує завзяття. Безтурботність загрожує виживанню Відступників у Тірісфалі, тож він запроваджує сувору дисципліну, щоб струснути вартових і змусити їх пильнувати.",al={"чому бити вартових смерті","чому мотивувати вартових смерті","причина зиґанда"}},{q="Чому Зиґанд доручає це шукачеві пригод, а не іншому солдатові?",a="Зиґанд зауважує, що ви, чужинець, який ще не належить до Вартових Смерті, поки не встигли його розчарувати.",al={"чому я","чому зиґанд наймає сторонніх"}},{q="Що таке Спонукач Екзекутора?",a="Спонукач Екзекутора — каральне знаряддя, яке видає Екзекутор Зиґанд. Ним боляче нагадують про обов'язок Вартовим Смерті, що байдикують на постах по Галявинах Тірісфалю.",al={"спонукач екзекутора","що таке спонукач"}},{q="Що буде, якщо відмовитися виконати наказ Зиґанда?",a="Зиґанд попереджає: за вагання чи відмову ваше ім'я потрапить до його книги, і наступного разу дисциплінувати когось пошлють уже по вас.",al={"погрози зиґанда","загроза облікової книги"}},{q="Як Відступники ставляться до болю?",a="Зиґанд зараховує біль до тих небагатьох утіх, які ще лишилися йому по смерті. Його захоплення покараннями відбиває його власну сувору вдачу.",al={"чи нежить відчуває біль","біль відступників"}}},fp="10,234,26.467.0,21.367.0,31.174.0,54.215.0,61.123.0,33.183.0,42.162.0,30.139.0"}
P.entries["quest:99141"] = {n="Терпіння",s="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності заради Темної Леді. Оскільки чергові польові донесення запізнюються, Зиґанд відряджає шукача пригод зібрати звіти від сусідніх Вартових Смерті та одного незвичайного вартового. Доручення підкреслює сувору, безкомпромісну дисципліну, яку насаджують по всіх володіннях Відступників.",h="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності...",kw={"терпіння","зиґанд","донесення","діллінджер","крістоф","ґордо","ставок тихої води"},ang={["faction:Horde"]="Завдання дає гостям з Орди зазирнути в похмуру, суворо дисципліновану командну структуру, яку офіцери Сильвани Віндраннер насаджують по всьому Тірісфалю.",["race:Undead"]="Для щойно звільнених Відступників виконання наказів Зиґанда закріплює сувору дійсність виживання в Лордероні: цілковита відданість Темній Леді й нульова терпимість до невдач."},sec={{t="Воля Темної Леді",b="Екзекутор Зиґанд командує місцевою безпекою в Галявинах Тірісфалю і не терпить жодних послаблень пильності. Для Зиґанда служити Леді Сильвані означає ніщо інше, як цілковиту ефективність. Коли чергові польові донесення не надходять на його пост вчасно, він бачить у цьому неприпустиме порушення обов'язку, а не дрібну затримку. Замість покинути пост і розбиратися самому, він посилає новоприбулих агентів Відступників приструнити недбалих підлеглих і пересвідчитися, що кордони в безпеці."},{t="Вартові галявин",b="Донесення стосуються вартових на ключових спостережних пунктах довкола Брілла. Вартовий Смерті Діллінджер пильнує цвинтар на заході, де часто ворушаться здичавіла нежить і недобитки Погибелі. На сході Вартовий Смерті Крістоф наглядає за заставою, що стереже підступи до Столиці — колишнього стольного міста — і східні дороги. Найнезвичайніший серед них — Ґордо, здоровенна гидота, що тиняється біля Ставка Тихої Води: з його простим розумом військове діловодство — вельми сумнівне сподівання."}},faq={{q="Хто такий Екзекутор Зиґанд?",a="Екзекутор Зиґанд — високопоставлений офіцер Відступників, що підтримує лад і оборону довкола Брілла на Галявинах Тірісфалю. Він звітує безпосередньо командуванню, яке служить Леді Сильвані, і вимагає бездоганного виконання від усіх підлеглих.",al={"зиґанд","хто такий зиґанд","роль екзекутора зиґанда"}},{q="Чому Зиґанд посилає шукача пригод збирати донесення?",a="Кілька польових вартових не надіслали вчасно своїх донесень. Не маючи терпіння до затримок і не бажаючи покидати свій пост, Зиґанд посилає щойно випробуваних Відступників збирати прострочені донесення по околицях.",al={"чому терпіння","чому збирати донесення"}},{q="Хто такий Ґордо і чому в нього донесення?",a="Ґордо — гидота, що блукає на заході біля Ставка Тихої Води. Зиґанд чекав від нього донесення про стан справ, як і від будь-якого польового вартового, але, отримавши його, Екзекутор швидко розуміє, що чекати письмових відомостей від гидоти було ганебним недоглядом.",al={"ґордо","чому в потвори донесення","хто такий ґордо"}},{q="Де Вартовий Смерті Діллінджер?",a="Вартовий Смерті Діллінджер стоїть трохи на захід від Брілла, біля місцевого цвинтаря, — він пильнує рештки Погибелі й щойно піднятих мерців.",al={"місце діллінджера","знайти діллінджера","де діллінджер"}},{q="Де стоїть Вартовий Смерті Крістоф?",a="Вартовий Смерті Крістоф — на заїжджому дворі біля дороги на схід від Брілла: він стереже підступи від непроханих гостей і стежить за рухом на дорозі.",al={"місце крістофа","знайти крістофа","де крістоф"}},{q="Що станеться, коли здати донесення Ґордо?",a="Екзекутор Зиґанд визнає, що чекати від гидоти зв'язного письмового донесення було дурною помилкою. Він мовчки змиряється з наслідками й просить, щоб цей ганебний недогляд лишився суворо між вами двома.",al={"результат донесення ґордо","ґордо пише"}}},fp="8,361,30.486.0,23.490.0,23.260.0,54.244.0,43.288.1,38.153.0,38.157.0,46.224.1"}
P.entries["quest:99142"] = {n="Могильне зілля",s="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю. Голланд видозмінював дике Зілля Приречення і пересаджував його на проклятому Хуторі Балнірів, вирощуючи сильний новий зразок, що несподівано приваблює місцеву Погибель.",h="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю.",kw={"могильне зілля","гробнична трава","голланд","хутір балнірів","зілля приречення","алхімія"},ang={["profession:Herbalism"]="Гробнична Трава показує, як штучне алхімічне втручання може докорінно змінити властивості й поведінку спустошених трав на кшталт Зілля Приречення.",["race:Undead"]="Дослідження Молодшого Аптекаря Голланда показують невпинне прагнення аптекарів Відступників перетворювати спустошену флору Тірісфалю на алхімічні знаряддя на замовлення."},sec={{t="Вирощування Голланда",b="Молодший Аптекар Голланд не задовольняється простим збиранням місцевих трав для Королівського Аптекарського Товариства — він плекає власні великі амбіції. Зібравши Зілля Приречення й піддавши його незначним алхімічним змінам, він пересадив ці пагони в землю Хутора Балнірів, щоб вивести вдосконалений зразок, який охрестив Гробничною Травою. Голланд бачить у цій гібридній рослині осердя своєї праці й провісника власної долі."},{t="Небажана принада",b="Голланд розраховував на алхімічну силу, та пересадження Гробничної Трави на Хутір Балнірів дало непередбачений побічний ефект. Блукаючі недобитки Погибелі, що кишать на спустошених полях, виявили до буйної рослини моторошний, нездоланний потяг. Голланд покладається на перехожих мандрівників: ті мають пробитися крізь нежить, що насідає, і зібрати дозрілий урожай, щоб він міг продовжити експерименти."}},faq={{q="Що таке могильне зілля?",a="Могильне зілля — алхімічно змінений різновид Зілля Приречення, який вирощує Молодший Аптекар Голланд. Він бере місцеве Зілля Приречення, змінює його хімічними реагентами й висаджує в отруєний ґрунт Хутора Балнірів.",al={"що таке могильне зілля","переказ про могильне зілля","рослина могильне зілля"}},{q="Хто такий Молодший Аптекар Голланд?",a="Голланд — член Королівського Аптекарського Товариства, що працює на Галявинах Тірісфалю. Честолюбний і часто доведений до розпачу помічниками на кшталт гидоти Ґордо, Голланд проводить власні садівничі й алхімічні досліди, щоб піднятися в чині.",al={"хто такий голланд","молодший аптекар голланд","аптекар голланд"}},{q="Де вирощують могильне зілля?",a="Голланд садить свої змінені рослини на Хуторі Балнірів — покинутому господарстві на сході Галявин Тірісфалю, що занепало й спустошене пошестю.",al={"де могильне зілля","місце могильного зілля","бур'ян на фермі балніра"}},{q="Чому могильне зілля приваблює Погибель?",a="Голланд помітив, що безмозку Погибель, яка блукає Хутором Балнірів, ніби інстинктивно тягне до зміненої рослини, хоча й не знає чому; йому це просто цікаво.",al={"чому погибель хоче зілля","погибель тягнеться до зілля","реакція погибелі"}},{q="Чим могильне зілля відрізняється від звичайного Зілля Приречення?",a="Зілля Приречення — дика рослина, що росте біля братської могили на північ від цвинтаря Брілла. Могильне зілля з'являється, коли Зілля Приречення штучно змінюють алхімією й вибірково пересаджують у ґрунт хутора під наглядом Голланда.",al={"зілля приречення проти могильного","різниця між зіллями"}},{q="Хто такий Ґордо, про якого згадує Голланд?",a="Ґордо — гидота, створена Відступниками, що блукає дорогами Галявин Тірісфалю; Голланд часто доручає йому прості завдання, що виявляються надто складними для його неповороткого розуму.",al={"хто такий ґордо","ґордо зустріч","ґордо тірисфаль"}}},fp="9,263,21.442.0,21.406.0,18.223.0,33.257.0,25.149.0,43.180.0,48.250.0,34.179.0"}
P.entries["quest:99156"] = {n="Тиловий патруль",s="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю. Замість відбиватися від звичайних заблукалих гулів, патрульним доручають вистежити Ріптіра — гидоту, що блукає біля Долини Отруйного Павутиння, хоч ніколи не мала пройти повз Заслон.",h="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю.",kw={"тиловий патруль","ріптір","гидота","ліннея","заслон","долина отруйного павутиння"},ang={["faction:Horde"]="Безпека східного кордону Тірісфалю гарантує, що лінії постачання Заслону й Андерсіті не підірвуть здичавілі жахіття.",["race:Undead"]="Відступники не можуть дозволити собі війну на два фронти; будь-який витвір Погибелі, що блукає за їхніми оборонними загорожами, — смертельна небезпека для їхнього королівства."},sec={{t="Пролом на кордоні",b="Заслон — єдина укріплена перепона, що відділяє Галявини Тірісфалю від жахіть, якими повняться Західні Чумні Землі. Стратегія війська Відступників тримається на суворо одному фронті. Якщо безтямна нежить прослизне в тил, лінії постачання фронту можна задушити за мить. Поодинокі духи чи гулі зрідка обходять загорожі, та звістки про гидоту, що блукає галявинами, свідчать про серйозний провал стримування."},{t="Загроза Ріптіра",b="Потвору-відступника на ім'я Ріптір бачили, як вона сунула поблизу Долини Отруйного Павутиння, за передовими редутами Заслону. Гидоти — величезні машини різанини, зшиті з трупів і темної некромантії. Вони не проходять укріплені вузькі проходи непоміченими, тож Вартову Смерті Ліннею глибоко тривожить, як саме істота перетнула периметр. Ліннея вимагає серце Ріптіра як беззаперечне підтвердження його знищення."}},faq={{q="Хто дає завдання «Тиловий патруль»?",a="Наказ про патруль дає Вартова Смерті Ліннея — Вартова Смерті з Відступників на Галявинах Тірісфалю, що звітує Екзекуторові Зиґанду.",al={"хто дає тиловий патруль","видавець тилового патруля","хто дає це завдання"}},{q="Що таке Ріптір?",a="Ріптір — гидота, що вийшла з-під контролю; її помітили на східних галявинах біля Долини Отруйного Павутиння, у тилу передових оборонних рубежів.",al={"хто такий ріптір","що таке ріптір","переказ про ріптіра"}},{q="Чому гидота біля Долини Отруйного Павутиння так тривожить?",a="Гидоти — величезні створіння, для виготовлення яких потрібні темна некромантія й тяжка праця. Непомітно прослизнути крізь сильно укріплений Заслон мало б бути неможливо, тож це свідчить про тривожний прорив або невідомий шлях у тил Відступників.",al={"чому ріптір так турбує","чим небезпечна потвора тут","прорив заслону"}},{q="Де зазвичай буває ця потвора?",a="Ріптіра бачили в лісах і на галявинах сходу Галявин Тірісфалю, поблизу Долини Отруйного Павутиння.",al={"де ріптір","місце ріптіра","де знайти потвору"}},{q="Який доказ потрібен, щоб завершити патруль?",a="Вартова Смерті Ліннея вимагає Серце Ріптіра, щоб переконатися, що велетенську потвору знищено назавжди.",al={"що принести ліннеї","предмет здачі","доказ смерті ріптіра"}},{q="Хто керує обороною Заслону?",a="У завданні не названо командира Заслону. Вартова Смерті Ліннея підпорядкована Екзекуторові Зиґанду в Бріллі, який отримує її подання про відзнаки за патрулі, що тримають Погибель на відстані.",al={"хто керує заслоном","начальник ліннеї","екзекутор зиґанд"}}},fp="17,285,24.457.0,21.441.1,39.121.0,16.124.0,53.248.0,33.117.0,44.112.0,40.189.0"}
P.entries["quest:993"] = {n="Зниклий господар",s="Зібравши шкури й тонку нитку, ви несете готовий Зачарований Плащ Місячного Скрадача в нетрі Темного Узбережжя, щоб знайти зниклого нічного ельфа Волкора. Ведені його вірним білим ведмедем Похмурим кігтем, ви мусите розшукати пораненого розвідника, перш ніж ворожі фурболги його доб'ють.",h="Зібравши шкури й тонку нитку, ви несете готовий Зачарований Плащ Місячного Скрадача в нетрі Темного...",kw={"зниклий господар","волкор","похмурий кіготь","зачарований плащ місячного скрадача","терентіс","фурболги"},ang={["class:Hunter"]="Те, як Похмурий кіготь знаходить дорогу, щоб привести допомогу Волкорові, підкреслює надзвичайний розум і відданість добре вишколених звірів Калімдору.",["faction:Alliance"]="Обердайн залежить від розвідників на кшталт Волкора, що стежать за дедалі сильнішою порчею племен фурболгів Темного Узбережжя, тож його порятунок — головна справа для застави.",["race:NightElf"]="Непохитна вірність Похмурого кігтя, що шукає допомоги для свого господаря Волкора, показує зв'язок між розвідниками нічних ельфів і їхніми звірами-супутниками."},sec={{t="Маяк у лісі",b="Коли Терентіс в Обердайні виткав Зачарований Плащ Місячного Скрадача, пошуки зниклого розвідника Волкора починаються по-справжньому. Його товариш-ведмідь, Похмурий кіготь, повернувся на дорогу на південь від поселення й чатує на будь-якого союзника, якого пошле Терентіс. Привітавшись із вірним звіром знайомим знаком, мандрівники рушають за ним із битого шляху просто до печери, де ховається Волкор."},{t="Схованка в темряві",b="Волкор знайшов притулок у печері, тяжко поранений місцевими зіпсованими фурболгами. Затиснутий у пастці й стікаючи кров'ю, він міг покладатися лише на потайність і кмітливість Похмурого кігтя, щоб його не здолали. Зачарований плащ дає йому укриття й надію, потрібні, щоб спланувати втечу, хоча через рани зворотна дорога до Обердайна для нього небезпечна."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник нічних ельфів із Темного Узбережжя, що зник, коли вирушив до ворожих таборів фурболгів. Під час сутички його тяжко поранили, і він ледве доповз до печери неподалік, а його супутник-ведмідь Похмурий кіготь пішов по допомогу.",al={"переказ про волкора","хто зниклий господар"}},{q="Як знайти схованку Волкора?",a="Похмурий кіготь чекає біля дороги на південь від Обердайна. Помахайте звірові — так він зрозуміє, що ви та підмога, яку послав Терентіс, і побіжить просто до відлюдної печери, де Волкор виходжує свої рани.",al={"де волкор","знайти печеру волкора","як іти за похмурим кігтем"}},{q="Навіщо потрібен Зачарований Плащ Місячного Скрадача?",a="Терентіс зачарував плащ, зшитий із тонких ниток і шкур місячних скрадачів, щоб той ненадовго давав сильну магічну невидимість. Його чари дають змогу безперешкодно проходити повз створіння Темного Узбережжя, поки ви шукаєте Волкора, а потім плащ віддають йому.",al={"плащ місячного скрадача","магія плаща"}},{q="Хто напав на Волкора?",a="На Волкора напали й поранили його зіпсовані скверною племена фурболгів, що никають Темним Узбережжям. Йому вдалося уникнути загибелі, але через рани він не міг сам дістатися назад до Обердайна.",al={"хто поранив волкора","чому волкор кровить"}},{q="Що буде, коли Волкора знайдено?",a="Отримавши зачарований плащ, Волкор переводить подих і просить допомогти йому вибратися з нетрів: ви можете або обережно вивести його крадькома, або прорубати шлях крізь фурболгів силою.",al={"наступне завдання волкора","після зниклого господаря"}}},fp="13,276,21.399.0,18.402.1,14.248.0,37.223.0,55.241.0,20.211.0,34.243.1"}
P.entries["quest:994"] = {n="Втеча силою",s="«Втеча силою» — завдання Альянсу на Темному Узбережжі, в якому шукач пригод допомагає Волкорові прорватися крізь навколишні загрози в прямому бою. Коли вони пробиваються крізь небезпеки нетрів до дороги й Волкор возз'єднується з вірним товаришем Похмурим кігтем, шукач пригод доповідає про його порятунок Терентісові в Обердайні.",h="«Втеча силою» — завдання Альянсу на Темному Узбережжі, в якому шукач пригод допомагає Волкорові прорватися...",kw={"втеча силою","волкор","похмурий кіготь","терентіс","вартова селарін","обердайн"},ang={["faction:Alliance"]="Допомагаючи місцевим розвідникам, ви зміцнюєте зв'язок між молодим Альянсом і нічними ельфами й доводите цінність фракції в захисті північного рубежу Калімдору.",["race:NightElf"]="Рятувати розвідників на кшталт Волкора украй важливо, щоб калдореї втримали хиткий контроль над Темним Узбережжям, де дикі звірі, порча й чужинці загрожують лісам їхніх предків."},sec={{t="Прямий шлях назовні",b="Коли застрягнеш у небезпечних нетрях Темного Узбережжя, не завжди обираєш тиху ходу. Перед лицем небезпеки нічний ельф Волкор погоджується на пряму стратегію — прорубатися крізь ворожих істот довкола до безпечного місця. Замість намагатися непомітно вислизнути, Волкор покладається на бойову майстерність, щоб прорубати прохід просто до головної дороги."},{t="Зустріч на дорозі",b="Благополучно діставшись тракту, Волкор возз'єднується з Похмурим кігтем — своїм непохитним товаришем-ведмедем, що чекав біля стежки. Убезпечивши втечу, Волкор готується до нової дороги й просить шукача пригод доповісти безпосередньо Терентісові в Обердайні. Звістка про те, що Волкор у безпеці, заспокоює провід нічних ельфів і одразу привертає увагу Вартової Селарін, вказуючи на глибші негаразди, що визрівають на півдні, в Ашенвалі."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник чи лісовик із нічних ельфів на Темному Узбережжі, що зник разом зі своїм супутником Похмурим кігтем. Коли його знаходять шукачі пригод, послані Терентісом, йому потрібна допомога, щоб вибратися від ворожих звірів і з небезпечної місцини.",al={"особа волкора","хто такий волкор","волкор темне узбережжя"}},{q="Хто такий Похмурий кіготь?",a="Похмурий кіготь — вірний супутник Волкора, ведмідь. Поки Волкор був у пастці, Похмурий кіготь лишався окремо біля дороги — саме там і було місце зустрічі після втечі Волкора.",al={"похмурий кіготь","ведмідь волкора","вихованець волкора"}},{q="Чому Терентісові важливо, щоб Волкор повернувся?",a="Терентіс керує розвідниками й місцевою обороною з Обердайна. Розшукувати загублених союзників і оцінювати загрози на узбережжі вкрай важливо, щоб нічні ельфи утримали контроль над Темним Узбережжям, де ситуація стрімко погіршується.",al={"терентіс і волкор","чому допомагати волкору","завдання терентіса"}},{q="Що буде після цього завдання?",a="Report Volcor's safe passage to Terenthis in Auberdine. The chain then leads to Trek to Ashenvale.",al={"після втечі силою","що далі","наступне завдання після волкора"}},{q="Чи є інший спосіб завершити супровід Волкора?",a="Так. Рятуючи Волкора, шукачі пригод можуть обрати підхід: прорватися з боєм у завданні «Втеча силою» або тихо провести його повз небезпеку крадькома.",al={"інший спосіб втечі","втеча крадькома","вибір волкора"}},{q="Куди веде це завдання в ширшому сюжеті?",a="Порятунок Волкора — місток між місцевими сутичками на Темному Узбережжі й ширшою обороною земель нічних ельфів: він прямо відкриває доручення в Ашенвалі.",al={"сюжет волкора","ланцюжок темного узбережжя до ашенвалю"}}},fp="20,323,16.372.0,19.463.1,14.245.0,16.175.0,46.236.0,41.98.1,52.179.0,52.188.1"}
P.entries["quest:995"] = {n="Втеча крадькома",s="«Втеча крадькома» — завдання Альянсу із супроводом на Темному Узбережжі. Знайшовши розвідника нічних ельфів Волкора, що опинився в пастці глибоко в лігві фурболгів, шукач пригод допомагає йому безпечно прослизнути повз ворожих звірів на волю, а тоді доповідає Терентісові в Обердайні.",h="«Втеча крадькома» — завдання Альянсу із супроводом на Темному Узбережжі.",kw={"втеча крадькома","волкор","терентіс","лігво фурболгів","супровід","обердайн"},ang={["class:Rogue"]="Розбійники цінують тактичне чуття Волкора — оминути закріпленого ворога, а не марнувати час і кров у безрозсудній бійці в лоб.",["faction:Alliance"]="Успішна втеча Волкора доводить проводові нічних ельфів в Обердайні, що союзникам з Альянсу, які не є калдореями, можна довіряти делікатні операції в нетрях.",["race:NightElf"]="Для нічних ельфів допомога Волкорові зміцнює важливу мережу розвідників, що стежать за неспокійними лісами Калімдору, поки порча шириться зі спотворених курганів і лігв."},sec={{t="Розвідник у пастці",b="Волкора, посланця, якого відрядили вглиб Темного Узбережжя розслідувати дедалі грізніші загрози краю, загнали в кут у печері фурболгів. У меншості й відрізаний від головних доріг, він покладається на союзника, що опинився поруч, аби організувати втечу, перш ніж ворожі фурболги збагнуть, що він вислизає."},{t="Обережна втеча",b="Замість самогубної атаки в лоб Волкор обирає обережність. Покладаючись на тіні й виважені маневри, він прослизає повз зіпсованих мешканців печери. Знаючи, що найважливіше — швидкість і тиша, Волкор щойно за входом до печери розлучається з рятівником і мчить уперед пішки, наказавши йому зустрітися в поселенні Обердайн."},{t="Донесення в Обердайні",b="Повернувшись до Обердайна, шукач пригод приносить звістку про порятунок Терентісові — провідникові нічних ельфів, що координує захист неспокійного узбережжя. Терентіс бачить у безпечному поверненні Волкора доказ того, що темряві, яка насувається на Темне Узбережжя й нетрі за ним, можна протистояти дисципліною й злагодженістю."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник нічних ельфів, що за дорученням старших заглибився в нетрі Темного Узбережжя. Він опинився в пастці у ворожій печері фурболгів, доки його не врятував шукач пригод з Альянсу.",al={"переказ про волкора","хто такий волкор","волкор темне узбережжя"}},{q="Чому Волкор, вибравшись із печери, тікає сам?",a="Волкор зауважує, що, вибравшись із тісних печерних ходів, сам рухатиметься швидше. Він велить шукачеві пригод зустрітися з ним в Обердайні, а не триматися разом на відкритих дорогах.",al={"чому волкор іде","волкор розділяється"}},{q="Хто такий Терентіс?",a="Терентіс — помітний очільник нічних ельфів в Обердайні. Він керує місцевою розвідкою й організовує відсіч скверні та ворожим мешканцям, що загрожують Темному Узбережжю.",al={"терентіс оберіжин","хто такий терентіс"}},{q="Де відбувається порятунок?",a="Порятунок починається в глибині печери фурболгів у диких спірних лісах Темного Узбережжя, далеко від безпечного Обердайна.",al={"місце печери волкора","де печера волкора"}},{q="Що буде після цього завдання?",a="Коли Волкор у безпеці, а Терентіс вислухав доповідь, гравців скеровують на наступний етап подорожі — на південь, до Ашенвалю, у завданні «Похід до Ашенвалю».",al={"що після втечі крадькома","наступне завдання після волкора"}},{q="Яка альтернатива скраданню в цьому порятунку?",a="Волкор пропонує інший підхід: замість того щоб вибиратися крадькома, шукачі пригод можуть прорватися самою силою — це окремий варіант супроводу з боєм.",al={"втеча силою","інше завдання волкора","крадькома проти сили"}}},fp="22,259,17.293.0,16.380.0,22.325.0,14.196.0,52.198.0,17.191.0,34.137.0,41.179.0,50.190.0"}
P.entries["quest:997"] = {n="Земля Деналана",s="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет. Сірал Блейдліф просить мандрівників власноруч доставити затриману посилку з рідкісним збагаченим ґрунтом її колезі-ботаніку Деналану, який вивчає гілля та флору нового Світового Дерева.",h="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет.",kw={"земля деналана","деналан","сірал блейдліф","ґрунт","озеро ал'амет","доланаар"},ang={["class:Druid"]="Друїди мають природну спорідненість із працею Деналана, адже стеження за ростом і рівновагою флори Тельдрассила — запорука захисту природи на новому гіллі.",["profession:Herbalism"]="Травникам припаде до душі озерний прихисток Деналана, адже його досліди зосереджені на розумінні крихкого молодого рослинного життя, властивого лише щойно вирослому Світовому Дереву.",["race:NightElf"]="Для нічних ельфів, що виходять із Тінедола, допомога Сірал і Деналанові — раннє знайомство з ширшою опікою, потрібною, щоб підтримувати Тельдрассил."},sec={{t="Кур'єр для Доланаара",b="Коли мандрівники проходять через Доланаар, прямуючи на південь до Озера Ал'Амет, Сірал Блейдліф зупиняє їх із задавненим дорученням. Її колега-дослідник Деналан замовив особливий пакунок рідкісної землі аж із Дарнасуса для своїх ботанічних досліджень. Посилка затрималася в дорозі й лише нещодавно прибула до Доланаара. Щоб багатий ґрунт не зіпсувався й не лежав без діла, Сірал шукає люб'язного кур'єра, готового віднести його лісовою стежкою до озерного табору Деналана."},{t="Вирощуючи Тельдрассил",b="Деналан тримає самотню робітню на східному березі Озера Ал'Амет, де спостерігає, як укорінюється молода екосистема Тельдрассила. Тельдрассил юний — він стрімко виріс після катаклізму на горі Гіджал, і його флора поводиться несподівано. Деналан випробовує унікальні суміші ґрунту й зразки, щоб перевірити життєвість і поведінку острівних деревляників і місцевих рослин, тож свіжа посилка рідкісної землі вкрай важлива для його дослідів."}},faq={{q="Хто такий Деналан?",a="Деналан — дослідник і травник із нічних ельфів, що отаборився на східному березі Озера Ал'Амет. Він вивчає, вирощує й випробовує неповторну рослинність Тельдрассила.",al={"переказ про деналана","хто такий деналан","деналан неігровий персонаж"}},{q="Де знайти Сірал Блейдліф?",a="Сірал Блейдліф мешкає в Доланаарі — головній заставі нічних ельфів у центрі Тельдрассила: там вона розподіляє припаси для досліджень і допомагає мандрівникам, що подорожують гілками.",al={"місце сірал блейдліф","де сірал"}},{q="Навіщо рідкісна земля?",a="У партії — особливо удобрений ґрунт зі столиці, Дарнасуса. Деналан вирощує на ньому дослідні посадки й перевіряє, як місцеві паростки Тельдрассила, зокрема деревляники, реагують на різні умови росту.",al={"навіщо деналану земля","призначення рідкісної землі"}},{q="Де Озеро Ал'Амет?",a="Озеро Ал'Амет лежить на південь від Доланаара — тиха водойма серед південного коріння Тельдрассила.",al={"місце озера ал'амет","як дістатися озера ал'амет"}},{q="Чому партія затрималася?",a="Пакунок мав дістатися з Дарнасуса й, поки добирався звивистими дорогами Тельдрассила, зазнав невідомих затримок, перш ніж нарешті прибув до розподільного пункту в Доланаарі.",al={"чому земля запізнилася","затримка посилки"}},{q="До чого веде доставка цієї землі?",a="Отримавши рідкісний ґрунт, Деналан просить посланця допомогти зібрати паростки й насіння деревляників на берегах озера — так починається глибша низка польових ботанічних досліджень.",al={"продовження землі деналана","що далі"}}},fp="15,297,22.508.0,22.469.0,15.208.0,33.178.0,32.234.0,23.118.0,26.178.0,40.181.1"}
P.entries["quest:cutting-teeth"] = {n="Проба зубів",s="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі. Наглядач Ґорнек доручає новачкам прорідити плямистих вепрів, які блукають сусідніми кактусовими городами на червоній землі, і так перевіряє їхню базову бойову готовність. Пройти цей скромний обряд посвяти — означає довести, що майбутній воїн чи чарівник має хребет, потрібний для служби Орді.",h="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі.",kw={"проба зубів","вепри","ґорнек","долина випробувань","новобранці","перше завдання"},ang={["faction:Horde"]="Кожен молодий герой, що ступає в Дуротар, має починати від самої землі, доводячи, що майбутнє Орди тримається на крові й поті, а не на незаслуженій славі.",["race:Orc"]="Орківська культура понад усе цінує практичне виживання й воїнську честь; навіть скромне винищення вепрів — священний перший крок у доросле життя й службу новій державі Тралла.",["race:Troll"]="Поки плем'я Темного Списа відбудовується поруч з орками-союзниками, молоді тролівські розвідники й містики теж мають довести свою самостійність серед безжальних хижаків Дуротару."},sec={{t="Міра хребта",b="Долина Випробувань не потурає мріям про велич. Хоч молоді новобранці можуть марити полюванням на велетенських звірів у Пустках чи славою на полях битв, наглядач Ґорнек починає їхню оцінку зі значно приземленіших справ. Проріджування плямистих вепрів довкола городів долини — базова перевірка: вона показує, чи вміє новобранець тримати зброю або накласти закляття, чи впорається з дикою люттю й чи має досить глузду, щоб пережити свою найпершу сутичку."},{t="Приборкання червоного пилу",b="Окрім перевірки сирих новобранців, винищення плямистих вепрів має й практичну господарську мету для поселення в червоній пустелі. Здичавілі свині блукають городами на північ і північний схід від табору, риють кактусові грядки й загрожують убогим припасам, вирощеним на суворому ґрунті Дуротару. Посилаючи претендентів їх вибити, табір тримає місцевих шкідників у шорах і водночас кує з молодих орків і тролів умілих захисників нової держави."}},faq={{q="Чому Ґорнек посилає новобранців на кабанів, а не на більших звірів?",a="Як визнає сам Ґорнек, живі новобранці для Орди куди корисніші за мертвих. У Пустках водяться могутні кодо й хижаки, але посилати проти них необстріляного новачка — це просто марна різанина. Кабани ж — надійна перевірка базових бойових навичок без зайвих втрат.",al={"чому кабани","чому вбивати кабанів","полювання ґорнека на кабанів"}},{q="Де водяться плямисті кабани?",a="Плямисті кабани риються в чагарниках і на земляних грядках на північ і північний схід від центральної галявини Долини Випробувань.",al={"місце кабанів","де кабани","знайти плямистих кабанів"}},{q="Що означає вислів «проба зубів»?",a="Цей вислів означає перший практичний досвід у ремеслі чи покликанні. Для майбутнього захисника Орди це перехід від тренувальних опудал і порожніх балачок до справжньої боротьби за виживання, де ллється кров.",al={"що значить проба зубів","значення проби зубів"}},{q="Хто дає це випробування?",a="Доручення дає Ґорнек — наглядач у серці Долини Випробувань, що оцінює й скеровує новобранців, які прибувають на вишкільні землі Дуротара.",al={"хто дає пробу зубів","видавець проби зубів","випробування ґорнека"}},{q="Чи завершує це навчання в Долині Випробувань?",a="Ні. Ґорнек попереджає, що бої з кабанами — лише розминка. Після цього доручення одразу настають небезпечніші випробування — зокрема сутички з непроханими гостями й збирання життєво важливих ресурсів долини.",al={"чи це останнє завдання","що після проби зубів"}},{q="Чим кабани заважають у долині?",a="Дикі кабани агресивно никають місцевими земляними грядками й заростями, наражаючи на небезпеку робітників і поїдаючи ті кілька витривалих рослин, як-от кактусові плоди, якими живе табір.",al={"проблема кабанів","кабани долини випробувань"}}},fp="13,382,21.488.0,19.449.0,67.301.0,36.136.0,55.225.0,23.166.0,56.205.0,46.182.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="Сюрприз із Кактусових Яблук від Ґалґара",s="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем Долині Випробувань. Шукаючи порятунку від нищівної спеки Дуротару, орк Ґалґар просить подорожніх назбирати диких кактусових яблук, щоб приготувати свої знамениті освіжні ласощі. Завдання навчає новобранців збирати харч і виживати в посушливому краї.",h="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем...",kw={"ґалґар","кактусові яблука","сюрприз","кулінарія","долина випробувань","спека"},ang={["faction:Horde"]="Кожен новобранець, що ступає в Долину Випробувань, швидко дізнається: витримати нищівне сонце Дуротару — така сама частина вишколу, як і бій.",["profession:Cooking"]="Страва Ґалґара показує винахідливість, потрібну, щоб із жорсткої колючої пустельної рослинності приготувати поживну їжу й освіжні ласощі.",["race:Orc"]="Освоєння Дуротару означало пристосуватися до посушливого краю, і прості страви з місцевих кактусів утілюють практичну здатність орків процвітати на новій землі."},sec={{t="Виживання в червоних пустках",b="Багряна земля Долини Випробувань славиться своєю безжальністю. Між виснажливими бойовими вправами й лютими сутичками з тутешніми звірами виснаження й зневоднення настають швидко. Для молодих орків і тролів Темного Списа, що роблять перші кроки як захисники Орди, навчитися жити з дарів землі не менш важливо, ніж махати сокирою. Кактуси по всій долині родять стиглі, соковиті яблука, що дають негайний перепочинок від гнітючого пустельного сонця."},{t="Делікатес долини",b="Ґалґар, що стоїть на тренувальних землях, перетворив збирання місцевих плодів на мистецтво. Його знаменитий Сюрприз із Кактусових Яблук став легендою серед мешканців долини: він остуджує швидше, ніж стрибок у річкову воду. Наймаючи завзятих новобранців збирати колючі плоди з сусідніх кактусів, Ґалґар тримає свою кухню повною й дбає, щоб жоден новий мандрівник не вирушав у Дуротар із порожнім шлунком."}},faq={{q="Хто такий Ґалґар?",a="Ґалґар — орк, що мешкає в Долині Випробувань у Дуротарі. Замість того щоб наглядати за бойовим вишколом, він готує освіжні харчі й ласощі, як-от свій знаменитий Сюрприз із Кактусових Яблук, щоб новобранці легше переносили пустельну спеку.",al={"хто такий ґалґар","переказ про ґалґара","хто дає завдання кактусових яблук"}},{q="Що таке Сюрприз із Кактусових Яблук?",a="Це популярні місцеві ласощі й освіжна закуска, яку Ґалґар готує зі свіжих кактусових яблук, зібраних з диких пустельних кактусів. Учні цінують її за те, що вона швидко рятує від спеки й угамовує спрагу під пекучим сонцем Дуротара.",al={"їжа сюрприз із кактусових яблук","що за сюрприз","рецепт ґалґара"}},{q="Де ростуть кактусові яблука?",a="Кактусові яблука ростуть невеликими гронами на землі біля підніжжя квітучих кактусів, розкиданих серед червоних скель і каньйонів Долини Випробувань.",al={"де кактусові яблука","знайти кактусові яблука","як отримати кактусові яблука"}},{q="Чому Ґалґар просить новобранців їх зібрати?",a="У Долині Випробувань страшенна спека, а Ґалґар не може покинути свій пост, щоб самому никати пустелею. Він пропонує поділитися своїми хвалебними ласощами з кожним перехожим новачком, що наважиться піти в чагарники й назбирати для нього сировини.",al={"чому збирати кактусові яблука","чому ґалґару потрібні яблука"}},{q="Чи пов'язане це завдання з ширшим сюжетом?",a="Ні. Це окреме завдання на збирання, яке має навчити новобранців добувати ресурси з довкілля, поки вони проходять перші випробування для Орди.",al={"чи є ланцюжок","продовження кактусових яблук","що після сюрпризу з яблук"}},{q="Чому в Долині Випробувань так важливо вміти збирати харчі?",a="Дуротар — суворий, немилосердний край із посушливих скель і чагарників. Ватажки Орди вважають, що вміння вижити на мізерних природних ресурсах Дуротара — необхідний вишкіл для кожного, хто хоче витримати випробування ширшого світу.",al={"чому збирати харчі","виживання в дуротарі"}}},fp="30,363,24.470.0,17.431.0,14.265.0,30.242.0,30.154.0,44.257.0,46.178.0,50.231.0"}
P.entries["quest:lazy-peons"] = {n="Ліниві пеони",s="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі. Отримавши його обтяжений кийок, молоді новобранці обходять долину, щоб привести до тями сплячих пеонів і подбати, щоб життєво важлива деревина й далі текла до поселень Дуротару.",h="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі.",kw={"пеони","наглядач тазз'ріл","кийок наглядача","деревина","долина випробувань","робітники"},ang={["faction:Horde"]="Кожна застава в Дуротарі покладається на деревину, яку рубають ці пеони, тож базова дисципліна робітників — справа спільного виживання.",["race:Orc"]="Для молодих орків, що дорослішають, дисциплінувати робочу силу власних родичів — ранній урок суворих реалій і практичної дисципліни, потрібних, щоб вирізьбити державу з дикої землі.",["race:Troll"]="Тролі Темного Списа, що навчаються поруч із союзниками, на власні очі бачать дивне поєднання грубої сили й управлінського відчаю, яке визначає орківське будівництво."},sec={{t="Байдики на сонці",b="Будівництво нового дому на посушливих рівнинах Дуротару вимагає величезної кількості деревини, каменю й просто важкої праці. Більша частина цього тягаря лягає на касту пеонів — орків, яким бракує воїнської вправності, та які становлять працьовитий хребет Орди. На лихо Наглядача Тазз'ріла, пекуча спека й виснажлива праця в Долині Випробувань роблять надто легкою спокусу для цих робітників ушитися під тінисте дерево на самовільну дрімоту."},{t="Швидка побудка",b="Замість дозволити продуктивності зупинитися, Наглядач Тазз'ріл вдається до доволі прямолінійного способу керування — Кийка Наглядача. Довіривши цей тупий дисциплінарний інструмент новобранцям Орди, він посилає їх долиною гамселити сплячих робітників по голові. Злякано прокинувшись, очманілі пеони поспіхом повертаються рубати дрова, нагадавши собі, що лінивим рукам немає місця у виживанні Дуротару."}},faq={{q="Чому пеони засинають?",a="Заготовляти важкі колоди під пекучим сонцем Дуротара — тяжка, виснажлива праця. Коли над душею не стоїть наглядач, пеони раз у раз нишком утікають відпочити в затінку великих дерев.",al={"чому пеони сплять","ліниві пеони","пеони сплять на роботі"}},{q="Хто такий Наглядач Тазз'ріл?",a="Наглядач Тазз'ріл — орк-наглядач у Долині Випробувань. Він керує робітниками, що заготовляють деревину й припаси для будівництва молодої Орди.",al={"тазз'ріл","хто дає лінивих пеонів"}},{q="Що таке Кийок Наглядача?",a="Це важкий шкіряний кийок, яким Наглядач Тазз'ріл приводить до тями ледачих робітників. Швидкого удару по голові якраз досить, щоб розбудити сплячого пеона й не скалічити його.",al={"кийок","палиця пеонів","знаряддя кийок"}},{q="Яку роль пеони відіграють в Орді?",a="Пеони — робітничий стан орківського суспільства. Вони кремезні, але непридатні до війни, тож працюють будівничими, рудокопами й лісорубами, живлячи воєнну машину й поселення Орди.",al={"роль орочих пеонів","що таке пеони","каста пеонів"}},{q="Де знайти сплячих пеонів?",a="Вони по всій Долині Випробувань — і на північ, і на південь від Лігва. Шукайте під широкими кронами дерев, куди робітники ховаються в затінок.",al={"місця лінивих пеонів","де ліниві пеони","знайти сплячих пеонів"}},{q="Що буде, коли пеонів розбуджено?",a="Коли ви повернете кийок Наглядачеві Тазз'рілу, він дасть вам нове доручення — дістати його загублене кайло з глибини сусідньої печери.",al={"після лінивих пеонів","що далі після лінивих пеонів","наступне завдання після пеонів"}}},fp="10,277,19.426.0,20.419.0,33.197.0,25.186.0,32.185.0,37.227.0,35.162.0,42.146.1"}
P.entries["quest:sarkoth"] = {n="Саркот",s="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало поставило молодого мисливця Темного Списа на поріг смерті. Лежачи пораненим під деревом, умирущий троль Гана'зуа благає перехожого воїна вбити звіра й принести його скалічений пазур, щоб урятувати його честь.",h="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало...",kw={"саркот","гана'зуа","скорпід","плато","долина випробувань","честь","пазур"},ang={["faction:Horde"]="У безжальному середовищі Долини Випробувань прийти на поміч полеглим товаришам — ось що визначає силу громади, яку прагне плекати Орда Тралла.",["race:Orc"]="Орки розуміють муку смерті без перемоги; помста за Гана'зуа дарує невипробуваному розвідникові воїнське вдоволення бачити свого ворога поваленим.",["race:Troll"]="Для одноплемінника з Темного Списа відгукнутися на благання Гана'зуа — урочистий обов'язок спорідненості: подбати, щоб гідний опір члена племені визнали, а не загубили в пісках Дуротару."},sec={{t="Справа честі",b="Випробування в долині мають гартувати майбутніх воїнів Орди, та сувора пустеля рідко дає другий шанс. Вистежуючи отруйну тутешню звірину долини, молодий троль-розвідник Гана'зуа натрапив на скорпіда, значно більшого й смертоноснішого за решту. Хоч він і завдав важкого удару, що скалічив одну з клешень, хвіст Саркота впився йому в груди, і він лишився стікати кров'ю в сухій червоній пилюці. Перед лицем того, що здається кінцем його життя, у нього лишилося єдине бажання: щоб звір не пережив його."},{t="Жах плато",b="Саркот нишпорить піднесеним плато над південними околицями Долини Випробувань. Позначений розтрощеною клешнею від удару Гана'зуа, страхітливий звір панує на високому хребті й кидається на кожного, кому стане зухвалості піднятися кам'янистою стежкою. Убивство створіння й повернення його пошрамованого пазура Гана'зуа дає пораненому розвідникові гірку розраду — відчутний доказ того, що його останній відчайдушний удар послабив чудовисько настільки, щоб його можна було здолати."}},faq={{q="Де знайти Саркота?",a="Саркот никає на високому плато на південь від місця, де лежить поранений Гана'зуа. Щоб дістатися до нього, шукайте земляний підйом, що в'ється схилами каньйону, — там, на хребті, і блукає великий скорпід.",al={"місце саркота","де саркот","як дістатися саркота"}},{q="Хто такий Гана'зуа?",a="Гана'зуа — молодий троль Темного Спису, що проходить мисливські випробування в Долині Випробувань. Пошматований і отруєний Саркотом, він лежить під деревом і відчайдушно шукає шукача пригод, який помстився б за нього, перш ніж рани доконають його.",al={"ґана'зуа","троль помирає долина випробувань","видавець саркота"}},{q="Навіщо Гана'зуа клешня Саркота?",a="Під час бою Гана'зуа завдав лютого удару й розтрощив Саркотові клешню, перш ніж той його вжалив. Понівечена клешня стане доказом смерті чудовиська, і Гана'зуа пишатиметься, знаючи, що його останній бій був не зовсім марним.",al={"чому клешня саркота","доказ покаліченої клешні","честь ґана'зуа"}},{q="Чи помирає Гана'зуа від отрути?",a="Він тяжко поранений і гірко переживає свої, як йому здається, невдачі, але смерть Саркота дає Гана'зуа досить надії, щоб послати вас до Лігва по лікарську допомогу, а не змиритися зі смертю під деревом.",al={"чи ґана'зуа виживе","доля ґана'зуа","чи ґана'зуа мертвий"}},{q="Чим Саркот відрізняється від інших скорпідів?",a="На відміну від звичайних скорпідів, що снують дном долини, Саркот значно більший, агресивніший і має виразні сліди недавнього бою, зокрема пошкоджену клешню.",al={"чим відрізняється саркот","чому саркот особливий","бос скорпід дуротару"}},{q="Яке доручення йде після вбивства Саркота?",a="Коли ви повернете клешню Саркота Гана'зуа, він квапить вас мерщій повернутися до Лігва, розповісти ватажкам табору про його біду й привести допомогу, поки отруйна рана не стала смертельною.",al={"завдання після саркота","наступний крок ґана'зуа","завдання назад до лігва"}}},fp="7,323,17.545.0,18.451.0,25.181.0,16.238.0,38.247.0,33.217.1,49.201.0,49.183.1"}
P.entries["quest:your-place-in-the-world"] = {n="Твоє місце у світі",s="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді. Його дає Калтунк у Долині Випробувань, посилаючи невипробуваних новобранців просто до Ґорнека, щоб розпочати базовий бойовий вишкіл. Це найперший крок до честі й виживання в суворих землях Дуротару.",h="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді.",kw={"калтунк","ґорнек","долина випробувань","новобранець","перше завдання","орда"},ang={["faction:Horde"]="Кожен молодий новобранець Орди в Дуротарі має довести, що має досить впертості боронити свою молоду державу, перш ніж узяти зброю в ім'я Вождя.",["race:Orc"]="Для орків досягти повноліття й з'явитися на службу в Долину Випробувань — глибоко культурна віха, зосереджена на особистій честі й воїнській готовності.",["race:Troll"]="Оселившись у Дуротарі поруч з орками-союзниками, тролі Темного Списа навчаються тут пліч-о-пліч із побратимами, щоб кувати єдність і спільне виживання."},sec={{t="Дорослішання в Дуротарі",b="In the arid canyon of the Valley of Trials, young orcs and darkspear trolls must prove their worth before they can ever set foot in the wider world. Life under Warchief Thrall demands strength, vigilance, and discipline. Kaltunk evaluates every eager recruit, temperately dampening their dreams of wrestling demons and dragons to redirect them toward realistic duties. New recruits begin their training here, learning humility before claiming glory."},{t="Прибуття до Ґорнека",b="За кілька кроків від Калтунка сидить Ґорнек — суворий ветеран біля табірного вогнища. Ґорнек оцінює новоприбулих скептичним оком, часто бурчачи про жалюгідний матеріал, що прибуває до табору. Та саме його обов'язок — загартувати цих бійців-початківців суворими випробуваннями, починаючи з винищення тутешніх шкідників, що загрожують припасам табору."}},faq={{q="Навіщо це завдання?",a="Це вступний обряд посвяти для молодих новобранців у Долині Випробувань. Він офіційно зараховує вас на службу Орді й знайомить із Ґорнеком, який дає вам перші справжні бойові доручення.",al={"навіщо це завдання","перше завдання орди","твоє місце у світі"}},{q="Хто такий Калтунк?",a="Калтунк — орк-наглядач біля входу в Долину Випробувань. Він вітає новобранців, що досягли повноліття, оглядає їх і скеровує до відповідних наставників і ватажків табору.",al={"роль калтунка","хто дає завдання"}},{q="Хто такий Ґорнек?",a="Ґорнек — досвідчений наставник Орди, що сидить біля вогнища в Долині Випробувань. Його завдання — випробовувати новобранців і гартувати з них справних бійців, перш ніж відпустити з каньйону.",al={"роль ґорнека","де ґорнек"}},{q="Куди веде це завдання далі?",a="Доповідь Ґорнекові веде просто до випробування «Проба зубів», де новобранців посилають у пилюку винищувати плямистих кабанів і доводити свою базову бойову вправність.",al={"що далі","після твого місця у світі"}},{q="Чому новобранців тримають у Долині Випробувань?",a="Долина Випробувань — відлюдний, захищений каньйон у Дуротарі, призначений, щоб навчати, оцінювати й відсіювати новобранців, перш ніж вони зустрінуть куди смертоносніших звірів, шипогривів і ворожих розвідників ширшого краю.",al={"чому долина випробувань","чому почати тут"}},{q="Чи різниться це завдання для орків і тролів?",a="І молоді орки, і тролі Темного Спису починають навчання разом у Долині Випробувань і отримують від Калтунка той самий вступний заклик до зброї.",al={"вступне завдання тролів","вступне завдання орків"}}},fp="23,330,24.449.0,19.377.0,34.217.0,15.200.0,14.215.0,32.168.0,46.217.0,47.152.0"}
P.entries["subzone:agama-gor"] = {n="Аґама'ґор",s="Аґама'ґор — велике стійбище шипогривів Щетиноспинів на півдні Пусток, трохи на північ від дороги, що веде від Табору Тауражо на захід до Малгору. Це постійна скалка в боці сусідньої застави Орди: тут кишать ворожі шипогриви, які затято тримаються за свою сувору землю.",h="Аґама'ґор — велике стійбище шипогривів Щетиноспинів на півдні Пусток, трохи на північ від дороги, що веде від...",kw={"аґама'ґор","шипогриви","щетиноспини","криваві скалки","табір тауражо","пустки"},ang={["faction:Horde"]="Безпека Табору Тауражо залежить від того, чи вдасться стримувати Щетиноспинів Аґама'ґора, тож знищення їхніх воїнів — першочергова справа для захисників Орди.",["race:Tauren"]="Розбійники Аґама'ґора, що засіли просто на шляху до Великої Брами й Малгору, становлять постійну небезпеку для шляхів постачання й паломників тауренів."},sec={{t="Твердиня Щетиноспинів",b="Аґама'ґор, що розкинувся на курних рівнинах південних Пусток, — укріплене поселення агресивного племені шипогривів Щетиноспинів. Шипогриви, що живуть небезпечно близько від Табору Тауражо, звели тут густу мережу терновиків, хиж і грубих тотемів. Їхня численність становить пряму загрозу для мандрівників між Пустками й трав'янистими пагорбами Малгору, тож розвідники й мисливці Орди ведуть проти них безупинну війну, щоб їх стримати."},{t="Криваві скалки й вигнанець",b="Окрім загальної ворожнечі між Ордою та шипогривами, Аґама'ґор — головне джерело загадкового багряного каміння, відомого як Криваві скалки. Ці геомантичні мінерали, які знаходять у Щетиноспинів із цього селища, дуже цінує Понівечозуб — вигнанець-шипогрив, якого тримають у полоні в Таборі Тауражо. Давні вірування пов'язують скалки зі священною суттю Аґамаґґана, тож шукачі пригод часто нападають на Аґама'ґор, щоб зібрати їх і виміняти на могутні племінні обереги."}},faq={{q="Що таке Аґама'ґор?",a="Аґама'ґор — велике поселення шипогривів Щетиноспинів на півдні Пусток. Воно лежить просто на північ від головної дороги, що веде на захід від Табору Тауражо до Малгору.",al={"огляд аґама'ґора","що за місце вепролюдів","табір вепролюдів біля тауражо"}},{q="Чому шипогриви Щетиноспини тут такі ворожі?",a="Шипогриви вірять, що вся земля, якої торкнувся полеглий прадавній бог-вепр Аґамаґґан, по праву належить їм. Тож Щетиноспини вважають тауренів і орків із сусіднього Табору Тауражо непроханими загарбниками, що зазіхають на їхню родову землю.",al={"чому вепролюди ворожі","ворожість вепролюдів","чому щетиноспини злі"}},{q="Що можна знайти в Аґама'ґорі?",a="Шипогриви Щетиноспини по всьому Аґама'ґору часто носять Кров'яні Скалки — кристалізовані поклади, насичені первісною силою, які можна обміняти у вигнанця-шипогрива Понівечозуба в Таборі Тауражо.",al={"що тут взяти","здобич аґама'ґора","чому вбивати щетиноспинів тут"}},{q="Хто такий Понівечозуб і як він пов'язаний із цим місцем?",a="Понівечозуб — шипогрив-вигнанець, якого тримають у клітці в Таборі Тауражо. Він плекає гірку образу на своїх родичів і охоче наділяє шукачів пригод з Орди захисними оберегами в обмін на Кров'яні Скалки, здобуті в його колишніх братів в Аґама'ґорі.",al={"зв'язок понівечозуба","хто такий понівечозуб","свиня-в'язень тауражо"}}},fp="9,311,24.479.0,22.458.0,18.164.0,49.247.0,31.194.0,56.247.0"}
P.entries["subzone:agamand-family-crypt"] = {n="Родинний Склеп Аґамандів",s="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку однієї з найзаможніших фермерських династій Тірісфалю. Тепер його захопила Погибель під проводом Капітана Дарґола: гробниці розкрито, а сплячих предків піднято безтямними страхіттями.",h="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку...",kw={"родинний склеп аґамандів","аґаманди","склеп","капітан дарґол","погибель","некромантія","тірісфаль"},ang={["race:Undead"]="Для Відступників захоплення склепу Капітаном Дарґолом — нестерпна присутність Погибелі в Тірісфалі, що глумиться з мертвих і загрожує північному кордону Андерсіті."},sec={{t="Неспокійні предки",b="До Третьої війни родина Аґамандів володіла великими маєтками по північних Галявинах Тірісфалю й ховала своїх предків у цьому мавзолеї на схилі пагорба. Коли Чума принесла королівству руїну, склеп потрапив у лабети Капітана Дарґола, агента Погибелі. Замість дати заможному роду спочивати з миром, Дарґол темною некромантією пробудив поховані скелети й мстиві привиди, перетворивши священне поховання на войовничий плацдарм Погибелі просто на краю земель Відступників."}},faq={{q="Де Родинний Склеп Аґамандів?",a="Склеп висічено в схилі пагорба трохи на північ від Млинів Аґаманда, на півночі Галявин Тірісфалю.",al={"місце склепу аґамандів","де склеп","як знайти склеп аґамандів"}},{q="Хто нині контролює склеп?",a="Гробницю утримує Капітан Дарґол — прислужник Погибелі, що спрямовує темну магію всередині й командує піднятими мерцями.",al={"хто в склепі аґамандів","бос склепу","капітан дарґол"}},{q="Що мене чекає в склепі?",a="Склеп повний пробуджених кістяків і неспокійних духів предків Аґамандів. Ведені темною магією, ці мстиві мерці нападають на кожного, хто ступає до гробниць.",al={"вороги склепу","що всередині склепу аґамандів","мобі склепу аґамандів"}},{q="Чи нежить у склепі — союзники Відступників?",a="Ні. Створіння всередині — раби Погибелі, підвладні Капітанові Дарґолу, тож вони ворожі і до Відступників, і до живих мандрівників.",al={"чи вони відступники","склеп аґамандів дружній","чому нападати на нежить"}}},fp="20,295,18.535.0,42.109.0,33.129.0,39.175.0,57.144.0"}
P.entries["subzone:agmond-s-end"] = {n="Кінець Аґмонда",s="Кінець Аґмонда — покинуті дворфські розкопки серед південних пагорбів Пустищ. Колись це була багатообіцяльна розвідувальна експедиція шукача Аґмонда, та табір перетворився на бойню, коли троги, що прогризали собі нори, налетіли на розкопки й убили їхнього провідника.",h="Кінець Аґмонда — покинуті дворфські розкопки серед південних пагорбів Пустищ.",kw={"кінець аґмонда","розкопки","троги","пустища","дворфи","телдурін"},ang={["race:Dwarf"]="Табір — тверезе нагадування про те, як небезпечно розкопувати прадавні землі землян без належної збройної підтримки."},sec={{t="Моторошні розкопки",b="Як і багато місць у посушливих Пустищах, Кінець Аґмонда починався як дворфська справа: розкопати прадавні реліквії й зазирнути в поховану історію землі. Ця мрія раптово обірвалася, коли з довколишніх розколин хлинули люті троги й здолали гірників. Сам Аґмонд загинув під час нападу — звідси й похмура назва місця. Нині зруйновані розкопки цілком заполонили троги Кам'яного Сховища, а потрощені ящики й покинуті інструменти лежать там, де їх кинули."},{t="Самотній сусід",b="Трохи на північ від зруйнованих розкопок стоїть самотній табір Телдуріна Загубленого. Життя по сусідству з лютими трогами навряд чи пішло на користь його розуму, та він — одна з небагатьох душ, що наважуються жити в південній пустелі поблизу приреченого місця."}},faq={{q="Хто такий Аґмонд?",a="Аґмонд був дворфом-шукачем, що очолив розкопки на півдні Пустищ. Його розвідка скінчилася катастрофою: з-під землі вилізли троги й вирізали його разом з експедицією.",al={"хто такий аґмонд","переказ про аґмонда"}},{q="Які істоти живуть у Кінці Аґмонда?",a="Зруйновані розкопки цілком заполонили ворожі троги: вони вирізали дворфів-рудокопів і привласнили розорений табір і довколишні скелі.",al={"мобі кінця аґмонда","хто тут живе"}},{q="Хто живе біля Кінця Аґмонда?",a="Неподалік, на південних пагорбах, отаборився дворф-відлюдник Телдурін Загублений, що настороже стежить за безплідним краєм.",al={"хто поруч","місце телдуріна"}},{q="Навіщо дворфи взагалі тут копали?",a="Дворфи-шукачі часто розвідують Пустища в пошуках артефактів титанів, давніх руїн і багатих рудних жил, хоча чимало таких експедицій недооцінюють лютих створінь, що чаяться під землею.",al={"навіщо дворфи копали","мета розкопок"}}},fp="12,266,21.475.0,17.267.0,15.181.0,36.158.0,28.137.0,49.204.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Лігво Аку'мая",s="Лігво Аку'мая — найглибша й найтемніша печера Чорноглибинних Печер. Ця затоплена западина за Святилищем Місячної Святині — гніздовище Аку'мая, страхітливої гідри, яку шанують як провісника Древніх Богів.",h="Лігво Аку'мая — найглибша й найтемніша печера Чорноглибинних Печер.",kw={"аку'май","гідра","чорноглибинні печери","молот присмерку","древні боги","святилище місячної святині"},ang={["class:Druid"]="Гидка мутація й протиприродна порча, що розходяться від водяного кубла Аку'мая, — тяжка пошесть для природних водойм і звірів Калімдору.",["race:NightElf"]="Для нічних ельфів бачити, як осквернений храм Елуни обернувся на брудне гніздо мерзенного породження Древніх Богів, — нестерпна наруга над священною землею Ашенвалю."},sec={{t="Серце глибин",b="Запечатане за Святилищем Місячної Святині, Лігво Аку'мая — вершина порчі, що охопила Чорноглибинні Печери. Щоб увійти до печери, треба провести темний обряд: запалити чотири жаровні обабіч статуї наги й тим пробудити вартових, що присягнули боронити поріг. За важкими двостулковими дверима лежить затоплений грот, куди не сягає сонце. Тут і культисти Молота Присмерку, і наги-загарбники збираються, щоб шанувати Аку'мая — давню триголову гідру, яку вважають первісним пожирачем і живим слугою Древніх Богів."},{t="Провісник загибелі",b="Через Аку'мая лігво стає осередком апокаліптичних задумів Молота Присмерку. Культисти шанують велетенського звіра як прикмету обіцяної доби темряви й вірять, що його поява й годування провістять падіння підземних в'язниць, де ув'язнено їхніх давніх божеств. Живлене жертвами й ревно захищене темною магією, підземне озеро — похмурий символ давнього зла, що видирається назад у Калімдор."}},faq={{q="Де Лігво Аку'мая?",a="Лігво Аку'мая — у самому кінці печерного комплексу Чорноглибинних Печер в Ашенвалі, одразу за запечатаними дверима Святилища Місячної Святині.",al={"де лігво аку'мая","як дістатися кімнати аку'мая","місце лігва аку'мая"}},{q="Як відчинити двері до Лігва Аку'мая?",a="Подвійні двері до лігва відчиняються, коли запалити чотири обрядові жаровні довкола статуї наги в Святилищі Місячної Святині й відбити хвилі створінь, закликаних їх боронити.",al={"відчинити двері аку'мая","як відімкнути лігво аку'мая","запалити вогні аку'мая"}},{q="Хто живе в цій печері?",a="У печері мешкає Аку'май — велетенська триголова гідра, отруєна прадавніми темними силами, улюбленець і втілення волі Древніх Богів.",al={"хто в лігві аку'мая","що живе в лігві","бос лігва аку'мая"}},{q="Чому культ Молота Присмерку тут поклоняється?",a="Молот Присмерку шанує Аку'мая як провісника кінця світу, чиє піднесення віщує звільнення їхніх темних володарів з підземних в'язниць, щоб зруйнувати світ.",al={"чому сектанти поклоняються аку'маю","молот присмерку лігво аку'мая","чому молот присмерку тут"}}},fp="14,237,19.545.0,17.489.0,32.158.0,44.209.0,31.154.0,50.174.0"}
P.entries["subzone:aldrassil"] = {n="Алдрассил",s="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила. Головний прихисток і місце навчання молодих калдореїв; у його вирізьблених порожнинах знайшли притулок наставники, крамарі та місцеве керівництво.",h="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила.",kw={"алдрассил","тінедол","тельдрассил","дерево","наставники","тенарон стормґріп"},ang={["class:Druid"]="Алдрассил показує схильність калдореїв до живої архітектури, виплеканої з живого дерева без порушення рівноваги лісу.",["race:NightElf"]="Для багатьох молодих калдореїв вирізьблені порожнини й пандуси Алдрассила — перший спогад про громадське життя й основа їхнього раннього навчання."},sec={{t="Серце Тінедолу",b="Здіймаючись над відлюдною долиною Тінедолу, Алдрассил — водночас прихисток і громадський осередок для молодих нічних ельфів, що роблять перші кроки у світі. Усередині й довкола велетенського стовбура цього прадавнього дерева в'ються пандуси, що ведуть повз наставників класів і ремісників до високого сідала, звідки Тенарон Стормґріп наглядає за безпекою гаю. Поки Світове Дерево Тельдрассил тягнеться через увесь обрій, Алдрассил дає безпечну, надійну крону, де новачки опановують своє мистецтво, перш ніж спуститися в неспокійні хащі Калімдору."}},faq={{q="Що таке Алдрассил?",a="Алдрассил — величезне порожнисте дерево й поселення в центрі Тінедолу, на північному сході Тельдрассила. Це початковий прихисток, де молоді нічні ельфи здобувають вишкіл, припаси й настанови.",al={"дерево алдрассил","що таке алдрассил","велике дерево тіньової долини"}},{q="Хто очолює поселення в Алдрассилі?",a="Тенарон Стормґріп наглядає за Тінедолом зі своєї оселі на самій верхівці Алдрассила: він організовує оборону долини й наставляє щойно пробуджених калдореїв.",al={"хто керує алдрассилом","ватажок алдрассила","місце тенарона стормґріпа"}},{q="Які послуги тут можна знайти?",a="У дереві — класові наставники для молодих нічних ельфів-воїнів, розбійників, друїдів, мисливців і жерців, а також місцеві крамарі, зброярі й дарувальники завдань, що дбають про нагальні потреби долини.",al={"наставники алдрассила","торговці алдрассила","що є в алдрассилі"}}},fp="9,254,19.549.0,18.215.0,38.156.0,32.205.0"}
P.entries["subzone:alexston-farmstead"] = {n="Хутір Алекстона",s="Хутір Алекстона — занедбана ферма у Вестфолі, що заросла бур'янами й де никають зіпсовані Вартові Урожаю. Колись тут минуло дитинство міського архітектора Стормвінда Бароса Алекстона, а тепер хутір лежить у руїні, як і більшість житниці довкола.",h="Хутір Алекстона — занедбана ферма у Вестфолі, що заросла бур'янами й де никають зіпсовані Вартові Урожаю.",kw={"хутір алекстона","барос алекстон","ферма","вартові врожаю","вестфол"},ang={["faction:Alliance"]="Ферма нагадує і про тихе працьовите коріння, з якого виросли найкращі уми Стормвінда, і про те, як Альянс досі змагається за захист власних кордонів."},sec={{t="Занепала садиба",b="Хутір Алекстона, що стоїть серед сухих рівнин Вестфолу, — ще одне похмуре свідчення занедбаності королівства. Як і сусідні садиби, ферму покинули господарі, коли краєм прокотився розбій. Нині поля заросли, а механічні Вартові Урожаю, яких лишили доглядати посіви, вийшли з-під контролю й люто нападають на кожного, хто наближається до спустілої хати."},{t="Скромне коріння",b="Попри сумний вигляд, ферма пов'язана з одним із найвідоміших громадян Стормвінда. Барос Алекстон, вправний архітектор, що допоміг спроєктувати частину відбудованої столиці, у юності гнув спину саме на цих полях. Він покинув хутір задовго до заворушень, щоб опанувати ремесло каменяра й будівничого, і лишив серед руїн пам'ятку свого раннього життя."}},faq={{q="Кому належить Хутір Алекстона?",a="Хутір названо на честь родини Бароса Алекстона, міського архітектора Стормвінда. Барос ще хлопчиком обробляв тут землю, а тоді перебрався до столиці вчитися архітектури.",al={"чия це ферма","власник алекстона","чий це хутір"}},{q="Чому ферму покинуто?",a="Як і більшість Вестфолу, хутір покинули через повсюдні заворушення й розбій Братства Дефіас. Королівство не могло дати захисту, тож фермери втекли, а господарство пішло в занепад.",al={"чому ферму покинуто","що сталося з фермою алекстона","хто зруйнував ферму"}},{q="Чому тут на людей нападають механічні опудала?",a="Механічних Стражів Врожаю збудували, щоб обробляти землю й захищати врожай від шкідників. Коли фермери втекли й ніхто їх не доглядав, їхній внутрішній механізм зламався, і вони стали лютими до будь-якої живої істоти.",al={"чому нападають опудала","вороже опудало","ворожі големи жнив"}},{q="Чи сховано щось у хаті?",a="Барос Алекстон лишив у хаті свій компас із часів юності. Мандрівників, що виконують доручення в Стормвінді, іноді просять забрати його з покинутого господарства.",al={"завдання тут","здобич на фермі","предмет бароса"}}},fp="18,240,18.427.0,12.388.0,32.191.0,26.216.0,52.246.0,46.182.0"}
P.entries["subzone:algaz-station"] = {n="Станція Алґаз",s="Станція Алґаз — дворфійська військова застава на північному заході Лох Модану, просто на південь від укріпленого перевалу Дун Алґаз. Її гарнізон горян стереже підступи до північних тунелів, охороняє мандрівників і пильнує прикордоння в бік Багнокраю.",h="Станція Алґаз — дворфійська військова застава на північному заході Лох Модану, просто на південь від...",kw={"станція алґаз","дун алґаз","горяни","перевал","лох модан","багнокрай"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, що мандрують між Лох Моданом і північними болотами, застава — безпечний плацдарм і місце, де можна полагодити спорядження.",["race:Dwarf"]="Для дворфів-мандрівників Станція Алґаз — знайомий символ того, як далеко сягає влада Айронфорджа: королівські шляхи тут під охороною від загроз, що сповзають із гір."},sec={{t="Варта на північному перевалі",b="Станція Алґаз, що стоїть трохи на схід від Перевалу Північної Брами й на південь від Дун Алґаза, — важливий стратегічний дозорний пункт королівства Айронфорджа. Загін дворфійських горян несе тут постійну варту, тримаючи відкритою важливу дорогу між Лох Моданом і північними низинами для торгівлі й пересування військ. Зважаючи на часті загрози з довколишніх пагорбів — від мандрівних звірів до трогів, що наступають, — застава дає втомленим мандрівникам перепочинок, змогу полагодити спорядження й військову підтримку, перш ніж вони вирушать гірськими тунелями."}},faq={{q="Що таке Станція Алґаз?",a="Це військова застава Айронфорджа на північному заході Лох Модану. Вона правує за вартовий пост і перепочинок для горян, що патрулюють гірські перевали на північ до Дун Алґазу.",al={"що за місце","призначення станції алґаз","хто керує станцією алґаз"}},{q="Звідки назва станції?",a="Вона названа на честь Дун Алґазу — величезного дворфійського перевалу й системи тунелів просто на північ від станції, що з'єднує Лох Модан із Багнокраєм.",al={"чому станція так зветься","зв'язок із дун алґазом","значення назви"}},{q="Кого можна зустріти на Станції Алґаз?",a="На заставі несуть службу дворфійські горяни, зокрема Горянин Стормпайк, а також допоміжний люд на кшталт зброяра Ґотора Брумна, що лагодить мандрівникам спорядження.",al={"хто тут","неігрові персонажі станції алґаз","місце гірського стрільця сторміпайка"}}},fp="13,284,26.539.0,22.180.0,36.153.0,34.178.0"}
P.entries["subzone:altar-of-storms-burning-steppes"] = {n="Вівтар Бур (Палаючі Степи)",s="Вівтар Бур, що височіє серед зубчастих скель Палаючих Степів, — темний монумент, присвячений обрядам Скверни й демонічній силі. Зловісне місце утримують чорнокнижники клану Блекрок, що творять мерзенну магію в тіні Шпиля Блекрок. Його темна аура вабить честолюбних адептів тіні з усього Азерота.",h="Вівтар Бур, що височіє серед зубчастих скель Палаючих Степів, — темний монумент, присвячений обрядам Скверни...",kw={"вівтар бур","палаючі степи","блекрок","чорнокнижники","мор'зул","скакун жаху","скверна"},ang={["class:Warlock"]="Вівтар Бур і сусідні відлюдники, Мор'зул Бладбрінґер і Ґорзікі Вайлдайз, — ключова зупинка для чорнокнижників, які шукають матеріали й ритуали, щоб викликати грізного скакуна жаху.",["race:Orc"]="Вівтар — незручне нагадування про темне минуле Старої Орди, коли Рада Тіней Ґул'дана використовувала подібні мерзенні святилища, щоб насичувати огрів і воїнів темним чаклунством."},sec={{t="Спадщина тіні й полум'я",b="Вівтар Бур, зведений під час давніших воєн, щоб спрямовувати руйнівну магію Скверни, — похмурий пам'ятник темним угодам. У Палаючих Степах ці землі контролюють ворожі чорнокнижники клану Блекрок, що правлять окультні ритуали й звертаються до демонічних сил. Неподалік над вівтарем височіє табір відлюдника Ґорзікі Вайлдайза та його господаря Мор'зула Бладбрінґера: ці ренегати вивчають бурхливі енергії вівтаря й готують вимогливі ритуали для честолюбних чаклунів, які прагнуть більшої темної сили."}},faq={{q="Що таке Вівтар Бур?",a="Це осквернений кам'яний пам'ятник, на якому правлять темні обряди Скверни й спрямовують демонічну енергію. Збудований за часів воєн Старої Орди, він досі лишається діючим осередком темної сили, яку використовують чорнокнижники Блекрок.",al={"переказ про вівтар бур","що за вівтар","вівтар палаючих степів"}},{q="Хто нині контролює вівтар?",a="Ворожі чорнокнижники й послушники з клану орків Блекрок захопили землю довкола вівтаря: вони правлять темні церемонії й стережуть своє місце від непроханих гостей.",al={"хто біля вівтаря бур","вороги вівтаря бур","хто тут живе"}},{q="Хто такий Ґорзікі Вайлдайз?",a="Ґорзікі Вайлдайз — дивакуватий гоблін, знавець темних мистецтв, що мешкає на пагорбі над вівтарем разом зі своїм господарем Мор'зулом Бладбрінґером. Він допомагає могутнім чорнокнижникам, що прагнуть опанувати сильніші демонічні узи.",al={"ґорзікі вайлдайз","орк на пагорбі","хто такий ґорзікі"}}},fp="33,324,28.524.0,28.203.0,33.181.0,25.235.0"}
P.entries["subzone:alterac-mountains"] = {n="Гори Альтерак",s="Гори Альтерак — порізаний, засніжений хребет, що здіймається просто над пологими пасовищами Гілсбреда. Колись серце гордого людського королівства, тепер на їхніх схилах — зруйновані поселення, розбійницькі угруповання й небезпечна дика місцина, де мандрівники рідко ходять без охорони.",h="Гори Альтерак — порізаний, засніжений хребет, що здіймається просто над пологими пасовищами Гілсбреда.",kw={"гори альтерак","перенольд","синдикат","странбрад","огри","гілсбред"},ang={["class:Rogue"]="Гірські перевали кишать агентами Синдикату й найманими головорізами, тож ці пагорби — чудове випробувальне поле для виживання й контррозвідки.",["faction:Alliance"]="Для Альянсу Альтерак — гіркий пам'ятник зраді, де віроломство Перенольда мало не прирекло людство під час Другої війни."},sec={{t="Занепале королівство",b="Задовго до того, як пагорби поринули в хаос, це нагір'я було суверенним королівством Альтерак — одним із семи королівств, що постали з давнього Аратора. Ця спадщина розбилася під час Другої війни, коли король Ейден Перенольд уклав таємну угоду зі Старою Ордою, дозволивши оркам пройти крізь гори в обмін на безпеку свого королівства. Альянс Лордерона викрив зраду й скинув Перенольда, залишивши край розколотим воєнним станом і суперечками за землю."},{t="Дикі краї й розбійники",b="Після спустошень Третьої війни гори остаточно поринули в беззаконня. Позбавлені спадку вельможі королівства об'єдналися в Синдикат: вони діють із руїн Странбрада й замишляють повернути втрачену владу диверсіями й убивствами. Між лютими ограми Трощихребтами, що засіли в зруйнованій столиці, розбійними гнолами й зруйнованими магічними руїнами довкола Даларана перевали Альтерака лишаються одними з найнебезпечніших шляхів Лордерона."}},faq={{q="Яке королівство колись володіло цими горами?",a="Людське королівство Альтерак володіло цими горами впродовж поколінь після розпаду Імперії Аратор. Його столиця стояла серед найвищих вершин і панувала над дорогами між Лордероном, Далараном і Аратійським нагір'ям, доки не впала в Другій війні.",al={"хто володів альтераком","що було альтераком","королівство альтерак"}},{q="Чому Альтерак у руїнах?",a="Під час Другої війни Король Ейден Перенольд зрадив Альянс Лордерона, допомагаючи Орді. Коли зраду викрили, армії Альянсу розгромили війська Альтерака й позбавили династію корони. Без законного правителя й після спустошень Третьої війни королівство розсипалося на руїни.",al={"що сталося з альтераком","хто зруйнував альтерак","історія руїн альтерака"}},{q="Хто такий Синдикат, що ховається в пагорбах?",a="Синдикат — злочинне угруповання з колишньої шляхти Альтерака та її челяді. Під проводом Алідена Перенольда вони наймають розбійників, убивць і найманців-ренегатів, щоб розхитати край у надії силою відновити своє королівство.",al={"хто синдикат","що таке синдикат","чому розбійники в альтераці"}},{q="Які загрози чатують на засніжених вершинах?",a="Мандрівникам, що наважаться піднятися схилами, доведеться мати справу з жорстокими ограми Трощихребтами, зграями гірських гнолів, кобольдами-мародерами й розбійниками Синдикату, що патрулюють перевали.",al={"що живе в альтераці","чудовиська альтерака","загрози альтерака"}}},fp="17,274,14.492.0,22.502.0,42.266.0,24.302.0,43.246.0,36.195.0"}
P.entries["subzone:alterac-mountains-classic"] = {n="Гори Альтерак (класика)",s="Гори Альтерак — суворе, вічно захмарене нагір'я, що круто здіймається на північ від Передгір'я Гілсбреда; його зубчасті вершини вкриває вічний сніг. Колись тут було людське королівство Альтерак і вчені твердині Даларану, а нині край здебільшого лежить у руїнах, і за нього б'ються жорстокі огри, розбійники шляхетного роду та ворожі армії Долини Альтерак.",h="Гори Альтерак — суворе, вічно захмарене нагір'я, що круто здіймається на північ від Передгір'я Гілсбреда...",kw={"гори альтерак","альтерак","синдикат","странбрад","даларан","огри","долина альтерак"},ang={["class:Rogue"]="У відлюдній гірській долині на кордоні Альтераку ховається Маєток Рейвенголдт — давня оселя братства злодіїв і вбивць на чолі з Лордом Джорахом Рейвенголдтом.",["faction:Alliance"]="Альянс тримає в цих замерзлих пагорбах передову заставу під проводом Лейтенанта Гаґґердіна: тут набирають стійких бійців на підмогу дворфійській Варті Стормпайків у Долині Альтерак."},sec={{t="Зруйноване нагір'я",b="Гори Альтерак, що високо здіймаються над низинами Гілсбреда, — суворий край дощів, сосон і високогірних снігів. Колись тут трималися три великі людські сили — гірське королівство Альтерак, магократія Даларан і укріплене містечко Странбрад, — але зрада й війна звели край нанівець. Нині в зруйнованій столиці Альтераку отаборилися огри Трощихребти, Странбрад захопили розбійники, а уламки Даларану сховані під мерехтливим непрозорим фіолетовим куполом, поки вцілілі чарівники невтомно відновлюють своє зруйноване пристановище."},{t="Розбійники, звірі й війна",b="Крім місцевих гірських левів і єті, що никають обмерзлими хребтами, за нагір'я змагаються й відчайдушні смертні угруповання. Синдикат — позбавлені маєтностей людські вельможі, що подалися в розбійники, — орудує клинком і засідками зі старих садиб і таборів у передгір'ях, безупинно б'ючись з ограми, які дедалі глибше вдираються в їхні землі. А глибокі перевали до високих скель правлять за табори у кривавій війні між Експедицією Стормпайків і кланом Морозного Вовка за потаємні закутки Долини Альтерак."}},faq={{q="Що сталося з королівством Альтерак?",a="Альтерак зганьбився в Другій війні, коли його правитель, Король Ейден Перенольд, зрадив Великий Альянс, щоб допомогти Орді. Після війни королівство розформували. Без проводу його міста занепали, Странбрад перетворився на руїну, а столицю захопили брутальні огри Трощихребти.",al={"чому альтерак у руїнах","хто правив альтераком","падіння альтерака"}},{q="Хто ці розбійники Синдикату в горах?",a="Синдикат — злочинна організація, що складається переважно з колишньої шляхти Альтерака та її челяді. Утративши після зради Альтерака землі, становище й статки, вони взялися за шпигунство, вбивства й грабіж на дорогах, щоб повернути землі, які вважають своїми по праву.",al={"хто синдикат","чому розбійники в альтераці","бандити альтерака"}},{q="Що за величезний фіолетовий купол на березі озера?",a="Цей непроникний магічний купол оточує руїни Даларана. Після того як владика демонів Архімонд зрівняв місто з землею в Третій війні, уцілілі маги Кірін-Тору звели захисний бар'єр від Погибелі й Відступників, а під ним таємно відбудовують свої зруйновані вежі.",al={"фіолетова бульбашка в альтераці","що за бульбашка даларана","магічний щит даларана"}},{q="Як дістатися до Гір Альтерак?",a="Зазвичай мандрівники приходять пішки з Передгір'я Гілсбреда — північними дорогами від Таррен Мілла чи на північ від Саутшора. А сміливі плавці можуть перепливти Озеро Лордамер на південний схід від берегів Срібнолісся чи околиць Андерсіті.",al={"як дістатися альтерака","вхід до альтерака","шлях до альтерака"}}},fp="27,359,20.584.0,24.503.0,40.308.0,47.304.0,50.292.0,35.283.0"}
P.entries["subzone:alther-s-mill"] = {n="Млин Альтера",s="Млин Альтера — зруйнована лісопильня серед скелястих пагорбів на північний схід від Лейкшира в Горах Редріджу. Колись важливе джерело обробленої деревини для місцевих будівничих, покинуте обійстя стало притулком для диких стерв'ятників і хижаків. Для шукачів пригод, що прямують на схід до Кам'яної Варти, напіврозвалені будівлі — похмурий орієнтир, що позначає межу безпечних прикордонних земель.",h="Млин Альтера — зруйнована лісопильня серед скелястих пагорбів на північний схід від Лейкшира в Горах Редріджу.",kw={"млин альтера","лісопильня","гори редріджу","лейкшир","зламування замків","розбійники"},ang={["class:Rogue"]="Пройдисвіти Альянсу добре знають Млин Альтера: злодійські спілки використовують розкидані, забуті скриньки й відлюдну місцину як тихий полігон, щоб тренуватися в делікатному мистецтві зламування замків.",["faction:Alliance"]="Зруйнований млин — ще одне суворе нагадування про виснажені прикордонні гарнізони Стормвінда: цінне господарство лежить у руїні просто на виду в Лейкшира."},sec={{t="Покинутий прикордонний млин",b="Доки край не став здобиччю хижаків і орочих набігів, Млин Альтера вирував торгівлею деревиною, з якої будували Лейкшир і навколишні поселення. Тиха галявина на північний схід від Озера Незрушного давала зручний доступ до гірських лісів. Коли смута в Королівстві Стормвінд наростала, а клан Блекрок насунув із висот Кам'яної Варти, місцеві мельники покинули лісопильню, і сухі дерев'яні будівлі разом із колесом почали гнити."},{t="Тіні й мотлох",b="Без людей млин заполонили страхітливі тарантули, стерв'ятники й зухвалі грабіжники. Мандрівники, що зрізають дорогу до східних перевалів, мусять обережно обходити його затінені околиці. Останніми роками покинутим обійстям скористалися й тіньові ділки та злодії: серед розкиданих ящиків і в потаємних закутках вони відточують заборонене ремесло зламування замків і проворачують таємні оборудки подалі від очей міської варти Лейкшира."}},faq={{q="Що таке Млин Альтера?",a="Млин Альтера — зруйнована лісопильня на північний схід від Лейкшира в Горах Редріджу. Колись вона заготовляла й обробляла деревину для довколишніх поселень, доки дедалі більші небезпеки нетрів не змусили її покинути.",al={"млин альтера","що це за місце","що це за млин","що було млином альтера"}},{q="Чому млин покинуто?",a="Коли після Першої й Другої воєн оборона краю ослабла, агресивні звірі на кшталт велетенських павуків і набіги орків Блекрок зробили роботу на прикордонні надто небезпечною для простих робітників без захисту королівського війська.",al={"чому покинуто","хто покинув млин альтера","що сталося з мельниками"}},{q="Які істоти никають довкола млина?",a="Подвір'я й навколишні чагарники заполонили здебільшого велетенські гірські тарантули, стерв'ятники й хижаки, а ще — заблукані мародери, що ходять між Кам'яною Вартою й Озером Незрушним.",al={"вороги млина альтера","істоти біля млина","що тут живе"}},{q="Навіщо розбійники навідуються до Млина Альтера?",a="Відлюдне, завалене уламками подвір'я — улюблене місце випробувань для розбійників Альянсу: наставники посилають їх сюди вправлятися у зламуванні замкнених скринь і здобувати цінні злодійські свідоцтва.",al={"завдання розбійника біля млина","відмичка біля млина альтера","свідоцтво злодія"}}},fp="13,425,26.491.0,17.485.0,22.230.0,26.247.0,36.205.0,34.215.0"}
P.entries["subzone:amberstill-ranch"] = {n="Ранчо Амберстілл",s="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру Гол'Болар. Це головне місце, де розводять і тренують славетних гірських баранів Айронфорджа. Шукачі пригод навідуються сюди, щоб придбати витривалого дворфського скакуна, навчитися верхової їзди або допомогти родині захистити худобу від місцевих хижаків.",h="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру...",kw={"ранчо амберстілл","барани","скакуни","верхова їзда","дун мороґ","вендіго"},ang={["faction:Alliance"]="Міцні барани, вирощені Амберстіллами, дають Альянсу надійну кавалерію для холодного клімату, придатну для суворої гірської місцевості.",["race:Dwarf"]="Для дворфських шукачів пригод ранчо — предмет гордості й культурна основа: саме тут молоді герої здобувають свого першого барана породи Барак Тор'ол."},sec={{t="Домівка гірських баранів",b="Притулившись до скель Дун Мороґу, Ранчо Амберстілл славиться на весь Каз Модан найвитривалішими гірськими баранами Східних Королівств. Родина Амберстіллів порядкує в стайнях і загонах, навчаючи цих твердоногих тварин долати підступні снігові перевали й круті альпійські урвища. Окрім постачання їздових скакунів і свійської худоби, родині часто доводиться відбиватися від дикої звірини пагорбів — особливо від вендіго, яких приваблює запах свіжої отари."}},faq={{q="Чим славиться Ранчо Амберстілл?",a="Ранчо — головний осередок Альянсу з розведення гірських баранів Барак Тор'ол. Дворфи й шановані звитяжці Альянсу приходять сюди вчитися їзди верхи на баранах і купувати їздових тварин у місцевих конюхів.",al={"призначення амберстілл","навіщо йти на амберстілл","барани амберстілла"}},{q="Чи можуть тут купити їздових тварин не дворфи?",a="Баранів здавна дають лише дворфам, які розуміють їхню вперту вдачу. Представники інших рас Альянсу можуть навчитися їздити на них і купити їх, лише здобувши найвищу довіру й звеличення в Айронфорджі.",al={"купити барана не дворфу","людина купує барана","вимоги до скакуна барана"}},{q="Які загрози чатують на ранчо?",a="Отарі постійно загрожують голодні вендіго, що спускаються з крижаних круч. Найгорезвісніший хижак на навколишніх висотах — Ваґаш, велетенський вендіго, що раз у раз нападає на беззахисну худобу.",al={"небезпека амберстілла","загроза вендіґо","завдання вагаша"}},{q="Чи можна на ранчо отримати ще щось?",a="Юний Ярлін Амберстілл тримає домашніх зайців-біляків і охоче продає зайців у клітках мандрівникам, що шукають собі улюбленця в дорогу.",al={"кролик амберстілла","кролик-снігоступ вихованець","ярлін амберстілл"}}},fp="16,374,25.495.0,35.200.0,37.240.0,33.228.0,42.163.0"}
P.entries["subzone:andorhal"] = {n="Андоргал",s="Колись квітуче хліборобське серце північного Лордерону, Андоргал став епіцентром загибелі королівства під час Третьої війни. Саме тут Кел'Тузад заразив зерно Чумою нежиття, накликавши жах на весь край. Нині зруйноване місто міцно тримає в залізних лещатах Погибель.",h="Колись квітуче хліборобське серце північного Лордерону, Андоргал став епіцентром загибелі королівства під час...",kw={"андоргал","кел'тузад","чума нежиття","утер","срібна длань","культ проклятих","лордерон"},ang={["class:Paladin"]="Андоргал — свята земля, освячена кров'ю Срібної Длані: саме тут Утер Світлоносець і його вірні лицарі прийняли свій трагічний останній бій проти Артаса.",["race:Undead"]="Для Відступників поля Андоргала — гірке нагадування про власне походження: саме тут Культ Проклятих спланував загибель їхнього смертного життя."},sec={{t="Епіцентр чуми",b="До Третьої війни Андоргал був заможною зерновою коморою Іствілду: сюди звозили зерно з усього Лордерону, а звідси розвозили на схід, до Гартглена й Стратгольма. Саме через цю розгалужену мережу постачання Кел'Тузад і Культ Проклятих обрали Андоргал плацдармом для свого жахливого задуму. Отруївши ящики із зерном Чумою нежиття, культ перетворив житницю королівства на рушій некрозу й заразив незліченних мешканців, перш ніж Корона бодай збагнула, що діється."},{t="Падіння Срібної Длані",b="Саме тут принц Артас Менетіл і Джайна Праудмур уперше зустрілися з Кел'Тузадом і вбили його, але смерть некроманта не стала кінцем. Коли Артас повернувся з Нортренду поборником Погибелі, він знову рушив на Андоргал, щоб забрати останки Кел'Тузада. Утер Світлоносець і рештки Срібної Длані прийняли тут відчайдушний останній бій, захищаючи прах короля Теренаса. Паладинів розгромили, Утер загинув від руки свого колишнього учня, а величне поселення перетворилося на оповитий чумною гниллю оплот Погибелі."}},faq={{q="Чому Андоргал такий важливий в історії чуми?",a="Андоргал був головним осередком розподілу зерна на півночі Лордерона. Кел'Тузад скористався цим шляхом постачання: заразив зерносховища Чумою Нежиття й відправив отруєний урожай Королівським Шляхом просто до Стратгольма й сусідніх міст.",al={"як почалася чума тут","чума зерна андоргала","чому андоргал важливий"}},{q="Хто нині контролює Андоргал?",a="Руїни Андоргала міцно тримає Погибель. Вартові-кістяки, некроманти й гулі никають обпаленими вулицями, стережучи осередок своєї першої перемоги в Західних Чумних Землях.",al={"хто править андоргалом","погибель в андоргалі","хто керує андоргалом"}},{q="Чи тут загинув Утер Світлоносець?",a="Так. Після падіння Столиці Утер і його паладини охороняли на околицях Андоргала урну з прахом Короля Теренаса. Артас напав на процесію, щоб забрати урну для решток Кел'Тузада, і зрештою на дорозі зійшовся в поєдинку зі своїм наставником і вбив його.",al={"де загинув утер","смерть утера андоргал","чи артас убив утера тут"}}},fp="8,321,25.521.0,27.529.0,53.272.0,32.206.0,36.273.0"}
P.entries["subzone:angerfang-encampment"] = {n="Табір Анґерфанґ",s="Табір Анґерфанґ — головна твердиня клану Драконячої Пащі в центрі Багнокраю. Ці орки-ренегати на чолі з Вождем Нек'рошем Скаллкрашером використовують розлогий табір як плацдарм, щоб загрожувати сусіднім дворфійським поселенням і плести задуми знищення Гавані Менетіл.",h="Табір Анґерфанґ — головна твердиня клану Драконячої Пащі в центрі Багнокраю.",kw={"табір анґерфанґ","драконяча паща","нек'рош","орки","багнокрай","гавань менетіл","фоліант кабали"},ang={["class:Warlock"]="Темні тіньові вартові в таборі носять Жезли Спрямування — артефакти, необхідні для зв'язувань, описаних у Фоліанті Кабали.",["faction:Alliance"]="Для захисників Гавані Менетіл Анґерфанґ — явна й нагальна загроза: повалити бойові прапори Нек'роша й здобути його голову вкрай важливо, щоб уберегти прибережні торгові шляхи."},sec={{t="Оплот серед драговини",b="Табір Анґерфанґ, що розкинувся в багнюці центрального Багнокраю, — укріплене серце влади Драконячої Пащі в цьому краї. На відміну від розпорошених загонів, що никають болотами, тут є добре захищені барикади, сторожові вежі й грізне військо воїнів, кісткових вартових і темних чаклунів, вірних старим звичаям. Звідси Драконяча Паща простягає свою військову силу на всі болота, нападає на мандрівників на дорогах і загрожує довколишнім дворфійським розкопкам, як-от Місцю Розкопок Велґара."},{t="Амбіції Нек'роша",b="Табором командує Вождь Нек'рош Скаллкрашер, син сумнозвісного чорнокнижника Некроса, який колись поневолив червоних драконів у Ґрім Батолі. Плекаючи глибоку ненависть до Альянсу, Нек'рош стягнув катапульти й підняв бойові прапори, готуючись до генерального штурму Гавані Менетіл. Знаючи про неминучу облогу, командири Альянсу в портовому місті посилають звитяжців у самісіньке черево Анґерфанґа — захопити прапори, розтрощити бойові машини й принести голову Нек'роша, перш ніж його наступ потопить гавань у вогні."}},faq={{q="Хто керує Табором Анґерфанґ?",a="Табором керує Вождь Нек'рош Скаллкрашер, син горезвісного чорнокнижника Драконячої Пащі Некроса Скаллкрашера. Зі свого командного намету в глибині табору Нек'рош спрямовує загони, що грабують край, і планує захопити Гавань Менетіл.",al={"хто керує анґерфанґом","бос анґерфанґа","хто головний тут","табір некроша"}},{q="Чи ці орки — союзники Орди Тралла?",a="Ні. Клан Драконячої Пащі тут не підкоряється Новій Орді Тралла. Вони тримаються темної спадщини Старої Орди й ворожі і до мандрівників Альянсу, і до мандрівників Орди. Воїни Тралла вважають їх здичавілими вигнанцями й навіть полюють на них заради матеріалів для обладунків.",al={"чи драконяча паща орда","чи анґерфанґ дружній до орди","чи анґерфанґ частина орди тралла"}},{q="Чому Альянс прагне знищити цей табір?",a="Капітан Стаутфіст і дворфійські захисники Гавані Менетіл з'ясували, що Нек'рош зібрав в Анґерфанґу катапульти й величезні сили, щоб обстріляти й захопити гавань. Альянс завдає випереджального удару, щоб зірвати облогу, перш ніж вона почнеться.",al={"чому нападати на анґерфанґ","капітан стаутфіст анґерфанґ","чому вбити некроша"}},{q="Чому чорнокнижники шукають цей табір?",a="Темні заклиначі Драконячої Пащі в Анґерфанґу носять Жезли Каналізування — знаряддя темних обрядів, яких прагнуть знавці демонічних мистецтв, щоб завершити Фоліант Кабали.",al={"завдання чорнокнижника анґерфанґ","том кабалу мокрі землі","жезл каналу анґерфанґ"}}},fp="20,284,21.531.0,19.554.1,35.252.0,45.277.0,52.249.0,41.191.0"}
P.entries["subzone:anvilmar"] = {n="Анвілмар",s="Анвілмар — укріплена дворфська застава в засніжених глибинах Долини Холодного Хребта в Дун Мороґу. Збудована довкола величезної кам'яної кузні, вона є головним тренувальним майданчиком і місцем збору молодих дворфів Бронзбірдів та гномських біженців, що починають свої пригоди.",h="Анвілмар — укріплена дворфська застава в засніжених глибинах Долини Холодного Хребта в Дун Мороґу.",kw={"анвілмар","долина холодного хребта","дун мороґ","дворфи","модімус анвілмар","морозогриви"},ang={["race:Dwarf"]="Для дворфів Анвілмар — початок шляху у великий світ; можливо, він носить ім'я давнього Верховного Короля, що колись правив єдиним дворфським королівством.",["race:Gnome"]="Гноми, що знайшли тут прихисток після падіння Гномреґану, зустрічають міцних дворфських союзників, тепле вогнище й наставників, готових допомогти їм призвичаїтися до замерзлої глушини."},sec={{t="Вогнище Холодного Хребта",b="Схований серед північних скель Долини Холодного Хребта, Анвілмар стоїть як незмінний символ дворфської стійкості. Над цим міцним кам'яним комплексом панує ревуча центральна кузня, а всередині знайшли місце наставники класів, торговці припасами та бувалі горяни, які муштрують новобранців, перш ніж відіслати їх у ширше королівство. Хоч поселення й сховане за високими заметами, воно постійно насторожі проти ворожих тролів Морозогривів та лютих диких звірів, що нишпорять замерзлою долиною."},{t="Спадок заліза й тролів",b="Своє горде ім'я поселення, найімовірніше, дістало від Верховного Короля Модімуса Анвілмара — давнього володаря, що правив усіма дворфськими кланами ще до Війни Трьох Молотів. Та його історія не обійшлася без лиха. Колись велетенський троль Морозогрив зумів прорвати оборону й спустошити анклав. Нині гарнізон пильнує, щоб вогонь у кузні не гаснув і подібне лихо більше ніколи не спіткало ці перші тренувальні угіддя."}},faq={{q="Що таке Анвілмар?",a="Анвілмар — дворфійська твердиня й поселення на півночі Долини Холодного Хребта в Дун Мороґу. Це перший збірний пункт і навчальний осередок для щойно набраних шукачів пригод із дворфів і гномів.",al={"що таке анвілмар","місце анвілмара","огляд анвілмара"}},{q="Чому він зветься Анвілмар?",a="Можливо, заставу названо на честь Верховного Короля Модімуса Анвілмара чи роду Анвілмарів. Модімус правив дворфськими кланами ще до Війни Трьох Молотів, але походження назви поселення не підтверджено.",al={"хто був анвілмар","походження назви анвілмар","значення назви"}},{q="Які загрози чатують на Анвілмар?",a="Заставі постійно загрожують місцеві тролі Морозогриви, що засіли серед скель Долини Холодного Хребта, а також небезпечні звірі на кшталт вовків і вендіго. Колись велетенський троль-Морозогрив навіть промчав поселенням, усе трощачи.",al={"вороги анвілмара","хто нападає на анвілмар","загрози анвілмара"}},{q="Чи можна тут опанувати професії?",a="В Анвілмарі гуде кузня, де можна кувати й плавити метал, але наставників ремесел тут немає. Молодим новобранцям доводиться йти глибше в Дун Мороґ — наприклад, до Хараноса чи Айронфорджа, щоб як слід опанувати ремесла.",al={"професії в анвілмарі","кузня анвілмара","ковальство анвілмар"}}},fp="8,291,23.496.0,27.451.0,17.214.0,25.199.0,32.255.0,31.257.0"}
P.entries["subzone:apothecarium"] = {n="Апотекаріум",s="Апотекаріум — південно-західний квартал Андерсіті й осідок Королівського Аптекарського Товариства. У його смердючих лабораторіях алхіміки-Відступники невтомно працюють під проводом Головного Аптекаря Фаранелла, створюючи згубні чуми, отрути й штучно виведені жахіття. Це похмуре серце біологічних досліджень Андерсіті, без якого не обійтися в боротьбі Леді Сильвани проти живих і Погибелі.",h="Апотекаріум — південно-західний квартал Андерсіті й осідок Королівського Аптекарського Товариства.",kw={"апотекаріум","андерсіті","аптекарі","фаранелл","алхімія","чума"},ang={["profession:Herbalism"]="Травники постачають огидним перегонникам Королівського Аптекарського Товариства рідкісні, уражені скверною рослини, зібрані в руїнах північних королівств.",["race:Undead"]="Для Відступників Апотекаріум — кузня їхнього виживання: тут створюють хімічну й зшиту зброю, без якої не втримати Лордерон проти переважаючих ворогів."},sec={{t="Кімната жахів",b="Апотекаріум займає південно-західну терасу підземної столиці — це лабіринт булькотливих чанів, секційних столів і їдких хімічних випарів. Під проводом Головного Аптекаря Фаранелла Королівське Аптекарське Товариство використовує цей квартал, щоб глибше пізнати смертність і тлін. Тут алхіміки й хірурги експериментують із пересадкою тканин, розтинами живих і складанням могутніх гидот. Їхня найголовніша мета, визначена Леді Сильваною Віндраннер, — створити нову чуму, здатну знищити і Погибель, і рештки людей у Лордероні."},{t="Осередок алхімії Відступників",b="Окрім великих військових задумів, квартал — головний осередок практичної алхімії й травництва Орди у Східних Королівствах. Новачки й майстри збираються біля отруйних каналів, щоб переганяти зілля, вивчати хвороби рослин і радитися з досвідченими знавцями."}},faq={{q="Навіщо Апотекаріум?",a="Апотекаріум — дослідницьке й виробниче крило Королівського Аптекарського Товариства. Тут алхіміки Відступників варять дослідні отрути, вдосконалюють Нову Чуму, збирають гидот і навчають алхімії та травництва.",al={"призначення апотекаріума","що тут відбувається","навіщо апотекаріум"}},{q="Хто очолює Апотекаріум?",a="Квартал і його дослідників очолює Головний Аптекар Фаранелл — головний учений Королівського Аптекарського Товариства, що діє з повної влади й під опікою Королеви Сильвани Віндраннер.",al={"хто очолює апотекаріум","хто керує апотекаріумом","фарранелл андерсіті"}},{q="Що намагається створити Королівське Аптекарське Товариство?",a="Головна його мета — виплекати смертоносну Нову Чуму, що має знищити і війська Погибелі Короля-Ліча, і будь-який живий людський опір, який оскаржує землі Відступників у Лордероні.",al={"дослідження чуми відступників","нова чума андерсіті","що вони варять"}},{q="Чи можуть гравці опанувати тут професії?",a="Так. Квартал — головний осередок алхіміків і травників столиці: у його переходах і залах чекають наставники вищого рівня.",al={"наставники апотекаріума","алхімія в андерсіті","наставник травництва андерсіті"}}},fp="12,415,18.603.0,26.285.0,34.255.0,27.202.0,54.199.0,35.144.0"}
P.entries["subzone:astranaar"] = {n="Астранаар",s="Астранаар — головне поселення нічних ельфів у центральному Ашенвалі, збудоване на острові посеред спокійного озера, яке перетинає давня лісова дорога. Це серце діяльності Альянсу в краї: тут мандрівники знаходять надійний притулок від ворожих фурболгів, сатирів та Орди.",h="Астранаар — головне поселення нічних ельфів у центральному Ашенвалі, збудоване на острові посеред спокійного...",kw={"астранаар","ашенваль","нічні ельфи","озеро","валстанн стаґгелм","фурболги"},ang={["faction:Alliance"]="Астранаар — командний пункт Альянсу й головний вузол постачання для походів спірними нетрями Ашенвалю.",["race:NightElf"]="Для калдореїв Астранаар — головний оплот їхньої прадавньої батьківщини в серці Калімдору: він береже священні гаї, а поруч спочиває полеглий герой Валстанн Стаґгелм."},sec={{t="Серце лісу",b="Астранаар, що стоїть на острові посеред лісового озера, — найбільше поселення нічних ельфів в Ашенвалі. З берегом його з'єднують дерев'яні кладки над водою, а в місті живуть вартові, жерці й ремісники, які пильнують ліси. Окрім звичних вигод — корчми, крамарів і вправного шкірника, — на його високих помостах є приборкувач гіпогрифів, з яким можна полетіти до далеких застав Калімдору."},{t="Оплот в облозі",b="Попри спокійні води й сяйливі ліхтарі, Астранаар живе в постійній готовності. Місцеві ватажки на кшталт Рейн Вульфраннер організовують патрулі й оборону від осквернених фурболгів Будякохутрих, що підступають з півночі: тут бояться, що ті наважаться напасти просто на поселення. Місто береже й тиху давню скорботу: за озером, на кладовищі, спочиває Валстанн Стаґгелм, що поліг тисячу років тому у Війні Мінливих Пісків."}},faq={{q="Які послуги є в Астранаарі?",a="Астранаар пропонує мандрівникам Альянсу все необхідне: корчму, крамарів із загальними товарами, наставника-майстра шкірництва й приборкувача летунів, що сполучає з ключовими заставами Ашенвалю й Калімдору.",al={"послуги астранаара","що є в астранаарі","політний майстер астранаара"}},{q="Хто похований на цвинтарі за озером?",a="На цвинтарі біля озера — гробниця Валстанна Стаґгелма, сина Архідруїда Фандрала Стаґгелма, що загинув у давній Війні Рухомих Пісків проти кіраджі в Силітусі.",al={"могила астранаара","могила вальстанна стаґгелма","хто тут похований"}},{q="Чому Вартових в Астранаарі непокоять місцеві фурболги?",a="Фурболги Будякохутрі на півночі потрапили під темний, псувальний вплив. Вартова Рейн Вульфраннер боїться, що, якщо їх не зупинити, дедалі більша агресія підштовхне їх відкрито напасти на сам Астранаар.",al={"чому фурболги непокоять вартових","загроза будякохутрих","завдання рейн вульфраннер"}},{q="Чи можуть гравці Орди безпечно відвідати Астранаар?",a="Ні. Астранаар — сильно укріплена твердиня Альянсу, яку охороняють озброєні Вартові нічних ельфів, що нападають на членів Орди, щойно їх побачать.",al={"чи астранаар дружній до орди","орда в астранаарі"}}},fp="9,315,19.477.0,21.497.0,41.223.0,47.190.0,68.231.0,41.133.0"}
P.entries["subzone:auberdine"] = {n="Обердайн",s="Обердайн — приморське портове містечко нічних ельфів на похмурих берегах Темного Узбережжя, головна морська брама Альянсу до північного Калімдору. Сховане під хмарним небом і порослими соснами кручами, воно з'єднує острівну домівку на Тельдрассилі зі Східними Королівствами й слугує осередком влади серед дикого краю, що наступає.",h="Обердайн — приморське портове містечко нічних ельфів на похмурих берегах Темного Узбережжя, головна морська...",kw={"обердайн","порт","темне узбережжя","тундріс віндвівер","альянс","калімдор"},ang={["faction:Alliance"]="Цей порт — кровоносна жила подорожей і постачання Альянсу на півночі Калімдору: він забезпечує надійне сполучення між Стормвіндом, Айронфорджем і Дарнасусом.",["race:NightElf"]="Для калдореїв, що вирушають із Тельдрассилу, Обердайн — перший справжній осередок на материку, де давні традиції зустрічаються з дивними звичаями й гамірною діяльністю молодших союзників по Альянсу."},sec={{t="Брама до північного Калімдору",b="Обердайн, що лежить на березі Прихованого Моря, — єдине велике поселення, яке встояло на нинішньому Темному Узбережжі. На відміну від відлюдних міст у кронах Тельдрассилу, Обердайн дивиться назовні: це найжвавіший порт Альянсу на півночі. Звідси регулярно ходять кораблі до Гавані Менетіл у Східних Королівствах, а місцеві пороми курсують до Селища Рут'теран біля коріння Світового Дерева. Завдяки торгівлі в Обердайні панує розмаїтіший дух, ніж у традиційних ельфійських анклавах: гості бачать ліхтарі над брукованими вулицями, вивіски дарнаською й всезагальною мовами та заморських купців, серед них дворфів і гномів, що походжають між низькими дерев'яними будинками з арками."},{t="Прихисток в облозі",b="Містечком керують старійшина Тундріс Віндвівер і Рада селища Обердайн, які разом із місцевими Вартовими організовують оборону Темного Узбережжя. Попри роль важливого торгового вузла, високородні мешканці Дарнасуса часто дивляться на Обердайн скоса, вважаючи його торговців, рибалок і чужинців диваками. Містечко постійно потерпає від небезпек краю: агресивні мурлоки нападають на рибальські човни на узмор'ї, осквернені фурболги Чорнолісся тиснуть із півдня, а мерзенна магія, що стікає зі Сквернолісся, бентежить місцевих звірів."}},faq={{q="Куди ходять кораблі з Обердайна?",a="Доки сполучають північ Калімдору з ширшим світом Альянсу. Біля одного причалу стоїть пором до Селища Рут'теран біля підніжжя Тельдрассила, а біля іншого — великі океанські судна, що пливуть через Велике Море просто до Гавані Менетіл у Багнокраї.",al={"кораблі з оберіжина","куди йдуть кораблі","подорож з оберіжина"}},{q="Хто править Обердайном?",a="Обердайном опікується старійшина Тундріс Віндвівер разом із Радою Селища Обердайн. Оборону поселення ведуть Вартові, яких на місці очолює Вартова Ґлінда Нал'Шея.",al={"хто править оберіжином","керівник оберіжина","хто головний"}},{q="Чому в містечку нічних ельфів живуть дворфи й люди?",a="Обердайн — головний порт Альянсу на півночі Калімдору, тож чужоземні торгівці, ремісники й мандрівники прибувають саме сюди. Дворфи влаштували тут кузню, щоб обслуговувати кораблі й подорожніх, і через це містечко незвично різноманітне й гостинне порівняно з традиційними поселеннями нічних ельфів.",al={"чужинці в оберіжині","чому тут дворфи"}},{q="Чому нічні ельфи з Дарнасуса зверхньо дивляться на Обердайн?",a="Прихильники традицій і відлюдності в Дарнасусі часто вважають Обердайн зіпсованим мирською торгівлею й чужоземним впливом. Дехто з ортодоксальних ельфів має його мешканців за диваків, а жвавий торговий осередок, на їхню думку, погано пасує до суворо традиційного друїдського способу життя.",al={"суперництво дарнасуса й оберіжина","вигнанці оберіжина"}}},fp="9,353,28.711.0,19.550.0,35.261.0,20.188.0,60.308.0,57.277.0"}
P.entries["subzone:azurelode-mine"] = {n="Шахта Лазурової Жили",s="Шахта Лазурової Жили — діюча залізна копальня Альянсу в південно-західних пагорбах Передгір'я Гілсбреда. Її охороняє ополчення Саутшора, а працюють тут люди-робітники; надійний видобуток руди живить воєнні зусилля місцевих людей проти Відступників Таррен Мілла.",h="Шахта Лазурової Жили — діюча залізна копальня Альянсу в південно-західних пагорбах Передгір'я Гілсбреда.",kw={"шахта лазурової жили","залізо","саутшор","наглядач бондс","гірництво","гілсбред"},ang={["faction:Horde"]="Удар по Шахті Лазурової Жили відрізає Саутшор від свіжого заліза й прямо підтримує наступ Відступників у Передгір'ї.",["profession:Mining"]="Тунелі всередині й кряжі довкола Шахти Лазурової Жили багаті на залізну руду, хоча рудокопи Альянсу люто стережуть надра."},sec={{t="Жили передгір'я",b="Шахта Лазурової Жили, що лежить на південний захід від відкритих полів і трохи на захід від Саутшора, здавна видобуває багатства з рудних кряжів уздовж узбережжя. До того як запечатали Стіну Ґреймейна, ці пагорби вважалися частиною земель Ґілнеаса. Сьогодні люди-рудокопи працюють глибоко під землею під пильним оком Наглядача Бондса, добуваючи залізо, щоб кувати зброю й обладунки для захисників Альянсу, які тримають край проти Андерсіті."},{t="Важлива воєнна ціль",b="Шахта Лазурової Жили дає більшу частину сирого заліза, потрібного для утримання гарнізонів і міського ополчення Саутшора, тож вона опинилася просто під прицілом Орди. Таррен Мілл раз у раз б'є по її робітниках і охороні, намагаючись перерізати шляхи постачання, що підтримують людські твердині Гілсбреда."}},faq={{q="Хто контролює Шахту Лазурової Жили?",a="Шахту Лазурової Жили контролює Альянс, а працюють у ній людські рудокопи, пов'язані із Саутшором і селищем Гілсбред; на місці за ними наглядає Наглядач Бондс.",al={"хто керує лазуровою жилою","фракція шахти лазурової жили","чия лазурова жила"}},{q="Чому шахта важлива для Орди?",a="Шахта постачає життєво важливе залізо до зброярень Саутшора й місцевого ополчення Альянсу. Провід Таррен Мілла б'є по рудокопах і наглядачах, щоб підірвати виробництво людської зброї в Передгір'ї.",al={"чому нападати на лазурову жилу","битва за шахту гілсбреду","інтерес орди до шахти"}},{q="Чи Шахта Лазурової Жили завжди належала Гілсбреду?",a="Колись суворий хребет, де лежить Шахта Лазурової Жили, був у межах зовнішніх кордонів Ґілнеасу — ще до того, як Король Ґенн Ґреймейн звів Стіну Ґреймейна, відгородивши своє королівство від решти Лордерона.",al={"історія стіни грейманів","чи лазурова жила була гілнеаса","гілнеаська шахта"}},{q="Які метали тут добувають?",a="Шахта здебільшого дає залізну руду для людських зброярень поблизу.",al={"яка руда в лазуровій жилі","ресурси лазурової жили"}}},fp="14,261,22.430.0,23.300.0,28.163.0,39.197.0,44.199.0,27.63.0"}
P.entries["subzone:bael-dun-digsite"] = {n="Розкопки Бел'дуну",s="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору. Закладена загоном Шукача Хазґорма з Бель Модану, вона в очах місцевих тауренів — пряме осквернення прабатьківської землі й образа Земній Матері.",h="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору.",kw={"бел'дун","розкопки","дворфи","ліга дослідників","бель модан","малгор","титани"},ang={["faction:Alliance"]="Хоч копачами Бел'дуну рухає щира жага історичних відкриттів, вони зайшли надто глибоко в суверенні землі Орди, спричинивши криваві сутички з місцевими.",["race:Tauren"]="Рубці від вторгнення на західних пагорбах Малгору роблять Бел'дун прямою образою Земній Матері, що вимагає рішучих дій — захистити прабатьківську землю від чужинського осквернення."},sec={{t="Вторгнення в пагорби",b="Розкопки Бел'дуну, що примостилися на гірських схилах західного Малгору, — найпівденніший форпост експедиції дворфійської Ліги Дослідників, яка базується в Бель Модані в південних Пустках. Не зважаючи ні на кордони, ні на духовні традиції щойно осілих племен, дворфійські шукачі прибули з кирками, лопатами й вибуховим порохом, аби видобути стародавні реліквії титанів, поховані під рівнинами."},{t="Захист Земної Матері",b="Плем'я Бладгуф сприйняло ці загарбницькі розкопки як відвертий напад на Земну Матір. Бейн Бладгуф спершу закликав до обережності й намагався застерегти зайд, та дворфи навідріз відмовилися покинути свої траншеї. Дійшовши висновку, що дипломатія зазнала поразки, таурени постановили потрощити знаряддя експедиції й силою вигнати копачів, поки їхнє руйнівне копання не роздерло священну землю Малгору ще глибше."}},faq={{q="Чому дворфи копають у Малгорі?",a="Шукачі належать до дворфійської експедиції зі штабом у Бель Модані на півдні Пусток. Ведені прагненням Ліги Дослідників знайти давні артефакти й спадщину Титанів, вони заснували цю заставу там, де їхні прилади вказували на реліквії, знехтувавши правом тауренів на ці землі.",al={"чому дворфи тут","дворфи в мулґорі","дворфи бел'дуну"}},{q="Як плем'я Бладгуф ставиться до розкопок?",a="Таурени вважають ці роботи нестерпною раною на тілі Земної Матері. Коли дворфи відмовилися мирно піти після перших попереджень, Бейн Бладгуф і очільники села послали воїнів знищити знаряддя рудокопів і вигнати непроханих гостей із Малгору.",al={"що думають таурени","реакція бейна","відповідь тауренів на розкопки"}},{q="Що пов'язує Бел'дун і Бель Модан?",a="Бел'дун — допоміжні розкопки, засновані просто з фортеці й головних розкопок у Бель Модані, що лежать одразу за гірським хребтом на півдні Пусток.",al={"зв'язок з бель моданом","звідки ці дворфи"}},{q="Чому таурени просто не домовилися з експедицією?",a="Бейн Бладгуф спершу шукав дипломатичних рішень і офіційно попереджав очільників експедиції. Але дворфи вважали Малгор нічийною глушиною й цілком знехтували духовними переконаннями тауренів, тож племені не лишалося нічого, крім сили.",al={"чи таурени пробували мир","дипломатія з дворфами"}}},fp="16,299,22.420.0,26.432.0,35.308.0,52.266.0,55.172.0,59.263.0"}
P.entries["subzone:bael-dun-keep"] = {n="Фортеця Бел'дун",s="Фортеця Бел'дун — грізне дворфійське укріплення над розкопками Бель Модан на півдні Пусток. Під командуванням Генерала Твінбрейда ця фортеця тримає суперечливу присутність Альянсу в краї і втягує його в запеклий конфлікт із довколишніми землями Орди.",h="Фортеця Бел'дун — грізне дворфійське укріплення над розкопками Бель Модан на півдні Пусток.",kw={"фортеця бел'дун","бель модан","дворфи","генерал твінбрейд","стоунспайр","пустки"},ang={["faction:Alliance"]="Ця фортеця — ваш головний військовий плацдарм на півдні Пусток: вона береже цінні відкриття Ліги Дослідників від ворожих сил Орди.",["race:Tauren"]="Фортеця Бел'дун стоїть на священній землі, відібраній у племені Стоунспайр, — образливе нагадування про те, як Альянс зазіхає на вашу батьківщину."},sec={{t="Дворфійська твердиня на Калімдорі",b="Фортеця Бел'дун, збудована за кресленнями дворфійського архітектора Гаґґіса Боутмердера, — укріплене військове серце присутності Айронфорджа на півдні Пусток. Височіючи над широкими траншеями розкопок Бель Модана, вона захищає шукачів і археологів, які розшукують давні артефакти титанів. Гарнізон, добре озброєний залізом і гарматами, пильно стереже дворфійські шляхи постачання й демонструє військову силу Альянсу в самому серці Калімдору."},{t="Осередок кровопролиття",b="Будівництво Фортеці Бел'дун і розкопок поряд не минуло мирно: воно вигнало місцеве плем'я тауренів Стоунспайр з їхньої прадавньої домівки. Тепер Бел'дун — гаряча точка Пусток, що ось-ось вибухне. Ближні застави Орди вважають фортецю зухвалим військовим вторгненням, а Ґанн Стоунспайр веде проти загарбників особисту війну помсти. Між скривдженими тауренами, спритними розвідниками й насторожено ворожими заставами на кшталт Табору Тауражо фортеця постійно під загрозою набігів і диверсій."}},faq={{q="Хто контролює Фортецю Бел'дун?",a="У фортеці стоїть гарнізон дворфійських вояків, підпорядкованих Альянсу й Лізі Дослідників з Айронфорджа, на чолі з непохитним командиром Генералом Твінбрейдом.",al={"хто керує бел'дуном","хто керує фортецею бел'дун","генерал твінбрейд"}},{q="Чому Фортецю Бел'дун збудували на півдні Пусток?",a="Її заснували, щоб боронити Бель Модан — величезну археологічну експедицію, що шукає в Калімдорі реліквії титанів і давні витоки дворфів.",al={"чому дворфи в пустках","призначення бел'дуну","чому дворфи збудували тут"}},{q="Чому місцеві таурени нападають на Фортецю Бел'дун?",a="Розкопки й фортеця вигнали тауренів-Стоунспайрів з їхніх родових земель. Уцілілі на кшталт Ґанна Стоунспайра прагнуть помсти й знищення дворфійських загарбників.",al={"помста ґанна стоунспайра","чому таурени ненавидять бел'дун","ворожнеча стоунспайрів"}},{q="Хто був архітектором фортеці?",a="Дворфійські архітектурні записи свідчать, що фортецю спроєктував і збудував Гаґґіс Боутмердер.",al={"хто збудував фортецю","хеґіс боутмердер","креслення бел'дуну"}}},fp="13,304,32.528.0,25.523.0,27.162.0,51.142.0,49.187.0,38.102.0"}
P.entries["subzone:bael-modan"] = {n="Бель Модан",s="Бель Модан — укріплена дворфійська застава й місце археологічних розкопок на півдні Пусток. Її заснували дворфи-копачі, що шукають давні реліквії Титанів, і ця добре озброєна споруда розпалила запеклий конфлікт, вигнавши корінних тауренів Стоунспайр.",h="Бель Модан — укріплена дворфійська застава й місце археологічних розкопок на півдні Пусток.",kw={"бель модан","розкопки","ліга дослідників","сльоза місяців","фіґлі вигнанець","стоунспайр"},ang={["race:Dwarf"]="Розкопки — свідчення невтомного прагнення Ліги Дослідників розкрити історію Титанів, хоча грубі методи її командирів накликали люту ворожнечу місцевих племен.",["race:Tauren"]="Бель Модан — відкрита рана Пусток, збудована на руїнах священної землі племені Стоунспайр. Допомогти Ґаннові Стоунспайру помститися — справа племінної честі."},sec={{t="Відкопані таємниці й кров",b="Бель Модан — це укріплена Фортеця Бел'дун, ряд велетенських облогових гармат, майданчики для гірокоптерів і глибокий відкритий котлован. Дворфи-шукачі прибули на Калімдор, переконані, що під червоною землею похована давня споруда Титанів. Проте їхні вибухові роботи прорвалися просто крізь священну землю тауренів Стоунспайр. Замість домовлятися, дворфійська експедиція прогнала Стоунспайрів з прадавніх земель рушничним вогнем і вибухівкою, і вцілілі одноплемінники розсіялися, сповнені жаги помсти."},{t="Ціна відкопаних реліквій",b="Розкопки виявили значно більше, ніж давню кладку. Нещодавно дворфи-копачі відкопали артефакт, відомий як Сльоза Місяців, — реліквію, що викликає параною й божевілля в тих, хто поруч. Один вигнаний шукач, Фіґлі Вигнанець, цілком піддався її впливу — і щойно камінь знову опинився в його руках, обернувся на трога. Між смертоносними реліквіями й розлюченими тауренами, що шукають відплати за брамою, дворфійський табір постійно в небезпеці."}},faq={{q="Чому дворфи копають у Пустках?",a="Дворфи шукають давні споруди й реліквії Титанів, поховані під Калімдором. Їхні розкопки — частина ширшої експедиції, що прагне з'ясувати походження їхньої раси, яке, як вони вірять, пов'язане з похованими дослідницькими осередками Титанів.",al={"чому дворфи копають","призначення бель модана","що шукають дворфи"}},{q="Що сталося з тауренами, які тут жили?",a="Колись ця земля належала племені Стоунспайр, яке вважало ці пагорби святими. Прибувши, дворфи підірвали місце розкопок вибухівкою, вирізали чи вигнали тауренів і знищили їхнє село.",al={"таурени стоунспайр","хто жив у бель модані","село тауренів"}},{q="Хто такий Ґанн Стоунспайр?",a="Ґанн Стоунспайр — один із небагатьох уцілілих із племені Стоунспайр. Після того як спроби мирно владнати справу провалилися, він отаборився біля дороги під Бель Моданом і закликає мандрівників з Орди нищити дворфійські літальні машини й убивати офіцерів, винних у руйнуванні домівки його народу.",al={"ґанн","видавець ґанн"}},{q="Що таке Сльоза Місяців?",a="Сльоза Місяців — загадковий артефакт, який викопали дослідники. Він доводить до божевілля смертних, що беруть його до рук, і вигнанець-дворф Фіґлі став одержимим думкою повернути його.",al={"реліквія сльоза місяців","артефакт фіґлі"}}},fp="10,281,31.560.0,29.490.1,39.246.0,50.245.0,23.302.0,30.181.1"}
P.entries["subzone:bal-lal-ruins"] = {n="Руїни Бал'лал",s="Руїни Бал'лал — прадавні руїни тролів Ґурубаші на північно-західному узбережжі Долини Стренглторну, трохи на північ від Базового Базового Табору Ґром'ґол. Ці кам'яні підмурки, що розсипаються над каламутними водами Мерзотного Рифу, нині захопили ворожі тролі Кривавого Скальпа.",h="Руїни Бал'лал — прадавні руїни тролів Ґурубаші на північно-західному узбережжі Долини Стренглторну, трохи на...",kw={"руїни бал'лал","ґурубаші","кривавий скальп","тролі","долина стренглторну","риф"},ang={["faction:Horde"]="Бал'лал лежить трохи далі узбережжям від Базового Базового Табору Ґром'ґол, і тролі Кривавого Скальпа там — постійна докука для патрулів Орди вздовж берега.",["race:Troll"]="Для тролів Темного Списа, що стоять за Орду, такі місця, як Бал'лал, — тверезий погляд на руїни давньої слави Ґурубаші, які тепер тримають споріднені племена, засліплені невгамовною жагою крові."},sec={{t="Зруйнована застава над рифом",b="Руїни Бал'лал на узбережжі на північ від Базового Базового Табору Ґром'ґол — ще один уламок розтрощеної Імперії Ґурубаші. Колись це була частина величної тролячої цивілізації, що панувала на півдні Азероту, а тепер від неї лишилися порослі мохом кам'яні мури й потріскана кладка. Руїни прилягають просто до Мерзотного Рифу, і з них видно підступні прибережні мілини. Нині тут хазяйнують агресивні тролі Кривавого Скальпа, що люто боронять від чужинців вивітрені реліквії своїх предків."}},faq={{q="Хто контролює Руїни Бал'лал?",a="Нині руїни захопили тролі з племені Кривавий Скальп, які люто стережуть свою територію від чужинців, мандрівників і суперників.",al={"хто тут живе","мобі руїн бал'лал","хто на руїнах бал'лал"}},{q="Де Руїни Бал'лал?",a="Вони на північно-західному узбережжі Долини Стренглторну, просто на північ від Базового Базового Табору Ґром'ґол, з видом на Мерзенний Риф.",al={"місце руїн бал'лал","де руїни бал'лал","як знайти руїни бал'лал"}},{q="Яка історія цих руїн?",a="Як і більшість кам'яних споруд, розкиданих Долиною Стренглторну, Руїни Бал'лал сягають часів давньої Імперії Ґурубаші — ще до того, як вона розпалася на ворогуючі племена джунглевих тролів.",al={"переказ про бал'лал","історія руїн бал'лал","хто збудував бал'лал"}}},fp="13,269,31.527.0,27.153.0,36.151.0,33.193.0"}
P.entries["subzone:balia-mah-ruins"] = {n="Руїни Балія'ма",s="Руїни Балія'ма — порослі мохом рештки прадавнього поселення Ґурубаші на півночі Долини Стренглторну. Ці кам'яні тераси, що розсипаються, лежать на схід від Базового Базового Табору Ґром'ґол, по той бік річки, і нині їх захопили й стережуть воїни ворожого тролячого племені Череполомів.",h="Руїни Балія'ма — порослі мохом рештки прадавнього поселення Ґурубаші на півночі Долини Стренглторну.",kw={"руїни балія'ма","ґурубаші","череполоми","тролі","долина стренглторну","ґром'ґол"},ang={["faction:Horde"]="Ворожі Череполоми в Балія'ма, що засіли просто за річкою від Базового Базового Табору Ґром'ґол, — постійна загроза для розвідників і шляхів постачання Орди.",["race:Troll"]="Для тролів Темного Списа прогулянка цими прадавніми кам'яними терасами нагадує і про горду цивілізацію Ґурубаші, спільну для їхніх предків, і про темні чвари, що розірвали суспільство тролів джунглів."},sec={{t="Розтрощена спадщина",b="Як і чимало кам'яних споруд, розкиданих джунглями, Балія'ма — уламок розлогої Імперії Ґурубаші, що колись панувала на більшій частині півдня Східних Королівств. Після падіння давньої столиці землі Ґурубаші розкололися на ворожі угруповання. Нині руїни — твердиня племені Череполомів, які люто боронять кам'яні тераси від бродячих звірів, сусідніх огрів із кургану Мош'Оґґ і всіх чужинців, яким стане дурості перейти річку."}},faq={{q="Де Руїни Балія'ма?",a="Руїни — на півночі Долини Стренглторну, на схід-південний схід за річкою від застави Орди Базовий Табір Ґром'ґол і на південний захід від Кургану Огрів Мош'Оґґ.",al={"місце балі'ма","де балія'ма","карта руїн балія'ма"}},{q="Хто нині контролює руїни?",a="Нині руїни захопило плем'я Череполомів — вороже угруповання джунглевих тролів, що люто стереже давні кам'яні тераси.",al={"хто живе в балія'ма","які мобі в балія'ма","вороги балія'ма"}},{q="Яка історія Балія'ма?",a="Цей комплекс збудували за розквіту Імперії Ґурубаші. Коли імперія впала, місце занепало, і врешті його поглинули джунглі та вцілілі племена тролів.",al={"переказ про балія'ма","хто збудував балія'ма"}},{q="Чи пов'язані Череполоми в Балія'ма з іншими таборами тролів?",a="Так. Плем'я Череполомів має кілька таборів і руїн на півночі й у центрі Долини Стренглторну й веде безперервну війну за землі із суперницькими племенами, як-от Кривавий Скальп.",al={"череполоми в штормовій гущавині","череполоми балія'ма"}}},fp="15,283,20.498.0,38.164.0,33.148.0,33.200.0,67.205.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="Курганне Лігво Бан'етіл",s="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила. Створене як місце спочинку для сплячих Друїдів Кігтя, печерний комплекс нещодавно поринув у хаос. Зіпсуті фурболги племені Вузлошкірів заполонили його зали, перетворивши місце мирного сну на небезпечне лігво божевілля.",h="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила.",kw={"курганне лігво бан'етіл","бан'етіл","друїди кігтя","фурболги","вузлошкіри","смарагдовий сон","тельдрассил"},ang={["class:Druid"]="Бан'етіл — священна земля для Кола Кенарія, збудована саме для того, щоб захищати Друїдів Кігтя, поки ті єднаються зі Смарагдовим Сном.",["race:NightElf"]="Захоплення Бан'етілу зіпсутими фурболгами-Вузлошкірами — тривожна ознака хвороби, що шириться їхньою новою домівкою, Тельдрассилом."},sec={{t="Осквернене святилище",b="Курганні лігва — священні покої спочинку, де друїди нічних ельфів сплять, посилаючи свій дух у Смарагдовий Сон. Курганне Лігво Бан'етіл було призначене саме для Друїдів Кігтя, що єднаються з природою. Поділене на верхні й нижні підземні покої, лігво колись бриніло тихою задумою й глибокою магією медитації. Та недуга, що охопила живність Тельдрассила, не оминула й фурболгів-Вузлошкірів: вони вдерлися до комплексу й перетворили його видовбані зали на укріплене кубло."},{t="Вторгнення Вузлошкірів",b="Збожеволілі від таємничої скверни, що пускає коріння по всьому Світовому Дереву, Вузлошкіри вигнали сплячих друїдів із Бан'етілу або поставили їх під загрозу. Тепер фурболги люто стережуть звивисті тунелі й нападають на кожного нічного ельфа, що наближається. Для захисників Тельдрассила повернути курганне лігво — нагальне завдання: не лише щоб відігнати ворожих фурболгів, а й щоб захистити вразливих друїдів і священні реліквії, замкнені в нижніх глибинах."}},faq={{q="Що таке Курганне Лігво Бан'етіл?",a="Курганне Лігво Бан'етіл — підземна западина на Тельдрассилі, створена нічними ельфами. Її збудували як прихисток для сплячих Друїдів Кігтя, поки їхні духи мандрують Смарагдовим Сном.",al={"що таке бан'етіл","призначення бан'етіл","що це за печера"}},{q="Чому в Курганному Лігві Бан'етіл фурболги?",a="Фурболги Вузлошкіри стали жертвами скверни, що поширюється серед створінь Тельдрассила. Ставши ворожими й ревно стережучи свою територію, вони вдерлися до курганного лігва, витіснили доглядачів і загрожують сплячим друїдам.",al={"чому фурболги в бан'етіл","будякохутрі в бан'етіл","хто захопив бан'етіл"}},{q="З яких частин складається курганне лігво?",a="Печерний комплекс поділяється на два головні пов'язані яруси: Верхнє Лігво біля вхідних ходів і Нижнє Лігво глибше серед підземного коріння.",al={"розташування бан'етіл","верхнє лігво нижнє лігво","рівні бан'етіл"}},{q="Чому курганні лігва такі важливі для друїдів?",a="Курганні лігва дають безпечний прихисток друїдам, що поринають у тривалий глибокий сон, аби перенести свою свідомість до Смарагдового Сну, — адже їхні тіла роками чи десятиліттями лишаються беззахисними.",al={"чому друїди сплять в лігвах","переказ про курганні лігва друїдів","курганне лігво смарагдового сну"}}},fp="20,368,19.540.0,23.472.0,29.189.0,51.224.0,40.159.0,43.209.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="Лощина Бан'етіл",s="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і Дарнасусом. Вона стала небезпечним прихистком для зіпсутих, агресивних фурболгів, які постійно загрожують подорожнім. У глибині яру ховається вхід до Курганного Лігва Бан'етіл.",h="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і...",kw={"лощина бан'етіл","бан'етіл","яр","фурболги","доланаар","дарнасус","тельдрассил"},ang={["class:Druid"]="Лощина ховає вхід до Курганного Лігва Бан'етіл — священної землі, де друїди традиційно спочивають, єднаючись зі Смарагдовим Сном, а тепер їм загрожує скажена живність.",["race:NightElf"]="Бачити, як фурболги божеволіють так близько до дороги між Доланааром і Дарнасусом, — похмурий знак дедалі тяжчої хвороби Тельдрассила, що вимагає втручання молодих вартових і друїдів."},sec={{t="Небезпечний яр",b="Лощина Бан'етіл, що лежить осторонь шляху між Доланааром і Дарнасусом, — різке нагадування, що гілля Тельдрассила не зовсім безпечне. Фурболги, збожеволілі від дивної недуги, яка мучить Світове Дерево, знайшли притулок по всьому скелястому спуску. Вони часто чатують біля стежки, вичікуючи необачних гінців і мандрівних вартових, щоб напасти із засідки. У глибині яру — поріг Курганного Лігва Бан'етіл, де сплячі друїди й давні тунелі потерпають від навали знавіснілих звірів іззовні."}},faq={{q="Де Лощина Бан'етіл?",a="Лощина Бан'етіл — яр у центрі Тельдрассила, трохи на південь від головної дороги між селом Доланаар і столицею Дарнасусом.",al={"місце лощини бан'етіл","де лощина бан'етіл","знайти лощину бан'етіл"}},{q="Чому тутешні фурболги ворожі?",a="Фурболги по всьому Тельдрассилу піддалися скверні й шаленству, що охопили звірів Світового Дерева. Замість того щоб мирно жити поруч із нічними ельфами, як було здавна, ці племена стали люто ворожими й ревно стережуть свої землі.",al={"чому фурболги шаленіють","ворожі фурболги бан'етіл","напад фурболгів бан'етіл"}},{q="Що в Курганному Лігві Бан'етіл у глибині лощини?",a="Курганне Лігво Бан'етіл — підземний комплекс, у якому друїди нічних ельфів здавна поринали в глибокий сон і єдналися зі Смарагдовим Сном. Та відтоді як у лощині наростає скверна, лігво стало небезпечним місцем.",al={"що в курганному лігві","курганне лігво бан'етіл","лігво в лощині бан'етіл"}},{q="Чи безпечна дорога над лощиною?",a="Головну дорогу зазвичай патрулюють Вартові нічних ельфів, але фурболги з Лощини Бан'етіл часто вибираються з яру, щоб влаштовувати засідки на мандрівників. Тим, хто подорожує між Доланааром і Дарнасусом, варто бути насторожі.",al={"чи безпечна дорога","засідки фурболгів","чи безпечна дорога до дарнасуса"}}},fp="16,317,17.529.0,34.165.0,34.262.0,66.236.0,44.239.0"}
P.entries["subzone:baradin-bay"] = {n="Затока Барадін",s="Затока Барадін — розлога водойма між берегами Каз Модану, Багнокраю, Аратійського нагір'я та південного Лордерону. Під час Другої війни її пильно патрулював могутній флот Кул Тіраса, а нині в її водах ховаються підступні рифи, затонулі бойові кораблі й ворожі морські хижаки.",h="Затока Барадін — розлога водойма між берегами Каз Модану, Багнокраю, Аратійського нагір'я та південного...",kw={"затока барадін","кул тірас","загублений флот","друга війна","гавань менетіл","морський шлях"},ang={["faction:Alliance"]="Затока Барадін — морська артерія, що поєднує дії Альянсу в Каз Модані з його заставами в Араті й Гілсбреді, хоча морські небезпеки й затонулі уламки роблять кожну переправу ризикованою.",["race:Human"]="Для людей, особливо тих, чий рід сягає Кул Тіраса чи Лордерону, затока — освячена й скорботна земля, де лежать водяні могили моряків Другої війни."},sec={{t="Стратегічний водний шлях",b="Затока Барадін, яку обрамлюють береги Дун Мороґа на півдні та Лордерону на півночі, — важливий морський шлях, що з'єднує гавані Східних Королівств. Її опорою є жваві порти — Гавань Менетіл у Багнокраї та Саутшор у Передгір'ї Гілсбреда. Та плавати цими водами небезпечно: мілкі піщані коси, зубчасті мілини й небезпечні мешканці — мурлоки, кроколіски й глибоководні акули — повсякчас загрожують і морякам, і мандрівникам."},{t="Цвинтар флотів",b="Під час Другої війни Затока Барадін бачила запеклі морські бої флотів Кул Тіраса з Ордою. Нині похмурі нагадування про ті битви всіюють узбережжя й морське дно. Розтрощені корпуси Третього флоту Кул Тіраса — тут їх звуть Загубленим Флотом — лежать напівзатоплені вздовж берега Багнокраю, а інші кораблі пішли на дно аж до Затопленого Рифу. Тепер довкола цих трухлявих дерев'яних руїн никають ворожі духи, спритні шукачі поживи й ненажерливі морські звірі."}},faq={{q="Які великі порти розташовані на Затоці Барадін?",a="Найпомітніші поселення на березі затоки — Гавань Менетіл у Багнокраї й Саутшор у Передгір'ї Гілсбреда, що забезпечують життєво важливе морське сполучення.",al={"порти затоки барадін","гавані затоки барадін","куди веде затока барадін"}},{q="Чому на березі затоки стільки затонулих кораблів?",a="Чимало уламків, зокрема Загублений Флот біля берегів Багнокраю й кораблі на Затопленому Рифі, — це судна флоту Кул Тіраса, потоплені в запеклих морських битвах Другої війни.",al={"затонулі кораблі мокрих земель","чому тут затонулі кораблі","походження загубленого флоту"}},{q="Які загрози чатують у водах Затоки Барадін?",a="Мілини кишать агресивними мурлоками й болотяними кроколісками, а глибші води — хижими крабами, акулами й неспокійними духами потопельників-моряків.",al={"чудовиська затоки барадін","мурлоки затоки барадін","чи безпечно плавати в затоці барадін"}},{q="Які землі межують із Затокою Барадін?",a="Затоку Барадін оточують північний захід Дун Мороґу, болотисті береги Багнокраю, скелі Аратійського нагір'я й узбережжя півдня Гілсбреда та Ґілнеасу.",al={"які зони межують із затокою барадін","географія затоки барадін"}}},fp="11,315,20.484.0,23.504.0,47.178.0,55.190.0,55.183.0,37.172.0"}
P.entries["subzone:bashal-aran"] = {n="Башал'Аран",s="Башал'Аран — давні руїни Високородних на півночі Темного Узбережжя, трохи на схід від Обердайна. До Великого Розколу це було квітуче місто-сестра Амет'Арану, а тепер тут кишать демонічні сатири й грелли, що живляться залишками таємної магії, а самотній ельфійський привид досі ув'язнений давнім прокляттям.",h="Башал'Аран — давні руїни Високородних на півночі Темного Узбережжя, трохи на схід від Обердайна.",kw={"башал'аран","астеріон","сатири","грелли","високородні","темне узбережжя"},ang={["race:NightElf"]="Башал'Аран — трагічне нагадування про безрозсудну таємну гординю, що прирекла давню Імперію калдореїв і проклала шлях демонічній скверні."},sec={{t="Розколоте місто-близнюк",b="До того як десять тисяч років тому Великий Розкол зламав давній Калімдор, королева Азшара оселила улюблених підданих із Високородних у містах-близнюках Башал'Аран і Амет'Аран. Під владою могутнього мага Атрікуса Нарассіна міста славилися розкішними ринками й храмами на честь Елуни. Коли Колодязь Вічності обвалилося, катаклізм спустошив обидва поселення. З причин, загублених у часі, Атрікус скористався своєю таємною майстерністю, щоб ув'язнити власного заступника, мага Астеріона, у печатці з місячного каменю в Башал'Арані. Навіть після смерті тіла привид Астеріона лишився прикутим до зруйнованої святині."},{t="Демонічна навала",b="Нині напівзруйноване каміння Башал'Арану захопили мерзенні зайди: сатири Дет'рилл і пустотливі грелли. Приваблені залишками магії, що досі чіпляється за давню кладку, ці осквернені створіння вбирають рештки енергії, щоб підживлювати свої мерзенні мистецтва. Хоч вони роями кишать у зруйнованих дворах і тероризують мандрівників на лісових стежках Темного Узбережжя, демони оминають центральну святиню, де Астеріон несе свою нескінченну варту."}},faq={{q="Чим був Башал'Аран до свого знищення?",a="Башал'Аран був пишним містом калдореїв, яке королева Азшара заснувала для улюбленої знаті з-поміж Високородних ще до Великого Розколу. Разом із містом-близнюком Амет'Араном ним правив маг-володар Атрікус Нарассін.",al={"історія башал'арана","хто збудував башал'аран","чим була ця руїна"}},{q="Що за привид блукає святилищем?",a="Це дух Астеріона — шанованого воїна-мага з Високородних, що колись наглядав і за Башал'Араном, і за Амет'Араном. Його загадково зрадив правитель Атрікус Нарассін і прикув до цього місця печаткою з місячного каменю, тож Астеріон лишається ув'язненим навіть по смерті.",al={"хто астеріон","привид башал'арана","чому тут привид"}},{q="Чому в руїнах живуть сатири?",a="Сатирів і греллів привабили до Башал'Арана рештки могутньої тайної енергії, що лишилася по давніх Високородних. Вони живляться цими залишковими магічними випарами, щоб посилити свою темну демонічну магію.",al={"чому сатири тут","переказ про сатирів дет'рілл","грелли башал'арана"}},{q="Що пов'язує Башал'Аран і Амет'Аран?",a="Башал'Аран і Амет'Аран були містами-побратимами, якими правили разом за королеви Азшари. Астеріон часто подорожував між обома поселеннями, дбаючи про потреби мешканців, доки обидва не зруйнував Розкол.",al={"зв'язок з амет'араном","близнючі міста темного узбережжя","амет'аран і башал'аран"}}},fp="11,326,21.622.0,19.462.0,45.226.0,38.265.0,36.209.0,42.224.0"}
P.entries["subzone:bathran-s-haunt"] = {n="Притулок Батрана",s="Притулок Батрана — давні руїни калдореїв на північному заході Ашенвалю, на схід від Зорамського Узмор'я. Нещодавно це місце захопили травники Відступників зі своєю охороною: вони збирають тутешні рослини для алхімічних досліджень, і довколишній ліс поволі в'яне.",h="Притулок Батрана — давні руїни калдореїв на північному заході Ашенвалю, на схід від Зорамського Узмор'я.",kw={"притулок батрана","волосся батрана","відступники","руїни","травництво","ашенваль"},ang={["profession:Herbalism"]="Ці руїни — унікальне місце для травника: наскільки відомо, лише тут росте Волосся Батрана, трава, цінована за рідкісні цілющі властивості.",["race:NightElf"]="Табір Відступників у Притулку Батрана — образа для спадщини калдореїв: тут нежить-загарбники оскверняють давню ельфійську кладку й отруюють священну землю."},sec={{t="Сплюндрований притулок у давньому лісі",b="На північ від Руїн Ордил'Аран серед густого ашенвальського листя стоять напівзруйновані колони нічних ельфів. Колись тиха пам'ятка калдореїв опинилася в тіні Відступників. Серед мармурових уламків нишпорять травники-нежить та їхні охоронці, що влаштували тут грубу лабораторію просто неба. Сама їхня присутність отруює давню землю: трава гниє й буріє, яскраві квіти в'януть, а гаєм розповзається неприродний тлін, поки вони методично збирають рідкісні лісові інгредієнти для своїх дослідів."},{t="Збір Волосся Батрана",b="Головна цінність цих руїн — Волосся Батрана, унікальна цілюща трава, що вкорінюється лише серед цього каміння. Розвідники нічних ельфів і Альянсу вважають присутність Відступників мерзенним оскверненням священної ельфійської землі, а нежить тим часом старанно видобуває з рослини її могутні властивості. Орда кровно зацікавлена в цьому врожаї, хоча таємні методи Відступників і отруєна ними земля викликають підозру і в чужинців, і в союзників."}},faq={{q="Де Притулок Батрана?",a="Притулок Батрана — на північному заході Ашенвалю, просто на північ від Руїн Ордил'Аран і вглиб суходолу на схід від Зорамського Узмор'я.",al={"де притулок батрана","місце притулку батрана","як дістатися притулку батрана"}},{q="Чому тут Відступники?",a="Травники з Відступників влаштували серед руїн табір і лабораторію, щоб збирати й вивчати неповторну рослинність лісу, передусім рідкісну цілющу рослину Волосся Батрана.",al={"що нежить робить в ашенвалі","чому відступники в притулку батрана","мета відступників батрана"}},{q="Що таке Волосся Батрана?",a="Волосся Батрана — особлива цінна трава з сильними відновлювальними властивостями, що росте лише довкола зруйнованих мурів Притулку Батрана.",al={"рослина волосся батрана","що таке волосся батрана","трава батрана"}},{q="Чому земля довкола руїн гине?",a="Тривала присутність Відступників і їхня алхімічна діяльність отруїли найближчу місцину: трава буріє й в'яне, а ніжні лісові квіти гинуть.",al={"чому трава руда","скверна в притулку батрана","чому земля гниє"}}},fp="15,277,38.528.0,29.506.0,33.144.0,26.202.0,23.154.0,41.171.0"}
P.entries["subzone:bay-of-storms"] = {n="Затока Бур",s="Затока Бур — широка, неспокійна затока, що врізається в скелясті східні кручі Азшари. У її бурхливих водах ховаються прадавні руїни, затоплені печери й небезпечні морські звірі, тож плавати вздовж цього узбережжя ризиковано.",h="Затока Бур — широка, неспокійна затока, що врізається в скелясті східні кручі Азшари.",kw={"затока бур","азшара","храм арккорана","кладка гетери","печера лускобородого","риболовля"},ang={["profession:Cooking"]="Бурхливі глибокі води Затоки Бур славляться серед прибережних рибалок рідкісним і цінним глибоководним уловом біля берегів Калімдору."},sec={{t="Буремне узбережжя",b="Затока Бур, що відкривається до Великого Моря, визначає значну частину мальовничого узбережжя Азшари. Це далеко не тиха гавань: її збурені води й скелясті виступи — дім небезпечних звірів і прадавніх морських загроз. У її водах і вздовж берегів лежать такі пам'ятні місця, як затонулий Храм Арккорана, коралові рифи Кладки Гетери й Печера Лускобородого, тож звичайні моряки здебільшого уникають затоки, лишаючи її прибережним чудовиськам."}},faq={{q="Де Затока Бур?",a="Затока Бур — на східному краю Азшари, вона відкривається просто у Велике Море біля узбережжя Калімдору.",al={"місце затоки бур","де затока бур","де затока"}},{q="Які помітні місця є в затоці?",a="У затоці кілька помітних прибережних місць, зокрема Храм Арккорана, риф, відомий як Кладка Гетери, і прихована схованка — Печера Лускобородого.",al={"пам'ятки затоки бур","що є в затоці бур","цікаві місця затоки бур"}},{q="Чому затокою небезпечно плавати?",a="Шалений прибій, гострі зубчасті скелі й ворожі морські створіння роблять затоку зрадливою для кораблів, а прибережних поселень, що могли б прийти на порятунок, тут майже немає.",al={"чи затока бур безпечна","чому небезпечно","небезпеки затоки"}}},fp="13,238,19.462.0,35.117.0,42.165.0,37.168.0"}
P.entries["subzone:bear-s-head"] = {n="Ведмежа Голова",s="Ведмежа Голова — відлюдна гірська місцина на південно-східних кручах Азшари. Вона названа на честь місцевих фурболгів із племені Деревопащих, чиї поселення розкидані на скелястих висотах, і правує за заставу, пов'язану з їхніми більшими осідками далі на півночі; а просто над нею, на скелі, стоїть святилище Архімага Ксилема.",h="Ведмежа Голова — відлюдна гірська місцина на південно-східних кручах Азшари.",kw={"ведмежа голова","фурболги","деревопащі","вежа ксилема","архімаг ксилем","азшара"},ang={["class:Mage"]="На високій кручі над Ведмежою Головою живе Архімаг Ксилем — могутній і дивакуватий чародій, до якого звертаються знавці тайної магії, що прагнуть вищої науки."},sec={{t="Застави фурболгів і магія на кручі",b="Ведмежа Голова, захована на південному сході Азшари, завдячує назвою таборам фурболгів із племені Деревопащих, не зачеплених порчею, які стоять на її висотах. Ці прості поселення — віддалені табори, пов'язані з великими лігвами фурболгів в Урсолані й Твердині Деревопащих на півночі. Високо на кручах просто над цією місциною стоїть Вежа Ксилема — дивовижне пристановище, де Архімаг Ксилем і жменька його учнів займаються тайними студіями в тихій самоті, далеко від решти неспокійного узбережжя."}},faq={{q="Чому ця місцина зветься Ведмежа Голова?",a="Край названо на честь сіл фурболгів-Деревопащих, розкиданих його пагорбами. Ведмежий народ тримає тут табори, що правлять за південні застави їхніх твердинь на півночі Калімдору.",al={"походження назви ведмежа голова","чому ведмежа голова","значення ведмежої голови"}},{q="Які фурболги живуть у Ведмежій Голові?",a="Тут живе плем'я Деревопащих. На відміну від багатьох інших племен фурболгів Калімдору, що стали жертвами демонічної скверни, Деревопащі здебільшого встояли перед нею й підтримують зв'язок зі своїми головними поселеннями в Урсолані й Твердині Деревопащих.",al={"фурболги ведмежої голови","тімбермоу ведмежа голова","яке плем'я фурболгів тут"}},{q="Що за вежа на скелях над Ведмежою Головою?",a="Цей шпиль на кручі належить Архімагові Ксилему — дивакуватому чарівникові з людей, що покинув Даларан і подався до Азшари, щоб навчатися на самоті разом із кількома учнями й соратниками з високих ельфів.",al={"вежа над ведмежою головою","хто живе у вежі","вежа ксилем"}}},fp="11,312,36.510.0,36.215.0,35.262.0,50.219.0"}
P.entries["subzone:beezil-s-wreck"] = {n="Уламки Бізіла",s="Уламки Бізіла — місце катастрофи нещасливого гоблінського цепеліна глибоко в трясовинах Багна Пилоброду. Розбите судно лежить на схід від Ферми Табети, і його вантаж — розкидані припаси й вибухові інженерні деталі — приваблює збирачів поживи.",h="Уламки Бізіла — місце катастрофи нещасливого гоблінського цепеліна глибоко в трясовинах Багна Пилоброду.",kw={"уламки бізіла","багно пилоброду","цепелін","гобліни","сіфорій","ферма табети","інженерія"},ang={["profession:Engineering"]="Покручені уламки гоблінського цепеліна ховають нестабільні механічні деталі — зокрема сіфорієві прискорювачі, яких жадав би будь-який майстер.",["race:Gnome"]="Огляд димних решток гоблінського суперника в повітроплаванні — моторошне нагадування про небезпеки, властиві будь-якій негномській повітряній конструкції."},sec={{t="Катастрофічне приземлення",b="Захований у вологій багнюці на схід від Ферми Табети, лежить розтрощений кістяк гоблінського цепеліна, відомий як Уламки Бізіла. Судно везло вантаж на південь через Калімдор, коли катастрофічно впало в болото. Уламки досі тліють серед сплутаного очерету, а ексцентричний капітан Бізіл, схоже, зник із багна, лишивши розкидані ящики й механізми, що цокають, повільно гнити в солоній воді."},{t="Пожива в багнюці",b="Попри суворе довкілля, місце катастрофи лишається ласим шматком для заповзятливих шукачів. Повітряне судно везло вибухонебезпечний вантаж — зокрема сіфорієві прискорювачі й важкі ящики, що вціліли після удару. Збирачі поживи, які наважуються пробиратися повз навколишніх звірів, нерідко ризикують життям, щоб забрати рештки загубленого вантажу, перш ніж їдка болотяна вода остаточно його зіпсує."}},faq={{q="Що таке Уламки Бізіла?",a="Уламки Бізіла — місце падіння гоблінського цепеліна в глибині Багна Пилоброду, просто на схід від Ферми Табети. Повітряний корабель упав, коли перевозив вантаж через болото.",al={"уламки бізіла","розбитий цепелін пилових боліт","що це за уламки"}},{q="Де пілот, Бізіл?",a="Пілота Бізіла ніде біля місця падіння не видно. Чи він утік у підступні нетрі, чи взагалі покинув болото — для тих, хто обшукує корпус, лишається загадкою.",al={"де бізіл","хто такий бізіл","місце бізіла"}},{q="Який цінний вантаж віз цепелін?",a="Цепелін був навантажений товарами й нестійкою гоблінською технікою, зокрема сіфорієвими прискорювачами. Ці цінні інженерні деталі роблять місце падіння частою ціллю шукачів пригод і мародерів.",al={"що було в цепеліні","підсилювачі сіфорію","вантаж уламків"}}},fp="14,263,20.440.0,19.403.0,23.186.0,27.189.0,46.203.0"}
P.entries["subzone:beggar-s-haunt"] = {n="Притон Жебрака",s="Притон Жебрака — покинута розвідувальна вежа Стормвінда на схилі пагорба на північному сході Сутінколісся, біля гірської дороги до Перевалу Мертвого Вітру. Колись її звели, щоб стерегти східні кордони королівства, а тепер вона стала заставою лазутчиків-Відступників глибоко на землях Альянсу.",h="Притон Жебрака — покинута розвідувальна вежа Стормвінда на схилі пагорба на північному сході Сутінколісся...",kw={"притон жебрака","вежа","відступники","аптекарське товариство","сутінколісся","лицарська улоговина"},ang={["faction:Alliance"]="Агенти Відступників у старій розвідувальній вежі Стормвінда, просто біля головного шляху, — тривожна ознака того, що Орда проникла під самий поріг Даркшира.",["race:Undead"]="Для агентів Відступників ця відлюдна застава — рідкісний і небезпечний плацдарм глибоко в людських землях півдня."},sec={{t="Вартова вежа в тіні",b="Притон Жебрака, що височіє над туманними пагорбами на схід від Маєтку Містмантл, колись був діяльним спостережним постом, де Вартові Стормвінда стерегли східні підступи до королівства. Коли Велике Селище поринув у морок нинішнього Сутінколісся, а королівські патрулі відійшли до Даркшира, кам'яну вежу покинули на поталу негоді. Нині її вигідне розташування служить куди зловіснішій меті: агенти Відступників, серед них члени Королівського Аптекарського Товариства та скрадачі смерті, проводять у зруйнованій твердині досліди й стежать за краєм просто під носом в Альянсу."},{t="Лицарська Улоговина й забуті мерці",b="За вежею крута звивиста стежка спускається до відлюдного ставка з водоспадом, відомого як Лицарська Улоговина. Тут лежить безіменна могила, яку обступають дві зловісні кам'яні статуї в каптурах, схожі на вартових обабіч Темного Порталу. Поховання неподалік, серед них могила Невідомого Солдата, свідчать про забуті сутички на цьому прикордонні задовго до того, як Відступники оселилися у вежі."}},faq={{q="Чому в Притоні Жебрака Відступники?",a="Агенти з Андерсіті, зокрема Аптекар Фостін із Королівського Аптекарського Товариства й Скрадач Смерті Зраедус, захопили покинуту вартову вежу. Звідси вони можуть стежити за пересуваннями Альянсу й нишком проводити досліди далеко на півдні.",al={"хто в притоні жебрака","чому тут орда","нежить у притоні жебрака"}},{q="Чи цю вежу збудували Відступники?",a="Ні. Вежу збудувало королівство Стормвінд як розвідувальну заставу. Коли місцева оборона ослабла, а край перетворився на Сутінколісся, Варта Стормвінда покинула її, і вежа стояла порожньою, доки її не захопили розвідники Відступників.",al={"хто збудував притон жебрака","історія притону жебрака","чи це вежа альянсу"}},{q="Що за дивна могила за вежею?",a="Стежкою позаду притону лежить Лицарська Лощина — відлюдне озерце під водоспадом із безіменною могилою, яку обрамлюють статуї вартових у каптурах, точнісінько як пам'ятники обабіч Темного Порталу.",al={"могила за вежею","статуї лицарського яру","статуї темного порталу сутінковий ліс"}},{q="Чи ворожий Притон Жебрака до мандрівників Альянсу?",a="Так. Відступники у вежі — досвідчені агенти, що вбивають кожного шукача пригод з Альянсу, який підійде надто близько до їхнього укріплення на схилі.",al={"чи вони нападуть","стражі притону жебрака","чи притон жебрака безпечний"}}},fp="14,297,27.594.0,38.408.0,41.251.0,48.233.0,43.202.0,48.155.0"}
P.entries["subzone:beren-s-peril"] = {n="Лихо Берена",s="Лихо Берена — відлюдна гірська печера серед скелястих пагорбів на південний захід від Амбермілла в Срібноліссі. Це вкорінений редут мерців-ренегатів, вірних Погибелі, що служать некромантові Тулу Рейвенклову й плетуть змову проти сусідніх Відступників.",h="Лихо Берена — відлюдна гірська печера серед скелястих пагорбів на південний захід від Амбермілла в...",kw={"лихо берена","тул рейвенклов","погибель","печера","гробниця","срібнолісся"},ang={["faction:Horde"]="Щоб убезпечити суворі стежки Срібнолісся, треба вичистити гнізда мерців-ренегатів, перш ніж вони переріжуть шляхи постачання між Гробницею й південними землями.",["race:Undead"]="Посіпаки Рейвенклова з Лиха Берена — гірке нагадування про те, як міцно досі тримається Погибель: вони загрожують безпеці Гробниці, і прибічники Сильвани мають знищити їх швидко й нещадно."},sec={{t="Прихована загроза в пагорбах",b="Лихо Берена, що сховалося високо в скелях на південний захід від Амбермілла, — це затінена печера й звивиста гірська стежка, приховані від головної дороги. Після спустошень Третьої війни мерці Погибелі, що не підкорилися Відступникам, під командуванням некроманта-ренегата Тула Рейвенклова укріпили цей анклав. Замість схилитися перед Темною Леді чи відступити на північ, слуги Рейвенклова — регенти, вартові й наймити — таємно збиралися тут, щоб підготувати напад на базу Відступників у Гробниці. Розвідники Відступників викрили їх, і тиха скеля перетворилася на поле бою для загонів Орди, посланих знищити загрозу, перш ніж напад відбудеться."}},faq={{q="Що таке Лихо Берена?",a="Це печера й гірський перехід довкола неї на південний захід від Амбермілла в Срібноліссі, між центральним шляхом і бічною дорогою до Амбермілла.",al={"лихо берена","де лихо берена","печера лиха берена"}},{q="Хто контролює Лихо Берена?",a="Печеру захопила нежить Погибелі, віддана некромантові Тулу Рейвенклову, — зокрема вартові, трудяги й регенти Рейвенклова.",al={"хто живе в лиху берена","вороги лиха берена","нежить рейвенклов"}},{q="Чому Відступникам важливе це місце?",a="Розвідники Відступників з'ясували, що нежить, яка засіла в Лиху Берена, збирає війська й озброюється для неминучого нападу на Гробницю, тож Жрець Тіні Аллістер наказав завдати випереджальних ударів.",al={"лихо берена елістер","чому нападати на лихо берена","загроза гробниці"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — могутній некромант у Срібноліссі, що тримав під владою осередки безмозких і ворожих прислужників Погибелі й залякував край із таких місць, як Лихо Берена й Фортеця Фенріс.",al={"тул рейвенклов","тул срібнолісся"}}},fp="13,256,28.691.0,22.161.0,27.134.0,45.222.0,23.218.0"}
P.entries["subzone:bitter-reaches"] = {n="Гіркі Обшири",s="Гіркі Обшири — скелясті, обвітрені дикі землі на північному сході Азшари. Цивілізація їх майже не торкнулася, а суворими кручами никають хижі звірі й величезні гірські велетні.",h="Гіркі Обшири — скелясті, обвітрені дикі землі на північному сході Азшари.",kw={"гіркі обшири","азшара","гірський срібношавлій","химери","гіпогрифи","гірські велетні","травництво"},ang={["class:Hunter"]="Гнізда на кручах Гірких Обширів — чудові мисливські угіддя, що аж кишать дикими гіпогрифами й агресивними химерами, споконвічними мешканцями цього прадавнього узбережжя.",["profession:Herbalism"]="Обвітрені висоти Гірких Обширів — одне з небагатьох місць в Азшарі, де росте цінний Гірський Срібношавлій, але щоб його зібрати, вам доведеться мати справу з химерами й велетнями."},sec={{t="Небезпечний прибережний край",b="Гіркі Обшири, що займають північно-східні кручі Азшари, лишаються суворою й неприборканою смугою кам'янистої землі над Великим Морем. На висотах гніздяться зграї диких гіпогрифів і двоголових химер, а холодною землею повзуть їдкі слизняки. На високих північних хребтах колосальні гірські велетні захопили схили, витіснили менших істот і перетворили засніжені підступи на смертельну пастку для кожного самотнього мандрівника."},{t="Рослини скель",b="Попри суворі вітри й хижих звірів, скелястий край живить рідкісні гірські рослини. Поодинокі кущики Гірського Срібношавлію чіпляються за високі кам'яні стіни й вітряні уступи, тож небезпечна місцевість часом варта мандрів для відважних травників, які зуміють уникнути велетнів і ревнивих до своїх земель химер."}},faq={{q="Де Гіркі Обшири?",a="Гіркі Обшири займають північно-східну частину Азшари — високі прибережні кручі й хребти над затокою.",al={"місце гірких обширів","де гіркі обшири","гіркі обшири азшара"}},{q="Які істоти тут живуть?",a="Тут водяться гіпогрифи, що ревно стережуть свої землі, двоголові химери й слизуни. А північною межею блукають височенні гірські велетні.",al={"мобі гірких обширів","що живе в гірких обширах","чудовиська гірких обширів"}},{q="Чому тут гірські велетні?",a="Прадавні гірські велетні живуть на високих північних вершинах і околицях Азшари: вони вибороли собі власні володіння й вигнали звідти більшість місцевих звірів.",al={"гірські велетні азшари","чому велетні в гірких обширах"}},{q="Які цінні ресурси ростуть у Гірких Обширах?",a="На скелястих виступах і хребтах подекуди трапляються рідкісні високогірні трави, як-от Гірський Срібношавлій.",al={"трави гірких обширів","збір у гірких обширах"}}},fp="14,191,28.480.0,18.331.0,29.120.0,25.132.0,35.178.0,51.124.0"}
P.entries["subzone:black-channel-marsh"] = {n="Багно Чорного Каналу",s="Багно Чорного Каналу — каламутна трясовина на південному заході Багнокраю, обабіч головної дороги до Гавані Менетіл. Мокрі землі, що кишать агресивними рапторами, — безпосередня загроза для необачних мандрівників і гінців із припасами, що перетинають прибережні низини.",h="Багно Чорного Каналу — каламутна трясовина на південному заході Багнокраю, обабіч головної дороги до Гавані...",kw={"багно чорного каналу","раптори","гавань менетіл","дорога","болото","багнокрай"},ang={["class:Hunter"]="Болото — небезпечний полігон для мисливців, що прагнуть приборкати чи вистежити лютих рапторів Багнокраю просто біля головної дороги.",["faction:Alliance"]="Цей коридор — життєво важлива артерія, що з'єднує порт Гавані Менетіл з рештою Каз Модану, тож набіги рапторів — постійний головний біль для мандрівників."},sec={{t="Небезпека на дорозі до Менетіла",b="Багно Чорного Каналу, що простягається болотистими низинами на південний захід від головного шляху, має сумну славу серед погоничів караванів і гінців, що прямують до Гавані Менетіл. Висока дорога створює ілюзію безпеки, але в застояних протоках і густому очереті живуть зграї рапторів, ревних до своєї території. Голодні звірі раз у раз вибігають просто на дорогу й нападають на новобранців і втомлених подорожніх, що відійдуть від протоптаної стежки бодай на крок-другий."}},faq={{q="Де Багно Чорного Каналу?",a="Багно Чорного Каналу займає південно-західний куток Багнокраю. Воно межує з південним боком великої дороги, що веде до Гавані Менетіл.",al={"де багно чорного каналу","місце багна чорного каналу","чорний канал мокрі землі"}},{q="Чому це багно вважають небезпечним для мандрівників?",a="У багні аж кишить лігвами рапторів. Ці хижаки полюють на околицях болота й раз у раз підкрадаються аж до узбіччя дороги, заскочуючи зненацька необачних мандрівників і недосвідчених шукачів пригод.",al={"чому небезпечно","загрози багна чорного каналу","раптори на дорозі"}},{q="Хто найчастіше тут подорожує?",a="Дорогою повз багно часто ходять гінці Альянсу, дворфійські купці й мандрівники між Айронфорджем і доками Гавані Менетіл.",al={"хто тут подорожує","мандрівники"}}},fp="19,280,26.449.0,37.149.0,53.225.0,36.177.0"}
P.entries["subzone:blackchar-cave"] = {n="Печера Чорної Гарі",s="Печера Чорної Гарі — таємнича замурована печера серед південно-західних скель Палючої Ущелини, неподалік підніжжя Гори Блекрок. Її вхід завалений непрохідним камінням і уламками скель.",h="Печера Чорної Гарі — таємнича замурована печера серед південно-західних скель Палючої Ущелини, неподалік...",kw={"печера чорної гарі","палюча ущелина","гора блекрок","печера","завал"},sec={{t="Замурований поріг",b="Печера Чорної Гарі, захована серед розпечених скель на підступах до Гори Блекрок, постає суцільною кам'яною стіною там, де колись, певно, був вхід до глибокої печери. Важкі уламки й обпалений шлак наглухо закривають отвір і не дають нікому дослідити тунелі, що, можливо, тягнуться далі в коріння гори. Пустельна місцевість довкола випалена попелом і магмою й мало чим може втішити мандрівників."}},faq={{q="Чи можна зайти в Печеру Чорної Гарі?",a="Ні. Вхід до Печери Чорної Гарі цілком завалений обваленим камінням, попелом і уламками. Усередині немає відкритого простору, який можна було б дослідити.",al={"чи відкрита печера чорної гарі","зайти в печеру чорної гарі","всередині печери чорної гарі"}},{q="Де Печера Чорної Гарі?",a="Вона в південно-західному куті Палючої Ущелини, серед скелястого передгір'я біля проходу до Гори Блекрок.",al={"місце печери чорної гарі","де печера чорної гарі"}}},fp="14,199,18.416.0,33.139.0,32.137.0"}
P.entries["subzone:blackrock-mountain"] = {n="Гора Блекрок",s="Гора Блекрок — велетенський діючий вулкан, що височіє між Палаючими Степами й Палючою Ущелиною. Вона постала внаслідок катастрофічного виклику Рагнароса, Володаря вогню, і в її порожнистих надрах ховаються прадавня дворфська кладка, ворожі армії й тліючі жахи.",h="Гора Блекрок — велетенський діючий вулкан, що височіє між Палаючими Степами й Палючою Ущелиною.",kw={"гора блекрок","рагнарос","темне залізо","тауріссан","війна трьох молотів","шпиль блекрок","вулкан"},ang={["faction:Horde"]="Для нової Орди Шпиль Блекрок — символ колишнього поневолення й кровопролиття під владою Думхаммера, а нині його утримують непокірні орки, що зреклися проводу Тралла.",["race:Dwarf"]="Гора — найтемніший розділ дворфської історії: трагічне безумство клану Темного Заліза, що коштувало йому свободи й залишило шрами на обличчі Східних Королівств."},sec={{t="Народжена катастрофою",b="Гори Блекрок не існувало аж до кульмінації Війни Трьох Молотів два з половиною століття тому. Перед загрозою знищення об'єднаними арміями Айронфорджа й клану Вайлдгаммерів тан-чародій Тауріссан шукав зброю в надрах землі. Його безрозсудне закляття зруйнувало межі між світами й викликало в Азерот Рагнароса, Володаря вогню. Наслідки були апокаліптичні: катастрофа розірвала гірський кряж Редріджу, вирвала Палючу Ущелину й Палаючі Степи та виштовхнула в небо колосальний вулкан. Тауріссан загинув у вибуху, а вцілілий клан Темного Заліза опинився у вічному рабстві Володаря вогню й висік свою столицю, Місто Тінькузні, глибоко в корінні гори."},{t="Цитадель попелу й крові",b="Під час Першої й Другої воєн гора набула нового похмурого значення. Під проводом Чо'ґалла Рада Тіней захопила верхню фортецю Шпиля Блекрок за мовчазної згоди посіпак Рагнароса. Після розграбування Стормвінда Оргрім Думхаммер розправився з радою й зробив шпиль столицею-фортецею Орди, вбачаючи у спільній назві зі своїм кланом Блекрок доленосний знак. Нині гора лишається жорстоким полем бою: дворфи Темного Заліза та їхній стихійний господар тримають вогняні глибини, а непокірні орки Блекрок, дракониди та їхні темні господарі займають верхні шпилі."}},faq={{q="Як з'явилася Гора Блекрок?",a="Вона з'явилася приблизно 250 років тому, під час Війни Трьох Молотів. Прагнучи будь-що перемогти суперницькі дворфійські клани, Імператор Тауріссан спробував вивільнити глибинну підземну енергію й ненароком закликав Рагнароса, Володаря вогню, — і руйнівний вибух звів вулкан.",al={"походження гори блекрок","хто створив гору блекрок","як утворився вулкан"}},{q="Чому вона зветься Гора Блекрок?",a="Вулкан назвали Горою Блекрок і Шпилем Блекрок за кілька століть до того, як орки ступили на Азерот. Коли прибув Оргрім Думхаммер, він побачив у тому, що назва збігається з назвою клану Блекрок, добрий знак і зробив гору своєю головною базою.",al={"походження назви блекрок","названо на честь клану блекрок"}},{q="Хто нині контролює Гору Блекрок?",a="Гору розділяє жорстока боротьба. Поневолені дворфи Темного Заліза тримають підземні зали Міста Тінькузні на службі в Рагнароса, а рештки клану Блекрок і чорні драконороди панують у верхній цитаделі — Шпилі Блекрок.",al={"хто живе в блекроку","хто править горою блекрок"}},{q="Які краї сполучає Гора Блекрок?",a="Внутрішні проходи й ланцюги Гори Блекрок — прямий шлях між Палючою Ущелиною на півночі й Палаючими Степами на півдні.",al={"як пройти крізь блекрок","зв'язки гори блекрок"}}},fp="18,264,20.717.0,24.633.0,35.285.0,35.268.0,42.259.0,46.154.0"}
P.entries["subzone:blackrock-pass"] = {n="Перевал Блекрок",s="Перевал Блекрок — гірський прохід, що сполучає північні кручі Гір Редріджу з посушливими пустирями Палаючих Степів. Пролягаючи під важкою залізною брамою, він позначає різкий рубіж між мирним людським краєм і небезпечними бойовищами дворфів Темного Заліза та орків Блекрок. Для кожного втомленого мандрівника, що прямує на північ пішки, це суворий і небезпечний кордон.",h="Перевал Блекрок — гірський прохід, що сполучає північні кручі Гір Редріджу з посушливими пустирями Палаючих...",kw={"перевал блекрок","редрідж","палаючі степи","лейкшир","брама","орки блекрок"},ang={["faction:Alliance"]="Для захисників Редріджу й Королівства Стормвінд Перевал Блекрок — вічне джерело страху, адже він відкриває оркам Блекрок прямий шлях на південь, у людські землі."},sec={{t="Випалений поріг",b="Перевал Блекрок, прорубаний у зубчастому хребті гір, — сухопутний шлях між Горами Редріджу й Палаючими Степами. На скелястій межі стоїть міцна залізна брама, що відділяє ідилічні ліси й озера південних долин від вулканічної руїни за нею. Переступивши цю межу, мандрівник лишає позаду мирні землі, які захищає знесилене ополчення Лейкширу, і опиняється на відкритому пустирі, де никають вогняні елементалі, дракониди й ворожі орчі ватаги. Мало хто перетинає перевал пішки, хіба що прямує до самої Гори Блекрок."}},faq={{q="Куди веде Перевал Блекрок?",a="Перевал Блекрок з'єднує північну межу Гір Редріджу просто з південними околицями Палаючих Степів. Це одна з прямих сухопутних брам, що пов'язують південні землі Альянсу з передгір'ям Гори Блекрок.",al={"куди веде перевал блекрок","призначення перевалу блекрок","шлях з реджриджа до палаючих степів"}},{q="Чи безпечно мандрівникам із Лейкшира переходити перевал?",a="Ні. Землі одразу на північ від перевалу куди смертоносніші за довколишні пагорби Редріджу. Палаючі Степи кишать лютими орками Блекрок, велетенськими вогняними елементалями й чорними дракончиками, тож для недосвідчених шукачів пригод і простих подорожніх тут надзвичайно небезпечно.",al={"чи можна пройти перевал блекрок","чи небезпечний перевал блекрок","вимога рівня перевалу блекрок"}},{q="Хто контролює Перевал Блекрок?",a="Ні Стормвінд, ні Орда повністю не контролюють перевал. Це спірне, слабко укріплене вузьке місце, обабіч якого насідають орки Блекрок і дикі звірі, і варта Редріджу внизу стежить за ним із глибоким страхом.",al={"хто володіє перевалом блекрок","стражі перевалу блекрок","контроль фракцій перевалу блекрок"}}},fp="14,409,20.586.0,31.250.0,58.290.0,28.240.0"}
P.entries["subzone:blackrock-stronghold"] = {n="Твердиня Блекрок",s="Твердиня Блекрок — добре укріплений табір, вирубаний у скелях на півночі Палаючих Степів, просто біля входу до Гори Блекрок. Це великий польовий гарнізон орків Блекрок та їхніх союзників під прапором Темної Орди.",h="Твердиня Блекрок — добре укріплений табір, вирубаний у скелях на півночі Палаючих Степів, просто біля входу...",kw={"твердиня блекрок","темна орда","орки блекрок","палаючі степи","ренд блекгенд","гарнізон"},ang={["faction:Alliance"]="Твердиня — похмуре нагадування про Другу війну: вона стоїть на відстані одного удару від північних кордонів Королівства Стормвінд.",["faction:Horde"]="Для Орди Тралла клан Блекрок — ганебна спадщина Старої Орди: кровожерні, зіпсовані рештки, що зрікаються честі й миру."},sec={{t="Гарнізон Темної Орди",b="Твердиня, що розкинулася на випалених передгір'ях під Горою Блекрок, — головна наземна база клану Блекрок у Палаючих Степах. На відміну від Орди Тралла, ці орки чіпляються за свою войовничу спадщину й служать Рендові Блекгенду та драконородам, що причаїлися вгорі, у шпилі."},{t="Передова Шпиля Блекрок",b="Твердиня — водночас зовнішня оборона й плацдарм для нападів на Гори Редріджу та сусідні людські землі. Фортеця невпинно стежить за південними підступами до гори й кидає виклик кожному, хто наважиться перетнути спустошені пустирі."}},faq={{q="Що таке Твердиня Блекрок?",a="Це укріплена військова база на півночі Палаючих Степів, під самою Горою Блекрок, що правує за зовнішній гарнізон клану орків Блекрок.",al={"що це за місце","твердиня блекрок палаючі степи","що таке твердиня блекрок"}},{q="Чи ці орки дружні до Орди Тралла?",a="Ні. Орки Твердині Блекрок належать до Темної Орди, яку очолює Ренд Блекгенд. Вони не визнають проводу Тралла й ворожі і до Альянсу, і до нової Орди.",al={"чи це орда","чи орки блекрок з орди","дружні до орди"}}},fp="20,275,26.299.0,29.280.0,29.166.0,45.173.0"}
P.entries["subzone:blackthorn-ridge"] = {n="Кряж Чорного Терну",s="Кряж Чорного Терну — порізана, задушена терновиками долина в південній частині Пусток, просто на північ від Рейзорфен Краула. Тут кишать агресивні шипогриви Гостромани, що стережуть свої колючі поселення. Високо на кряжі стоїть табір орчихи-шаманки Брайн, яка оберігає надзвичайно чисте озерце гірської води.",h="Кряж Чорного Терну — порізана, задушена терновиками долина в південній частині Пусток, просто на північ від...",kw={"кряж чорного терну","гостромани","шипогриви","брайн","рейзорфен краул","пустки"},ang={["class:Shaman"]="Кряж — важливе місце паломництва для молодих шаманів Орди, які шукають Брайн, щоб пізнати чистоту природної стихії води серед суворих сухих рівнин.",["faction:Horde"]="Гостромани, що живуть на кряжі, загрожують шляхам постачання Орди через південні Пустки до Тисячі Голок, тож каравани мусять бути постійно напоготові."},sec={{t="Колючий редут",b="Кряж Чорного Терну, що лежить поблизу велетенських наростів Рейзорфен Краула, заріс густими хащами величезних гострих колючок. Шипогриви Гостромани вважають ці землі прадавньою територією і використовують природні загорожі, щоб влаштовувати засідки на чужинців і готувати вилазки в південні Пустки. Попри постійну небезпеку, мандрівники шукають кряж заради відлюдної орчихи-шаманки Брайн: її табір стоїть над джерелом, відомим на весь Калімдор дивовижною прозорістю й духовною чистотою."}},faq={{q="Де Кряж Чорного Терну?",a="Кряж Чорного Терну — на крайньому півдні Пусток, трохи на північ від велетенських колючих заростей довкола Рейзорфен Краулу й на південь від Табору Тауражо.",al={"місце кряжа чорного терну","де чорний терн","як знайти кряж чорного терну"}},{q="Хто живе на Кряжі Чорного Терну?",a="Дно долини кишить ворожими шипогривами Гостроманами. А над їхніми хащами, на високому скелястому виступі, живе Брайн — орк-шаман, що пильнує гірське джерело поблизу.",al={"хто на кряжі чорного терну","мешканці кряжа чорного терну","вепролюди чорного терну"}},{q="Чим особливе озерце під табором Брайна?",a="Хоча довкола посушливі рівнини й колюча скверна шипогривячих хащів, приховане озерце під кряжем має надзвичайно чисту, прозору воду, тож це священне природне осердя для шаманських обрядів.",al={"озерце брайна","вода чорного терну","джерело кряжа чорного терну"}}},fp="16,345,22.491.0,26.152.0,30.187.0,45.233.0"}
P.entries["subzone:blackwolf-river"] = {n="Річка Чорного Вовка",s="Річка Чорного Вовка витікає з Озера Скельної Заводі й збігає крізь Кручу Вітрорізу в Горах Кам'яного Кігтя. Колись це був чистий гірський потік, а тепер його води геть отруєні хижацькими вирубками та промисловими роботами Венчурної Компанії.",h="Річка Чорного Вовка витікає з Озера Скельної Заводі й збігає крізь Кручу Вітрорізу в Горах Кам'яного Кігтя.",kw={"річка","гори кам'яного кігтя","венчурна компанія","гобліни","забруднення","лісоруби"},ang={["class:Druid"]="Осквернення Річки Чорного Вовка гоблінськими лісорубами — тяжка образа для Кола Кенарія і всіх, хто шанує дикі води Калімдору.",["race:Tauren"]="Понівечена земля й каламутні води, зіпсовані зайдами, що женуться за наживою, лише зміцнюють рішучість тауренів очистити Гори Кам'яного Кігтя від цієї безоглядної промислової напасті."},sec={{t="Промислові стоки",b="Спускаючись з Озера Скельної Заводі, Річка Чорного Вовка перетинає улоговину Кручі Вітрорізу. Вона мала б бути незайманою гірською притокою, але натомість узяла на себе весь тягар неприборканого гоблінського підприємництва. Поки Венчурна Компанія розчищає навколишні ліси важкими машинами й циркулярними пилами, мул, мастило та відходи лісозаготівлі невпинно стікають у течію. Сплюндрована річка — яскравий приклад торговельного грабунку, що загрожує дикій природі Кам'яного Кігтя."}},faq={{q="Звідки витікає й куди тече Річка Чорного Вовка?",a="Річка витікає з Озера Скельної Заводі у верхів'ях гір і в'ється вирубаною улоговиною Кручі Вітрорізу.",al={"джерело річки чорного вовка","де річка чорного вовка","місце річки чорного вовка"}},{q="Чому вода в річці забруднена?",a="Венчурна Компанія веде на Кручі Вітрорізу масштабну вирубку лісу за допомогою механічних лісозаготівельних машин. Стоки з її парових машин, відходи й наслідки суцільної вирубки стікають просто в річку.",al={"чому річка брудна","забруднення чорного вовка","забруднення венчурної компанії"}},{q="Хто нині господарює вздовж річки?",a="На березі панує Венчурна Компанія: вона використовує навколишню долину для заготівлі деревини й роботи важких машин, попри опір місцевих звірів і тубільних мешканців.",al={"хто контролює річку чорного вовка","хто біля річки","вороги біля річки чорного вовка"}}},fp="15,259,17.458.0,46.133.0,32.203.0,43.194.0"}
P.entries["subzone:blackwood-den"] = {n="Лігво Чорнолісся",s="Лігво Чорнолісся — осквернене стійбище фурболгів на півдні Темного Узбережжя, біля кордону з Ашенвалем. Колись мирна оселя, печера й табори довкола неї поринули в божевілля разом з усім племенем Чорнолісся. Самотній розвідник нічних ельфів на ім'я Волкор опинився в пастці в печері й чекає допомоги з Обердайна.",h="Лігво Чорнолісся — осквернене стійбище фурболгів на півдні Темного Узбережжя, біля кордону з Ашенвалем.",kw={"лігво чорнолісся","фурболги","волкор","скверна","печера","темне узбережжя"},ang={["class:Druid"]="Друїди оплакують занепад фурболгів, що колись були вірними охоронцями дикої природи, і бачать у божевіллі Лігва Чорнолісся ще одну болючу ознаку отруєної природи Калімдору.",["race:NightElf"]="Для нічних ельфів Обердайна втрата племені Чорнолісся через скверну — трагічна подія, а порятунок Волкора з його лап — нагальний обов'язок, щоб уберегти своїх на південній дорозі."},sec={{t="Осквернена твердиня",b="Лігво Чорнолісся, що лежить біля південного кордону, де Темне Узбережжя сходиться з Ашенвалем, — це звивиста мережа грубих таборів і кам'яниста печера. Фурболги Чорнолісся, що живуть тут, піддалися скверні, яка охопила край, і стали люто ворожими до чужинців. Глибоко в печері нічний ельф Волкор досі в облозі агресивного племені й у смертельній небезпеці, і йому конче потрібна допомога розвідників і мандрівників, посланих з Обердайна."}},faq={{q="Що таке Лігво Чорнолісся?",a="Лігво Чорнолісся — поселення фурболгів і печерний комплекс на крайньому півдні Темного Узбережжя, біля межі з Ашенвалем. Це база зіпсованого скверною племені фурболгів Чорнолісся.",al={"що таке лігво чорнолісся","фортеця чорнолісся","де лігво чорнолісся"}},{q="Хто в печері в Лігві Чорнолісся?",a="У печері — Волкор, нічний ельф, що опинився в пастці у ворожому тилу. Мандрівники, які його знайдуть, мають разом із союзниками в Обердайні влаштувати втечу й безпечно вивести його з лігва.",al={"хто в пастці в печері","хто такий волкор","ельф у лігві чорнолісся"}},{q="Чому тутешні фурболги ворожі?",a="Фурболги Чорнолісся стали жертвами темної скверни, що поширилася Темним Узбережжям і Калімдором після Третьої війни. Ця біда довела їх до несамовитого шалу, і вони нападають на будь-якого чужинця, щойно його побачать.",al={"чому фурболги чорнолісся агресивні","чи фурболги чорнолісся злі","осквернені фурболги темного узбережжя"}}},fp="13,344,22.482.0,22.186.0,40.208.0,34.231.0"}
P.entries["subzone:bladefist-bay"] = {n="Затока Блейдфіст",s="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара. Названа на честь Карґата Блейдфіста, затока служить природною гаванню, зверненою до Великого Моря, у тіні скелястих круч і сусідніх південних берегів Азшари.",h="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара.",kw={"затока блейдфіст","узбережжя","гавань","карґат","розтрощена рука","оргріммар","дуротар"},ang={["class:Rogue"]="Розтрощена Рука діє в тінях Оргріммара як гільдія злодіїв і вбивць Орди, тож для таємних агентів це узбережжя має тихий відгомін.",["race:Orc"]="Затока носить горде й жорстоке ім'я Карґата Блейдфіста, нагадуючи про випробування клану Розтрощеної Руки на Дренорі."},sec={{t="Гавань на Великому Морі",b="Простягшись уздовж північно-східного краю Дуротару, Затока Блейдфіст відкривається просто в неосяжні води Великого Моря. Затиснута скелястими урвищами й підступним прибоєм, вона є головним морським порогом столиці Орди — Оргріммара. Припливи раз у раз викидають на берег плавник, океанське сміття та уламки, тож серед місцевих затока має славу природного збірника морського непотребу. Просто на північ, через воду, височіють прадавні червоні скелі й руїни Азшари, роблячи затоку важливим морським кордоном Дуротару."},{t="Тінь Розтрощеної Руки",b="Затока вшановує Карґата Блейдфіста — славетного вождя клану Розтрощеної Руки, який відтяв собі руку, щоб замінити її клинком під час випробувань старої Орди на Дренорі. Близькість затоки до місць на кшталт Череп-скелі, де в тіні діють культисти й приховані мережі розбійників, перегукується з лютою та безжальною спадщиною клану, чий вождь дав цим водам ім'я."}},faq={{q="На честь кого названо Затоку Блейдфіст?",a="Затоку названо на честь Карґата Блейдфіста — легендарного вождя клану Розтрощеної Руки, що замінив свою відрубану руку смертоносним серпоподібним лезом.",al={"хто такий блейдфіст","на честь блейдфіста","затока каргата блейдфіста"}},{q="Де Затока Блейдфіст?",a="Вона на північно-східному узбережжі Дуротара, просто на схід від головної брами Оргріммара й на південь через воду від Азшари.",al={"місце затоки блейдфіст","де затока блейдфіст","як дістатися затоки блейдфіст"}},{q="Які загрози чатують довкола Затоки Блейдфіст?",a="Берег лежить просто поруч із Череп-скелею — печерою, що зажила лихої слави сховищем чорнокнижників, демонів і членів зловісного культу Палаючого Клинка.",al={"небезпека затоки блейдфіст","небезпеки довкола затоки блейдфіст","вороги затоки блейдфіст"}},{q="Чому затоку іноді називають смітником?",a="Течії Великого Моря постійно виносять на її береги морське сміття, уламки й рештки кораблів, тож затока славиться як звалище всього, що викидає море.",al={"смітник затоки","океанське сміття блейдфіст","сміттєва затока"}}},fp="13,267,25.553.0,28.387.0,33.157.0,31.129.0,39.148.0,46.175.0"}
P.entries["subzone:bloodfen-burrow"] = {n="Нора Кривавої Драговини",s="Нора Кривавої Драговини — печера в південно-західній частині Багна Пилоброду, де кишать люті раптори. Звірі захопили печеру й галявину навколо неї, геть заполонивши руїни поселення, що колись намагалося вижити серед боліт.",h="Нора Кривавої Драговини — печера в південно-західній частині Багна Пилоброду, де кишать люті раптори.",kw={"нора кривавої драговини","багно пилоброду","раптори","печера","кортелло","мисливці"},ang={["class:Hunter"]="Раптори Кривавої Драговини, що гніздяться тут, — люті й прудкі звірі, які чудово підійдуть мисливцям, що шукають витривалих і агресивних болотяних супутників."},sec={{t="Лігво хижаків",b="Захована в південно-західних закутках Багна Пилоброду, Нора Кривавої Драговини — головне лігво агресивних тутешніх рапторів Кривавої Драговини. Вхід до печери й улоговина довкола аж кишать зграєю, яку приваблюють захищена розколина й щедрі мисливські угіддя, що їх дає болото. Біля входу лежать розкидані уламки й розтрощені рештки невідомого поселення — похмуре нагадування про те, хто насправді панує в глибинах болота. А ще мандрівники шепочуть, що Кортелло, відчайдушний пірат, залишив десь у цьому смертоносному лігві одну зі своїх захованих загадок-підказок."}},faq={{q="Хто живе в Норі Кривавої Драговини?",a="Нору заполонили раптори Кривавої Драговини. Вони влаштували густе гніздовище і в печері, і на галявині довкола, нападаючи на кожного, хто необачно вдереться на їхню територію.",al={"хто тут живе","раптори нори кривавої драговини","мобі нори кривавої драговини"}},{q="Що за руїни біля печери?",a="The remains of an unidentified settlement lie outside the cave. Raptors destroyed the settlement, but the identity and fate of its occupants are not recorded.",al={"руїни біля печери","хто збудував хатини біля нори","руїни зовні печери"}},{q="Навіщо шукачеві пригод обшукувати Нору Кривавої Драговини?",a="Окрім полювання на лютих болотяних рапторів, дослідники, що розгадують Загадку Кортелло, мусять спуститися в нору: пірат сховав одну з підказок своєї загадки в темних глибинах печери.",al={"загадка кортелло","скарб нори кривавої драговини","завдання нори кривавої драговини"}}},fp="15,244,18.594.0,30.208.0,36.158.0,47.202.1"}
P.entries["subzone:bloodhoof-village"] = {n="Село Бладгуф",s="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі. Назване на честь племені Бладгуф, воно стає першим великим осередком для молодих мисливців і сміливців, що прямують із Табору Нарачі до Тандер Блафа. Під проводом Бейна Бладгуфа село узгоджує місцеву оборону, торгівлю й традиційні обряди по всіх рівнинах.",h="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі.",kw={"село бладгуф","бейн бладгуф","озеро кам'яного бика","малгор","таурени","поселення"},ang={["faction:Horde"]="Це мирне поселення — важлива зупинка й сполучна ланка між південними рівнинами Малгору та столицею Орди в Тандер Блафі.",["race:Tauren"]="Для молодих тауренів вхід до Села Бладгуф — перший справжній крок із юності до ширшої відповідальності перед племенем і духовної зрілості."},sec={{t="Серце рівнин",b="Розташоване довкола прозорих вод Озера Кам'яного Бика, Село Бладгуф — жвавий осередок торгівлі, ремесла й обрядів у центрі Малгору. Молоді таурени, що пройшли випробування в Таборі Нарачі, приходять сюди відточити вміння, перш ніж рушити далі, до великих плато Тандер Блафа. Село також відоме по всьому Калімдору своїми майстрами-барабанниками й терплячими заводчиками, що приручають диких кодо для подорожей."},{t="Проводирі та обряди",b="Повсякденне врядування й оборона краю лежать на Бейні Бладгуфі, синові Верховного Вождя Кайрна Бладгуфа. Під його пильним оком сміливців посилають убезпечувати пасовища від агресивних звірів, зазіхань шипогривів і тіньової присутності Венчурної Компанії. Поруч із Бейном духовні провідники, як-от Зарлман Ту-Мунс, дбають про внутрішнє життя племені й ведуть новачків через священні мандри на кшталт Обряду Видіння."}},faq={{q="Хто очолює Село Бладгуф?",a="Бейн Бладгуф, син Верховного Вождя Кайрна Бладгуфа, очолює поселення й керує його обороною від загроз центральним рівнинам.",al={"хто очолює село","бейн бладгуф","хто головний в бладгуфі"}},{q="Які важливі обряди тут проводять?",a="Духовні наставники на кшталт Зарлмана Ту-Мунса ведуть молодих тауренів традиційним Обрядом Видіння — неодмінною духовною подорожжю на шляху до дорослості.",al={"обряд видіння","духовні випробування","завдання зарлмана ту-мунса"}},{q="Чим славиться поселення?",a="Село Бладгуф славиться своїми неповторними обрядовими барабанами, а ще це головне місце, де приборкують диких рівнинних кодо й навчають їх ходити під сідлом.",al={"скакуни тауренів","приборкання кодо","барабани бладгуфа"}},{q="Куди вирушають мандрівники, завершивши тут справи?",a="Коли справи в центрі Малгору завершено, мандрівників зазвичай скеровують на північ, до Тандер Блафа — столиці тауренів.",al={"після бладгуфа","куди далі після бладгуфа","наступний центр"}}},fp="17,379,19.417.0,20.454.0,28.141.0,36.160.0,43.146.0,55.142.0"}
P.entries["subzone:bloodtooth-camp"] = {n="Табір Кривавого Ікла",s="Табір Кривавого Ікла — стійбище ворожих осквернених фурболгів у центральному Ашенвалі, трохи на захід від Річки Фалфаррен. Під проводом вождя Рана Бладтуса ці колись мирні створіння піддалися темному божевіллю й нападають на кожного, хто наближається. Табір — одна з головних цілей розвідників Альянсу, які очищають довколишні ліси.",h="Табір Кривавого Ікла — стійбище ворожих осквернених фурболгів у центральному Ашенвалі, трохи на захід від...",kw={"табір кривавого ікла","ран бладтус","фурболги","скверна","річка фалфаррен","ашенваль"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу Табір Кривавого Ікла — осередок скверни, що загрожує безпеці південних гаїв і місячних колодязів Ашенвалю.",["race:NightElf"]="Нічні ельфи бачать у божевіллі племені Рана Бладтуса трагічну ознаку глибокої скверни, що спотворює їхню прадавню батьківщину."},sec={{t="Осквернене лігво",b="Табір Кривавого Ікла, що сховався на південний захід від південного місячного колодязя й на захід від Річки Фалфаррен, — суворе нагадування про занепад, який охоплює Ашенваль. Фурболги, що живуть тут, колись були пов'язані зі священною дикою природою Калімдору, але затяжна духовна скверна поглинула їхнє плем'я. Під командою Рана Бладтуса вони з шаленою ворожістю стережуть своє примітивне поселення, кидаючись і на мандрівників, і на нічних ельфів, що боронять ліс."},{t="Очищення лісу",b="Зграя Рана Бладтуса загрожує ближнім священним місцям, тож вартові Альянсу та їхні союзники не можуть оминути табір. Щоб повернути лісові гармонію — а саме допомогти Рейн Вульфраннер в очищенні, — Кролґ посилає шукачів пригод проникнути до табору, убити Рана Бладтуса й покінчити з його лютими охоронцями."}},faq={{q="Де Табір Кривавого Ікла?",a="Табір Кривавого Ікла — у центрі Ашенвалю, просто на захід від Річки Фалфаррен і трохи на південний захід від південного Місячного Колодязя.",al={"місце табору кривавого ікла","де табір кривавого ікла","знайти табір кривавого ікла"}},{q="Чому тутешні фурболги ворожі?",a="Як і чимало племен фурболгів Ашенвалю, клан Кривавого Ікла став жертвою темної демонічної скверни, що лишилася в нетрях. Вона доводить їх до божевілля й безмежної агресії до всіх чужинців.",al={"чому фурболги кривавого ікла нападають","осквернення кривавого ікла","чи фурболги тут злі"}},{q="Хто очолює фурболгів у Таборі Кривавого Ікла?",a="Табором керує Ран Бладтус — лютий вождь, що верховодить місцевими фурболгами разом зі своєю особистою вартою.",al={"бос табору кривавого ікла","ран кривавий ікол","хто очолює табір кривавого ікла"}},{q="Чому Альянс посилає сюди розвідників?",a="Під час подій «Очищення Рейн» фурболг-вигнанець Кролґ скеровує звитяжців Альянсу вдарити по табору, знищити Рана Бладтуса й усунути загрозу, яку становлять для краю його зіпсовані скверною прибічники.",al={"завдання табору кривавого ікла","чому вбити рана","місія кролга"}}},fp="15,364,15.448.0,20.375.1,33.131.0,34.213.0,42.131.0,39.222.0"}
P.entries["subzone:bloodvenom-falls"] = {n="Водоспад Кривавої Отрути",s="Водоспад Кривавої Отрути — височенний смердючий водоспад, що зривається з осквернених скель північного Сквернолісся. Його отруйний потік живить Річку Кривавої Отрути й несе породжену демонами гниль униз схилами гір до земель нижче за течією.",h="Водоспад Кривавої Отрути — височенний смердючий водоспад, що зривається з осквернених скель північного...",kw={"водоспад кривавої отрути","водоспад","річка кривавої отрути","річка дикого закруту","сквернолісся","темне узбережжя"},ang={["class:Druid"]="Отруйний водоспад — гірке видовище для Кола Кенарія: це головний канал, яким мерзенна недуга Сквернолісся тече до земель унизу.",["race:NightElf"]="Для нічних ельфів видовище Водоспаду Кривавої Отрути, що живить отруєну Річку Дикого Закруту на Темному Узбережжі, — пряма загроза родовим домівкам і прибережним святилищам."},sec={{t="Джерело гнилизни",b="Водоспад Кривавої Отрути, що спадає з урвищ Сквернолісся, — одна з найочевидніших ран, завданих давнім лісам Калімдору. Колись це був чистий гірський каскад, але в Третю війну демонічна магія й рештки Палаючого Легіону перетворили його воду на ядучий мул. Водоспад живить Річку Кривавої Отрути, що в'ється самим серцем Сквернолісся. Звідти отруєний потік мчить гірськими схилами й стає мерзенною Річкою Дикого Закруту на Темному Узбережжі, розносячи заразу далеко за зачумлені межі Сквернолісся."},{t="Отрута для природи",b="Ядучі стоки Водоспаду Кривавої Отрути не лише барвлять річище — вони спотворюють усе, чого торкаються. На болотистих берегах у його бризках розводяться покручені древені, хворі звірі й агресивні слизи. Для друїдів і охоронців лісу, що намагаються стримати гниль Сквернолісся, водоспад — моторошне нагадування, що води північного Калімдору глибоко хворі в самому своєму витоку."}},faq={{q="Куди тече вода з Водоспаду Кривавої Отрути?",a="Водоспад живить Річку Кривавої Отрути. Річка перетинає Сквернолісся, а тоді спадає з гір на Темне Узбережжя, де стає зіпсованою Річкою Дикого Закруту.",al={"куди тече кривава отрута","шлях річки кривавої отрути","куди стікає"}},{q="Чому водоспад зіпсований?",a="Під час Третьої війни демонічна магія Палаючого Легіону просякла край і зіпсувала дикі ліси Сквернолісся. Джерела й високогірні струмки, що живлять водоспад, увібрали цю скверну, і вода перетворилася на отруйну жижу.",al={"чому водоспад зелений","чому вода отруєна","що осквернило водоспад кривавої отрути"}},{q="Чи впливає скверна водоспаду на інші краї?",a="Так. Води спадають зі Сквернолісся західними гірськими хребтами на Темне Узбережжя, виходять там отруєною Річкою Дикого Закруту й несуть гниль до узбережжя.",al={"чи гниліліс отруює темне узбережжя","як це впливає на темне узбережжя","забруднення річок темного узбережжя"}},{q="Чи можна очистити води Водоспаду Кривавої Отрути?",a="Коло Кенарія й далі шукає способів очистити Сквернолісся, але через величезний об'єм і глибоку насиченість річки демонічною скверною зцілити водоспад — титанічне завдання, яке досі не розв'язане.",al={"чи друїди можуть виправити","чи можна очистити водоспад","очищення водоспаду"}}},fp="16,219,17.560.0,17.381.0,48.179.0,31.240.0,52.164.0,47.203.0"}
P.entries["subzone:bloodvenom-post"] = {n="Застава Кривавої Отрути",s="Застава Кривавої Отрути — віддалене поселення Орди на скелястих урвищах західного Сквернолісся, звідки видно Темне Узбережжя. Тауренські будівлі й тауренська варта дають Орді плацдарм у краї, де панують демонічна скверна й осквернена звірина.",h="Застава Кривавої Отрути — віддалене поселення Орди на скелястих урвищах західного Сквернолісся, звідки видно...",kw={"застава кривавої отрути","орда","таурени","сквернолісся","темне узбережжя","застава"},ang={["faction:Horde"]="Як єдиний укріплений притулок Орди в Скверноліссі, цей табір дає безпеку, захист і базу для дій у цілком ворожій глушині.",["race:Tauren"]="Таурени-воїни тримають цю заставу, щоб вивчати спустошення природи, заподіяне Легіоном, і протидіяти скверні, що нищить природних духів землі."},sec={{t="Хиткий плацдарм",b="До Застави Кривавої Отрути, схованої на високих кручах над Темним Узбережжям, можна дістатися, якщо звернути з головного шляху Сквернолісся й піти оскверненим південним берегом Річки Кривавої Отрути. Збудований із традиційних тауренських наметів, тотемів і дозорних веж, цей табір дає мандрівникам Орди важливу базу посеред лісу, що помирає. Звідси розвідники стежать за наступом демонічних сил, вивчають, як поширюється отруєння вод, і намагаються наглядати за ворожою звіриною, спотвореною рештками сили Палаючого Легіону."},{t="Очі над кряжем",b="Табір не лише спостерігає за отруєними нетрями Сквернолісся: він стоїть просто на краю урвища, звідки видно північ Темного Узбережжя. Таке відлюдне розташування служить подвійній меті: Орда знає про пересування нічних ельфів уздовж західного узбережжя, а сама лишається поза легкою досяжністю патрулів Альянсу, що ходять центральним шляхом лісу."}},faq={{q="Де Застава Кривавої Отрути?",a="Застава Кривавої Отрути захована на західних хребтах центрального Сквернолісся. Щоб дістатися до неї з головної дороги північ — південь, ідіть південним берегом Річки Кривавої Отрути на захід вузькою стежкою, що огинає скелястий схил.",al={"знайти заставу кривавої отрути","як дістатися застави кривавої отрути","напрям до застави кривавої отрути"}},{q="Хто контролює цю заставу?",a="Застава Кривавої Отрути належить Орді: її охороняють таурени, і збудована вона в традиційному тауренському стилі.",al={"хто керує заставою кривавої отрути","фракція застави кривавої отрути"}},{q="Чому заставу названо Кривавою Отрутою?",a="Вона названа на честь сусідньої Річки Кривавої Отрути, чиї води забруднила й отруїла демонічна скверна, що просочилася в ліс.",al={"чому кривава отрута","значення назви кривавої отрути"}},{q="З якими загрозами стикаються тут розвідники?",a="Застава постійно потерпає від зіпсованих скверною звірів Сквернолісся — скажених шаблезубів, отруєних слизунів і спотворених деревнів, — а також від демонічної присутності Ради Тіней і решток Палаючого Легіону по всьому краю.",al={"вороги кривавої отрути","що нападає на заставу кривавої отрути"}}},fp="15,243,21.534.0,21.345.0,33.232.0,26.90.0,33.146.0,37.244.0"}
P.entries["subzone:bloodvenom-river"] = {n="Річка Кривавої Отрути",s="Річка Кривавої Отрути — смердючий потік, що перетинає центральне Сквернолісся й просякнутий демонічною скверною, яка сплюндрувала давній ліс. Її гнилі води просочуються нижче за течією через гори до Темного Узбережжя й перетворюються на отруєну Річку Дикого Закруту.",h="Річка Кривавої Отрути — смердючий потік, що перетинає центральне Сквернолісся й просякнутий демонічною...",kw={"річка кривавої отрути","річка","сквернолісся","темне узбережжя","річка дикого закруту","скверна"},ang={["class:Druid"]="Річка Кривавої Отрути — разюче свідчення осквернення священних гаїв Калімдору: вона розносить скверну по різних краях і вимагає, щоб природу відновили.",["race:NightElf"]="Для калдореїв бачити, як води їхніх родових лісів отруюють Темне Узбережжя через Річку Дикого Закруту, — гірке нагадування про незагоєну рану, яку лишив Легіон."},sec={{t="Жила скверни",b="Річка Кривавої Отрути, що тече оскверненим серцем Сквернолісся, — відкритий канал духовного й тілесного тління цієї землі. Її береги вкриті мерзенними слизами, мутованими звірами й гидкими стоками, що лишилися після вторгнення Палаючого Легіону. Скверна в руслі настільки сильна, що отруює землі далеко за межами самого Сквернолісся: вона тече на захід, до прибережних лісів Темного Узбережжя, вже як Річка Дикого Закруту."}},faq={{q="Чому річка зіпсована?",a="Річка тече центральним Сквернолісся — давнім лісом нічних ельфів, глибоко спотвореним демонічною магією Палаючого Легіону під час Третьої війни. Скверна цілком просякла землю й води, і річка стала руслом отруйного мулу й некротичного слизу.",al={"скверна річки кривавої отрути","чому вода зелена","отрута річки гнилолісся"}},{q="Куди тече Річка Кривавої Отрути?",a="Річка тече отруєною долиною Сквернолісся, а тоді прориває гори й спадає на Темне Узбережжя. За хребтом її зіпсовані води течуть далі під назвою Річка Дикого Закруту.",al={"шлях річки кривавої отрути","куди вона тече","річка до темного узбережжя"}},{q="Які істоти живуть на берегах річки?",a="У воді й на мулистих берегах живуть отруйні слизуни, спотворені звірі й зіпсовані хижаки, яких приваблює чи породжує ця згубна демонічна пошесть.",al={"дика природа річки кривавої отрути","мобі біля річки","чудовиська в річці"}}},fp="16,261,20.435.0,27.281.0,37.206.0,41.151.0"}
P.entries["subzone:bluefen"] = {n="Синє Багно",s="Синє Багно — мокра болотиста місцина в північній частині Багна Пилоброду, між Селом Папоротяної Стіни й Селом Чорного Копита. Тут кишать агресивні болотяні хижаки, а ще ця трясовина стала плацдармом для таємних лазутчиків Терамору, що стежать за пересуванням Орди.",h="Синє Багно — мокра болотиста місцина в північній частині Багна Пилоброду, між Селом Папоротяної Стіни й Селом...",kw={"синє багно","багно пилоброду","лазутчики терамору","кам'яний молот","раптори","кроколіски"},ang={["faction:Alliance"]="Хоч дикі звірі й роблять подорож небезпечною, розвідники Терамору користуються густою болотяною рослинністю Синього Багна, щоб пильно стежити за таборами огрів і тауренів неподалік.",["faction:Horde"]="Синє Багно, що лежить одразу на схід від Села Папоротяної Стіни, подвійно небезпечне для чемпіонів Орди: тут і люті болотяні звірі, і пильні лазутчики Терамору, які шпигують за вашими союзниками з Кам'яного Молота."},sec={{t="Спірне болото",b="Затиснуте між ограми Кам'яного Молота із Села Папоротяної Стіни на заході й тауренами Ґрімтотем із Села Чорного Копита на сході, Синє Багно втілює всі дикі небезпеки Багна Пилоброду. Задушливе болото кишить хижаками — тут раптори, велетенські павуки, птахи-падальники й кроколіски, що чатують у воді. Окрім природних хижаків, мандрівникам доводиться мати справу з лазутчиками Терамору, які нишпорять каламутною місцевістю, шпигують за Ордою й поширюють людський вплив углиб болота."}},faq={{q="Де Синє Багно?",a="Синє Багно — на півночі Багна Пилоброду, просто між Селом Папоротяної Стіни на заході й Селом Блекгуф на сході.",al={"місце синього багна","де синє багно","карта синього багна"}},{q="Які загрози чатують у Синьому Багні?",a="Болото кишить небезпечними звірами — павуками, кроколісками, рапторами й болотяними птахами. До того ж місцину потай розвідують лазутчики Терамору, загрожуючи мандрівникам з Орди.",al={"вороги синього багна","що живе в синьому багні","мобі синього багна"}},{q="Чому розвідники Терамору діють у Синьому Багні?",a="Лазутчики Терамору стежать із Синього Багна за північчю Багна Пилоброду: вони спостерігають за сусіднім поселенням огрів Кам'яного Молота — Селом Папоротяної Стіни — й патрулюють спірні болотяні стежки.",al={"лазутчики терамору","чому альянс тут","шпигуни терамору"}}},fp="7,276,15.502.0,25.135.0,37.198.0,43.196.0"}
P.entries["subzone:bluegill-marsh"] = {n="Багно Синьозябрих",s="Багно Блакитнозябрих — мокра трясовина на заході Багнокраю, де розкинулося поселення ворожого племені мурлоків-Блакитнозябрих. Протоки й халупи люто стережуть ці водяні істоти під владою громила на ім'я Жерун. Мандрівникам, що йдуть через західні драговини, варто обережно обирати шлях, щоб їх не оточили на мілині.",h="Багно Блакитнозябрих — мокра трясовина на заході Багнокраю, де розкинулося поселення ворожого племені...",kw={"багно синьозябрих","мурлоки","жерун","гавань менетіл","синьозябрі","багнокрай"},ang={["faction:Alliance"]="Розташовані неподалік від Гавані Менетіл, агресивні мурлоки-Блакитнозябрі — постійна дошкульна загроза для мандрівників і шляхів постачання через західний Багнокрай."},sec={{t="Кишливе лихо",b="Серед багнистих рівнин західного Багнокраю Багно Блакитнозябрих повне мулу, очерету й булькотливих бойових вигуків місцевих мурлоків. Плем'я Блакитнозябрих поставило по всій застояній воді грубі первісні табори й оголосило ці землі своїми. На відміну від самотніших болотяних звірів, ці мурлоки живуть і полюють тісними зграями. Обачні волоцюги й розвідники з Гавані Менетіл знають: забредеш на їхню територію — і на тебе нападуть з усіх боків, а надто тоді, коли каламутною мілиною нишпорить грізний ватажок Жерун."}},faq={{q="Що таке Багно Блакитнозябрих?",a="Багно Блакитнозябрих — болотиста місцина на заході Багнокраю. Це головне поселення й гніздовище агресивного племені мурлоків Блакитнозябрих.",al={"де багно блакитнозябрих","що це за місце","болото мурлоків мокрих земель"}},{q="Хто панує на болоті?",a="Плем'я Блакитнозябрих очолює могутній і лютий мурлок на прізвисько Жерун, що пильнує скупчені табори й нищить кожного суходільця, який зазіхає на їхні води.",al={"вождь мурлоків мокрих земель","ґоблер","хто веде блакитнозябрих мурлоків"}},{q="Чому тут небезпечно мандрувати самому?",a="Мурлоки тут рідко никають поодинці. Вони збираються біля хиж і на берегах тісними ватагами по двоє-троє, тож самотнього мандрівника в глибокому в'язкому болоті дуже легко здолати.",al={"чому тут так багато мурлоків","чи багно блакитнозябрих важке","агресія мурлоків"}},{q="Навіщо мандрівники заходять у Багно Блакитнозябрих?",a="Розвідників і шукачів пригод із сусідніх поселень на кшталт Гавані Менетіл раз у раз посилають на болото проріджувати агресивних мурлоків і повертати крадене, яке ті потягли до своїх таборів.",al={"навіщо йти сюди","завдання багна блакитнозябрих","причини відвідати"}}},fp="14,361,17.573.0,23.163.0,25.189.0,41.197.0,45.201.0"}
P.entries["subzone:bolgan-s-hole"] = {n="Нора Болґана",s="Нора Болґана — підземна печера в південних скелях Села Ґелкіс у Пустограї. Це внутрішнє святилище клану кентаврів Ґелкіс, де живуть найвищі вожді й зберігаються священні реліквії землі.",h="Нора Болґана — підземна печера в південних скелях Села Ґелкіс у Пустограї.",kw={"нора болґана","село ґелкіс","пустограй","кентаври","принцеса терадрас","кристали","печера"},ang={["class:Shaman"]="Печера похмуро показує, як шанування землі може спотворитися, коли воно пов'язане з кривавою спадщиною Принцеси Терадрас, а не з природною рівновагою духів."},sec={{t="Осередок влади Ґелкіс",b="Видовбана глибоко в зубчастих урвищах над табором Ґелкіс, Нора Болґана слугує племені командним центром. Саме тут правлячий хан тримає двір в оточенні досвідчених вартових і найвпливовіших шаманів племені. Печера — природне укріплення проти ворожих кланів, передусім кровожерливих кентаврів Маґрам на сході."},{t="Сльози Принцеси Землі",b="Крім військового значення, печера має для Ґелкіс глибокий релігійний сенс. Із вологих кам'яних стін проростають сяйливі блакитні мінерали, відомі як сльози Терадрас. Шамани Ґелкіс одержимо збирають і стережуть ці кристали, шануючи їх як божественне благословення, що дарує підземний захист Принцеси Терадрас — первісної стихійної володарки землі й праматері роду кентаврів."}},faq={{q="Де Нора Болґана?",a="Нора Болґана — печера в південній частині Села Ґелкіс, захована серед пагорбів півдня Пустограю.",al={"місце нори болґана","де нора болґана","вхід до нори болґана"}},{q="Хто живе в Норі Болґана?",a="У печері — вищий провід кентаврів Ґелкіс, зокрема хан клану, як-от Хан Шака, а також їхнє найближче коло охоронців і шаманів-містиків.",al={"хто в норі болґана","бос нори болґана","місце ґелкіса хана"}},{q="Що за сяйливі блакитні кристали в печері?",a="Ці кристали звуться сльозами Терадрас. Ґелкіс шанують їх як зриме втілення прихильності своєї матері-землі й вірять, що камені дарують містичний захист тим, хто ними володіє.",al={"блакитні кристали в норі болґана","сльози терадраса","каміння нори болґана"}},{q="Чи можуть гравці безпечно зайти в Нору Болґана?",a="Зазвичай кентаври Ґелкіс у печері люто ворожі до чужинців. Але мандрівники, які стануть на бік Ґелкіс, винищуючи їхніх ненависних суперників — клан Маґрамів, — можуть здобути таку прихильність, що зможуть ходити печерою спокійно.",al={"чи нора болґана ворожа","дружні до ґелкіса","чи можна зайти в нору болґана"}}},fp="13,217,24.365.0,27.409.0,31.116.0,31.173.0,51.204.0,39.230.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="Кістки Ґраккаронда",s="Кістки Ґраккаронда — рештки скелета величезного бронзового дракона, що біліють під сонцем у центрі Силітусу. Цей змій загинув під час прадавньої Війни Мінливих Пісків, і тепер його кістки — похмурий пам'ятник, священний для вартових-анубісатів кіражів.",h="Кістки Ґраккаронда — рештки скелета величезного бронзового дракона, що біліють під сонцем у центрі Силітусу.",kw={"кістки ґраккаронда","бронзовий дракон","війна мінливих пісків","анубісати","оссиріан","силітус"},ang={["race:NightElf"]="Скелет — суворе нагадування про Війну Мінливих Пісків, коли калдореї й чотири драконячі роди пліч-о-пліч відкидали навалу кіражів."},sec={{t="Пам'ятник мінливих пісків",b="Посеред продутих вітрами дюн центрального Силітусу лежать велетенські ребра й череп Ґраккаронда — бронзового дракона, що загинув під час прадавньої Війни Мінливих Пісків. У тій апокаліптичній битві тисячу років тому великого дракона повалив Оссиріан Безшрамний — воїн-анубісат, звеличений темними силами міста-царства. Для анубісатів цей трофей з поля бою — священне свідчення їхньої переваги над драконячими зграями, тож його так і лишили незайманим там, де дракон упав."}},faq={{q="Чиї це кістки?",a="Це рештки Ґраккаронда — великого бронзового дракона з Бронзового драконячого роду. Він загинув у битві з комахоподібними військами Ан'Кіража тисячу років тому, під час Війни Рухомих Пісків.",al={"хто був ґраккаронд","який дракон тут загинув","скелет дракона сілітус"}},{q="Хто вбив Ґраккаронда?",a="Ґраккаронда вбив воїн-анубісат Оссиріан Безшрамний. Перемога над бронзовим змієм принесла Оссиріанові величезну славу й темні благословення від володарів Ан'Кіража.",al={"хто вбив дракона","як загинув ґраккаронд"}},{q="Чому анубісати шанують це місце?",a="Анубісати вважають кістяк священним, бо він нагадує про їхню вирішальну перемогу над могутнім драконячим родом. Він стоїть серед відкритих дюн як переможний символ їхньої сили проти тих, хто прийшов їх ув'язнити.",al={"чому ануб'ісати шанують","чому кістки священні"}}},fp="19,269,32.494.0,22.205.0,22.185.0,39.228.0"}
P.entries["subzone:booty-bay"] = {n="Буті Бей",s="Буті Бей — розлогий піратський притулок, вбудований у стрімкі морські скелі на півдні Долини Стренглторну; ним заправляють Нападники Чорної Води з картелю Стімвідл. Суходолом сюди потрапляють крізь роззявлену пащу велетенської акулячої туші. Це нейтральний порт із залізними правилами, де Альянс і Орда змішуються під пильним оком добре озброєних гоблінських вишибал.",h="Буті Бей — розлогий піратський притулок, вбудований у стрімкі морські скелі на півдні Долини Стренглторну...",kw={"буті бей","піратський порт","нападники чорної води","картель стімвідл","долина стренглторну","нейтральне місто"},ang={["class:Rogue"]="Буті Бей, відомий як рай для пройдисвітів, аж кишить зв'язками в злочинному світі, скупниками краденого, замкненими скриньками й потаємними донощиками, готовими продати таємниці за монету.",["faction:Alliance"]="Далеко на південь від захищених кордонів Стормвінда Буті Бей пропонує мандрівникам Альянсу рідкісні нейтральні вигоди, польотні маршрути й морське сполучення просто з Калімдором."},sec={{t="Кубло пройдисвітів і наживи",b="Колись тут було людське поселення під назвою Бухта Чорної Води, яке згодом заполонили тролі джунглів, а ще до Першої війни бухту захопили гобліни з картелю Стімвідл. Нині це міжнародне роздоріжжя й притулок для пройдисвітів, вигнанців і купців. Портом з балконів таверни «Солоний моряк» керують Барон Ревілґаз і Флотоводець Сігорн. На позір тут панує беззаконня, але насправді лад суворий: кожен може пити, торгувати чи наймати найманців, якщо дотримується миру картелю й сплачує портові збори."},{t="Загрози з моря",b="Гамірні доки Буті Бею сполучають Східні Королівства просто з Раджетом за Великим Морем, тож порт — важливий осередок торгівлі й подорожей між континентами. Проте величезні статки притягують невпинну ворожість. Головний ворог міста — Буканіри Кривавого Вітрила, агресивний піратський флот, що раз у раз грабує кораблі Чорної Води, никає узбережжям Стренглторну й відкрито плете змову, щоб цілком знищити й пограбувати гоблінський порт."}},faq={{q="Хто править Буті Бей?",a="Портом править Барон Ревілґаз — помітна постать картелю Стімвідл — у тісній співпраці з Флотоводцем Сігорном, тауреном-командиром Нападників Чорної Води. Обидва ведуть свої справи з верхніх поверхів таверни «Солоний Моряк», звідки видно гавань.",al={"лідер буті бею","хто править буті беєм","бос буті бею"}},{q="Чому гравці Альянсу й Орди можуть тут стояти пліч-о-пліч?",a="Буті Бей контролює нейтральний картель Стімвідл, для якого прибуток і торгівля куди важливіші за ворожнечу фракцій. Картель суворо дотримується нейтралітету: він радий кожному, хто має гроші, і спускає добірних гоблінів-вишибал на кожного, хто наважиться почати бійку.",al={"чому буті бей нейтральний","безпечна зона буті бею","чи орда нападе на альянс тут"}},{q="Хто такі Буканіри Кривавого Вітрила?",a="Буканіри Кривавого Вітрила — суперницьке злочинне угруповання, що веде запеклу війну з Нападниками Чорної Води. Вони тримають кораблі вздовж південного узбережжя Долини Стренглторну й завзято плетуть змову, щоб захопити Буті Бей і його прибуткову гавань.",al={"пірати кривавого вітрила","чому кривавий вітрила ненавидять буті бей","переказ про буканірів кривавого вітрила"}},{q="Куди плаває корабель із Буті Бей?",a="Пасажирське судно з нижніх доків пливе через Велике Море просто до портового містечка Раджет у Пустках — це головний нейтральний шлях між півднем Східних Королівств і Калімдором.",al={"куди пливе корабель буті бею","призначення корабля","корабель до калімдора"}},{q="Що за велетенська статуя біля входу в затоку?",a="Величезна статуя невідомого гобліна з розкинутими руками стоїть на Мисі Жанейро, одразу за входом до гавані. Вона правує за орієнтир і привітальний пам'ятник для купецьких кораблів і піратських команд, що прибувають.",al={"статуя буті бею","колос буті бею","статуя на острові"}}},fp="9,361,30.568.0,20.455.0,20.281.0,55.273.0,33.237.0,38.224.0,56.223.0"}
P.entries["subzone:boulder-gor"] = {n="Болдер'ґор",s="Болдер'ґор — скелястий пагорб у західній частині Аратійського нагір'я, просто на північ від зруйнованого людського королівства Стромґард. Тут стоїть табір огрів Каменекулаків та їхніх незвичних союзників — лісових тролів із племені Сухокорів.",h="Болдер'ґор — скелястий пагорб у західній частині Аратійського нагір'я, просто на північ від зруйнованого...",kw={"болдер'ґор","огри","каменекулаки","сухокори","тролі","стромґард","аратійське нагір'я"},ang={["faction:Alliance"]="Для сил Альянсу, що прагнуть відвоювати Стромґард, Болдер'ґор — серйозна загроза, яка чатує просто на північному порозі занепалого королівства.",["race:Troll"]="Тролі Темного Списа не знайдуть тут рідні: лісові тролі Сухокорів із Болдер'ґора плекають давню глибоку ворожнечу до всіх чужинців, зокрема й до інших тролячих племен."},sec={{t="Лігво огрів і тролів",b="Стрімка круча Болдер'ґор, що здіймається просто на північ від осипаних валів Фортеці Стромгард, належить клану Каменекулаків. У її тіні стоїть курган Застави Каменекулаків, тож це місце — головний оплот огрської сили в нагір'ї. Як не дивно, тутешні огри ділять вогнища й укріплення з лісовими тролями з племені Сухокорів, серед яких є й тіньові заклиначі, що підсилюють грубу силу клану темною магією. Через цей союз центральні дороги нагір'я постійно небезпечні для мандрівників."},{t="Навколишні землі",b="Зі схилів Болдер'ґора видно відкриті простори західного нагір'я. Затиснутий між руїнами Стромґарда, куди проник Синдикат, і дикими осередками стихій на рівнинах, Болдер'ґор лишається пильно стереженою, ворожою твердинею племінної згуртованості проти мандрівників і з Альянсу, і з Орди."}},faq={{q="Що таке Болдер'ґор?",a="Болдер'ґор — високий пагорб і табір на північ від Фортеці Стромгард на Аратійському нагір'ї. Тут повно огрів Каменекулаків і лісових тролів Сухокорів.",al={"де болдер'ґор","інформація про болдер'ґор","що це за місце"}},{q="Чому лісові тролі живуть тут поруч з ограми?",a="Тролі Сухокори й огри Каменекулаки тримаються розважливого союзу на Аратійському нагір'ї. І ті, й ті прагнуть панувати на нагір'ї й відбиватися від суперників, поєднуючи тролячу тіньову магію з грубою огрською силою.",al={"чому тролі тут","союз огрів сухокорів","тролі й огри"}},{q="Які помітні місця поблизу Болдер'ґору?",a="Болдер'ґор лежить просто на північ від Фортеці Стромгард, а в самому пагорбі — огрський курган Застава Каменекулаків.",al={"місця поруч","що біля болдер'ґора","пам'ятки"}},{q="Чи Болдер'ґор дружній до Орди чи Альянсу?",a="Ні до кого. Огри Каменекулаки й тролі Сухокори з Болдер'ґору цілком ворожі і до Альянсу, і до Орди й люто боронять свій пагорб від чужинців.",al={"чи можна безпечно","чи ворожий болдер'ґор"}}},fp="11,249,25.542.0,21.312.0,20.171.0,50.216.0,42.122.0,49.174.0"}
P.entries["subzone:boulder-lode-mine"] = {n="Шахта Кам'яної Жили",s="Шахта Кам'яної Жили — хижацька розробка, врізана в пагорби північно-східних Пусток. Хоча орківські прапори й сторожові вежі свідчать, що першою це місце облаштувала Орда, нині ним твердо заволоділа й орудує безжальна Венчурна Компанія.",h="Шахта Кам'яної Жили — хижацька розробка, врізана в пагорби північно-східних Пусток.",kw={"шахта кам'яної жили","венчурна компанія","бос копперплаґ","смарагд","гірництво","пустки"},ang={["faction:Horde"]="Бачити, як Венчурна Компанія хазяйнує в укріпленнях із прапорами Орди, — дратівливе нагадування про те, як зухвало гоблінський картель зазіхає на землі Калімдору.",["profession:Mining"]="Глибокі тунелі врізаються просто в посушливі пагорби, відкриваючи багаті рудні жили, які Венчурна Компанія нещадно вибирає."},sec={{t="Корпоративна ділянка",b="Обвітрені орківські споруди біля входу до Шахти Кам'яної Жили вказують на те, що колись цією ділянкою володіла або навіть заснувала її Орда. Проте сьогодні тут кишать наглядачі й костоломи Венчурної Компанії, що працюють під орудою Боса Копперплаґа. Гоблінський синдикат нещадно розорює каньйон, не зважаючи ні на місцеву природу, ні на своїх робітників, — його цікавлять лише цінні мінерали, дорогоцінне каміння й промислові машини."},{t="Самоцвіти й креслення",b="Чутки про багатства з Шахти Кам'яної Жили дійшли до сторонніх вух у Раджеті. Начальник Пристані Діззівіг послав найманців забрати величезний смарагд, який нібито знайшли в її тунелях, а інженери, що хочуть розібратися в складних гоблінських машинах, знають: Бос Копперплаґ ховає у своєму таборі важливі робочі посібники."}},faq={{q="Хто контролює Шахту Кам'яної Жили?",a="Шахтою керує Венчурна Компанія під безпосередньою владою Боса Копперплаґа; її стережуть добре озброєні охоронці компанії й наглядачі за робітниками.",al={"хто керує шахтою","бос шахти кам'яної жили","хто в кам'яній жилі"}},{q="Чи шахта спершу належала Орді?",a="Уцілілі орківські дерев'яні споруди, вартові вежі й вилинялі прапори Орди переконливо свідчать, що спершу шахту заснувала чи привласнила Орда, а вже потім прийшла й захопила її Венчурна Компанія.",al={"орочі прапори шахти","шахта орди","чому тут прапори орди"}},{q="Чому Начальника Пристані Діззівіга цікавить це місце?",a="Діззівіг прочув, що рудокоп у Шахті Кам'яної Жили викопав незвично великий і цінний смарагд, і наймає безпринципних найманців, щоб ті пробралися в тунелі й поцупили камінь за частку прибутку.",al={"завдання діззівіга про шахту","смарагд пустки","скарб шахтаря"}},{q="Що пов'язує Боса Копперплаґа із самофланжем?",a="У Боса Копперплаґа — необхідний посібник із керування загадковою машиною-самофланжем, знайденою неподалік, і інженери з Раджета посилають шукачів пригод забрати в його ватаги книгу та її розкидані сторінки.",al={"інструкція самофланжа шахта","інструкція коппера","шахта ріллі"}}},fp="17,247,15.464.0,19.338.0,31.159.0,39.200.0,53.201.0,56.212.0"}
P.entries["subzone:boulderfist-hall"] = {n="Зала Кам'янокулаків",s="Зала Кам'янокулаків — добре укріплений курган огрів у південних пагорбах Аратійського нагір'я, просто на північ від Мосту Тандол. Це місцева твердиня клану, чиї огри під проводом Кор'ґреша Колдрейджа тримають у кулаці довколишні торгові шляхи й долини.",h="Зала Кам'янокулаків — добре укріплений курган огрів у південних пагорбах Аратійського нагір'я, просто на...",kw={"зала кам'янокулаків","огри","кор'ґреш колдрейдж","міст тандол","аратійське нагір'я","каменекулаки"},ang={["faction:Alliance"]="Тутешні огри засіли просто над Мостом Тандол і постійно загрожують засідками гінцям і підкріпленням Альянсу, що йдуть на північ з Айронфорджа в нагір'я.",["faction:Horde"]="Щоб утвердитися в Аратійському нагір'ї, треба зламати незалежну владу огрів і очистити південний хребет, аби вберегти шляхи Орди з Гаммерфолла."},sec={{t="Оплот грубої сили",b="Зала Кам'янокулаків, видовбана в скелястих південних кручах Аратійського нагір'я, — головний оплот клану в цьому краї. Під захистом земляних валів і глибоких печер огри-громили й огри-маги тримають укріплене поселення за кілька кроків від Села Сухокорів і стратегічного Мосту Тандол. У глибині кургану чатує їхній місцевий вождь Кор'ґреш Колдрейдж разом із посіпаками на кшталт Фаланакса. Із цієї твердині огри силою тримають довколишні дороги, тож будь-який мирний шлях між нагір'ям і Багнокраєм небезпечний і для мандрівників, і для валок із припасами."}},faq={{q="Що таке Зала Кам'янокулаків?",a="Це укріплений огрський курган і печерний комплекс на півдні Аратійського нагір'я — головна база клану Каменекулаків у цьому краї.",al={"що це за місце","пагорб каменекулаків","печера огрів арати"}},{q="Хто править Залою Кам'янокулаків?",a="Твердиню очолює огр-вождь Кор'ґреш Колдрейдж, що керує кланом із глибокої печери в кургані разом зі звитяжцями на кшталт Фаланакса.",al={"хто керує залою каменекулаків","бос огрів арати","кор'ґреш"}},{q="Чому це місце важливе стратегічно?",a="Завдяки близькості до Мосту Тандол огри Каменекулаки можуть загрожувати життєво важливому сухопутному шляху між Аратійським нагір'ям і Каз Моданом: перекривати рух і битися із сусідніми тролями й мандрівниками.",al={"чому огри тут","небезпека мосту тандол"}},{q="Чи Каменекулаки — союзники тролів Сухокорів поблизу?",a="Ні. Огри Каменекулаки й лісові тролі з Села Сухокорів живуть зовсім поруч, але лишаються незалежними й ворожими угрупованнями, що змагаються за панування на Аратійському нагір'ї.",al={"огри й тролі друзі","союз сухокорів"}}},fp="16,315,27.633.0,25.157.0,27.153.0,45.217.0,61.182.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Застава Кам'яного Кулака",s="Застава Каменекулаків — укріплений курган у самій глибині огрського поселення Болдер'ґор в Аратійському нагір'ї. Це внутрішнє лігво й сховище, де живуть войовничі огри та кілька тролів із племені Сухокорів.",h="Застава Каменекулаків — укріплений курган у самій глибині огрського поселення Болдер'ґор в Аратійському...",kw={"застава кам'яного кулака","болдер'ґор","огри","курган","сухокори","аратійське нагір'я"},ang={["faction:Alliance"]="Розвідникам Альянсу в нагір'ї краще обходити курган десятою дорогою: огри-громили всередині нападають на кожного чужинця, щойно його побачать.",["faction:Horde"]="Огри з кургану не розрізняють фракцій і нападають на мандрівників Орди так само охоче, як на їхніх суперників з Альянсу."},sec={{t="Твердиня в кургані",b="Застава Каменекулаків, видовбана в землі й камені західного нагір'я, — серце Болдер'ґора. Поки нагорі в поселенні панують огри-громили, у надрах застави зосереджена головна сила клану й прихований темний підземний прихисток. Між ограми тут часом трапляються кілька тролів-знахарів із племені Сухокорів — ознака хиткої співпраці між племенами."}},faq={{q="Де Застава Каменекулаків?",a="Застава Каменекулаків — внутрішній курган у більшому огрському поселенні Болдер'ґор на західних просторах Аратійського нагір'я.",al={"місце застави каменекулаків","де застава каменекулаків","вхід до пагорба каменекулаків"}},{q="Чому в огрській заставі тролі?",a="Лісові тролі Сухокори живуть неподалік на Аратійському нагір'ї й часом ділять землю з ограми Каменекулаками. У глибині застави поруч з ограми можна зустріти кількох знахарів-Сухокорів, що чаклують своє ремесло.",al={"чому тролі в огрській заставі","тролі каменекулаків","тролі сухокорів арати"}},{q="Хто ув'язнений у заставі?",a="Наразі не відомо, щоб у заставі тримали когось із бранців на ім'я. Її вогкі коридори належать громилам Каменекулаків і кільком знахарям-Сухокорам, тож кожен, хто туди зайде, має готуватися до бою, а не до порятунку.",al={"в'язні каменекулаків","хто в пастці","полонені огрів арати"}},{q="Хто очолює огрів у заставі?",a="Нутрощами кургану патрулюють громили клану, але відомо, що там чаїться й надзвичайно лютий огр на ім'я Коворк — помітна загроза.",al={"коворк","бос каменекулаків арати","рідкісний каменекулак"}}},fp="19,239,29.390.0,37.154.0,44.240.0,33.219.0,39.150.0"}
P.entries["subzone:boulderslide-cavern"] = {n="Печера Кам'яного Зсуву",s="Печера Кам'яного Зсуву — підземний лабіринт нір у найглибшому кінці Яру Кам'яного Зсуву в Горах Кам'яного Кігтя. Тут головне лігвище й копальня місцевих кобольдів Кам'яного Зсуву, які одержимо риють тунелі в пошуках сяйливих мінералів.",h="Печера Кам'яного Зсуву — підземний лабіринт нір у найглибшому кінці Яру Кам'яного Зсуву в Горах Кам'яного...",kw={"печера","кобольди","резоніт","ґоґґерок","гірництво","гори кам'яного кігтя"},ang={["class:Shaman"]="Резонітові кристали й сплячий землянин Ґоґґерок відгукуються первісною магією землі — відлунням прадавніх каменетворців, що колись формували цей світ.",["profession:Mining"]="Клан Кам'яного Зсуву невтомно розробляє печеру, прокладаючи тунель за тунелем, аби дістатися сяйливих жил магічного резоніту."},sec={{t="Розкопки резоніту",b="Кобольди Кам'яного Зсуву глибоко вгризлися в скелі Кам'яного Кігтя й зробили Печеру Кам'яного Зсуву своєю твердинею. На відміну від звичайних печерних шкідників, що шукають лише сховку, ці кобольди гарячково видобувають резоніт — рідкісний сяйливий пурпуровий кристал, вкраплений по всій породі. Кристали пульсують залишками земної магії, і через це істоти шаленіють, люто обороняючи свої розкопки від кожного прибульця."},{t="Сплячий велетень",b="Глибше в печерах безоглядні розкопки відкрили прадавні таємниці. У підземну скелю вмурована резонітова скриня, в якій спить Ґоґґерок — землянин із незапам'ятних часів. Кобольди невпинно риють довкола цієї містичної реліквії й ризикують пробудити істоту, сповнену первісної магії каменю, — а це вмить стане загрозою для всього яру."}},faq={{q="Що тут добувають кобольди?",a="Кобольди добувають резоніт — рідкісний фіолетовий кристал, вкраплений у скельні стіни печери. Мінерал ледь чутно гуде від слідів магії землі, тож це цінна здобич, і кобольди фанатично стережуть свої схованки.",al={"що таке резоніт","фіолетові кристали кам'яного кігтя","чому кобольди добувають"}},{q="Хто такий Ґоґґерок?",a="Ґоґґерок — давній землянин, що дрімає в резонітовій скрині в глибині печери. Розкопки кобольдів довкола його місця спочинку можуть порушити його багатовіковий сон.",al={"переказ про ґоґґерока","земляни кам'яного зсуву","сплячий велетень у печері"}},{q="Де Печера Кам'яного Зсуву?",a="Вхід до печери — у дальньому кінці Яру Кам'яного Зсуву, серед скелястих гір на півдні Гір Кам'яного Кігтя, трохи на північний схід від стежки до Пусток.",al={"місце печери кам'яного зсуву","як знайти печеру кам'яного зсуву","де печера"}},{q="Чому Орда цікавиться цією печерою?",a="Орда стежить за печерою, щоб стримувати навалу агресивних кобольдів, яка вихлюпується в яр, а також цікавиться магічними властивостями резонітових кристалів, які вони добувають.",al={"завдання орди кам'яного зсуву","чому посилають до кам'яного зсуву"}}},fp="19,271,16.421.0,20.353.1,33.236.0,16.188.0,37.176.0,43.185.0"}
P.entries["subzone:boulderslide-ravine"] = {n="Яр Кам'яного Зсуву",s="Яр Кам'яного Зсуву — дикий відлюдний каньйон серед центральних вершин Гір Кам'яного Кігтя, куди веде Стежка Павутинника. Прямі сутички між Ордою та Альянсом його здебільшого оминули: це кам'янистий підхід до Печери Кам'яного Зсуву, де досі живуть дикі гірські звірі.",h="Яр Кам'яного Зсуву — дикий відлюдний каньйон серед центральних вершин Гір Кам'яного Кігтя, куди веде Стежка...",kw={"яр","каньйон","печера","наскельні малюнки","таурени","гірництво"},ang={["profession:Mining"]="Стрімкі скельні стіни яру — надійне місце, щоб угледіти рудні жили, які оголює рухлива гірська порода.",["race:Tauren"]="Вицвілі малюнки в бічній печерці мають виразні риси тауренських племінних знаків — натяк на те, що стежки ваших предків пролягали крізь височини Кам'яного Кігтя."},sec={{t="Тихий гірський прохід",b="Яр Кам'яного Зсуву, захований осторонь Стежки Павутинника, — вузька розколина у височинах Кам'яного Кігтя. Поки лісоруби, нічні ельфи та Орда воюють за деревину й священні галявини по всьому краю, цей скелястий прохід війська майже не тривожать. Тутешня живність — дикі гірські барани та бродячі скельні звірі на кшталт скельних буревісників, що пробираються підступними уступами й прямовисними кам'яними стінами. Не зводять очей з яру й рудошукачі: на кам'янистих схилах, що ведуть углиб до печер, раз у раз проступають багаті рудні жили."},{t="Сліди в камені",b="Навпроти входу до Печери Кам'яного Зсуву, над самим яром, є невелика тиха печерка. Її освітлюють грубі смолоскипи, всередині стоять поторощені часом бочки з припасами, а стіни вкривають примітивні племінні малюнки. Ці грубі зображення разюче схожі на прадавні тауренські візерунки — певно, тубільні племена мандрували тут або шукали тимчасового прихистку серед цих скель задовго до того, як у гори прийшли нинішні війни."}},faq={{q="Де Яр Кам'яного Зсуву?",a="Яр Кам'яного Зсуву — у Горах Кам'яного Кігтя. До нього можна дістатися Стежкою Павутинника вгору, до вищих скель.",al={"місце яру кам'яного зсуву","як дістатися яру кам'яного зсуву","де яр кам'яного зсуву"}},{q="Які істоти живуть у Яру Кам'яного Зсуву?",a="Яр населяють здебільшого місцеві звірі, передусім гірські барани й небезпечні скельні скрадачі, як-от Скельні Буревії.",al={"мобі яру кам'яного зсуву","що в яру кам'яного зсуву"}},{q="Що за покинута печера навпроти Печери Кам'яного Зсуву?",a="Навпроти входу до печери — невелика ніша, освітлена смолоскипами, із старими бочками. На її кам'яних стінах — племінні малюнки, схожі на традиційне мистецтво тауренів, тож колись тут, певно, бували місцеві мандрівники чи мисливці.",al={"покинута печера кам'яного зсуву","печера в яру кам'яного зсуву","печера тауренів кам'яного кігтя"}},{q="Чим важливий Яр Кам'яного Зсуву?",a="Він — природний підступ до Печери Кам'яного Зсуву, підземного лігва глибоко в горах, а ще мандрівники знаходять тут цінні рудні виходи.",al={"навіщо яр кам'яного зсуву","призначення яру кам'яного зсуву"}}},fp="19,306,21.567.0,19.442.0,37.130.0,43.128.0,59.222.0,39.172.0"}
P.entries["subzone:brackenwall-village"] = {n="Село Папоротяної Стіни",s="Село Папоротяної Стіни — головний форпост Орди в Багні Пилоброду, що тулиться серед трясовин у північно-західному куті краю. Його заснували вцілілі огри Кам'яного Молота, після того як дракони спустошили їхнє давнє поселення на півдні, і тепер село — хистка твердиня в оточенні шпигунів Альянсу, дезертирів і чорних драконів.",h="Село Папоротяної Стіни — головний форпост Орди в Багні Пилоброду, що тулиться серед трясовин у...",kw={"село папоротяної стіни","багно пилоброду","кам'яний молот","огри","мок'морокк","драз'зілб","орда"},ang={["faction:Alliance"]="Папоротяна Стіна лежить глибоко на ворожій території, але розслідування зникнення дипломата й справи дезертирів-ренегатів із Терамору приведуть відважних агентів аж до краю табору огрів.",["faction:Horde"]="Папоротяна Стіна — ваш єдиний прихисток і пункт польотів у болоті; обороняючи її, ви зберігаєте для Орди важливий пост спостереження й захищений фланг проти Терамору."},sec={{t="Притулок Кам'яного Молота",b="Коли чорне драконяче кодло вигнало огрів Кам'яного Молота з їхнього давнього дому в Селі Кам'яного Молота на півдні болота, їхній ватажок — Володар Мок'Морокк, наступник Рекссара, — повів уцілілих на північ, у глиб болота, щоб збудувати Папоротяну Стіну. Поселення, що виросло довкола традиційних земляних насипів, хатин і старої сторожової вежі, дало пошарпаному кланові захищений прихисток. Хоч село й на боці Орди, воно гниє зсередини: Мок'Морокк сидить склавши руки, накопичує припаси й не хоче протистояти драконячій загрозі, лишаючи духовний і тактичний провід кланом таким постатям, як огр-маг Драз'Зілб, та посланцям Орди."},{t="Очі в болоті",b="Окрім внутрішнього розладу, Папоротяну Стіну обсідають і зовнішні загрози. Лазутчики Терамору постійно чатують у хащах, шпигують за тим, що діється в селі, і доповідають в острівну фортецю. А Павала Ріта, дезертира з Терамору, вигнаного із Загубленого Мису, підозрюють у крадіжці важливих припасів із форпосту. Під пильними поглядами зі сходу й під загрозою чорних драконів, що нишпорять на півдні, Папоротяна Стіна лишається відрізаним плацдармом Орди, який стримує і Альянс, і виводок Оніксії."}},faq={{q="Чому тут огри — союзники Орди?",a="Це огри Кам'яного Молота — шляхетний клан, який звитяжець Рекссар прийняв до сучасної Орди під час заснування Дуротара. Здолавши їхнього колишнього ватажка, Рекссар став їхнім вождем і прив'язав клан до нового союзу Вождя Тралла, а тоді передав провід Мок'Морокку.",al={"чому огри союзники орди","переказ про клан кам'яного молота","хто ці огри"}},{q="Чому Кам'яний Молот оселився тут, а не лишився в старому домі?",a="Їхнє родове поселення на півдні Багна Пилоброду захопив і стер на порох чорний драконячий рід. Володар Мок'Морокк повів уцілілих на північ, у болото, і заснував Папоротяну Стіну як укріплений прихисток.",al={"що сталося з селом кам'яного молота","чому папоротяна стіна","огри-біженці"}},{q="Хто керує Селом Папоротяної Стіни?",a="Поселенням керує Володар Мок'Морокк, але його владою чимало хто невдоволений. Замість того щоб згуртувати народ і відвоювати батьківщину чи кинути виклик драконам, він ховається в селі, а щоденні негаразди мусять розв'язувати огр-маг Драз'Зілб і посланці Орди.",al={"керівник папоротяної стіни","хто керує папоротяною стіною","мок'морокк"}},{q="Чому біля села шпигуни Терамору?",a="Попри крихке перемир'я між Терамором і Оргріммаром, військо Леді Джайни Праудмур пильно стежить за будь-якими пересуваннями військ Орди в Багні Пилоброду. Лазутчики никають околицями Папоротяної Стіни, доповідаючи про сили огрів і дії Орди.",al={"шпигуни терамору пилові болота","лазутчики терамору","чому терамор стежить"}}},fp="19,343,23.633.0,15.527.1,47.294.0,71.229.0,40.263.0,50.262.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Гарбузова Ділянка Брекуеллів",s="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн. Колись домівку родини Брекуеллів, її поля й хатину цілком прибрало до рук Братство Дефіас як робочий сховок. Тут зустрічаються змовники-розбійники й звідси переправляють украдене золото.",h="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн.",kw={"гарбузова ділянка брекуеллів","ферма","братство дефіас","розбійники","принцеса","сурена каледон","ліс елвінн"},ang={["class:Warlock"]="У халупі на фермі переховується втікачка-учениця Сурена Каледон, чиє вкрадене кольє з кривавика потрібне, щоб зв'язати блукача Порожнечі.",["faction:Alliance"]="Захоплена ділянка — одна з найсхідніших робочих баз Дефіасів в Елвінні, що безпосередньо загрожує сусіднім фермам і торговим шляхам."},sec={{t="Розбійницький прихисток",b="Ферма Брекуеллів на південний схід від садиби Стоунфілдів колись була родючим клаптем елвіннської землі. Нині її законні господарі зникли безслідно — їх вигнала, а може, й гірше, хвиля злочинності, що здіймається. За їхньої відсутності Братство Дефіас захопило міцну хатину й зарослі поля ферми. Місце працює як схованка й перевалочний пункт, де розбійники перегруповуються подалі від пильних очей патрулів Ґолдшира. Помітні змовники на кшталт Морґана Збирача використовують відлюдну ділянку, щоб приймати партії золота, незаконно вкраденого з лісових копалень."},{t="Свині й темна магія",b="Дефіаси — не єдині бешкетники, що нишпорять серед гарбузового бадилля. Брекуелли лишили по собі величезну свиню-рекордистку на ім'я Принцеса, яка блукає ділянкою й без упину тероризує сусідні поля. Тим часом горище хатини та господарські будівлі приховують небезпечні особисті справи: розбійник Ерлан Драджмур звабив Сурену Каледон — ученицю-чорнокнижницю, що втекла від свого наставника в Стормвінді з украденим артефактом-кривавиком, і так привернув до сховку увагу темних практиків."}},faq={{q="Що сталося з родиною Брекуеллів?",a="Їхня доля достеменно невідома. Коли Братство Дефіас поширило свою присутність на південний схід Лісу Елвінн, Брекуеллів або змусили втекти, або вбили, а їхні гарбузові поля й хата дісталися розбійникам.",al={"де брекуелли","хто жив на фермі брекуеллів","доля родини брекуеллів"}},{q="Навіщо Братству Дефіас ця ферма?",a="Ферма — відлюдна база біля межі лісу. Тут братство зберігає награбоване й керує контрабандою — скажімо, отримує через кур'єрів на кшталт Морґана Збирача партії краденого шахтного золота — подалі від Варти Стормвінда.",al={"чому дефіас тут","що бандити роблять на ділянці","дефіас у брекуеллів"}},{q="Хто така Принцеса?",a="Принцеса — величезна свиня-призерка, яку колись виростили Брекуелли. Покинута, коли ферма впала, вона розрослася ще більше, бо раз у раз вдирається на сусідню Ферму Стоунфілдів і пожирає їхній добірний урожай.",al={"свиня принцеса","гігантська свиня","чому тут величезний кабан"}},{q="Навіщо чорнокнижники приходять на гарбузову ділянку?",a="Сурена Каледон, учениця стормвіндського наставника чорнокнижників Ґакіна Зв'язувача Темряви, викрала могутнє Намисто Кровавика й утекла на ферму, щоб сховатися там зі своїм коханцем — розбійником Дефіас Ерланом Драджмуром. Ґакін посилає сюди молодих чорнокнижників стратити її й повернути реліквію.",al={"завдання чорнокнижника брекуелл","сурена кейледон","завдання пустоти ґакіна"}}},fp="23,317,14.602.0,19.504.1,38.236.0,46.283.0,16.221.0,42.276.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Яр Тернистого Клинка",s="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари. Це укріплене лігво шипогривів племені Щетиноспинних, які раз у раз нападають на сусіднє тауренське поселення, Табір Нарачі. Молодих тауренських сміливців посилають сюди довести свою силу й захистити батьківщину від цих лютих зайд.",h="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари.",kw={"яр тернистого клинка","шипогриви","щетиноспинні","плато червоної хмари","табір нарачі","шарптаск торнмантл"},ang={["faction:Horde"]="Зачистка войовничих Щетиноспинних у Яру Тернистого Клинка допомагає Орді закріпити перші позиції по всьому Малгору.",["race:Tauren"]="Для молодих тауренів, що дорослішають у Таборі Нарачі, похід у Яр Тернистого Клинка — одне з найперших випробувань бойової та духовної витривалості на захист племені."},sec={{t="Скалка в боці плато",b="Вирізьблений у випаленій сонцем землі Плато Червоної Хмари, Яр Тернистого Клинка густо заріс колючими хащами й усіяний стійбищами шипогривів. Плем'я Щетиноспинних використовує цю природну фортецю як плацдарм для наскоків на Табір Нарачі, загрожуючи безпеці молодих тауренів, що входять у зрілий вік. Шамани й воїни Щетиноспинних на чолі з Вождем Шарптаском Торнмантлом живуть у глибині яру серед вишколених бойових вепрів. Для Шу'хало удар у саме серце каньйону — водночас важливий обряд посвяти й сувора необхідність, щоб убезпечити рівнини."}},faq={{q="Що таке Яр Тернистого Клинка?",a="Яр Тернистого Клинка — каньйон на північно-східному краю Плато Червоної Хмари в Малгорі. Тут повно шипогривів Щетиноспинів, і це їхня місцева твердиня.",al={"яр тернистого клинка","що таке яр тернистого клинка","тернистий клинок мулґор"}},{q="Чому шипогриви Щетиноспини нападають звідси?",a="Щетиноспини люто стережуть свої землі й вважають присутність тауренів зазіханням на землі, які вони мають за свої. З Яру Тернистого Клинка вони раз у раз здійснюють набіги на сусідній Табір Нарачі.",al={"чому вепролюди нападають","мотиви щетиноспинів","табір нараше вепролюди"}},{q="Хто очолює шипогривів у Яру Тернистого Клинка?",a="Тутешніх шипогривів очолює Вождь Шарптаск Торнмантл — грізний ватажок, що живе у великій хижі в глибині яру.",al={"ватажок яру тернистого клинка","бос вепролюдів мулґору","вождь гострозуб тернорубаха"}},{q="Чому молоді таурени вирушають до яру?",a="Старійшини й вожді Табору Нарачі доручають молодим звитяжцям увійти в яр, відкинути загрозу Щетиноспинів, проредити їх і здолати їхніх ватажків, щоб убезпечити плато.",al={"завдання тауренів тернистого клинка","чому йти до тернистого клинка","завдання табору нараше"}}},fp="19,341,26.544.0,28.181.0,53.214.0,46.147.0,41.199.0"}
P.entries["subzone:bramblescar"] = {n="Тернистий Шрам",s="Тернистий Шрам — потужно укріплене поселення шипогривів Гостроманів на півдні Пусток. Густі колючі терновики захищають стійбище, а його мешканці ведуть жорстоку війну із суперницьким племенем Щетиноспинів по той бік Золотого Шляху.",h="Тернистий Шрам — потужно укріплене поселення шипогривів Гостроманів на півдні Пусток.",kw={"тернистий шрам","гостромани","шипогриви","щетиноспини","золотий шлях","пустки"},ang={["faction:Horde"]="Захистити Золотий Шлях від набігів шипогривів із Тернистого Шраму вкрай важливо, щоб зберегти безпечне сполучення між Перехрестям, Табором Тауражо й південним прикордонням."},sec={{t="Твердиня серед колючок",b="Тернистий Шрам, врізаний у порізані велетенські колючі хащі південних Пусток, — важливий редут шипогривів Гостроманів. Оборонні терновики виростають настільки густими й гострими, що відлякують випадкових мандрівників, але шипогриви всередині аж ніяк не мирні. Затято ревниві до своєї землі й ворожі до чужинців, вони раз у раз нападають на кожного, хто наблизиться до їхніх меж, бо вважають усіх, хто не шипогрив, загарбниками землі, благословенної їхніми давніми богами-вепрами."},{t="Кривава ворожнеча племен",b="Тернистий Шрам перебуває у вічній напрузі навпроти Аґама'ґора, через Золотий Шлях, — стійбища, яке тримає суперницьке плем'я Щетиноспинів. Два племені зчепилися в нескінченній війні за панування над південними Пустками. Відбиваючись від мандрівників Орди на шляху й відганяючи загони Щетиноспинів, воїни Гостроманів із Тернистого Шраму постійно в лютій бойовій готовності."}},faq={{q="Хто живе в Тернистому Шрамі?",a="У Тернистому Шрамі живе плем'я шипогривів Гостроманів, що боронить свій зарослий колючками табір і від суперників-шипогривів, і від усіх мандрівників, що проходять повз.",al={"хто тут","мобі тернистого шраму","вепролюди тернистого шраму"}},{q="Чому тутешні шипогриви б'ються між собою?",a="Гостромани з Тернистого Шраму й шипогриви Щетиноспини через дорогу в Аґама'ґорі — запеклі вороги, що ведуть люту кровну ворожнечу за панування на півдні Пусток.",al={"чому вони воюють","гостромани проти щетиноспинів","війна вепролюдів"}},{q="Де Тернистий Шрам?",a="Тернистий Шрам лежить на південних рівнинах Пусток, трохи на схід від головного Золотого Шляху, навпроти Аґама'ґору.",al={"місце тернистого шраму","де тернистий шрам","як знайти тернистий шрам"}},{q="Чи тутешні шипогриви ворожі до Орди?",a="Так. Шипогриви Гостромани вважають Орду загарбниками, що зазіхнули на їхні священні племінні землі, і нападають на кожного мандрівника, що підійде близько.",al={"чи тернистий шрам дружній","репутація орди тернистий шрам"}}},fp="11,238,17.466.0,17.402.0,25.164.0,46.184.0,29.121.0,43.157.0"}
P.entries["subzone:brewnall-village"] = {n="Село Брюнолл",s="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану. Засноване родиною Барліброю, воно служить полігоном для сміливих пивоварних дослідів і місцевої оборони від диких звірів. Хоч його й називають селом, насправді це радше сільський табір у засніжених гномських низинах Дун Мороґу.",h="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану.",kw={"село брюнолл","барліброю","пивовари","долина холодного вітерцю","гномреґан","дун мороґ"},ang={["race:Dwarf"]="Для дворфів пошук Барліброю досконалого рецепта — почесна справа, що підтримує одну з найкращих традицій Айронфорджа.",["race:Gnome"]="Розташоване поруч із Гномреґаном, село — несподівана дворфська застава глибоко в гномських долинах західного Дун Мороґу."},sec={{t="Гірке варево в долині",b="Сховане серед заметів Долини Холодного Вітерцю, Село Брюнолл лежить просто посеред споконвічних гномських земель західного Дун Мороґу. Тут живе клан Барліброю — непохитні дворфські пивовари, віддані вдосконаленню прадавніх рецептів і створенню найкращого стауту. Хоч це й зветься селом, застава складається здебільшого з наметів і просто неба розставленого пивоварного начиння, а не з кам'яних будівель. Випробовуючи дослідні партії елю й відбиваючись від лютих тутешніх вовків та ведмедів, Барліброю чимало покладаються на мандрівних горян, які збирають рідкісні інгредієнти й охороняють долину."}},faq={{q="Що таке Село Брюнолл?",a="Село Брюнолл — невеликий дворфійський табір у Долині Холодного Вітерцю на заході Дун Мороґу, трохи на схід від Гномреґана. Це застава, де клан Барліброу випробовує нові рецепти пива й дає раду місцевим звірам.",al={"де село брюнолл","що за село брюнолл","інформація про брюнолл"}},{q="Чому це звуть селом, якщо тут немає будинків?",a="Попри назву «село», це по суті табір просто неба з наметів і барил із припасами. Барліброу облаштували тут свою броварню в холодному кліматі, так і не збудувавши справжніх кам'яних осель.",al={"чому це табір","де будинки","споруди брюнолла"}},{q="Чому дворфійське поселення стоїть на гномівських землях?",a="Західна половина Дун Мороґу оточує Гномреґан і заселена здебільшого гномами, але тісний союз Айронфорджа з гномами робить спільні поселення звичною справою. Барліброу оселилися тут, у Долині Холодного Вітерцю, щоб спокійно займатися своїм ремеслом.",al={"дворфи біля гномреґану","чому дворфи тут","дворфійський табір на землях гномів"}},{q="З якими негараздами стикаються мешканці?",a="На табір часто нападають агресивні звірі долини, передусім скельні кабани, ведмеді й морозні вовки. До того ж Барліброу постійно шукають рідкісних і незвичних складників, щоб винайти нові, ще кращі напої.",al={"завдання брюнолла","що потрібно барлібрю","проблеми села"}}},fp="16,380,27.637.0,25.243.0,53.234.0,57.266.0,36.244.0"}
P.entries["subzone:brightwood-grove"] = {n="Гай Брайтвуд",s="Гай Брайтвуд — темний лісовий простір одразу на захід від Даркшира в Сутінколіссі. Колись частина мирного хліборобського краю, тепер він кишить лютими воргенами Найтбейн, що отаборилися серед зруйнованих садиб і нападають на кожного мандрівника, який підійде надто близько.",h="Гай Брайтвуд — темний лісовий простір одразу на захід від Даркшира в Сутінколіссі.",kw={"гай брайтвуд","воргени","нічна згуба","даркшир","сутінколісся"},ang={["class:Hunter"]="Темні хащі гаю — сувора місцевість для вистежування лютих воргенів Найтбейн, що перевіряє пильність кожного мисливця перед засідками за деревами.",["faction:Alliance"]="Гай Брайтвуд лежить просто за брамою Даркшира, тож знищення тутешніх зграй воргенів життєво важливе, щоб обложене місто не відрізали від заходу."},sec={{t="Гай у тіні",b="Гай Брайтвуд, що видніється просто з околиць Даркшира, уособлює повзучу небезпеку, яка загрожує межам міста. Садиби й огорожі, що колись розмежовували мирні ниви, тепер повалені й гниють. На їхньому місці воргени Найтбейн спорудили грубі табори й никають зарослими галявинами. Близькість цих вовкоподібних звірів — постійна загроза для міста, тож Нічна Варта й перехожі шукачі пригод мусять раз у раз проріджувати їхні лави, доки вони не захопили поселення."}},faq={{q="Де Гай Брайтвуд?",a="Гай Брайтвуд — на сході Сутінколісся, трохи на захід від містечка Даркшир, уздовж головних стежок.",al={"місце гаю брайтвуд","де гай брайтвуд","брайтвуд сутінковий ліс"}},{q="Які істоти живуть у Гаю Брайтвуд?",a="Гай заполонили дикі воргени Найтбейн. Ці прокляті вовколюди влаштували грубі табори в зруйнованих будівлях і нападають на кожного, хто наближається.",al={"чудовиська гаю брайтвуд","вороги брайтвуда","що живе в брайтвуді"}},{q="Чим гай небезпечний для Даркширу?",a="Гай Брайтвуд лежить одразу на захід від Даркширу, тож агресивні зграї воргенів у хащах — пряма загроза міським патрулям, шляхам постачання й усім мандрівникам, що прибувають дорогою.",al={"чому гай небезпечний","загроза брайтвуда даркширу"}},{q="Чи є в гаю дружні поселення?",a="Ні. Кілька кам'яних будівель і хуторів на околицях гаю цілком зруйновані, покинуті на поталу негоді й захоплені мандрівними воргенами.",al={"чи є дружні в брайтвуді","містечко брайтвуд"}}},fp="16,279,17.516.0,26.111.0,40.174.0,40.207.0,48.152.0"}
P.entries["subzone:brill"] = {n="Брілл",s="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона. Колись квітуче людське містечко, тепер воно править за адміністративний і військовий осередок для щойно пробуджених мерців, що виходять за межі Похоронного Подзвону.",h="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона.",kw={"брілл","тірісфаль","відступники","цепелін","магістрат севрен","таверна шибеничний кінець","культ проклятих"},ang={["faction:Horde"]="Пристань цепелінів за містом — головна ланка північної Орди між Лордероном і союзними твердинями в Калімдорі та Східних Королівствах.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, Брілл — перший проблиск цивілізації й місце, де починають доводити вірність Темній Леді."},sec={{t="Від чумної землі до бастіону",b="До Третьої війни Брілл був жвавим селом під владою місцевих дворян — родин Барових і Аґамандів. Цьому добробуту настав кінець, коли Кел'Тузад обрав ці місця для найперших дослідів Культу Проклятих із Чумою Нежиті. Спустошлива пошесть прокотилася населенням так швидко, що місцеве ополчення було вибите, а по собі лишила величезне братське кладовище.\n\nТепер, відбудований Відступниками під проводом Магістрата Севрена, Брілл зберігає обвітрену лордеронську архітектуру під покровом похмурої цілеспрямованості. Містечко править за командний центр краю, координуючи оборону від вторгнень Багряного Хрестового Походу, мандрівних решток Погибелі та місцевих звірів, спотворених некромантичним тлінням."},{t="Перехрестя північного Лордерона",b="Окрім місцевої оборони, Брілл — важливе перехрестя, що з'єднує Галявини Тірісфалю з рештою Орди. Над головою гоблінська вежа цепелінів забезпечує сполучення на південь, до Дуротару, і вглиб Долини Стренглторну. У самому поселенні Таверна «Шибеничний Кінець» править не лише за темний прихисток для подорожніх, а й за імпровізовану лабораторію, де полонених багряних фанатиків допитують і піддають аптекарським дослідам."}},faq={{q="Хто править Бріллом?",a="Магістрат Севрен керує цивільним управлінням і місцевою обороною Брілла від імені Леді Сильвани Віндраннер і Відступників.",al={"хто править бріллом","хто керує бріллом","магістрат бріллу"}},{q="Чому під Бріллом такий величезний цвинтар?",a="Саме в Бріллі Кел'Тузад провів одні з перших дослідів Чуми Нежиття на живих. Зараза з жахливою швидкістю викосила місцевих людей, тож довелося влаштувати велике кладовище, щоб поховати жертв, перш ніж вони повстануть як Погибель.",al={"цвинтар біля бріллу","кладовище під бріллом","чому стільки могил"}},{q="Для чого Таверна «Шибеничний Кінець»?",a="Окрім того що тут ночують утомлені мандрівники, підвал таверни правує за базу для аптекарів, які проводять хімічні й токсикологічні досліди на полонених фанатиках Багряного Хрестового Походу.",al={"шибеничний кінець","корчма бріллу","що відбувається в таверні бріллу"}},{q="Куди літає цепелін із вежі під Бріллом?",a="Вежа цепелінів, яку обслуговують гобліни, сполучає Лордерон просто з Калімдором під Оргріммаром, а також на півдні — з Базовим Табором Ґром'ґол у Долині Стренглторну.",al={"куди летять цепеліни бріллу","куди літають дирижаблі з бріллу","маршрути польотів бріллу"}}},fp="5,273,29.744.0,32.429.0,16.135.0,52.252.0,37.176.0,54.164.0"}
P.entries["subzone:brill-town-hall"] = {n="Ратуша Брілла",s="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю. Найпомітніша будівля містечка, вона править за цивільний штаб, звідки Відступники керують своїми місцевими володіннями й координують оборону галявин.",h="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю.",kw={"ратуша брілла","брілл","магістрат севрен","відступники","врядування","тірісфаль"},ang={["faction:Horde"]="Союзники Орди, прибувши в Тірісфаль, можуть завітати до ратуші, щоб зрозуміти, як Відступники підтримують цивільну владу й військовий лад на своїх потемнілих рідних землях.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, ратуша — перший смак упорядкованого цивільного врядування в державі Королеви Сильвани, де офіційно організовують місцеву оборону й відновлення."},sec={{t="Цивільний осідок Відступників",b="Поки значна частина Лордерона лежить розбита й зруйнована, Ратуша Брілла досі стоїть як діючий громадський центр під владою нежиті. Усередині Магістрат Севрен керує справами містечка зі свого подіуму, роздаючи шукачам пригод Відступників важливі доручення й розпорядження. Якщо не рахувати Лігва Осквернителя в Аратійському нагір'ї, це одна з небагатьох визнаних ратуш у відомому світі, якою справді керують Відступники, — похмура пародія й водночас дієве продовження міської бюрократії старого Лордерона."}},faq={{q="Для чого Ратуша Брілла?",a="Це місцеве осердя влади поселення Брілл. Провід Відступників, передусім Магістрат Севрен, звідси організовує місцеву оборону, видає укази й доручає важливі справи мандрівникам і щойно пробудженій нежиті.",al={"призначення ратуші бріллу","що це за будівля","чому відвідати ратушу бріллу"}},{q="Хто тут головний?",a="Магістрат Севрен керує ратушею зі своєї кафедри: він веде міські справи від імені Відступників і спрямовує дії по всьому центру Галявин Тірісфалю.",al={"хто керує ратушею бріллу","керівник ратуші бріллу","хто магістрат"}},{q="Чим ця ратуша особлива порівняно з іншими?",a="Ратуші — зазвичай пережиток живих людських королівств. Ратуша Брілла особлива тим, що це одна з небагатьох діючих громадських зал, які утримують Відступники; таке є хіба що в місцях на кшталт Лігва Осквернителя на Аратійському нагір'ї.",al={"унікальна ратуша відступників","чи є інші ратуші відступників"}}},fp="15,278,26.509.0,37.251.0,22.176.0,49.226.0"}
P.entries["subzone:broken-hall"] = {n="Зруйнована Зала",s="Зруйнована Зала — затоплений зовнішній поріг затонулого Храму Атал'Гаккара на Болоті Скорботи. Вона розкололася, коли Ізера, Аспект драконів, разом зі своєю зграєю потягла величний зикурат під воду, і нині ці руїни стоять покинуті, бо фанатики Атал'аї відступили в глибші святилища.",h="Зруйнована Зала — затоплений зовнішній поріг затонулого Храму Атал'Гаккара на Болоті Скорботи.",kw={"зруйнована зала","храм атал'гаккара","затонулий храм","атал'аї","ізера","болото скорботи"},ang={["race:Troll"]="Для тролів, які шанують лоа, Зруйнована Зала — похмуре нагадування про загибель, що спіткала фанатиків Атал'аї, які пішли проти решти свого народу, аби служити Гаккарові Душолупу."},sec={{t="Затоплений поріг",b="Коли зелені дракони обрушили свій гнів на жрецтво Атал'аї й занурили їхній нечестивий зикурат у Ставок Сліз, найбільше від катаклізму постраждали зовнішні споруди. Підлога Зруйнованої Зали повністю обвалилася, і каламутна болотяна вода затопила приміщення. Через руйнування й затоплення тролі-культисти покинули цю вхідну залу й відступили вглиб комплексу. Шукачам пригод, які проникають до затонулого храму, доводиться брести цими розмоклими руїнами, перш ніж піднятися сходами до Зали Масок."}},faq={{q="Що таке Зруйнована Зала?",a="Це крайня вхідна зала Храму Атал'Гаккара, одразу за затопленим входом під Ставком Сліз.",al={"огляд зруйнованої зали","що це за місце","вхідна зала храму"}},{q="Чому Зруйнована Зала затоплена й зруйнована?",a="Залу зруйновано, коли зелений драконячий рід затягнув увесь храм під болотяні води, щоб зупинити закликання Бога Крові Гаккара: підлога тріснула, а залу затопило.",al={"чому зруйнована зала мокра","чому зала затоплена","хто зруйнував залу"}},{q="Чи живуть у цій залі тролі Атал'аї?",a="Сама Зруйнована Зала здебільшого покинута. Після затоплення верхнього храму культисти Атал'аї відступили в сухіші, зручніші для оборони зали глибше в комплексі.",al={"вороги зруйнованої зали","чи порожня зруйнована зала"}},{q="Куди ведуть сходи у Зруйнованій Залі?",a="Піднявшись кам'яними сходами із затопленої Зруйнованої Зали, дослідники потрапляють просто до Зали Масок.",al={"сходи зруйнованої зали","вихід зруйнованої зали","куди йти зі зруйнованої зали"}}},fp="11,304,17.555.0,24.141.0,42.193.0,49.184.0,44.115.0"}
P.entries["subzone:broken-pillar"] = {n="Зламаний Стовп",s="Зламаний Стовп — вивітрене скупчення прадавніх тролячих руїн, що стирчать із дюн на південь від Ґаджетзана. Тут облаштував відлюдну дослідницьку станцію гоблін-старатель і вчений Марвон Рівітсікер, який вивчає загадкові артефакти, поховані в довколишніх пісках.",h="Зламаний Стовп — вивітрене скупчення прадавніх тролячих руїн, що стирчать із дюн на південь від Ґаджетзана.",kw={"зламаний стовп","марвон рівітсікер","ґаз'рідіан","тролячі руїни","ґаджетзан","танаріс"},ang={["race:Gnome"]="Цікавість, що рухає дослідженнями Марвона Рівітсікера, який вивчає невідомі властивості реліквій, перегукується з гномівськими науковими амбіціями, хоча методи в нього суто гоблінські.",["race:Troll"]="Ці розсипані стовпи — урочисті знаки прабатьківської тролячої архітектури, відлуння доби, коли влада імперії над південним Калімдором ще не розкришилася під тиском часу й піску."},sec={{t="Вибілене сонцем каміння",b="Зламаний Стовп здіймається з пісків на південь від Ґаджетзана й на схід від підступних Пісків Безодні та позначає рештки прадавньої тролячої архітектури, яку давно поглинув Танаріс. Попри безлюдну місцевість і пустельних звірів, що підступають дедалі ближче, тут можна натрапити на рідкісні підказки про доісторичні цивілізації континенту. Марвон Рівітсікер, гоблін-дослідник, який раніше працював у Раджеті, розбив біля розтрощеної кладки самотній табір, щоб вивчати дивні реліквії, відомі як ґаз'рідіан, розкидані по всій пустелі."}},faq={{q="Що таке Зламаний Стовп?",a="Зламаний Стовп — давні тролячі руїни в центрі Танаріса, на південь від Ґаджетзана й на схід від Пісків Безодні. Від первісної споруди лишилися хіба вивітрені кам'яні стовпи й уламки, напівзасипані мінливими дюнами.",al={"зламаний стовп танаріс","що таке зламаний стовп","руїни стовпа"}},{q="Хто отаборився біля Зламаного Стовпа?",a="Марвон Рівітсікер — допитливий гоблін-науковець і шукач із Раджета — влаштував серед руїн самотній дослідницький табір. Він вивчає загадкові прикраси Ґаз'рідіан, поховані в навколишній пустелі.",al={"хто біля зламаного стовпа","неігровий персонаж зламаного стовпа","місце марвона ріветсікера"}},{q="Хто збудував тутешні руїни?",a="Кладка тролячої роботи — вона сягає часів, коли давні тролячі імперії панували на півдні Калімдору, задовго до того, як край поглинули піски.",al={"хто збудував зламаний стовп","історія зламаного стовпа","походження зламаного стовпа"}},{q="Що таке реліквії Ґаз'рідіан?",a="Ґаз'рідіан — давні кам'яні артефакти й різьблені личини, поховані в пісках Танаріса. Марвон Рівітсікер вивчає їх у своєму таборі біля Зламаного Стовпа, щоб розгадати таємниці й силу, приховані в мистецтві зниклої імперії.",al={"ґаз'рідіан","що таке ґаз'рідіан","предмети завдань марвона"}}},fp="13,279,18.526.0,26.242.0,35.228.0,34.177.0,28.228.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="Табір Бронзоборода",s="Табір Бронзоборода — суворий дворфійський форпост на півдні Силітусу, трохи на схід від величезної Стіни Скарабея. Тут працюють загартовані мандрівники й науковці з Ліги Дослідників, і табір слугує базою для вивчення прадавніх гліфів силітидів і таємниць, похованих під пустельними пісками.",h="Табір Бронзоборода — суворий дворфійський форпост на півдні Силітусу, трохи на схід від величезної Стіни...",kw={"табір бронзоборода","ліга дослідників","силітус","стіна скарабея","дворфи","гліфи"},ang={["faction:Alliance"]="Для мандрівників з Альянсу, що пробираються похмурими просторами Силітусу, цей віддалений табір — бажаний дружній форпост далеко на південь від Цитаделі Кенаріуса.",["race:Dwarf"]="Форпост показує незламну впертість Ліги Дослідників і доводить, що для дворфів Айронфорджа, які шукають історичної правди, немає надто ворожої пустелі."},sec={{t="Опора серед мінливих пісків",b="Табір Бронзоборода, що притулився до безлюдних південних круч Силітусу, — рідкісний прихисток дворфійської витривалості в цілком ворожій пустелі. Заснований завдяки археологічним прагненням Айронфорджа, табір стоїть так, що звідси видно височенну Стіну Скарабея. Тут дослідники на кшталт Рутґара Ґліфшейпера й Франкала Стоунбриджа долали пекучу спеку, скорпідів і навали силітидів, щоб вивчати дивні написи й пам'ятки, залишені забутими цивілізаціями."},{t="Гліфи й відчай",b="Життя в таборі — аж ніяк не тихі розкопки. Загроза силітидів розповзається з підземних вуликів по всій пустелі, а неподалік у пісках нишпорять небезпечні жахіття на кшталт страхітливого скорпіда Смертохвата, тож форпост мусить поєднувати ретельну науку з боротьбою за виживання. Дослідники покладаються на заїжджих шукачів пригод: ті здобувають відбитки загадкових гліфів, допомагають розшифрувати прадавні мови комах і шукають зниклих товаришів, які забрели надто глибоко в божевілля пустелі."}},faq={{q="Де Табір Бронзоборода?",a="Табір — на півдні Силітусу, на схід від колосальної Стіни Скарабея й на північ від південного гірського хребта.",al={"де табір бронзоборода","місце табору бронзоборода","як знайти табір бронзоборода"}},{q="Хто керує Табором Бронзбірда?",a="У таборі працюють члени й соратники дворфійської Ліги Дослідників, зокрема дослідник гліфів Рутґар Ґліфшейпер, Франкал Стоунбридж і їхній супутник Ґлібб.",al={"хто в таборі бронзоборода","неігрові персонажі табору бронзоборода","хто керує табором бронзоборода"}},{q="Що тут вивчають дворфи?",a="Дослідники розшифровують давні кам'яні гліфи, з'ясовують, як спілкуються силітиди, і розкопують давно поховані таємниці півдня Калімдору.",al={"чому дворфи в сілітусі","що вивчає рутґар","призначення табору бронзоборода"}},{q="Які загрози чатують біля табору?",a="Навколишньою пустелею никають агресивні силітиди, піщані скорпіони й горезвісний велетенський скорпід Смертохват, Жах Пісків, що гніздиться трохи на південний схід.",al={"небезпеки біля табору бронзоборода","місце дезклеспа","чудовиська табору бронзоборода"}}},fp="22,331,32.498.0,22.486.0,44.131.0,36.178.0,35.176.0,38.187.0"}
P.entries["subzone:browman-mill"] = {n="Тартак Броумена",s="Тартак Броумена — сплюндрована лісопильня трохи на північ від Каплиці Надії Світла у Східних Чумних землях. Колись важлива частина лісоторгівлі Лордерону, тепер вона кишить прислужниками-нежиттю під залізною владою Погибелі. Її колишній власник, Стівен Броумен, і після смерті лишається в пастці свого зруйнованого цеху.",h="Тартак Броумена — сплюндрована лісопильня трохи на північ від Каплиці Надії Світла у Східних Чумних землях.",kw={"тартак броумена","стівен броумен","східні чумні землі","каплиця надії світла","погибель","нежить"},ang={["class:Paladin"]="Осквернені рештки тартака й змучені духи, що блукають його територією, — саме те, від чого святі ордени борються очистити Лордерон.",["race:Undead"]="Поневолення Стівена Броумена — суворе нагадування про долю всіх жертв Короля-Ліча, яким не дісталася вільна воля, виборена Відступниками."},sec={{t="Зруйнований промисел",b="До Третьої війни Тартак Броумена обслуговував довколишні містечка й обійстя Лордерону, обробляючи деревину з багатих лісів Східнолісся. Коли чума Погибелі прокотилася королівством, тартак загинув разом з усією провінцією. Нині гнилі колоди й розтрощені колеса стоять без діла, а довкола патрулюють гидоти, баньші та воїни-скелети. Через близькість до Каплиці Надії Світла тартак — постійне й грізне нагадування про орду нежиті, що тисне на самий поріг Срібного світанку."},{t="Доля наглядача",b="Перший власник тартака, Стівен Броумен, спіткав ту саму похмуру долю, що й незліченні прості люди Лордерону. Убитий, коли Погибель заполонила маєток, він повстав у нежитті ненажерливим гулем. Позбавлений людяності й поневолений волею Короля-Ліча, Броумен блукає в темних стінах свого колишнього тартака, стережучи розтрощені руїни справи всього свого життя."}},faq={{q="Де Тартак Броумена?",a="Тартак Броумена — на крайньому сході Східних Чумних земель, просто на північ від Каплиці Надії Світла.",al={"місце тартака броумена","де тартак броумена","як знайти тартак броумена"}},{q="Які вороги живуть на тартаку?",a="Подвір'я кишить силами Погибелі: тут і кремезні гидоти, і банші, що голосять, і кістяні потвори, і мандрівні гулі.",al={"мобі тартака броумена","хто на тартаку броумена","що живе на тартаку броумена"}},{q="Хто такий Стівен Броумен?",a="Стівен Броумен був першим господарем тартаку з людей. Він загинув під час падіння Лордерона й повстав гулем, прикутим стерегти свою зруйновану будівлю.",al={"хто такий стівен броумен","переказ про стівена броумена","гуль броумена"}},{q="Чому Тартак Броумена небезпечний для мандрівників?",a="Через велике скупчення могутньої нежиті це смертельно небезпечне місце — тим паче що воно лише за кілька хвилин їзди на північ від твердині Срібного Світанку в Каплиці Надії Світла.",al={"чому тартак броумена небезпечний","загроза тартака броумена"}}},fp="12,323,17.538.0,19.371.0,30.125.0,38.134.0,24.196.0,43.175.0"}
P.entries["subzone:burning-blade-coven"] = {n="Ковен Палаючого Клинка",s="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує найновішим новобранцям Орди. Усередині чаяться осквернені культисти й прикликані демони, перетворивши стару мінеральну печеру на плацдарм темної магії просто на порозі Дуротару.",h="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує...",kw={"ковен палаючого клинка","культисти","демони","біси","печера","долина випробувань","ярроґ бейншедов"},ang={["class:Warlock"]="Демонічні біси й темні обряди тут — ранній застережливий погляд на те, що стається, коли силу Скверни пускають у хід безоглядно, у відкритому непослуху Орді.",["race:Orc"]="Присутність культу Палаючого Клинка так близько до Долини Випробувань — нестерпна образа для нової Орди Тралла й суворе нагадування про поклоніння демонам, яке орки так боролися залишити позаду."},sec={{t="Тінь над полігоном",b="Запилені червоні гори, що обступають Долину Випробувань, колись були просто дикою місциною для випробувань молодих орків і тролів Темного Списа, які робили перші кроки на службі Орді. Та нещодавно північні печери охопили темні обряди. З гирла печери висипають біси та дрібні демони, сіючи хаос і загрожуючи новобранцям. Культ Палаючого Клинка на чолі з потаємним чорнокнижником Ярроґом Бейншедовом міцно окопався в глибині, перетворивши колись звичайний тренувальний майданчик на справжнє поле бою з демонічним скверненням."},{t="Скверна в скелях",b="Ще до того, як тут укорінилися демони, печери привернули увагу місцевих наглядачів, що сподівалися добути сировину для поселення. Наглядач Тазз'ріл спустився вглиб із мінеральною розвідкою, та його поспіхом вигнали, і він покинув цінне спорядження, коли культисти дали про себе знати. Нині відтіснити ковен Бейншедова — найголовніше випробування для майбутніх воїнів, розбійників і чаклунів, перш ніж їх визнають готовими вийти в ширший Дуротар."}},faq={{q="Де Ковен Палаючого Клинка?",a="Печера врізана у високі червоні скельні хребти просто вздовж північного краю Долини Випробувань у Дуротарі.",al={"місце ковену","де ковен палаючого клинка","місце печери в долині"}},{q="Хто очолює тутешніх культистів?",a="Ковен очолює чорнокнижник на ім'я Ярроґ Бейншедов, що керує місцевими обрядами й командує закликаними демонами.",al={"ватажок ковену","хто очолює ковен палаючого клинка","яррог"}},{q="Які вороги чаяться всередині?",a="Печера кишить свавільними бісами, дрібними демонічними прислужниками й смертними послушниками, вірними зловісному культу Палаючого Клинка.",al={"які мобі в печері","чудовиська ковену","демони в долині випробувань"}},{q="Навіщо новобранці заходять у печеру?",a="Спуститися в темні глибини печери, повернути загублене знаряддя на кшталт кайла Наглядача Тазз'ріла й убити Ярроґа Бейншедова — останній обряд посвяти для нових шукачів пригод з орків і тролів, перш ніж вони покинуть долину.",al={"навіщо йти до ковену","призначення ковену","останнє випробування ковену"}}},fp="19,297,33.554.0,23.490.0,41.117.0,28.118.0,34.127.0,37.216.0"}
P.entries["subzone:caer-darrow"] = {n="Каер Дарроу",s="Каер Дарроу — укріплений острів на Озері Дарроумер у Західних Чумних Землях. Колись тут був родовий маєток шляхетного Дому Баровів, але твердиню острова потай продали Кел'Тузадові й перетворили на школу некромантії Сколомансію, а місто нагорі заполонили блукаючі привиди.",h="Каер Дарроу — укріплений острів на Озері Дарроумер у Західних Чумних Землях.",kw={"каер дарроу","дім баровів","сколомансія","озеро дарроумер","кел'тузад","альтерак","друга війна"},ang={["faction:Alliance"]="Для Альянсу Каер Дарроу — це дві глибокі зради: засідка альтерацьких каперів у Другій війні, що викрила зраду короля Перенольда, і продаж Домом Баровів власного родового гнізда Кел'Тузадові.",["race:Human"]="Люди впізнають у цьому острові колишній маєток Дому Баровів — колись однієї з найбагатших шляхетних родин Лордерону, аж доки жадібність не штовхнула їх до угод із Культом Проклятих."},sec={{t="Спадок війни й зради",b="Задовго до Погибелі Каер Дарроу був стратегічною твердинею Лордерону, де зберігався прадавній ельфійський руновий камінь. Під час Другої війни Орда розграбувала фортецю й розколола руновий камінь, щоб збудувати з нього Вівтарі Бур Ґул'дана. Коли лорд Утер Світлоносець приплив, аби допомогти вцілілим, його флот потрапив у засідку альтерацьких каперів, — і саме ця підступність викрила перед Альянсом зраду Альтераку."},{t="Падіння Дому Баровів",b="Відбудований після Другої війни, Каер Дарроу став розкішним маєтком родини Баровів, яка мала земельні грамоти на угіддя в Бріллі, Таррен Міллі й Саутшорі. Відчайдушно прагнучи вберегти свої статки й життя, коли підступала старість, Барови уклали угоду з Кел'Тузадом. Під фортецею пустив коріння Культ Проклятих і заснував Сколомансію. Ще до того як Третя війна прокотилася Лордероном, на слуг і містян острова наслали першу, пробну чуму. Мешканці загинули й тепер приречені блукати зруйнованою твердинею неупокоєними відлуннями."}},faq={{q="Що таке Каер Дарроу?",a="Каер Дарроу — острівна фортеця на Озері Дарроумер у Західних Чумних Землях. Колись горда родова садиба заможної родини Баровів, нині це моторошні руїни, у катакомбах яких розташована некромантична академія Сколомансія.",al={"огляд каер даррову","що це за місце","переказ про каер дарроу"}},{q="Чому містечко покинуте й зруйноване?",a="Родина Баровів уклала угоду з Кел'Тузадом: віддала свій маєток Культу Проклятих в обмін на безсмертя. Культ використав челядь замку для перших некромантичних дослідів, а тоді наслав на все поселення смертельну чуму — ще до того, як почалося ширше вторгнення в Лордерон.",al={"чому каер дарроу зруйноване","що сталося з каер дарроу","історія каер дарроу"}},{q="Чому я не бачу привидів у містечку?",a="Убиті мешканці Каер Дарроу блукають неспокійними духами, застиглими у свої останні миті. Звичайне око їх не бачить — потрібен особливий магічний зір, як-от Примарна Есенція, яку дають духи Еви й Люсьєна Саркгоффів.",al={"де привиди","невидимі люди каер дарроу","як побачити привидів"}},{q="Що за рунний камінь колись тут був?",a="Під час Другої війни в Каер Дарроу зберігався давній рунний камінь високих ельфів. Орда напала на острів і розтрощила священний камінь на шматки, з яких Ґул'дан збудував Вівтарі Бур, щоб спрямовувати магію в огрів-магів.",al={"рунний камінь каер дарроу","ельфійський рунний камінь","камінь вівтаря бур"}},{q="Що під фортецею?",a="Під замком лежить Сколомансія — штаб і навчальна академія Культу Проклятих. Під проводом Темного Майстра Ґандлінґа некроманти й послушники вивчають там темні мистецтва й проводять досліди на мертвих.",al={"що під каер дарроу","що в підвалі","підземелля під каер дарроу"}}},fp="11,317,28.424.0,23.548.1,20.236.0,37.298.0,39.248.1,44.232.0,32.217.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Корчма «Тихий Вітерець»",s="Корчма «Тихий Вітерець» — так звуться головні заклади Острова Зефрас, де можна знайти прихисток і послуги: вони є і в Селі Шен'дар, і у Валанаарі. Це важливі зупинки для мандрівників, що досліджують острів: тут працюють місцеві наставники ремесел і корчмарі, а також зберігаються історичні реліквії.",h="Корчма «Тихий Вітерець» — так звуться головні заклади Острова Зефрас, де можна знайти прихисток і послуги...",kw={"корчма тихий вітерець","острів зефрас","село шен'дар","валанаар","корчма","наставники ремесел"},ang={["class:Rogue"]="Міріанн Містблейд навчає розбійницького ремесла біля вогнища корчми «Тихий Вітерець» у Селі Шен'дар.",["profession:Herbalism"]="Травники, що завітають до Села Шен'дар, можуть знайти в корчмі «Тихий Вітерець» Галассу Фернбріз і відточити своє ремесло збирача."},sec={{t="Відпочинок на острові",b="Корчми «Тихий Вітерець» дають прихисток серед звивистих стежок Острова Зефрас. У Селі Шен'дар корчму тримає Коріелла Калмбріз, і там же збираються острівні ремісники — зокрема наставники травництва, знімання шкур і зачарування. А у Валанаарі ще одна корчма «Тихий Вітерець» приймає місцевих подорожніх і зберігає рідкісні дивовижі, серед них — звуковий кристал із записом історії давнього повстання в Ельдре'Таласі."}},faq={{q="Де корчми «Тихий Вітерець»?",a="Корчми «Тихий Вітерець» є і в Селі Шен'дар, і у Валаанарі на Острові Зефрас.",al={"місце корчми тихий вітерець","де корчма тихий вітерець","карта корчми тихий вітерець"}},{q="Хто тримає корчму в Селі Шен'дар?",a="Корчмою в Селі Шен'дар опікується корчмарка Коріелла Калмбріз, що гостинно приймає і мешканців острова, і мандрівників.",al={"корчмар тихого вітерця","хто тримає корчму тихий вітерець"}},{q="Яких наставників можна знайти в корчмі?",a="У Селі Шен'дар у корчмі є Галасса Фернбріз (Травництво), Мендаласс Таттерменд (Білування), Насаланна Віндсінґер (Накладання чарів) і Міріанн Містблейд (наставниця розбійників).",al={"наставники тихого вітерця","наставники корчми шен'дар"}},{q="Що за звуковий кристал нагорі у Валаанарі?",a="Нагорі в корчмі Валаанара лежить звуковий кристал із третьою частиною «Повстання в Ельдре'Таласі» — літопису історичних подій давнього міста Високородних.",al={"звуковий кристал валаанара","кристал заколоту ельдре'таласа"}}},fp="14,286,16.458.0,38.92.0,37.139.0,38.183.0,53.166.0"}
P.entries["subzone:camp-aparaje"] = {n="Табір Апараже",s="Колись Табір Апараже був мирним тауренським селищем у східних височинах Гір Кам'яного Кігтя. Нині його захопило вороже плем'я Ґрімтотем: вони вирізали поселенців і забрали заставу собі.",h="Колись Табір Апараже був мирним тауренським селищем у східних височинах Гір Кам'яного Кігтя.",kw={"табір апараже","ґрімтотем","гори кам'яного кігтя","ґрундіґ дарклауд","макаба флетгуф","таурени"},ang={["faction:Horde"]="Вигнати Ґрімтотемів із Табору Апараже — це і помста, і оборона: віроломне плем'я має відповісти за різанину безневинних підданих Орди в Горах Кам'яного Кігтя.",["race:Tauren"]="Руїни Табору Апараже — гірке нагадування про жорстокість племені Ґрімтотем, яке веде Маґата. Вони доводять, що не всі діти Земної Матері поділяють бачення честі й миру, яке плекає Кайрн Бладгуф."},sec={{t="Трагічний занепад",b="Табір Апараже на кручах Гір Кам'яного Кігтя заснували мирні таурени, які хотіли спокійно жити у височинах. Той спокій розлетівся на друзки, коли нападники з сусідньої Застави Ґрімтотем на чолі з Ґрундіґом Дарклаудом без жодної причини люто вдарили по селищу. Мешканців вирізали або прогнали, а вцілілі — як-от Макаба Флетгуф — оплакують зруйнований дім і зі страхом думають про долю родичів, що потрапили в полон."},{t="Під владою Ґрімтотемів",b="Тепер Табір Апараже цілком зайняли воїни Ґрімтотем, і плем'я зробило його своєю передовою базою в цьому краї. На відміну від звичних поселень Ґрімтотем, де майорять сині знаки, великий тотем в Апараже розмальовано густою багряною фарбою."}},faq={{q="Хто колись жив у Таборі Апараже?",a="У Таборі Апараже жили мирні таурени, пов'язані з Ордою й племенем Бладгуф, зокрема Макаба Флетгуф і його донька Кая, — доки на поселення не напали.",al={"хто жив тут","первісні мешканці табору апараже","село макаби флетгуфа"}},{q="Чому табір ворожий до гравців Орди?",a="Село жорстоко захопило плем'я Ґрімтотем — ненависний до чужих і підступний тауренський клан, що не визнає влади Кайрна Бладгуфа й нападає на чужинців, зокрема й на членів Орди.",al={"чому таурени нападають","хто керує табором апараже","чому табір апараже червоний"}},{q="Хто очолив напад на Табір Апараже?",a="Напад очолив Ґрундіґ Дарклауд — жорстокий вождь Ґрімтотемів, що діє із Застави Ґрімтотем і прагне поширити жорстоку владу свого племені на Гори Кам'яного Кігтя.",al={"хто напав на апараже","ґрундіґ дарклауд","хто тут ватажок"}},{q="Що сталося з уцілілими селянами?",a="Більшість мешканців загинула під час нападу. Кільком удалося втекти, а інших, як-от юну Каю Флетгуф, Ґрімтотеми захопили в полон і тримають на сусідній Заставі Ґрімтотем.",al={"кая флетгуф","де вціліли","чи є вцілілі"}}},fp="12,250,17.458.0,20.270.0,33.176.0,41.205.0,36.169.0,41.186.0"}
P.entries["subzone:camp-e-thok"] = {n="Табір Е'ток",s="Табір Е'ток — поселення кентаврів Ґалак на північному заході Тисячі Голок. Войовниче плем'я використовує цей табір у каньйоні як базу для засідок на каравани, що проходять руслом річки внизу.",h="Табір Е'ток — поселення кентаврів Ґалак на північному заході Тисячі Голок.",kw={"табір е'ток","кентаври ґалак","тисяча голок","засідки","каравани","візло берінґшайнер"},ang={["race:Tauren"]="Невпинна агресія кентаврів Ґалак із Табору Е'ток — постійне нагадування про давню війну тауренів і кентаврів на півдні Калімдору."},sec={{t="Твердиня Ґалаків",b="Табір Е'ток, захований у суворих північно-західних закутках Тисячі Голок, — важливе поселення ворожих кентаврів Ґалак. Як і їхні родичі по всьому Калімдору, Ґалаки — невгамовні хижаки, що полюють на кожного мандрівника, який забреде в тіні каньйону. Табір сумно відомий набігами на торгові каравани: саме звідси напали на гобліна Візло Берінґшайнера й захопили його товари — хоча його найцінніший пристрій вислизнув із їхніх рук, бо його стерегла люта пантера."}},faq={{q="Хто живе в Таборі Е'ток?",a="Табір займає клан кентаврів Ґалак — агресивне плем'я, що панує в частині північного заходу Тисячі Голок.",al={"хто в таборі е'ток","мешканці табору е'ток","хто керує табором е'ток"}},{q="Що тут сталося з Візло Берінґшайнером?",a="На купецький караван, у якому був гоблін Візло Берінґшайнер, напали кентаври Ґалак із Табору Е'ток. Вони пограбували караван, але не змогли забрати Візлову цінну штуковину, бо вона була закріплена на нашийнику його лютої пантери.",al={"набіг на візло берінґшайнера","напад на гоблінський караван","що кентаври вкрали у візло"}},{q="Де Табір Е'ток?",a="Табір Е'ток — на північному заході Тисячі Голок, біля підніжжя стін каньйону поблизу Висот Розщепленого Копита.",al={"місце табору е'ток","де табір е'ток","карта табору е'ток"}}},fp="11,231,18.508.0,25.127.0,42.256.0,29.124.0"}
P.entries["subzone:camp-kosh"] = {n="Табір Кош",s="Табір Кош — стійбище огрів на півночі Пустищ, де живуть агресивні огри Курного Виверга. Тутешні громили засідають біля важливих шляхів, нападають на каравани й підбирають усе спорядження, яке мандрівники лишають у суворій пустелі.",h="Табір Кош — стійбище огрів на півночі Пустищ, де живуть агресивні огри Курного Виверга.",kw={"табір кош","огри","курний виверг","пустища","каравани","ульдаман"},ang={["faction:Alliance"]="Розвідникам Альянсу, що йдуть північним перевалом до Палючої Ущелини, біля Табору Кош слід бути насторожі: тутешні громили охоче влаштовують засідки на обози.",["race:Dwarf"]="Огри-мародери з Табору Кош розграбували життєво важливі харчі й зброю, які лишила знесилена експедиція Сіґрун Айронг'ю до Ульдамана."},sec={{t="Лігво мародерів",b="Табір Кош, розташований у північних пустирях Пустищ, — найпівнічніше поселення огрів Курного Виверга, яким належать і сусідні табори Бофф, Каґґ і Вурґ. Огри звідси користуються близькістю доріг і грабують вразливі обози, що прямують до Карґата чи на захід, у Палючу Ущелину. Коли дворфські шукачі на чолі з Сіґрун Айронг'ю мусили втекти з розкопок в Ульдамані, громили з Табору Кош миттю пограбували їхні покинуті вози й потягли до свого курного стійбища цінні харчі та зброю."}},faq={{q="Хто живе в Таборі Кош?",a="У Таборі Кош живуть огри Пилоригачі — плем'я жорстоких огрів, що контролює кілька невеликих таборів по всіх посушливих Пустищах.",al={"мобі табору кош","хто в таборі кош","огри табору кош"}},{q="Чому Табір Кош розташований саме тут?",a="Північне розташування дає огрям Пилоригачам змогу влаштовувати засідки на каравани з припасами й необачних мандрівників між Палючою Ущелиною, Ульдаманом і заставою Орди Карґат.",al={"чому табір кош тут","місце табору кош"}},{q="Що огри вкрали в дворфів?",a="Коли дворфійська експедиція Сіґруна Айронг'ю відступила від небезпек Ульдамана, вона покинула в пустелі вози з припасами. Огри з Табору Кош обнишпорили уламки й поцупили ящики з харчами й партії зброї.",al={"припаси дворфів табір кош","припаси сіґрун айронх'ю","вози улдамана"}}},fp="9,250,19.583.0,23.138.0,30.177.0,42.227.0"}
P.entries["subzone:camp-mojache"] = {n="Табір Моджаче",s="Табір Моджаче — головна застава Орди у Фераласі: укріплене поселення тауренів на потоці, що живить Озеро Дикого Вітру. Тут мандрівники, які мають справу з дикими нетрями, лютим звіром і прадавніми руїнами глибокого лісу, знаходять прихисток, припаси та сполучення повітрям.",h="Табір Моджаче — головна застава Орди у Фераласі: укріплене поселення тауренів на потоці, що живить Озеро...",kw={"табір моджаче","фералас","орда","таурени","застава","озеро дикого вітру"},ang={["faction:Horde"]="Моджаче — єдиний укріплений опорний пункт Орди у Фераласі, тож лише тут ви можете перепочити, поповнити припаси й швидко перебратися через глибокий ліс.",["race:Tauren"]="Табір Моджаче — найпівденніший осередок давнього ремесла й поселень вашого народу в Калімдорі, місце, де таурени знайшли злагоду з глибоким тропічним лісом."},sec={{t="Оплот тауренів серед тропічного лісу",b="Табір Моджаче стоїть у східному Фераласі, на бистрому потоці, що впадає в Озеро Дикого Вітру. Це поселення тауренів, зведене, щоб закріпитися в дикому південному лісі. Хоч у густих джунглях чигає чимало небезпек — від лютих звірів до огрів Ґордунні й войовничих гнолів Лісолапів, — табір лишається острівцем безпеки. Тут є житло, торговці й сідало вітрокрилів, тож він став життєво важливим вузлом для героїв Орди, що діють у цьому краї."},{t="Прикордонна застава",b="Мисливці й воїни табору славляться відвагою та товстою шкурою: вони невсипно стережуться набігів із навколишніх нетрів. Для Орди втримати Моджаче — означає мати вплив на весь Фералас і стримувати як нічних ельфів з узбережжя, так і темні сили, що зачаїлися в Лютопащі."}},faq={{q="Що таке Табір Моджаче?",a="Табір Моджаче — головна база Орди у Фераласі. Збудований і утримуваний переважно тауренами, він стоїть обабіч струмка, що впадає в Озеро Дикого Вітру, і пропонує відпочинок, торгові припаси й повітряне сполучення.",al={"призначення табору моджаче","що це за табір","містечко тауренів ферелас"}},{q="Хто очолює чи боронить табір?",a="Поселення захищають бувалі тауренські звитяжці, що відбивають набіги місцевих звірячих зграй, огрів Ґордунні й агресивних гнолів Лісолапів, які никають лісами трохи на захід.",al={"стражі табору моджаче","хто захищає моджаче","хто керує табором моджаче"}},{q="Куди літає місцевий приборкувач летунів?",a="З вітрогоничного сідала табору мандрівники можуть дістатися великих осередків — Тандер Блафа, Перехрестя в Пустках, Села Тіньової Здобичі в Пустограї — і сусідніх застав, як-от Ґаджетзана в Танарісі.",al={"маршрути польотів моджаче","куди літати з моджаче"}},{q="Які головні загрози оточують Табір Моджаче?",a="У навколишніх лісах — клан гнолів Лісолапів на заході, огри Ґордунні, що стережуть свої землі на півночі й півдні, і сили Альянсу, що діють із далекого західного узбережжя — Твердині Перистого Місяця.",al={"небезпеки феласу моджаче","загрози біля табору моджаче","вороги біля моджаче"}}},fp="12,306,34.478.0,16.347.0,21.230.0,30.191.0,42.204.0,41.210.0"}
P.entries["subzone:camp-narache"] = {n="Табір Нарачі",s="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі. Це прабатьківська домівка племені Гоквінд і місце випробувань, де молоді таурени починають навчання. Високо над рівнинами табір береже давні традиції й невпинно стереже від зазіхань шипогривів і не зниклої загрози кентаврів.",h="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі.",kw={"табір нарачі","плато червоної хмари","малгор","таурени","гоквінд","стартова зона","шипогриви"},ang={["class:Shaman"]="Молоді шамани роблять тут найперші кроки духовним шляхом: проходять випробування, щоб здобути свій Тотем Землі й заговорити напряму зі стихіями плато.",["race:Tauren"]="Для тауренів Табір Нарачі — кінець дитинства: священна земля, де ви проходите перші обряди полювання й налаштовуєтеся на духів предків під пильним оком старійшин Гоквіндів."},sec={{t="Серце племені Гоквінд",b="Табір Нарачі, що лежить на північному краю піднесеного Плато Червоної Хмари, — головне поселення племені Гоквінд. Селище складається з кількох великих шкіряних осель і наметів: тут є спільний намет для поранених сміливців, зброярня, пекарський намет і духовний куточок для роздумів і спілкування з предками. У центрі табору колом стоять старійшини племені й наставники шляхів; тут досі дає поради поважна Прамати Гоквінд, скеровуючи щойно посвячену молодь, яка стає на шлях захисників Земної Матері."},{t="Місце випробувань під загрозою",b="Хоч табір природно укріплений стрімкими урвищами плато, спокою Табору Нарачі бракує. Шипогриви Щетиноспинних із Яру Тернистого Клинка невпинно зазіхають на землі Гоквіндів, а віддалік чатують розвідники кентаврів. Молоді мисливці, шамани, друїди й воїни гартуються тут, виполюючи агресивну місцеву живність, захищаючи криницю селища та відбиваючи наскоки шипогривів, перш ніж спуститися великим шляхом у ширші долини Малгору."}},faq={{q="Що таке Табір Нарачі?",a="Табір Нарачі — стартове селище молодих тауренів на вершині Плато Червоної Хмари в південному Малгорі. Це головне стійбище племені Гоквінд, прихисток, де мисливці, воїни, друїди й шамани-початківці опановують своє ремесло, перш ніж вирушити до Села Бладгуф і Тандер Блафа.",al={"що таке табір нарачі","лор нарачі","стартове місто тауренів"}},{q="Хто очолює селище?",a="Вождь Гоквінд веде сміливців племені й керує обороною плато разом із шанованою старійшиною племені, Праматір'ю Гоквінд. Наставники й старійшини племені збираються в центрі табору, щоб навчати молодих шукачів пригод.",al={"хто очолює табір нарачі","вождь табору нарачі","ватажок гоквінд"}},{q="Які загрози чигають на табір?",a="Стійбищу постійно дошкуляють шипогриви Щетиноспинних, що діють із Яру Тернистого Клинка на сході. Окрім здичавілих бойових вепрів і довгоступів, що блукають довколишніми кручами, не зникла небезпека хижих ватаг кентаврів, і це тримає сміливців Гоквіндів у постійній готовності.",al={"вороги табору нарачі","хто нападає на табір нарачі","загрози плато"}},{q="Чи легко мандрівникам залишити плато?",a="Плато Червоної Хмари з усіх боків оточене стрімкими урвищами. Єдиний спуск до великих рівнин Малгору — гірська стежка, що веде на північ під охороною сміливців Гоквіндів, які не дають ворожим звірам і шипогривам влаштовувати засідки на подорожніх.",al={"як залишити плато червоної хмари","вихід із табору нарачі","стежка з плато"}}},fp="12,358,27.590.0,29.487.0,21.318.0,22.237.0,32.285.0,36.250.0"}
P.entries["subzone:camp-taurajo"] = {n="Табір Тауражо",s="Табір Тауражо — тихе поселення тауренів на півдні Пусток, просто біля гірського перевалу, що веде на захід до Малгору. Це важливий прикордонний прихисток: утомлені мандрівники знайдуть тут корчму, припаси, наставників ремесел і вітрокрилів, що літають між рівнинами й центральним Калімдором.",h="Табір Тауражо — тихе поселення тауренів на півдні Пусток, просто біля гірського перевалу, що веде на захід до...",kw={"табір тауражо","таурени","малгор","вітрокрили","корчма","пустки"},ang={["faction:Horde"]="Табір Тауражо захищає важливе сухопутне перехрестя й повітряний шлях, міцно пов'язуючи Малгор з рештою підвладного Орді центрального Калімдору.",["race:Tauren"]="Для тауренів, що вперше вирушають із Малгору, Табір Тауражо — перший дружній прихисток на суворих рівнинах Пусток."},sec={{t="Прикордоння Червоних Скель",b="Табір Тауражо, що стоїть біля східного виходу з перевалу до Малгору, часто стає першим місцем, де молоді таурени, які вирушають із Села Бладгуф, бачать безкраї Пустки. Оточений сухими чагарниками й порізаними плато, табір водночас застава й торговий осередок. Тут знаходять прихисток мисливці, шкірники й польові травники, а вітрокрили сполучають його з Тандер Блафом, Перехрестям і Заставою Вільного Вітру далі на півдні."}},faq={{q="Що таке Табір Тауражо?",a="Табір Тауражо — тауренська застава й поселення на півдні Пусток, важливий перевалочний пункт між рідним Малгором і посушливими чагарниками Пусток.",al={"огляд табору тауражо","що таке тауражо","переказ про тауражо"}},{q="Куди веде дорога на захід?",a="Ґрунтова стежка на захід повз Табір Тауражо веде гірським перевалом у Малгор — просто до Села Бладгуф і Тандер Блафа.",al={"західний прохід тауражо","дорога на захід від тауражо","шлях до мулґору"}},{q="Куди літають вітрогони з Табору Тауражо?",a="Місцевий приборкувач летунів веде маршрути віверн, що сполучають табір із Перехрестям на півночі, Тандер Блафом на заході й Заставою Вільного Вітру в Тисячі Голок на півдні.",al={"майстер польотів тауражо","маршрути польотів тауражо","сполучення тауражо"}}},fp="12,303,25.441.0,21.173.0,30.146.0,47.189.0"}
P.entries["subzone:camp-wurg"] = {n="Табір Вурґ",s="Табір Вурґ — стійбище огрів у посушливих просторах Пустищ. Це одна з кількох застав, які захопили войовничі огри Курного Виверга, що панують у східних долинах.",h="Табір Вурґ — стійбище огрів у посушливих просторах Пустищ.",kw={"табір вурґ","огри","курний виверг","пустища","то'ґрун"},sec={{t="Твердиня Курного Виверга",b="Табір Вурґ, захований серед скель Пустищ, — один із чотирьох головних таборів огрів Курного Виверга поряд із Табором Каґґ, Табором Бофф і Табором Кош. Тутешні огри люто боронять свої суворі землі й видирають із немилосердної пустелі все, що можуть. Поки рядові громили й вибивайли живуть біля грубих багать і шкур Вурґа, їхній ватажок, Бос То'ґрун, не має тут постійного осідку: він блукає стежками Пустищ і пильнує всі свої табори."}},faq={{q="Хто живе в Таборі Вурґ?",a="Табір Вурґ населяють огри Пилоригачі — люте плем'я, що ревно стереже свої землі й заснувало поселення по всіх Пустищах.",al={"мобі табору вурґ","хто в таборі вурґ","хто тут живе"}},{q="Де ватажок табору?",a="Ватажок огрів Пилоригачів, Бос То'ґрун, не сидить у Таборі Вурґ. Натомість він обходить відкриті стежки Пустищ між Вурґом, Каґґом, Боффом і Кошем.",al={"бос табору вурґ","місце босса тоґруна","хто керує табором вурґ"}},{q="Які ще табори належать цьому племені?",a="Пилоригачі контролюють чотири головні твердині на Пустищах: Табір Вурґ, Табір Каґґ, Табір Бофф і Табір Кош.",al={"табори пилового шлунка","інші огрські табори пустищ","огрські поселення пустищ"}}},fp="9,193,24.521.0,23.132.0,32.175.0,38.119.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Канали (Стормвінд)",s="Канали — мережа облицьованих каменем водних шляхів, що в'ються Стормвіндом і розділяють його квартали. Це тихі шляхи для перехожих і рибалок, але вони ховають приховані небезпеки й вхід до міської в'язниці.",h="Канали — мережа облицьованих каменем водних шляхів, що в'ються Стормвіндом і розділяють його квартали.",kw={"канали","стормвінд","риболовля","в'язниця","кроколіск-альбінос"},ang={["faction:Alliance"]="Канали — свідчення відбудови столиці Альянсом Лордерону, що перетворив завалені трупами руїни Першої війни знову на справне, мальовниче місто.",["profession:Cooking"]="Тихі береги каналів — зручне місце, де кухарі-початківці можуть навчитися ловити свіжу рибу, не виходячи за безпечні мури столиці."},sec={{t="Артерії столиці",b="Канали з'єднують і окреслюють квартали Стормвінда, відділяючи гомінкі ринки Торгового Кварталу від старих провулків Старого Міста, соборних садів і Дворфійського Кварталу. Кам'яні мости, арки й набережні обрамлюють тихі заклади на кшталт Виноробні Ґалліни, кравецьких крамниць і спокійних житлових будинків. Водні шляхи не лише служать місцевим купцям і рибалкам-аматорам — вони ще й ховають укріплений вхід до В'язниці, де під рівнем вулиць тримають найнебезпечніших злочинців і бунтарів Стормвінда."},{t="Моторошне минуле й тіні в глибині",b="Спокійна гладінь каналів приховує жорстоке минуле. Після розграбування Стормвінда в Першу війну канали виявилися завалені уламками, колодами й тілами вбитих захисників. Коли Альянс Лордерону звільнив руїни, солдати взялися за похмуру роботу: розчищали канали й ховали мертвих, перш ніж почалася відбудова. Нині, хоч канали очищено й відновлено, їхні глибини досі оповиті таємницею — у місті ходять чутки про величезного кроколіска-альбіноса, що никає під пристанями."}},faq={{q="Що сталося з каналами під час Першої війни?",a="Коли Орда орків захопила й сплюндрувала Стормвінд у Першій війні, водні шляхи лишилися завалені битим камінням, деревом і гниючими тілами. Війська Альянсу Лордерона, що відвоювали місто, мусили ретельно розчистити канали й гідно поховати полеглих, перш ніж місто можна було відбудовувати.",al={"історія каналів","канали першої війни","розграбування каналів стормвінда"}},{q="Чи справді в каналах Стормвінда живе чудовисько?",a="Напевно ніхто не скаже. Живучі міські легенди розповідають про величезного білого кроколіска, що чаїться у водах. Міські вартові й мешканці часто відмахуються від цього як від корчемних пліток, але свідчення не вщухають, і шукачів пригод застерігають не падати у воду.",al={"крокодил стормвінда","алігатор каналів","чудовисько каналізації","білий кроколіск"}},{q="Де вхід до В'язниці?",a="Вхід до В'язниці — на найпівнічнішій ділянці каналу довкола Кварталу магів, і його пильно стереже Міська Варта Стормвінда.",al={"де вхід до в'язниці","вхід до в'язниці","як дістатися в'язниці"}},{q="Чи можуть гравці плавати каналами, щоб пересуватися Стормвіндом?",a="Плавати каналами цілком можна, але щоб вибратися назад на вулицю, доведеться шукати кам'яні сходи чи причали, розкидані вздовж набережних.",al={"плавання каналами","подорож водою стормвінд","водний маршрут стормвінда"}}},fp="23,257,23.546.0,38.519.0,49.299.0,50.245.0,46.151.0,63.154.0"}
P.entries["subzone:canals-undercity"] = {n="Канали (Андерсіті)",s="Канали — каламутний кільцевий рів, що в'ється між окремими кварталами Андерсіті. Замість прісної води їх заповнює неприродний, отруйний зелений слиз, тож вони водночас слугують каналізацією і похмурим символом підземної твердині Відступників.",h="Канали — каламутний кільцевий рів, що в'ється між окремими кварталами Андерсіті.",kw={"канали","андерсіті","відступники","слиз","рів","рибальство"},ang={["class:Shaman"]="Стихії майже не мають влади над забрудненою твані, що заповнює водні шляхи Андерсіті, тож звичні закляття на кшталт Ходіння по воді тут не діють зовсім.",["race:Undead"]="Неживим тілам Відступників смердючі канали анітрохи не шкодять, тож вони слугують і оборонним ровом, і стоком для хімікатів — саме те, що треба підземному королівству."},sec={{t="Отруйний рів",b="Канали, висічені в підземних глибинах під руїнами Лордерона, оточують серце Андерсіті й розділяють його квартали широкими руслами млявої зеленої твані. Міста живих пропускають вулицями річкову воду, щоб тримати їх у чистоті, а Відступники заповнили ці кам'яні жолоби промисловими покидьками, хімічними стоками й алхімічними відходами. Рідина ледь помітно, хворобливо світиться й випускає смердючі випари, тож перейти її звичними чарами на кшталт ходіння по воді неможливо. Попри смертоносність цієї бурди, відчайдушні рибалки часом витягають із багна дивні, зіпсовані дивовижі."}},faq={{q="Що за зелена рідина в каналах?",a="Це алхімічний мул з отруйних стоків, побічних продуктів чуми й промислових відходів, що збирається в стічній системі Андерсіті. На відміну від чистої води, він явно отруєний і шкідливий.",al={"зелена вода андерсіті","що за слиз в андерсіті","зелена річка слизу"}},{q="Чи можна рибалити в каналах Андерсіті?",a="Так, терплячі рибалки можуть закинути вудку в цю жижу. Окрім хворобливої, отруєної риби, часом витягують і непотріб, зокрема старі людські черепи з полеглого минулого Лордерона.",al={"рибалка в андерсіті","чи можна рибалити тут","рибалка у зеленому слизу"}},{q="Чому «Ходіння по воді» не діє на каналах?",a="Густа хімічна жижа поводиться не так, як природна вода. Її мерзенна в'язкість і неприродний склад не дають шаманам та іншим заклиначам утриматися на поверхні за допомогою звичайної магії ходіння по воді.",al={"ходіння по воді андерсіті","шаман ходіння по воді помилка","чому не можу ходити по воді в андерсіті"}}},fp="18,261,12.614.0,39.201.0,37.192.0,45.217.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="Мис Стренглторну",s="Мис Стренглторну — випалений сонцем південний край Долини Стренглторну, що простягається від Арени Ґурубаші на південь аж до морських урвищ. Опорою краю є розлогий піратський порт Буті Бей, а сам мис — поле битви, за яке змагаються гобліни, Буканіри Кривавого Вітрила, прадавні тролі джунглів і дика природа, що наступає звідусіль.",h="Мис Стренглторну — випалений сонцем південний край Долини Стренглторну, що простягається від Арени Ґурубаші...",kw={"мис стренглторну","буті бей","буканіри кривавого вітрила","пірати","південні моря","долина стренглторну"},ang={["class:Rogue"]="Мис — притулок для каперів, пройдисвітів і головорізів: тут безліч нагод поцупити гаманець, провезти узбережжям контрабанду чи нацькувати Нападників Чорної Води на Буканірів Кривавого Вітрила.",["profession:Cooking"]="Довколишні Південні Моря й прибережні води — цінні рибальські угіддя, а рідкісні рецепти продають лише торговці рибою й портові кухарі Буті Бею."},sec={{t="Край континенту",b="На південь від прадавнього колізею Арени Ґурубаші густі джунглі поступаються узбережжю, відомому як Мис Стренглторну. Мис, усіяний поселеннями тролів, що розсипаються, — як-от Руїни Джубувалу й Руїни Абораза, — давно вийшов з-під влади Імперії Ґурубаші. Нині на його пляжах, у бухтах і на лісових галявинах у хаосі співіснують небезпечні хижаки, табори мурлоків і ворогуючі піратські команди, що б'ються за торгові шляхи й закопану здобич."},{t="Буті Бей і війна з буканірами",b="Головна сила на мисі — Нападники Чорної Води на чолі з Бароном Ревілґазом і Флотоводцем Сігорном, що правлять із піратського міста Буті Бей. Цю нейтральну гавань, вирубану просто в скелях південної бухти, пароплави сполучають із Раджетом, а отже, Східні Королівства — з Калімдором. Проте влада гоблінів досі хитка. Буканіри Кривавого Вітрила хазяйнують на південних мілинах і зовнішніх островах, грабують шляхи постачання й відкрито замишляють повалити Буті Бей і захопити повну владу над Південними Морями."}},faq={{q="Чим відрізняються Долина Стренглторну й Мис Стренглторну?",a="Мис Стренглторну — це саме південна частина більшої Долини Стренглторну: землі й узбережжя на південь від Арени Ґурубаші аж до Буті Бей.",al={"мис проти долини","географія стренглторну","де мис"}},{q="Хто править Мисом Стренглторну?",a="Жодна влада не контролює весь мис. Буті Бей і води довкола підпорядковані Баронові Ревілґазу й Нападникам Чорної Води, за якими стоять гобліни, а Буканіри Кривавого Вітрила, наги й рештки тролів тримають різні пляжі й руїни в глибині суходолу.",al={"хто править буті беєм","правитель мису","хто контролює мис"}},{q="Чи можуть і Орда, і Альянс користуватися Буті Бей?",a="Так. Буті Бей — відкритий нейтральний порт, який утримує картель Стімвідл. Доки мандрівники тримають зброю в піхвах і зберігають мир у межах міста, шукачі пригод і з Альянсу, і з Орди можуть користуватися його доками, крамарями, приборкувачем летунів і аукціоном.",al={"чи буті бей нейтральний","альянс і орда буті бей","чи орда може увійти в буті бей"}},{q="Що таке Арена Ґурубаші?",a="Арена Ґурубаші — давня троляча бійцівська яма біля північного краю мису, де збираються бійці, щоб випробувати себе.",al={"скриня ґурубаші","правила арени","арена стренглторну"}},{q="Як мандрівники дістаються між Мисом і Калімдором?",a="Пароплав, яким керують гобліни, регулярно ходить між доками Буті Бей і портовим містечком Раджет у Пустках — це один із небагатьох пасажирських шляхів між континентами через Південні Моря.",al={"корабель до раджета","транспорт до калімдора","корабель буті бею"}}},fp="21,323,21.466.0,31.516.0,80.184.0,36.256.0,42.271.0,28.132.0,51.196.0"}
P.entries["subzone:capital-gardens"] = {n="Столичні Сади",s="Столичні Сади — західне крило прадавніх ельфійських руїн Лютопащу у Фераласі. Колись це був тихий доглянутий парк для знаті калдореїв, а нині — зчахлий, отруєний ліс, де бродять зіпсовані древні, привиди й рештки Шен'дралару.",h="Столичні Сади — західне крило прадавніх ельфійських руїн Лютопащу у Фераласі.",kw={"столичні сади","лютопащ","шен'дралар","високородні","атенеум","іммол'тар","фералас"},ang={["class:Mage"]="Попри занепад, крізь сади веде шлях до Атенеуму — одного з найбільших сховищ магічної науки часів до Розколу, що досі вціліли в Калімдорі.",["race:NightElf"]="Для нічних ельфів пройтися зчахлими алеями Столичних Садів — це болісне нагадування про пиху Високородних і про згубну ціну залежності від тайнознавства."},sec={{t="Занепала обитель",b="Десять тисяч років тому Елдре'Талас був однією з найяскравіших перлин імперії калдореїв. Столичні Сади слугували йому кварталом просто неба: пишна зачарована рослинність, величні мармурові тераси, де сперечалися й відпочивали чародії з Високородних. Після Великого Розколу анклав спіткали скрутні часи. Утративши Колодязь Вічності, місцевий орден Шен'дралар звернувся до темної магії, щоб зберегти безсмертя, — а сади покинув чахнути. Нині розбиті подвір'я заповнюють сірі покручені віти й зіпсовані древені, а залишкова магічна скверна не дає лісові по-справжньому загоїтися."},{t="Атенеум і В'язниця",b="За зарослими алеями та ворожими древніми Столичні Сади ведуть далі, у самісіньке серце твердині Шен'дралару. Стежки виходять просто до Двору Високородних і Атенеуму — бібліотеки, що зберегла століття тайнознавчих знань і забутих трактатів. А ще глибше лежить В'язниця Іммол'тара: там уцілілі ельфи скували демона, щоб висмоктувати його силу. Цей учинок відчаю й перетворив довколишні сади на нинішнє жахіття."}},faq={{q="Що таке Столичні Сади?",a="Столичні Сади — західне крило Лютопаща в руїнах Ельдре'Таласа в центрі Фераласу. Колись тут був розкішний громадський парк і оселі знаті Високородних.",al={"що таке столичні сади","сади захід дір маула","парк ельдре'таласа"}},{q="Чому тутешні дерева й прадавні зіпсовані?",a="Після знищення Колодязя Вічності вцілілі Шен'дралар підтримували себе, висмоктуючи темну енергію Скверни із закликаного демона Іммол'тара. Витік нестійкої магії поволі спотворив місцеву рослинність і довів прадавніх, що тут мешкали, до лютого божевілля.",al={"чому прадавні злі","що сталося з деревами","чому все заражене"}},{q="Куди веде ця місцина?",a="Сади ведуть глибше в західний комплекс Лютопаща — до Двору Високородних, ученого Атенеуму й внутрішнього святилища, де ув'язнено демона Іммол'тара.",al={"що з'єднується із садами","куди веде"}},{q="Чи лишилися в садах дружні ельфи?",a="Більшість Високородних, що блукають доріжками, — ворожі духи чи навіжені захисники. Проте в сусідньому Атенеумі досі тримаються деякі вчені Шен'дралар, готові поділитися давніми знаннями чи виміняти загублені ельфійські фоліанти.",al={"союзники всередині","хто живе в садах"}}},fp="15,263,19.609.0,28.475.1,28.195.0,46.280.0,26.182.0,49.232.0"}
P.entries["subzone:cathedral-square"] = {n="Соборна Площа",s="Соборна Площа — духовне й громадське серце Стормвінда, над яким панує величний Собор Світла. Це не лише місце молитви й відданості: на гомінкій площі стоять міські установи — Ратуша, міський сиротинець і місцевий штаб Срібного світанку.",h="Соборна Площа — духовне й громадське серце Стормвінда, над яким панує величний Собор Світла.",kw={"соборна площа","собор світла","ратуша","срібний світанок","стормвінд","сиротинець"},ang={["class:Paladin"]="Для паладинів Соборна Площа — джерело віри й обов'язку: тут наставники, священні обітниці й бронники, що працюють саме для святих воїнів.",["class:Priest"]="Тихі зали й височенні шпилі площі дають жерцям мирне святилище, де можна єднатися зі Святим Світлом, поглиблювати духовні студії й служити мешканцям Стормвінда."},sec={{t="Святий квартал",b="Соборна Площа, що лежить на північний захід від Торгового Кварталу й на південний схід від Дворфійського Кварталу, — осередок віри Королівства Стормвінд. Над обрієм панує Собор Світла — найголовніше святилище вірних Святого Світла в усьому Азероті. Жерці, паладини й цілителі збираються тут, щоб навчатися, молитися й тренуватися. Містяни, прочани й місцеві школярі на чолі зі Шкільною Наставницею Данною часто збираються на площі для розмов і роздумів."},{t="Громадське серце й святий орден",b="Квартал не лише для молитви: це один із найжвавіших громадських осередків столиці. На площі стоять Сиротинець Стормвінда й Ратуша, на яких тримається адміністративне життя королівства. Уздовж вулиць тягнуться крамниці бронників і зброярів для святих хрестоносців, як-от «Праведні Лати» й «Справедливі Булави». Тут же розташований штаб Срібного світанку в Стормвінді: його вербувальники й представники організовують допомогу й згуртовують поборників проти загроз Погибелі, що насуваються в північних королівствах."}},faq={{q="Що таке Соборна Площа?",a="Соборна Площа — великий квартал Стормвінда довкола Собору Світла. Це і духовний осередок послідовників Світла, і важливий громадський центр, де розташовані Ратуша, міський сиротинець і різні крамниці.",al={"район собору","святий район","що це за місце"}},{q="Хто навчається на Соборній Площі?",a="Жерці й паладини Альянсу приходять на Соборну Площу й до Собору Світла вдосконалювати вміння й вивчати священні догмати. Тут також навчаються в наставників Першої допомоги цілителі й доглядальники.",al={"наставники класів тут","хто навчає тут","наставники паладинів і жерців"}},{q="Чому тут розташований Срібний Світанок?",a="Срібний Світанок тримає на Соборній Площі помітне посольство, щоб набирати здатних звитяжців і організовувати постачання зі Стормвінда для своєї невпинної боротьби з Погибеллю в Чумних Землях.",al={"срібний світанок стормвінд","присутність срібного світанку"}},{q="Куди веде Соборна Площа?",a="Мости й доріжки вздовж каналів з'єднують Соборну Площу з жвавим Торговим Кварталом на південному сході, промисловим Дворфійським Кварталом на північному заході й тихими садами Парку на південному заході.",al={"сусідні райони","куди веде"}}},fp="16,300,17.492.0,26.571.0,25.241.0,31.201.0,36.216.0,33.205.0"}
P.entries["subzone:cauldron"] = {n="Казан",s="Казан — величезний відкритий кар'єр, що займає саме серце Палючої Ущелини. Цією вогняною копальнею володіє клан Темного Заліза: вдень і вночі тут гарують зламані духом раби під оком жорстоких наглядачів, а поміж них никають елементалі.",h="Казан — величезний відкритий кар'єр, що займає саме серце Палючої Ущелини.",kw={"казан","кар'єр","палюча ущелина","темне залізо","раби","копальня"},ang={["profession:Mining"]="Велетенські механічні землечерпалки й терасовані уступи Казана свідчать про промисловий розмах, з яким дворфи Темного Заліза вгризаються просто в непевну вулканічну кору.",["race:Dwarf"]="Побачивши на власні очі, до чого опустилися дворфи Темного Заліза, які кидають розумних полонених, мов витратний матеріал, працювати серед вогняних елементалів, дворфи Айронфорджа відчувають глибоку огиду."},sec={{t="Розпечений кар'єр",b="Казан, глибоко врізаний у спечену землю Палючої Ущелини, укріпили після того, як Імператор Тауріссан закликав Рагнароса — і накликав лихо. Краями каньйону тягнуться величезні димні машини Темного Заліза, що вишкрібають породу й руду з тліючого каменю. Унизу, в палючих розколинах, бродять живий вогонь і магмові елементалі разом із погоничами Темного Заліза, а з надр гори безупинно здіймається підземний жар."},{t="Зламані робітники",b="Глибоко в ямі полонені раби терплять жорстокі нескінченні зміни під батогом наглядачів Темного Заліза. Виснажливу працю, задушливу спеку й катування витримують не всі: чимало робітників цілком збожеволіли. Вони вже не відрізняють друга від ворога й люто кидаються на кожного чужинця, що заважає їхній праці, — навіть на тих, хто міг би подарувати їм волю."}},faq={{q="Що таке Казан?",a="Казан — величезний відкритий кар'єр і розкопки в центрі Палючої Ущелини. Збудований і укріплений кланом Темного Заліза, він правує за промисловий осередок видобутку каменю й руди серед дуже небезпечної вулканічної місцевості.",al={"переказ про казан","що таке казан","кар'єр палаючої ущелини"}},{q="Хто контролює розкопки?",a="Усе місце контролює клан Темного Заліза. Він керує роботами за допомогою важких копальних машин і озброєних наглядачів, жорстоко тримаючи в кулаці кар'єр і робітників.",al={"хто керує розкопками","господарі казана"}},{q="Чому раби нападають на шукачів пригод, що хочуть допомогти?",a="Рабів зламали жорстокі муки, сліпуча спека й нескінченне виснаження. Доведені до божевілля господарями й нестерпним життям, вони бачать загрозу в будь-якій перерві в роботі й нападають на кожного поблизу.",al={"чому раби ворожі","раби нападають","чи можна звільнити рабів"}},{q="Які істоти живуть у кар'єрі?",a="Окрім наглядачів Темного Заліза та їхніх рабів, вогняні розколини Казана кишать нестійкими вогняними й магмовими елементалями, яких вивільнила вулканічна природа ущелини.",al={"мобі казана","що в казані","чудовиська казана"}}},fp="8,243,17.465.0,20.403.0,21.253.0,28.169.0,53.254.0,44.188.0"}
P.entries["subzone:cavern-of-mists"] = {n="Печера Імли",s="Печера Імли — простора зовнішня передпечера, що веде в глибини Печер Стогонів. Її живлять підземні гейзери, які б'ють крізь скелю, а в центральному озерці й завислому тумані водяться дивні мутовані звірі, що никають біля самого входу.",h="Печера Імли — простора зовнішня передпечера, що веде в глибини Печер Стогонів.",kw={"печера імли","печери стогонів","гейзери","трайґор шмагач","мутовані звірі","пустки"},ang={["class:Druid"]="Спотворені звірі, що буяють у густій парі, — перше застереження для друїдів Кола Кенарія про те, як далеко збилося з путі єднання Наралекса зі Смарагдовим Сном.",["faction:Horde"]="Печера лежить у самому серці Пусток, тож очистити ці тумани від хижих звірів украй важливо, щоб уберегти торгові шляхи й застави довкола Перехрестя."},sec={{t="Поріг Жахіття",b="Перш ніж спуститися в справжнє серце Печер Стогонів, мандрівники мають пройти Печеру Імли. Тут повсякчас висить густа тепла пара — її живлять природні гейзери, що б'ють із дна печери в глибоке центральне озерце. Хоч це лише вхід, спокою тут немає. Уступами й водою никають зграї рапторів, змії, слизуни й напівводяні трешадони, а поряд із ними — сумнозвісні звірі на кшталт гідри Трайґора Шмагача. Це зловісний передсмак протиприродного буяння, що гниє глибше внизу."}},faq={{q="Де Печера Імли?",a="Печера Імли — зовнішня система печер Печер Стогонів, на південний захід від Перехрестя в Пустках. Це загальнодоступна зала, якою гравці мусять пройти, щоб дістатися до порталу підземелля.",al={"місце печери імли","де печера імли","вхід до печер стенань"}},{q="Чому вона зветься Печерою Імли?",a="З кам'яної долівки безупинно б'ють гейзери, що живлять центральне озерце й наповнюють підземне повітря густим вологим туманом.",al={"чому імла","походження назви печери імли"}},{q="Які істоти тут живуть?",a="Залу населяють раптори, слизуни, вітряні змії, гадюки, жаби й трешадони в озерці, а часом тут бачать і рідкісну гідру Трайґора Шмагача.",al={"мобі печери імли","чудовиська печери імли"}},{q="Хто такий Трайґор Шмагач?",a="Трайґор Шмагач — небезпечна рідкісна гідра, яку часом можна побачити в центральному озерці зали поруч із трешадонами.",al={"трайґор","рідкісна гідра печер стенань"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="Печери часу",s="Печери часу, сховані в східних скелях Танарісу, — таємниче лігво Ноздорму й зграї бронзових драконів. У їхніх звивистих глибинах дракони стежать за крихкими шляхами часу Азероту й оберігають їх від будь-якого втручання смертних чи маніпуляцій із часом.",h="Печери часу, сховані в східних скелях Танарісу, — таємниче лігво Ноздорму й зграї бронзових драконів.",kw={"печери часу","ноздорму","бронзові дракони","анахронос","час","танаріс"},ang={["class:Mage"]="Магія часу, якою просякнуті печери, далеко перевершує хрономантію смертних і дає змогу смиренно зазирнути в сили, що лежать поза межами тайної магії.",["race:NightElf"]="Калдореї добре пам'ятають прадавні угоди Аспектів драконів і вважають доручення Ноздорму вкрай важливим для виживання світу."},sec={{t="Звивисті шляхи часу",b="Печери часу, вирізьблені глибоко під пустельними кручами, — це вузол, де сходяться течії історії. Ще на світанку світу титани доручили Ноздорму Позачасовому та його зграї бронзових драконів вічно стерегти ці коридори. Усередині час поводиться непередбачувано: крізь приховані розколини прослизають проблиски минулого й майбутнього, а пісками розкидано реліквії, вихоплені з далеких епох. Біля входу чатує могутній прадавній дракон Анахронос, а звивистим спуском патрулюють менші бронзові дракони, які люто оберігають єдину справжню лінію часу."},{t="Скарбниця епох",b="Печери — не лише перехрестя минулого й майбутнього, а й дивакувата скарбниця. Упродовж тисячоліть бронзова зграя збирала уламки історії з усіх куточків Азероту: прадавні дворфійські споруди, сторожову вежу з Лордерону, оселі ватажків орківських кланів і обладунки часів перших королів Стромґарда. Та хоч часом який-небудь сміливець і прослизне повз вартових, щоб глянути на ці дива, внутрішні брами лишаються щільно зачиненими — до того дня, коли зграя визнає, що без втручання смертних не обійтися."}},faq={{q="Чи можна зараз зайти в Печери часу?",a="Довгим звивистим тунелем можна спуститися до головної зали, але самі портали в історію лишаються запечатаними. Будьте обережні з драконами, що патрулюють вхід: старійшина бронзових драконів Анахронос байдужий до мандрівників, але його супутники нападуть на кожного смертного, що підійде надто близько.",al={"чи можна увійти в печери часу","як увійти в печери часу","чи відкриті печери часу"}},{q="Хто володіє Печерами часу?",a="Печери належать Ноздорму Позачасовому — Аспектові драконів, якого титани наділили владою пильнувати час. Щоденна опіка й охорона входу часто лягають на його найстаршого нащадка Анахроноса та вартових бронзового драконячого роду.",al={"хто править печерами часу","бос печер часу","хто живе в печерах часу"}},{q="Звідки всередині випадкові будівлі й артефакти?",a="Ноздорму віками впорядковував і збирав речові реліквії з усієї історії Азероту. По печерах розкидані скарби не на своєму місці — зокрема ціла лордеронська вартова вежа, дворфійські споруди, орківські будівлі й зброя давно забутих королівств смертних.",al={"чому людські вежі в печерах часу","артефакти печер часу"}},{q="Яке призначення бронзового драконячого роду тут?",a="Їхній священний обов'язок, дарований титанами, — оберігати плин часу й цілісність історії. Вони стежать, щоб втручання смертних чи сторонні збурення не розплели подій, які визначають світ.",al={"що роблять бронзові дракони тут","мета бронзового лету"}}},fp="15,275,20.575.0,15.538.0,46.315.0,35.254.0,52.279.0,52.219.0"}
P.entries["subzone:cenarion-enclave"] = {n="Ценаріонський Анклав",s="Ценаріонський Анклав — зелений північно-західний район Дарнасуса, головне місце зборів і осідок влади Кола Кенарія в столиці. Поки Архідруїд Малфуріон Стормрейдж спить у Смарагдовому Сні, друїдів нічних ельфів веде Архідруїд Фандрал Стаґгелм — серед величезних дупел і живого гілля цього гаю.",h="Ценаріонський Анклав — зелений північно-західний район Дарнасуса, головне місце зборів і осідок влади Кола...",kw={"ценаріонський анклав","коло кенарія","друїди","дарнасус","фандрал","мисливці","розбійники"},ang={["class:Druid"]="Для друїдів нічних ельфів Ценаріонський Анклав — громадський осередок вашого ордену на Тельдрассилі: тут вас навчають і скеровують під суворим проводом Архідруїда Фандрала Стаґгелма.",["class:Hunter"]="Мисливці збираються на східних гілках анклаву, щоб відточувати влучність і знання дикої природи поруч із приборкувачами, які вирощують столичних нічних шаблезубів."},sec={{t="Серце Кола",b="Ценаріонський Анклав розкинувся на високій терасі над Храмовими Садами. Його виплекано з прадавніх дубів і ясенів, чию кору поцятковано рунами. Збори Кола Кенарія відбуваються в спорудах, виліплених просто з живого дерева й каменю. Поки Малфуріон Стормрейдж перебуває у Смарагдовому Сні, справами тут порядкує Архідруїд Фандрал Стаґгелм: він просуває свої честолюбні задуми щодо Тельдрассила, попри давні політичні тертя з Верховною Жрицею Тірандою Віспервінд. Окрім друїдів, що медитують біля його струмків, анклав прихищає мисливців столиці та стайні, де вправні вершники вчаться приборкувати дарнасуських нічних шаблезубів."},{t="Тіні серед віт",b="Though renowned as a tranquil sanctuary of nature, the enclave harbors more covert activities. Beneath the hollowed roots of the westernmost bough lies a subterranean refuge used by Darnassus's clandestine rogues, who conduct their quiet business shielded by the rustling canopy above."}},faq={{q="Хто очолює Ценаріонський Анклав?",a="Нині гаєм і друїдами нічних ельфів у Дарнасусі керує Архідруїд Фандрал Стаґгелм. Малфуріон Стормрейдж, верховний провідник Кола Кенарія, і досі лишається в Смарагдовому Сні, поринувши в глибокий незбагненний сон, тож Стаґгелм — фактична влада.",al={"хто тут головний","лідер ценаріонського анклаву","фандрал стаґгелм"}},{q="Які класи тут навчаються?",a="Анклав — головна домівка столичних наставників друїдів, що навчають новачків серед живих дерев. На східних гілках — наставники мисливців, а в коріннях під західною гілкою ховається тихе лігво наставників розбійників.",al={"наставники ценаріонського анклаву","наставник друїдів дарнасуса","наставник мисливців дарнасуса"}},{q="Де купити нічного шаблезуба для їзди?",a="Наставники верхової їзди й заводчики, що доглядають цінних шаблезубих кішок Дарнасуса, стоять біля підніжжя східного дерева поблизу входу до гаю: вони навчають їзди й продають нічних шаблезубів мандрівникам Альянсу, що мають на те право.",al={"наставник нічних шаблезубів","наставник скакунів нічних ельфів","наставник їзди дарнасуса"}},{q="Як Коло Кенарія ставиться до Альянсу?",a="Цей квартал лежить у столиці Альянсу, і його очолює затятий прихильник своєї раси Фандрал Стаґгелм, але Коло Кенарія загалом присвячене збереженню природного ладу, а не війнам фракцій. Утім, через Стаґгелма саме цей анклав тісно пов'язаний з інтересами нічних ельфів у краї.",al={"чи коло кенарія з альянсу","чи друїди лише альянс"}}},fp="16,358,19.640.0,21.285.0,31.283.0,24.246.0,35.227.0,57.362.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Палата Спокути",s="Палата Спокути — похмура вхідна зала до крила Кладовища в Багряному Монастирі. Тут, під кам'яними арками, з яких звисають залізні ланцюги, Багряний Хрестовий Похід піддає полонену нежить та інших, кого вважає єретиками, жорстоким допитам і катуванням, а потім викидає їхні рештки до обителі за стіною.",h="Палата Спокути — похмура вхідна зала до крила Кладовища в Багряному Монастирі.",kw={"палата спокути","багряний монастир","дізнавач вішас","воррел сенґутц","катування","відступники"},ang={["class:Priest"]="Ніде наруга над святими обітницями не видно так ясно, як тут, де дізнавачі Походу перекручують священну дисципліну на тілесну різанину й садистські тортури.",["race:Undead"]="Палата Спокути — вершина жорстокості Багряних до вашого народу: тут полонених Відступників, як-от Воррела Сенґутца, систематично катують лише за те, що вони існують."},sec={{t="Зала мук",b="Палата Спокути, поріг Покинутої Обителі, аж ніяк не схожа на святиню мирної молитви. Багряний Хрестовий Похід перетворив величний вхід на дім болю з дибами, кайданами й палаючими жаровнями. Ревні інквізитори вибивають цими знаряддями зізнання й катують бранців, вважаючи нестерпний біль єдиною гідною покутою для нечестивих створінь. Палатою безупинно лунають крики приречених, а заправляють тут жорстокі наглядачі, які дбають, щоб ті, хто сюди потрапив, рідко виходили звідси цілими."},{t="Володіння дізнавача",b="Палатою опікується дізнавач Вішас — один із найсадистичніших майстрів примусу в Поході. Вішас потворно пишається тим, що ламає волю кожного, кого спіймали на землях монастиря. Серед його найцінніших жертв — бранець із Відступників Воррел Сенґутц, який тижнями без кінця терпить катування з рук Вішаса. Жорстокість, яку чинять у цих стінах, доводить стороннім: хрестовий похід Багряних за чистоту перекрутився в безглуздий садизм."}},faq={{q="Для чого Палата Спокути?",a="Це крило допитів і катувань Багряного Хрестового Походу в Кладовищі монастиря. Тут бранців — здебільшого Відступників та інших, кого вважають ворогами, — допитують, ламають і катують жорстокими знаряддями, а тоді викидають їхні тіла на кладовище.",al={"призначення палати спокути","чому тут знаряддя тортур","що відбувається в палаті спокути"}},{q="Хто контролює цю палату?",a="Палатою керує дізнавач Вішас — садистський кат Багряного Хрестового Походу, горезвісний тим, що насолоджується стражданнями своїх жертв.",al={"хто тут бос","лідер палати спокути","хто керує катівнею"}},{q="Куди веде ця палата?",a="Це крайня зала крила Кладовища, і вона веде просто до Покинутої Обителі — кладовища просто неба, де спочивають полеглі хрестоносці й блукають неспокійні мерці.",al={"виходи палати","куди веде палата спокути","наступна зона після спокути"}},{q="Кого тут тримають у полоні?",a="Бранця з Відступників на ім'я Воррел Сенґутц дізнавач Вішас тижнями тримає й катує в цій палаті.",al={"хто в'язень","воррел сенґутц","закатований в'язень"}}},fp="20,317,15.566.0,25.480.0,42.292.0,26.157.0,26.171.0,31.128.0"}
P.entries["subzone:charred-vale"] = {n="Обвуглена Долина",s="Обвуглена Долина — тліюча долина на південному заході Гір Кам'яного Кігтя, спустошена безоглядною вирубкою та машинами Венчурної Компанії. Колись тут був квітучий притулок древенів і химер, а тепер долину охопило полум'я, і хазяйнують тут розлючені елементалі та ворожі гарпії.",h="Обвуглена Долина — тліюча долина на південному заході Гір Кам'яного Кігтя, спустошена безоглядною вирубкою та...",kw={"обвуглена долина","вирубка","елементалі","гарпії","друїди","древені"},ang={["class:Druid"]="Тутешнє спустошення — суворе застереження про те, що буває, коли природну рівновагу руйнує неприборкана жадоба. Тому ця долина — одне з головних місць, де природу намагаються відродити.",["faction:Horde"]="Із Притулку Сонячної Скелі сили Орди діють пліч-о-пліч із союзниками з Кола Кенарія, стримуючи заворушення елементалів і долаючи згубні наслідки діяльності Венчурної Компанії."},sec={{t="Спалений ліс",b="Ще недавно ця південно-західна улоговина була буйним гірським лісом, який стерегли величні древені, а населяли тутешні химери й гарпії. Занепад почався з приходом Венчурної Компанії. Жадібна гоблінська зграя вирубала ліс під корінь вибуховими машинами, зіпсувала його охоронців і розбудила хаотичних вогняних елементалів. Древені зрештою відтіснили гоблінів, але земля лишилася понівеченою, випаленою й отруєною тим мерзенним начинням, яке лісоруби пустили в хід, відступаючи."},{t="Боротьба за відродження",b="Нині почорнілі прадавні наосліп блукають крізь дим і попіл поряд із розлюченими елементалями. Гарпії Бладф'юрі гніздяться на голих обгорілих стовбурах, обороняючи рештки своєї території. Хоч долина й ворожа, друїди з Притулку Сонячної Скелі не покидають цих земель: вони посилають мандрівників сіяти зачароване насіння й доглядати зіпсованих прадавніх, уперто відвойовуючи випалену землю."}},faq={{q="Чому Обвуглена Долина горить?",a="Спустошення спричинила безжальна лісозаготівля Венчурної Компанії. Її руйнівні машини й шалена вирубка розлютили первісних духів землі й вивільнили руйнівних вогняних елементалів, що поширилися долиною.",al={"чому горить","хто спалив обвуглену долину","що сталося з обвугленою долиною"}},{q="Чи може ліс в Обвугленій Долині колись відродитися?",a="Друїди-таурени із сусіднього Притулку Сонячної Скелі вірять, що так. Вони доручають мандрівникам заспокоювати навіжених деревнів і садити серед попелу зачароване земляне насіння, сподіваючись виманити з понівеченого ґрунту зелені пагони.",al={"чи гоїться обвуглена долина","друїди обвугленої долини"}},{q="Які істоти живуть в Обвугленій Долині?",a="Улоговина кишить ворожими духами вогню, почорнілими мстивими прадавніми, Обпаленими Василісками й дикими химерами. А ще її мордують гарпії Бладф'юрі.",al={"чудовиська обвугленої долини","що живе в обвугленій долині"}},{q="Як звалася Обвуглена Долина, перш ніж згоріла?",a="Її первісна назва загубилася в часі, але задовго до появи гоблінських сокир вона славилася як пишний лісовий прихисток.",al={"стара назва обвугленої долини","первісна назва обвугленої долини"}}},fp="12,275,19.499.0,20.411.0,32.249.0,48.216.0,40.172.0,50.122.0"}
P.entries["subzone:chill-breeze-valley"] = {n="Долина Холодного Вітерцю",s="Долина Холодного Вітерцю — суворий засніжений перевал на заході Дун Мороґу, що сполучає дворфське поселення Харанос зі змученим боями містом Гномреґан. Головний її шлях — жвава дорога для молодих мандрівників і біженців, та в її відлюдних закутках чаяться небезпечні звірі й криваві лігва.",h="Долина Холодного Вітерцю — суворий засніжений перевал на заході Дун Мороґу, що сполучає дворфське поселення...",kw={"долина холодного вітерцю","перевал","вендіго","харанос","гномреґан","дун мороґ"},ang={["race:Dwarf"]="Горяни та молоді дворфські мисливці випробовують себе, винищуючи лютих вендіго, які загрожують життєво важливому проходу між центральним Дун Мороґом і західним високогір'ям.",["race:Gnome"]="Для гномських біженців, що тікають від наслідків катастрофи Гномреґану до безпечних Хараноса й Айронфорджа, пережити перехід повз хижаків Долини Холодного Вітерцю — важливий перший крок."},sec={{t="Перехрестя снігу й пазурів",b="Долина Холодного Вітерцю прорізає гори західного Дун Мороґу Т-подібним рівчаком. Головною стежкою зі сходу на захід постійно снують дворфи та гноми-новачки, мандруючи між Хараносом і околицями Гномреґану. Але звернути в північно-південне відгалуження долини — зовсім інша справа. Усіяні плямами крові й понівеченими тушами, ці похмурі закутки ховають лютих хижаків — насамперед диких вендіго, що гніздяться в глибоких крижаних печерах і полюють на кожного, хто необачно забреде в їхні мисливські угіддя."}},faq={{q="Де Долина Холодного Вітерцю?",a="Долина Холодного Вітерцю — на заході Дун Мороґу, просто між жвавим гірським осередком Харанос на сході й технологічним гномівським містом Гномреґан на заході.",al={"місце долини холодного вітерцю","де долина холодного вітерцю","карта долини холодного вітерцю"}},{q="Чому долиною так небезпечно мандрувати?",a="Головна стежка між Хараносом і Гномреґаном відносно безпечна й людна, але північні й південні відноги долини — мисливські угіддя хижих звірів. Сніг там заплямований кров'ю й поцяткований розірваними тушами, а сліди ведуть до печер, де живуть люті вендіго, що ревно стережуть свої володіння.",al={"чудовиська долини холодного вітерцю","небезпеки долини холодного вітерцю","чому тут кістки"}},{q="Які звірі влаштовують тут лігва?",a="У глибині долини живуть люті вендіго, зокрема особливо великі й добірні ватажки, що привласнили кілька печер як свої лігва.",al={"вендіґо долини холодного вітерцю","що живе в долині холодного вітерцю"}}},fp="19,303,30.543.0,37.192.0,49.302.0,42.178.0"}
P.entries["subzone:chillwind-camp"] = {n="Табір Студеного Вітру",s="Табір Студеного Вітру стоїть на південному перевалі, що веде з Гір Альтерак до Західних Чумних Земель. Його тримає загін Альянсу разом зі Срібним світанком, і це останній безпечний плацдарм перед зруйнованими чумою землями Лордерону. З цієї хиткої застави командири спрямовують удари по сусідніх твердинях Погибелі й чумних казанах.",h="Табір Студеного Вітру стоїть на південному перевалі, що веде з Гір Альтерак до Західних Чумних Земель.",kw={"табір студеного вітру","альянс","срібний світанок","ашлам валорфіст","західні чумні землі","чумні казани"},ang={["class:Paladin"]="Лорд Ґрейсон Шедовбрейкер у Стормвінді посилає сюди перспективних паладинів на допомогу Командирові Валорфісту, щоб ті обрушили на лави нежиті святий гнів Срібної Длані.",["faction:Alliance"]="Табір Студеного Вітру — авангард зусиль Альянсу повернути північний Лордерон: тут є безпечний прихисток, грифони для перельотів і бойові накази проти Погибелі."},sec={{t="На межі чуми",b="Табір Студеного Вітру, що сховався в скелястому проході під Мисом Студеного Вітру, — перша лінія оборони й головна база сил Альянсу, які пробиваються в Західні Чумні Землі. Хоча від найгіршої чумної зарази його відгороджують високі гірські хребти, мертвий холод півночі важко нависає над наметами й частоколами. Під проводом Командира Ашлама Валорфіста нечисленний гарнізон вояків, розвідників і фахівців Срібного світанку намагається стримати жахи, що чатують уздовж Королівського шляху, і збирає відомості, потрібні, щоб повернути полеглі поля Лордерону."},{t="Війна на виснаження",b="Табору бракує регулярних армій для повномасштабного штурму Андоргала чи некромантської фортеці Сколомансії, тож він покладається здебільшого на незалежних поборників і найманців. Тутешні операції — це точкові партизанські удари: збирати розвіддані про Культ Проклятих, знешкоджувати алхімічні чумні казани, що отруюють ґрунт, і тримати відкритими шляхи постачання до східних застав, як-от Каплиці Надії Світла. Коли Погибель сидить у руїнах просто на півночі, а Відступники укріплюють західну межу, захисники табору б'ються лише за те, щоб перевал не впав."}},faq={{q="Навіщо Табір Студеного Вітру?",a="Табір Студеного Вітру — головний південний плацдарм Альянсу й Срібного Світанку на межі Західних Чумних Земель. Це надійна база, звідки здійснюють партизанські вилазки проти Погибелі в Андоргалі й знешкоджують чумні казани краю.",al={"чому табір студеного вітру тут","мета студеного вітру","що таке табір студеного вітру"}},{q="Як дістатися до Табору Студеного Вітру із Саутшора?",a="Із Саутшора в Передгір'ї Гілсбреда йдіть дорогою на північ, на роздоріжжі поверніть на схід і вздовж річки підніміться на північ до альтерацького гірського перевалу. Подавшись на захід крізь високу ущелину, мандрівники вийдуть до Мису Студеного Вітру, а звідти — просто до табору.",al={"як дістатися табору студеного вітру","напрям до студеного вітру","шлях до студеного вітру"}},{q="Що відповідає цій заставі в Орди?",a="Відповідник Орди — Заслон на західному прикордонні між Галявинами Тірісфалю й Західними Чумними Землями. Обидві застави — укріплені плацдарми для походів проти Погибелі в краї.",al={"табір студеного вітру орда","версія орди студеного вітру","чи є табір орди студеного вітру"}},{q="Хто командує силами в Таборі Студеного Вітру?",a="Гарнізон Табору Студеного Вітру очолює Командир Ашлам Валорфіст: він спрямовує добровольців Альянсу, Лицарів Срібної Длані й посланців Срібного Світанку в діях серед навколишніх руїн і отруєних ферм.",al={"лідер табору студеного вітру","хто командує табором студеного вітру","командир студеного вітру"}}},fp="14,373,22.595.0,18.620.0,38.269.0,48.271.0,45.221.0,42.213.0"}
P.entries["subzone:chillwind-point"] = {n="Мис Студеного Вітру",s="Мис Студеного Вітру — скелясте підвищення з давніми тролівськими руїнами на високому пограниччі між Горами Альтерак, Передгір'ям Гілсбреда та Західними Чумними Землями. Назву він дістав від крижаних протягів, що завивають у гірському перевалі, налітаючи з ураженої півночі. Нині це самотній оглядовий пункт, де живе хіба що тролівський містик-відлюдник.",h="Мис Студеного Вітру — скелясте підвищення з давніми тролівськими руїнами на високому пограниччі між Горами...",kw={"мис студеного вітру","альтерак","гілсбред","тролі","бат'ра","шамани","чумні землі"},ang={["class:Shaman"]="Дикі пориви, що збиваються в ущелині, роблять Мис Студеного Вітру місцем, де стихії відчутні як ніде: сюди приходять навчатися у відлюдника Бат'ри Спостерігача Вітрів.",["faction:Alliance"]="Ці давні руїни лежать трохи південніше прикордонного посту в Таборі Студеного Вітру й позначають перехід від спірних передгір'їв до моторошних теренів Чумних Земель."},sec={{t="Гірке перехрестя",b="Мис Студеного Вітру примостився на межі, де Гілсбред поступається Альтераку й зачумленій півночі, і дивиться на гірську ущелину, що веде просто до Західних Чумних Земель. Задовго до того, як Лордерон заявив права на ці перевали, давні тролі звели на цих висотах кам'яні споруди — їхні рештки, побиті негодою, стоять і досі. Нині холодні вітри дмуть ущелиною на південь і несуть подих полеглої півночі в долини передгір'я."},{t="Спостерігач Вітрів",b="Попри відкритість усім вітрам і близькість до спустошених Погибеллю земель, Мис Студеного Вітру не зовсім безлюдний. Давня кладка дає прихисток Бат'рі Спостерігачу Вітрів — тролю-відлюднику з джунглів, що спілкується з лютими шквалами, які мчать крізь прохід. Мандрівники й шамани, що прямують на північ, часто розшукують його самотній табір серед руїн, аби пізнати таємниці гірських вітрів."}},faq={{q="Що таке Мис Студеного Вітру?",a="Мис Студеного Вітру — давні тролячі руїни на високому підвищенні над перевалом між Гілсбредом, Альтераком і Західними Чумними Землями. Назву він дістав від пронизливих протягів, що безупинно свищуть у сусідній ущелині.",al={"огляд мису студеного вітру","де мис студеного вітру","що це за місце"}},{q="Чи Мис Студеного Вітру — те саме, що Табір Студеного Вітру?",a="Ні, хоча їх часто плутають. Табір Студеного Вітру — укріплена застава Альянсу й Срібного Світанку трохи на північ, за межею, у Західних Чумних Землях, а Мис Студеного Вітру — зруйноване троляче підвищення трохи на південь.",al={"мис проти табору студеного вітру","різниця табору студеного вітру","чи це табір студеного вітру"}},{q="Хто живе на Мисі Студеного Вітру?",a="Єдиний мешканець руїн — Бат'ра Спостерігач Вітрів, привітний троль із джунглів, що вивчає вітри й допомагає шукачам стихій і шаманам, які наважуються перейти гірський перевал.",al={"хто тут","хто троль","батра"}},{q="Чому тут так холодно?",a="Мис лежить просто біля вузької гірської ущелини, що жене крижані протяги з високих північних країв і отруєних просторів Західних Чумних Земель униз, у передгір'я.",al={"чому холодно","студені вітри","крижаний вітер"}}},fp="15,354,19.478.0,15.392.0,24.235.0,46.238.0,29.177.0,23.203.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Коло Аквементаса",s="Коло Аквементаса — загадкове кільце прямовисних каменів на східному узбережжі Танарісу, трохи на південь від Бухти Загублених такелажників. Це місце обрядів, де мандрівники можуть викликати духа-елементаля Аквементаса.",h="Коло Аквементаса — загадкове кільце прямовисних каменів на східному узбережжі Танарісу, трохи на південь від...",kw={"коло аквементаса","аквементас","елементаль","стихії","танаріс","узбережжя"},ang={["class:Shaman"]="Здатність кола зосереджувати первісні енергії й утримувати духа-елементаля робить його неабиякою цікавинкою для кожного шамана, що мандрує узбережжям Танарісу."},sec={{t="Кільце біля моря",b="Коло Аквементаса тихо стоїть на обвітреному східному узбережжі Танарісу, на південь від піратської твердині в Бухті Загублених такелажників. Ці вивітрені прямовисні камені, розставлені по колу, гудуть енергією стихій на тлі пустельного берега. Коло слугує осередком для виклику Аквементаса — сутності-елементаля, пов'язаної з прадавнім артефактом. Довколишні пляжі кишать розбійниками з Південних морів і морськими тваринами, але саме коло лишається урочистим острівцем обрядової сили серед дюн."}},faq={{q="Що таке Коло Аквементаса?",a="Це коло стоячих каменів на південно-східному узбережжі Танаріса, де закликають стихійну сутність Аквементаса.",al={"що за кам'яне коло","призначення кола аквементаса","стоячі камені танаріс"}},{q="Де це коло?",a="Коло лежить на східному березі Танаріса, просто на південь від скель і входу до Бухти Загублених такелажників.",al={"де коло аквементаса","як знайти коло аквементаса","місце кола аквементаса"}},{q="Хто такий Аквементас?",a="Аквементас — дух стихії, пов'язаний із давнім ланцюжком завдань про дивні артефакти; його закликають просто в коло каменів.",al={"хто такий аквементас","переказ про аквементаса"}},{q="Чи стережуть коло пірати?",a="Пірати Південних Морів никають біля Бухти Загублених такелажників і на навколишньому березі, але саме коло — здебільшого відлюдне місце для закликання.",al={"чи пірати стережуть коло","пірати південних морів біля кола"}}},fp="20,246,17.546.0,33.154.0,28.119.0,18.139.0,33.146.0"}
P.entries["subzone:circle-of-east-binding"] = {n="Коло Східного Узлуччя",s="Коло Східного Узлуччя — таємниче прадавнє ритуальне місце на сході Аратійського нагір'я, трохи на південний захід від Гаммерфолла. Його осердя — Камінь Східного Узлуччя, за який точиться запекла боротьба; стережуть його мандрівні водяні елементалі — пінисті вигнанці.",h="Коло Східного Узлуччя — таємниче прадавнє ритуальне місце на сході Аратійського нагір'я, трохи на південний...",kw={"коло східного узлуччя","камінь узлуччя","елементалі","водяні духи","гаммерфолл","аратійське нагір'я"},ang={["class:Shaman"]="Сковувальні камені Аратійського нагір'я — грубий або дуже давній спосіб приборкувати стихії, що різко контрастує з прагненням шамана до рівноваги й єднання зі стихіями.",["faction:Horde"]="Коло лежить за кілька кроків дорогою від Гаммерфолла, і неспокійні водяні духи довкола нього постійно дошкуляють патрулям і валкам Орди."},sec={{t="Східний оберіг",b="Коло Східного Узлуччя, що лежить серед скелястого нагір'я на схід від Стромґарда, — одне з кількох прадавніх місць сили, розкиданих по Аратійському нагір'ю. У його центрі стоїть Камінь Східного Узлуччя — загадковий моноліт, що випромінює потужну магію стихій. Довкола кружляють водяні елементалі, відомі як пінисті вигнанці: вони блукають навколишніми землями й люто боронять камінь від усіх смертних, хто наважиться підійти."},{t="Ув'язнені стихії",b="Камені Аратійського нагір'я — не просто дивина природи: це прадавні сковувальні обереги, що мали стримувати й ув'язнювати буйні сили стихій. Неспокійні водяні духи довкола східного кола видають, як важко доводиться цим оберегам: істоти, яких магія каменя притягла чи ув'язнила, кидаються на мандрівників і шукачів пригод, що йдуть недалекою дорогою до Гаммерфолла."}},faq={{q="Де Коло Східного Узлуччя?",a="Коло Східного Узлуччя — на сході Аратійського нагір'я, на південь від головної дороги й трохи на південний захід від табору Орди Гаммерфолл.",al={"місце кола східного узлуччя","де коло східного узлуччя","карта східного узлуччя"}},{q="Які істоти тут водяться?",a="Коло заполонили агресивні водяні елементалі — Гребеневі Вигнанці, що невпинно стережуть Камінь Східного Узлуччя.",al={"мобі східного узлуччя","які чудовиська у східному узлуччі","вигнанці гребеня"}},{q="Звідки на нагір'ї водяні елементалі?",a="Камені, розкидані Аратійським нагір'ям, — давні стихійні узи. Водяні елементалі тут свідчать, що через східний оберіг утримують чи притягують водяну стихійну енергію.",al={"чому водяні елементалі на нагір'ї","переказ про стихійців східного узлуччя"}},{q="Навіщо Камінь Східного Узлуччя?",a="Камінь Східного Узлуччя — частина злагодженої мережі каменів-узів по всьому Аратійському нагір'ю, створеної, щоб утримувати, спрямовувати й замикати нестійкі стихійні сутності.",al={"призначення каменя східного узлуччя","що робить камінь східного узлуччя"}}},fp="22,286,16.417.0,22.389.0,44.169.0,30.124.0,48.219.0,49.180.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="Коло Внутрішнього Узлуччя",s="Коло Внутрішнього Узлуччя — прадавнє кільце ритуальних каменів у південних пагорбах Аратійського нагір'я, просто на схід від Фортеці Стромгард. Його стережуть ворожі земляні елементалі, а в центрі стоїть Камінь Внутрішнього Узлуччя — найпотужніша печать, що сковує ув'язнену глибоко під землею принцесу стихій Мізраель.",h="Коло Внутрішнього Узлуччя — прадавнє кільце ритуальних каменів у південних пагорбах Аратійського нагір'я...",kw={"коло внутрішнього узлуччя","мізраель","печать","земляні елементалі","камені","аратійське нагір'я"},ang={["class:Mage"]="Геометричне розташування каменів утворює складне й довговічне поле стримування, здатне спрямовувати й утримувати величезний підземний тиск магії.",["class:Shaman"]="Сира земна сила, що вирує в Колі Внутрішнього Узлуччя, свідчить про давні й міцні пута стихій, хоча неприродне збурення місцевих духів землі застерігає: під ґрунтом щось зіпсоване."},sec={{t="Головна печать",b="Коло Внутрішнього Узлуччя стоїть на плато на південь від головної дороги й тримає найсильніший із прадавніх оберегів, що замикають Мізраель під нагір'ям. Центральний Камінь Внутрішнього Узлуччя оточують високі брили, і він гуде густою силою земної магії. Величезні гуркітливі земляні елементалі невтомно обходять камені — чи то їх притягує відгомін цього місця, чи то вони прикуті тут як вартові. Та попри потужні обереги, крізь тріщини у внутрішній печаті ув'язнена під нагір'ям сутність може телепатично тягтися назовні й нашіптувати благання про волю необачним мандрівникам, які беруть до рук уламки її каменя."}},faq={{q="Навіщо Коло Внутрішнього Узлуччя?",a="У Колі — Камінь Внутрішнього Узлуччя, головний і найсильніший оберіг, що утримує підземну в'язницю Мізраель. Він діє разом з іншими стихійними колами, розкиданими Аратійським нагір'ям, щоб тримати цю істоту під землею.",al={"чому це коло тут","що робить внутрішнє узлуччя","переказ про коло внутрішнього узлуччя"}},{q="Які істоти стережуть це коло?",a="Коло пильно стережуть могутні земляні елементалі, передусім Гуркітливі Вигнанці. Ці кам'яні велетні люто нападають на кожного, хто наближається до обрядових каменів.",al={"які вороги тут","мобі внутрішнього узлуччя","громовий вигнанець"}},{q="Хто шепоче крізь камінь?",a="Голос, що лунає крізь уламок-узи, належить Мізраель — давній і могутній принцесі стихій, ув'язненій глибоко під землею. Її ментальна сила зуміла пробитися крізь цю тріснуту печатку й дістатися розуму смертних.",al={"хто з тобою говорить","голос мізраеля","шепочучий камінь"}},{q="Де Коло Внутрішнього Узлуччя?",a="Воно на півдні Аратійського нагір'я, на високому хребті трохи на схід від зруйнованої твердині — Фортеці Стромгард.",al={"місце внутрішнього узлуччя","де коло внутрішнього узлуччя","як знайти внутрішнє узлуччя"}}},fp="23,327,13.590.0,51.274.0,33.169.0,36.239.0,45.152.0"}
P.entries["subzone:circle-of-west-binding"] = {n="Коло Західного Узлуччя",s="Коло Західного Узлуччя — одне з кількох прадавніх ритуальних місць, розкиданих Аратійським нагір'ям; воно лежить неподалік Муру Торадіна. Осердя цього тайного кола — Камінь Західного Узлуччя, а саме місце кишить вогняними елементалями, прикутими до нього.",h="Коло Західного Узлуччя — одне з кількох прадавніх ритуальних місць, розкиданих Аратійським нагір'ям; воно...",kw={"коло західного узлуччя","мур торадіна","палаючі вигнанці","вогняні елементалі","аратійське нагір'я"},ang={["class:Mage"]="Сковувальні камені нагір'я дають знавцям тайної магії змогу побачити, як прадавні маги й шамани прив'язували й приборкували елементальні сутності з інших світів.",["class:Shaman"]="Буйні Палаючі вигнанці свідчать про давній неспокій стихій, прив'язаний до цих прадавніх наріжних каменів нагір'я."},sec={{t="Західний наріжний камінь",b="Коло Західного Узлуччя, що тулиться до скелястих схилів біля Муру Торадіна, — частина ширшої мережі ритуальних місць, розкиданих по всьому Аратійському нагір'ю. У його серці стоїть Камінь Західного Узлуччя — прадавня реліквія, пов'язана зі стриманням стихій. Довкола рояться Палаючі вигнанці — буйні вогняні елементалі, які невтомно стережуть околиці, тож будь-яка спроба наблизитися до каменя — небезпечна справа для мандрівників західними рівнинами."}},faq={{q="Що таке Коло Західного Узлуччя?",a="Це давнє обрядове місце на заході Аратійського нагір'я, біля Муру Торадіна. Тут стоїть Камінь Західного Узлуччя, який люто стережуть ворожі вогняні елементалі.",al={"коло західного узлуччя","камінь західного узлуччя","західне коло узлуччя"}},{q="Звідки тут вогняні елементалі?",a="Палаючі Вигнанці живуть біля Каменю Західного Узлуччя й стережуть його. Це стихійні сили, яких притягують чи прив'язують давні магічні осердя, зведені по всьому Аратійському нагір'ю.",al={"палаючі вигнанці арати","чому вогняні стихійці західного узлуччя","стихійці кола західного узлуччя"}},{q="Хто такий Руул Ванстоун?",a="Руул Ванстоун — огр-маг Каменекулаків, що никає цим місцем: рідкісний і небезпечний громило, а не знавець каменю-узів.",al={"руул ванстоун","руул","дворф біля західного узлуччя"}}},fp="22,253,20.472.0,35.174.0,35.173.0,21.132.0"}
P.entries["subzone:clean-zone"] = {n="Чиста Зона",s="Чиста Зона — укріплений анклав для знезараження всередині зруйнованого Гномреґана, одразу за верхньою Залою Шестерень. Це єдиний безпечний прихисток в опроміненому комплексі, де неосквернені гномські сили тримають оборону від трогів і гномів-прокажених довкола. Тут польові медики, техніки й особливі машини «Іскромат» дають перепочинок і допомагають рятувати цінне з радіоактивних руїн.",h="Чиста Зона — укріплений анклав для знезараження всередині зруйнованого Гномреґана, одразу за верхньою Залою...",kw={"чиста зона","гномреґан","іскромат 5200","тінк спрокетвісл","знезараження"},ang={["profession:Engineering"]="Робочі машини «Іскромат 5200» і крамар Тінк Спрокетвісл роблять цю заставу важливим місцем, де можна перебрати опромінений мотлох у пошуках рідкісних креслень і механічних деталей.",["race:Gnome"]="Для гномів перебування в Чистій Зоні — і похмуре нагадування про падіння домівки, і вперта іскра надії, що технології Гномреґана ще можна відвоювати в трогів."},sec={{t="Оплот серед шлаку",b="Хоча більша частина Гномреґана постраждала від катастрофічного викиду радіоактивних відходів, на який зважився Меккаторк, Чиста Зона лишається незараженою. Розташована стратегічно між заполоненим трогами Гуртожитком унизу й спірними коридорами Зали Шестерень нагорі, вона слугує укріпленою передовою базою. Рішучі гноми-захисники, техніки й польові медики тримають барикади вдень і вночі, щоб експедиції Альянсу мали надійний плацдарм, де можна перегрупуватися, перев'язати рани й полагодити машини."},{t="Іскромат 5200",b="Чиста Зона — не лише військовий редут, а й осередок порятунку втраченої столиці. Гномські інженери встановили тут машини «Іскромат 5200», щоб хімічно чистити й відмивати вкриті брудом реліквії, витягнуті з радіоактивного черева міста. Техніки й крамарі на кшталт Тінка Спрокетвісла обробляють ці повернені шестерні й дрібнички, споряджаючи шукачів пригод і водночас вивчаючи отруйні викиди, що досі отруюють глибокі тунелі."}},faq={{q="Чому ця місцина не опромінена, як решта Гномреґана?",a="У Чистій Зоні живуть гноми, яких не зачепила радіація, що спустошила Гномреґан. Чому саме цю невелику місцину оминуло зараження, розповідь не пояснює.",al={"чому чиста зона не опромінена","чому тут безпечно","радіація чистої зони"}},{q="Що роблять машини Спарклматик 5200?",a="Спарклматики 5200 — особливі гномівські пральні й знезаражувальні машини. Шукачі пригод можуть закидати в них обліплені брудом речі, здобуті у трогів і прокажених гномів, — машина змиває радіоактивний бруд і відкриває корисну руду, самоцвіти, монети чи інженерні дивовижі.",al={"спарклматик 5200","що таке спарклматики","очищення бруду"}},{q="Хто контролює й боронить Чисту Зону?",a="Межу тримає окремий загін незіпсованих гномівських вартових, польових медиків і техніків. Вони відбивають набіги трогів із Гуртожитку й прокажених гномів, що спускаються з верхніх рівнів, щоб уберегти цей опорний пункт.",al={"хто в чистій зоні","охорона чистої зони","хто тримає чисту зону"}},{q="Чи можуть тут гравці безпечно відпочити чи полагодити спорядження?",a="Так. Чиста Зона — діючий польовий табір у глибині Гномреґана: тут є інженерні припаси, ремонт у крамаря Тінка Спрокетвісла й навіть справна поштова скринька для шукачів пригод, що діють за лінією фронту.",al={"ремонт у чистій зоні","чи можна відпочити в чистій зоні","поштова скринька в гномреґані"}}},fp="10,424,21.486.0,21.438.0,59.175.0,42.263.0,40.249.0,39.232.0"}
P.entries["subzone:cleft"] = {n="Розколина",s="Розколина — темна улоговина на північний захід від Доланаара на Тельдрассилі. Колись тихий куточок гілля, вона дісталася зіпсутим фурболгам-Вузлошкірам, які зробили з неї твердиню для засідок на подорожніх, що йдуть головним шляхом до Дарнасуса.",h="Розколина — темна улоговина на північний захід від Доланаара на Тельдрассилі.",kw={"розколина","фурболги","вузлошкіри","доланаар","дарнасус","засідка","тельдрассил"},ang={["class:Druid"]="Зіпсуті Вузлошкіри загрожують безпеці подорожніх на дорозі до Дарнасуса.",["race:NightElf"]="Розколина — болісна трагедія для нічних ельфів: вони бачать, як їхні давні союзники-фурболги піддаються божевіллю й нападають на подорожніх."},sec={{t="Лігво скверни",b="Розколина осторонь шляху між Доланааром і Дарнасусом стала одним із найнебезпечніших лігв на Світовому Дереві. Збожеволілі від нечистої зарази, що шириться Тельдрассилом, тутешні фурболги-Вузлошкіри укріпили цю улоговину. Із цього редуту знавіснілі звірі тероризують місцеві дороги, загрожуючи відрізати Доланаар від столиці."},{t="Засідки на дорозі",b="Загроза з Розколини стала такою серйозною, що Місячна Жриця Амара та її вартові мусили виставити оборонну варту на дорозі біля її входу. Очищення Розколини конче потрібне Вартовим, щоб убезпечити головну артерію, яка з'єднує селища Тельдрассила з Дарнасусом."}},faq={{q="Що таке Розколина?",a="Розколина — лігво фурболгів на гілках Тельдрассила, на північний захід від Доланаара, біля головної дороги до Дарнасуса.",al={"що таке розколина","розколина тельдрассил","місце розколини"}},{q="Хто контролює Розколину?",a="Її захопили ворожі фурболги Вузлошкіри, що стали жертвами підступної скверни Тельдрассила.",al={"хто живе в розколині","вороги розколини","хто править розколиною"}},{q="Чому тут б'ються нічні ельфи?",a="Вузлошкіри з Розколини влаштовують засідки на мандрівників на дорозі до Дарнасуса. Місячна Жриця Амара й Вартові прагнуть убезпечити цю дорогу.",al={"чому нападати на розколину","завдання нічних ельфів розколини","дорога до дарнасуса"}},{q="Чи пов'язана Розколина з Тіньовою Розколиною?",a="Ні. Попри схожу назву, ця Розколина — печера фурболгів на Тельдрассилі, а Тіньова Розколина — темна підземна печера в столиці Орди, Оргріммарі.",al={"зв'язок з тіньовою розколиною","розколина проти тіньової розколини"}}},fp="5,265,19.366.0,21.295.1,18.143.0,23.104.0,38.157.0,44.185.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Тіньова Розколина",s="Тіньова Розколина, що ховається глибоко в підземних печерах під Оргріммаром, — оселя міських майстрів скритності, чаклунства й демонології. Далеко від гордого воїнського духу верхніх районів Тралла вона слугує необхідним прихистком для розбійників, чорнокнижників і магів, що діють у тіні Орди.",h="Тіньова Розколина, що ховається глибоко в підземних печерах під Оргріммаром, — оселя міських майстрів...",kw={"тіньова розколина","оргріммар","розбійники","чорнокнижники","маги","провалля лютого вогню"},ang={["class:Rogue"]="Тут збирається Братство Прудкої Тіні разом із торговцями отрутами й зламувачами замків, тож цей темний закуток став головним лігвом таємних агентів Орди.",["class:Warlock"]="Анклав Темного Вогню дає чорнокнижникам Орди дозволене місце під Оргріммаром, де можна прикликати демонів і підкоряти енергію скверни, не накликаючи на себе гніву шаманів і воїнів."},sec={{t="Підземне святилище",b="Нова Орда Тралла звеличує честь, шаманство й силу зброї, та розважливий провід розуміє, що й тоншим мистецтвам потрібне місце. Тіньова Розколина, висічена у вогких кам'яних печерах під столицею, прихищає розбійників із Братства Прудкої Тіні, чорнокнижників з Анклаву Темного Вогню й учених Чародійного Анклаву. Подалі від щоденної метушні долин цей темний квартал дає змогу знавцям отрут, енергії скверни й чародійної магії займатися своїм ремеслом не на людях, хоч і під пильним оком провідників Оргріммара."},{t="Небезпечний поріг",b="Тіньова Розколина — не лише осередок таємного навчання й магічних реагентів: вона спускається просто до Провалля Лютого Вогню. Ця вогняна мережа вулканічних печер пронизує надра під самим Оргріммаром і становить постійну загрозу, що приваблює до краю печери і відважних захисників, і зловісних культистів."}},faq={{q="Чому чорнокнижників і розбійників тримають тут, під землею?",a="Тралл прагне згуртувати Орду довкола шляхетних шаманських і воїнських традицій. Користь від чорнокнижників і розбійників визнають, але більшість орків не довіряє їхнім практикам. Тримаючи їх у підземних печерах, небезпечну магію Скверни й незаконні справи обмежують і пильнують.",al={"чому тіньова розколина","чому чорнокнижники під землею оргріммара","переказ про тіньову розколину"}},{q="Які головні наставники й послуги є в Тіньовій Розколині?",a="Печера — головний осередок Оргріммара для наставників розбійників, чорнокнижників і магів. Тут також є постачальники отрут, крамарі реагентів і продавці жезлів та палиць.",al={"наставники тіньової розколини","хто в тіньовій розколині"}},{q="Що за вхід на дні печери?",a="Прірва в долівці печери веде до Провалля Лютого Вогню — небезпечної підземної мережі лавових тунелів під Оргріммаром, де кишать троги, пекучі елементалі й культисти-відступники.",al={"підземелля тіньової розколини","вхід у печеру розколини","яке підземелля тут"}}},fp="15,315,24.573.0,21.326.0,50.318.0,69.162.0,49.191.0"}
P.entries["subzone:cliffspring-falls"] = {n="Водоспад Скельного Джерела",s="Водоспад Скельного Джерела — величний початок важливої для Темного Узбережжя Річки Скельного Джерела, що зривається зі східних скель у прибережний ліс. Довго його шанували як головне джерело чистої питної води в краї, але останнім часом його води вразила мерзенна скверна, що шириться. Підземну печеру, яка живить водоспад, заполонили ворожі наги й таємничі культисти Молота Присмерку.",h="Водоспад Скельного Джерела — величний початок важливої для Темного Узбережжя Річки Скельного Джерела, що...",kw={"водоспад скельного джерела","річка скельного джерела","наги","молот присмерку","скверна","темне узбережжя"},ang={["class:Druid"]="Друїди Кола Кенарія пильно стежать за річкою, намагаючись розпізнати й очистити неприродне гниття, що загрожує задушити дику природу.",["race:NightElf"]="Для калдореїв Обердайна осквернення Водоспаду Скельного Джерела — природна й духовна криза: отруєно життєдайні води, що живлять прадавні ліси Темного Узбережжя."},sec={{t="Отруєне джерело",b="Водоспад Скельного Джерела, що б'є з печер високо в скелястих кручах на східному кордоні Темного Узбережжя, живить Річку Скельного Джерела, яка петляє на захід лісами й впадає в море. Здавна цей каскад давав місцевим поселенням нічних ельфів найчистішу питну воду. Проте останнім часом води стали брудними й каламутними, поширюючи хвороби й занепад природи по всьому басейну річки. Дослідники природи з'ясували, що мережу печер біля витоків водоспаду заполонили мерзенні наги й темні культисти, які плетуть змови в тіні, а демонічна скверна із сусіднього Сквернолісся загрожує просочитися крізь скелі нагір'я."}},faq={{q="Що таке Водоспад Скельного Джерела?",a="Водоспад Скельного Джерела — великий водоспад на сході Темного Узбережжя, з якого бере початок Річка Скельного Джерела. Здавна він був головним джерелом питної води для навколишнього лісу.",al={"водоспад скельного джерела","водоспад скельної води","що таке водоспад скельного джерела"}},{q="Чому вода з водоспаду зіпсована?",a="Підозрюють дві лихі причини: демонічну скверну, що просочується крізь гори зі зіпсованого Сквернолісся, і присутність культистів Молота Присмерку та ворожих наг, що ховаються в печерах, які живлять водоспад.",al={"чому вода заражена","осквернення річки скельного джерела","заражена вода"}},{q="Хто засів у печерах за водоспадом?",a="Печери над водоспадом і за ним кишать ворожими нагами, що повзають затопленими залами, а також культистами апокаліптичного Молота Присмерку.",al={"хто в печерах","мобі печер скельного джерела","хто живе у водоспаді скельного джерела"}},{q="Чому Водоспад Скельного Джерела такий важливий для Темного Узбережжя?",a="Річка Скельного Джерела перетинає самий центр півночі Темного Узбережжя. Це головне джерело прісної води, тож її отруєння прямо загрожує звірам, давнім гаям і місцевим оселям нічних ельфів.",al={"чому темне узбережжя дбає","важливість скельного джерела"}}},fp="17,417,16.682.0,26.197.0,49.225.0,42.181.0,51.218.0"}
P.entries["subzone:clockwerk-run"] = {n="Годинниковий Хід",s="Годинниковий Хід — головний вхідний коридор, що веде до серця полеглого Гномреґана. Цей пошкоджений коридор, що тягнеться між Депо потяга й Залою Шестерень, сильно заражений отруйними опадами й кишить опроміненими трогами.",h="Годинниковий Хід — головний вхідний коридор, що веде до серця полеглого Гномреґана.",kw={"годинниковий хід","гномреґан","депо потяга","зала шестерень","троги","радіація"},ang={["profession:Engineering"]="Зруйновані машини й обвалена інфраструктура вздовж Ходу похмуро показують, що буває з гномськими механізмами промислового масштабу після катастрофічного вибуху й радіації.",["race:Gnome"]="Пройти Годинниковим Ходом — гірко згадати падіння столиці й на власні очі побачити, як відчайдушна спроба очистити місто змутувала загарбників замість знищити їх."},sec={{t="Зруйнований поріг",b="Головна брама до Гномреґана від зовнішнього депо потяга, Годинниковий Хід колись був жвавою артерією гномських перевезень і постачання. Коли Великий Тінкер Меккаторк наказав випустити радіоактивні відходи, щоб зупинити вторгнення трогів, коридор перетворився на смертельну пастку. Вибух і подальші бої обвалили частини проходу. Нині він задушений отруйними випарами й кишить опроміненими трогами, що нишпорять довкола, — це небезпечна передова, крізь яку мусить пробитися кожна експедиція, щоб дістатися до верхньої Зали Шестерень."}},faq={{q="Куди веде Годинниковий Хід?",a="Годинниковий Хід з'єднує Депо потяга перед глибинними сховищами просто з верхніми рівнями Зали Шестерень у Гномреґані.",al={"місце годинникового ходу","куди веде цей коридор","вхід до годинникового ходу"}},{q="Чому тут стільки трогів?",a="Під час першої навали підземні троги ринули нагору нижніми ходами Гномреґана. Ті, що никають Годинниковим Ходом, надихалися радіоактивних викидів і перетворилися на лютих опромінених трогів, що нападають на кожного, хто намагається потрапити до міста.",al={"чому троги","вороги годинникового ходу"}},{q="Чому коридор частково обвалився?",a="Запеклі бої під час падіння Гномреґана й катастрофічний викид отруйних засобів захисту завдали тяжких ушкоджень спорудам по всьому периметру, тож коридор частково завалився сам на себе.",al={"обвал годинникового ходу","чому зламано"}}},fp="13,248,18.561.0,34.135.0,34.272.0,39.217.0"}
P.entries["subzone:cold-hearth-manor"] = {n="Маєток Холодного Вогнища",s="Маєток Холодного Вогнища — уражений чумою хутір одразу на захід від Брілла, біля головної дороги Галявин Тірісфалю. Колись жвавий, гостинний маєток, славний щедрими врожаями, він утратив усіх мешканців зі спалахом Чуми Нежиті, а довколишні поля заполонила безтямна Погибель. Сьогодні Відступники убезпечили головний будинок як заставу й перевалочний пункт для подорожніх.",h="Маєток Холодного Вогнища — уражений чумою хутір одразу на захід від Брілла, біля головної дороги Галявин...",kw={"маєток холодного вогнища","хутір","брілл","чума","погибель","застава","тірісфаль"},ang={["faction:Horde"]="Маєток дає надійну точку огляду на дорозі між Бріллом і східними краями Тірісфалю — безпечний перепочинок для подорожніх, що пробираються зачумленою околицею.",["race:Undead"]="Для Відступників повернення таких місць, як Маєток Холодного Вогнища, — гірке нагадування про втрачене смертне життя: колишні людські прихистки обертаються на похмурі оборонні застави проти Погибелі й Багряного Хрестового Походу."},sec={{t="Охололе вогнище",b="До Третьої війни ця садиба славилася теплом і гостинністю, даючи багаті врожаї в серці Лордерона. Коли Чума прокотилася королівством, уся родина та її робітники загинули й повстали знову — порожніми оболонками, прив'язаними до Погибелі. Здичавіла нежить досі шкутильгає зруйнованими полями, та сили Відступників зуміли витіснити безтямних мерців із головного будинку й повернули будівлю, зробивши з неї торговий пост і опору на дорозі до східних галявин."}},faq={{q="Що сталося з людьми, які тут жили?",a="Фермерів і робітників маєтку цілком викосила Чума Нежиття, що прокотилася Лордероном. Замість спокою по смерті вони повстали безмозкими зомбі, що й досі блукають навколишніми полями.",al={"хто жив у холодному вогнищі","історія маєтку","що сталося з родиною"}},{q="Чому він зветься Маєток Холодного Вогнища?",a="Колись маєток славився теплом і гостинними вогнищами. Похмуру назву, мабуть, дали Відступники — як іронічний натяк на його колишнє життя й на те, яким холодним, мертвим і отруєним став хутір.",al={"значення холодного вогнища","чому холодне вогнище"}},{q="Хто нині контролює маєток?",a="Відступники захопили головну хату й зробили з неї безпечну зупинку для мандрівників і торгівців на дорозі з Брілла. Проте відкриті поля й клуні довкола маєтку досі кишать ворожою Погибеллю.",al={"хто володіє маєтком холодного вогнища","чи маєток дружній"}},{q="Чому Відступники не очистять поля?",a="Сили Відступників на Галявинах Тірісфалю розпорошені: вони відбиваються від решток безмозкої Погибелі й водночас стримують хрестоносців Багряного Хрестового Походу. Убезпечити хату й головну дорогу — нагальна користь, а розкидані полями мерці — радше прикрість, ніж безпосередня загроза Бріллу.",al={"чому зомбі на полях","чому погибель тут"}}},fp="17,390,16.513.0,43.236.0,35.230.0,33.229.0,44.297.0"}
P.entries["subzone:coldridge-pass"] = {n="Перевал Холодного Кряжа",s="Перевал Холодного Кряжа — суворий засніжений тунель, пробитий крізь південний гірський хребет Дун Мороґу. Це єдиний сухопутний шлях, що сполучає відлюдні тренувальні угіддя Долини Холодного Хребта з рештою королівства і виходить поблизу гамірного містечка Харанос. Та оскільки прохід захопили ворожі троги, кожному мандрівникові доводиться або пробиватися з боєм, або відчайдушно бігти на той бік.",h="Перевал Холодного Кряжа — суворий засніжений тунель, пробитий крізь південний гірський хребет Дун Мороґу.",kw={"перевал холодного кряжа","тунель","троги","долина холодного хребта","харанос","дун мороґ"},ang={["race:Dwarf"]="Для дворфських горян і новобранців перехід через Перевал Холодного Кряжа означає, що ви залишаєте навчання новачка в Анвілмарі й стаєте на дійсну службу в землях Айронфорджа.",["race:Gnome"]="Гноми-вигнанці, що прагнуть допомогти Альянсу, мусять пробитися крізь цю повну трогів горловину, щоб дістатися Хараноса й гірської дороги на Айронфордж."},sec={{t="Брама з долини",b="Для молодих дворфських новобранців і гномів-новачків, що роблять перші кроки за межі Долини Холодного Хребта, Перевал Холодного Кряжа — суворий обряд посвяти. Висічений просто в скелі, цей тунель — головна ланка, що веде щойно навчених шукачів пригод на схід, до прикордонного осередку Харанос. Колись безпечний гірський коридор перетворився на небезпечну вузьку горловину, кишить лютими трогами, які вилізли з темних підземель і загрожують кожному, хто намагається пройти між захищеною долиною і ширшими просторами Дун Мороґу."}},faq={{q="Куди веде Перевал Холодного Кряжа?",a="Перевал з'єднує Долину Холодного Хребта на південному заході з рештою Дун Мороґу й виходить на засніжені пагорби трохи на захід від містечка Харанос.",al={"куди веде перевал холодного кряжа","призначення перевалу холодного кряжа","як вийти з долини холодного кряжа"}},{q="Чому в Перевалі Холодного Кряжа троги?",a="Останнім часом троги ринули з глибоких підземних тріщин під Дун Мороґом і захопили темні печери й тунелі по всьому краю. Перевал Холодного Кряжа дав їм прихисток і зручне місце для засідок на гірських мандрівників.",al={"чому троги тут","чудовиська перевалу холодного кряжа","навала трогів"}},{q="Чи безпечно ходити Перевалом Холодного Кряжа?",a="Ні, небезпечно. Тунель кишить ворожими трогами, тож новобранцям і мандрівникам доводиться прорубуватися крізь цих громил або щодуху бігти темрявою до протилежного кінця.",al={"чи небезпечний перевал холодного кряжа","чи можна пройти перевал холодного кряжа"}},{q="Хто охороняє чи доглядає перевал?",a="Горяни стежать за виходами в долину й на дорогу, але всередині тунель лишається спірним і не очищеним, тож мандрівникам доводиться самим захищатися під час переходу.",al={"дворфійські стражі перевалу холодного кряжа","хто контролює перевал"}}},fp="14,440,29.541.0,31.157.0,39.231.0,41.190.0,33.179.0"}
P.entries["subzone:coldridge-valley"] = {n="Долина Холодного Хребта",s="Долина Холодного Хребта — захищена засніжена долина, схована серед південно-західних височин Дун Мороґу. Її серце — селище Анвілмар, і саме тут молоді дворфи та гномські біженці вперше беруться за зброю на службі Айронфорджу. Єдиний тунель, Перевал Холодного Кряжа, сполучає цю відлюдну улоговину з рештою гірського краю.",h="Долина Холодного Хребта — захищена засніжена долина, схована серед південно-західних височин Дун Мороґу.",kw={"долина холодного хребта","стартова локація","анвілмар","дворфи","гноми","троги","морозогриви"},ang={["race:Dwarf"]="Як споконвічне місце початку шляху для горян і кліриків Бронзбірдів, долина — це перші кроки дворфа від рідного вогнища на службу Високому Престолу.",["race:Gnome"]="Для гномів-вигнанців, змушених залишити Гномреґан, сніги Долини Холодного Хребта — безпечний притулок, де можна опанувати чари й механізми пліч-о-пліч із дворфськими господарями."},sec={{t="Відлюдний полігон",b="Оточена прямовисними гірськими скелями, Долина Холодного Хребта лишається здебільшого відрізаною від жвавих торгових шляхів Дун Мороґу. У її серці стоїть Анвілмар — міцна кам'яна зала й селище, де бувалі дворфські наставники та гноми-вчені, що втратили дім, навчають новобранців мистецтва бою, скритності й чарів. За межами теплих вогнищ Анвілмара дно долини вкрите глибоким снігом, а в ньому нишпорять вепри та голодні зимові вовки — так новачки вперше по-справжньому куштують виживання на порубіжжі."},{t="Вороги насуваються",b="Попри відлюдність, Долині Холодного Хребта безпосередньо загрожують два невтомні вороги. Тутешні тролі Морозогриви розбили табори на кшталт Халупи Морозогривів, нападають на горян і боронять свої прадавні володіння від дворфського наступу. Та ще гірше: дикі троги з племені Кам'янощелепів захопили Перевал Холодного Кряжа — природний тунель, що сполучає долину з Хараносом. Доки цих підземних тварюк не відтіснять, ані мандрівники, ані припаси не зможуть вільно рухатися між долиною та високим престолом Айронфорджа."}},faq={{q="Як вийти з Долини Холодного Хребта?",a="Єдиний сухопутний шлях із долини веде через Перевал Холодного Кряжа — засніжений тунель, пробитий крізь гірський хребет на північний схід. За перевалом дорога прямує на схід, просто до містечка Харанос, а далі — до великої брами Айронфорджа.",al={"вихід із холодного хребта","як вибратися","шлях до хараноса"}},{q="Чому гноми починають тут разом із дворфами?",a="Після трагічного падіння Гномреґану, захопленого трогами й отруєного радіацією, уцілілі гноми втекли до Дун Мороґу як біженці. Король Маґні Бронзбірд прийняв народ Великого Тінкера Меккаторка, тож багато гномських учнів-вигнанців тепер навчаються пліч-о-пліч із молодими дворфами в Анвілмарі.",al={"гноми в долині холодного хребта","чому тут гноми","стартова локація гномів"}},{q="Які загрози турбують долину?",a="Долині загрожують дві головні напасті: ворожі тролі Морозогриви, яким ненависні дворфські поселення на їхніх гірських землях, і грубі троги з племені Кам'янощелепів, що вилізли з надр землі й перекрили Перевал Холодного Кряжа. Тутешні хижаки — вовки та вепри — теж не дають спокою необачним мандрівникам.",al={"вороги холодного хребта","загрози долини","хто нападає"}},{q="Що таке Анвілмар?",a="Анвілмар — центральна фортеця-оселя й поселення Долини Холодного Хребта. Тут розташувалися наставники класів, майстри-ковалі та офіцери місцевих горян, які керують обороною долини й готують щойно загартованих шукачів пригод до великого світу.",al={"містечко анвілмар","що це за містечко тут"}}},fp="16,350,25.508.0,16.522.0,34.256.0,47.293.0,38.283.0,17.249.0"}
P.entries["subzone:commons"] = {n="Торгові Ряди",s="Торгові Ряди — жваве торговельне серце Айронфорджа, що веде від міської брами просто в його величезні печери. Тут аж кишить купцями, мандрівниками й банкірами: це найлюдніша вулиця дворфійської столиці й головне торжище всього Альянсу.",h="Торгові Ряди — жваве торговельне серце Айронфорджа, що веде від міської брами просто в його величезні печери.",kw={"торгові ряди","айронфордж","аукціонний дім","банк","торгівля","альянс"},ang={["faction:Alliance"]="Торгові Ряди — фактично торговий майданчик усього Альянсу: сюди з'їжджаються герої з Тельдрассила, Стормвінда й Гномреґана, щоб виставити на аукціон цінну здобич і запастися припасами.",["race:Dwarf"]="Для дворфів Бронзбірдів Торгові Ряди — предмет гордості, доказ того, що дворфійська гостинність, працьовитість і торгівля можуть процвітати глибоко в серці замерзлої гори."},sec={{t="Торговий осередок гори",b="Торгові Ряди лежать одразу на північний схід від Брами Айронфорджа — це перший район, що зустрічає мандрівників у гірському королівстві. На цій гамірній торговій вулиці, висіченій просто в камені, розташовані головний аукціонний дім Альянсу, Таверна «Кам'яний Вогонь» і центральний банк міста у Сховищі Айронфорджа. Широкі проспекти плавно з'єднують її з Великою Кузнею, Кварталом містиків і Військовим Кварталом, тож майже кожен, хто ходить горою, минає тутешні гамірні крамниці."},{t="Роздоріжжя Альянсу",b="Айронфордж стоїть у самому центрі континенту Східних Королівств і пов'язаний прямою підземною лінією Глибинного трамвая зі Стормвіндом, тож Торгові Ряди — головний торговий вузол Альянсу. Шукачі пригод сходяться сюди, щоб торгувати товарами з усіх куточків Азерота, купувати зброю в таких купців, як Стілф'юрі та Барім, або зустрітися в теплому світлі ліхтарів місцевої корчми, перш ніж вирушити в сніги Каз Модану."}},faq={{q="Чому в Торгових Рядах так людно порівняно з іншими кварталами?",a="У Торгових Рядах — головний Аукціонний дім Альянсу, головний банк міста в Сховищі Айронфорджа й гамірна Таверна «Кам'яний Вогонь». А що вони одразу за головною брамою, це найзручніше місце для зустрічей і торгівлі в усьому королівстві.",al={"чому в торгових рядах людно","чому тут багато гравців","торговий центр айронфорджа"}},{q="Куди ведуть Торгові Ряди?",a="Торгові Ряди сполучаються майже з кожним великим кварталом Айронфорджа. На південний захід — назад до міської брами, на північний схід — до Великої Кузні, на схід — до Військового Кварталу, а на північ — до Кварталу містиків.",al={"виходи торгових рядів","як вийти з торгових рядів","напрями торгових рядів"}},{q="Які головні крамниці й послуги тут є?",a="Окрім Аукціонного дому й банку, у Торгових Рядах є Центр для гостей Айронфорджа, Збройовий Дім Стілф'юрі, Зброярня Айронфорджа, «Реагенти Баріма» й «Товари загального вжитку Фіззлспіннера».",al={"торговці торгових рядів","послуги торгових рядів","зручності торгових рядів айронфорджа"}},{q="Чи тут банк?",a="Yes. The Vault of Ironforge stands across from the Auction House in the Commons and serves as the city's main bank.",al={"де банк айронфорджа","сховище айронфорджа","місце банку"}}},fp="7,278,34.513.0,29.428.0,62.262.0,28.230.0,43.195.0,25.115.0"}
P.entries["subzone:corin-s-crossing"] = {n="Перехрестя Коріна",s="Перехрестя Коріна — зруйноване людське поселення на великому роздоріжжі в південно-центральній частині Східних Чумних земель. Колись квітуча зупинка між Стратгольмом, Рукою Тіра, Дарроуширом і Андоргалом, нині спустошене містечко цілком заполонила Погибель. У його ратуші й кузні, що розсипаються, чигають жахіття, зокрема невидимі примарні вартові.",h="Перехрестя Коріна — зруйноване людське поселення на великому роздоріжжі в південно-центральній частині...",kw={"перехрестя коріна","східні чумні землі","погибель","незримі слуги","стратгольм","озеро мерельдар","нежить"},ang={["class:Paladin"]="Руїни Перехрестя Коріна — цілковите осквернення серця Лордерону: ця жалюгідна твердиня Погибелі глузує зі святого бастіону Стратгольма, що стоїть далі дорогою.",["class:Rogue"]="Не покладайтеся тут на тіні. Незримі Слуги блукають провулками, невидимі для смертного ока, і бачать крізь вашу скритність, тож безтурботна прогулянка міським майданом може стати смертельною."},sec={{t="Розтрощене перехрестя",b="До Третьої війни Перехрестя Коріна було головним вузлом подорожей східним Лордероном. Розташоване між мерехтливими водами Озера Мерельдар і тим, що нині стало сплюндрованою прірвою Шраму Інфектіс, воно бачило на своїх шляхах купців, гінців і прочан, що мандрували між великим бастіоном Стратгольма й південними твердинями. Коли чума прокотилася провінцією, поселення опинилося просто на шляху руйнування й швидко впало під самою вагою авангарду нежиті."},{t="Притулок проклятих",b="Нині Перехрестя Коріна остаточно належить Погибелі. Брудні вулиці заповнені блукаючою нежиттю, а в спорожнілій кузні й ратуші чатують гнилі туші й гулі. Містечко особливо підступне для розвідників: примарні Незримі Слуги дрейфують серед руїн, цілком невидимі для звичайного ока, бачать крізь звичайну скритність і влаштовують засідки на кожного, хто спробує непомітно прослизнути повз головну орду."}},faq={{q="Чим було Перехрестя Коріна до чуми?",a="Це було квітуче вузлове містечко на сході Лордерона. Із ратушею й кузнею в центрі, воно приймало мандрівників між Стратгольмом, Рукою Тіра, Дарроуширом і Андоргалом, доки Погибель не винищила його мешканців.",al={"історія перехрестя коріна","переказ про перехрестя коріна","чим було перехрестя коріна"}},{q="Чому Перехрестя Коріна таке небезпечне для тих, хто скрадається?",a="Містечком блукають Незримі Слуги — невидимі примари, прикуті до Погибелі. Вони легко бачать крізь магічну й звичайну невидимість, заскочуючи зненацька необачних розбійників чи розвідників і скликаючи нежить поблизу.",al={"скрадання на перехресті коріна","невидимі слуги","розбійник перехрестя коріна"}},{q="Які помітні місця довкола містечка?",a="Перехрестя Коріна лежить у південно-центральній частині Східних Чумних земель. Зовсім поруч — отруєний рів Шраму Інфектис, а біля межі — Озеро Мерельдар.",al={"місце перехрестя коріна","де перехрестя коріна"}},{q="Хто нині контролює Перехрестя Коріна?",a="Над руїнами цілковито панує Погибель. Живих захисників у містечку не лишилося, і все поселення кишить мандрівними вояками-нежиттю й духами.",al={"хто володіє перехрестям коріна","фракція перехрестя коріна"}}},fp="16,358,22.539.0,21.419.0,44.228.0,60.222.0,39.180.0,36.169.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="Кинджал Коррана",s="Кинджал Коррана — другий із чотирьох гірських «пальців», що здіймаються над північчю Передгір'я Гілсбреда. Ця височина править за схованку головорізам Синдикату.",h="Кинджал Коррана — другий із чотирьох гірських «пальців», що здіймаються над північчю Передгір'я Гілсбреда.",kw={"кинджал коррана","гілсбред","синдикат","розбійники","кряж"},ang={["race:Dwarf"]="Кряж — схованка Синдикату, тож дворфам, які перетинають північні передгір'я, варто чекати тут розбійників, а не союзників.",["race:Undead"]="Головорізи Синдикату на кряжі ворожі до Відступників, що діють у Гілсбреді."},sec={{t="Північний оплот",b="Кинджал Коррана круто здіймається на півночі Передгір'я Гілсбреда — це другий із чотирьох скелястих виступів, які місцеві звуть пальцями Гілсбреда. Кряж захопили головорізи Синдикату: з висоти вони стежать за долиною внизу."}},faq={{q="Хто контролює Кинджал Коррана?",a="Хребет тримають люди-відступники із Синдикату, які зробили з висот свою схованку.",al={"хто на кинджалі коррана","фракція кинджала коррана","хто тут живе"}},{q="Що таке пальці Гілсбреда?",a="Пальці Гілсбреда — чотири помітні гірські хребти, схожі на пальці, що тягнуться від північного пасма на південь у долину Гілсбреда. Кинджал Коррана — другий із них.",al={"чотири пальці гілсбреду","чотири хребти гілсбреду","пальці гілсбреду"}}},fp="16,184,22.271.0,30.86.0,34.205.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="Тераса Ремісників",s="Тераса Ремісників — гамірний район майстрів на півночі Дарнасуса. Це головний осередок ремесел і торгівлі столиці нічних ельфів: тут майстерні, наставники професій і жвава корчма. Район приймає й гостей іздалеку — зокрема тут розташоване посольство нейтрального Срібного світанку.",h="Тераса Ремісників — гамірний район майстрів на півночі Дарнасуса.",kw={"тераса ремісників","дарнасус","ремесла","професії","срібний світанок","корчма"},ang={["faction:Alliance"]="Гості з Альянсу вважають терасу одним із найгостинніших куточків Дарнасуса: тут є звичні товари для ремесел, управління гільдіями й нічліг, а поруч — іноземні представники.",["race:NightElf"]="Для калдореїв тераса — доказ того, що їхня громада на Тельдрассилі здатна покладатися на власні сили, поєднуючи давнє ремесло з повсякденними потребами нової столиці."},sec={{t="Ремісниче серце Дарнасуса",b="Тераса Ремісників тягнеться північним краєм міста в кронах і збирає докупи різні ремесла, на яких тримається життя Дарнасуса. Тут мають свої крамниці теслі, шкірники, алхіміки й інші майстри, що поєднують давні методи нічних ельфів із практичним ремеслом. Є тут і все потрібне для громади: корчма, розпорядник гільдій і продавці гільдійських грамот. Мости ведуть із тераси просто до Ценаріонського Анклаву на заході й до Тераси Воїна на півдні."},{t="Зв'язки зі світом і забуті знання",b="Попри споконвічну відокремленість калдореїв, на Терасі Ремісників є й зв'язки із зовнішнім світом — передусім посольство Срібного світанку, яке узгоджує дії з північними союзниками проти Погибелі. Блукаючи майстернями району, гості можуть натрапити й на розкидані вчені томи — від історичних оповідей про Війну Прадавніх до хронік Другої війни та езотеричних трактатів про Древніх Богів."}},faq={{q="Які послуги є на Терасі Ремісників?",a="У кварталі — більшість міських наставників ремесел, крамарі з ремісничими припасами, корчма й реєстрація гільдій. Це торговий осередок для мандрівників, що хочуть опанувати чи практикувати ремесла в Дарнасусі.",al={"послуги тераси ремісників","що є на терасі ремісників","наставники дарнасуса"}},{q="Чому на Терасі Ремісників є Срібний Світанок?",a="Срібний Світанок тримає в кварталі посольство, щоб підтримувати зв'язок із нічними ельфами й шукати допомоги проти Погибелі. Його присутність — дипломатичний місток між силами Альянсу на заході й розореними війною землями Лордерона.",al={"срібний світанок дарнасус","посольство срібного світанку","чому срібний світанок тут"}},{q="Як дістатися до Тераси Ремісників?",a="Тераса займає північну частину Дарнасуса. До неї можна дійти мостами на північ від Тераси Воїна чи на схід від Ценаріонського Анклаву.",al={"як дістатися тераси ремісників","місце тераси ремісників","знайти терасу ремісників"}},{q="Які помітні книги можна знайти в майстернях?",a="По майстернях лежать учені томи, зокрема історії Війни Прадавніх і наслідків Другої війни, а також дослідження про Древніх Богів у приміщенні Срібного Світанку.",al={"книги тераси ремісників","книги переказів дарнасуса","книги в майстернях"}}},fp="19,341,30.508.0,31.454.0,51.235.0,58.239.0,41.160.0,53.199.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Скеля Вічноживих",s="Скеля Вічноживих — зелена печерна зала глибоко в Печерах Стогонів. Тут панують буйні зіпсовані рослини й хижі рослинні істоти, а саме місце — володіння Володаря іклів Лорда Пайтаса. У її височенних верхніх ярусах ховається прадавня істота, на честь якої названо скелю.",h="Скеля Вічноживих — зелена печерна зала глибоко в Печерах Стогонів.",kw={"скеля вічноживих","печери стогонів","вердан вічноживий","лорд пайтас","лорд серпентіс","травництво"},ang={["class:Druid"]="Скеля Вічноживих — трагічний урок для друїдів Кола Кенарія: чисту природну життєву силу й охоронну місію стихій тут обернули на смертоносні знаряддя Жахіття.",["profession:Herbalism"]="Протиприродно буйне підземне повітря скелі живить рідкісне коріння й гриби, що розквітають у вологому, просякнутому снами ґрунті."},sec={{t="Спотворене гілля",b="Більшу частину Печер Стогонів видовбано у вологому підземному камені, але Скеля Вічноживих аж буяє неприборканою, спотвореною рослинністю, яку живить Жахіття, що отруює сон Наралекса. Височенні мохові уступи й звивисті стежки заполонили девіантні човгуни — живі рослинні громадини, що никають підліском. Лорд Пайтас, один із занепалих учнів Наралекса, стереже середину скелі: він проміняв шляхетні друїдські обітниці на отруйні обряди Друїдів Ікла."},{t="Прадавній охоронець",b="Зала дістала назву на честь Вердана Вічноживого — велетенського первісного рослинного елементаля, що живе у верхніх висотах скелі. Спотворений Смарагдовим Жахіттям, яке тримає печеру в лещатах, Вердан тепер не мирний природний охоронець, а грізна лінія оборони. За його височенною постаттю чатує Лорд Серпентіс, самопроголошений ватажок Володарів іклів, який веде секту в безодню зміїного божевілля."}},faq={{q="Звідки назва цієї місцини?",a="Залу названо на честь Вердана Вічноживого — давнього колосального рослинного звіра, що живе на найвищих терасах скелі. Колись він був утіленням позачасової життєвої сили природи, але потрапив під владу Жахіття, що вразило печери.",al={"чому скеля вічноживих","походження назви скелі вічноживих","назва скелі"}},{q="Хто контролює цю частину печер?",a="Скелею безпосередньо керує Лорд Пайтас, один із головних Володарів Ікла. На вищих уступах над ним чаяться Вердан Вічноживий і Лорд Серпентіс — ватажок Друїдів Ікла.",al={"хто тут головний","бос скелі","володар іклів тут"}},{q="Які істоти зазвичай трапляються на Скелі Вічноживих?",a="Скеля кишить Мутованими Шкандибачами — рослинними потворами, народженими зіпсованими джерелами, — а також спотвореними зміями й фанатичними Друїдами Ікла.",al={"чудовиська скелі","вороги скелі","що тут живе"}},{q="Чому рослини так буйно ростуть глибоко під землею?",a="Підземні джерела використав друїд нічних ельфів Наралекс, щоб відродити Пустки. Коли його обряд потрапив у пастку Смарагдового Жахіття, дикий ріст вийшов з-під контролю й перетворився на ворожу, спотворену рослинність.",al={"чому рослини під землею","чому все зелене","осквернена зелень"}}},fp="22,298,18.491.0,20.427.0,34.261.0,38.196.0,64.170.0,47.219.0"}
P.entries["subzone:cragpool-lake"] = {n="Озеро Скельної Заводі",s="Озеро Скельної Заводі ховається в Кручі Вітрорізу в Горах Кам'яного Кігтя. Над його темними водами нависає величезна дерев'яна споруда Венчурної Компанії.",h="Озеро Скельної Заводі ховається в Кручі Вітрорізу в Горах Кам'яного Кігтя.",kw={"озеро скельної заводі","круча вітрорізу","венчурна компанія","ґерензо ренчвісл","гори кам'яного кігтя","лісорубство"},ang={["class:Druid"]="Стоки, дерев'яні помости й розруха довкола Озера Скельної Заводі — потворний шрам на тілі Кам'яного Кігтя: вони калічать місцеву природу й виганяють тутешніх звірів із рідних місць.",["profession:Engineering"]="Висока дерев'яна риштовка й консольні механізми над Озером Скельної Заводі — хрестоматійний приклад гоблінської промислової доцільності: зведено нашвидкуруч, навантажено до краю, а рельєф місцевості нікого не обходить."},sec={{t="Промисловий наступ",b="Озеро Скельної Заводі лежить глибоко в Кручі Вітрорізу, просто під височенною лісозаготівельною машинерією Венчурної Компанії. Над водою розкинулася велетенська дерев'яна конструкція — оглядовий пункт, звідки Ґерензо Ренчвісл керує роботами по всій гірській долині. На помостах угорі порядкують робітники Венчурної Компанії."}},faq={{q="Що за величезна дерев'яна споруда нависає над озером?",a="Це промислова надбудова, яку звела Венчурна Компанія, щоб керувати масштабною вирубкою лісу й видобутком на Кручі Вітрорізу. Вона з'єднує платформи й важкі машини просто над озером.",al={"платформа венчурної компанії","риштування скельної заводі","міст скельної заводі"}},{q="Хто керує роботами на Озері Скельної Заводі?",a="Ґерензо Ренчвісл, важливий агент Венчурної Компанії, облаштувався на верхівці високого риштування, щоб наглядати за вирубкою лісу й видобутком ресурсів по всій Кручі Вітрорізу.",al={"хто керує венчурною компанією тут","хто тут бос","ґеренцо врентвістл"}},{q="Які небезпеки чатують біля Озера Скельної Заводі?",a="На помостах над озером хазяйнує Венчурна Компанія. Її озброєні робітники роблять цей промисловий об'єкт небезпечним для чужинців.",al={"що в озері скельної заводі"}},{q="Чи Венчурна Компанія покинула Озеро Скельної Заводі?",a="Ні. Споруду над озером займають робітники Венчурної Компанії та Ґерензо Ренчвісл.",al={"чи венчурна компанія пішла","хто живе біля озера скельної заводі"}}},fp="13,184,23.344.0,59.212.0,45.193.0,36.128.0,48.90.0"}
P.entries["subzone:crossroads"] = {n="Перехрестя",s="Перехрестя — серце сполучення Орди через центральний Калімдор: воно стоїть там, де Золотий Шлях, що тягнеться з півночі на південь, перетинає дорогу від Раджета до Гір Кам'яного Кігтя. Це гамірна торгова застава, військовий плацдарм і перевалочний пункт для мандрівників між Дуротаром, Малгором і північними фронтами.",h="Перехрестя — серце сполучення Орди через центральний Калімдор: воно стоїть там, де Золотий Шлях, що тягнеться...",kw={"перехрестя","золотий шлях","орда","раджет","вітрокрили","пустки"},ang={["faction:Alliance"]="Удар по Перехрестю відрізає потік підкріплень Орди між Оргріммаром, Малгором і спірними кордонами Ашенвалю.",["faction:Horde"]="Перехрестя — головне випробувальне поле й осердя вашої молодої держави: воно з'єднує батьківщини орків, тауренів і тролів і координує постачання по всьому Калімдору."},sec={{t="Життєво важливий вузол савани",b="Як і каже назва, Перехрестя стоїть якраз на перетині Золотого Шляху й дороги зі сходу на захід, що веде від гоблінського порту Раджет до Гір Кам'яного Кігтя. Попри скромне житло, застава — гамірний осередок усього краю. Господарі вітрокрилів, крамарі, ковалі й наставники постійно працюють тут під сторожовими вежами. Для молодих воїнів із Дуротара чи Малгору це поселення часто стає першим місцем, де вони бачать, як складна мережа постачання на багатьох фронтах тримає нову Орду вкупі."},{t="Прикордонна застава в облозі",b="Підтримувати лад на Перехресті — нескінченна боротьба. Місцеві звірі, зокрема рівнинні раптори, що мають нахабство красти зі сторожових веж срібло на платню, — постійна морока, а гарпії, шипогриви й племена кентаврів невпинно тиснуть на околиці. Окрім загроз, звичних для Пусток, близькість до нейтрального Раджета й спірних лісів Ашенвалю робить поселення ласою ціллю для розвідувальних загонів Альянсу, тож сутички трапляються просто за його оборонними барикадами."}},faq={{q="Чому Перехрестя таке важливе для Орди?",a="Воно тримає головні транспортні артерії центрального Калімдору. Кожен мандрівник, що суходолом прямує між Дуротаром, Малгором, Раджетом, Горами Кам'яного Кігтя чи Ашенвалем, мусить пройти через Перехрестя чи повз нього, тож це головний вузол постачання й підкріплень.",al={"чому перехрестя важливе","призначення перехрестя","значення перехрестя"}},{q="Хто забезпечує повітряне сполучення на Перехресті?",a="Деврак — приборкувач летунів на Перехресті: він доглядає сідало вітрогонів і сполучає мандрівників із заставами по всьому Калімдору, зокрема з Оргріммаром і Тандер Блафом.",al={"майстер польотів перехрестя","хто тримає віверн тут","політний майстер перехрестя"}},{q="Чому Альянс так часто нападає на Перехрестя?",a="Перехрестя — осердя руху Орди, і воно лежить на відстані зручного удару і від Ашенвалю на півночі, і від нейтрального порту Раджет на сході, тож загони Альянсу раз у раз б'ють по заставі, щоб перерізати шляхи постачання Орди.",al={"чому альянс нападає на перехрестя","бої гравців на перехресті","напади на перехрестя"}},{q="Що сталося зі сріблом на платню для застави?",a="Раптори Пусток напали на вартову вежу Перехрестя й потягли партію срібла, призначену на платню вартовим поселення, розкидавши її по навколишній савані.",al={"вкрадена платня перехрестя","хто взяв срібло","вкрадене срібло перехрестя"}}},fp="10,336,32.539.0,28.538.0,48.251.0,48.198.0,58.253.0,46.184.0"}
P.entries["subzone:crown-guard-tower"] = {n="Вежа Коронної Варти",s="Вежа Коронної Варти — зруйнована дозорна вежа Лордерона на півдні Східних Чумних Земель. Погибель знищила її під час вторгнення в Лордерон у Третю війну, і відтоді її уламки стоять посеред зачумленої землі.",h="Вежа Коронної Варти — зруйнована дозорна вежа Лордерона на півдні Східних Чумних Земель.",kw={"вежа коронної варти","дозорна вежа","лордерон","погибель","руїни","східні чумні землі"},ang={["faction:Alliance"]="Для Альянсу зруйнована Вежа Коронної Варти — нагадування про те, як дощенту Погибель зламала оборону Королівства Лордерон."},sec={{t="Полеглий оплот",b="Колись Вежа Коронної Варти входила до оборонної лінії Королівства Лордерон: з неї дозорці стежили за землями східного Лордерона. Коли Погибель захопила королівство, вежу знищили й покинули в руїнах. Це одна з кількох повалених веж, розкиданих теренами нинішніх Східних Чумних Земель. Її обвуглене каміння стоїть на землі, яку й досі тримає нежить."}},faq={{q="Для чого спершу збудували Вежу Коронної Варти?",a="До Третьої війни вона була військовою вартовою вежею й розвідувальною заставою людського королівства Лордерон, що стерегла дороги від набігів.",al={"історія вежі коронної варти","навіщо збудували","вежа лордерона"}},{q="Чому вежа зруйнована?",a="Вежу зруйновано під час вторгнення Погибелі в Лордерон, коли хвилі нежиті змели оборону королівства, лишивши від споруди самі уламки.",al={"хто зруйнував вежу коронної варти","що тут сталося"}}},fp="17,225,16.354.0,48.157.0,24.151.0"}
P.entries["subzone:crusader-outpost"] = {n="Застава Хрестоносців",s="Застава Хрестоносців — укріплена сторожова вежа на скелястих пагорбах східних Галявин Тірісфалю. Її тримають ревні члени Багряного Хрестового Походу, охороняючи підступи до своєї твердині — Багряного Монастиря. З цієї висоти хрестоносці стежать за рухом на дорозі й готові відбити будь-яке вторгнення Відступників.",h="Застава Хрестоносців — укріплена сторожова вежа на скелястих пагорбах східних Галявин Тірісфалю.",kw={"застава хрестоносців","багряний хрестовий похід","сторожова вежа","багряний монастир","капітан вашон","тірісфаль"},ang={["faction:Horde"]="Східними стежками Тірісфалю треба йти обережно: багряні вартові на цьому пагорбі миттю нападуть на кожного, хто прямує до Монастиря.",["race:Undead"]="Ця сторожова вежа стоїть на самому краю земель Відступників — гірке нагадування, що ревні живі хрестоносці досі тримають суверенні острівці в галявинах."},sec={{t="Очі над Тірісфалем",b="Збудована на кручах над східною дорогою, Застава Хрестоносців — головний пост раннього попередження Багряного Хрестового Походу. З високої вежі вартові стежать за рухом між Бріллом і східними краями Лордерона, щоб мандрівну нежить чи розвідувальні загони помічали задовго до того, як ті дістануться брами Монастиря. Вежа також дає гарнізону змогу вдарити з флангу по будь-якому війську, що спробує піднятися долиною до їхнього святого бастіону."},{t="Скалка в боці Темної Леді",b="Під командуванням багряних офіцерів на кшталт Капітана Вашона тутешній гарнізон зберігає непохитну пильність. Довколишні ліси для них — не суверенна земля Відступників, а неосвячений ґрунт, украдений у людства чудовиськами. Для мандрівників, вірних Андерсіті, застава — повсякчасне місце засідки, де арбалетні болти й очисна сталь чекають на кожного, хто надто наблизиться до круч."}},faq={{q="Що таке Застава Хрестоносців?",a="Це укріплена розвідувальна вежа Багряного Хрестового Походу на сході Галявин Тірісфалю. Вона стежить за дорогою внизу й захищає південні підступи до Багряного Монастиря.",al={"що за вежа","застава хрестоносців тірисфаль","багряна дозорна вежа"}},{q="Хто контролює цю заставу?",a="На заставі несуть службу фанатики Багряного Хрестового Походу під командуванням Капітана Вашона. Усю нежить вони вважають потворами, яких треба знищувати на місці.",al={"хто володіє заставою хрестоносців","хто тут живе","застава багряного хрестового походу"}},{q="Чому вежа стоїть на цих пагорбах?",a="З високого місця добре видно головний східний шлях Галявин Тірісфалю. Тож хрестоносці можуть завчасно помітити пересування військ Відступників і вдарити у фланг будь-яким силам, що спробують напасти на Багряний Монастир.",al={"чому збудували тут","місце застави","тактична мета"}},{q="Чи нападуть на мене тутешні вартові?",a="Так. Багряний Хрестовий Похід вважає всіх чужинців — особливо Відступників та їхніх союзників з Орди — зіпсованими ворогами, яких треба очистити святим вогнем.",al={"чи застава хрестоносців ворожа","чи вони агресивні"}}},fp="16,340,18.492.0,31.433.0,29.184.0,26.156.0,41.232.0,31.150.0"}
P.entries["subzone:crusader-s-armory"] = {n="Зброярня Хрестоносця",s="Зброярня Хрестоносця — укріплена внутрішня зала в крилі Зброярні Багряного Монастиря. Напхана боєприпасами, порохом і гарматними ядрами, вона слугує плацдармом для фанатиків, що стережуть шлях до внутрішнього святилища. За її замкненими залізними дверима лежить Зала Чемпіонів.",h="Зброярня Хрестоносця — укріплена внутрішня зала в крилі Зброярні Багряного Монастиря.",kw={"зброярня хрестоносця","багряний монастир","зала чемпіонів","багряний ключ","порох","хрестоносці"},ang={["faction:Horde"]="Для Відступників і всієї Орди вибухові запаси Зброярні Хрестоносця — пряма загроза кордонам Галявин Тірісфалю й брамам Андерсіті.",["profession:Blacksmithing"]="Зброя й боєприпаси, складені тут, свідчать про високу майстерність і військову дисципліну колишніх ковалів Лордерону, які тепер служать сліпому фанатизму."},sec={{t="Арсенал фанатизму",b="Зброярня Хрестоносця, розташована між Зброярнею Піхотинця й величною Залою Чемпіонів, показує повну бойову готовність Багряного Хрестового Походу. На відміну від тренувальних дворів зовні, ці вузькі кам'яні коридори аж до стелі заставлені ящиками з вибухонебезпечним порохом, штабелями гарматних ядер і важкоозброєними хрестоносцями, готовими відбити будь-якого зайду. Похід перетворив колишній монастир на наїжачену фортецю й віддав кожну вільну залу знаряддям тотальної війни. У дальньому кінці зброярні стоять важкі замкнені залізні двері: до внутрішніх покоїв не пройти, якщо не маєш Багряного Ключа."}},faq={{q="Що таке Зброярня Хрестоносця?",a="Зброярня Хрестоносця — внутрішня частина крила Зброярні Багряного Монастиря. Це склад боєприпасів і оборонний коридор між Зброярнею Піхотинця й Залою Чемпіонів.",al={"зброярня хрестоносця","що таке зброярня хрестоносця","кімната зброярні монастиря"}},{q="Чому двері наприкінці замкнені?",a="Двері наприкінці Зброярні Хрестоносця стережуть прохід до Зали Чемпіонів і покоїв командира за нею. Багряний Хрестовий Похід суворо їх замикає, і щоб відімкнути, потрібен Багряний Ключ, який можна знайти в крилі Бібліотеки Монастиря.",al={"замкнені двері зброярні","як відчинити двері зброярні","багряний ключ зброярні"}},{q="Чому тут стільки гарматних ядер і ящиків із порохом?",a="Багряний Хрестовий Похід тримає облогові сили й артилерійську оборону по всіх Галявинах Тірісфалю. Ця зброярня — головний склад для їхніх гармат і вибухових снарядів, щоб війська мали все необхідне для війни з Погибеллю й Відступниками.",al={"порохові ящики зброярні","гармати в монастирі","чому порох"}},{q="Хто охороняє цю місцину?",a="Залу боронять бувалі вояки Багряного Хрестового Походу — піхотинці, хрестоносці й лучники, розставлені серед боєприпасів, щоб зупинити загарбників, які прагнуть пробитися глибше в комплекс.",al={"мобі зброярні","хто в зброярні хрестоносця"}}},fp="17,293,15.621.0,30.194.0,34.252.0,60.275.0,21.196.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Застава Хрестоносця",s="Застава Хрестоносця — укріплена розвідувальна вежа Багряного Хрестового Походу в західних Галявинах Тірісфалю. Поруч із нею лежить Хутір Соллідена, а сама вежа — найзахідніша позиція Хрестового Походу в усьому Лордероні. Небезпечна віддаленість від головних багряних бастіонів лишає її гарнізон відрізаним у серці ворожих земель Відступників.",h="Застава Хрестоносця — укріплена розвідувальна вежа Багряного Хрестового Походу в західних Галявинах Тірісфалю.",kw={"застава хрестоносця","багряний хрестовий похід","сторожова вежа","хутір соллідена","похоронний подзвін","тірісфаль"},ang={["faction:Horde"]="Застава — гірке нагадування про фанатичну відмову Багряного Хрестового Походу поступитися Тірісфалем Відступникам та їхнім союзникам з Орди.",["race:Undead"]="Для щойно воскреслих Відступників, що виходять із Похоронного Подзвону, ця сусідня вежа й багряні фанатики, що її стережуть, — безпосередня смертельна загроза просто на їхньому кордоні."},sec={{t="Самотня сторожова вежа",b="Ця кам'яна вежа на західних пагорбах Тірісфалю, одразу на захід від Похоронного Подзвону, — крайня межа влади Багряного Хрестового Походу в Лордероні. Тутешній гарнізон діє разом із уцілілими людськими робітниками сусіднього Хутора Соллідена, намагаючись стримати нежить, що насувається. З вершини вежі дозорці пильнують довколишні гарбузові поля й лісові стежки, остерігаючись і мандрівних почвар Погибелі, і патрулів з Андерсіті."},{t="Відрізані в тилу ворога",b="Утримувати західний кордон украй небезпечно. Відрізані від своїх головних твердинь — Багряного Монастиря й далекої Руки Тіра на сході, — хрестоносці цієї застави не можуть сподіватися на швидке підкріплення, якщо напад проломить частокіл. Будь-яка облога силами Відступників, що збираються по всьому Тірісфалю, означає або втримати вежу самотужки, або бути знищеними дощенту, перш ніж допомога взагалі надійде."}},faq={{q="Чому Багряний Хрестовий Похід аж тут, на заході Тірісфалю?",a="Вежа — пост раннього попередження й оборонне укріплення на західних пагорбах Тірісфалю. Вона захищає живих людей-фермерів на Хуторі Соллідена й стежить за західними підступами, звідки можуть підійти і дика Погибель, і передові розвідники Відступників.",al={"чому багряні тут","багряні хрестоносці захід тірисфалю","призначення застави хрестоносця"}},{q="Чи зможуть підкріплення дістатися застави, якщо на неї нападуть?",a="Нелегко. Застава — найзахідніше володіння Багряних у Лордероні. Їхні головні твердині — далеко на сході, у Багряному Монастирі й Руці Тіра, тож якщо сили Відступників оточать гарнізон, він опиниться цілком відрізаним.",al={"чи підкріплення дійде","допомога заставі","як далеко допомога"}},{q="Що пов'язує вежу з Хутором Соллідена?",a="Хрестоносці вступили в союз із рештою людей-фермерів на Хуторі Соллідена. Солдати захищають їх від ходячих мерців в обмін на харчі й вірний плацдарм на околицях Лордерона.",al={"зв'язок із соллідена","чому хрестоносці на фермі","хрестоносці й фермери"}},{q="Чи є в краї інші такі вежі?",a="Так. Ця вежа — одна з чотирьох подібних Застав Хрестоносця, які Багряний Хрестовий Похід звів по Галявинах Тірісфалю, щоб розвідувати й патрулювати навколишні землі.",al={"інші застави хрестоносців","більше багряних веж"}}},fp="18,343,19.496.0,27.411.0,68.253.0,58.229.0,66.221.0,47.160.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Склеп (Фортеця Стромгард)",s="Глибоко в руїнах Фортеці Стромгард, за каплицею Святилища, у серці кварталу, який досі тримають уцілілі захисники Стромґарда, лежить королівський склеп. Тут гробниця полеглого короля Тораса Троллбейна й родові скарби його династії. Склеп пильно стережуть Принц Ґален і вірні доглядачі, і він лишається святинею королівської честі посеред зруйнованого королівства.",h="Глибоко в руїнах Фортеці Стромгард, за каплицею Святилища, у серці кварталу, який досі тримають уцілілі...",kw={"склеп","фортеця стромгард","торас троллбейн","ґален троллбейн","трол'калар","стромґард"},ang={["faction:Alliance"]="Королівський склеп Стромґарда — один з останніх оплотів спадщини Альянсу в Аратійському нагір'ї, який уперто боронять від розбійників, огрів і Орди.",["race:Human"]="Для людей Альянсу гробниця — свідок трагічного занепаду Стромґарда, одного із семи великих королівств, і священна могила одного з найзапекліших воєначальників Альянсу."},sec={{t="Гробниця Тораса Троллбейна",b="Цей підземний склеп, захований під Святилищем Фортеці Стромгард, — місце останнього спочинку короля Тораса Троллбейна, короля-воїна, що провів Стромґард крізь Другу війну. Попри руїну, що поглинула місто, поділене між розбійниками Синдикату й ограми Каменекулаків, уцілілі ополченці Стромґарда завзято тримають цей квартал. Принц Ґален Троллбейн особисто стереже склепи разом із відданими королівськими доглядачами, щоб ні тіла, ні спадщини його батька не потривожили мародери й вороги ззовні."},{t="Сховище Трол'калара",b="Склеп не лише прихищає королівських мерців — він береже й цінні артефакти роду Троллбейнів. Найголовніша з цих реліквій — Трол'калар, прадавній дворучний меч із рунами, викуваний століття тому, щоб убивати тролів. Палату та її скарби довірено під присягу таким доглядачам, як Аларік, Невлін і Вестон, і їх убезпечують потужні засоби захисту. Ґален і його прибічники невтомно стережуть гробницю, добре знаючи, що ворожі фракції й тролі по всьому нагір'ю жадають прадавньої сили цього клинка."}},faq={{q="Хто похований у склепі?",a="Тут спочиває Король Торас Троллбейн, покійний правитель Стромґарда. Його син, Принц Ґален Троллбейн, стереже гробницю серед зруйнованого міста.",al={"хто похований у склепі","чия це гробниця","гробниця склепу"}},{q="Що таке Трол'калар?",a="Трол'калар — давній родовий клинок Троллбейнів. Його назва давньою мовою означає «вбивця тролів», і викували його для боротьби з лісовими тролями Аратійської Улоговини.",al={"трол'калар меч","меч трол'калар","що таке трол'калар"}},{q="Хто стереже склеп?",a="Склеп боронять Принц Ґален Троллбейн і королівські доглядачі Стромґарда, зокрема Аларік, Невлін і Вестон. Вони захищають поховальну залу від злодіїв Синдикату й огрів Каменекулаків, що насідають довкола.",al={"охорона склепу","хто обороняє склеп","доглядачі"}},{q="Де склеп?",a="Він у Фортеці Стромгард на Аратійському нагір'ї, глибоко в кварталі Святилища позаду замкової каплиці, у частині, яку досі тримають вірні Стромґардові.",al={"де склеп","як знайти склеп","де склеп стромґарду"}}},fp="23,394,28.570.0,23.518.0,27.153.0,19.219.0,21.212.0,27.176.0"}
P.entries["subzone:crystal-shore"] = {n="Кришталевий Берег",s="Кришталевий Берег — смуга піщаного узбережжя на південно-східному краю Долини Стренглторну, яку омивають хвилі Південних Морів. Пляж захований під стрімкими прибережними кручами, трохи на південь від прадавніх Руїн Абораза й навпроти Острова Ягуеро за протокою.",h="Кришталевий Берег — смуга піщаного узбережжя на південно-східному краю Долини Стренглторну, яку омивають...",kw={"кришталевий берег","узбережжя","пляж","долина стренглторну","південні моря","острів ягуеро"},sec={{t="Відлюдна прибережна смуга",b="Кришталевий Берег тягнеться південно-східною околицею Долини Стренглторну й стає природною межею між густими тропічними нетрями та відкритими водами Південних Морів. Від джунглів углибині суходолу пляж відгороджують стрімкі пасма, тож мандрівникам, які хочуть пробратися між узбережжям і глибшою дичиною Імлистої Долини, лишається лише кілька суворих перевалів. На півночі розсипаються тролячі споруди Руїн Абораза, а вздовж південних вигинів мису тягнеться Дикий Берег. Через своє розташування це тихий, продутий вітрами край, далекий від гамірних доків Буті Бею."}},faq={{q="Де Кришталевий Берег?",a="Кришталевий Берег — на крайньому південно-східному узбережжі Долини Стренглторну. Він тягнеться вздовж вод Південних Морів, на південь від Руїн Абораза й на північний схід від Дикого Берега.",al={"де кришталевий берег","розташування кришталевого берега","кришталевий берег на мапі"}},{q="Як дістатися до Кришталевого Берега з глибини суходолу?",a="Пляж від материкових джунглів відділяє крутий хребет. Утім, крізь високі скелі пролягають кілька вузьких природних проходів, зокрема стежка просто до Імлистої Долини.",al={"як дістатися до кришталевого берега","шлях до кришталевого берега","дійти до кришталевого берега"}},{q="Які помітні місця поблизу?",a="Трохи на північ від берега стоять давні Руїни Абораза, а через протоку на південний захід — Острів Ягуеро. Далі на південь уздовж узбережжя лежить Дикий Берег.",al={"помітні місця біля кришталевого берега","що поруч із кришталевим берегом"}},{q="Чи заселила Кришталевий Берег якась фракція?",a="Жодна фракція не має на Кришталевому Березі містечка чи поселення. Це дика смуга пляжу, де панують місцеві звірі, на півночі — давні тролячі руїни, а береги б'ють хвилі Південних Морів.",al={"хто живе на кришталевому березі","поселення на кришталевому березі","містечка кришталевого берега"}}},fp="13,270,24.627.0,35.208.0,48.186.0,26.187.0,44.218.0"}
P.entries["subzone:crystal-vale"] = {n="Кришталева Долина",s="Кришталева Долина, захована в далекому північно-західному кутку Силітусу, — віддалений каньйон, де панують зубчасті мінеральні шпилі та вирують стихійні сили. Її скелястими рівнинами бродять елементалі землі й повітря, що стережуть багаті рудні жили. А ще це місце могутньої магії виклику, тісно пов'язане з прадавніми володарями стихій.",h="Кришталева Долина, захована в далекому північно-західному кутку Силітусу, — віддалений каньйон, де панують...",kw={"кришталева долина","силітус","елементалі","торій","тандераан","демітріан"},ang={["class:Shaman"]="Неприборкане тертя між духами землі й повітря тут — разюче нагадування про нестримний хаос свавільних елементалів по всьому Силітусу.",["profession:Mining"]="Скелясті краї й стіни каньйону Кришталевої Долини славляться цінними жилами багатого торію, тож для досвідчених гірників це прибуткове, хоч і небезпечне місце."},sec={{t="Де сходяться камінь і вітер",b="Кришталева Долина вирізняється серед голих пустельних пісків південного Силітусу. Улоговину, оточену стрімкими урвищами, наповнюють мерехтливі кристалічні утворення, мандрівні елементалі землі й ревучі вихори живого повітря. Багаті поклади торію часом приваблюють сміливих рудошукачів, проте спокою в долині немає. Тутешні стихійні істоти споконвіку ворожі до чужинців і стережуть край, що ніби просякнутий первісними чварами прадавнього Азероту."},{t="Сон Шукача Вітру",b="Окрім мінералів і місцевих духів, Кришталева Долина має глибоке значення для прадавніх стихійних сил. Саме тут перебуває Верховний Лорд Демітріан, що береже таємниці принца Тандераана, Шукача Вітру. Тих, хто збере розірвані стихійні пута полеглого принца й найрідкісніші ковані метали, спрямовують у цю долину: тут ув'язненого володаря повітря можна виманити з його пут і викликати на відкритий бій."}},faq={{q="Де Кришталева Долина?",a="Кришталева Долина — на крайньому північному заході Силітусу, біля гірського обрамлення, що межує з пустелею.",al={"де кришталева долина","кришталева долина на мапі","розташування кришталевої долини"}},{q="Які істоти живуть у цій долині?",a="Каньйон населяють здебільшого агресивні повітряні й земляні елементалі, що ширяють і тупотять довкола мінеральних виступів.",al={"істоти кришталевої долини","хто живе в кришталевій долині","елементалі кришталевої долини"}},{q="Хто такий Верховний Лорд Демітріан і чому він тут?",a="Верховний Лорд Демітріан — самотній відлюдник, що живе в долині й має глибокі знання про принца Тандераана. Він допомагає звитяжцям, здатним знову з'єднати Пута Шукача Вітру, щоб закликати принца стихій.",al={"хто такий демітріан","верховний лорд демітріан кришталева долина","де демітріан"}},{q="Що таке Сплюндрований Сутінковий Табір?",a="Це рештки табору Молота Присмерку в долині, який розгромили й рознесли люті стихійні мешканці, що вважають каньйон своїм.",al={"сплюндрований сутінковий табір кришталева долина","сутінковий табір у долині","зруйнований сутінковий табір"}}},fp="12,325,30.472.0,29.437.1,34.134.0,35.122.0,45.208.0,34.148.0"}
P.entries["subzone:crystalvein-mine"] = {n="Шахта Кришталевої Жили",s="Шахта Кришталевої Жили — печера в центральній частині Долини Стренглторну, неподалік прадавніх руїн Зул'Мамве. Печера багата на цінні «Співочі кристали», але агресивні місцеві василіски цілком захопили це місце й обертають на камінь кожного, хто приходить сюди по руду.",h="Шахта Кришталевої Жили — печера в центральній частині Долини Стренглторну, неподалік прадавніх руїн Зул'Мамве.",kw={"шахта кришталевої жили","співочі кристали","василіски","венчурна компанія","печера","долина стренглторну"},ang={["profession:Mining"]="Гірники, яких вабить обіцянка Співочих кристалів, мусять бути обережними: через місцевих василісків пошуки руди тут — одна з найнебезпечніших справ у Стренглторні."},sec={{t="Вигідна пастка",b="Шахта Кришталевої Жили, захована серед порослих джунглями пагорбів біля Зул'Мамве, славиться рідкісними покладами Співочих кристалів — особливого мінералу, за який добре платять у південних торгових портах. Спокушена обіцянкою величезних прибутків, Венчурна Компанія задумала видобувати ці жили. Проте природні мешканці шахти виявилися для справи справжньою катастрофою. Місцеві василіски поїдають дивні кристали, від чого їхня луска твердне, а самі вони стають неприродно смертоносними. Біля входу до печери стоять скам'янілі статуї тролів і людей — мовчазне свідчення провалених експедицій Венчурної Компанії."}},faq={{q="Чим цінна Шахта Кришталевої Жили?",a="У шахті — поклади рідкісних Співочих Кристалів, прибуткового мінералу, що трапляється лише в Долині Стренглторну. Гобліни на кшталт Кренка Фіззлбаба цінують їх за звучання й грошову вартість, тож шукачі ризикують спускатися в небезпечні печери.",al={"чому цінна шахта кришталевої жили","що в шахті кришталевої жили","співучі кристали"}},{q="Чому біля шахти стоять кам'яні статуї?",a="Статуї — скам'янілі рештки нещасних місцевих тролів і робітників Венчурної Компанії. Василіски, що тут живуть, живляться дзвінкими кристалами, зміцнюючи свою кам'яну шкуру, і перетворюють на камінь кожного, хто необачно зайде на їхні пасовиська.",al={"скам'яніли люди кришталева жила","кристалізовані тролі","кам'яні тіла стренґлторн"}},{q="Хто нині контролює Шахту Кришталевої Жили?",a="Венчурна Компанія заявила права на розробку печери, але насправді її не тримає. Василісків так багато, що гоблінам так і не вдалося почати видобуток у глибинах.",al={"хто володіє кришталевою жилою","фракція кришталевої жили","венчур ко кришталева жила"}}},fp="16,265,16.596.0,37.239.0,45.252.0,40.224.0"}
P.entries["subzone:cut-throat-alley"] = {n="Провулок Горлорізів",s="Провулок Горлорізів — відлюдний, безлюдний закуток Стормвінда, захований за крамницями над каналом. Схований за крамничкою «Тіньова Леді» біля межі Дворфійського Кварталу, він складається з тихого дворика й порожнього будинку, відрізаних від звичайних потоків перехожих.",h="Провулок Горлорізів — відлюдний, безлюдний закуток Стормвінда, захований за крамницями над каналом.",kw={"провулок горлорізів","стормвінд","схованка","розбійники","тіньова леді"},ang={["class:Rogue"]="До цього глухого кута, куди не заходять патрулі, можна потрапити лише крізь задні двері сумнівної крамниці над каналом, тож це ідеальна схованка для кожного, хто волів би не потрапляти на очі Міській Варті Стормвінда."},sec={{t="Відлюдний закуток",b="Провулок Горлорізів — один із найтихіших і найпотаємніших куточків Стормвінда. Хоча на мапах його й позначають разом із Дворфійським Кварталом, від гуркоту горнів і густої кіптяви кварталу тут немає нічого. До провулка не дістатися з жодної головної вулиці міста: єдина стежка веде просто крізь «Тіньову Леді» — невелику крамницю над каналом трохи на південь від мосту з Соборної Площі. За дверима крамниці — маленький брукований глухий кут зі штабелями ящиків, забутими бочками й одним порожнім двоповерховим будинком. Цілковито прихований від вартових і звичайних містян, він стоїть у повній тиші посеред гамору столиці."}},faq={{q="Як дістатися до Провулка Горлорізів?",a="Ідіть до набережної каналу на краю Дворфійського Кварталу, трохи на південь від пішохідного мосту до Соборної Площі. Шукайте крамничку «Сумнівна Леді». Пройшовши крізь задню частину цього закладу, ви опинитеся просто в схованому провулку.",al={"знайти провулок горлорізів","де провулок горлорізів","як зайти в провулок горлорізів","вхід у провулок горлорізів"}},{q="Чому на мапі це Дворфійський Квартал?",a="На звичайних мапах цей прохід просто неба позначено загальною назвою Дворфійського Кварталу. Назва «Провулок Горлорізів» з'являється на компасі лише тоді, коли ви заходите в порожній двоповерховий будинок у глибині ділянки.",al={"мінімапа дворфійський квартал","чому написано дворфійський квартал","помилка в назві провулка горлорізів"}},{q="Чи живе хтось у Провулку Горлорізів?",a="Ні. Провулок і його єдиний двоповерховий будинок цілком покинуті. Окрім складених вантажних ящиків і порожніх бочок, тут немає ні мешканців, ні крамарів, ні міських вартових.",al={"нпс провулка горлорізів","хто живе в провулку горлорізів","порожній будинок провулок горлорізів"}},{q="Чи є завдання в Провулку Горлорізів?",a="Жодні офіційні доручення чи міські справи не ведуть до провулка. Це просто непомітне, відлюдне тло в столиці.",al={"завдання провулка горлорізів","сюжет провулка горлорізів"}}},fp="16,287,15.663.0,35.264.0,48.219.0,37.189.0,41.146.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="Хутір Дабірі",s="Хутір Дабірі — сільська садиба на півночі Аратійського нагір'я, що тримає бік Альянсу. У краю, який розтрощила Третя війна й заполонили розбійники Синдикату та тролі-Сухокори, цей маєток лишається впертим оплотом мешканців Стромґарда на чолі з Кенатою Дабірі.",h="Хутір Дабірі — сільська садиба на півночі Аратійського нагір'я, що тримає бік Альянсу.",kw={"хутір дабірі","кената дабірі","ґенаві келлоу","стромґард","відступники","аратійське нагір'я"},ang={["faction:Alliance"]="Для мандрівників Альянсу хутір — рідкісне й утішне нагадування, що люди Стромґарда досі живуть і борються за свою землю, хоч вороги й підступають дедалі ближче.",["race:Undead"]="Для Відступників заможна садиба — дратівливе видовище: живі люди збирають добро, награбоване в родин, що загинули в Третю війну."},sec={{t="Оплот серед нагір'я",b="Хутір Дабірі, що розкинувся на північних полях Аратійського нагір'я, — одне з небагатьох людських господарств, які ще живуть у розколотому королівстві Стромґард. Ним володіє Кената Дабірі, що порає землю разом із синами Фарделом і Марселем, а боронить садибу родинне ополчення. Довкола — хижі звірі, нахабні розбійники й Відступники, що отаборилися на півночі, тож хутір став символом людської витривалості в зруйнованому краї."},{t="Запекла ворожнеча",b="Вижити в цьому нагір'ї рідко вдається, не наживши запеклих ворогів. Садиба накликала на себе люту ненависть Відступників, а надто Ґенаві Келлоу — колишньої шляхтянки, що втратила землі й рідних у Третю війну. Келлоу звинувачує вцілілу родину Дабірі в тому, що серед хаосу чуми вони пограбували дорогоцінні реліквії її роду, — і тепер скромний хутір став мішенню для мстивих найманців Орди, охочих звести давні північні рахунки."}},faq={{q="Хто живе на Хуторі Дабірі?",a="Хутір — дім Кенати Дабірі та її синів, Фарделя й Марселя. Це люди, піддані Стромґарда, вірні Альянсу, і їх захищає присягле місцеве ополчення.",al={"чий хутір дабірі","родина дабірі","кената дабірі"}},{q="Чому Орда б'є по цьому хуторі?",a="Жінка з Відступників на ім'я Ґенаві Келлоу затаїла образу на Дабірі. Вона стверджує, що вони пограбували маєток її родини й забрали вцілілі родинні реліквії, поки її рідні гинули в Третій війні.",al={"чому вбити дабірі","завдання женаві келлоу","завдання орди дабірі"}},{q="Чи Хутір Дабірі належить Стромґардові?",a="Так. Дабірі вважають себе підданими королівства Стромґард і союзниками всього Альянсу й тримаються, попри падіння їхньої столиці на півдні.",al={"чи дабірі альянс","ферма стромґарду"}},{q="Які загрози оточують хутір?",a="Хутір небезпечно близько до ворожих хижаків нагір'я, мандрівних горлорізів Синдикату й сил Відступників, що тиснуть через кордони з півночі.",al={"загрози дабірі","небезпека біля хутора дабірі"}}},fp="19,277,26.482.0,12.437.1,33.168.0,37.215.0,42.184.0,36.162.0"}
P.entries["subzone:dagger-hills"] = {n="Кинджальні Пагорби",s="Кинджальні Пагорби — скелястий кряж, що здіймається на півдні Вестфолу просто за сплюндрованим містечком Мунбрук. Давно занедбане короною, це кам'янисте нагір'я стало ворожим сховком для головорізів, розбійників і повзучих жахів, що загрожують довколишнім рівнинам.",h="Кинджальні Пагорби — скелястий кряж, що здіймається на півдні Вестфолу просто за сплюндрованим містечком...",kw={"кинджальні пагорби","вестфол","дефіас","лепрітус","ґрімбуз тандербрю","мунбрук"},ang={["faction:Alliance"]="Пагорби уособлюють цілковитий крах закону на півдні Вестфолу, де Народне ополчення Ґраяна Стаутмантла мусить відвойовувати землю, покинуту Стормвіндом.",["race:Dwarf"]="Самотній Ґрімбуз Тандербрю на цьому відкритому кряжі показує неймовірну впертість дворфійських пивоварів, що шукають тихого місця, аби вдосконалювати своє ремесло."},sec={{t="Розбійницький притулок",b="Здіймаючись високо над напіврозваленим Мунбруком, Кинджальні Пагорби позначають зубчастий південний край Вестфолу. Позбавлене королівських патрулів зі Стормвінда, це посушливе нагір'я стало природною фортецею для Братства Дефіас. Кастетники, нишпорки й грабіжники з великої дороги чаяться серед скелястих гребенів і чагарників, нападаючи на необачних мандрівників і стережучи підступи до своїх сховків унизу."},{t="Тіні на кряжі",b="Окрім смертних розбійників, Кинджальні Пагорби мають моторошну славу після заходу сонця. Тривожна примара — блукаючий гуль Лепрітус — никає спустілими висотами, щойно сонце сідає. Крім розбійників і неупокоєних мерців, єдиний, хто наважується жити на кряжі, — Ґрімбуз Тандербрю, дворф-пивовар, що поставив свою перегінну апаратуру посеред дикої місцевості, не зважаючи на небезпеки довкола."}},faq={{q="Де Кинджальні Пагорби?",a="Кинджальні Пагорби — висока скеляста південна межа Вестфолу, просто за покинутим поселенням Мунбрук.",al={"де кинджальні пагорби","розташування кинджальних пагорбів","як дістатися до кинджальних пагорбів"}},{q="Хто контролює Кинджальні Пагорби?",a="Братство Дефіас міцно засіло на хребті, розставивши розбійників із великої дороги, слідопитів і кастетників стерегти південні пагорби.",al={"кинджальні пагорби дефіас","хто живе в кинджальних пагорбах","вороги в кинджальних пагорбах"}},{q="Чому тут дворф варить ель?",a="Ґрімбуз Тандербрю влаштував свою гуральню на цих самотніх висотах, щоб варити міцні дворфійські напої, не боячись ні розбійників, ні звірів заради доброї випивки.",al={"грімбуз вестфолл","дворф у кинджальних пагорбах","грімбуз громоварів лор"}},{q="Що таке Лепрітус?",a="Лепрітус — горезвісний гуль, що блукає скелями Кинджальних Пагорбів і наводить жах на мандрівників чи розбійників, яким не пощастить натрапити на нього в темряві.",al={"поява лепрітуса","гуль у кинджальних пагорбах","нежить кинджальних пагорбів"}}},fp="12,278,14.431.0,20.444.0,35.130.0,30.151.0,36.172.0,18.160.0"}
P.entries["subzone:dalaran"] = {n="Даларан",s="Даларан колись був сяйливою столицею магократії Кірін-Тору на південному березі Озера Лордамер. У Третю війну його зруйнували Погибель і демонічний володар Архімонд; тепер уцілілі маги відбудовують місто, а захисний фіолетовий щит зняли ще на початку відбудови.",h="Даларан колись був сяйливою столицею магократії Кірін-Тору на південному березі Озера Лордамер.",kw={"даларан","кірін-тор","фіолетова цитадель","рада шести","архімонд","третя війна","маги"},ang={["class:Mage"]="Даларан — історична колиска людського й високоельфійського чарівництва. Легендарні шпилі, які досі відбудовують, — сумне нагадування про страшні втрати, яких маги зазнали в Третю війну.",["faction:Alliance"]="Даларан був одним із семи королівств — засновників першого Альянсу Лордерону, і нині Кірін-Тор відбудовує свою спустошену столицю."},sec={{t="Падіння магократії",b="Даларан заснували після давніх Тролячих воєн чародії імперії Аратор, і століттями він був головним притулком людства для вивчення тайної магії. Під проводом Ради Шести Кірін-Тор зібрав величезні магічні архіви й беріг могутні артефакти у Фіолетовій Цитаделі. Та доба розквіту раптово скінчилася в Третю війну. Принц-зрадник Артас провів Погибель крізь міську браму, щоб заволодіти Книгою Медіва, а невдовзі демонічний володар Архімонд обернув високі шпилі Даларану на руїну."},{t="Відбудова магократії",b="In the aftermath of the Legion's defeat, the surviving wizards of the Kirin Tor returned to their devastated homeland. Refusing to surrender their ancestral ground to the Scourge or scavengers, they erected an impassable, shimmering violet barrier over the city's heart. The shield has since been removed, though reconstruction continues. The magi continue rebuilding their fallen sanctuary, and Archmage Ansirem Runeweaver can be found in the Violet Citadel."}},faq={{q="Що сталося із захисним щитом Даларана?",a="The Kirin Tor erected a magical shield over Dalaran after its destruction in the Third War. The shield has since been removed, and the city is still being rebuilt.",al={"фіолетова бульбашка","фіолетовий щит альтерак","що це за купол","купол даларана"}},{q="Чи можуть гравці зайти в Даларан?",a="Yes. Dalaran is accessible while reconstruction is still underway. Archmage Ansirem Runeweaver resides in the Violet Citadel.",al={"чи можна зайти в даларан","як потрапити в даларан","пройти крізь щит даларана"}},{q="Хто зруйнував Даларан?",a="На Даларан напали принц Артас і його армія Погибелі, що викрали з його сховищ Книгу Медіва. Невдовзі владика демонів Архімонд закликав темні чари й стер місто на руїни.",al={"як упав даларан","хто підірвав даларан","чому даларан у руїнах"}},{q="Хто править Далараном?",a="Містом керує Кірін-Тор — елітний орден магів, що править через збори, відомі як Рада Шести.",al={"хто керує далараном","керівництво даларана","хто очолює кірін-тор"}}},fp="7,308,21.539.0,24.459.0,43.163.0,26.125.0,22.202.0,18.118.0"}
P.entries["subzone:dalson-s-tears"] = {n="Сльози Далсона",s="Сльози Далсона — спустошена чумою ферма в самому серці Західних Чумних Земель. Колись вона звалася Садом Далсона, але під час Третьої війни її захопили й перетворили на плацдарм для одного зі смердючих чумних казанів Погибелі. Неупокоєні рештки колишніх власників досі блукають полями й господарськими будівлями.",h="Сльози Далсона — спустошена чумою ферма в самому серці Західних Чумних Земель.",kw={"сльози далсона","ферма","чумний казан","малвініус","фермер далсон","західні чумні землі"},ang={["class:Paladin"]="Осквернені поля й змучені душі родини Далсонів показують, яке зло досі гніздиться в Лордероні, — те зло, яке святі воїни Світла присягнули викорінити."},sec={{t="Отруєний урожай",b="До Третьої війни цей маєток процвітав як Сад Далсона — щедра ферма в житниці Лордерону. Нині поля задихаються від гнилі, а саму місцину перейменували на Сльози Далсона. Посеред зруйнованого господарства стоїть величезний залізний казан, що безупинно випускає над краєм отруйні зелені чумні випари. Наглядає за ним Володар Казана Малвініус, а боронить зграя заражених зомбі, гнилих трупів і кістяних жахіть на службі Короля-Ліча."},{t="Доля Далсонів",b="Перших господарів ферми спіткав трагічний кінець, коли краєм пронеслася чума, — та смерть не принесла їм звільнення. Пані Далсон блукає отруєною землею безтямним скелетом, стискаючи ключ від надвірної вбиральні. А в тій хатинці ховається жахливий гуль, що колись був самим Фермером Далсоном: його замкнула там зневірена дружина, перш ніж обоє остаточно піддалися прокляттю Погибелі."}},faq={{q="Як звалися Сльози Далсона до чуми?",a="До того як Третя війна спустошила Лордерон, це було заможне господарство, відоме як Сад Далсона.",al={"сад далсона","первісна назва","як звалася ця ферма"}},{q="Чому посеред ферми величезний казан?",a="Погибель поставила на полях Лордерона величезні чумні казани, у яких безупинно кипить згубна отрута. Їхні випари розносяться краєм, отруюючи землю й воду та псуючи кожну живу істоту, яка їх вдихне.",al={"казан далсона","зелений дим із казана","чому тут казан"}},{q="Хто стереже казан у Сльозах Далсона?",a="Чумний казан стереже Володар Казана Малвініус — командир-нежить на службі Погибелі — у супроводі орд отруєних зомбі, кістяних жахіть і гниючих трупів.",al={"володар казана","хто тут бос","володар казана мальвініус"}},{q="What is known about the locked outhouse?",a="The locked outhouse is part of the abandoned farm. Mrs. Dalson's diary offers clues for anyone investigating what happened to the family.",al={"чудовисько у вбиральні","хто у вбиральні","фермер далсон"}}},fp="14,329,18.487.0,23.399.1,49.118.0,56.245.0,42.181.0,40.137.1"}
P.entries["subzone:dandred-s-fold"] = {n="Кошара Дандреда",s="Кошара Дандреда — відлюдний хутір із садибою на туманному північно-західному березі Озера Лордамер у Горах Альтерак. Тепер її захопив Синдикат, і вона правує за надійну схованку для Лорда Алідена Перенольда та його спільників. І Орда, і Альянс пильно стежать за цим маєтком над озером — кожна сторона зі своїх причин.",h="Кошара Дандреда — відлюдний хутір із садибою на туманному північно-західному березі Озера Лордамер у Горах...",kw={"кошара дандреда","синдикат","перенольд","озеро лордамер","наґаз","слід аргуса","тарета"},ang={["faction:Alliance"]="Альянс не може змиритися із союзом людських розбійників і демонічного Сліду Аргуса, тож Магістрат Генрі Малеб наказує завдавати по маєтку точкових ударів.",["faction:Horde"]="Для Орди проникнути в Кошару Дандреда — справа особиста. Вождь Тралл прагне повернути намисто Тарети Фокстон."},sec={{t="Шляхетний прихисток у руках розбійників",b="Кошара Дандреда стоїть на західному краю Узвишшя й має власний вихід до вод Озера Лордамер. Колись це був тихий заміський маєток — імовірно, ним володів альтерацький шляхтич на ім'я Дандред. Коли королівство впало, маєток обернувся на укріплений анклав Синдикату. Тепер його огорожі й пристані патрулюють убивці та громили Синдикату, ховаючи занепалу знать від очей влади Саутшора й Відступників з іншого берега озера."},{t="Осередок інтриг",b="За зачиненими дверима садиби визрівають небезпечні змови. Лорд Аліден Перенольд, визнаний ватажок Синдикату, тримає в Кошарі Дандреда свій штаб разом із коханкою Елісою. Та розбійники тут не самі: в садибі закріпився й свавільний орк із Ради Тіней на ім'я Наґаз зі Сліду Аргуса, що укладає темні угоди з людськими розбійниками. Через цей небезпечний союз Кошара Дандреда стала мішенню і для магістратів Саутшора, і для героїв Орди."}},faq={{q="Хто контролює Кошару Дандреда?",a="Маєток захопив Синдикат — шляхетна злочинна мережа на чолі з поваленою знаттю Альтерака. Убивці й громили Синдикату стережуть садибу, служачи Лордові Алідену Перенольду.",al={"хто в кошарі дандреда","хто живе в кошарі дандреда","вороги кошари дандреда"}},{q="Чому Орду цікавить цей маєток?",a="Орда б'є по садибі, щоб убити Лорда Алідена Перенольда й повернути вкрадену пам'ятку — родинне намисто, що колись належало Тареті Фокстон, рятівниці й довіреній подрузі Тралла з дитячих років.",al={"орда кошара дандреда","чому орда іде до кошари дандреда"}},{q="Чому Альянс посилає сюди шукачів пригод?",a="Магістрат Генрі Малеб із Саутшора посилає сюди агентів Альянсу знищити Наґаза — небезпечного члена культу Слід Аргуса, що змовився з розбійниками Синдикату.",al={"альянс кошара дандреда","завдання магістрата малеба кошара дандреда"}},{q="Хто такий Дандред?",a="Хто такий Дандред, ніде не записано. Маєток носить його ім'я, але жодна певна розповідь не називає його першого власника.",al={"хто такий дандред","дандред лор"}}},fp="14,352,36.473.0,20.477.1,28.201.0,42.198.0,44.172.0,16.121.0"}
P.entries["subzone:dark-portal"] = {n="Темний Портал",s="Темний Портал — велетенська кам'яна брама на південному краю Спустошених Земель. Уперше її відчинили об'єднані чари Медіва й Ґул'дана, і саме крізь цей фатальний прохід Стара Орда прийшла в Азерот і розв'язала Першу війну.",h="Темний Портал — велетенська кам'яна брама на південному краю Спустошених Земель.",kw={"темний портал","спустошені землі","медів","ґул'дан","стара орда","перша війна","дренор"},ang={["faction:Alliance"]="Для Альянсу портал — скорботний пам'ятник Першій війні й падінню давнього Стормвінда, тож маги Незерґарда мусять безупинно нести тут варту.",["race:Orc"]="Портал — болісний поріг минулого вашого народу: брама, крізь яку Стара Орда, поневолена демонічними господарями, рушила на війну, покинувши рідну землю предків."},sec={{t="Розрив між світами",b="До відкриття Порталу цей край був частиною Чорної Трясовини — болотистої низини, що простягалася на півдні. Усе змінилося, коли Медів, одержимий Саргерасом, поєднав свою магію Стража Тірісфалю з чаклунством Скверни, яке творив Ґул'дан на Дренорі. Ритуал забрав незліченні життя й розірвав саму тканину реальності. Стара Орда звела масивні кам'яні споруди, щоб закріпити розрив, і повела крізь його поріг армії, що розгромили Королівство Стормвінд у Першій війні. Випромінювання Скверни від порталу докорінно спотворило довколишню землю й перетворило буйні болота на червоні скам'янілі пустирі, які ми бачимо нині."},{t="Приспана пильність",b="Після перемоги Альянсу Лордерону в Другій війні архімаг Хадґар могутніми чарами зруйнував кам'яну раму порталу, сподіваючись назавжди відрізати Дренор. Проте міжвимірний розрив під нею виявився практично незнищенним. Альянс звів неподалік Замок Незерґард, щоб пильнувати цей шрам, а демони й рештки Ради Тіней і далі прослизають спустошеною улоговиною. Нині брама стоїть відновлена, але мовчазна — тихий шрам між світами, який жодна сторона не наважується залишити без нагляду."}},faq={{q="Чи можна зараз пройти крізь Темний Портал?",a="Ні. Кам'яна рама брами стоїть ціла, але розрив у ній приспаний. Наразі жоден мандрівник не може переступити поріг.",al={"чи можна зайти в темний портал","чи відкритий темний портал","портал в аутленд"}},{q="Хто збудував Темний Портал?",a="Його створили спільним обрядом людина-Вартовий Медів на Азероті й чорнокнижник Ґул'дан на вмирущому світі Дренор, розпочавши вторгнення, з якого спалахнула Перша війна.",al={"хто створив темний портал","медів ґулдан портал","творці темного порталу"}},{q="Чому за ним стежить Замок Незерґард?",a="Після того як Архімаг Хадґар зруйнував першу раму порталу після Другої війни, він переконав Альянс пильнувати його руїни. Альянс заснував Замок Незерґард, щоб постійно стежити за цим місцем на випадок, якщо загроза повернеться.",al={"чому тут замок незерґард","незерґард охороняє портал","чому незерґард"}},{q="Чому земля довкола порталу червона й безплідна?",a="Колись Спустошені Землі були родючим болотом — Чорним Багном. Величезна енергія Скверни, потрібна, щоб прорвати реальність, разом зі скверною з Дренору й демонічними звірами отруїли ґрунт і омертвили все живе.",al={"чому спустошені землі мертві","псування порталу","чому спустошені землі червоні"}}},fp="11,264,23.601.0,17.516.0,47.126.0,37.192.0,40.257.0,51.236.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="Шпиль Темної Хмари",s="Шпиль Темної Хмари — укріплене тауренське поселення на кількох з'єднаних між собою столових горах на схід від Великого Підйомника в Тисячі Голок. Цю повітряну твердиню тримає агресивний клан Ґрімтотем, і звідси він сіє в краї безлад і крутить темні справи.",h="Шпиль Темної Хмари — укріплене тауренське поселення на кількох з'єднаних між собою столових горах на схід від...",kw={"шпиль темної хмари","ґрімтотем","арнак ґрімтотем","тисяча голок","таурени","змова"},ang={["faction:Horde"]="Ґрімтотеми, що засіли на цій столовій горі, — вороги: вони загрожують мандрівникам, які прямують від Великого Підйомника вглиб Тисячі Голок.",["race:Tauren"]="Віроломна поведінка Ґрімтотемів на цих столових горах цілковито суперечить єдності та миру, які Кайрн Бладгуф намагається зберегти між племенами."},sec={{t="Твердиня на скелях",b="Шпиль Темної Хмари розкинувся на трьох головних столових горах, з'єднаних мотузяними мостами, і панує над улоговиною каньйону внизу. Дістатися на висоту можна лише крутим природним схилом від дна каньйону через дерев'яні мости або високою переправою біля Рейзорфен Даунс. Із цих обвітрених скель Ґрімтотеми стежать за долиною — у безпеці від випадкових нападів і далеко від решти тауренських племен."},{t="Інтриги на столових горах",b="Поселення, яким керують такі ватажки, як Арнак Ґрімтотем і Гарб Фаулмаунтін, — значно більше, ніж звичайна застава. Таємне листування, знайдене на столовій горі, свідчить, що Ґрімтотеми діють заодно з темними й невідомими силами та плекають задуми, вельми далекі від миру, який уклав Кайрн Бладгуф у Тандер Блафі."}},faq={{q="Хто контролює Шпиль Темної Хмари?",a="Твердиня належить клану Ґрімтотем — агресивному відлюдному угрупованню тауренів, відкрито ворожому до більшості чужинців і глибоко недовірливому до Орди.",al={"хто живе на шпилі темної хмари","власники шпиля темної хмари","хто на шпилі темної хмари"}},{q="Як дістатися до Шпиля Темної Хмари?",a="На шпиль можна піднятися природним схилом на сусіднє плато з дна каньйону й перейти дерев'яними мотузяними мостами або скористатися мостом біля Рейзорфен Даунсу.",al={"як піднятися на шпиль темної хмари","шлях на шпиль темної хмари","вхід на шпиль темної хмари"}},{q="Хто очолює тутешніх Ґрімтотемів?",a="Справами поселення керують помітні постаті Ґрімтотемів, зокрема Арнак Ґрімтотем і Гарб Фаулмаунтін.",al={"ватажки шпиля темної хмари","хто очолює шпиль темної хмари","боси ґрімтотемів"}},{q="Що Ґрімтотеми тут замишляють?",a="Ґрімтотеми на шпилі таємно підтримують зв'язок із невідомою темною силою й прагнуть похмурих цілей, що загрожують спокою Тисячі Голок.",al={"що діється на шпилі темної хмари","змова ґрімтотемів"}}},fp="18,273,21.385.0,20.328.1,32.157.0,36.177.0,29.121.0,37.170.0"}
P.entries["subzone:darkened-bank"] = {n="Темний Берег",s="Темний Берег — північне узбережжя Сутінколісся вздовж річки, що відділяє темний ліс від Лісу Елвінн. Тягнеться він від далекого заходу аж на схід до Гір Редріджу й позначає межу між відносно безпечною північчю та темними жахами лісу.",h="Темний Берег — північне узбережжя Сутінколісся вздовж річки, що відділяє темний ліс від Лісу Елвінн.",kw={"темний берег","річка","ліс елвінн","сутінколісся","свен йорґен"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що вирушають із Лісу Елвінн, Темний Берег — перший перевалочний пункт перед заглибленням у примарне серце Сутінколісся."},sec={{t="Хистка межа",b="Темний Берег пролягає південним берегом річки навпроти Лісу Елвінн і утворює північний край Сутінколісся. Він тягнеться від західних закрутів річки на схід, до кам'яного мосту, що веде до Гір Редріджу. Хоч під проклятою завісою крон Сутінколісся тут і похмуро, цей берег часто стає першим прихистком для мандрівників, що вирушають на південь з Елвінна. Біля його західного краю стоїть тимчасовий табір, де знайшли притулок біженці, серед них Свен Йорґен і Ларс, — ледь-ледь за межами лісової гущавини."}},faq={{q="Де Темний Берег?",a="Темний Берег тягнеться вздовж усього північного берега річки в Сутінколіссі, просто навпроти Лісу Елвінн. Він сягає від крайніх західних околиць краю на схід аж до мосту, що веде в Гори Редріджу.",al={"де темний берег","розташування темного берега","темний берег сутінколісся"}},{q="Хто живе на Темному Березі?",a="На крайньому західному краю берега стоїть скромний табір утікачів, де живуть Свен Йорґен і Ларс. Вигнані зі свого колишнього життя глибше в краї, вони мають цей північний берег за хиткий прихисток і шукають допомоги проти загроз Сутінколісся.",al={"табір на темному березі","хто на темному березі","нпс темного берега"}},{q="Як мандрівники зазвичай сюди добираються?",a="До західної частини Темного Берега легко дістатися, перепливши річку на південь із південно-західних околиць Лісу Елвінн, або йдучи південним берегом річки на захід від редріджського мосту.",al={"як дістатися до темного берега","дорога до темного берега"}}},fp="13,306,21.557.0,35.242.0,34.259.0,41.220.0"}
P.entries["subzone:darkmist-cavern"] = {n="Печера Темної Імли",s="Печера Темної Імли — покинута шахта в північно-західній частині Багна Пилоброду, геть заполонена хижими велетенськими павуками. Руїни, що розсипаються біля входу, натякають на нещасливе давнє поселення, яке поглинули небезпеки болота. Місцеві досі сперечаються, чи то печера дала назву павукам, чи навпаки.",h="Печера Темної Імли — покинута шахта в північно-західній частині Багна Пилоброду, геть заполонена хижими...",kw={"печера темної імли","багно пилоброду","павуки","шахта","джарл","болотне око"},ang={["profession:Cooking"]="Дивакуватий відлюдник Джарл «Болотне Око» вважає мерзенні очі павуків Темної Імли головним інгредієнтом ситної болотяної юшки, хоча поза болотом мало хто поділяє його смаки.",["profession:Mining"]="Печеру явно видовбали колишні рудокопи, та кожному, хто захоче розвідати її кам'яні глибини, спершу доведеться пробитися крізь полчища павуків, що там гніздяться."},sec={{t="Виводок у шахті",b="Печера Темної Імли в північно-західних закутках Багна Пилоброду, схоже, колись була діючою копальнею. Нині людей тут давно немає: біля входу лишилися гнилі, зруйновані халупи, а тунелі затягнуло густим павутинням. Печеру заполонили павуки Темної Імли — хижі потвори, чия отрута й розміри роблять тунелі смертельними для необачних блукачів. Мешканці болота досі сперечаються, чи печеру назвали на честь мерзенного виводку, що в ній гніздиться, чи павуки взяли назву від самої туманної печери."},{t="Комора відлюдника",b="Попри очевидну небезпеку, печера час від часу приваблює збирачів поживи й дивакуватих болотяних мешканців. Відлюдник Джарл «Болотне Око» славиться тим, що посилає мандрівників углиб павутиння по очі цих жахливих павуків, запевняючи, що з них виходить чудовий бульйон. Окрім таких дивакуватих кулінарних вилазок, більшість розважливих мандрівників тримається подалі від обплутаного павутинням входу."}},faq={{q="Що таке Печера Темної Імли?",a="Це покинута шахта на північному заході Багна Пилоброду, яку цілком захопили велетенські отруйні павуки Темної Імли.",al={"що таке печера темної імли","печера темної імли","печера з павуками пилотрясин"}},{q="Хто жив у руїнах біля печери?",a="Невеликі дерев'яні руїни свідчать, що колись тут було поселення чи табір рудокопів, але хто тут жив — невідомо.",al={"хто тут жив","будинки біля печери темної імли","покинуте село темна імла"}},{q="Навіщо місцеві спускаються в Печеру Темної Імли?",a="Мало хто заходить туди з власної волі, але дивакуватий відлюдник Джарл «Болотяне Око» наймає сміливих шукачів пригод пірнати в тунелі й добувати павучі очі для його дивної болотяної юшки.",al={"навіщо йти в печеру темної імли","завдання печери темної імли"}},{q="Що дістало назву першим — павуки чи печера?",a="Мешканці Багна Пилоброду сперечаються, чи павуків назвали на честь печери, чи печеру на честь павуків. Певної розповіді про те, яка назва з'явилася першою, немає.",al={"звідки назва павуків","чому називається темна імла"}}},fp="15,322,21.557.0,15.381.0,24.155.0,40.125.0,43.179.0,49.182.0"}
P.entries["subzone:darkshire"] = {n="Даркшир",s="Даркшир, колись відомий як Велике Селище, — потерпале поселення на сході Сутінколісся. Огорнуте нескінченним неприродним мороком і занедбане Стормвіндом, містечко тримається лише завдяки пильності Нічної Варти й упертій витривалості своїх мешканців.",h="Даркшир, колись відомий як Велике Селище, — потерпале поселення на сході Сутінколісся.",kw={"даркшир","сутінколісся","нічна варта","великий хутір","місто","медів"},ang={["class:Paladin"]="Мерці повстають на кожному довколишньому цвинтарі, а налякані містяни майже забули Світло, тож святі воїни знайдуть довкола села вдосталь нечестивої скверни для очищення.",["faction:Alliance"]="Даркшир — суворе нагадування про те, що кордони королівства тріщать. Герої Альянсу знайдуть тут вдячних містян, але й відчутну гіркоту щодо байдужої знаті в Стормвінді."},sec={{t="Покинуте місто",b="Колись це було мирне лісове поселення під назвою Велике Селище; під час Першої війни Стара Орда спалила його, а згодом його відбудували. По-справжньому гірко доля повернулася після падіння Медіва в Каражані: його передсмертні корчі прокляли Брайтвуд, і той став темною пущею, яку нині звуть Сутінколіссям. Хоча формально місто належить Королівству Стормвінд, ратуша не отримує від корони майже ніякої допомоги. Політичний параліч у Стормвінді лишив гарнізон без людей, а кордони — без патрулів, тож мер Елло Ебонлок і місцева рада змушені в темряві вершити власне суворе, замкнене в собі правосуддя."},{t="Межа в пітьмі",b="Оточений ходячими мерцями із західних цвинтарів і дикими воргенами, що полюють у лісах, Даркшир чіпляється за життя за своїми частоколами. Головний щит міста — Нічна Варта, добровільне ополчення містян під командою Алтеї Ебонлок. З міської площі ці втомлені вартові вирушають патрулювати непроглядні шляхи, тримають дороги відкритими й відганяють жахи, що никають на узліссі. Мандрівники, що прибувають до Таверни «Багряний Крук», бачать місцевих підозріливими, наляканими й готовими на все заради будь-якого найманця, здатного тримати клинок."}},faq={{q="Чому містечко перейменували з Великого Селища?",a="Спершу поселення звалося Великим Селищем, коли край ще був сонячним лісом Брайтвуд. Після того як Вартовий Медів загинув у сусідньому Каражані, темна магія поповзла лісом, затуляючи сонце й підіймаючи мерців. Коли Брайтвуд занепав і перетворився на Сутінколісся, похмура дійсність проклятого краю спонукала мешканців перейменувати село на Даркшир.",al={"чому називається даркшир","зміна назви великого селища","історія даркшира"}},{q="Чому Стормвінд не допомагає боронити Даркшир?",a="Stormwind withdrew its troops from Duskwood amid political turmoil following King Varian Wrynn's disappearance. The townspeople formed the Night Watch to defend themselves against threats the crown was no longer containing.",al={"де армія стормвінда","чому в сутінколіссі немає вартових","чому стормвінд покинув даркшир"}},{q="Хто очолює Даркшир?",a="Цивільна влада — в руках Лорда Елло Ебонлока й Ради Даркшира, що засідають у ратуші разом із міським писарем Долтрі. Військову оборону очолює донька Елло, Командир Алтея Ебонлок, що командує добровольчим ополченням — Нічною Вартою.",al={"хто головний у даркширі","керівництво даркшира","мер даркшира"}},{q="Що таке Нічна Варта?",a="Нічна Варта — місцеве цивільне ополчення, яке Алтея Ебонлок створила з нужди. Армія Стормвінда не посилає військ до Сутінколісся, тож місцеві взялися за зброю, щоб патрулювати похмурі дороги, стерегти межі й відбивати набіги гулів і навіжених звірів.",al={"що таке нічна варта","вартові даркшира","хто захищає даркшир"}},{q="Хто такий Морган Ладімор?",a="Morgan Ladimore was a veteran who returned after the Third War to find his home ruined and his family missing. His search brought him to Darkshire; local accounts preserve the rest of his story.",al={"морган ладімор історія","ладімор даркшир","хто такий ладімор"}}},fp="9,262,16.635.0,20.574.0,43.376.0,45.223.0,20.268.0,24.277.0,24.194.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Ратуша Даркшира",s="Ратуша Даркшира стоїть на західному краю міської площі й править за осередок місцевої влади в Сутінколіссі. З її тьмяно освітлених зал мер, Лорд Елло Ебонлок, і його рада намагаються керувати поселенням, яке облягають повзуча темрява й потвори нежиті.",h="Ратуша Даркшира стоїть на західному краю міської площі й править за осередок місцевої влади в Сутінколіссі.",kw={"ратуша даркшира","даркшир","елло ебонлок","рада","сутінколісся"},ang={["faction:Alliance"]="Для мандрівників Альянсу ратуша — символ хиткої влади на південних рубежах королівства: вона показує, як тонко розтягнутий захист Стормвінда у відрізаних поселеннях."},sec={{t="Осередок влади Даркшира",b="Ратуша стоїть просто на захід від головної площі, і саме тут збираються міські очільники Даркшира, щоб правити дедалі відрізанішим краєм. У її витертих негодою стінах засідає мер, Лорд Елло Ебонлок, який намагається зберегти лад і захистити людей, поки Стормвінд майже не надає воєнної допомоги. Разом із мером міські урядники на кшталт Писаря Долтрі ведуть місцеві записи й облік мандрівників, що наважуються на небезпечні дороги Сутінколісся, хоча тримати книги в порядку за таких лихих часів — справа похмура й нелегка."}},faq={{q="Хто керує містечком із цієї будівлі?",a="Лорд Елло Ебонлок — Мер Даркширу: він головує в міській раді з Ратуші. Він керує місцевою обороною й просить допомоги в заїжджих шукачів пригод, адже зі столиці королівства підкріплень майже не надходить.",al={"хто мер","хто керує даркширом","хто в ратуші"}},{q="Які записи зберігаються в Ратуші?",a="Писар Долтрі веде міські книги з переліком мешканців і мандрівників, що проходять через Даркшир. Через безлад і часті небезпеки Сутінколісся чимало його записів трохи застаріли.",al={"писар далтрі записи","чим займається далтрі","реєстр містечка"}},{q="Чому Ратуша така важлива для виживання Сутінколісся?",a="Сутінколісся відрізане від прямої військової підтримки Стормвінда, тож Ратуша — робочий осередок Нічної Варти й місцевої влади. Тут рада організовує оборону мирних мешканців і розсилає допомогу похмурим краєм.",al={"чому ратуша важлива","роль ради даркшира"}}},fp="19,278,21.556.0,38.263.0,43.229.0,57.255.0"}
P.entries["subzone:darkspear-strand"] = {n="Побережжя Темного Списа",s="Побережжя Темного Списа — відтинок узбережжя на півдні Дуротару, куди тролів Темного Списа винесло на берег після вигнання з Островів Відлуння. Цей пляж просто поруч із Селом Сен'джин знаменує гіркий початок материкового притулку племені під проводом Вол'джина.",h="Побережжя Темного Списа — відтинок узбережжя на півдні Дуротару, куди тролів Темного Списа винесло на берег...",kw={"побережжя темного списа","пляж","тролі","вигнання","село сен'джин","острови відлуння","дуротар"},ang={["faction:Horde"]="Побережжя позначає південний берег, де Темний Спис закріпився на материку Калімдору поруч зі своїми союзниками-орками після втрати острівного поселення.",["race:Troll"]="Для тролів Темного Списа ступити на цей берег — відчути біль зради Залазана й гірко-солодкий спогад про те, як вони врятувалися живими й заснували Село Сен'джин."},sec={{t="Берег вигнання",b="Коли знахар Залазан збожеволів і захопив владу над Островами Відлуння, уцілілі тролі Темного Списа були змушені залишити свій дім за морем. Зневірені біженці перетнули вузьку протоку й висадилися на цьому вибіленому сонцем узбережжі. Замість розсіятися ворожими червоними пустками Дуротару, вцілілі гуртом збудували Село Сен'джин за кілька кроків від берегової лінії. Нині побережжя лишається тихим нагадуванням про вигнання, дивлячись через прибій на острови, які вони досі сподіваються повернути."}},faq={{q="Що сталося на Побережжі Темного Списа?",a="Саме на цей берег висадилися тролі Темного Спису, утікши з Островів Відлуння. Коли Залазан обернув свою темну магію проти власного народу, уцілілі переправилися через воду, вийшли тут на берег і одразу заснували поруч Село Сен'джин.",al={"чому зветься побережжя темного списа","побережжя темного списа історія","що це за пляж"}},{q="Чому Темний Спис покинув Острови Відлуння?",a="Знахар Залазан зрадив родичів і темним вуду поневолив розум своїх одноплемінників. Вождь Вол'джин вивів з островів незіпсованих тролів Темного Спису, щоб уникнути повного поневолення, і вони висадилися на цьому березі.",al={"чому тролі покинули острови відлуння","залазан вигнання","евакуація островів відлуння"}},{q="Яке поселення поруч із Побережжям Темного Списа?",a="Село Сен'джин стоїть за кілька кроків від пляжу вглиб суходолу. Його заснували втікачі одразу після висадки на берег, і це головна застава й духовний осередок Темного Спису в Дуротарі.",al={"село біля побережжя темного списа","містечко поруч із пляжем","де село сен'джин"}}},fp="16,286,16.539.0,34.270.0,43.233.0,52.206.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="Ущелина Темного Шепоту",s="Ущелина Темного Шепоту — підступний яр у південних висотах Вінтерспрінгу, що аж кишить демонами. Коли наприкінці Третьої війни було знищено Архімонда, рештки розбитого Палаючого Легіону втекли схилами Гори Гіджал і окопалися в цих зубчастих проваллях. Нині тут нишпорять могутні демони, що стережуть давні мінерали й темні реліквії з інших світів.",h="Ущелина Темного Шепоту — підступний яр у південних висотах Вінтерспрінгу, що аж кишить демонами.",kw={"ущелина темного шепоту","демони","леді гедерін","палаючий легіон","справжнє срібло","торій","вінтерспрінг"},ang={["class:Warlock"]="Демони Гедерін, що нишпорять цими печерами, мають при собі важливі складники з інших світів, тож ущелина — головне випробувальне поле для чорнокнижників, які прагнуть опанувати ритуали призову вищих демонів, як-от Вартового загибелі.",["profession:Mining"]="Підступні провалля ховають щедрі поклади справжнього срібла й багаті жили торію — і все це ваше, якщо стане сміливості прокрастися повз елітних демонів."},sec={{t="Плацдарм Легіону серед снігів",b="Після поразки Архімонда на вершині Гори Гіджал уцілілі демони Палаючого Легіону розбіглися по навколишніх гірських хребтах. Дисциплінований авангард сховався в Ущелині Темного Шепоту й перетворив південний кордон Вінтерспрінгу на неприступну твердиню. Тут верховодять демони Гедерін — смертоносні ловці мани, убивці й посвячені, підвладні Леді Гедерін, — і вони люто боронять свої підземні тунелі та вогняні табори. Та не лише елітні мешканці загрожують чужинцям: у найнижчій точці ущелини височіє зловісна запечатана арка — натяк на замкнені проходи, що ведуть вище на священну гору."},{t="Приховані реагенти й рідкісні знання",b="Попри смертельну небезпеку, відчайдушні шукачі пригод і ласі до наживи пройдисвіти вирушають в ущелину по її незвичайні багатства. Яри багаті на цінні руди — справжнє срібло й щільні поклади торію. Глибше, у затінених гротах, животіють дивні мешканці: біс-торговець Ві'ел, що продає просякнуті Скверною реагенти на зразок тканини Скверни та Крові ґрома, і невловимий високий ельф Землекличник Франзал, який зберігає давні металургійні знання про виплавку рідкісного елементію."}},faq={{q="Чому у Вінтерспрінгу стільки демонів?",a="Демони в Ущелині Темного Шепоту — уцілілі після вторгнення Палаючого Легіону на Гору Гіджал у Третій війні. Коли Архімонда вбили біля Світового Дерева, його розбиті сили не загинули цілком, а відступили в ці прірви, щоб перегрупуватися.",al={"чому тут демони","легіон темного шепоту історія","звідки взялися демони"}},{q="Що за запечатана брама в глибині ущелини?",a="У глибині південної частини ущелини стоїть арка з рунами й діючий магічний бар'єр. Вона стереже гірський прохід просто на Гору Гіджал, не пускаючи смертних на священні висоти, поки гора оговтується від демонічної навали.",al={"портал темного шепоту","портал підземелля вінтерспрінг","брама гіджалу"}},{q="Хто очолює тутешніх демонів?",a="У таборі панує секта демонічних загарбників, відома як Гедерін, якою, схоже, командує Леді Гедерін. Ущелинами патрулюють їхні вбивці, послушники й люті гончаки — манаскрадачі.",al={"бос темного шепоту","ватажок гедеринів","хто править темним шепотом"}},{q="Навіщо шукачеві пригод іти в Ущелину Темного Шепоту?",a="Місцина надзвичайно небезпечна, і безпечно пройти її можна лише злагодженим загоном. Проте вона приваблює чорнокнижників, що шукають позасвітових уз, жерців, що полюють на рідкісне Око Тіні, ковалів і рудокопів, що шукають багаті жили торію, і вчених, що шукають прихованого Землекличника Франзала.",al={"навіщо йти в темний шепіт","завдання темного шепоту","нагороди темного шепоту"}}},fp="17,388,29.628.0,34.498.0,45.261.0,49.257.0,26.211.0,55.285.0"}
P.entries["subzone:darnassus"] = {n="Дарнасус",s="Високо серед розлогого гілля Тельдрассила стоїть Дарнасус — столичний прихисток калдорей. Зведений уздовж тихих вод і зелених гаїв, він є духовним серцем нічних ельфів і головним бастіоном Альянсу на півночі Калімдору. Звідси Верховна Жриця Тіранда Віспервінд та Архідруїд Фандрал Стаґгелм ведуть свій народ крізь випробування новознайденої смертності.",h="Високо серед розлогого гілля Тельдрассила стоїть Дарнасус — столичний прихисток калдорей.",kw={"дарнасус","столиця","нічні ельфи","тіранда віспервінд","фандрал стаґгелм","храм місяця","тельдрассил"},ang={["faction:Alliance"]="Для мандрівників зі Східних Королівств Дарнасус — відлюдна, безтурботна гавань, що є неодмінним якорем Альянсу на континенті Калімдор.",["race:NightElf"]="Дарнасус — культурна й політична столиця калдорей, новий початок вашого народу й суверенний прихисток після тяжких жертв Третьої війни."},sec={{t="Прихисток у гіллі",b="Збудований після Третьої війни, Дарнасус був заснований на честь виживання народу нічних ельфів після втрати безсмертя, яке дарувало їхнє священне Світове Дерево Нордрассил. На відміну від щільних кам'яних метрополій Айронфорджа чи Стормвінда, Дарнасус — відкрите, тихе поселення з дерев'яних осель, сяйливих святинь і аркових мостів над кришталевими озерами. Пильні Вартові, велетенські древні війни й друїди, що формують дерева, стережуть стежки, дбаючи, щоб мирна тиша природи зберігалася в межах міста."},{t="Розділений провід",b="Дарнасус утілює єдність калдорей, та його врядування відображає тонкі тріщини. Верховна Жриця Тіранда Віспервінд керує цивільними й військовими справами з осяйного Храму Місяця в оточенні Сестер Елуни. Тим часом справи Кола Кенарія перебувають у віданні Архідруїда Фандрала Стаґгелма, який просував висадження Тельдрассила, щоб повернути ельфам утрачене безсмертя. Поки Малфуріон Стормрейдж спить таємничим сном і Смарагдовий Сон не відпускає його, напориста візія Стаґгелма щодо їхнього майбутнього раз у раз спричиняє тертя з терплячішим жрецтвом."}},faq={{q="Хто править Дарнасусом?",a="Верховна Жриця Тіранда Віспервінд — головна очільниця суспільства нічних ельфів: вона перебуває в Храмі Місяця й командує Вартовими. Справами друїдів керує Архідруїд Фандрал Стаґгелм, що очолює Коло Кенарія за відсутності Малфуріона Стормрейджа.",al={"лідер дарнасуса","хто керує дарнасусом","лідер нічних ельфів"}},{q="Як мандрівники дістаються до Дарнасуса з-поза Тельдрассила?",a="Дарнасус стоїть на величезних гілках острова-Світового Дерева, тож кораблі й повітряні шляхи сполучаються лише із Селищем Рут'теран біля підніжжя дерева. А з Рут'терана магічний портал переносить гостей нагору, у саме місто.",al={"як дістатися до дарнасуса","вхід у дарнасус","потрапити в дарнасус"}},{q="Чому Дарнасус заснували так недавно?",a="Після руйнувань на Горі Гіджал у Третій війні нічні ельфи втратили безсмертя й давній уклад життя. Фандрал Стаґгелм і його прибічники посадили Тельдрассил біля берегів Калімдору, і на його гілках виріс Дарнасус — новий прихисток для їхнього народу.",al={"чому дарнасус новий","коли збудували дарнасус","вік дарнасуса"}},{q="Де Малфуріон Стормрейдж?",a="Архідруїд Малфуріон Стормрейдж зник: його дух ув'язнений у глибокому незбагненному сні в Смарагдовому Сні. Через його відсутність провід Колом Кенарія в Дарнасусі цілком перейшов до Фандрала Стаґгелма.",al={"де малфуріон","чи малфуріон у дарнасусі","статус малфуріона"}}},fp="9,392,23.569.0,20.599.0,20.268.0,57.227.0,38.291.0,29.213.0"}
P.entries["subzone:darrow-hill"] = {n="Пагорб Дарроу",s="Пагорб Дарроу — високе роздолля суворих лук на півночі Передгір'я Гілсбреда, просто під Мисом. На відкритих схилах пасуться гірські леви й олені, а в Печерах Передгір'я, що поцяткували пагорб, чатують здичавілі єті. Багатий на жили Альтеракського Граніту, пагорб лишається підступним пограниччям, де дикі звірі й ворожі мандрівники раз у раз сходяться в сутичках.",h="Пагорб Дарроу — високе роздолля суворих лук на півночі Передгір'я Гілсбреда, просто під Мисом.",kw={"пагорб дарроу","гілсбред","єті","граніт","гірські леви","печери"},ang={["class:Hunter"]="Пагорби — чудові мисливські угіддя: гірські леви й олені кочують тут між узліссям Альтерака й нижчими луками.",["profession:Mining"]="Печерні ходи, що пронизують Пагорб Дарроу, — надто Печери Передгір'я — багаті на Альтеракський Граніт і місцеві рудні жили, якщо ви дасте раду єті, що гніздяться поблизу."},sec={{t="Підступне пограниччя",b="Пагорб Дарроу тягнеться попід північними горами нижче Мису й поєднує хвилясті пасовища південного Гілсбреда з гострими, холоднішими висотами Альтерака. Гірські леви й олені ходять високими травами, ділячи кам'янисті схили з велетенськими єті, що вибираються з Печер Передгір'я. Крім диких звірів, стіни печер ховають поклади щільного Альтеракського Граніту, і він заманює каменотесів, рудокопів та шукачів пригод просто в пащу небезпеки. Край ділять ворожі сторони, тож тутешні стежки славляться небезпекою для необачних мандрівників з обох фракцій."}},faq={{q="Де Пагорб Дарроу?",a="Пагорб Дарроу — на півночі Передгір'я Гілсбреда, одразу на південь від скелястих круч, відомих як Мис, і на схід від головної гірської дороги до Альтерака.",al={"де пагорб дарроу","розташування пагорба дарроу","пагорб дарроу на мапі"}},{q="Які істоти загрожують мандрівникам біля Пагорба Дарроу?",a="Відкритими схилами никають олені й гірські леви, а довкола Передгірних Печер і в них самих блукають люті єті.",al={"монстри пагорба дарроу","хто живе на пагорбі дарроу","чудовиська пагорба дарроу"}},{q="Що можна знайти в Передгірних Печерах?",a="Передгірні Печери кишать дикими єті, а в їхніх кам'яних стінах — жили цінного Альтеракського Граніту.",al={"передгірні печери","печера пагорба дарроу","що в печері"}},{q="Чому цю місцину вважають такою небезпечною для мандрівників?",a="Окрім лютих звірів і лігв єті, відкрита місцевість просто біля спірних доріг зробила Пагорб Дарроу горезвісним місцем сутичок, де мандрівники Альянсу й Орди часто влаштовували засідки одне на одного.",al={"чому пагорб дарроу небезпечний","пагорб дарроу пвп","небезпека пагорба дарроу"}}},fp="11,385,22.608.0,29.181.0,53.134.0,46.129.0,55.213.0"}
P.entries["subzone:darrowmere-lake"] = {n="Озеро Дарроумер",s="Озеро Дарроумер — широке прісноводне озеро в південно-східній частині Західних Чумних Земель. Посеред нього лежить острів-фортеця Каер Дарроу, чиї зруйновані зали приховують страшну некромантську академію Культу Проклятих — Сколомансію.",h="Озеро Дарроумер — широке прісноводне озеро в південно-східній частині Західних Чумних Земель.",kw={"озеро дарроумер","каер дарроу","сколомансія","друга війна","праудмур","зул'джин","дім баровів"},ang={["faction:Alliance"]="Ветерани Альянсу пам'ятають Озеро Дарроумер як важливий морський фронт, де під час Другої війни флот Праудмура бився, щоб спинити Стару Орду й визволити Стратгольм.",["race:Undead"]="Озеро — це поріг Каер Дарроу, де ще живі Барови віддали свій смертний дім Королю-Лічу, щоб там постала страшна академія Сколомансія."},sec={{t="Внутрішнє море з історією",b="Озеро Дарроумер — одна з найбільших внутрішніх водойм Східних Королівств; його обступають уражені чумою ліси Лордерону, а живлять річки Тондроріл і Дарроумер. Під час Другої війни на цих глибоких водах точилися запеклі морські сутички між Ордою та флотом великого адмірала Дейліна Праудмура. Кораблі Праудмура перевезли озером ватажків Альянсу Туральйона й Аллерію Віндраннер на допомогу Стратгольму, а на цих берегах узяли в полон воєначальника лісових тролів Зул'джина. Колись жвавий водний шлях і торговельна артерія Дому Баровів, нині озеро — похмура, оповита туманом улоговина в самому серці Чумних Земель."},{t="Тінь над водами",b="Посеред озера височіє Каер Дарроу — колись горде родове гніздо родини Баровів. Під його зруйнованими підмурками лежить Сколомансія, головна академія некромантії й темних мистецтв Погибелі. Води навколо острова стоячі й сповнені небезпек — вони наче віддзеркалюють темну спадщину Культу Проклятих. Шукачам пригод, які наважаться перетнути озеро, доведеться долати не лише небезпеки чумного краю, а й гнітючий жах, що його навіває фортеця посередині."}},faq={{q="Де Озеро Дарроумер?",a="Озеро Дарроумер — у південно-східному куті Західних Чумних Земель: на півночі в нього впадає Річка Тондроріл, а на південь витікає Річка Дарроумер.",al={"розташування дарроумера","де озеро дарроумер","як дістатися до дарроумера"}},{q="Що на острові посеред озера?",a="На острові — Каер Дарроу, давнє поселення, яким колись правив шляхетний Дім Баровів. Під зруйнованим містечком лежить Сколомансія — розлога школа темної магії, яку тримає Культ Проклятих.",al={"острів на дарроумері","що на острові","де кер-дарроу"}},{q="Яку роль Озеро Дарроумер відіграло в Другій війні?",a="Озеро було спірним водним шляхом, де флот Праудмурів давав морські бої Орді. Транспортні судна перевозили озером війська Туральйона й Аллерії до Стратгольма, а біля його берегів захопили троля-воєводу Зул'джина.",al={"друга війна дарроумер","морські битви дарроумера","історія дарроумера"}},{q="Чи можуть кораблі ще запливати в Озеро Дарроумер?",a="У Другу війну озером ходили великі флоти, але тепер на річках, що з ним сполучаються, круті водоспади й мілини, тож великі судна не можуть запливти з моря.",al={"човни до дарроумера","чи можуть кораблі запливти в дарроумер"}}},fp="15,258,20.663.0,24.493.0,33.173.0,48.202.0,53.243.0,42.196.0"}
P.entries["subzone:darrowshire"] = {n="Дарроушир",s="Дарроушир — зруйноване село на південних пагорбах Східних Чумних Земель, колись тихе поселення Лордерона. У Третю війну його мешканці відчайдушно й трагічно протистояли значно більшому війську Погибелі. Нині серед тиші лишилися тільки потрощені балки, неспокійні духи й гіркі спогади.",h="Дарроушир — зруйноване село на південних пагорбах Східних Чумних Земель, колись тихе поселення Лордерона.",kw={"дарроушир","село","погибель","мардук блекпул","горґус спустошувач","привиди","третя війна"},ang={["class:Paladin"]="Трагічна доля Дарроуширу — незгасний заклик до паладинів нести очисне Світло в Чумні Землі: і щоб розгромити нежить, і щоб упокоїти змучених духів.",["race:Human"]="Для людей Альянсу Дарроушир — скорботне свідчення руйнування, якого зазнав Лордерон. Тут прості люди стали на безнадійну оборону своїх родин."},sec={{t="Трагічна оборона",b="Доки чума не поглинула північний Лордерон, Дарроушир був скромним сільським поселенням під південними скелями. Коли в Третю війну Погибель рушила на південь, військо на чолі з лицарем смерті Мардуком Блекпулом і повелителем гулів Горґусом Спустошувачем обложило містечко. Селяни й місцеві захисники билися хоробро й якийсь час навіть стримували ворога всупереч безнадійній перевазі. Та врешті оборона впала, і містечко вирізали до останньої душі. Полеглі захисники Дарроуширу не знайшли спокою в смерті: багатьох із них підняли гулями, щоб поповнити лави Погибелі, а село стало моторошним порожнім пам'ятником утраченій звитязі."},{t="Відлуння битви",b="Хоч живі давно покинули Дарроушир, порожнім його не назвеш. Тягар різанини досі тяжко тисне на долину й тримає серед руїн примарні рештки містян. Мандрівники розповідають про дивні явища, зокрема про моторошні повтори, коли трагічна битва знову розгортається в примарній тиші. Земля тут і досі просякнута скорботою й похмуро нагадує, що саме Погибель вирвала з серця королівства."}},faq={{q="Що сталося з Дарроуширом?",a="Дарроушир зруйновано в Третій війні, коли на містечко напала величезна армія Погибелі. Під проводом лицаря смерті Мардука Блекпула й володаря гулів Горґуса Спустошувача нежить зламала оборону містечка й вирізала мешканців, лишивши поселення в руїнах.",al={"історія дарроуширу","чому зруйновано дарроушир","що тут сталося"}},{q="Хто очолював напад Погибелі на Дарроушир?",a="Напад очолили лицар смерті Мардук Блекпул і Горґус Спустошувач — страхітливий володар гулів. Разом їхні сили зламали захисників села й прирекли поселення.",al={"хто напав на дарроушир","лиходії дарроуширу","горгус і мардук"}},{q="Чому в Дарроуширі блукають привиди?",a="Різанина була такою раптовою й жахливою, що духи полеглих лишилися прикутими до землі. Окрім примар, що блукають зруйнованими будинками, кажуть, сама жорстока битва час від часу повторюється в примарному вигляді, і мерці знову й знову переживають свої останні трагічні миті.",al={"привиди дарроуширу","чому в дарроуширі духи"}},{q="Що сталося із селянами, які загинули, боронячи містечко?",a="Більшість захисників вирізали там, де вони стояли, а чимало їхніх тіл некроманти підняли безмозкими гулями, змусивши служити тій самій армії Погибелі, що зруйнувала їхні домівки.",al={"селяни дарроуширу","оборонці дарроуширу"}}},fp="11,321,14.670.0,20.468.0,29.284.0,58.190.0,27.294.0,57.200.0"}
P.entries["subzone:dawning-isles"] = {n="Світанкові Острови",s="Світанкові Острови — група низьких острівців на Озері Лордамер біля східного краю Срібнолісся. Колись ідилічні місця відпочинку, вони піддалися пошесті Чуми Нежиття, і їх заполонили агресивні мурлоки.",h="Світанкові Острови — група низьких острівців на Озері Лордамер біля східного краю Срібнолісся.",kw={"світанкові острови","озеро лордамер","мурлоки","темноплавці","чума нежиття","срібнолісся"},ang={["faction:Alliance"]="Сплюндровані острови — похмуре нагадування про те, як глибоко скверна Погибелі проникла в наймальовничіші води Лордерона.",["race:Undead"]="Сплюндровані Світанкові Острови лежать на Озері Лордамер, звідки видно західні підступи до Андерсіті, а мурлоків-Темноплавців, що їх тримають, із кожним роком більшає."},sec={{t="Пошесть на озері",b="До Третьої війни Світанкові Острови славилися як мальовничі острівці серед спокійних прозорих вод Озера Лордамер. Коли Чума Нежиття прокотилася Лордероном, скверна просочилася в мілини озера. Рослинність зблідла й почала гнити, і ідилічний спокій зник. Сьогодні на мулистих берегах і в заплутаних чагарниках панує плем'я мурлоків-Темноплавців, що люто захищають свої колонії, які дедалі розростаються, від кожного, хто спробує перетнути озеро."},{t="Твердиня мурлоків",b="Мурлоки не завжди були єдиною небезпекою на островах. Колись поряд із ними сплюндрованими острівцями никали болотяні звірі, але відтоді ті зникли. Без них Темноплавців розплодилося стільки, що тепер мурлоки цілком контролюють острови, перетворивши колись тихе намисто острівців на свою твердиню на Озері Лордамер."}},faq={{q="Де Світанкові Острови?",a="Світанкові Острови — на Озері Лордамер, біля східної межі Срібнолісся, трохи на захід від Руїн Лордерона.",al={"розташування світанкових островів","де світанкові острови","світанкові острови на мапі"}},{q="Які істоти живуть на Світанкових Островах?",a="Острови заполонило здебільшого плем'я мурлоків-Темноплавців, що процвітає на отруєних берегах. Колись тут никали й небезпечні болотяні чудовиська, але тепер їх майже витіснили численні мурлоки.",al={"монстри світанкових островів","хто живе на світанкових островах","чудовиська світанкових островів"}},{q="Чому тут гниють дерева й береги?",a="Острови отруїла Чума Нежиття, що прокотилася Лордероном у Третій війні. Вода й ґрунт увібрали пошесть, отруївши рослинність, і острівці стали каламутними, хворобливими й гниючими.",al={"чому світанкові острови заражені","зараза озера світанкових островів"}}},fp="13,248,18.460.0,19.353.0,36.149.0,41.250.0,42.205.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="Катакомби Світанкового Лісу",s="Видовбані глибоко під Цвинтарем Воронячого Пагорба, Катакомби Світанкового Лісу — темний лабіринт, де кишить найлютіша нежить Сутінколісся. Тих, хто наважиться зійти в підземні ходи, чекають цілі зграї скелетів-вартових і гулів-трупоїдів.",h="Видовбані глибоко під Цвинтарем Воронячого Пагорба, Катакомби Світанкового Лісу — темний лабіринт, де кишить...",kw={"катакомби світанкового лісу","катакомби","нежить","гулі","воронячий пагорб","сутінколісся"},ang={["class:Paladin"]="Катакомби — похмуре свідчення про полеглих підданців королівства: осквернені гробниці вимагають, щоб їх очистив святий гнів Світла.",["class:Priest"]="Під кам'яними склепіннями Воронячого Пагорба неспокійні духи й тліючі тіла благають про вічний спокій, тож катакомби стають сумним випробуванням віри."},sec={{t="Під Воронячим Пагорбом",b="Задовго до того, як сутінкове прокляття лягло на ліс, Катакомби Світанкового Лісу були величною усипальницею для шанованих мерців Великого Селища та довколишніх садиб. Тепер, похована під зруйнованим Цвинтарем Воронячого Пагорба, ця мережа темних кам'яних коридорів зберігає найсмертоноснішу нежить краю. Катакомби мають два окремі підземні крила: західні ходи тримають шеренги оживлених скелетів, що стережуть родові гробниці, а східні спускаються в мерзенне кубло, де кишать ненажерливі гулі — розносники хвороб. Самотні мандрівники рідко виживають у цих глибинах."}},faq={{q="Де Катакомби Світанкового Лісу?",a="Катакомби лежать просто під Цвинтарем Воронячого Пагорба, на крайньому західному краю Сутінколісся. Входи спускаються з поверхні серед розкиданих надгробків і зруйнованих склепів.",al={"розташування катакомб","де катакомби світанкового лісу","як дістатися до катакомб"}},{q="Що чаїться в катакомбах?",a="У катакомбах — найбільше скупчення найлютішої нежиті в Сутінколіссі. Західне крило боронять добре озброєні воїни-кістяки, а східні тунелі кишать дикими, зачумленими гулями.",al={"вороги катакомб","що в катакомбах світанкового лісу","монстри катакомб"}},{q="Навіщо взагалі збудували катакомби?",a="Ще тоді, коли край був зеленим Брайтвудом, катакомби викопали як велику усипальницю для місцевих родин і знаних людей. Темне прокляття, що згодом огорнуло ліс, підняло похованих там мерців.",al={"історія катакомб","навіщо будувати катакомби","первісне призначення катакомб"}},{q="Чи безпечно досліджувати катакомби самому?",a="Іти в катакомби самому небезпечно. У тісних тунелях майже немає куди відступати, а нежить збирається щільними агресивними зграями, здатними здолати самотнього мандрівника.",al={"чи можна самому в катакомби","небезпека катакомб","чи важкі катакомби"}}},fp="22,245,18.602.0,45.180.0,32.215.0,48.221.0,42.206.0"}
P.entries["subzone:dead-acre"] = {n="Мертвий Лан",s="Мертвий Лан — зруйнована, ще димна садиба на південному сході Вестфолу, біля річкового мосту до Сутінколісся. Братство Дефіас спалило її дотла під час повстання, що прокотилося краєм, і тепер на почорнілих полях немає людей — лише блукають некеровані големи жнив.",h="Мертвий Лан — зруйнована, ще димна садиба на південному сході Вестфолу, біля річкового мосту до Сутінколісся.",kw={"мертвий лан","вестфол","ферма","дефіас","вартові врожаю"},ang={["faction:Alliance"]="Мертвий Лан — похмуре нагадування про байдужість Стормвінда до Вестфолу, через яку вірні фермери лишилися беззахисними перед жорстокими грабунками Братства Дефіас."},sec={{t="Попіл на кордоні",b="Мертвий Лан, що лежить трохи на північ від дороги із Сентінел Гілла до Сутінколісся, колись був урожайною садибою серед ферм житниці Вестфолу. Коли Братство Дефіас підняло бунт і вигнало місцевих землевласників, ця ферма зазнала жорстокої долі. Садибу й посіви довкола підпалили, лишивши по собі обвуглені колоди, задимлену землю й механічних Вартових Урожаю, що досі блукають і жнуть безплідну землю."}},faq={{q="Чому це місце зветься Мертвий Лан?",a="Братство Дефіас, захоплюючи Вестфол, спалило хутір і навколишні поля дотла. Похмуру назву ферма дістала від почорнілих руїн і тліючої землі, що лишилися після них.",al={"чому мертвий лан","що сталося з мертвим ланом","чому тут усе згоріло"}},{q="Чому тут блукають механічні Стражі Врожаю?",a="Як і на багатьох фермах Вестфолу, механічні женці, збудовані доглядати врожай, лишилися, коли поселенці втекли чи загинули. Зіпсовані чи покинуті без нагляду, автоматичні Стражі Врожаю й далі безкінечно патрулюють спалені поля, нападаючи на кожного, хто наблизиться.",al={"големи врожаю мертвий лан","чому тут големи","стражі врожаю"}},{q="Де Мертвий Лан?",a="Мертвий Лан — на південному сході Вестфолу, трохи на північ від головної дороги біля мосту, що веде до похмурих меж Сутінколісся.",al={"розташування мертвого лану","де мертвий лан","як знайти мертвий лан"}}},fp="9,279,19.446.0,39.213.0,51.282.0,31.148.0"}
P.entries["subzone:dead-field"] = {n="Мертве Поле",s="Мертве Поле — сплюндрований покинутий хутір на півночі Срібнолісся. Колись тихі сільські угіддя, тепер його захопили гнилошкірі гноли й перетворили на передовий плацдарм сил Погибелі. Неодноразові спроби Відступників очистити місцевість зазнали невдачі через баньші Найтлаш, що командує тут.",h="Мертве Поле — сплюндрований покинутий хутір на півночі Срібнолісся.",kw={"мертве поле","гнилошкірі гноли","найтлаш","погибель","тул рейвенклов","срібнолісся"},ang={["class:Rogue"]="Розвідувальні загони скрадачів смерті пильно стежать за хутором; проникнути в лави гнолів і вдарити по їхньому командуванню — першочергове тактичне завдання.",["race:Undead"]="Для Відступників плацдарм Погибелі на Мертвому Полі — безпосередня загроза дорозі між Гробницею й північним Лордероном, і його треба негайно знищити."},sec={{t="Сплюндрований плацдарм",b="Від колишнього хутора на півночі Срібнолісся мало що лишилося: його живі мешканці давно загинули під час Третьої війни. Сьогодні зруйнована ділянка — база гнилошкірих гнолів, що охоче служать Погибелі. Коли їх побільшало, розвідники-скрадачі смерті, що проходили краєм, помітили ознаки неминучого військового збору, який загрожує шляхам постачання й заставам Відступників. Невеликі напади Відступників на хутір раз у раз зазнавали невдачі: їх відкидала голосна примара Найтлаш — баньші, що з'являється щоразу, коли її підвладним гнолам загрожує небезпека."},{t="Задуми Рейвенклова",b="Гнилошкірі гноли діють не самі. Їхніми справами на Мертвому Полі здалеку керує некромант Тул Рейвенклов, що засів на Острові Фенріс. Прагнучи утвердити владу Погибелі над Срібноліссям і вигнати сили Сильвани з Лордерона, Рейвенклов посилає на хутір свої магічні проєкції, щоб оглядати орду нежиті й застерігати загарбників-Відступників."}},faq={{q="Що таке Мертве Поле?",a="Мертве Поле — занедбаний, отруєний хутір на півночі Срібнолісся. Колись звичайна людська ферма, тепер він лежить у руїнах, і його захопили гнилошкірі гноли, що служать Погибелі.",al={"мертве поле сілверпайн","де мертве поле","що сталося з мертвим полем"}},{q="Чому на фермі гноли?",a="Ці гнилошкірі гноли підвладні Погибелі. Вони використовують хутір як передовий плацдарм, щоб збирати сили й готувати напади на позиції Відступників на півночі Срібнолісся.",al={"чому гноли гнильошкірі","гнильошкірі на мертвому полі","гноли погибелі"}},{q="Хто така Найтлаш?",a="Найтлаш — банші Погибелі, що командує гнилошкірими гнолами на фермі. Щоразу, як ударні загони Відступників нападають на табір, вона з'являється на захист своїх слуг і вже відбила попередні спроби відвоювати землю.",al={"найтлаш банши","банши на мертвому полі","хто захищає гнолів"}},{q="Хто командує тутешніми силами Погибелі?",a="Табір підпорядкований Тулові Рейвенклову — могутньому некромантові, що діє із сусіднього Острова Фенріс. Він керує гнолами через видіння й магічний нагляд, щоб заважати поширенню Відступників.",al={"хто керує мертвим полем","туле крукокіготь мертве поле","хто головний"}}},fp="10,327,25.616.0,20.386.1,23.196.0,33.202.0,17.220.0,37.198.0"}
P.entries["subzone:deadeye-shore"] = {n="Берег Дедай",s="Берег Дедай — обвіяний вітрами відтинок узбережжя на східному краю Дуротару, просто на схід від Яру Сухої Балки. Названі на згадку про легендарного вождя клану Кривавої Западини Кілроґґа Дедая, ці пустельні піски населяють здебільшого дикі раптори, скорпіди та здичавілі вепри.",h="Берег Дедай — обвіяний вітрами відтинок узбережжя на східному краю Дуротару, просто на схід від Яру Сухої...",kw={"берег дедай","узбережжя","кілроґґ","кривава западина","раптори","скорпіди","дуротар"},ang={["race:Orc"]="Для орків, що будують нову державу в Дуротарі, берег ушановує Кілроґґа Дедая, нагадуючи про старих вождів, які творили історію Орди під час воєн на Азероті."},sec={{t="Берег Кривавої Западини",b="Берег Дедай під червоними кручами центрального Дуротару дістав своє ім'я від Кілроґґа Дедая — одноокого вождя клану Кривавої Западини, що бився в Першій та Другій війнах. Згори пісок і скелясті виступи ледь помітно нагадують обрис черепа з порожньою очницею. Хоч тут немає великих поселень чи військових застав, берег аж ніяк не мирний: на пісках панує войовнича звірина, а потаємні культисти Палаючого Клинка, як відомо, спускаються до води зі своїх сховків у сусідніх ярах."}},faq={{q="Чому він зветься Берег Дедай?",a="Берег названо на честь Кілроґа Дедая, знаменитого вождя клану Кривавої Западини. А ще обриси узбережжя нагадують череп без ока — так само, як порожня очниця самого вождя.",al={"хто такий дедай","чому берег дедай","походження назви"}},{q="Хто живе на Березі Дедай?",a="Постійних поселень на Березі Дедай немає. Цю смугу узбережжя населяють здебільшого місцеві звірі — раптори, скорпіди й кабани, хоча рибалки й мандрівники часом проходять тут, іноді натрапляючи на прихованих культистів Палаючого Клинка.",al={"хто тут","поселення берега дедай","нпс берега дедай"}},{q="Які загрози чатують біля Берега Дедай?",a="Окрім агресивних місцевих звірів, найбільша небезпека — сусідній Яр Сухої Балки. Культисти Палаючого Клинка часом спускаються зі скелястих каньйонів до узбережжя й нападають на необачних мандрівників і рибалок.",al={"небезпеки берега дедай","вороги тут","палаючий клинок дедай"}}},fp="13,271,34.569.0,31.205.0,30.263.0,44.243.0"}
P.entries["subzone:deadman-s-crossing"] = {n="Перехрестя Мерця",s="Перехрестя Мерця — зловісне роздоріжжя в похмурому каньйоні Перевалу Мертвого Вітру. Звідси дороги розходяться до Сутінколісся, Болота Скорботи й примарної вежі Каражану; це похмурий поріг, позначений шибеницею та застережними вказівниками. Попри моторошний вигляд, шлях лишається важливою артерією для мандрівників, що перетинають південь Східних Королівств.",h="Перехрестя Мерця — зловісне роздоріжжя в похмурому каньйоні Перевалу Мертвого Вітру.",kw={"перехрестя мерця","перевал мертвого вітру","шибениця","каражан","сутінколісся","болото скорботи"},ang={["faction:Alliance"]="Для гінців Альянсу, що прямують із Даркшира до Замку Незерґард у Спустошених Землях, шлях через Перехрестя Мерця — найкоротший, хоч і найбільш моторошний.",["faction:Horde"]="Мандрівники Орди, що йдуть на захід зі Стонарда до Сутінколісся, мусять минути цей похмурий орієнтир — перший присмак проклятих людських земель попереду."},sec={{t="Похмуре роздоріжжя",b="Перехрестя Мерця, що лежить на східному роздоріжжі Перевалу Мертвого Вітру, сполучає тіні Сутінколісся з каламутними глибинами Болота Скорботи, а зловісна південна стежка здіймається до примарної вежі Каражану. Назву перехрестю дало покручене дерево-шибениця на розвилці доріг: на ньому погойдуються двоє гниючих трупів — суворе застереження всім перехожим. Поруч із деревом побиті дерев'яні вказівники дають мандрівникам відверту пораду: повертайте назад і облиште надію. Сам каньйон кишить ворожими звірами й темним чаклунством, але ті, хто впевнено йде утоптаною ґрунтовою дорогою, на диво спокійно минають перехрестя — якщо тільки не заблукають серед проклятих скель."}},faq={{q="Куди веде кожна дорога з Перехрестя Мерця?",a="На захід — геть із перевалу, у моторошні ліси Сутінколісся. На схід — просто в болота Болота Скорботи. А звивиста південна стежка веде в саме серце Перевалу Мертвого Вітру, до проклятих руїн і величної вежі Каражана.",al={"куди ведуть дороги","напрямки перехрестя","шляхи перехрестя мерця"}},{q="Чиї трупи висять на дереві?",a="Хто вони — історія не зберегла. Перевал Мертвого Вітру за ці роки забрав безліч нещасних мандрівників, розбійників і втікачів, і хтось зробив із дерева-шибениці моторошний межовий знак, щоб відлякувати подорожніх.",al={"повішені тіла","мертві тіла на дереві","кого повісили"}},{q="Чи безпечне Перехрестя Мерця для мандрівників?",a="Як не дивно, так. Навколишні скелі й печери Перевалу Мертвого Вітру кишать лютими стерв'ятниками, привидами й ограми, але саме перехрестя й головна дорога схід — захід лишаються чистими. Недосвідчені гінці й шукачі пригод можуть безпечно пройти між Сутінколіссям і Болотом Скорботи, якщо не сходитимуть із протоптаної ґрунтової стежки.",al={"чи безпечно","чи нападуть на дорозі","рівень небезпеки"}},{q="Що написано на вказівниках на перехресті?",a="Вивітрені дерев'яні вказівники зловісно застерігають: на одному прямо написано «Повертай назад!», на іншому — «Покиньте надію, всі, хто сюди входить», тож щодо небезпеки долини сумнівів не лишається.",al={"вказівник на перехресті","що написано на вказівниках","знак покиньте надію"}}},fp="18,369,19.745.0,50.280.0,42.237.0,41.339.0,38.220.0"}
P.entries["subzone:deadmines"] = {n="Мертві Копальні",s="Глибоко під курним містом-привидом Мунбруком лежать Мертві Копальні — розлогий підземний лабіринт, що колись давав третину золотого запасу Стормвінда. Покинуті під час Першої війни й оповиті чутками про привидів, ці забуті штольні стали укріпленим штабом Едвіна Венкліфа та його бунтівного Братства Дефіас.",h="Глибоко під курним містом-привидом Мунбруком лежать Мертві Копальні — розлогий підземний лабіринт, що колись...",kw={"мертві копальні","мунбрук","едвін венкліф","братство дефіас","фоліант божественності","бухта айронклад","андуїн лотар"},ang={["class:Paladin"]="Мертві Копальні мають для паладинів святе значення: під час Першої війни сер Андуїн Лотар спустився в їхні найтемніші зали, щоб відбити в лютих огрів священний Фоліант Божественності.",["profession:Mining"]="До Першої війни ці штольні були перлиною людського гірництва й давали третину золотого запасу Стормвінда, доки їх не прибрали до рук гоблінські машини й розбійники Дефіасу."},sec={{t="Жила золота й крові",b="До Першої війни Мертві Копальні були найкращою гірничою розробкою людських земель — багатою на золото й міцний білокам'яний дуб, з якого робили брус і кріплення. Коли Орда орків рушила на північ, копальні поспіхом покинули. Сер Андуїн Лотар уславився тим, що спустився в їхні підступні глибини, щоб повернути священний Фоліант Божественності, і пережив двадцять місяців полону в підземних огрів, доки його не врятували. У сум'ятті, що настало після падіння королівства, штольні затихли й здобули моторошну славу проклятого місця."},{t="Ливарня Венкліфа",b="Після бунту каменярів у Стормвінді новостворене Братство Дефіас захопило підземний комплекс і зробило його своїм головним прихистком. Коли Ліга Шахтарів Стормвінда спробувала знову відкрити тунелі під проводом Наглядача Тистлнеттла, розбійники Дефіасу влаштували робітникам засідку й обвалили штольні, а загиблі шахтарі відтоді блукають там неспокійною нежиттю. Нині, під захистом огрів-силовиків і гоблінських майстрів, Братство Дефіас перетворило глибокі тунелі на промисловий воєнний табір довкола підземної корабельні в Бухті Айронклад."}},faq={{q="Як потрапити до Мертвих Копалень?",a="Головний вхід схований у Схованці Дефіасу в зруйнованому містечку Мунбрук на південному заході Вестфолу. Спускаючись підвалами, ви потрапите просто до розлогих шахтних стовбурів.",al={"де вхід у мертві копальні","як зайти в мертві копальні","розташування мертвих копалень"}},{q="Чому копальні взагалі покинули?",a="Їх покинули в Першу війну, коли Орда захопила південні землі королівства. Війна вирувала, у глибини вселилися огри, роботи припинилися, і покинуті тунелі швидко зажили слави місця з привидами.",al={"чому закрили мертві копальні","чому мертві копальні покинуті"}},{q="Що Братство Дефіас тут будує?",a="Глибоко в затопленій печері Бухти Айронклад Едвін Венкліф і найняті інженери-гобліни будують величезний броненосець. Венкліф хоче повести цей бойовий корабель уздовж узбережжя, щоб обстріляти й узяти в облогу Стормвінд — помститися йому.",al={"що в мертвих копальнях","план ванкліфа мертві копальні","корабель залізний борт"}},{q="Хто ця нежить біля вхідних тунелів?",a="Це нещасні робітники Ліги Шахтарів на чолі з Наглядачем Тистлнеттлом. Коли Ліга спробувала обстежити й повернути копальню, громили Дефіас напали на них і обвалили стовбури, лишивши шахтарів помирати в пастці, — і ті повстали неспокійними гулями.",al={"нежить мертвих копалень","бригадир чортополох мертві копальні","чому в копальнях гулі"}},{q="Що пов'язує Андуїна Лотара з Мертвими Копальнями?",a="Під час Першої війни сер Андуїн Лотар спустився глибоко в Мертві Копальні, щоб здобути священний Фоліант Божественності. Його захопили огри, що жили в печерах, і він пробув у полоні майже два роки, доки його нарешті не врятували.",al={"лотар мертві копальні","андуїн лотар мертві копальні"}}},fp="9,338,24.558.0,18.534.1,34.211.0,48.245.0,50.256.1,55.259.0,57.250.0"}
P.entries["subzone:deadwood-village"] = {n="Село Мертволісся",s="Село Мертволісся — табір фурболгів на півдні Сквернолісся. Колись його мешканці були мирним кланом, що жив у злагоді з природою, але стали жертвами демонічної скверни, яка сплюндрувала довколишній ліс. Збожеволілі від скверни, фурболги Мертволісся тепер нападають на кожного, хто наближається до їхнього грубого дерев'яного поселення.",h="Село Мертволісся — табір фурболгів на півдні Сквернолісся.",ang={["class:Druid"]="Село Мертволісся — болісна поразка захисників природи, що нагадує друїдам Кола Кенарія, як глибоко демонічна скверна може спотворити мирних істот."},sec={{t="Занепале плем'я",b="Село Мертволісся, що стоїть біля південного кордону Сквернолісся, — головний осередок племені Мертволісся. Коли демонічні енергії Палаючого Легіону прокотилися давніми лісами, фурболгам забракло сил опиратися повзучій гнилі. Їхній розум спотворила злоба скверни, і вони покинули давні традиції та духовну гармонію. Нині село — це злиденне збіговисько ворожих громил, шаманів і вартових лігва, які люто боронять свої отруєні землі від чужинців. Це завдає відчаю їхнім незіпсованим родичам — Деревопащим."}},faq={{q="Чому тутешні фурболги ворожі?",a="Фурболгів Села Мертволісся поглинула демонічна скверна, що спустошила Сквернолісся в Третій війні. Магія Скверни спотворила їхні природні інстинкти, обернувши їх на скажену агресію, і довела до лютого божевілля й ворожості до всіх чужинців.",al={"чому мертволісся ворожі","ворожість мертволісся","чому мертволісся червоні"}},{q="Чи можуть гравці говорити із Селом Мертволісся чи помиритися з ним?",a="Ні. Плем'я Мертволісся надто глибоко зіпсоване для мирних перемовин. Натомість шукачі пригод полюють на них, збираючи племінні пера, щоб здобути прихильність незіпсованих фурболгів-Деревопащих, які стережуть тунелі на півночі.",al={"чи можна подружитися з мертволіссям","репутація мертволісся"}},{q="Як це плем'я пов'язане з Деревопащими?",a="Колись обидва були звичайними племенами фурболгів, що жили в гармонії з природою. Коли Сквернолісся зіпсувалося, плем'я Деревопащих зуміло зберегти розум, а плем'я Мертволісся цілком піддалося шаленству Скверни. Тепер Деревопащі вважають Мертволісся пропащими й небезпечними.",al={"деревопащі й мертволісся","племена фурболгів"}}},fp="16,310,14.566.0,34.245.0,56.221.0,44.272.0"}
P.entries["subzone:deathknell"] = {n="Похоронний Подзвін",s="Похоронний Подзвін — укріплене село у відлюдній долині південно-західних Галявин Тірісфалю. Це головне місце пробудження щойно звільненої нежиті, що виривається з хватки Короля-Ліча, аби приєднатися до Відступників. В облозі безтямних решток Погибелі, місцевих фанатиків і агресивної живності, поселення — суворе місце випробувань для тих, хто претендує на місце в королівстві Сильвани Віндраннер.",h="Похоронний Подзвін — укріплене село у відлюдній долині південно-західних Галявин Тірісфалю.",kw={"похоронний подзвін","стартова зона","відступники","нежить","тірісфаль","багряний хрестовий похід","лощина нічної павутини"},ang={["faction:Horde"]="Хоч відлюдна й темна, ця долина — брама до королівства Відступників, що постачає свіжих вояків для зміцнення плацдарму Орди в Східних Королівствах.",["race:Undead"]="Кожен шукач пригод з-поміж Відступників починає тут: підводиться з холодної землі Тіньової Могили, щоб знайти мету й прихисток під рукою Леді Сильвани після жаху Чуми."},sec={{t="Колиска Відступників",b="Схований за зубчастими пагорбами одразу на північ від кордону Срібнолісся, Похоронний Подзвін — місце, де щойно пробуджені мерці вперше розплющують очі на свою безрадісну дійсність. На відміну від більшості поселень Галявин Тірісфалю, що зберегли людські назви з часів загиблого Королівства Лордерон, Похоронний Подзвін свідомо перейменувала нежить, яка його зайняла. Саме містечко розколоте навпіл: Відступники вперто тримаються південної частини довкола старої церкви, а північна половина — разом із сільською кузнею — лишається заполонена безтямними зомбі Погибелі й здичавілими гулями. Добірні Вартові Смерті надійно тримають вузьку ущелину з долини замкненою від зайд, щоб місцеві доглядачі могли посвячувати новоприбулих у службу Королеві Баньші."},{t="Долина в облозі",b="Вижити в Похоронному Подзвоні нелегко. На північному заході Лощину Нічної Павутини — золоту копальню, життєво важливу для молодого господарства Відступників, — захопили страхітливі павуки. На південному сході войовничий табір Багряного Хрестового Походу невпинно стежить, обмінюється гінцями зі своїми твердинями на сході й промацує оборону долини. Тим часом доглядачі села мусять безперестанку відбивати безтямну нежить, що блукає північними руїнами, і збирати металобрухт, знаряддя й припаси, щоб спорядити щойно воскреслі душі на довгу дорогу."}},faq={{q="Чому містечко перейменували на Похоронний Подзвін?",a="Похоронний Подзвін перейменували після того, як він став поселенням нежиті, — на відміну від більшості громад Тірісфалю, що зберегли людські назви. Причина нової назви невідома.",al={"походження назви похоронний подзвін","чому називається похоронний подзвін","стара назва похоронного подзвону"}},{q="Чому північну половину містечка заполонила нежить?",a="Не кожен труп, піднятий після Третьої війни, вирвався на волю зі здоровим глуздом. Північний майдан села й кузню заполонили «Безтямні» — здичавілі зомбі, гулі й скелети, якими досі рухає залишкова воля Погибелі. Захисники Відступників регулярно вичищають їх, щоб роздобути спорядження й захистити церкву.",al={"чому в похоронному подзвоні зомбі","погибель у похоронному подзвоні","безтямні похоронний подзвін"}},{q="Що робить Багряний Хрестовий Похід біля Похоронного Подзвону?",a="Загін Багряного Хрестового Походу тримає табір у пагорбах на південний схід від села. Фанатично віддані знищенню всієї нежиті без розбору, вони стежать за проходом, нападають із засідки на щойно пробуджених Відступників й обмінюються розвідданими з багряними твердинями в інших куточках Лордерона.",al={"багряний табір похоронний подзвін","хрестоносці біля похоронного подзвону","багряний хрестовий похід долина тірісфалю"}},{q="Чому Відступники не можуть користуватися місцевою золотою копальнею?",a="Лощину Нічної Павутини — золоту копальню в скелях на північний захід від села — цілком заполонили агресивні павуки. Здобувати природні ресурси на кшталт золота вкрай важливо для воєнних зусиль Відступників, та поки навалу не вичищено, поселення не може розробляти жилу.",al={"копальня похоронного подзвону","лощина нічної павутини","павуча копальня тірісфаль"}}},fp="10,405,22.740.0,20.560.0,36.169.0,55.350.0,50.302.0,47.283.0"}
P.entries["subzone:decrepit-ferry"] = {n="Ветха Переправа",s="Ветха Переправа — зруйнований причал на східному березі Срібнолісся, звідки колись можна було переправитися через Озеро Лордамер на Острів Фенріс. Після падіння Лордерона пором знищили, перевізника вбили, а берег заполонили мерці й люті гнилошкірі гноли.",h="Ветха Переправа — зруйнований причал на східному березі Срібнолісся, звідки колись можна було переправитися...",kw={"ветха переправа","озеро лордамер","острів фенріс","гнилошкірі гноли","гулі","срібнолісся"},ang={["race:Undead"]="Руїни — похмуре нагадування про падіння Лордерона: тепер тут хазяйнують бездумні рештки Погибелі й брудні гноли, що загрожують діям Відступників у східному Срібноліссі."},sec={{t="Обірвана нитка",b="До Третьої війни цей причал щодня вирував рухом через Озеро Лордамер. Місцеві фермери привозили до води свіжі продукти й продавали врожай просто заможному володареві Острова Фенріс та його челяді. За помірну плату перевізник возив товари, гінців і знатних гостей між берегом і фортецею. Цій мирній торгівлі раптово настав кінець, коли королівством прокотилася Погибель. Перевізника жорстоко вбили, човни розтрощили, а пристань занепала."},{t="Осквернений берег",b="Сьогодні причал небезпечний для кожного мандрівника, що йде берегом озера. Відколи пором не працює, Острів Фенріс стоїть відрізаний за водою, а самі руїни кишать гулями, скелетами-воїнами й мандрівними гнилошкірими гнолами. Те, що колись було впорядкованою переправою, стало ще одним гнійником небезпеки в Срібноліссі."}},faq={{q="Для чого спершу була Ветха Переправа?",a="Це був головний перехід між материковим Срібноліссям і Островом Фенріс. Місцеві фермери перевозили поромом урожай через Озеро Лордамер, щоб продати його шляхетному лордові острова, і платили місцевому поромникові невелику плату за кожен рейс.",al={"історія переправи","що була ця пристань","чому тут переправа"}},{q="Що сталося з поромом і поромником?",a="Коли Погибель вдерлася в Лордерон, на пристань напали. Поромника вбили, човни й снасті переправи знищили, а саме місце покинули на поталу нежиті.",al={"що сталося з поромником","хто зламав пором"}},{q="Які чудовиська нині чаяться біля пристані?",a="Берег кишить рештками Погибелі — гулями й воїнами-кістяками, — а неподалік никають небезпечні гнилошкірі гноли.",al={"чудовиська ветхої переправи","хто живе біля переправи"}},{q="Чи можна ще звідси дістатися човном до Острова Фенріс?",a="Ні. Пором розбили під час навали, і він лежить у руїнах. Хто хоче дістатися Острова Фенріс, мусить пливти чи шукати іншого шляху через озеро.",al={"човном на фенріс","як дістатися до острова фенріс","чи працює пором"}}},fp="14,288,20.523.0,21.349.0,48.241.0,44.175.0,46.158.0,51.155.0"}
P.entries["subzone:deep-elem-mine"] = {n="Шахта Глибокого Елему",s="Шахта Глибокого Елему — копальня в самому серці Срібнолісся. Колись вона працювала, але її захопили, коли темна магія Архімага Аруґала прокотилася краєм і перетворила рудокопів на лютих воргенів.",h="Шахта Глибокого Елему — копальня в самому серці Срібнолісся.",kw={"шахта глибокого елему","воргени","ґрімсон блідий","аруґал","гірництво","срібнолісся"},ang={["profession:Mining"]="Хоч зараз шахта небезпечна через дику зграю, що там живе, це одне з найбагатших підземних родовищ Срібнолісся.",["race:Undead"]="Для Відступників захоплення шахти — і господарська необхідність, і прямий наказ із Гробниці зламати владу Аруґала, що ширшає над центральним Срібноліссям."},sec={{t="Лігво звірів",b="Шахта Глибокого Елему, що лежить у центрі Срібнолісся, колись слугувала живим мешканцям Лордерона звичайною рудною жилою. Коли Архімаг Аруґал випустив на ліс вовчий кошмар, його дике прокляття проникло глибоко в тунелі. Робітники всередині піддалися недузі й обернулися на лютих воргенів, що покинули кайла й перетворили печеру на хиже лігво."},{t="Ґрімсон і задуми Відступників",b="Зграєю в шахті командує Ґрімсон Блідий — колишній наглядач копальні, що зберіг свою хитрість навіть після жахливого перетворення. Розуміючи стратегічну цінність тунелів і руди, Відступники в Гробниці дуже зацікавлені повернути копальню. За наказом, що спирається на владу Жахолорда Варіматраса, агенти Відступників прагнуть зняти голову Ґрімсонові й винищити звірів, щоб Орда могла заволодіти багатствами шахти."}},faq={{q="Що в Шахті Глибокого Елему?",a="Шахта кишить ворожими воргенами, ураженими магією Архімага Аруґала. Їх очолює колишній наглядач-людина Ґрімсон Блідий, що тепер верховодить зграєю в глибині тунелів.",al={"що в шахті глибокого елему","монстри шахти глибокого елему","хто живе в шахті глибокого елему"}},{q="Чому Відступники хочуть очистити Шахту Глибокого Елему?",a="Відступники прагнуть скористатися природними багатствами шахти, щоб посилити свої воєнні зусилля в Лордероні. Далар Донвівер і провід у Гробниці мають намір забрати її ресурси на ім'я Жахолорда Варіматраса, щойно воргенів знищать.",al={"інтерес відступників до шахти","чому очищати шахту глибокого елему","кому потрібна шахта"}},{q="Хто такий Ґрімсон Блідий?",a="Ґрімсон спершу був смертним наглядачем, що керував роботами в Шахті Глибокого Елему. Коли дике прокляття Аруґала перетворило робітників, Ґрімсон став хитрим ватажком воргенів, що зберіг досить розуму, аби командувати зграєю в шахті.",al={"хто такий ґрімсон","ґрімсон блідий історія","бос шахти глибокого елему"}},{q="Як воргени потрапили в шахту?",a="Вони не прийшли ззовні: самих рудокопів перетворило прокляття Архімага Аруґала, що поширилося Срібноліссям, і робітники стали чудовиськами просто там, де працювали.",al={"чому в шахті воргени","походження воргенів шахти глибокого елему","як шахтарі перетворилися"}}},fp="14,224,15.397.0,29.457.1,30.188.0,48.257.0,24.243.0,37.196.0"}
P.entries["subzone:deeprun-tram"] = {n="Глибинний трамвай",s="Глибинний трамвай — підземне диво гномської інженерії, що з'єднує столиці Альянсу Айронфордж і Стормвінд. Його збудували на замовлення Короля Маґні Бронзбірда після Другої війни, і тепер городяни й вояки долають величезні відстані під землею за лічені хвилини. Закриті подвійні колії пролягають під горами й озером і слугують життєво важливою артерією для військової підтримки й торгівлі Альянсу.",h="Глибинний трамвай — підземне диво гномської інженерії, що з'єднує столиці Альянсу Айронфордж і Стормвінд.",kw={"глибинний трамвай","айронфордж","стормвінд","гноми","інженерія","меккаторк"},ang={["faction:Alliance"]="Трамвай — головна стратегічна артерія між двома найукріпленішими столицями Альянсу: він дає змогу за лічені хвилини перекидати війська й приходити одне одному на поміч.",["profession:Engineering"]="Уся залізниця — неперевершений шедевр гномської думки: передовий рушій на коліях, герметичне скло, що витримує тиск на дні підземного озера, і хитромудрі електричні стрілочні станції."},sec={{t="Диво підземної інженерії",b="Після спустошень Другої війни Король Маґні Бронзбірд дедалі більше дратувався, бачачи, як повільно дворфійська допомога й будівельні матеріали дістаються до Стормвінда гірськими перевалами. Щоб розв'язати цю проблему й гарантувати, що дворфійські вояки зможуть швидко прийти на поміч людській столиці в скрутну годину, Маґні звернувся до Великого Тінкера Ґелбіна Меккаторка. Видатний гномський інженер розробив креслення закритої підземної залізниці, що працювала на найпередовіших технологіях. Попри всі труднощі прокладання — довелося пробиватися крізь величезне підземне озеро й без кінця воювати з навалами підземних щурів, — трамвай став вершинним досягненням Альянсу й безкоштовно перевозить тисячі мандрівників між Айронфорджем і Стормвіндом."}},faq={{q="Навіщо збудували Глибинний трамвай?",a="Після Другої війни Королю Маґні Бронзбірду знадобився швидший спосіб перевозити припаси й дворфійські війська, щоб допомогти відбудувати й боронити Стормвінд. Він доручив це Великому Тінкерові Ґелбіну Меккаторку, який спроєктував і втілив підземну залізницю, що надійно з'єднала дві столиці.",al={"чому збудували трамвай","призначення трамвая","хто збудував глибинний трамвай"}},{q="Як трамвай їде під водою?",a="Прокладаючи шлях між Дун Мороґом і Стормвіндом, гномівські інженери натрапили на величезне підземне озеро. Замість того щоб оминати його, вони збудували крізь глибоку воду герметичний укріплений скляний тунель, з якого пасажири можуть дивитися, як поруч із коліями пливуть дикі трешадони й акули.",al={"вікно з водою в трамваї","трамвай під водою","озеро глибинного трамвая"}},{q="Чому вздовж колій стільки щурів?",a="Вогкі темні підземні шахти — ідеальне місце для розмноження паразитів. Гномівські начальники станцій постійно намагаються не дати щурам перегризти кабелі чи заполонити платформи, часом покладаючись на мандрівників і щуроловів на кшталт Монті, щоб їх проредити.",al={"щури глибинного трамвая","чому щури в трамваї","проблема зі щурами"}},{q="Чи безкоштовний трамвай?",a="Так. Як відкритий громадський і військовий проєкт, який утримують уряди Айронфорджа й Стормвінда, трамвай ходить безупинно й безплатно для всіх громадян і союзників Альянсу.",al={"вартість трамвая","ціна квитка на трамвай","скільки коштує проїзд"}}},fp="12,410,36.774.0,31.306.0,36.317.0,44.293.0,25.192.0"}
P.entries["subzone:deepwater-tavern"] = {n="Таверна «Глибока Вода»",s="Таверна «Глибока Вода» — гамірний приморський заїзд Гавані Менетіл серед вогких боліт Багнокраю. Це головне місце зустрічей, поповнення припасів і відпочинку для мандрівників і моряків, що проходять жвавим портовим містечком. Між щедрими чарками й портовими чутками відвідувачі часто знаходять роботу — або потрапляють у бурхливі шинкові бійки.",h="Таверна «Глибока Вода» — гамірний приморський заїзд Гавані Менетіл серед вогких боліт Багнокраю.",kw={"таверна глибока вода","гавань менетіл","багнокрай","заїзд","моряки","бійка"},ang={["faction:Alliance"]="Таверна «Глибока Вода» — незамінне місце збору й відпочинку для членів Альянсу, що мандрують між Айронфорджем і відкритим морем."},sec={{t="Серце Гавані Менетіл",b="Таверна «Глибока Вода», що стоїть серед розмоклих вулиць Гавані Менетіл, дарує мандрівникам жаданий прихисток від вічно мрячних, підступних боліт за її стінами. Моряки, докери, купці й утомлені шукачі пригод збираються під її дерев'яними сволоками, щоб обмінятися новинами, погрітися біля вогню й залатати рани. Окрім звичних вигод портового заїзду, тут є свій наставник із першої допомоги та місцеві купці, що забезпечують тих, хто вирушає назустріч небезпекам боліт чи пливе за Велике Море. Атмосфера тут галаслива, а часом і небезпечна: суперечки через розлитий ель спалахують миттєво, а відомі забіяки на кшталт Тапоука «Сліма» Джана здатні зчинити бійку на всю таверну."}},faq={{q="Де Таверна «Глибока Вода»?",a="Таверна «Глибока Вода» — біля набережної Гавані Менетіл, головного портового містечка Багнокраю на західному узбережжі Каз Модану.",al={"де таверна глибока вода","розташування таверни глибока вода","корчма менетілу"}},{q="Які послуги є в таверні?",a="Окрім звичайного нічлігу й частування, у таверні є крамарі й наставник Першої допомоги, тож це важливе місце, де шукачі пригод, що мандрують болотами, поповнюють припаси й лікуються.",al={"послуги таверни глибока вода","наставники таверни менетілу","що є в таверні глибока вода"}},{q="Хто часто починає бійки в таверні?",a="Таверна славиться раптовими бійками, і часто їх розпалює підозрілий баламут Тапоке «Худий» Джан серед галасливих відвідувачів і моряків.",al={"бійка в барі менетіл","тапоке слім джан","хто починає бійки в таверні"}},{q="Чому в таверні так людно?",a="Гавань Менетіл — великі морські ворота, що з'єднують Каз Модан із Калімдором і північними портами. Як єдина велика корчма містечка, таверна приймає безперервний потік моряків, найманців і шукачів пригод з Альянсу, що прямують у Багнокрай.",al={"навіщо йти в таверну глибока вода","чому таверна глибока вода популярна"}}},fp="16,353,24.710.0,38.146.0,46.202.0,43.163.0,26.239.0"}
P.entries["subzone:defias-hideout"] = {n="Схованка Дефіасу",s="Схованка Дефіасу — непоказний занедбаний будинок на південному краю Мунбрука. Він зливається з довколишнім зруйнованим поселенням, але його горішній поверх ховає головний наземний вхід до розлогої підземної мережі Мертвих Копалень.",h="Схованка Дефіасу — непоказний занедбаний будинок на південному краю Мунбрука.",kw={"схованка дефіасу","мунбрук","мертві копальні","вхід","дефіас","вестфол"},ang={["class:Rogue"]="Схованка — справжній взірець потаємної оборони: сховавши вхід до величезної підземної фортеці в непримітному зруйнованому маєтку, Дефіас приховують свій справжній розмах від випадкових патрулів Стормвінда.",["faction:Alliance"]="Цей напіврозвалений маєток — парадні двері змови Едвіна Венкліфа, тож для шукачів пригод Альянсу, що прагнуть покласти край бунту Дефіас, він — важливий плацдарм."},sec={{t="Брама серед руїн",b="Для випадкового ока Схованка Дефіасу нічим не відрізняється від інших пограбованих садиб чи хат Мунбрука, де повно злиденних волоцюг і головорізів Дефіас. Проте її скромне нутро приховує нервовий центр південних операцій Едвіна Венкліфа. Піднявшись на горішній поверх, можна знайти отвір, що веде просто вниз — у розлогий лабіринт Мертвих Копалень. Братство кидає основні сили на охорону околиць Мунбрука й на роботи глибоко під землею, тож саму схованку охороняють нечисленно: це радше пильно стережене вузьке місце, ніж діюча твердиня."}},faq={{q="Що в Схованці Дефіасу?",a="У будівлі є сходи до звивистого тунелю — наземного входу до Мертвих Копалень. Окрім бродяг і розкиданих розбійників, сама будівля здебільшого порожня й правує передусім за вхід під охороною.",al={"усередині схованки дефіасу","вхід у схованку","що тут є"}},{q="Чому всередині схованку майже не охороняють?",a="Братство Дефіас зосереджує бойові сили назовні, на вулицях Мунбрука, щоб перехоплювати непроханих гостей ще на підступах, а решта його робітників і громил зайнята роботою глибоко в копальнях.",al={"чому порожньо","де дефіас","чому так мало охорони"}},{q="Де в Мунбруку ця будівля?",a="Схованка — на південному краю Мунбрука на південному заході Вестфолу: це велика вціліла двоповерхова будівля біля підніжжя гір.",al={"як знайти схованку","де схованка дефіасу","розташування схованки"}},{q="Хто ці люди, що вештаються довкола схованки?",a="У будівлі й містечку довкола — розбійники Дефіас і зневірені бродяги, що зібралися в Мунбруку, тікаючи від злиднів чи пристаючи до Братства з нужди.",al={"хто такі волоцюги","волоцюги мунбруку","люди дефіасу"}}},fp="14,268,17.598.0,34.252.0,47.240.0,44.174.0,48.212.0"}
P.entries["subzone:demon-fall-canyon"] = {n="Каньйон Падіння Демона",s="Каньйон Падіння Демона — понівечена, вражена скверною ущелина на півдні Ашенвалю. Це легендарне поле бою, де Ґроммаш Хеллскрім і Тралл зійшлися з володарем безодні Манноротом і поклали край демонічному прокляттю крові, що ціле покоління тримало орків у рабстві.",h="Каньйон Падіння Демона — понівечена, вражена скверною ущелина на півдні Ашенвалю.",kw={"каньйон падіння демона","маннорот","ґроммаш хеллскрім","тралл","прокляття крові","скверна"},ang={["faction:Horde"]="Ця випалена земля священна для Орди: тут Ґроммаш Хеллскрім приніс найвищу жертву і тут нарешті було зламано кровне прокляття Палаючого Легіону.",["race:Orc"]="Кожен орк завдячує своєю свободою, і духовною, і тілесною, битві в цьому каньйоні, де Ґром віддав життя, щоб розбити демонічні кайдани свого народу."},sec={{t="Падіння Маннорота",b="Цей каньйон, що врізався в суворі південні околиці Ашенвалю поблизу Пагорба Вогню Скверни та Хребта Падіння Демона, несе тяжкі шрами Третьої війни. Саме тут вождь Тралл і ватажок Ґроммаш Хеллскрім вистежили володаря безодні Маннорота, щоб зламати його владу над Ордою. У запеклому двобої Маннорот повалив Тралла, та Ґром скористався нагодою й увігнав свою сокиру, Ґоргаул, просто в груди демонові. Пекельний вибух розірвав володаря безодні, забрав і життя Ґрома, але назавжди звільнив орків від решток демонічного рабства."},{t="Священна й небезпечна ущелина",b="Після загибелі Маннорота Орда назвала каньйон на згадку про останній бій Ґрома й звела неподалік пам'ятник на честь його спокути. Хоч володаря безодні знищено, його насильницька смерть вивільнила сиру демонічну силу, яка геть отруїла довколишню землю. Сьогодні каньйон досі просякнутий магією скверни й кишить ворожими дрібними демонами, тож будь-яке паломництво до цієї освяченої землі — небезпечна справа."}},faq={{q="Чому це місце зветься Каньйон Падіння Демона?",a="Каньйон назвала Орда на пам'ять про загибель володаря безодні Маннорота, що впав тут від руки Громмаша Хеллскріма.",al={"походження назви каньйону падіння демона","чому каньйон падіння демона","звідки така назва"}},{q="Що тут сталося між Ґромом і Манноротом?",a="Тралл і Ґром разом вийшли проти Маннорота. Тралла оглушили, але Ґром завдав смертельного удару сокирою. Шалений вибух демонічного вогню, що вирвався, коли загинув Маннорот, смертельно поранив Ґрома, і з останнім подихом він звільнив свій народ від кривавого прокляття.",al={"смерть ґрома","ґром проти манноротха","як загинув ґром"}},{q="Чому каньйоном досі блукають демони?",a="Коли загинув володар безодні Маннорот, страшний вибух демонічної енергії назавжди зіпсував дно каньйону, лишивши скверну, що приваблює й ховає нижчих демонів.",al={"чому демони в каньйоні падіння демона","монстри каньйону падіння демона","чому тут скверна"}},{q="Де пам'ятник Ґромові Хеллскріму?",a="Пам'ятник на честь Ґрома Хеллскріма стоїть неподалік, поблизу Каньйону Падіння Демона, — сюди приходять прочани з Орди вшанувати воїна, що звільнив їхній народ.",al={"де пам'ятник ґрому","пам'ятник хеллскріма","де могила ґрома"}}},fp="17,274,21.577.0,28.436.0,43.141.0,46.275.0,46.193.0,36.176.0"}
P.entries["subzone:demon-fall-ridge"] = {n="Хребет Падіння Демона",s="Хребет Падіння Демона — сплюндроване нагір'я на південному сході Ашенвалю, що височіє над каньйоном, де поліг Маннорот. Тут кишать дрібні демони й буяє згубна магія, а серце хребта — осквернене курганне лігво нічних ельфів, яке захопив Палаючий Легіон.",h="Хребет Падіння Демона — сплюндроване нагір'я на південному сході Ашенвалю, що височіє над каньйоном, де поліг...",kw={"хребет падіння демона","курганне лігво","діаторус шукач","жахолорд","демони","ашенваль"},ang={["class:Druid"]="Курганне лігво, колись священний притулок, пов'язаний зі Смарагдовим Сном, осквернене й захоплене демонами, тож цей хребет — образа для Кола Кенарія.",["class:Warlock"]="Силами скверни тут керує жахолорд, що й досі при владі, тож адепти темних мистецтв можуть побачити, як організовані рештки Легіону на Калімдорі."},sec={{t="Висота над скверною",b="Хребет Падіння Демона, що здіймається просто на захід від Каньйону Падіння Демона й над ним, досі заплямований рештками скверни з часів Третьої війни. Якщо каньйон унизу — місце згубного зіткнення Ґроммаша Хеллскріма з володарем безодні Манноротом, то це нагір'я стало плацдармом для демонічних загарбників, що вціліли. Дрібні демони патрулюють скелясті кручі, оскверняючи давній ліс і загрожуючи кожному, хто йде південним кордоном Ашенвалю."},{t="Осквернене курганне лігво",b="У схилі хребта висічене покинуте курганне лігво нічних ельфів, яке спорожніло й перетворилося на твердиню темного чаклунства. Замість сплячих друїдів підземні ходи кишать нечистю скверни. У найглибших надрах чатує Діаторус Шукач — хитрий жахолорд, що верховодить цим збіговиськом і спрямовує рештки демонів по всьому лісі."}},faq={{q="Де Хребет Падіння Демона?",a="Хребет Падіння Демона — на південному сході Ашенвалю. Він здіймається просто на захід і над Каньйоном Падіння Демона, біля межі з Пустками.",al={"розташування хребта","де хребет падіння демона","хребет демонів ешенвейл"}},{q="Чому на цьому хребті демони?",a="З хребта видно місце, де в Третій війні загинув володар безодні Маннорот. Демони, що пережили поразку Легіону, розбіглися навколишніми висотами й закріпилися на хребті та в покинутому курганному лігві.",al={"чому тут демони","демони хребта падіння демона","присутність палаючого легіону"}},{q="Хто очолює тутешніх демонів?",a="Збіговиськом на хребті командує Діаторус Шукач — могутній жахолорд-натрезім, що мешкає в найглибших закутках курганного лігва.",al={"хто тут бос","ватажок демонів","діатор шукач"}},{q="Що за споруда врізана в хребет?",a="Це давнє курганне лігво нічних ельфів. Колись святилище, де друїди поринали в Смарагдовий Сон, воно було покинуте, а згодом його захопив і осквернив Палаючий Легіон.",al={"курганне лігво","печера падіння демона","що за лігво"}}},fp="16,252,23.462.0,21.389.0,26.149.0,35.246.0,26.148.0,44.182.0"}
P.entries["subzone:demont-s-place"] = {n="Обійстя Демонта",s="Обійстя Демонта — зруйнована садиба на південному заході Вестфолу, трохи на захід від покинутого містечка Мунбрук. Колись тут була робоча ділянка, але ферма занепала разом із рештою краю, і її захопили свавільні агенти Братства Дефіас. Нині її вивітрені огорожі й порожні поля — ще одна жертва згаслого добробуту королівства.",h="Обійстя Демонта — зруйнована садиба на південному заході Вестфолу, трохи на захід від покинутого містечка...",kw={"обійстя демонта","вестфол","мунбрук","дефіас","ферма"},ang={["class:Rogue"]="Розлогі зруйновані ділянки довкола Мунбрука, зокрема Обійстя Демонта, відкривають неприкрашену картину беззаконної мережі, яку Братство Дефіас розкинуло по всьому краю.",["faction:Alliance"]="Для мандрівників Альянсу Обійстя Демонта — похмуре нагадування про те, як далеко порядок відступив із Вестфолу: колишні ниви тримають розбійники Дефіас просто під носом у королівства."},sec={{t="Зруйнована садиба",b="Обійстя Демонта, звідки видно Мунбрук і гниючі простори Мертвого Лану, колись було серед приватних родинних господарств, що годували Королівство Стормвінд. Господарський занепад і раптова поява розбійницьких ватаг позбавили ферму засобів до життя й вигнали її господарів. Як і сусідні поля, ділянка перетворилася на грубий сховок, де хазяйнують розбійники, що використовують занедбане подвір'я як продовження твердині Дефіас у Мунбруку."},{t="У лещатах Братства",b="Обійстя Демонта лежить зовсім поруч із Мунбруком, тож Братству Дефіас воно служить робочою заставою на околиці їхнього місцевого осередку. Головорізи, кишенькові злодії й робітники, що залишилися без роботи, тиняються між огорожами й розваленими будівлями, нападаючи на мандрівників, що збилися з південних доріг. Доки Мунбрук не повернуто, а розбійників не розбито, ця земля надто небезпечна, щоб сюди колись повернулося мирне хліборобство."}},faq={{q="Де Обійстя Демонта?",a="Обійстя Демонта — на південному заході Вестфолу, одразу на захід від покинутого містечка Мунбрук і неподалік отруєних полів Мертвого Лану.",al={"розташування обійстя демонта","де обійстя демонта","обійстя демонта на мапі"}},{q="Кому належить Обійстя Демонта?",a="Ферма, певно, належала поселенцеві на ім'я Демонт, перш ніж селянські заворушення й господарські негаразди прокотилися краєм. Її первісні мешканці давно втекли чи загинули, лишивши зруйновані наділи розбійникам.",al={"чиє обійстя демонта","хто такий демонт","власник ферми демонта"}},{q="Хто нині займає ферму?",a="Обійстя кишить членами Братства Дефіас, що використовують занедбану садибу як допоміжний пункт поза своєю базою в Мунбруку.",al={"хто в обійсті демонта","які вороги в обійсті демонта","монстри обійстя демонта"}},{q="Чи можна знову налагодити господарство на фермі?",a="За нинішніх умов — ні. Дефіас міцно засіли по всьому півдню Вестфолу, а Стормвінд не може виділити гарнізонних військ, тож обійстя надто небезпечне, щоб прості хлібороби його відбудували.",al={"чи можна відновити обійстя демонта","чи покинуте обійстя демонта"}}},fp="14,374,18.482.0,27.431.0,32.151.0,24.220.0,32.179.0,39.214.0"}
P.entries["subzone:den-of-flame"] = {n="Лігво Полум'я",s="Лігво Полум'я — укріплена печера в західній частині Багна Пилоброду, трохи на захід від Руїн Кам'яного Молота. Її збудували огри Кам'яного Молота як свій курган, але згодом печеру заполонило драконяче кодло чорних драконів, що служить Оніксії.",h="Лігво Полум'я — укріплена печера в західній частині Багна Пилоброду, трохи на захід від Руїн Кам'яного Молота.",kw={"лігво полум'я","багно пилоброду","кам'яний молот","огри","чорні дракони","оніксія","стяг"},ang={["faction:Horde"]="Огри Кам'яного Молота — присяжні союзники Орди; очистивши Лігво Полум'я від драконячого кодла й повернувши їхній клановий стяг, ви допоможете помститися за їхнє зруйноване поселення."},sec={{t="Захоплений курган",b="Лігво Полум'я, збудоване ограми Кам'яного Молота як головний курган і притулок, має безпомилкові ознаки огрячого мурування з грубо обтесаного каменю. Та коли чорні дракони сплюндрували поселення клану Кам'яного Молота, виводок не просто розігнав огрів — він захопив їхню твердиню собі. Нині чорні драконороди патрулюють палаючі околиці й вхід до печери в тіні сусіднього лігва Оніксії. Попри навалу, всередині досі лишаються сліди колишніх господарів, зокрема покинутий у метушні стяг клану Кам'яного Молота."}},faq={{q="Для чого спершу збудували Лігво Полум'я?",a="Споруду збудували огри Кам'яного Молота як головний курган свого клану. Її кладка й планування повторюють класичну архітектуру огрських кланів.",al={"хто збудував лігво полум'я","походження лігва полум'я","курган огрів пилотрясини"}},{q="Чому в цьому кургані кишать чорні драконороди?",a="Велика чорна драконка Оніксія влаштувала лігво на болоті неподалік. Її драконороди вигнали огрів Кам'яного Молота з їхнього поселення й зробили з печери передову заставу виводку.",al={"чому тут дракони","хто живе в лігві полум'я","драконороди пилотрясини"}},{q="Чи можуть огри Кам'яного Молота повернути печеру?",a="Уцілілі огри Кам'яного Молота, що тепер мешкають у Селі Папоротяної Стіни, досі вважають печеру священною землею. Вони шукають сміливих звитяжців, які зайшли б усередину й відбили в драконородів утрачений прапор клану.",al={"прапор кам'яного молота","повернення лігва"}}},fp="12,257,17.590.0,47.161.0,45.194.0,41.210.0"}
P.entries["subzone:dire-maul"] = {n="Лютопащ",s="Лютопащ — це руїни Елдре'Таласу, прадавнього міста Високородних, захованого в глибині нетрів Фераласу. Колись його звели, щоб уберегти тайнознавчі секрети королеви Азшари, а тепер його розсипані майдани й височенні колізеї поділили між собою огри Ґордок, сатири-загарбники та зчахлі рештки ельфів, які колись про місто дбали.",h="Лютопащ — це руїни Елдре'Таласу, прадавнього міста Високородних, захованого в глибині нетрів Фераласу.",kw={"лютопащ","елдре'талас","шен'дралар","тортельдрін","іммол'тар","огри ґордунні","фералас"},ang={["class:Mage"]="У зруйнованих бібліотеках Шен'дралару лежать тайнознавчі трактати й секрети, збережені з часів до Великого Розколу, — їх стережуть привиди великих чародіїв.",["race:NightElf"]="Елдре'Талас — трагічний пам'ятник нестримній тайнознавчій гордині й угодам із демонами, які зламали прадавню Імперію калдореїв."},sec={{t="Елдре'Талас і Великий Розкол",b="Дванадцять тисяч років тому Елдре'Талас був дивовижним оплотом улюблених чародіїв королеви Азшари — Шен'дралару. Коли під час Великого Розколу Колодязь Вічності зруйнувався, Принц Тортельдрін сплів магічний бар'єр, що вберіг місто від загибелі. Відрізані від джерела магії, уцілілі Високородні ув'язнили під своїм святилищем велетенського демона Іммол'тара й тисячоліттями висмоктували з нього скверну, щоб підтримувати своє безсмертя й тайнознавчу силу."},{t="Поділені руїни",b="Століття самотності й згасання сили довели Принца Тортельдріна до божевілля: він вирізав більшість власних підданих, щоб жменька обраних привласнила рештки демонової енергії. Нині зовнішні квартали розлогого комплексу покинуті на поталу іншим загрозам. Огри Ґордунні захопили Майдан Ґордок і влаштовують на арені жорстокі гладіаторські бої, а Алззін Дикоформ зі своїми зіпсованими сатирами гноїть зсередини Квартал Кривого Лісу."}},faq={{q="Як спершу звався Лютопащ?",a="Спершу Лютопащ був Ельдре'Таласом — розкішним містом нічних ельфів, яке дванадцять тисяч років тому звела секта Шен'дралар, щоб уберегти найцінніші тайні знання королеви Азшари.",al={"первісна назва лютопаща","історія ельдре'таласу","хто збудував лютопащ"}},{q="Хто нині живе в Лютопащі?",a="Комплекс розколовся на кілька ворожих частин. Огри Ґордунні під проводом Короля Ґордока тримають північний майдан, сатири й зіпсовані деревні кишать у східних садах, а нечисленні рештки відлюдних чаклунів-Високородних насилу виживають у західних святилищах.",al={"хто в лютопащі","мешканці лютопаща","які монстри в лютопащі"}},{q="Як місто пережило Розкол?",a="Коли під час Великого Розколу континент розірвало, Принц Тортельдрін і його маги наклали могутні захисні чари, що вберегли Ельдре'Талас від руйнування, яке поглинуло навколишню імперію.",al={"як ельдре'талас пережив розкол","щит розколу лютопащ","чому не зруйнували"}},{q="Чому тутешні Високородні користуються демонічною енергією?",a="Коли Колодязь Вічності знищили, Шен'дралар тяжко страждали без тайної магії. Щоб зберегти силу й безсмертя, вони ув'язнили демона Іммол'тара й живилися його есенцією.",al={"імоль'тар лютопащ","чому шен'драляри висмоктують демона","демон у лютопащі"}},{q="Що відбувається на арені Лютопаща?",a="Відкритий амфітеатр у центрі міста, відомий як Паща, огри й наглядачі рабів використовують як бійцівську яму для гладіаторських турнірів, кривавих розваг і поєдинків за трон Ґордока.",al={"колізей лютопаща","мол пвп","гладіатори лютопаща"}}},fp="9,341,36.477.0,14.450.1,37.180.0,27.271.0,39.213.0,48.201.0,39.192.0"}
P.entries["subzone:direforge-hill"] = {n="Пагорб Лютокузні",s="Пагорб Лютокузні — скелясте узвишшя на північному сході Багнокраю, на південний схід від Дун Модра й на північний схід від Зеленого Пояса. На його схилах стоїть ворожий табір, яким командує чорнокнижник дворфів Темного Заліза Балґарас Мерзенний.",h="Пагорб Лютокузні — скелясте узвишшя на північному сході Багнокраю, на південний схід від Дун Модра й на...",kw={"пагорб лютокузні","балґарас мерзенний","темне залізо","дун модр","табір","багнокрай"},ang={["class:Druid"]="Друїдам, що мандрують Багнокраєм, доводиться зважати на ворожий табір Темного Заліза на Пагорбі Лютокузні.",["race:Dwarf"]="Для дворфів-Бронзбірдів з Айронфорджа бачити, як підступність клану Темного Заліза розповзається Багнокраєм — надто під проводом таких чорнокнижників, як Балґарас, — обурення, на яке треба відповісти холодною сталлю."},sec={{t="Твердиня темних чарів",b="Пагорб Лютокузні — великий табір Темного Заліза на північному сході Багнокраю. Балґарас Мерзенний, чорнокнижник дворфів Темного Заліза, командує ворожими дворфами, що зайняли пагорб на південний схід від Дун Модра."},{t="Загроза Багнокраю",b="Дворфи Темного Заліза, що засіли на Пагорбі Лютокузні, загрожують мандрівникам на північному сході Багнокраю. Ворожим табором командує Балґарас Мерзенний."}},faq={{q="Де Пагорб Лютокузні?",a="Пагорб Лютокузні — на північному сході Багнокраю. Він лежить на південний схід від Дун Модра, трохи на північний схід від пишного Зеленого Пояса й на північний захід від скелястих круч Кряжа Рапторів.",al={"розташування пагорба лютокузні","де пагорб лютокузні","лютокузня багнокрай"}},{q="Хто нині контролює Пагорб Лютокузні?",a="Пагорб захопили ворожі дворфи Темного Заліза під командуванням чорнокнижника Балґараса Мерзенного. Вони укріпили висоту барикадами, вартовими вежами й вогняними ямами.",al={"хто на пагорбі лютокузні","хто живе на пагорбі лютокузні","монстри пагорба лютокузні"}},{q="Чим Пагорб Лютокузні важливий для Багнокраю?",a="Пагорб — ворожий табір Темного Заліза на північному сході Багнокраю. Балґарас Мерзенний і його дворфи загрожують мандрівникам по всій окрузі.",al={"чому пагорб лютокузні важливий","загроза лютокузні","що діється на пагорбі лютокузні"}},{q="Хто такий Балґарас Мерзенний?",a="Балґарас Мерзенний — дворф-чорнокнижник Темного Заліза, що командує силами на Пагорбі Лютокузні. Його зіпсоване чаклунство й агресивна присутність на пагорбах роблять його першочерговою ціллю для захисників болотяного краю.",al={"балґарас","балґарас мерзенний історія","хто такий балґарас"}}},fp="14,211,25.198.0,26.159.0,32.191.0,38.180.0,50.155.0,25.212.0"}
P.entries["subzone:dolanaar"] = {n="Доланаар",s="Доланаар — тихе поселення нічних ельфів у центрально-східному гіллі Тельдрассила. Розташоване на південний захід від Тінедолу, воно стає першим справжнім містечком, яке бачать молоді калдореї, залишивши захищені землі навчання. Тут збираються слідопити, друїди й ремісники, щоб скеровувати новачків і давати раду дивним недугам, що насуваються на Світове Дерево.",h="Доланаар — тихе поселення нічних ельфів у центрально-східному гіллі Тельдрассила.",kw={"доланаар","поселення","нічні ельфи","тельдрассил","перехрестя","навчання"},ang={["class:Druid"]="Доланаар — важлива зупинка для посвячених, які шукають настанов щодо недуг Тельдрассила й учаться налаштовувати свій дух на природну рівновагу.",["race:NightElf"]="Для молодих нічних ельфів Доланаар — перші кроки в ширший світ, випробування їхніх обітниць берегти природу, коли вони бачать, як росте скверна на Світовому Дереві."},sec={{t="Перехрестя гілля",b="Доланаар, що лежить під пишною кроною на південний захід від Тінедолу, — важливе перехрестя для мандрівників Тельдрассила. Збудований у традиційній манері нічних ельфів, він гармонійно вплітає свої оселі й помости в ліс. Селище дає новачкам перше повне навчання в ремеслах, бойовому мистецтві й природних уміннях і стоїть на дорозі до столиці — Дарнасуса. Завдяки центральному розташуванню звістки про зіпсуту живність, агресивних фурболгів і нечистий мох із довколишнього гілля неминуче потрапляють до ради Доланаара."}},faq={{q="Навіщо Доланаар?",a="Доланаар — головний осередок завдань і застава для молодих нічних ельфів, що покидають початкові землі Тінедолу. Це адміністративна застава на сході Тельдрассила, де є ремісники, наставники бойових і магічних мистецтв і зв'язок зі столицею.",al={"що таке доланаар","призначення доланаара","чим важливий доланаар"}},{q="Де Доланаар?",a="Доланаар — у центрально-східній частині Тельдрассила, за кілька хвилин ходьби стежкою на південний захід від Тінедолу й на схід від столиці, Дарнасуса.",al={"розташування доланаара","де доланаар","як дійти до доланаара"}},{q="Як мандрівникам звідси дістатися до Дарнасуса?",a="У Доланаарі немає власного повітряного шляху. Мандрівники йдуть лісовою дорогою на захід через Тельдрассил і пішки доходять до брами Дарнасуса.",al={"поїздка в дарнасус","майстер польотів доланаара","з доланаара до дарнасуса"}},{q="Які загрози чатують на Доланаар?",a="Ліс довкола Доланаара потерпає від дивної скверни, що підкрадається до Тельдрассила: поблизу з'являються хворі звірі, навіжені деревляники й ворожі племена фурболгів.",al={"біда в доланаарі","проблеми доланаара","завдання доланаара"}}},fp="8,383,22.588.0,32.257.0,26.158.0,44.137.0,29.176.0"}
P.entries["subzone:dor-danil-barrow-den"] = {n="Курганне Лігво Дор'Даніл",s="Курганне Лігво Дор'Даніл — давнє святилище нічних ельфів, висічене в землі центрального Ашенвалю, на південь від Застави Розщепленого Дерева. Колись тут тихо спочивали друїди, чиї духи мандрували Смарагдовим Сном, але після втручання Відступників, які відтяли духи сновидців від тіл, у лігві запанував жах.",h="Курганне Лігво Дор'Даніл — давнє святилище нічних ельфів, висічене в землі центрального Ашенвалю, на південь...",kw={"дор'даніл","курганне лігво","друїди","відступники","смарагдовий сон","ашенваль"},ang={["class:Druid"]="Курганні лігва — священні місця єднання зі Смарагдовим Сном, тож катування друїдів у Дор'Даніл і руйнування їхнього розуму — непрощенне святотатство.",["race:Undead"]="Спотворені досліди в Дор'Даніл показують невситиму цікавість Відступників до межі між життям і смертю та до магії, що відтинає душу від тіла, — навіть на далеких полях битв Калімдору."},sec={{t="Осквернене святилище",b="Курганні лігва по всьому Калімдору — шановані святилища, де друїди нічних ельфів віками спали, мандруючи Смарагдовим Сном, поки їхні смертні тіла лежали в безпеці під землею. Коли Орда просунулася в Ашенваль, Дор'Даніл опинився глибоко в тилу ворога. Орки здебільшого не зважали на непритомних ельфів, але Відступники, нові союзники Орди, побачили в цьому нагоду. Їхні агенти пробралися в глибини й почали моторошні досліди, щоб відтяти сплячих друїдів від їхніх духів, — це розколювало розум сновидців і безнадійно зводило їх з глузду. Тепер у темних проходах кишать зловісні вбивці Відступників і люті, збожеволілі від мук духи друїдів, що вже не можуть повернутися до своїх тіл."},{t="Змучені охоронці",b="The corruption within Dor'Danil reaches deep into the subterranean tunnels, where three prominent druidic spirits wander in madness: Uthil Mooncall, Mavoris Cloudsbreak, and Taneel Darkwood. Alongside them stalks Darkslayer Mordenthal, a Forsaken agent found within the den. For night elves and allies of the Cenarion Circle, putting these anguished souls to rest is a grim mercy, while the ongoing Forsaken presence exposes the ruthless, morbid curiosity Sylvanas's agents bring to the conflicts of Kalimdor."}},faq={{q="Що таке Курганне Лігво Дор'Даніл?",a="Курганне Лігво Дор'Даніл — підземний прихисток нічних ельфів в Ашенвалі, на південь від Застави Розщепленого Дерева й на південний захід від Пагорба Вогню Скверни. Здавна тут спали в глибокому трансі друїди, що поринали в Смарагдовий Сон, поки їхні тіла були в безпеці.",al={"що це за місце","інформація про курганне лігво дор'даніл","дор'даніл історія"}},{q="Чому духи друїдів усередині ворожі й божевільні?",a="Агенти Відступників проникли в лігво, щоб проводити досліди на сплячих друїдах, і відірвали їхні духи від тіл. Мука від того, що їх розірвало між світом наяву й Сном, довела друїдів до лютого божевілля.",al={"чому друїди тут божевільні","чому духи злі","божевільні друїди історія"}},{q="Хто такий Убивця Темряви Морденталь?",a="Darkslayer Mordenthal is a Forsaken found deep inside the barrow den, among its undead occupants. His presence is known, but he is not identified as the director of the experiments.",al={"морденталь","хто ця нежить усередині"}},{q="Які помітні духи блукають у глибинах?",a="У нижніх залах блукають три помітні духи друїдів: Утіл Мункол, Маворіс Клаудсбрейк і Таніл Дарквуд. Усіх трьох відірвали від тіл, і тепер вони блукають темними тунелями в безкінечній люті.",al={"іменні вороги дор'даніл","іменні друїди всередині"}}},fp="20,320,22.716.0,23.509.1,29.256.0,52.229.0,29.181.0,39.206.0"}
P.entries["subzone:dormitory"] = {n="Гуртожиток",s="Гуртожиток — житловий сектор у занепалій технологічній столиці Гномреґані. Колись тут жили незліченні гноми-містяни, а тепер він задушений радіоактивними викидами й кишить лютими опроміненими трогами.",h="Гуртожиток — житловий сектор у занепалій технологічній столиці Гномреґані.",kw={"гуртожиток","гномреґан","троги","перфограф","радіація"},ang={["profession:Engineering"]="Навіть за цілковитого провалу біологічного стримування автоматичні термінали на кшталт «Матричного Перфографа 3005-Б» і далі бездоганно обробляють алгоритмічні перфокарти доступу.",["race:Gnome"]="Для кожного гнома вхід до Гуртожитку — особиста справа: колись це була ваша домівка, а тепер — опромінені руїни, захоплені тими самими бевзями, що вигнали вас звідси."},sec={{t="Захоплена домівка",b="Гуртожиток, що лежить одразу за камерами знезараження Чистої Зони, колись давав дах винахідникам, робітникам і родинам Гномреґана. Коли Великий Тінкер Меккаторк наказав аварійно випустити радіацію, щоб відбитися від навали трогів, цей густонаселений сектор став пасткою. Сьогодні його спільні зали й житлові відсіки цілком покинуті гномами — натомість тут хазяйнують мутовані троги, яким добре в радіоактивному мареві. Мандрівники, що спускаються до нижніх ярусів міста, мусять пробиватися крізь це трагічне нагадування про катастрофу, щоб дістатися нижньої частини Зали Шестерень."},{t="Термінали-перфографи",b="Серед покинутих житлових відсіків досі працюють рештки адміністративного апарату міста. Машини «Матричний Перфограф 3005-Б» обробляють перфокарти доступу. Ці термінали дають допуск до захищеніших терміналів даних глибше в Гномреґані, допомагаючи повернути важливі записи, покинуті гномами під час утечі."}},faq={{q="Для чого був Гуртожиток до падіння?",a="Гуртожиток правив за звичайне житло для численних винахідників, робітників Гномреґана та їхніх родин. Він був поруч із промисловими й громадськими секторами, тож гноми легко ходили між робочими місцями й нарами для відпочинку, доки отруйна радіація не затопила нижні коридори.",al={"що таке гуртожиток","призначення гуртожитку","хто тут жив"}},{q="Чому Гуртожиток кишить трогами?",a="Коли троги прорвалися в місто знизу, Великий Тінкер Меккаторк затопив місто отруйним газом, щоб їх знищити. Але замість того щоб викосити трогів, радіація змінила вцілілих: вони стали ще лютішими й цілком несприйнятливими до опроміненого середовища житлових кварталів.",al={"чому тут трогги","навала троггів у гуртожитку","опромінені трогги"}},{q="Куди веде Гуртожиток?",a="Гуртожиток — одразу за знезараженими шлюзами Чистої Зони, і він з'єднує верхні рівні з нижнім рівнем Зали Шестерень, тож це неминуче вузьке місце для кожного, хто пробивається глибше в Гномреґан.",al={"виходи з гуртожитку","куди йти з гуртожитку","зв'язки гуртожитку"}},{q="Що за машини Матричний Перфограф тут стоять?",a="Термінали Матричний Перфограф 3005-Б обробляють перфокартки доступу. Закодовані картки відкривають доступ до терміналів вищого рівня захисту, що дає змогу повернути важливі дані, лишені в Гномреґані.",al={"перфограф","матричний перфограф 3005-б","перфокарти"}}},fp="9,240,14.610.0,21.331.0,48.302.0,42.294.0,30.221.0,52.202.0"}
P.entries["subzone:drag"] = {n="Прохід",s="Прохід — гамірна, затінена вулиця, висічена в червоній скелі Оргріммара, що з'єднує Долину Сили з Долиною Честі й Долиною Мудрості. По всьому Дуротару її знають як серце торгівлі в столиці: уздовж стін каньйону тягнуться майстерні ремісників, крамарів і умільців. Тут же ховається печерний спуск до сумнозвісної Тіньової Розколини.",h="Прохід — гамірна, затінена вулиця, висічена в червоній скелі Оргріммара, що з'єднує Долину Сили з Долиною...",kw={"прохід","оргріммар","ремесла","торгівля","тіньова розколина","інженерія"},ang={["faction:Horde"]="Кожен мандрівник у столиці рано чи пізно ступає на Прохід, адже він з'єднує бойове осердя Оргріммара з громадськими й містичними кварталами.",["profession:Engineering"]="У Проході розташована «Механічна майстерня Ноґґа», де гоблінські умільці передають Орді креслення, вибухівку й особливі інженерні знання."},sec={{t="Вулиця ремісників",b="Прохід, що тулиться глибоко між червоними стінами каньйону Оргріммара, — торговельний хребет столиці Орди. Долина Сили зосереджена на військових зборах і управлінні, а в Проході вирує щоденне міське життя. Під навісами з високих скель і шкур вулиця сповнена запахів дубильних чанів, булькотіння алхімічних казанів і брязкоту механізмів умільців. Тут збираються майстри майже всіх ремесел, щоб працювати й навчати молодих шукачів пригод, — від шкірництва й кравецтва до гоблінських інженерних майстерень, як-от «Механічна майстерня Ноґґа»."},{t="Роздоріжжя тіней і ремесла",b="Окрім крамниць і лавок старого мотлоху, Прохід посідає непросте місце в суспільній географії Оргріммара. На стіні каньйону тут розташований охоронюваний вхід до підземної Тіньової Розколини. Тож Прохід — неминуче роздоріжжя, де чесні ремісники, шамани на шляху до Долини Мудрості й потаємні знавці темних мистецтв ходять пліч-о-пліч під тьмяними, курявими навісами каньйону."}},faq={{q="Для чого в Оргріммарі Прохід?",a="Прохід — головний торговий квартал Оргріммара. Тут наставники й постачальники для багатьох професій — алхімії, кравецтва, шкірництва, білування, накладання чарів та інженерії, — а також крамарі з усяким крамом і непотребом.",al={"призначення проходу","що таке прохід","які крамниці на проході"}},{q="Куди веде Прохід?",a="Ця вулиця-каньйон з'єднує Долину Сили на півдні з Долиною Честі на північному сході, а стежки ведуть і до Долини Мудрості. І головне — на західному схилі Проходу є спуск у тінисті печери Тіньової Розколини.",al={"зв'язки проходу","як дістатися до розколини тіней","куди веде прохід"}},{q="Хто такий Ноґґ?",a="Ноґґ — заповзятливий гоблін-інженер, що тримає на Проході Машинну Майстерню Ноґґа: він помітний наставник інженерії й постачальник штуковин для членів Орди.",al={"майстерня ноґґа","хто керує майстернею"}},{q="Чи всі наставники професій на Проході?",a="Більшість ремісничих і збиральних професій мають крамниці на нижніх і верхніх уступах Проходу, але не всі. Зокрема, міські ковалі й рудокопи воліють вогненні кузні Долини Честі.",al={"де наставники в оргріммарі","наставник першої допомоги прохід"}}},fp="4,367,26.607.0,33.442.0,39.260.0,25.291.0,12.177.0,48.213.0"}
P.entries["subzone:dragonmaw-gates"] = {n="Брами Драконячої Пащі",s="Брами Драконячої Пащі — низка грізних укріплень уздовж гірської дороги, що здіймається зі сходу Багнокраю. Зведені, щоб стерегти крутий підйом до гірської фортеці Ґрім Батол, ці важкі загорожі перекривають шлях на прокляті висоти дворфійських руїн.",h="Брами Драконячої Пащі — низка грізних укріплень уздовж гірської дороги, що здіймається зі сходу Багнокраю.",kw={"брами драконячої пащі","ґрім батол","драконяча паща","червоні дракони","душа демона","багнокрай"},ang={["faction:Alliance"]="Альянс пильно стежить за брамами, знаючи, що все, що вийде з високої дороги, загрожує стабільності всього Багнокраю.",["race:Dwarf"]="Для дворфів брами — замкнений поріг Ґрім Батола, прадідівського дому, покинутого після Війни Трьох Молотів і згодом оскверненого орками Драконячої Пащі."},sec={{t="Вартові Ґрім Батола",b="Врізані в скелясті вершини на сході Багнокраю, Брами Драконячої Пащі замикають звивисту дорогу, що здіймається в гори до Ґрім Батола. Названі на честь орківського клану Драконячої Пащі, що тримав дворфійське гірське місто під час Другої війни, ці оборонні загорожі досі лишаються добре укріпленими заставами. Кожен, хто спробує піднятися на висоти, мусить зважати на небезпеки перевалу, де могутні дракони й похмурі нагадування про темну історію клану досі кидають довгу тінь."},{t="Спірний поріг",b="Хоча після знищення Душі Демона орків Драконячої Пащі розбили й розпорошили, гірська стежка лишається надзвичайно небезпечною. Довкола брам, на звивистих схилах і скельних сідалах, бачили могутніх червоних драконів. Між жахливими драконами й рештками клану Драконячої Пащі, що причаїлися на сусідніх пагорбах, брами стоять міцною перепоною для кожного мандрівника, якому вистачить зухвалості піднятися на висоти."}},faq={{q="Куди ведуть Брами Драконячої Пащі?",a="Брами перекривають звивисту гірську стежку, що з Багнокраю піднімається на схід просто до проклятого міста-фортеці Ґрім Батол і навколишніх гірських висот.",al={"шлях за брамами драконячої пащі","що за брамами драконячої пащі","дорога за брамами"}},{q="Чому вони звуться Брами Драконячої Пащі?",a="Вони названі на честь клану орків Драконячої Пащі, що в Другій війні захопив сусідню дворфійську твердиню Ґрім Батол і мерзенним чаклунством поневолив червоних драконів.",al={"чому брами драконячої пащі","назва брам драконячої пащі","орки драконячої пащі багнокрай"}},{q="Чи можуть мандрівники пройти крізь брами?",a="Величезні брами міцно зачинені й добре охороняються, тож звичайного проходу у високі гори немає.",al={"чи можна відкрити брами драконячої пащі","пройти крізь брами драконячої пащі"}},{q="Хто стереже дорогу біля брам?",a="На дорозі й сусідніх суворих перевалах лютують червоні драконороди й дракони, а ще — розпорошені орки й темні загрози, що досі чіпляються за гірські схили.",al={"хто біля брам драконячої пащі","дракони біля брам драконячої пащі","акстроз брами драконячої пащі"}}},fp="15,272,23.504.0,21.430.0,34.164.0,40.178.0,37.107.0,37.177.0"}
P.entries["subzone:dragonmurk"] = {n="Драконяча Мряка",s="Драконяча Мряка — розлогий небезпечний край на півдні Багна Пилоброду, де кишать чорні драконороди й дракончики. Оточений давніми руїнами огрів і випаленими печерами, він слугує ворожим зовнішнім кордоном виводку Оніксії.",h="Драконяча Мряка — розлогий небезпечний край на півдні Багна Пилоброду, де кишать чорні драконороди й...",kw={"драконяча мряка","багно пилоброду","чорні дракони","оніксія","детвінг","драконороди"},ang={["faction:Alliance"]="Терамор насторожено стежить за Драконячою Мрякою, знаючи, що неприборканий виводок чорних драконів так близько від фортеці легко може обернутися лихом.",["faction:Horde"]="Дракони Драконячої Мряки вигнали огрів Кам'яного Молота з їхнього села й постійно загрожують експедиціям Орди, що заходять углиб болота."},sec={{t="Виводок у болоті",b="Драконяча Мряка, що простягається південною глибиною Багна Пилоброду, позначає поріг, де вогкі болота поступаються володінням чорних драконів. Протоки й густа багнюка тут кишать чорними вірмами, драконородами й ненажерливими дракончиками. Навколишній край тяжко постраждав від їхньої присутності: сусідні землі, як-от зруйноване село Кам'яного Молота й випалена печера, відома як Лігво Полум'я, цілком опинилися в лабетах драконів."},{t="Варта матері виводку",b="Зграї молодих драконів і вартових по всій Драконячій Мряці — не випадкові блукачі. Південь Багна Пилоброду — головне гніздовище Оніксії, доньки Детвінга, у Калімдорі. Вірми люто патрулюють трясовину, знищують зайд і захищають кладку і від розвідників Терамору, і від сусідніх таборів Орди."}},faq={{q="Що таке Драконяча Мряка?",a="Драконяча Мряка — південна частина Багна Пилоброду, де кишать дракончики, дракони й драконороди чорного драконячого роду.",al={"що таке драконяча мряка","де драконяча мряка","розташування драконячої мряки"}},{q="Чому тут стільки чорних драконів?",a="На півдні Багна Пилоброду — лігво Оніксії, матері виводку чорного драконячого роду. Драконяча Мряка — захисна смуга, де її нащадки й слуги можуть гніздитися, дорослішати й відбиватися від зовнішніх загроз.",al={"чому чорні дракони в пилотрясині","хто веде драконів","оніксія дракони пилотрясини"}},{q="Які помітні місця поблизу Драконячої Мряки?",a="Драконяча Мряка охоплює й оточує важливі місця, зокрема Лігво Полум'я й Руїни Кам'яного Молота, — обидва захопили чорні драконороди.",al={"помітні місця драконячої мряки","що поруч із драконячою мрякою","місця навколо драконячої мряки"}},{q="Чи безпечна Драконяча Мряка для мандрівників?",a="Анітрохи. Драконове плем'я в Драконячій Мряці однаково вороже й агресивне, тож це одна з найнебезпечніших диких місцин на півдні Калімдору.",al={"чи небезпечна драконяча мряка","чи можна пройти через драконячу мряку"}}},fp="10,237,18.495.0,24.349.1,19.152.0,41.215.0,41.165.0,33.153.0"}
P.entries["subzone:dreadmaul-post"] = {n="Застава Дредмол",s="Застава Дредмол — укріплене поселення огрів серед випалених пустирів Спустошених Земель. Цей насип, зведений кланом Дредмолів, править за укріплену твердиню поблизу Темного Порталу, де огри осіли ще відтоді, як прийшли з Дренора. Мандрівникам, що проходять цим краєм, доводиться мати справу і з лютими громилами, і з підступною місцевістю довкола їхнього табору.",h="Застава Дредмол — укріплене поселення огрів серед випалених пустирів Спустошених Земель.",kw={"застава дредмол","огри","дредмоли","спустошені землі","темний портал","дренор"},ang={["faction:Alliance"]="Для розвідників Альянсу, що стежать за Темним Порталом, огри клану Дредмолів — небезпечна й жорстока загроза, яка ускладнює кожен патруль південними околицями континенту.",["faction:Horde"]="Хоча колись огри воювали пліч-о-пліч зі Старою Ордою, дикі клани на кшталт Дредмолів давно розірвали зв'язки з новим ладом Тралла й вважають усіх мандрівників ворожими загарбниками."},sec={{t="Спадщина Дренора",b="Коли десятиліття тому Орда ринула крізь Темний Портал, разом із нею в Азерот прийшли й клани огрів. Клан Дредмолів вирішив окопатися біля самої брами: огри насипали грубі кам'яні пагорби й земляні вали по всіх червоних пустирях Спустошених Земель. Застава Дредмол — одна з їхніх головних застав: огри міцно тримають довколишні безплідні землі й б'ються з блукаючими звірами та кожним мандрівником, якому вистачить дурості наблизитися до їхніх володінь."}},faq={{q="Хто живе на Заставі Дредмол?",a="На Заставі Дредмол живе клан огрів Дредмолів. Ці кремезні громили під час воєн прийшли з Дренору крізь Темний Портал і міцно закріпилися серед безлюдних скель Спустошених Земель.",al={"хто на заставі дредмол","мешканці застави дредмол","огри дредмол"}},{q="Чому огри досі в Спустошених Землях?",a="Після розпаду Старої Орди й закриття Темного Порталу чимало огрів розбрелося по Азероту. Але клан Дредмолів лишився біля місця, де вони прийшли, зробивши своїм домом поранені, безлюдні простори довкола приспаного розриву.",al={"чому дредмол тут","огри спустошених земель","чому огри біля порталу"}},{q="Хто ще никає біля застави?",a="Окрім самих огрів, червоною пустелею біля Застави Дредмол никають люті місцеві хижаки — скорпіди й василіски.",al={"дренеї спустошені землі","хто біля дредмолу","істоти застави дредмол"}}},fp="14,391,19.456.0,28.227.0,45.253.0,40.125.0"}
P.entries["subzone:dreadmaul-rock"] = {n="Скеля Дредмол",s="Скеля Дредмол — височенна скеля з лабіринтом печер серед вогняних пустирів Палаючих Степів. Це головна база огрів Вогняного Черева, які живуть у її звивистих підземних насипах.",h="Скеля Дредмол — височенна скеля з лабіринтом печер серед вогняних пустирів Палаючих Степів.",kw={"скеля дредмол","огри","вогняне черево","палаючі степи","печери"},ang={["faction:Alliance"]="Для сил Альянсу, що стережуть прикордонні перевали з Редріджу, агресивні огри Скелі Дредмол — постійна жорстока загроза одразу за північним хребтом.",["faction:Horde"]="Мандрівникам з Орди, що прямують через Пустки до Гори Блекрок, слід обережно обходити Скелю Дредмол, щоб не розлютити клан Вогняного Черева, який ревно береже свої землі."},sec={{t="Твердиня Вогняного Черева",b="Скеля Дредмол, що височіє над випаленими рівнинами Палаючих Степів, — масивне кам'яне утворення, поцятковане лабіринтом печер. Хоча назва натякає на можливий зв'язок з ограми Дредмолів зі Спустошених Земель, скелю міцно тримає клан Вогняного Черева. Ці грубі огри використовують верхні стежки, скелі й земляні насипи всередині як укріплений табір, панують над довколишнім пустирем і загрожують кожному, хто намагається пройти північними схилами до Шпиля Блекрок."}},faq={{q="Хто живе на Скелі Дредмол?",a="Скеля Дредмол — головна база огрів Вогняне Черево. Вони живуть і на зовнішніх скельних стежках, і в заплутаній системі печер усередині скелі.",al={"хто на скелі дредмол","монстри скелі дредмол","які огри на скелі дредмол"}},{q="Чому вона зветься Скеля Дредмол, якщо тут живуть огри Вогняне Черево?",a="Нині вершину контролює клан Вогняне Черево, але назва переконливо натякає, що колись вона належала клану огрів Дредмолів, які мають чималу присутність на півдні, у Спустошених Землях.",al={"чому дредмол","дредмол чи вогняне черево","зв'язок огрів дредмол"}},{q="Як влаштована скеля?",a="Скеля Дредмол складається з крутих зовнішніх підйомів, що в'ються схилом, і заплутаної мережі печер усередині, повної огрських курганів і осель.",al={"печери дредмолу","розташування піку дредмол","як пройти скелею дредмол"}},{q="Де Скеля Дредмол?",a="Вона в Палаючих Степах — помітне, схоже на гору, утворення на північ від стежки до Гір Редріджу й на схід від Гори Блекрок.",al={"розташування скелі дредмол","де скеля дредмол","огрова база палаючих рівнин"}}},fp="14,233,25.510.0,28.162.0,58.190.0,36.151.0,32.165.0"}
P.entries["subzone:dreadmist-den"] = {n="Лігво Жахливої Імли",s="Лігво Жахливої Імли — підземна печера під скелями Піку Жахливої Імли на півночі Пусток. Її контролює культ Палаючого Клинка: печеру постійно огортає моторошний червоний серпанок, а сама вона слугує святилищем для поклоніння демонам.",h="Лігво Жахливої Імли — підземна печера під скелями Піку Жахливої Імли на півночі Пусток.",kw={"лігво жахливої імли","палаючий клинок","демонське сім'я","культ","печера","пустки"},ang={["class:Warlock"]="Демонічні реліквії й неспокійна енергія скверни, які плекають у Лігві Жахливої Імли, привертають пильну увагу чорнокнижників, що прагнуть скористатися темними таємницями Палаючого Клинка.",["faction:Horde"]="Лігво Палаючого Клинка над Пустками — нестерпна небезпека для ближніх торгових шляхів і поселень, тож захисники Орди мають діяти негайно."},sec={{t="Лігво лихих тіней",b="Лігво Жахливої Імли ховається серед зубчастих схилів Піку Жахливої Імли й править культистам Палаючого Клинка за темне святилище. Усередині стоїть густа багряна пара, що огортає печеру моторошними сутінками. Далеко від пильного ока Орди на рівнинах унизу культ проводить у цих кам'яних тунелях мерзенні демонічні обряди, стереже свої блюзнірські реліквії й замишляє поширити скверну по всьому Калімдору."},{t="Демонське Сім'я",b="At the deepest heart of the cavern rests the Demon Seed, a prized artifact of fel power cherished by the cultists. It rests above the Altar of Fire and is connected to the Burning Legion. Ak'Zeloth prepares a power stone to disrupt that connection. For Horde scouts and aspiring warlocks tracking the Burning Blade's machinations, plunging into this den is a dangerous necessity to uncover the full reach of demonic infiltration in the Barrens."}},faq={{q="Що таке Лігво Жахливої Імли?",a="Лігво Жахливої Імли — система печер, схована в Піку Жахливої Імли на півночі Пусток. Це діючий осередок і місце обрядів членів зловісного культу Палаючого Клинка.",al={"лігво жахливої імли","що таке лігво жахливої імли","печера жахливої імли пустовища"}},{q="Звідки червона імла в лігві?",a="A red haze shrouds Dreadmist Den and the peak above it. Burning Blade cultists conduct demonic rites here, but the exact cause of the mist is not established.",al={"червоний серпанок жахливої імли","багряний туман пустовища","червона імла лігва"}},{q="Що за Демонське Сім'я всередині?",a="Демонське Сім'я — темний артефакт, що зберігається в глибині Лігва Жахливої Імли. Для культистів Палаючого Клинка воно надзвичайно цінне, бо правує за потужне осердя їхньої магії Скверни.",al={"демонське сім'я","що таке демонське сім'я","артефакт у лігві жахливої імли"}},{q="Чому Орді важлива ця печера?",a="Культ Палаючого Клинка відкрито поклоняється демонам і прагне підточити Орду зсередини Калімдору. Твердиня демонопоклонників так близько до Перехрестя й Оргріммара — постійна загроза безпеці Пусток.",al={"орда лігво жахливої імли","чому очищати лігво жахливої імли","орки палаючого клинка пустовища"}}},fp="13,246,23.449.0,14.444.1,22.180.0,40.158.0,36.165.0,40.244.0"}
P.entries["subzone:dreadmist-peak"] = {n="Пік Жахливої Імли",s="Пік Жахливої Імли — зубчаста безлюдна гора, що здіймається на північний захід від Перехрестя в Пустках. Оповитий неприродним багряним маревом, пік став відлюдним прихистком для демонічних культистів Палаючого Клинка.",h="Пік Жахливої Імли — зубчаста безлюдна гора, що здіймається на північний захід від Перехрестя в Пустках.",kw={"пік жахливої імли","палаючий клинок","сарілус фоулборн","змодлор","джайна праудмур","пустки"},ang={["class:Druid"]="Таурени-друїди з Табору Тауражо досліджують джерела води на Піку Жахливої Імли, намагаючись з'ясувати, які неприродні отрути гублять газелей та інших звірів рівнин.",["faction:Alliance"]="Агенти Альянсу, що діють поблизу Ашенвалю, простежують згубну магію, яка тримає осквернених водяних елементалів, просто до Сарілуса Фоулборна — заклинача-нежиті, що ховається на піку."},sec={{t="Кубло скверни",b="Пік Жахливої Імли, що височіє над посушливими саванами Пусток, вирізняється відчутним злом. Коли мандрівники піднімаються скелями, яскраве небо затуляє густий червонуватий серпанок — залишкове марево давнього демонічного прокляття. На вершині гори й у її підземних порожнинах таємно діє культ Палаючого Клинка, даючи прихисток чорнокнижникам, отруйникам і мерзенним греллам. Звідси культисти отруюють ближні підземні води й плетуть інтриги проти молодих сил, що встановлюють владу над центральним Калімдором."},{t="Сплетіння задумів",b="Окрім чорнокнижників та їхніх темних ритуалів у Лігві Жахливої Імли, пік приваблює й інших лиходіїв. Маг-ренегат із Відступників Сарілус Фоулборн отаборився на висотах, підкоряючи сили стихій, щоб осквернити духів води аж на півночі, в Ашенвалі. А коли дрібний демон Змодлор задумав розпалити відкриту війну між Ордою Тралла й Терамором, саме тут Леді Джайна Праудмур і Аеґвінн дали йому бій і вигнали цю сутність, запобігши згубній різанині."}},faq={{q="Чому повітря довкола Піку Жахливої Імли червоне й туманне?",a="Червонясто-помаранчевий туман, що оповиває пік, — залишковий морок давнього демонічного прокляття, який підтримують і посилюють мерзенні обряди тутешніх чорнокнижників Палаючого Клинка.",al={"червона імла жахливої імли","оранжевий туман піку жахливої імли","чому жахлива імла червона"}},{q="Хто контролює Пік Жахливої Імли?",a="Гору контролює культ Палаючого Клинка: культисти пильнують її стежки й стережуть Лігво Жахливої Імли внизу. Тут також засіли темні постаті, як-от маг-нежить ренегат Сарілус Фоулборн.",al={"хто живе на піку жахливої імли","вороги піку жахливої імли","палаючий клинок жахлива імла"}},{q="Що сталося тут між Терамором і Ордою?",a="Через три роки після Третьої війни дрібний демон Змодлор зробив Пік Жахливої Імли своєю базою, щоб розпалити ворожнечу між Ордою й Терамором. Леді Джайна Праудмур разом з Еґвінн вистежила змову аж сюди й вигнала демона, ледь відвернувши війну.",al={"джайна пік жахливої імли","змодлор жахлива імла","війна терамору в пустовищі"}},{q="Як дістатися до Піку Жахливої Імли?",a="Ідіть головною дорогою на північ від Перехрестя, доки вона не розгалузиться до Ашенвалю й Гір Кам'яного Кігтя. Поверніться на північний захід — побачите скелю, що нависає вгорі, — і підніміться спіральною стежкою її східним схилом.",al={"як дістатися до піку жахливої імли","розташування піку жахливої імли","шлях до жахливої імли"}}},fp="14,224,19.572.0,24.503.1,51.189.0,28.206.0,51.266.0,32.195.0"}
P.entries["subzone:dreadmurk-shore"] = {n="Берег Жахливої Мряки",s="Берег Жахливої Мряки — туманне узбережжя й розкидані острівці Багна Пилоброду, що тягнуться на північ до Пусток. Тут панують агресивні мурлоки-Багноплавці та морські звірі, а віднедавна ці підступні води стали схованкою для розбійників із Братства Дефіас, що зазнали корабельної аварії.",h="Берег Жахливої Мряки — туманне узбережжя й розкидані острівці Багна Пилоброду, що тягнуться на північ до...",kw={"берег жахливої мряки","багно пилоброду","братство дефіас","мурлоки","багноплавці","острів алказ","терамор"},ang={["class:Rogue"]="Відлюдні табори й затонулі уламки вздовж берега — чудова нагода вистежити таємний вантаж Дефіас і прослизнути повз лютих вартових-Багноплавців.",["faction:Alliance"]="Те, що вцілілі з Братства Дефіас з'явилися так близько від Терамору, свідчить про змову, яка сягає далеко за межі Вестфолу й прямо загрожує стабільності Альянсу в Калімдорі."},sec={{t="Підступне узбережжя",b="Берег Жахливої Мряки, що тягнеться північно-східним краєм Багна Пилоброду між Островом Терамор і Твердинею Північної Варти, — похмурий простір мулистих мілин, припливних калюж і туманних острівців. Узбережжя заполонило плем'я Багноплавців — войовничий клан мурлоків, що люто нападає на кожного, хто наближається до їхніх прибережних сіл. На мілинах нишпорять морські черепахи й водяні хижаки, тож узбережжям небезпечно пробиратися навіть без огляду на болота довкола."},{t="Лазутчики Дефіас",b="Окрім місцевих болотяних істот, узбережжя привернуло пильну увагу Терамору через людей-розбійників. Корабель Братства Дефіас зазнав лиха у водах між берегом і Островом Алказ, і розбійники опинилися на піску й острівцях. Поява цих злочинців зі Східних Королівств так близько від твердині Леді Джайни Праудмур — тривожна подія, що загрожує крихкій рівновазі сил у затоці."}},faq={{q="Де Берег Жахливої Мряки?",a="Берег Жахливої Мряки тягнеться північно-східним узбережжям Багна Пилоброду, обернений до Великого Моря, між околицями Острова Терамор і межею з Пустками біля Твердині Північної Варти.",al={"розташування берега жахливої мряки","де берег жахливої мряки"}},{q="Чому на цьому березі розбійники Дефіас?",a="Нещодавно в морі між Жахливою Мрякою й Островом Алказ розбився корабель Братства Дефіас. Уцілілі вибралися на берег і влаштували тимчасові табори на відлюдному пляжі й скелях, намагаючись підняти свій затонулий вантаж.",al={"дефіас у пилотрясині","чому тут дефіас","дефіас з розбитого корабля"}},{q="Що за мурлоки живуть на пляжі?",a="Узбережжя густо заселяє плем'я мурлоків Багноплавців. Вони звели грубі рибальські селища на піщаних косах і скелястих острівцях і люто стережуть свої володіння і від патрулів Терамору, і від прибульців із розбитого корабля.",al={"мурлоки мирплавників","мурлоки берега жахливої мряки"}},{q="Чи контролює Берег Жахливої Мряки Терамор?",a="Терамор формально має владу над землями довкола острова, але на Березі Жахливої Мряки фактично панує беззаконня. Його болотисті мілини надто дикі й кишать мурлоками та розбійниками, щоб вартові Леді Джайни Праудмур могли регулярно патрулювати.",al={"хто володіє берегом жахливої мряки","чи берег жахливої мряки альянсу"}}},fp="15,287,19.482.0,19.463.1,33.188.0,43.250.0,43.228.0,43.254.0"}
P.entries["subzone:dream-bough"] = {n="Віття Сну",s="Віття Сну — велетенське Велике Дерево на острові посеред Озера Джейдмір на півночі Фераласу. Виросле з паростка Нордрассіла, прадавнє дерево ховає таємничу браму, що з'єднує Азерот просто зі Смарагдовим Сном. Зелені дракони віддано стережуть це святилище й не підпускають непроханих гостей до його зеленого гілля.",h="Віття Сну — велетенське Велике Дерево на острові посеред Озера Джейдмір на півночі Фераласу.",kw={"віття сну","озеро джейдмір","нордрассіл","смарагдовий сон","зелені дракони","друїди","фералас"},ang={["class:Druid"]="Віття Сну — священна земля, живий міст між дикими краями Азерота й незайманим Смарагдовим Сном, за яким доглядає ваш орден.",["race:NightElf"]="Це велике дерево виросло з благословенного гілля Нордрассіла завдяки Колу Кенарія — і втілює давній обов'язок вашого народу плекати й захищати живу природу."},sec={{t="Гілка Нордрассіла",b="Віття Сну здіймається високо над лісовим наметом північного Фераласу — це найбільше дерево в краї. Його виростили друїди, послідовники верховного друїда Фандрала Стаґгелма, що садили живці зі Світового Древа Нордрассіла, аби закріпити силу природи по всьому континенту. Велетенський вартовий стоїть серед тихих вод Озера Джейдмір, а в його стовбурі відкривається природний портал — прямий поріг до незайманого Смарагдового Сну."},{t="Смарагдові вартові",b="Через зв'язок зі Смарагдовим Сном дерево пильно охороняє Зелений драконячий рід. Драконороди й дракони патрулюють береги Озера Джейдмір і підступи до могутнього стовбура. Хоч передусім це місце роздумів і сну для друїдів, що мандрують між світами, мандрівникам варто підходити обережно: зелені дракони мало кого з непроханих гостей терплять біля такого важливого порогу."}},faq={{q="Що таке Віття Сну?",a="Віття Сну — величезне Велике Дерево на острові посеред Озера Джейдмір на півночі Фераласу. Вирощене з живця Світового Дерева Нордрассіл, воно є святилищем із діючою брамою до Смарагдового Сну.",al={"дерево віття сну","що таке віття сну","дерево озера джеад'мір"}},{q="Хто посадив Віття Сну?",a="Дерево посадили друїди нічних ельфів, вірні Архідруїдові Фандралу Стаґгелму, з гілки, зрізаної з Нордрассіла, щоб поширити відновлювальну силу давнього Світового Дерева по всьому Калімдору.",al={"хто виростив віття сну","походження віття сну","дерево оленерога"}},{q="Чому тут зелені дракони?",a="Зелений драконячий рід — вічні вартові Смарагдового Сну. У стовбурі дерева — пряма брама до Сну, тож дракони та їхні родичі постійно вартують, щоб захистити портал від непроханих гостей.",al={"зелений дракон віття сну","дракони озера джеад'мір"}},{q="Чи можуть гравці увійти в портал до Смарагдового Сну?",a="Вир порталу в стовбурі веде просто до Смарагдового Сну, але для смертних шукачів пригод, що не сплять у фізичному світі, він непрохідний. Вільно перетинати його межу можуть лише могутні сплячі друїди й Зелений драконячий рід.",al={"чи можна скористатися порталом віття сну","вхід у смарагдовий сон ферала"}}},fp="11,346,22.452.0,20.423.0,24.222.0,28.197.0,33.227.0,52.242.0"}
P.entries["subzone:dreamer-s-rock"] = {n="Скеля Сновидця",s="Скеля Сновидця — відлюдне природне святилище глибоко в Печерах Стогонів, за Волаючим Яром. Тут спить друїд із нічних ельфів Наралекс, чиє шляхетне прагнення відродити Пустки натомість породило живе жахіття. Це водночас і священна підземна обитель, і осердя порчі, що спотворює довколишній підземний світ.",h="Скеля Сновидця — відлюдне природне святилище глибоко в Печерах Стогонів, за Волаючим Яром.",kw={"скеля сновидця","наралекс","обряд пробудження","мутанус пожирач","печери стогонів","учень наралекса"},ang={["class:Druid"]="Скеля Сновидця — похмуре застереження про небезпеки, що чатують у Смарагдовому Сні: вона показує, як легко сплячі жахи можуть спотворити шляхетні наміри.",["race:NightElf"]="Знайти під посушливими Пустками священну залу спочинку, схожу на підземні обителі друїдів, і побачити її оскверненою — тяжке нагадування про трагічний ризик, на який пішли Наралекс і його послідовники далеко від північних лісів Калімдору."},sec={{t="Сон Наралекса",b="Скеля Сновидця, що лежить у серці Печер Стогонів, — щось на кшталт імпровізованої підземної обителі друїдів. Саме тут друїд із нічних ельфів Наралекс поринув у глибокий транс, щоб дістатися підземних джерел і спрямувати Смарагдовий Сон у посушливий ґрунт Пусток. Та замість принести життя, його зв'язок перехопили темні сили. Жахіття, що спотворює його думки, тепер вихлюпується в цю залу наяву: воно калічить місцевих звірів, обертає його послідовників на отруйних Друїдів Ікла й виводить у світ живих страхітливих потвор."},{t="Обряд пробудження",b="Лише коли покінчено з порчею Володарів іклів, уцілілий Учень Наралекса може вирушити до Скелі Сновидця, щоб провести обряд пробудження. Це вкрай небезпечно: щойно лунає спів, жахіття, що досі тримає Наралекса, породжує страховиськ, аби втримати владу над його сплячим розумом. Вершина цих душевних мук — Мутанус Пожирач, мерзенна потвора, що постає просто з глибин підсвідомості сновидця, щоб пожерти всіх, хто прагне його звільнити."}},faq={{q="Хто спить на Скелі Сновидця?",a="Тут спить Наралекс, могутній друїд нічних ельфів. Він прийшов до Печер Стогонів, сподіваючись скористатися їхніми підземними водотоками, щоб повернути Пусткам буйне життя, але його єднання зі Смарагдовим Сном перехопили страхітливі жахіття.",al={"ельф що спить","хто тут спить","хто такий наралекс","особа сновидця"}},{q="Чому ця зала зветься Скеля Сновидця?",a="Залу названо на честь самого Наралекса — «Сновидця». Вона діє майже як традиційне курганне лігво нічних ельфів: тут спочиває його тіло, поки дух мандрує Сном.",al={"чому скеля сновидця","значення назви скелі сновидця","походження назви"}},{q="Що станеться, якщо спробувати розбудити Наралекса?",a="Коли Володарів Ікла переможено, уцілілий Учень Наралекса пробує провести обряд пробудження. Чим він скінчиться і з чим доведеться зіткнутися під час обряду, з'ясується, коли його проведуть.",al={"пробудження наралекса","ритуал учня","подія наралекса"}},{q="Чому послідовники Наралекса стали ворожими?",a="Коли єднання Наралекса обернулося жахіттям, темні видіння спотворили розум його послідовників. Зрікшись присяг Кенарію, вони прийняли зміїні подоби, ставши Друїдами Ікла, і фанатично боронять змучений, нескінченний сон свого вчителя.",al={"походження друїдів ікла","чому друїди злі","зіпсовані друїди"}}},fp="14,367,22.553.0,20.496.1,34.254.0,42.199.0,42.196.1,41.259.0"}
P.entries["subzone:drowned-reef"] = {n="Затоплений Риф",s="Затоплений Риф — підступна смуга прибережних вод біля південних скель Аратійського нагір'я. Під хвилями лежать прадавні затонулі руїни, які захопили ворожі наги Кинджалоспинів; схоже, вони вміють керувати припливами в затоці й наражають на небезпеку кораблі, що пропливають повз.",h="Затоплений Риф — підступна смуга прибережних вод біля південних скель Аратійського нагір'я.",kw={"затоплений риф","наги","кинджалоспини","бухта фалдіра","принц назджак","кораблі","ельфійські самоцвіти"},ang={["race:NightElf"]="Затоплені зали під рифом і скам'янілі самоцвіти на морському дні — сумне нагадування про імперію калдореїв, що десять тисяч років тому розкололася й пішла під воду під час Великого Розколу."},sec={{t="Цвинтар кораблів",b="Просто біля прихованого входу до Бухти Фалдіра Затоплений Риф став водяним цвинтарем для мореплавців. Під хвилями лежать розбиті кораблі, серед них «Дівоча примха» й «Дух Срібнолісся». Риф населяють наги Кинджалоспинів на чолі з Принцом Назджаком; схоже, вони вміють керувати припливами в затоці й прирікають на загибель команди, що шукають прихистку в бухті."},{t="Затонуле місто",b="Ті, хто досить сміливий чи нерозважливий, щоб пірнути в глибину, побачать затонулі споруди прадавнього ельфійського міста. Серед його потоплених руїн досі лежать скам'янілі ельфійські самоцвіти."}},faq={{q="Що таке Затоплений Риф?",a="Затоплений Риф — небезпечна морська місцина біля південного узбережжя Аратійського нагір'я, трохи від берега навпроти Бухти Фалдіра. Він відомий мілинами, об які розбиваються кораблі, і давніми руїнами, що ховаються під водою.",al={"затоплений риф","де затоплений риф","риф араті"}},{q="Чому тут стільки затонулих кораблів?",a="Риф небезпечний для кораблів, що ходять уздовж південного узбережжя нагір'я. Схоже, наги Кинджалоспинні вміють керувати припливами затоки, наражаючи на небезпеку команди, що шукають притулку в Бухті Фалдіра.",al={"чому кораблі тонуть","затонулі кораблі араті","безумство діви"}},{q="Хто контролює Затоплений Риф?",a="На рифі живе плем'я наг Кинджалоспинних, що оселилося в затоплених руїнах. Їхніми місцевими силами керує Принц Назджак, який велить полювати на моряків, що зазнали лиха, і боронити підводні володіння.",al={"хто керує нагами","принц назджак","наги кинджальні хребти араті"}},{q="Що за руїни затоплені під рифом?",a="На рифі — руїни давнього ельфійського міста, серед затоплених решток якого трапляються скам'янілі ельфійські самоцвіти.",al={"підводні руїни араті","ельфійські руїни затопленого рифу"}}},fp="12,261,20.358.0,15.177.0,25.229.0,40.187.0,30.228.0,46.108.0"}
P.entries["subzone:drowned-sacellum"] = {n="Затоплений Сакелум",s="Затоплений Сакелум — ельфійська святиня, що лежить під водою одразу за входом до Чорноглибинних Печер. Залиті солонуватою морською водою й обплетені корінням, що звисає зі склепіння, її потрощені мури тепер належать мурлокам і макрурам.",h="Затоплений Сакелум — ельфійська святиня, що лежить під водою одразу за входом до Чорноглибинних Печер.",kw={"затоплений сакелум","чорноглибинні печери","мурлоки","макрури","ставок аск'ар","елуна"},ang={["class:Druid"]="Могутнє коріння дерев досі пробиває кам'яне склепіння з поверхні — доказ, що природа живе навіть серед отруєних підземних вод.",["race:NightElf"]="Давня священна святиня, затоплена солоною водою й загиджена мурлоками, — гірке нагадування про спадщину калдореїв, втрачену під Зорамським Узмор'ям."},sec={{t="Затоплене святилище",b="Щойно мандрівники переступають поріг Чорноглибинних Печер, вони опиняються в Затопленому Сакелумі. Колись це була тиха підземна каплиця Елуни, але вона давно обвалилася в омиту морем безодню під узбережжям Ашенвалю. Озерця солоної води поглинають давні мармурові плити, порослі морськими зірками, а зі склепіння печери звисає могутнє коріння дерев. Єдине тьмяне світло в мороці дають темні мерехтливі вогники — вони освітлюють зруйновану кам'яну стежку, якою шукачам пригод доведеться обережно пройти, щоб дістатися Ставка Аск'ар глибше в храмовому комплексі."},{t="Кубло падальників",b="Давно покинутий доглядачами з нічних ельфів, Затоплений Сакелум перейшов до рук прибережних падальників. Зграї агресивних мурлоків і закуті в панцири макрури живуть пліч-о-пліч у каламутних водах і нападають на кожного, хто наважиться потурбувати їхні гнізда. Хоч темніші загрози культистів чатують нижче, у глибинах храму, саме ці хижаки — перший небезпечний рубіж оборони підземних руїн."}},faq={{q="Для чого спершу був Затоплений Сакелум?",a="Сакелум — невелика святиня чи каплиця без даху. За давніх часів, до Розколу, це було ельфійське місце поклоніння у великому підземному храмовому комплексі, присвяченому місячній богині Елуні.",al={"призначення затопленого сакелуму","що таке затоплений сакелум","історія сакелуму"}},{q="Які істоти живуть у цій частині печер?",a="Затоплені руїни займають здебільшого дикі мурлоки й макрури. Вони процвітають у солонуватих озерцях і гніздових ущелинах печери.",al={"монстри затопленого сакелуму","хто живе в затопленому сакелумі","істоти затопленого сакелуму"}},{q="Як пройти повз Затоплений Сакелум?",a="Мандрівникам доведеться обережно перестрибувати з напівзатоплених платформ на колони, що виринають із води й кришаться, щоб дістатися тунелю, який веде далі, до Ставка Аск'ар.",al={"як пройти затоплений сакелум","стрибок у затопленому сакелумі","шлях до ставка аскар"}},{q="Звідки світло в печері?",a="Тьмяне моторошне світло ллється від темних вогників, що ширяють серед товстого покрученого коріння, яке пробилося крізь склепіння з лісів Ашенвалю нагорі.",al={"чому світиться","вогники в затопленому сакелумі","освітлення затопленого сакелуму"}}},fp="16,230,21.592.0,17.434.0,50.210.0,48.149.0,46.172.0,45.165.0"}
P.entries["subzone:dry-hills"] = {n="Сухі Пагорби",s="Сухі Пагорби — порізаний північно-західний куточок Пусток, що притулився до передгір'їв Гір Кам'яного Кігтя. Всупереч назві, ця височина помітно зеленіша за посушливі рівнини внизу, проте має лиху славу через агресивних гарпій Відьмокрилих, що гніздяться на її скелях.",h="Сухі Пагорби — порізаний північно-західний куточок Пусток, що притулився до передгір'їв Гір Кам'яного Кігтя.",kw={"сухі пагорби","гарпії","відьмокрилі","серена бладфезер","раптори","пустки"},ang={["class:Hunter"]="Порізана височина — багаті мисливські угіддя, де повно прудких гієн-Гавкоікло, хижих косокігтів Сонцелуских і лютих гарпій.",["faction:Horde"]="Гарпії Відьмокрилі, що гніздяться на Сухих Пагорбах, постійно загрожують північним торговим артеріям, які з'єднують Перехрестя з Горами Кам'яного Кігтя й Ашенвалем, тож герої Орди мусять регулярно проріджувати їхні зграї."},sec={{t="Зелений прихисток для гарпій",b="Сухі Пагорби, що сховалися там, де посушливі рівнини здіймаються до Гір Кам'яного Кігтя, носять не надто влучну назву: зелених кущів і чагарників тут значно більше, ніж у вибілених сонцем саванах на півдні. Та цей буйний передгірний край не обіцяє мандрівникам безпеки. На кручах панують гарпії Відьмокрилі на чолі з матріархинею Сереною Бладфезер. З цих висот їхні загони кидаються вниз на каравани з припасами, що йдуть північною ділянкою Золотого Шляху, а в чагарниках гниють покинуті орківські укріплення й зламані облогові машини."},{t="Загроза для Перехрестя",b="Гарпії Відьмокрилі раз у раз вилітають із пагорбів, щоб грабувати торгові шляхи й допікати ближнім поселенням, тож Орда постійно платить винагороду за їхнє пір'я. Шукачі пригод, що заходять углиб скелястих ярів, натраплять не лише на добре захищені гнізда гарпій, а й на гієн-Гавкоікло і лютих рапторів Сонцелуских, що полюють по всьому нагір'ю."}},faq={{q="Чому вони звуться Сухі Пагорби, якщо тут так зелено?",a="Despite their name, the Dry Hills are noticeably greener than the surrounding Barrens. The origin of the name and the reason for this local contrast are not recorded.",al={"чому називаються сухі пагорби","сухі пагорби зелені","рельєф сухих пагорбів"}},{q="Хто живе на Сухих Пагорбах?",a="Пагорби майже цілком контролює плем'я гарпій Відьмокрилих на чолі із Сереною Бладфезер. Скелястими схилами никають і дикі звірі — Гавкоікло гієни й Сонцелускі раптори.",al={"хто на сухих пагорбах","мешканці сухих пагорбів","гарпії сухих пагорбів"}},{q="Чому Орду цікавить ця місцина?",a="Нападниці Відьмокрилих часто спускаються з пагорбів і грабують каравани з припасами на північному Золотому Шляху, тож командири Орди оголошують нагороди, щоб проредити гарпій і знищити їхніх ватажків.",al={"орда сухі пагорби","чому воювати з гарпіями","завдання сухих пагорбів"}},{q="Що за зруйновані вежі й катапульти посеред пагорбів?",a="They are the remains of an abandoned orcish outpost. The surviving structures do not establish its original mission or why it was deserted.",al={"орківська вежа сухі пагорби","покинуті катапульти сухих пагорбів","орківські руїни сухих пагорбів"}}},fp="9,319,25.579.0,24.388.0,48.166.0,27.189.0,41.214.0,68.139.0"}
P.entries["subzone:drygulch-ravine"] = {n="Яр Сухої Балки",s="Яр Сухої Балки — сувора прихована ущелина серед скелястих круч східного Дуротару. Потрапити сюди можна лише через непримітний печерний прохід із Каньйону Гострого Вітру або небезпечним стрибком згори. У цьому скелястому рові гніздяться гарпії Пилового Вітру, що загрожують сусіднім обозам із припасами.",h="Яр Сухої Балки — сувора прихована ущелина серед скелястих круч східного Дуротару.",kw={"яр сухої балки","ущелина","гарпії","пиловий вітер","припаси","каньйон гострого вітру","дуротар"},ang={["faction:Horde"]="Зачистка гнізд у яру й повернення вкрадених припасів допомагає убезпечити внутрішні торгові шляхи Дуротару від постійного розбою.",["race:Orc"]="Яр Сухої Балки — випробування витривалості на порубіжжі, де молоді орки доводять свою вправність у боротьбі з лютими гарпіями, що засіли на скелястих кручах батьківщини."},sec={{t="Розбійницький прихисток серед червоних скель",b="Глибоко врізаний у скелі на схід від Оргріммара, Яр Сухої Балки майже повністю відрізаний від звичайних мандрівників. Єдиний наземний доступ — тісний природний тунель, що веде з Каньйону Гострого Вітру. У цій захищеній западині, яку живить невелика річка, колись мирно жили орки, та дикі звірі й гарпії Пилового Вітру, які тут гніздяться, перетворили її на беззаконний закуток Дуротару. Крилаті падложерки влаштовують на крутих скелях гнізда для виводків і складають награбоване з обозів Орди, що проходять місцевими стежками."},{t="Скалка в боці Дуротару",b="Життя в Яру Сухої Балки давно хитке. Невдовзі після Третьої війни околицям загрожували громові ящери, що втекли з Громового Хребта, і про це попереджали Вождя Тралла в Оргріммарі. Нині головна небезпека — гарпії. Їхні матріархині люто боронять кладки яєць на високих уступах, тож розвідники Орди часто посилають молодих воїнів прорідити зграю, повернути награбовані торгові ящики й вирвати яр із пазурів гарпій."}},faq={{q="Як потрапити в Яр Сухої Балки?",a="Якщо не стрибати з високих скель нагорі й не вижити, єдиний наземний шлях — крізь невеликий вхід у печеру в сусідньому Каньйоні Гострого Вітру.",al={"вхід у яр сухої балки","як зайти в яр сухої балки","де печера до сухої балки"}},{q="Які істоти живуть у Яру Сухої Балки?",a="У яру панують гарпії Пилового Вітру: на скелястих уступах вони в'ють гнізда, відкладають яйця й ховають награбовані з караванів припаси.",al={"монстри яру сухої балки","що в ярі сухої балки","хто живе в сухій балці"}},{q="Чому Орді важливий цей яр?",a="Гарпії Пилового Вітру нападають на життєво важливі торговельні стежки Дуротара й ховають крадений вантаж в ущелині. Влада Орди на Гострому Пагорбі раз у раз посилає новобранців повертати припаси й проріджувати зграю.",al={"чому вбивати гарпій у сухій балці","завдання яру сухої балки","інтерес орди до сухої балки"}},{q="Чи нападали колись на яр громоящери?",a="Так. Через кілька років після Третьої війни розлючені громоящери вирвалися із сусіднього Громового Хребта й загрожували Яру Сухої Балки, тож місцеві орки мусили просити військової допомоги у Вождя Тралла в Оргріммарі.",al={"громоящери сухої балки","історія громоящерів сухої балки"}}},fp="15,284,31.536.0,25.467.0,36.152.0,39.141.0,42.189.0,43.203.0"}
P.entries["subzone:drywhisker-gorge"] = {n="Ущелина Сухих Вусів",s="Ущелина Сухих Вусів — скеляста розколина у східних горах Аратійського нагір'я, на північний схід від Гаммерфолла, застави Орди. Ущелину та її внутрішню печеру тримає ворожий клан кобольдів, що люто стереже багаті поклади руди й прадавні реліквії стихій, поховані глибоко під землею.",h="Ущелина Сухих Вусів — скеляста розколина у східних горах Аратійського нагір'я, на північний схід від...",kw={"ущелина сухих вусів","кобольди","кровокам'яна руда","мізраель","гаммерфолл","гірництво"},ang={["faction:Horde"]="Ворожі кобольди Сухих Вусів, що засіли просто за гірським хребтом від Гаммерфолла, — непередбачувана загроза на східному фланзі застави.",["profession:Mining"]="Гірники цінують печеру Сухих Вусів як єдине відоме джерело Малої Кровокам'яної Руди — щільного мінералу з багряними прожилками, що залягає глибоко в скелі, де кишать кобольди."},sec={{t="Нори у східних скелях",b="Ущелина Сухих Вусів, захована в гірських складках на схід від Гаммерфолла, — головний оплот кобольдів із клану Сухих Вусів. Кобольдів часто мають за звичайних шахтних шкідників, але Сухі Вуса в Аратійському нагір'ї закріпилися міцно. Вони з лютою впертістю стережуть свої підземні ходи, розробляють жили рідкісної Малої Кровокам'яної Руди й боронять глибини землі. Таке сусідство завдає постійного клопоту оркам із Гаммерфолла."},{t="Таємниці глибокої печери",b="Якщо заглибитися досить далеко за барикади, освітлені смолоскипами, і звивисті тунелі, печера відкриє таємницю, темнішу за звичайні кайла й свічки. Кобольди Сухих Вусів у союзі з велетенськими кам'яними гігантами нагір'я доглядають за згустками прадавньої земної магії. У самому серці печери лежить таємничий кам'яний уламок, у якому ув'язнено частку сутності Принцеси Мізраель — прадавньої істоти землі, прикутої під поверхнею."}},faq={{q="Хто живе в Ущелині Сухих Вусів?",a="В ущелині та її печерах живе клан кобольдів Сухих Вусів. Вони люто стережуть свої володіння від чужинців — і свої копальні, і давні реліквії, сховані всередині.",al={"мешканці ущелини сухих вусів","що в ущелині сухих вусів","хто керує ущелиною сухих вусів"}},{q="Де Ущелина Сухих Вусів?",a="Ущелина прорізає скелясті східні гори Аратійського нагір'я, просто на північний схід від поселення Орди Гаммерфолл. До входу в печеру веде крута стежка пагорбами на схід від застави.",al={"як дістатися до ущелини сухих вусів","де ущелина сухих вусів","де печера в араті"}},{q="Чим важлива печера всередині?",a="Окрім рідкісних покладів Малої Кровокам'яної Руди, у печері зберігається давній кам'яний уламок. У цій реліквії — частка ув'язненої сутності Принцеси Мізраель, могутньої підземної істоти.",al={"що в печері","таємниці печери сухих вусів","уламок мізраеля"}},{q="Чому кобольди в союзі з гірськими велетнями?",a="Клан Сухих Вусів пов'язаний із місцевими кам'яними велетнями: кобольди служать їм і стережуть земляні реліквії та стихійні частки, пов'язані з узами Принцеси Мізраель глибоко під Аратійським нагір'ям.",al={"кобольди й велетні","чому сухі вуса з велетнями"}}},fp="16,304,29.490.0,26.438.1,30.210.0,34.225.0,39.209.0,48.188.0"}
P.entries["subzone:dun-algaz"] = {n="Дун Алґаз",s="Дун Алґаз — укріплений гірський перевал і мережа тунелів, що з'єднують Лох Модан із Багнокраєм. За нього точилися бої ще в Другу війну, а нині цю важливу торгову артерію взяли в облогу орки Драконячої Пащі, перерізавши зручний шлях між землями Айронфорджа та Гаванню Менетіл.",h="Дун Алґаз — укріплений гірський перевал і мережа тунелів, що з'єднують Лох Модан із Багнокраєм.",kw={"дун алґаз","перевал","драконяча паща","лох модан","дворфи","друга війна"},ang={["faction:Alliance"]="Шлях крізь Дун Алґаз украй важливий для постачання Альянсу: він тримає сухопутну дорогу, що з'єднує порт Гавані Менетіл із Лох Моданом та Айронфорджем.",["race:Dwarf"]="Для дворфів Дун Алґаз — дорога предків, прорубана крізь хребет Каз Модану. Бачити, як орки Драконячої Пащі займають дворфійські бастіони й загрожують шляхам постачання до Гавані Менетіл, — і нестерпна образа, і нагальна загроза безпеці."},sec={{t="Вузьке горло між краями",b="Дун Алґаз старший за Війну Трьох Молотів: колись цим проходом Вайлдгаммери рушили на північ, коли їх вигнали з Айронфорджа. Перевал, глибоко врізаний у зубчасті вершини між Лох Моданом і Багнокраєм, складається з широких кам'яних тунелів, бастіонів і сторожових постів. Його стратегічне значення годі переоцінити: хто тримає Дун Алґаз, той контролює єдиний сухопутний шлях, що поєднує серце дворфійських земель із західним морем біля Гавані Менетіл."},{t="Відродження Драконячої Пащі",b="Під час Другої війни Стара Орда після поразки під Дун Модром відступила до Дун Алґазу й зробила його своїм останнім південним бастіоном проти військ сера Андуїна Лотара. Через роки Некрос Скаллкрашер сховав клан Драконячої Пащі в довколишніх печерах. Альянс на якийсь час відвоював перевал, але орки Драконячої Пащі знову захопили твердиню: дворфійські горяни відступили у верхні тунелі, а гірський коридор став для мандрівників смертельним випробуванням."}},faq={{q="Чому Дун Алґаз нині такий небезпечний?",a="Орки Драконячої Пащі спустилися з навколишніх гір і захопили нижній перевал і твердиню. Дворфійських горян відтіснили до верхнього перевалу біля Станції Алґаз, тож головна дорога кишить ворожими орками, що влаштовують засідки на мандрівників між Лох Моданом і Багнокраєм.",al={"чому орки в дун алґазі","орки дун алґазу","хто контролює дун алґаз"}},{q="Чому цей перевал такий важливий для дворфів?",a="Дун Алґаз — головний суходільний шлях, що з'єднує Айронфордж і Лох Модан із Гаванню Менетіл у Багнокраї. Гавань Менетіл — головні морські ворота між Каз Моданом і рештою земель Альянсу, тож Дун Алґаз — життєво важливий коридор для припасів, військ і торгівлі.",al={"важливість дун алґазу","чому айронфордж потребує дун алґаз"}},{q="Чи відіграв Дун Алґаз роль у Другій війні?",a="Так. Зазнавши поразки при Дун Модрі, Орда орків відступила через Долину Тандол і зробила Дун Алґаз оборонною твердинею. Сер Андуїн Лотар наказав штурмувати її, щоб вибити орків і прогнати з Каз Модану, але Альянсові не вдалося цілком викорінити Орду, і Дун Алґаз лишився однією з її останніх твердинь у краї.",al={"дун алґаз друга війна","андуїн лотар дун алґаз"}},{q="Що пов'язує Дун Алґаз із дворфами Вайлдгаммер?",a="Задовго до Другої війни, у давній Війні Трьох Молотів, дворфів Вайлдгаммер вигнали з Айронфорджа. Вони пройшли через Дун Алґаз на північ, у Багнокрай, і зрештою оселилися в Ґрім Батолі.",al={"вайлдгаммер дун алґаз","війна трьох молотів перевал"}}},fp="9,301,27.477.0,24.503.0,40.320.0,45.296.0,44.336.0,65.229.0"}
P.entries["subzone:dun-garok"] = {n="Дун Ґарок",s="Дун Ґарок — укріплений дворфійський гірський оплот на південно-східних висотах Передгір'я Гілсбреда. Під командуванням Капітана Айронгілла стійкий гарнізон застави боронить інтереси Альянсу в краї та ближні об'єкти на кшталт Шахти Лазурової Жили від ворожого наступу. Для Відступників Таррен Мілла ця вкорінена дворфійська твердиня — постійна військова загроза біля їхніх володінь.",h="Дун Ґарок — укріплений дворфійський гірський оплот на південно-східних висотах Передгір'я Гілсбреда.",kw={"дун ґарок","дворфи","капітан айронгілл","горяни","таррен мілл","гілсбред"},ang={["faction:Horde"]="Цей добре захищений дворфійський анклав становить постійну небезпеку для розширення Відступників і безпеки кордону довкола Таррен Мілла, тож його гарнізон — першочергова ціль.",["race:Dwarf"]="Дун Ґарок — гордий символ того, як далеко в Лордерон сягає Айронфордж: тут Капітан Айронгілл і його горяни непохитно боронять своїх союзників-людей."},sec={{t="Оплот у передгір'ї",b="Дун Ґарок, вирубаний у скелястих південно-східних пагорбах Передгір'я Гілсбреда, — добре укріплений редут айронфорджських горян і стрільців. Під командуванням Капітана Айронгілла дворфи тримають тут важливий оборонний рубіж, прикриваючи людські поселення Гілсбреда й захищаючи важливі роботи в Шахті Лазурової Жили. Міцна кам'яна архітектура й глибокі окопи дають Альянсові опору проти загроз поблизу."},{t="Ціль Таррен Мілла",b="Дун Ґарок лежить так близько від Таррен Мілла, що Відступники вважають його нестерпним вторгненням на свій південний кордон. Війська Сильвани Віндраннер ненавидять присутність добре озброєних дворфійських загонів так близько від своєї твердині й раз у раз замишляють проникнути до фортеці, зламати її оборону й знищити гарнізон Капітана Айронгілла, щоб утвердити владу Відступників над Гілсбредом."}},faq={{q="Що таке Дун Ґарок?",a="Дун Ґарок — укріплена дворфійська застава в південно-східних горах Передгір'я Гілсбреда. Тут стоять війська з Айронфорджа, що боронять володіння Альянсу в краї.",al={"розташування дун ґарока","що за дворфійська фортеця","дворфійський форт гілсбрада"}},{q="Хто командує Дун Ґароком?",a="Твердинею командує Капітан Айронгілл, що веде місцевих горян і стрільців на захист Гілсбреда й сусідньої Шахти Лазурової Жили.",al={"лідер дун ґарока","хто очолює дун ґарок","капітан айронгілл"}},{q="Чому Відступники хочуть знищити Дун Ґарок?",a="Відступники вважають діючу укріплену дворфійську твердиню просто на своєму південному кордоні серйозною загрозою для Таррен Мілла й завзято посилають агентів знищити гарнізон.",al={"чому орда нападає на дун ґарок","відступники дун ґарок","конфлікт таррен міл і дун ґарока"}},{q="Яку стратегічну цінність Дун Ґарок має для Альянсу?",a="Дун Ґарок — ключова військова опора в Гілсбреді: він допомагає Альянсові тримати край у безпеці й захищає сусідню Шахту Лазурової Жили від ворожого захоплення.",al={"чому дун ґарок важливий","призначення дун ґарока для альянсу"}}},fp="9,417,26.450.0,21.400.0,18.195.0,23.151.0,46.186.0,52.169.0"}
P.entries["subzone:dun-mandarr"] = {n="Дун Мандарр",s="Дун Мандарр — покинутий дворфійський табір перед крижаною печерою на південному сході Вінтерспрінгу. Його заснував дворф Джарон Стоуншейпер, та нині табір лежить у руїнах: мешканці втекли, коли на них ринули розлючені місцеві місячники.",h="Дун Мандарр — покинутий дворфійський табір перед крижаною печерою на південному сході Вінтерспрінгу.",kw={"дун мандарр","джарон стоуншейпер","амулет із синім пір'ям","місячники","дворфи","вінтерспрінг"},ang={["class:Druid"]="Місячники, що стережуть Дун Мандарр, ревно оберігають природні й небесні артефакти й шаленіють, коли чужинці тривожать священні реліквії на кшталт Амулета із синім пір'ям.",["race:Dwarf"]="Назва табору складена за давнім дворфійським звичаєм, а самі руїни суворо нагадують, як легко археологічні амбіції в давньому Калімдорі обертаються лихом."},sec={{t="Покинутий табір",b="Дун Мандарр, що має в назві традиційну дворфійську приставку «Дун», заснував дослідник Джарон Стоуншейпер як опорну базу в морозних краях південно-східного Вінтерспрінгу. Цікавість Стоуншейпера його й згубила: він натрапив на реліквію, відому як Амулет із синім пір'ям. Потривожений артефакт розлютив місцевих диких місячників, і ті в нестямному шалі налетіли на табір. Дворфи не встояли й покинули табір назавжди. Нині серед заметів не лишилося жодної привітної душі: печеру стережуть люті місячники, що ревно боронять свою територію й нишпорять між поламаними укриттями."}},faq={{q="Що сталося з табором у Дун Мандаррі?",a="Дун Мандарр збудував дворф-дослідник Джарон Стоуншейпер. Ведучи розкопки, він знайшов загадковий Амулет із Синім Пір'ям. Реліквія страшенно розлютила навколишніх диких місячників, і ті люто напали на поселення. Джарона й супутників прогнали, а заставу покинули й захопили.",al={"чому дун мандарр покинутий","хто збудував дун мандарр","що таке дун мандарр"}},{q="Чому тут стільки місячників?",a="Місцеві дикі місячники вважають печеру й реліквії довкола священними. Коли Джарон Стоуншейпер викопав Амулет із Синім Пір'ям, ці створіння впали в несамовитий шал, щоб повернути артефакт і захистити свої володіння, прогнали непроханих гостей і привласнили табір.",al={"чому тут місячники","дикі місячники дун мандарра","чому нападають дикі місячники"}},{q="Куди подівся Джарон Стоуншейпер?",a="Вигнаний зі свого табору розлюченими місячниками, Джарон Стоуншейпер відступив в інше місце Вінтерспрінгу, щоб перегрупуватися й пошукати допомоги, аби повернути викрадені записи й спорядження.",al={"де джарон стоуншейпер","розташування джарона стоуншейпера"}}},fp="11,236,15.618.0,41.324.0,35.280.0,31.182.0"}
P.entries["subzone:dun-modr"] = {n="Дун Модр",s="Дун Модр — прадавнє укріплене дворфійське містечко на півночі Багнокраю, що стереже південний підступ до Мосту Тандол. Колись важлива фортеця, яку утримували й за яку билися в кількох війнах, нещодавно впала під ударом ворожого війська дворфів Темного Заліза.",h="Дун Модр — прадавнє укріплене дворфійське містечко на півночі Багнокраю, що стереже південний підступ до...",kw={"дун модр","темне залізо","міст тандол","балґарас мерзенний","дворфи","багнокрай"},ang={["faction:Alliance"]="Падіння Дун Модра загрожує важливому шляху через Міст Тандол і розриває зручне сполучення між Айронфорджем і рештками Альянсу на півночі.",["race:Dwarf"]="Бачити, як славетне гірське поселення Бронзбірдів потрапило до рук віроломного клану Темного Заліза, — гірка образа, що вимагає помсти."},sec={{t="Спірний бастіон",b="Дун Модр, що стоїть на північному краю Багнокраю, панує над головним сухопутним шляхом, який поєднує Каз Модан із північними людськими королівствами. Через таке важливе розташування твердиня за десятиліття бачила чимало крові. Під час Другої війни Орда захопила дворфійську фортецю й окопалася в ній, зробивши її передовим плацдармом для нападів і відсічі арміям Альянсу. Воїни Стромґарда здійснили жорстокий десант із Тол Барада, щоб відвоювати її, але орки вдарили у відповідь, і почалося криваве перетягування. Зрештою сили Альянсу під проводом лорда Андуїна Лотара відкинули загарбників на південь, за Міст Тандол, і повернули бастіон дворфам."},{t="Вторгнення Темного Заліза",b="Увага Айронфорджа була розпорошена, а багато найкращих горян служили Альянсу в далеких краях, тож Дун Модр лишився беззахисним. Скориставшись нагодою, загарбники Темного Заліза просунулися на північ, підірвали Міст Тандол і накинулися на фортецю. Під проводом чорнокнижника Темного Заліза Балґараса Мерзенного вони здолали захисників містечка, вигнали гарнізон Бронзбірдів і перетворили стратегічну заставу на вороже лігво. Горяни тепер тримають похмуре кільце трохи нижче дорогою й відчайдушно шукають допомоги, щоб вибити загарбників."}},faq={{q="Чому Дун Модр такий важливий?",a="Дун Модр стоїть просто на великій північній дорозі Багнокраю до Мосту Тандол. Хто контролює фортецю, той контролює весь суходільний рух, шляхи постачання й пересування військ між Каз Моданом і північним континентом — Лордероном.",al={"чому дун модр важливий","значення дун модра","стратегічна цінність дун модра"}},{q="Хто нині контролює Дун Модр?",a="Твердиня впала під натиском клану Темного Заліза, яким на місці керує чорнокнижник на ім'я Балґарас Мерзенний. Горяни-Бронзбірди, вірні Айронфорджу, пильнують поблизу в таборі, сподіваючись її відвоювати.",al={"хто в дун модрі","хто керує дун модром","хто живе в дун модрі"}},{q="Що сталося з Дун Модром у Другій війні?",a="Орда орків захопила містечко й зробила з нього передову військову базу. Війська Стромґарда вдарили з острова Тол Барад, щоб відбити руїни, і спалахнули запеклі сутички, доки сили Альянсу Андуїна Лотара нарешті не вимели Орду з краю.",al={"друга війна дун модр","орки в дун модрі","чи орда взяла дун модр"}},{q="Хто такий Балґарас Мерзенний?",a="Балґарас Мерзенний — чорнокнижник Темного Заліза, що очолює захоплення Дун Модра. Під його командуванням дворфи Темного Заліза зуміли пошкодити Міст Тандол і вигнати з фортеці місцевих захисників з Айронфорджа.",al={"балґарас мерзенний історія","хто такий балґарас","ватажок темного заліза дун модр"}}},fp="8,249,19.711.0,23.604.0,29.258.0,32.197.0,48.257.0,25.208.0"}
P.entries["subzone:dunemaul-compound"] = {n="Поселення Дюнного Молота",s="Поселення Дюнного Молота — головна оселя клану Дюнного Молота в Танарісі, що зосереджена довкола огрівського кургану. Сховане серед скелястих гребенів на межі пустелі, воно дає притулок клановим громилам і заклиначам.",h="Поселення Дюнного Молота — головна оселя клану Дюнного Молота в Танарісі, що зосереджена довкола огрівського...",ang={["class:Warlock"]="Чорнокнижники Дюнного Молота серед, здавалося б, примітивного пустельного клану — дивне видовище: виходить, традиції тіні й скверни пустили коріння навіть у відлюдних огрівських курганах.",["faction:Horde"]="Хоча чимало огрів колись ішли в лавах Старої Орди, відлюдні огри Дюнного Молота не підкоряються жодній зовнішній силі й вважають мандрівників з Орди такими самими загарбниками, як і всіх інших."},sec={{t="Твердиня серед пісків",b="Поселення Дюнного Молота, видовбане в суворих пустельних скелях західного Танарісу, — головна твердиня огрів Дюнного Молота. Ці велетенські мешканці пустелі пристосувалися до спекотного посушливого клімату й виживають завдяки грубій силі та вмінню вхопити свій шанс. Серцем поселення є огрівський курган і мережа печер. Хоч клан і примітивний, він виставляє небезпечну суміш воїнів, громил і викривлених заклиначів, що практикують темну магію чорнокнижників і магів. Для мандрівників, які перетинають дюни, поселення — підступне кубло агресивних велетнів, що жорстоко проганяють непроханих гостей."}},faq={{q="Хто править Поселенням Дюнного Молота?",a="Gor'marok the Ravager leads the Dunemaul ogres occupying the compound. Andi Lynn in Gadgetzan fears the strength of this newly arrived band.",al={"dunemaul leader","dunemaul boss"}},{q="Які огри тут живуть?",a="У поселенні — найрізноманітніші огри Дюнного Молота: від звичайних громил і вишибал до хитрих огрів-магів і чорнокнижників, що володіють темною магією Скверни й тіні.",al={"види дюнного молота","монстри дюнного молота"}},{q="Чому Орду цікавить це поселення?",a="The Dunemaul are an independent band of ogres led by Gor'marok the Ravager. Andi Lynn in Gadgetzan seeks help against them, fearing that their growing strength will threaten the region.",al={"horde dunemaul"}},{q="Хто такий Омґорн Загублений?",a="Омґорн Загублений — невловимий самотній огр, якого часом бачать на околицях Поселення Дюнного Молота; він не схожий на звичайних вартових, що патрулюють курган.",al={"омґорн","рідкісний огр танаріс"}}},fp="17,212,25.602.0,32.140.0,30.169.0,45.185.0,23.165.0"}
P.entries["subzone:durnholde-keep"] = {n="Твердиня Дурнгольд",s="Твердиня Дурнгольд — зруйнована фортеця на схід від Таррен Мілла в Передгір'ї Гілсбреда. Колись тут був осередок орківських таборів для інтернованих, які тримав Альянс, і саме тут виріс як бранець-гладіатор Вождь Тралл. Нині фортеця лежить у руїнах, а в ній засіли злочинці Синдикату.",h="Твердиня Дурнгольд — зруйнована фортеця на схід від Таррен Мілла в Передгір'ї Гілсбреда.",kw={"твердиня дурнгольд","тралл","блекмур","синдикат","табори для інтернованих","гілсбред"},ang={["faction:Alliance"]="Колись наріжний камінь оборони й правосуддя Лордерона, нині зруйновані мури Дурнгольда — лише жалюгідне лігво злочинців і головорізів Синдикату.",["race:Orc"]="Зруйноване каміння Дурнгольда позначає горнило, де Вождь Тралл скинув кайдани, поклавши край десятиліттям орківської неволі й розпаливши відродження Орди."},sec={{t="Горнило неволі",b="Дурнгольд, збудований Альянсом, після Другої війни став штабом, що наглядав за південними таборами для інтернованих. Під командуванням честолюбного й продажного генерал-лейтенанта Еделаса Блекмура він був водночас адміністративною фортецею й гладіаторською ареною. Саме тут Блекмур виховав осиротілого малюка Ґо'ела, назвавши його Траллом і навчаючи битися заради розваги й наживи. З допомогою Тарети Фокстон Тралл утік з неволі, а згодом об'єднав розпорошені орківські клани під прапором нової Орди. Повернувшись до Дурнгольда, Тралл узяв фортецю в облогу, вбив Блекмура й закликав духів землі зруйнувати її стіни."},{t="У лабетах Синдикату",b="Відколи фортеця впала ще до Третьої війни, Твердиня Дурнгольд лишається пошрамованою купою каміння. У порожнечі, що утворилася після падіння Лордерона, на мурах знайшли прихисток розбійники-аристократи із Синдикату. Діючи з розбитого двору й веж, ці позбавлені маєтностей альтерацькі вельможі й головорізи полюють на мандрівників по всьому Передгір'ю Гілсбреда, перетворивши колишнє знаряддя воєнного стану на добре укріплене розбійницьке кубло."}},faq={{q="Чому Твердиня Дурнгольд у руїнах?",a="Тралл повернувся до Дурнгольда на чолі визволеної Орди, щоб здолати свого колишнього господаря — Генерал-лейтенанта Еделаса Блекмура. Убивши Блекмура, Тралл звернувся до духів землі, щоб зруйнувати фортецю, — аби вона ніколи більше не стала кліткою для його народу.",al={"хто зруйнував дурнгольд","що сталося з твердинею дурнгольд","чому дурнгольд зруйнований"}},{q="Хто нині займає Твердиню Дурнгольд?",a="Твердиню тримає Синдикат — угруповання вигнаної знаті Альтерака, що стала злочинцями. Вони використовують мури, що кришаться, як укріплений притулок, звідки грабують і нападають по всьому Гілсбреду.",al={"хто живе в дурнгольді","монстри дурнгольда","синдикат у дурнгольді"}},{q="Що пов'язувало Тралла з цим місцем?",a="Еделас Блекмур знайшов осиротілого орка ще дитиною й виростив його в Дурнгольді рабом. Тралла навчили тактики й змушували битися гладіатором на арені, доки він не втік за допомогою людської жінки на ім'я Тарета Фокстон.",al={"чи жив тут тралл","історія тралла в дурнгольді","чи був тралл тут в ув'язненні"}},{q="Для чого фортеця слугувала в Другій війні?",a="Окрім того що вона була твердинею Альянсу, тут була в'язниця. Під час війни тут тримали троля-воєводу лісових тролів Зул'джина, доки Оргрім Думхаммер не прорвався у фортецю, щоб його визволити.",al={"дурнгольд друга війна","для чого слугував дурнгольд"}}},fp="14,286,23.665.0,32.442.0,31.269.0,38.203.0,43.258.0,54.214.0"}
P.entries["subzone:dustbowl"] = {n="Пилова Улоговина",s="Пилова Улоговина — розлогий посушливий простір на північному заході Пустищ, між заставою Орди Карґат і центральною Долиною Ікол. Її обдувають шорсткі пустельні вітри; це суворий дикий край, де живуть падальники, хижі звірі й мандрівні елементалі. Тут же стоїть Табір Вурґ, тож мандрівники, що зважуються на подорож пустирем, часто проходять цими місцями.",h="Пилова Улоговина — розлогий посушливий простір на північному заході Пустищ, між заставою Орди Карґат і...",kw={"пилова улоговина","пустища","карґат","табір вурґ","койоти","елементалі"},ang={["faction:Horde"]="Пилова Улоговина лежить одразу за Карґатом — це перша відкрита дика місцина, яку мусять перетнути розвідники Орди, просуваючись на схід углиб Пустищ."},sec={{t="Випалене перехрестя",b="Пилова Улоговина простяглася північним заходом Пустищ: сухі балки, потріскана глина й невгамовні вітри, що здіймають задушливі хмари піску. Попри безплідний ландшафт, тут тримається витривала пустельна рослинність — чіпкі кактуси й поодинокі покручені дерева. Відкрита рівнина постійно загрожує мандрівникам без провідника: їм доводиться мати справу з хижими койотами, стерв'ятниками, що кружляють у небі, і живими кам'яними елементалями, народженими із суворої землі. Серед цих чагарників ховається Табір Вурґ — помітний орієнтир посеред безлюдного простору."}},faq={{q="Де Пилова Улоговина?",a="Пилова Улоговина займає північний захід Пустищ, просто між укріпленим табором Орди Карґат на заході й Долиною Ікол ближче до центру краю.",al={"розташування пилової улоговини","де пилова улоговина","пилова улоговина на мапі пустовиськ"}},{q="Які істоти никають Пиловою Улоговиною?",a="Тут никають люті койоти й кружляють стерв'ятники, що виглядають падло. Мандрівники натраплять і на небезпечних кам'яних елементалів, що блукають кам'янистими просторами.",al={"монстри пилової улоговини","хто живе в пиловій улоговині","звірі пилової улоговини"}},{q="Які помітні місця є в Пиловій Улоговині?",a="Найпомітніше поселення в Пиловій Улоговині — Табір Вурґ, видимий орієнтир серед посушливої пустелі між Карґатом і центральними рівнинами.",al={"табори пилової улоговини","табір вурґ пилова улоговина"}},{q="Чи виживає тут якась рослинність?",a="Попри сухий і суворий клімат, у Пиловій Улоговині є мізерна рослинність — здебільшого витривалі кактуси й поодинокі зів'ялі пустельні дерева, пристосовані до безплідного ґрунту.",al={"рослини пилової улоговини","рослинність у пиловій улоговині"}}},fp="8,379,19.578.0,30.195.0,35.165.0,41.143.0,36.165.0"}
P.entries["subzone:dustfire-valley"] = {n="Долина Пилового Вогню",s="Долина Пилового Вогню — сухий, продутий вітрами яр біля північного краю Палючої Ущелини. Це випалений поріг, що веде просто до укріпленої брами Каменетесного Проходу, який перекриває гірський шлях до Лох Модана.",h="Долина Пилового Вогню — сухий, продутий вітрами яр біля північного краю Палючої Ущелини.",kw={"долина пилового вогню","палюча ущелина","каменетесний прохід","брама","лох модан"},ang={["race:Dwarf"]="Для дворфів ця брама — добре укріплений чорний хід між безпечним Каз Моданом і підступними землями, де панує клан Темного Заліза."},sec={{t="Північна межа",b="Долина Пилового Вогню, захована на півночі Палючої Ущелини, — це їдкий попіл, крихкий камінь і голі стіни каньйону. Найпомітніше тут — грізна замкнена дворфійська брама, що запечатує Каменетесний Прохід. Через ці замкнені залізні двері звичайним мандрівникам зась іти прямо на північ, до Долини Королів і Лох Модана, тож долина лишається відрізаним глухим кутом посеред сірчаних згарищ."}},faq={{q="Куди веде брама в Долині Пилового Вогню?",a="Брама перекриває Каменетесний Прохід — гірський шлях, висічений крізь висоти до Долини Королів у Лох Модані.",al={"брама долини пилового вогню","замкнені двері пилового вогню","куди веде перевал стоунврот"}},{q="Чи можна відчинити браму до Лох Модану?",a="Браму міцно замкнено дворфійською майстерністю, щоб захистити землі Лох Модану від загроз Палючої Ущелини. Щоб пройти, потрібен особливий ключ.",al={"як відчинити браму","відчинити перевал стоунврот","ключ від брами пилового вогню"}},{q="Чому ця місцина зветься Долиною Пилового Вогню?",a="Назва відбиває задушливу суміш вулканічного попелу, сухого пилу й невгасимої спеки, що панує в цьому каньйоні біля північних гірських стін.",al={"назва долини пилового вогню","чому пиловий вогонь"}}},fp="15,239,21.426.0,44.119.0,36.169.0,40.152.0"}
P.entries["subzone:dustwallow-bay"] = {n="Затока Пилоброду",s="Затока Пилоброду — рукав Великого Моря між вологим узбережжям Багна Пилоброду й укріпленим портом Острова Терамор. Її солонуваті прибережні мілини кишать морською живністю, а підступні обмілини й відлюдні бухти лежать осторонь головних морських шляхів східного Калімдору.",h="Затока Пилоброду — рукав Великого Моря між вологим узбережжям Багна Пилоброду й укріпленим портом Острова...",kw={"затока пилоброду","багно пилоброду","острів терамор","нат паґл","рибальство","бухта шаленого прибою"},ang={["faction:Alliance"]="Для моряків і мандрівників Альянсу, що прямують до Калімдору, Затока Пилоброду — останній відрізок відкритого моря перед укріпленою гаванню Острова Терамор."},sec={{t="Води східного болота",b="Затока Пилоброду позначає прибережну межу, де застояні каламутні болота Багна Пилоброду зустрічаються з відкритими водами Великого Моря. Зі сходу її обрамляє Острів Терамор, тож затока слугує морським підходом для суден, що прямують до острівного прихистку Леді Джайни Праудмур. Попри жвавий рух кораблів до пристаней і від них, навколишнє узбережжя лишається диким і небезпечним — усіяне скелястими виступами, таборами мурлоків і захованими бухтами на кшталт Бухти Шаленого Прибою."},{t="Притулок рибалки",b="Саме болото кишить кроколісками й ворожими звірами, але острівці й бухти затоки приваблюють тих, хто шукає усамітнення та щедрого улову. Невеликі острівці поблизу Бухти Шаленого Прибою — відлюдний прихисток для рибалок, і передусім для легендарного рибалки Ната Паґла, якого часто можна побачити з вудкою на скелях, подалі від гамірного міста Терамор."}},faq={{q="Де Затока Пилоброду?",a="Затока Пилоброду лежить біля східного узбережжя центрального Калімдору — просто між вологими східними берегами Багна Пилоброду й скелястою цитаделлю Острова Терамор.",al={"розташування затоки пилоброду","де затока пилоброду","вода пилоброду"}},{q="Кого можна зустріти в затоці?",a="Найвідоміший мешканець дальніх околиць затоки — Нат Паґл, знаменитий на весь світ рибалка. Він отаборився на невеликому острівці в сусідній Бухті Шаленого Прибою, трохи на південний захід від Острова Терамор.",al={"хто в затоці пилоброду","нат пеґл затока пилоброду","нпс затоки пилоброду"}},{q="Чи безпечно перепливати Затоку Пилоброду?",a="Затока порівняно недалеко від безпечного Острова Терамор, але на її мілинах і берегах часто трапляються мурлоки, акули й інші агресивні водяні звірі з околиць болота.",al={"чи небезпечна затока пилоброду","монстри затоки пилоброду"}}},fp="14,284,27.483.0,19.377.0,32.180.0,28.195.0,38.196.0"}
P.entries["subzone:dustwind-cave"] = {n="Печера Пилового Вітру",s="Печера Пилового Вітру — відлюдна западина на вершині скель Каньйону Гострого Вітру, просто на північний схід від Гострого Пагорба. Вона служить діючим тренувальним майданчиком і таємним притулком для посвячуваних лиховісного культу Палаючого Клинка, що діє в Дуротарі.",h="Печера Пилового Вітру — відлюдна западина на вершині скель Каньйону Гострого Вітру, просто на північний схід...",kw={"печера пилового вітру","культисти","палаючий клинок","демонологія","гострий пагорб","каньйон гострого вітру","дуротар"},ang={["class:Warlock"]="Чорнокнижники Орди впізнають темні обряди, що відбуваються в Печері Пилового Вітру, та Палаючий Клинок обертає свої дари Скверни на бунт, а не на службу новому ладу Тралла.",["faction:Horde"]="Печера Пилового Вітру — ганебний і небезпечний внутрішній пролом: тут переховуються культисти демонів за крок від Гострого Пагорба."},sec={{t="Тінь у скелях",b="Печера Пилового Вітру, що височіє над Каньйоном Гострого Вітру, — одна з найближчих і найнебезпечніших загроз Гострому Пагорбу. Багато хто гадає, що демонічні культисти збираються лише в глибоких підземеллях, та тут Палаючий Клинок навчає новобранців просто під носом у влади Орди. Потаємні культисти навчають посвячуваних забороненої темної магії та демонології, готуючи їх підривати молоду орківську державу зсередини кордонів самого Дуротару."},{t="Споганена кров",b="Хто вдереться до печери, ризикує зазнати небезпечного скверніння культистів. Ті, хто практикує всередині, спрямовують мінливі темні мистецтва на кшталт недуг скверної крові, показуючи, як міцно Палаючий Клинок чіпляється за демонічну спадщину, яку Тралл так тяжко боровся вигнати. Знищити тутешню кабалу вкрай важливо, щоб зберегти хиткий мир Дуротару."}},faq={{q="Де Печера Пилового Вітру?",a="Печера Пилового Вітру — високо на кручах Каньйону Гострого Вітру, просто на північний схід від Гострого Пагорба в Дуротарі.",al={"розташування печери пилового вітру","де печера пилового вітру","як знайти печеру пилового вітру"}},{q="Хто засів у Печері Пилового Вітру?",a="Печеру захопили культисти й послушники Палаючого Клинка — зловісного демонічного культу, що прагне поширювати скверну й розхитувати Орду.",al={"хто в печері пилового вітру","вороги печери пилового вітру","монстри печери пилового вітру"}},{q="Чому тут діє Палаючий Клинок?",a="Палаючий Клинок має Печеру Пилового Вітру за відлюдну навчальну заставу, де бувалі культисти навчають новачків демонічних мистецтв подалі від очей вартових Оргріммара й Гострого Пагорба.",al={"чому в печері пилового вітру культисти","призначення палаючого клинка в дуротарі"}},{q="Чому Орда хоче очистити цю печеру?",a="Демонопоклонники, що ховаються за кілька кроків від Гострого Пагорба, — неприпустима загроза для новобранців у дорозі й для оборони всього Дуротара.",al={"чому очищати печеру пилового вітру","загроза орді від печери пилового вітру"}}},fp="13,245,22.435.0,18.354.0,31.116.0,27.158.0,40.198.0,42.166.0"}
P.entries["subzone:dwarven-district"] = {n="Дворфійський Квартал",s="Захований у північному куті Стормвінда, Дворфійський Квартал — гомінкий промисловий анклав, повний ревучих печей, дзвінких ковадел і густого диму. Його заснували майстри з Айронфорджа, що прибули допомогти відбудувати столицю після Другої війни, і нині він — механічне серце міста.",h="Захований у північному куті Стормвінда, Дворфійський Квартал — гомінкий промисловий анклав, повний ревучих...",ang={["profession:Blacksmithing"]="Квартал має найкращі ковальські потужності Стормвінда: просторі плавильні горни, міцні ковадла й досвідчених наставників."},sec={{t="Дім далеко від Каз Модану",b="After the Second War, King Magni Bronzebeard sent hundreds of dwarven artisans, stonemasons, and engineers south to assist their human allies in rebuilding Stormwind. Rather than dispersing throughout the capital, they established their own enclave in the northern quarter. Today, the district retains the unmistakable character of Ironforge, dominated by heavy stone masonry, sprawling smelting operations, and bustling craft shops. Shops such as Potts' Plates provide a familiar haven for craftspeople from Khaz Modan. It also houses the Stormwind portal to the Deeprun Tram, tethering the human capital directly to Ironforge."}},faq={{q="Звідки в Стормвінді дворфійський квартал?",a="Після того як Стормвінд зруйнували в Першій війні й відвоювали в Другій, Король Маґні Бронзбірд послав на південь дворфійських майстрів і робітників допомогти відбудувати столицю. Робітники оселилися в цій північній частині міста й збудували майстерні й оселі на свій смак.",al={"чому дворфи в стормвінді","звідки дворфійська частина","чому дворфійський квартал"}},{q="Як звідси дістатися до Айронфорджа?",a="На східному боці кварталу відкритий арковий тунель веде просто до станції Глибинного трамвая. Це підземне диво з'єднує Стормвінд з Айронфорджем за лічені хвилини.",al={"як дістатися до айронфорджа","де трамвай","вхід у глибинний трамвай"}},{q="Яких професій навчають у Дворфійському Кварталі?",a="Відповідно до свого промислового характеру квартал — головний міський осередок рудокопства, ковальства й інженерії. Тут є важкі кузні, ковадла й окремі наставники цих ремесел.",al={"професії дворфійського кварталу","наставники дворфійського кварталу","наставник ковальства стормвінд"}},{q="Де мисливці навчаються в Стормвінді?",a="Мисливці Стормвінда мають свій штаб у Гільдії Мисливців у Дворфійському Кварталі — цілком доречно ділячи приміщення й торгові припаси з дворфійськими стрільцями.",al={"наставник мисливців стормвінд","мисливська ложа","гільдія мисливців стормвінда"}}},fp="16,318,27.628.0,44.284.0,38.177.0,53.200.0,37.159.0"}
P.entries["subzone:eastern-strand"] = {n="Східне Побережжя",s="Східне Побережжя — смуга південного узбережжя Передгір'я Гілсбреда, що тягнеться на південний схід, до кордону з Аратійським нагір'ям. Колись мирні береги й мілини тепер захопили ворожі наги Кинджалоспинів, що облаштовують тут прибережний плацдарм.",h="Східне Побережжя — смуга південного узбережжя Передгір'я Гілсбреда, що тягнеться на південний схід, до...",kw={"східне побережжя","гілсбред","наги","кинджалоспини","саутшор","узбережжя"},ang={["faction:Alliance"]="Наги, що отаборилися на Східному Побережжі, — пряма загроза з флангу, яка поволі підповзає до морських рубежів Саутшора й сусідніх патрулів.",["faction:Horde"]="Будь-який організований наступ наг з узбережжя вглиб суходолу загрожує розхитати пересування Орди й шляхи постачання через нижній Гілсбред."},sec={{t="Ворожий берег",b="Східне Побережжя біжить південно-східним краєм Передгір'я Гілсбреда й перегукується із Західним Узмор'ям по той бік затоки. Край відомий передусім людськими хуторами та сутичками за землю між Саутшором і Таррен Міллом, але ці піщані рівнини й смуги припливу цілком належать нагам Кинджалоспинів. Виповзши з Великого моря, зміїний народ ковзає піщаними косами й оселяється серед скелястих виступів, пильно стежачи за суходолом."},{t="Землі Кинджалоспинів",b="Через Кинджалоспинів берег на південний схід від Саутшора став небезпечним. Їхні воїни й чаклуни нишпорять пляжами та прибережними водами, тож мандрівникам тут загрожує небезпека."}},faq={{q="Де Східне Побережжя?",a="Східне Побережжя охоплює прибережні піски й мілини в південно-східному куті Передгір'я Гілсбреда й тягнеться вздовж води на схід, до меж Аратійського нагір'я.",al={"розташування східного побережжя","де східне побережжя","східне побережжя на мапі"}},{q="Які істоти живуть на Східному Побережжі?",a="Пляж і ближні води заполонило плем'я наг Кинджалоспинних — піші вояки, нападники й заклиначі, що никають уздовж лінії прибою.",al={"монстри східного побережжя","хто живе на східному побережжі","вороги східного побережжя"}},{q="Чому наги збираються на цьому пляжі?",a="Кинджалоспинні займають пляжі й води Східного Побережжя. Яка в них мета, окрім утримання цього прибережного краю, у розповіді Класики не сказано.",al={"чому наги в гілсбраді","плани нападу кинджальних хребтів","що тут роблять наги"}},{q="Чим Східне Побережжя відрізняється від Західного Узмор'я?",a="Обидва узбережжя облямовують південний берег Гілсбреда. Західне Узмор'я лежить на південному заході, ближче до Срібнолісся, і там живуть мурлоки Подертих Плавців; Східне Побережжя — на південному сході, ближче до Аратійського нагір'я, і його займають наги Кинджалоспинні.",al={"західне узмор'я проти східного побережжя","два пляжі гілсбреда"}}},fp="14,270,19.474.0,21.188.1,36.189.0,42.147.0,41.157.0,59.222.0"}
P.entries["subzone:eastmoon-ruins"] = {n="Руїни Східного Місяця",s="Руїни Східного Місяця — прадавня троляча пам'ятка на сході Танарісу, трохи на захід від Роззявленої Прірви. Колись їх збудували давні пустельні імперії, а нині розсипане кам'яне муровання заселили огри Дюнного Молота, які облаштували тут пустельний табір.",h="Руїни Східного Місяця — прадавня троляча пам'ятка на сході Танарісу, трохи на захід від Роззявленої Прірви.",kw={"руїни східного місяця","дюнний молот","огри","тролячі руїни","роззявлена прірва","танаріс"},ang={["class:Rogue"]="Розбиті колони й розкидані кам'яні мури дають безліч сліпих закутків, щоб непомітно прослизнути повз огрів Дюнного Молота, які блукають довкола, або влаштувати їм засідку.",["race:Troll"]="Зруйноване муровання — тихе нагадування про широку владу ваших предків над Калімдором, поки пустельні піски не забрали південь."},sec={{t="Каміння в піску",b="Руїни Східного Місяця, що здіймаються з розпеченої пустелі трохи на захід від Роззявленої Прірви, яка кишить комахами, зберігають розсипану архітектуру прадавньої тролячої цивілізації. Зотлілі колони, вивітрені кам'яні майдани й вибілені сонцем монументи нагадують про часи задовго до того, як піски поглинули цей край. Святинями тут опікуються не вчені й не нащадки тролів: місце міцно тримають огри Дюнного Молота, яким розбиті мури правлять за прихисток і зручне місце, щоб наглядати за торговими шляхами поблизу."}},faq={{q="Хто збудував Руїни Східного Місяця?",a="Ця архітектура — творіння давніх тролів. Задовго до того, як Танаріс перетворився на посушливу пустку, на півдні Калімдору панували тролячі цивілізації, лишивши по собі кам'яну кладку, храми й площі, як-от ті, що вивітрюються в Руїнах Східного Місяця.",al={"хто збудував руїни східного місяця","походження східного місяця","тролі збудували східний місяць"}},{q="Хто нині контролює Руїни Східного Місяця?",a="Руїни займають огри Дюнного Молота з Танаріса. Ці кремезні пустельні громили привласнили давні кам'яні мури, отаборилися там і пильнують схід Танаріса.",al={"хто живе на східному місяці","монстри руїн східного місяця","пустельні мандрівники східного місяця"}},{q="Де Руїни Східного Місяця?",a="Вони на сході Танаріса, одразу на захід від вуликів Зяючої Прірви, де кишать силітиди.",al={"розташування руїн східного місяця","де східний місяць","знайти руїни східного місяця"}},{q="Чи є завдання в Руїнах Східного Місяця?",a="Жодні звичайні завдання не ведуть саме до Руїн Східного Місяця. Це передусім розбійницький табір і історична пам'ятка для шукачів пригод, що досліджують глибини пустелі.",al={"завдання східного місяця","завдання в руїнах східного місяця","чи є тут завдання"}}},fp="14,273,18.492.0,29.225.0,32.174.0,37.130.0,39.185.0"}
P.entries["subzone:eastvale-logging-camp"] = {n="Лісозаготівельний Табір Східної Долини",s="Лісозаготівельний Табір Східної Долини — важливе лісорубне поселення у східних лісах Лісу Елвінн, поблизу кордону з Горами Редріджу. Табір постачає конче потрібну деревину Стормвінду й навколишнім поселенням, та його роботі невпинно заважають голодні хижаки, що нишпорять довколишніми лісами.",h="Лісозаготівельний Табір Східної Долини — важливе лісорубне поселення у східних лісах Лісу Елвінн, поблизу...",kw={"лісозаготівельний табір східної долини","деревина","лісоруби","стайні","скакуни","вовки","ліс елвінн"},ang={["faction:Alliance"]="Лісозаготівельний Табір Східної Долини — одне з найкращих місць у Лісі Елвінн, де члени Альянсу можуть придбати надійних стормвіндських коней.",["race:Human"]="Для людей Стормвінда Східна Долина дає конче потрібну деревину, яка й далі відбудовує та підтримує поселення королівства."},sec={{t="Важливий промисел в облозі",b="Замовлення на деревину безперервно надходять до Лісозаготівельного Табору Східної Долини від покупців з усього королівства Стормвінд, та вкластися в суворі терміни — справа нелегка. Густі хащі довкола табору кишать лютими вовками й ведмедями, які раз у раз проганяють лісорубів із ділянок, і цінний зрубаний ліс лишається покинутим у хащах. Під керівництвом Наглядачки Рейлен табір часто покладається на мандрівних шукачів пригод, щоб винищити звірину, яка насувається, і забрати повалені колоди, поки доставки не відстали безнадійно."},{t="Життя на східному порубіжжі",b="Попри віддаленість, Східна Долина — більше ніж просто лісорубна застава. Тут є кілька житлових осель і жваві стайні, де мандрівники можуть придбати добрих скакунів. Тутешня торгівля деревиною тісно пов'язана зі знаттю Стормвінда, зокрема з лордом Джораном Тремейндом, чия родина має чималий інтерес у лісозаготівлі табору. На сусідньому пагорбі над ділянкою стоїть тихий маєток відставного Маршала Гаґґарда — колишнього очільника вартових Стормвінда, що перебрався до цієї сільської застави доживати віку подалі від столичної політики."}},faq={{q="Яке головне призначення Лісозаготівельного Табору Східної Долини?",a="Східна Долина — головне джерело деревини для королівства Стормвінд на сході Лісу Елвінн. Лісоруби тут працюють від світанку до смеркання й у суворі строки, щоб задовольнити великий попит на деревину з боку будівничих і шляхти по всьому королівству.",al={"чому тут східна долина","що таке східна долина","роль лісозаготівлі східної долини"}},{q="Чому табір лісорубів постійно наймає шукачів пригод?",a="Табір оточують густі ліси, і робітникам безперестанку загрожують дикі ведмеді й вовки. Через напади лісоруби часто тікають, лишаючи нарубану деревину, і замовлення ризикують не встигнути до строку відвантаження.",al={"проблеми східної долини","чому лісорубам потрібна допомога","вовки східної долини"}},{q="Хто такий Маршал Гаґґард?",a="Маршал Гаґґард — колишній очільник Варти Стормвінда у відставці. Кілька років тому він пішов зі служби й тепер мешкає в тихому маєтку на кручі над Лісозаготівельним Табором Східної Долини.",al={"хаггард","старий біля східної долини","маршал гаґґард елвін"}},{q="Чи можна купити їздових тварин у Лісозаготівельному Таборі Східної Долини?",a="Так. У таборі є діюча кінська стайня, де шукачі пригод з Альянсу можуть купити верхових коней і навчитися їзди.",al={"торговець конями східна долина","коні східної долини","купити їздову тварину в елвіні"}}},fp="21,317,29.561.0,28.585.0,50.232.0,50.259.0,23.203.0,44.137.0"}
P.entries["subzone:eastwall-gate"] = {n="Брама Східного Муру",s="Брама Східного Муру — укріплений бічний вхід у зовнішньому мурі занепалого Стратгольма. Вона стоїть на півночі Східних Чумних Земель і веде просто в зруйнований Стратгольм іншим шляхом, оминаючи хаос біля головних міських брам.",h="Брама Східного Муру — укріплений бічний вхід у зовнішньому мурі занепалого Стратгольма.",kw={"брама східного муру","стратгольм","ключ від міста","площа старійшин","каплиця алонсуса","вхід"},ang={["class:Paladin"]="Пройшовши крізь Браму Східного Муру, хрестоносці опиняються просто біля Каплиці Алонсуса — святого прихистку, який тепер оточують попіл і жахіття Погибелі.",["class:Rogue"]="Міцний замок Брами Східного Муру вимагає найвищої майстерності зломщика, тож вправний розбійник стає безцінним, коли треба оминути головний вхід без Ключа від Міста."},sec={{t="Чорний хід до руїн",b="Велична головна брама Стратгольма відчиняється просто на Королівську Площу, а Брама Східного Муру пробиває східні укріплення міста. Надійно замкнена від непроханих гостей, вона веде прямо на Площу Старійшин, неподалік сходів Каплиці Алонсуса. Для тих, хто вирушає в палаюче серце твердині Погибелі, обхід передніх барикад може вирішити все: або стрімкий удар у глибину міста, або виснажлива м'ясорубка крізь передові лави нежиті."},{t="Крізь залізні ґрати",b="Пройти крізь Браму Східного Муру не так просто. Її намертво замикають важкі ковані ґрати, і відчинити їх можна або Ключем від Міста, який здобувають у самому Стратгольмі, або руками надзвичайно вправного зломщика, здатного впоратися з майстерними замками. А вже за порогом на внутрішній стіні є важкий механічний важіль: ним мандрівники можуть зсередини підняти ґрати й відкрити надійний шлях для союзників."}},faq={{q="Куди веде Брама Східного Муру?",a="Брама відкривається на Площу Старійшин у зруйнованому місті Стратгольм. Вона стоїть зовсім поруч з історичною Каплицею Алонсуса.",al={"куди веде брама східного муру","призначення брами східного муру","що за брамою східного муру"}},{q="Як відчинити браму?",a="Брама Східного Муру міцно замкнена. Її можна відчинити Ключем від Міста, знайденим у Стратгольмі, або ж її може зламати вправний розбійник, що опанував відмикання замків. Опинившись усередині, можна підняти браму вручну внутрішнім важелем.",al={"як відчинити браму східного муру","відімкнути браму східного муру","ключ від брами східного муру"}},{q="Навіщо шукачам пригод цей вхід замість головної брами?",a="Увійшовши через Браму Східного Муру, ударні загони минають передні вулиці, що кишать ворогами, і починають наступ просто біля Площі Старійшин, швидше діставшись певних кварталів міста.",al={"навіщо брама східного муру","переваги бічного входу","чому бічна брама стратхольма"}},{q="Чи можна відчинити браму зсередини?",a="Так. Важіль із внутрішнього, стратгольмського боку брами дає змогу кожному, хто всередині, підняти браму й пропустити інших без ключа.",al={"важіль усередині брами східного муру","відчинити браму східного муру зсередини"}}},fp="13,286,21.492.0,24.432.0,34.133.0,27.219.0,59.212.0,38.143.0"}
P.entries["subzone:eastwall-tower"] = {n="Вежа Східного Муру",s="Вежа Східного Муру — зруйнована дозорна вежа Лордерона у Східних Чумних Землях, поблизу східного шляху. Її розграбували в Третю війну, коли Погибель прокотилася королівством, і тепер її руїни здіймаються над дикими землями, де кишить Погибель.",h="Вежа Східного Муру — зруйнована дозорна вежа Лордерона у Східних Чумних Землях, поблизу східного шляху.",kw={"вежа східного муру","дозорна вежа","лордерон","погибель","східні чумні землі","каплиця надії світла"},ang={["faction:Alliance"]="Для Альянсу повернути Вежу Східного Муру — це вшанувати полеглих воїнів Лордерона й захистити підступи до Каплиці Надії Світла від набігів Погибелі.",["faction:Horde"]="Зруйнована дозорна вежа височіє над шляхами крізь ворожі північні землі."},sec={{t="Зруйнована варта на кордоні",b="Вежу Східного Муру збудували як прикордонний дозор Королівства Лордерон: колись вона наглядала за мандрівниками, що прямували до далеких околиць держави. Коли в Третю війну вдерлася Погибель, заставу розтрощили разом з довколишніми поселеннями, і від неї лишилися тільки потрощені кам'яні арки й обгорілі балки. Нині, коли війська Короля-Ліча досі заполоняють край, висока позиція вежі робить її незамінною передовою заставою. З її зруйнованих мурів видно шляхи через сільську місцевість, де кишить Погибель."}},faq={{q="Чим була Вежа Східного Муру до падіння?",a="Вежа Східного Муру спершу була оборонною розвідувальною вежею королівства Лордерон. Вона входила до мережі прикордонної варти краю й оберігала торгові шляхи та віддалені ферми, доки Третя війна не принесла падіння Лордерона.",al={"історія вежі східного муру","хто збудував вежу східного муру","що це було за місце"}},{q="Хто зруйнував вежу?",a="Вежу зруйнувала Погибель під час завоювання принцом Артасом Менетілом і подальшого спустошення Лордерона нежиттю. Потвори-нежить розтрощили її оборону, вбили захисників і лишили від споруди руїни.",al={"як зруйнували вежу східного муру","що сталося з вежею східного муру"}},{q="Чим вежа важлива стратегічно?",a="Навіть у руїнах вежа панує над висотою вздовж східних доріг Чумних Земель, звідки видно околиці, що кишать Погибеллю.",al={"значення вежі східного муру","позиція вежі східного муру"}},{q="Чи безпечно відпочивати біля вежі?",a="Зруйнована вежа стоїть серед околиць, що кишать Погибеллю, і надійного притулку не дає.",al={"чи можна тут відпочити","дружні вартові"}}},fp="14,232,28.519.0,39.245.0,24.226.0,41.138.0,29.84.0"}
P.entries["subzone:echo-isles"] = {n="Острови Відлуння",s="Острови Відлуння — гроно тропічних островів просто біля південно-східного узбережжя Дуротару. Спершу їх заселили тролі Темного Списа, що втекли зі своїх прадавніх островів, та нині архіпелаг втрачено: відступник-знахар Залазан вигнав свій народ темною магією та поневоленими поплічниками.",h="Острови Відлуння — гроно тропічних островів просто біля південно-східного узбережжя Дуротару.",kw={"острови відлуння","залазан","тролі","темний спис","вуду","архіпелаг","дуротар"},ang={["faction:Horde"]="Убезпечити Острови Відлуння вкрай важливо, щоб стабілізувати південне узбережжя Дуротару, захистити Село Сен'джин і зміцнити кордони молодої Орди проти морських загроз і містиків-відступників.",["race:Troll"]="Острови Відлуння — водночас обіцяний дім Темного Списа на Калімдорі й гіркий біль зради Залазана. Повернути їх — справа виживання племені й особистої честі."},sec={{t="Розколотий притулок",b="Після втечі через Велике Море разом із Траллом плем'я Темного Списа обрало Острови Відлуння своїм новим домом. Та їхній мир руйнували знову і знову: спершу флот Великого Адмірала Дейліна Праудмура під час вторгнення Кул Тірасу в Дуротар, а потім — зрада зсередини. Невдовзі після того, як тролі відбили флот Праудмура, один з їхніх власних знахарів, Залазан, узявся за темні мистецтва, щоб поневолити розум одноплемінників. Вождь Вол'джин і вільні тролі Темного Списа були змушені знову залишити острови й шукати тимчасового притулку по той бік вузької протоки, у Селі Сен'джин."},{t="Хватка Залазана",b="Нині тропічне гроно заполонили войовничі хижаки, споганена звірина й невільники Залазана. Зловісними насланнями, фетишами вуду та купами джу-джу, розставленими по островах, зрадливий знахар підкорює звірів і полонених тролів своїй волі. Зі свого табору на Побережжі Темного Списа розвідники та воїни Вол'джина часто роблять вилазки на острови, сповнені рішучості забрати рештки полеглих і вбити божевільного містика, що вкрав їхній дім."}},faq={{q="Чому тролі Темного Спису нині тут не живуть?",a="Знахар Залазан зрадив плем'я: темною магією він позбавив родичів вільної волі й перетворив на слухняних прислужників. Вождь Вол'джин наказав евакуюватися на материкове узбережжя Дуротара й заснував Село Сен'джин як плацдарм, поки плем'я бореться за повернення свого дому.",al={"чому острови покинуті","чому тролі пішли","дім тролів"}},{q="Хто такий Залазан?",a="Залазан — зрадливий знахар Темного Спису, що обернувся проти свого племені. Могутнім вуду й темною магією він наклав на острови закляття, зіпсував місцевих звірів і поневолив одноплемінників, перетворивши їх на безвольних рабів.",al={"хто такий залазан","бос островів відлуння","знахар залазан"}},{q="Які загрози чатують на островах?",a="Архіпелаг кишить дикими рапторами, тиграми й зіпсованими звірами, а ще — вуду-купами Залазана та його підвладними тролями-прислужниками, зачарованими й тролями-вуду.",al={"монстри островів відлуння","що на островах","небезпеки островів відлуння"}},{q="Як плем'я Темного Спису взагалі опинилося на цих островах?",a="Після того як Тралл і Орда врятували плем'я Темного Спису з острова, що тонув, і від ворожих наг у Великому Морі, тролі вирушили до Калімдору, і їм дали Острови Відлуння, щоб оселитися поруч зі своїми союзниками-орками.",al={"як тролі потрапили сюди","походження темного списа","історія островів відлуння"}}},fp="10,320,21.590.0,15.488.0,51.308.0,16.224.0,32.185.0,63.214.0"}
P.entries["subzone:echo-ridge-mine"] = {n="Шахта Ехо-Рідж",s="Шахта Ехо-Рідж — невелика розробка, вирубана в північно-західних скелях Долини Нортширу. Багата на камінь і руду, вона нещодавно потрапила в лапи руйнівної навали кобольдів, що зупинила місцевий промисел Нортширу.",h="Шахта Ехо-Рідж — невелика розробка, вирубана в північно-західних скелях Долини Нортширу.",kw={"шахта ехо-рідж","кобольди","шахта","нортшир","руда","маршал макбрайд","ліс елвінн"},ang={["profession:Mining"]="Штольні Ехо-Ріджу багаті на перші мінеральні поклади, та кожному шукачеві руди спершу доведеться пробитися крізь орди кобольдів зі свічками.",["race:Human"]="Для новобранців, що відгукнулися на поклик Стормвінда, зачистка Шахти Ехо-Рідж — важливе бойове хрещення на захист Абатства Нортшира."},sec={{t="Опора для погані",b="Схована в пагорбах над Абатством Нортшира, Шахта Ехо-Рідж мала постачати долині корисний камінь і метал. Натомість тунелі заполонили спритні кобольди й вигнали місцевих робітників. Маршал Макбрайд вважає цю навалу неприпустимою загрозою безпеці Нортширу та набору новобранців, тож посилає новачків просто в тунелі, щоб прорідити кобольдів і повернути шахту."},{t="Загроза під Нортширом",b="Захоплення Ехо-Ріджу — частина ширшої навали кобольдів, що шириться Лісом Елвінн. Якщо цю підземну погань не стримати на північно-західному хребті, вона загрожує порушити мирні тренувальні угіддя Нортширу й перекрити надходження важливих ресурсів до абатства."}},faq={{q="Чому в Шахті Ехо-Рідж кобольди?",a="Кобольди — природжені копачі, яких вабить до темних тунелів, багатих на руду. Відчувши слабку оборону, вони захопили Шахту Ехо-Рідж, щоб копати скарби й привласнити ці землі.",al={"чому тут кобольди","кобольди ехо-рідж","хто захопив шахту"}},{q="Хто намагається повернути Шахту Ехо-Рідж?",a="Маршал Макбрайд з Абатства Нортшира керує зусиллями з очищення шахти. Він залучає щойно прибулих шукачів пригод розвідати тунелі й проредити паразитів, поки ті не поширилися глибше в долину.",al={"хто хоче повернути ехо-рідж","завдання ехо-рідж","макбрайд ехо-рідж"}},{q="Де Шахта Ехо-Рідж?",a="Вхід до шахти — у північно-західному куті Долини Нортширу, висічений просто в скелястому схилі трохи на північ від абатських виноградників.",al={"розташування ехо-рідж","де ехо-рідж","знайти шахту ехо-рідж"}}},fp="15,235,21.427.0,29.298.0,35.177.0,41.203.0,33.146.0"}
P.entries["subzone:elder-rise"] = {n="Узвишшя Старійшин",s="Узвишшя Старійшин лежить на схід від центрального плато Тандер Блафа; дістатися туди можна довгими підвісними мостами і з Високого, і з Середнього Узвишшя. Це духовне серце тауренської столиці: тут Коло Кенарія, тауренські друїди й жерці та Рада Старійшин, що править містом.",h="Узвишшя Старійшин лежить на схід від центрального плато Тандер Блафа; дістатися туди можна довгими підвісними...",kw={"узвишшя старійшин","тандер блаф","друїди","гамуул рунотем","рада старійшин","маґата"},ang={["class:Druid"]="Узвишшя Старійшин — найголовніша домівка друїдів Орди: тут святилище Верховного Друїда Гамуула Рунтотема й осідок Кола Кенарія в цій частині Калімдору.",["race:Tauren"]="На узвишші засідає Рада Старійшин і живуть духовні провідники, які ведуть ваші племена шляхом миру й традицій крізь складну дійсність Орди."},sec={{t="Святилище віри й ради",b="Узвишшя Старійшин, з'єднане з головними столовими горами хиткими мотузяними мостами, віддане тихим роздумам, священній мудрості й громадському правлінню. Тауренські друїди й жерці збираються тут, щоб навчати послушників шляхів природи й духовного служіння. Високо на цій горі живе Верховний Друїд Гамуул Рунтотем — шанований провідник, що повернув друїдство тауренам і налагодив тісні зв'язки з Колом Кенарія. Поруч із цими дикими святилищами стоїть Зала Старійшин, де вожді племен радяться над справами молодої столиці."},{t="Хитка присутність",b="Хоч узвишшя й слугує мирним святилищем, над ним висить політична напруга. Маґата Ґрімтотем, стара матріарх потайного й зарозумілого племені Ґрімтотем, живе в хатині між двома мостами. Кайрн Бладгуф гостинно дає всім тауренським родам місця в раді, та її пильна присутність постійно нагадує, що не всі племена поділяють миролюбні ідеали Бладгуфів чи їхню беззастережну відданість Орді."}},faq={{q="Для чого Узвишшя Старійшин?",a="Узвишшя Старійшин — осередок духовного навчання й громадських нарад у Тандер Блафі. Тут мешкають друїди Кола Кенарія, жерці-таурени, правляча Рада Старійшин і вожді племен.",al={"призначення узвишшя старійшин","що на узвишші старійшин","будівлі узвишшя старійшин"}},{q="Хто очолює друїдів на Узвишші Старійшин?",a="Тут мешкає Верховний Друїд Гамуул Рунтотем. Близький друг і радник Кайрна Бладгуфа, Гамуул — найвищий за рангом таурен у Колі Кенарія, і він навчає тих, кого покликано йти шляхом природи.",al={"верховний друїд громовиці","лідер друїдів тауренів","де хамуул"}},{q="Чому тут мешкає Маґата Ґрімтотем?",a="Маґата Ґрімтотем займає намет між мостами. Як стара відьма й вождиня племені Ґрімтотем, вона засідає в Раді Старійшин, представляючи свій народ у Тандер Блафі, попри взаємну недовіру між її кланом і союзниками Кайрна.",al={"де маґата","маґата ґрімтотем","ґрімтотем на узвишші старійшин"}},{q="Як дістатися до Узвишшя Старійшин?",a="Узвишшя Старійшин лежить просто на схід від центрального плато міста. До нього можна дійти великими дерев'яними мотузяними мостами, що з'єднують його і з Високим Узвишшям, і з нижнім плато.",al={"як дістатися до узвишшя старійшин","мости узвишшя старійшин","шлях до узвишшя старійшин"}}},fp="10,292,30.550.0,21.480.0,28.204.0,35.201.0,37.258.0,28.163.0"}
P.entries["subzone:eldreth-row"] = {n="Ряд Елдретів",s="Ряд Елдретів — височенні зруйновані зовнішні зали, що утворюють західний вхід до Лютопащу у Фераласі. Колись це був величний поріг прадавнього Елдре'Таласу, а тепер усе тут поросло хащами, а прохід пильно патрулюють огри Ґордунні.",h="Ряд Елдретів — височенні зруйновані зовнішні зали, що утворюють західний вхід до Лютопащу у Фераласі.",kw={"ряд елдретів","лютопащ","елдре'талас","огри ґордунні","високородні","фералас"},ang={["race:NightElf"]="Бачити, як брутальні огри паплюжать величну кладку прадавнього Елдре'Таласу, — гірке нагадування про падіння Високородних і про Розкол."},sec={{t="Поріг Елдре'Таласу",b="Ряд Елдретів — крайня зовнішня межа прадавнього Елдре'Таласу, велична алея високих ельфійських арок, що лежить просто перед глибшими кварталами й Зруйнованим Майданом. За століття занедбання кладка потріскалася, і буйна рослинність Фераласу знову захопила колонади. Нині величну красу Високородних змінила груба влада огрів Ґордунні: вони обернули зали на передовий табір і стережуть стежки, що ведуть на схід — до Кварталу Кривого Лісу, і на захід — повз Лютий Став."}},faq={{q="Що таке Ряд Елдретів?",a="Ряд Елдретів — зовнішня вхідна зала й околиці Лютопаща у Фераласі, перед Зруйнованим Майданом і внутрішніми брамами підземелля.",al={"ряд елдретів","що це за місце","вхід у лютопащ"}},{q="Хто нині контролює Ряд Елдретів?",a="Місцину захопив і патрулює клан огрів Ґордунні, що укріпив руїни Лютопаща й блукає його зруйнованими алеями.",al={"хто тут живе","хто контролює ряд елдретів","монстри ряду елдретів"}},{q="Куди веде Ряд Елдретів?",a="Алея веде вглиб — до Зруйнованого Торгових Рядів й головних комплексів Лютопаща; на крайньому східному боці є вхід до Кварталу Кривого Лісу, а на заході — Лютий Ставок.",al={"куди веде ця зала","виходи ряду елдретів","шляхи лютопаща"}}},fp="11,236,29.554.0,20.148.0,35.133.0,28.191.0"}
P.entries["subzone:emerald-sanctuary"] = {n="Смарагдове Святилище",s="Смарагдове Святилище — застава Кола Кенарія біля південного входу до Сквернолісся. Тут друїди з нічних ельфів і тауренів об'єднуються, щоб вивчати всепроникну демонічну скверну й братися за нелегку справу — зцілення оскверненого лісу.",h="Смарагдове Святилище — застава Кола Кенарія біля південного входу до Сквернолісся.",kw={"смарагдове святилище","коло кенарія","друїди","сквернолісся","ашенваль","джеденар"},ang={["class:Druid"]="Для друїдів і з Дарнасуса, і з Тандер Блафа Смарагдове Святилище — важливе нагадування про спільне покликання: обов'язок зцілювати землю вищий за мирську фракційну вірність."},sec={{t="Маяк серед зарази",b="Смарагдове Святилище, що стоїть на південному краю Сквернолісся біля кордону з Ашенвалем, — головна база Кола Кенарія в цій сплюндрованій глушині. На відміну від запеклих фракційних чвар, що палають по всьому Калімдору, це святилище — нейтральний прихисток, де друїди відкидають політику й повністю зосереджуються на відновленні природи. Звідси дослідники стежать за оскверненими рослинами й спрямовують розвідку до Джеденару, шукаючи будь-який дієвий спосіб очистити отруєний ґрунт."}},faq={{q="Навіщо Смарагдове Святилище?",a="Коло Кенарія заснувало цей табір, щоб вивчати демонічну скверну, яка душить Сквернолісся, і протидіяти їй. Друїди тут досліджують зіпсовані рослини, звірів і джерела води й організовують боротьбу з культистами Ради Тіней, що засіли глибше в лісі.",al={"чому тут смарагдове святилище","що тут роблять друїди","призначення смарагдового святилища"}},{q="Чи можуть Смарагдове Святилище відвідувати і Альянс, і Орда?",a="Так. Коло Кенарія — незалежна нейтральна організація. Тут раді шукачам пригод і з Альянсу, і з Орди, якщо вони готові допомогти очистити Сквернолісся від глибокої скверни.",al={"чи нейтральне смарагдове святилище","чи орді можна в смарагдове святилище","чи вітають альянс у святилищі"}},{q="Яка загроза найбільше непокоїть тутешніх друїдів?",a="Увесь ліс спотворений демонічною енергією, що лишилася після Третьої війни, але найбільше друїдів тривожить Джеденар — розлогий печерний комплекс на півночі, де гніздиться Рада Тіней і поширює скверну.",al={"найбільша загроза в сквернолісі","з чим борються друїди","загроза джеденару"}}},fp="17,247,22.507.0,45.271.0,56.201.0,46.239.0"}
P.entries["subzone:engineering-labs"] = {n="Інженерні Лабораторії",s="Інженерні Лабораторії — багатоярусний дослідницько-виробничий комплекс глибоко в Гномреґані. Цей гамірний осередок гномської винахідливості, з'єднаний із Входом до Майстерні та Стартовим відсіком, було захоплено під час радіоактивного катаклізму міста, і тепер тут кишать божевільні гноми-прокажені та некеровані механічні пристрої.",h="Інженерні Лабораторії — багатоярусний дослідницько-виробничий комплекс глибоко в Гномреґані.",kw={"інженерні лабораторії","гномреґан","гноми-прокажені","перфограф","креслення"},ang={["profession:Engineering"]="Інженерні Лабораторії — вершина занепалої гномської автоматизації: серед уламків досі працюють автоматичні термінали-перфографи й лежать покинуті креслення.",["race:Gnome"]="Для гномів-вигнанців ці лабораторії — трагічне видовище: колись серце технічних тріумфів їхньої раси, тепер вони перетворилися на опромінені руїни, захоплені їхніми ж оскверненими родичами."},sec={{t="Занепалий осередок винахідництва",b="Інженерні Лабораторії, збудовані довкола центральної механічної споруди, займають два головні яруси, з'єднані центральним вантажним підйомником. У часи розквіту Гномреґана тутешні майстри розробляли креслення й доводили до ладу заводні винаходи. Сьогодні витоки радіації звели з глузду дослідників, що лишилися, перетворивши їх на шалених гномів-прокажених, які бездумно стережуть несправні машини разом із некерованими механізмами."},{t="Важливий вузол",b="Окрім історичної ролі лабораторії, ця зала — важливий транспортний вузол у нижніх частинах зруйнованого міста. Проходи звідси ведуть до Стартового відсіку, Двору Майстрів і чорного ходу біля Входу до Майстерні. На нижньому поверсі стоять і термінали «Матричний Перфограф 3005-Д» — важливі обчислювальні пристрої, без яких не розшифрувати закодованих перфокарт, що їх носять гноми-інженери."}},faq={{q="Для чого спершу були Інженерні Лабораторії?",a="До падіння міста Інженерні Лабораторії призначалися для досліджень, складання й випробування складних гномівських пристроїв і автоматів. Гномівські інженери й техніки креслили в цій величезній дворівневій залі нову техніку.",al={"призначення інженерних лабораторій","що тут виготовляли","історія інженерних лабораторій"}},{q="Які загрози нині никають Інженерними Лабораторіями?",a="Обидва яруси зали заполонили опромінені прокажені гноми й несправні механічні автомати. Ці мешканці, що лишилися, цілком збожеволіли від опроміненого газу, випущеного під час падіння міста, і нападають на кожного неопроміненого прибульця.",al={"хто всередині","вороги інженерних лабораторій","монстри тут"}},{q="Що таке машини Матричний Перфограф 3005-Д?",a="Це автоматичні гномівські термінали даних на нижньому рівні Інженерних Лабораторій. Вони дають змогу інженерам і шукачам пригод пробивати закодовані картки, підвищуючи рівень допуску й розшифровуючи технічні архіви, що збереглися в місті.",al={"перфограф д","матричний перфограф 3005-д","жовта машина карт"}},{q="Як ця місцина пов'язана з рештою Гномреґана?",a="Верхній рівень з'єднується просто з чорним ходом Входу до Майстерні й переходами до Стартового відсіку. Нижній рівень веде до головних коридорів, що з'єднують Стартовий відсік і Двір Майстрів.",al={"куди це веде","виходи інженерних лабораторій","шляхи до інженерних лабораторій"}}},fp="16,323,29.404.0,16.387.0,51.240.0,43.246.0,48.255.0,53.198.0"}
P.entries["subzone:ethel-rethor"] = {n="Етель Ретор",s="Етель Ретор — давні руїни нічних ельфів на скелястому північно-західному узбережжі Пустограю. Над хвилями досі здіймається самотня запечатана вежа, але більша частина поселення тепер під водою, і там хазяйнують ворожі наги.",h="Етель Ретор — давні руїни нічних ельфів на скелястому північно-західному узбережжі Пустограю.",kw={"етель ретор","пустограй","нічні ельфи","наги","руїни","срібний світанок","азор алдаморт"},ang={["faction:Alliance"]="Мандрівники Альянсу, що перетинають ворожі пустирі Пустограю, знайдуть біля руїн рідкісне доброзичливе нейтральне обличчя — спостерігача Срібного світанку Азора Алдаморта.",["race:NightElf"]="Для нічних ельфів Етель Ретор — сумний пам'ятник утраченій імперії, що нагадує про катастрофу Розколу і про змінених родичів, які тепер нишпорять затопленими залами."},sec={{t="Потопла реліквія",b="Етель Ретор, що стоїть на безлюдному узбережжі західного Калімдору, — моторошне нагадування про давню цивілізацію нічних ельфів, яка процвітала до Великого Розколу. Більшість величних споруд обвалилася в океанські глибини, лишивши тільки розтрощені фундаменти й самотню, понівечену негодою вежу, що стирчить із прибою. До запечатаного входу вежі веде невеликий міст, але сама споруда щільно зачинена — і від стихії, і від непроханих гостей. Затоплені зали й навколишні мілини стали твердинею прибережних наг, тож води тут підступні для кожного, хто наблизиться."},{t="Дозорці на березі",b="Попри віддаленість і зміїну навалу, Етель Ретор приваблює мандрівників, яких цікавлять забута історія Калімдору та його нинішні загрози. Біля руїн пильно чатує посланець Срібного світанку Азор Алдаморт: він стежить за загрозою наг і допомагає відважним шукачам пригод, готовим пірнути в затоплені проходи. Між водними небезпеками біля берега й безплідними пустирями всередині материка руїни слугують самотнім прибережним роздоріжжям."}},faq={{q="Що таке Етель Ретор?",a="Етель Ретор — зруйноване прибережне поселення нічних ельфів на північному заході Пустограю. Більшість його колишніх споруд нині під водою, і від нього лишилися самотня вежа в морі й затоплена кам'яна кладка.",al={"історія етель ретор","що це за місце в дезоласі","руїни етель ретор"}},{q="Хто нині контролює Етель Ретор?",a="Затонулі руїни й сусідні рифи захопили наги. Як і чимало давніх місць калдореїв на узбережжі, ці зміїсті створіння привласнили затоплені зали й агресивно патрулюють навколишні мілини.",al={"хто живе в етель реторі","монстри етель ретор","наги в етель реторі"}},{q="Чи можна зайти у вежу?",a="До вежі, що здіймається з моря, веде невеликий місток, але двері міцно запечатані. Мандрівники можуть хіба оглянути її ззовні й пірнути до затоплених руїн під нею.",al={"як відчинити вежу етель ретор","двері етель ретор","усередині етель ретор"}},{q="Чому тут Срібний Світанок?",a="Біля руїн перебуває представник Срібного Світанку — Азор Алдаморт. Світанок зосереджений передусім на Погибелі на сході, але його агенти по всьому Калімдору стежать за незвичними магічними збуреннями, давніми руїнами й новими загрозами на кшталт наг.",al={"срібний світанок у дезоласі","азор алдамор етель ретор","нпс срібного світанку дезолас"}}},fp="12,258,15.616.0,21.466.0,21.210.0,30.219.0,28.204.0,28.258.0"}
P.entries["subzone:everlook"] = {n="Евірлук",s="Евірлук — заметене снігом торгове містечко в центрі Вінтерспрінгу, засноване картелем Стімвідл. Воно стоїть на перехресті шляхів засніженої долини й слугує нейтральним прихистком для купців, рудошукачів і дослідників, що зважилися кинути виклик високогірному холоду.",h="Евірлук — заметене снігом торгове містечко в центрі Вінтерспрінгу, засноване картелем Стімвідл.",kw={"евірлук","картель стімвідл","гобліни","вінтерспрінг","аукціон","інженерія","нейтральне містечко"},ang={["profession:Engineering"]="Евірлук — важливий осередок для досвідчених інженерів, особливо тих, хто опанував гоблінську інженерію: тут ви зможете навчитися виготовляти вимірний розривач, налаштований просто на це містечко."},sec={{t="Торгівля на краю світу",b="Евірлук — найпівнічніше підприємство картелю Стімвідл, таке собі віддзеркалення Ґаджетзана й Буті Бей під ковдрою вічної мерзлоти. Обнесене муром містечко стоїть на перехресті снігових заметів Вінтерспрінгу й суворо дотримується нейтралітету. Тут діють єдиний у краї банк і спільний аукціон, тож сюди в пошуках тепла й притулку з'їжджаються мандрівники і з Альянсу, і з Орди. Містечко охороняють наймані вишибали, і тут можна сховатися від лютих морозних шаблезубів та єті."},{t="Шестерні в тундрі",b="Під крижаними дерев'яними дахами, серед химерних шпалер із пінгвінами, Евірлук аж вирує технічною цікавістю. Тут розмістилися спеціалізовані інженерні майстерні й передові алхімічні лабораторії, де гоблінські майстри-винахідники подалі від сторонніх очей розсувають межі свого ремесла. До вкритих інеєм воріт уже стукає й дипломатія ззовні: нещодавно Срібний світанок прислав сюди Ґреґора Ґрейстоуна, щоб той вів переговори безпосередньо з керівництвом містечка й пильно стежив за давніми руїнами краю та загрозами, що збираються на півночі."}},faq={{q="Хто контролює Евірлук?",a="Евірлук належить картелю Стімвідл, і ним керує місцеве врядування картелю. Саме до нього Срібний Світанок послав своїм представником Ґреґора Ґрейстоуна.",al={"хто керує евірлуком","лідер евірлука","хто головний в евірлуку"}},{q="Чому Евірлук безпечний і для Альянсу, і для Орди?",a="Картель Стімвідл суворо стежить за торговельним нейтралітетом. Гобліни-вишибали швидко відгамселять кожного, хто спробує розпочати бійку в мурах міста, тож мандрівники з будь-якої сторони можуть вільно торгувати.",al={"чи нейтральний евірлук","чи можуть орда й альянс в евірлук","правила пвп в евірлуку"}},{q="Чому в Евірлуку Срібний Світанок?",a="Срібний Світанок має тут офіційне представництво в особі посланця Ґреґора Ґрейстоуна. Він представляє орден перед гоблінськими купцями, забезпечує доступ до місцевих припасів і стежить за загрозами в краї.",al={"що тут робить срібний світанок","грегор ґрейстоун евірлук","срібний світанок вінтерспрінг"}},{q="Звідки Евірлук отримує товари?",a="Евірлук стоїть на перехресті головних торговельних шляхів Вінтерспрінгу, тож товари прибувають сюди торговельними перельотами й наземними караванами цими дорогами.",al={"контрабанда евірлука","товари вінтерспрінгу","звідки товари евірлука"}}},fp="8,266,33.520.0,19.526.0,22.176.0,49.214.0,35.205.0,40.145.0"}
P.entries["subzone:faldir-s-cove"] = {n="Бухта Фалдіра",s="Бухта Фалдіра — відлюдна природна гавань на південному узбережжі Аратійського нагір'я. Вона овіяна людською історією: за переказами, саме звідси перші поселенці вирушили на південь, щоб заснувати Стормвінд. Нині вона правує за вимушений прихисток для Нападників Чорної Води, чий флот потрапив у біду через місцеві небезпеки.",h="Бухта Фалдіра — відлюдна природна гавань на південному узбережжі Аратійського нагір'я.",kw={"бухта фалдіра","фалдір","нападники чорної води","пірати","стормвінд","наги","провісник"},ang={["race:Gnome"]="У таборі працюють Доктор Дракслґейдж і Професор Фізлторп, що розгорнули хитромудрі інженерні пристрої, аби досліджувати скам'янілі прибережні рифи й видобувати з них ельфійські самоцвіти.",["race:Human"]="Стоячи на цих берегах, люди торкаються своєї давньої спадщини: саме тут предки Стормвінда розлучилися з прадавньою імперією Аратор."},sec={{t="Брама на південь і піратська гавань",b="Бухта Фалдіра ховається за скелястими кручами на південь від Фортеці Стромгард, а з суходолом її з'єднує прихований печерний тунель. Бухта шанує пам'ять Фалдіра — давнього аратійського дослідника, чия експедиція вирушила саме з цих берегів, щоб перетнути Велике Море й заснувати південне королівство Стормвінд. Та нині в її тихих водах зовсім інше товариство: експедиція Нападників Чорної Води з Буті Бей на чолі з капітанами Стілґатом і О'Бріном, які подалися на північ по прадавні ельфійські скарби, а опинилися в пастці в затоці."},{t="Загибель флоту Чорної Води",b="Біля аратійського узбережжя похід Чорної Води обернувся катастрофою. Дивні, неприродні припливи, викликані нагами, що ревно стережуть свій Затоплений Риф неподалік берега, розбили два з трьох кораблів. Цілим лишився тільки «Провісник», що ледве дошкандибав до Бухти Фалдіра. Наги нишпорять у водах, морські мапи лежать на дні, тож уцілілі пірати та їхні дослідники-гноми опинилися відрізаними від світу й покладаються на нейтральних мандрівників, які б'ються з морськими жахіттями й піднімають затонуле добро."}},faq={{q="Хто такий Фалдір?",a="Фалдір був давнім першопрохідцем ранньої людської Імперії Аратор. Він і його послідовники вирушили з цієї прибережної гавані за море, подавшись на південь, щоб заснувати поселення, які зрештою стали королівством Стормвінд.",al={"історія фалдіра","хто такий фалдір","засновник фалдіра"}},{q="Як дістатися до Бухти Фалдіра?",a="До бухти веде прихований тунель трохи на південний схід від зовнішніх південних мурів Фортеці Стромгард. Пройшовши цим підземним тунелем, мандрівники виходять просто на відлюдний берег.",al={"як дістатися до бухти фалдіра","вхід у бухту фалдіра","печера до бухти фалдіра"}},{q="Чому тут Нападники Чорної Води?",a="Капітан Стілґат і Капітан О'Брін повели експедицію з Буті Бей на північ шукати затонулі ельфійські скарби. Разом із гномами-винахідниками, що сконструювали прилади для пошуку самоцвітів, вони збиралися підняти коштовні реліквії, скам'янілі в рифах біля берега.",al={"чому тут пірати","нападники чорної води араті","що роблять пірати"}},{q="Що сталося з їхніми кораблями?",a="Два з трьох кораблів експедиції знищили неприродні припливи, які здійняли ворожі наги із Затопленого Рифу. Лише флагман «Провісник» щасливо дістався бухти, і команда опинилася на мілині без своїх затонулих мап.",al={"чому кораблі розбиті","затонулі кораблі араті","хто потопив кораблі"}}},fp="13,356,34.569.0,33.529.0,15.243.0,31.221.0,36.256.0,29.240.0"}
P.entries["subzone:falfarren-river"] = {n="Річка Фалфаррен",s="Річка Фалфаррен тече з північного сходу на південний захід через серце Ашенвалю: вона бере початок на схилах Гори Гіджал, а потім ховається під землю під північними горами Пусток. Річка — природний кордон між володіннями нічних ельфів довкола Астранаару на заході та заставами Орди, що наступають зі сходу. Мандрівникам варто бути обережними: тінисті береги й мілини — прихисток ворожих звірів і край відкритої війни.",h="Річка Фалфаррен тече з північного сходу на південний захід через серце Ашенвалю: вона бере початок на схилах...",kw={"річка фалфаррен","ашенваль","кордон","гора гіджал","ксавіан","болотяні звірі"},ang={["faction:Alliance"]="Для нічних ельфів та їхніх союзників перейти Фалфаррен на схід означає ступити просто на передову Орди біля Застави Розщепленого Дерева.",["faction:Horde"]="Фалфаррен — західна межа, до якої Орда просунулася від Застави Розщепленого Дерева; за нею лежать укріплені землі нічних ельфів."},sec={{t="Спірний природний кордон",b="Спускаючись із Гори Гіджал, води Фалфаррену водоспадами збігають у Ксавіан, а потім петляють між Заставою Розщепленого Дерева й Нічним Потоком. Річка не надто глибока і за звичайної погоди цілком прохідна, проте саме вона приблизно ділить центральний Ашенваль між ворожими сторонами. На заході лежать Астранаар і головні володіння калдореїв, на сході — табори й лісорубні Орди. Перейшовши дерев'яні мости головної дороги, мандрівник опиняється у спірному серці лісу, де вздовж берегів сходяться патрулі."},{t="Небезпеки на мілинах",b="Окрім протистояння вартових і піхотинців Орди, річка ховає під водою небезпеки і природні, і неприродні. Нижче за течією, біля Пагорба Вогню Скверни, мулистими мілинами нишпорять осквернені болотяні звірі й агресивні водяні створіння. Дощі можуть роздути течію, та справжня загроза — у густих кронах по обидва береги, звідки засідки й сутички раз у раз виплескуються просто в потік."}},faq={{q="Де починається й закінчується Річка Фалфаррен?",a="Річка Фалфаррен бере початок на висотах Гори Гіджал і водоспадами спадає в озеро біля Ксавіана. Звідти вона петляє на південний захід через Ашенваль, а тоді пірнає під землю, у підземні русла під північними горами Пусток.",al={"витік річки фалфаррен","куди тече річка"}},{q="Чим Річка Фалфаррен важлива для війни в Ашенвалі?",a="Вона приблизно позначає межу між землями нічних ельфів і Орди в центрі Ашенвалю. На заході — володіння нічних ельфів з осердям в Астранаарі, а на сході — орківська Застава Розщепленого Дерева й діючі лісорубні Орди.",al={"чому річка фалфаррен важлива","межа річки ашенвейл"}},{q="Яких загроз варто чекати мандрівникам на берегах річки?",a="Мілинами никають агресивні болотяні чудовиська, особливо біля зіпсованих місцин довкола Пагорба Вогню Скверни. До того ж патрулі і Альянсу, і Орди пильнують мости й переправи, тож неохоронювані береги — ідеальне місце для сутичок і засідок.",al={"монстри річки фалфаррен","небезпеки фалфаррену"}}},fp="15,448,28.563.0,23.395.0,45.261.0,63.255.0,58.267.0"}
P.entries["subzone:fallen-sky-lake"] = {n="Озеро Впалого Неба",s="Озеро Впалого Неба — відлюдна водойма в глибині лісів східного Ашенвалю. Воно лежить між Заставою Срібнокрилих і Трудовим Табором Бойової Пісні, що дедалі ближче підступає, а його спокійні води таять небезпеку: лісові створіння Тінявої Хащі люто захищають озеро та острів посередині.",h="Озеро Впалого Неба — відлюдна водойма в глибині лісів східного Ашенвалю.",kw={"озеро впалого неба","тінява хаща","оракул","застава срібнокрилих","ашенваль"},ang={["class:Druid"]="Ці лісові створіння здавна вважаються священними, бо їх торкнулася ласка Елуни, тож осквернені, агресивні мешканці Тінявої Хащі на Озері Впалого Неба — тривожне видовище.",["race:NightElf"]="Озеро, що лежить трохи на південь від Застави Срібнокрилих, — ще один куточок священного прадавнього лісу, де звірі стали непередбачуваними під гуркіт барабанів Орди, що наближаються."},sec={{t="Спірне святилище",b="Озеро Впалого Неба, що сховалося на південь від Застави Срібнокрилих і трохи на захід від Трудового Табору Бойової Пісні, дає змогу на мить побачити природну пишноту Ашенвалю такою, якою вона була, доки поблизу не застукотіли орківські сокири. Береги й острівець посеред озера населяють створіння Тінявої Хащі — осквернені чи просто ревниві до своєї землі лісовики, для яких будь-який двоногий прибулець — загроза. Серце острова — володіння могутнього Оракула Тінявої Хащі, чия присутність прив'язує місцевих лісовиків до гаю й робить їх невсипуще пильними до мандрівників."}},faq={{q="Де Озеро Впалого Неба?",a="Озеро Впалого Неба — на сході Ашенвалю, просто на південь від Застави Срібнокрилих, на захід від Трудового Табору Бойової Пісні й на північний схід від Гаю Срібнокрилих.",al={"розташування озера впалого неба","де озеро впалого неба","як знайти озеро впалого неба"}},{q="Які істоти живуть довкола Озера Впалого Неба?",a="Озеро й береги довкола заполонили створіння Тінявої Хащі — агресивні дикі місячники — на чолі з грізним Оракулом Тінявої Хащі, що живе на острові посередині.",al={"монстри озера впалого неба","що біля озера впалого неба","вороги озера впалого неба"}},{q="Чим важливий Оракул Тінявої Хащі?",a="Оракул Тінявої Хащі — матріархиня-провідниця лісових місячників, що зібралися біля озера. Мандрівникам і розвідникам в Ашенвалі часто доручають вистежити оракула на її острові, щоб послабити загрозу ворожих диких місячників.",al={"оракул озера впалого неба","оракул тінявої хащі","хто на острові"}}},fp="15,303,21.568.0,33.153.0,43.170.0,41.228.0"}
P.entries["subzone:faol-s-rest"] = {n="Спочинок Фаола",s="Спочинок Фаола — тихе, занедбане поховання у східних Галявинах Тірісфалю, одразу на південний захід від Багряного Монастиря. Його звели як гробницю Архієпископа Алонсуса Фаола — шанованого духовного патріарха, що заснував Лицарів Срібної Длані. Сьогодні, занедбане під ураженою чумою кроною, воно править за цвинтар, де повертаються до життя ті, хто загинув біля монастиря.",h="Спочинок Фаола — тихе, занедбане поховання у східних Галявинах Тірісфалю, одразу на південний захід від...",kw={"спочинок фаола","алонсус фаол","архієпископ","гробниця","срібна рука","багряний монастир","тірісфаль"},ang={["class:Paladin"]="Кожен паладин завдячує своїм покликанням Архієпископу Фаолу, який першим зібрав Утера та його побратимів, щоб поєднати бойове мистецтво зі Святим Світлом. Стояти перед його занедбаною гробницею — тверезе нагадування про витоки ордену.",["class:Priest"]="Як верховний очільник Церкви Святого Світла в Другу війну, Фаол був пастирем усього жрецтва Лордерона; бачити його пам'ятник у руїнах — усе одно що бачити трагічну руїну церкви на півночі."},sec={{t="Гробниця Архієпископа",b="До того як Третя війна спустошила Лордерон, ця відлюдна улоговина була місцем урочистого паломництва. Тут стоїть кам'яна гробниця Архієпископа Алонсуса Фаола, який вів Церкву Святого Світла крізь темні дні Другої війни й заснував орден паладинів, щоб захищати людство. Фаол мирно відійшов до приходу Погибелі, уникнувши смертної муки бачити падіння свого королівства. У ті світліші роки скорботні регулярно йшли дорогою зі столичного міста Лордерона, щоб лишити дари й ушанувати улюбленого патріарха."},{t="Пустка в тіні Монастиря",b="Коли Чума Нежиті прокотилася Лордероном, Тірісфаль усох, а паломники зникли. Сьогодні пам'ятник стоїть покинутий і потрісканий у тінях під високими кручами Багряного Монастиря. Дикі хащі відвоювали стежки, а сама гробниця лежить нерухомо серед вологої імли. Для шукачів пригод, що б'ються з фанатиками Багряного Хрестового Походу чи рештками жахів Тірісфалю, це забуте місце спочинку тепер слугує здебільшого тихим порогом, де полеглі духи ненадовго збираються з силами, перш ніж повернутися в бій."}},faq={{q="Хто такий Алонсус Фаол?",a="Алонсус Фаол був Архієпископом Церкви Святого Світла під час Другої війни. Шанований за мудрість і милосердя, він організовував допомогу біженцям і заснував Лицарів Срібної Длані, перетворивши святих жерців і побожних лицарів на перших паладинів людства, серед яких були Утер Світлоносець і Туральйон.",al={"хто такий фаол","алонсус фаол історія","хто тут похований"}},{q="Чому цей пам'ятник біля Багряного Монастиря?",a="Землі біля Багряного Монастиря здавна були важливими церковними володіннями Церкви Святого Світла на півночі Лордерона. Фаола поховали в цьому тихому куточку Галявин Тірісфалю ще до падіння королівства — задовго до того, як фанатики в багряному укріпили сусідній монастир.",al={"чому поруч із монастирем","зв'язок із багряним монастирем","значення розташування"}},{q="Чи доглядає хтось гробницю нині?",a="Ні. Відтоді як Лордерон упав під натиском Погибелі, місце цілком занедбане. Багряний Хрестовий Похід рідко спускається в лощину, щоб доглянути його, а Відступникам байдуже до святинь старої церкви, тож кам'яні знаки вивітрилися й заросли.",al={"хто доглядає спочинок фаола","чи покинутий","догляд за гробницею"}},{q="Яка практична користь від Спочинку Фаола для мандрівників?",a="Спочинок Фаола — місцевий цвинтар духів для навколишніх нетрів і Багряного Монастиря. Шукачі пригод, що гинуть, намагаючись прорватися в монастир чи мандруючи сходом Тірісфалю, повертаються духами до тихого пам'ятника Архієпископа.",al={"біг до цвинтаря","що це за місце в грі","цвинтар монастиря"}}},fp="11,371,22.547.0,41.541.0,21.325.0,56.301.0,37.280.0,60.263.0"}
P.entries["subzone:far-watch-post"] = {n="Далека Дозорна Застава",s="Далека Дозорна Застава — укріплений аванпост Орди трохи на захід від мосту через Річку Південної Люті, що з'єднує Дуротар із Пустками. Як передова лінія оборони орківської батьківщини, застава захищає важливі торгові каравани від агресивних зграй шипогривів і ворожих вилазок Альянсу.",h="Далека Дозорна Застава — укріплений аванпост Орди трохи на захід від мосту через Річку Південної Люті, що...",kw={"далека дозорна застава","орда","дуротар","річка південної люті","шипогриви","пустки"},ang={["faction:Alliance"]="Далека Дозорна Застава, що стоїть просто навпроти мосту з Дуротара, — грізна перепона, яка не дає розвідникам і диверсантам легко підібратися до орківської столиці.",["faction:Horde"]="Для молодих воїнів, що вперше виходять за межі Дуротара, Далека Дозорна Застава — останній форпост знайомої землі перед тим, як рушити в суворе й небезпечне серце Калімдору."},sec={{t="Вартовий кордону",b="Далека Дозорна Застава, що стоїть біля західного підніжжя мосту з Дуротара, — перший оплот влади Орди, який бачать мандрівники, вступаючи в неозору посушливу савану Пусток. Поселення аскетичне, але практичне: його будували заради бойової готовності, а не зручності. Тут є міцна орківська сторожова вежа, землянка й облогові катапульти, заздалегідь наведені на курні рівнини. Просто на південь від головної дороги робітники доглядають загін верхових вовків, готових нести гінців чи підкріплення. Застава існує насамперед для того, щоб тримати в безпеці шлях постачання до Перехрестя: перевіряти подорожніх і відбивати набіги кочових племен шипогривів і потайних розвідників Альянсу."}},faq={{q="Навіщо Далека Дозорна Застава?",a="Застава — головний прикордонний пост між Дуротаром і Пустками. Її захисники охороняють життєво важливі каравани Орди й стежать, щоб місцеві небезпеки — передусім агресивні племена шипогривів і непрохані гості з Альянсу — не переходили Річку Південної Люті в Дуротар.",al={"навіщо далека дозорна застава","призначення далекої застави","роль далекої застави"}},{q="Хто контролює цю заставу?",a="Далека Дозорна Застава — діючий військовий табір Орди. Орки-вояки стоять гарнізоном у вежі й доглядають облогові машини, а пеони доглядають їздових вовків.",al={"хто керує далекою заставою","фракція далекої застави"}},{q="З якими загрозами стикається застава?",a="Заставу часто непокоять зграї шипогривів, що оскаржують навколишні колючі чагарники. До того ж вона пильнує від набігів Альянсу, що можуть спробувати вдарити через Пустки на Оргріммар.",al={"вороги далекої застави","небезпеки далекої застави"}}},fp="14,293,22.683.0,38.265.0,26.175.0,35.233.0"}
P.entries["subzone:fargodeep-mine"] = {n="Копальня Фарґодіп",s="Копальня Фарґодіп — покинута золота копальня в центральному Лісі Елвінн, на південь від Ґолдшира. Колись прибуткове джерело багатства королівства Стормвінд, нещодавно її захопив войовничий клан кобольдів.",h="Копальня Фарґодіп — покинута золота копальня в центральному Лісі Елвінн, на південь від Ґолдшира.",kw={"копальня фарґодіп","кобольди","золото","копальня","золотозуб","ґолдшир","ліс елвінн"},ang={["faction:Alliance"]="Очистити Копальню Фарґодіп від погані вкрай важливо, щоб убезпечити шляхи постачання та ферми в найближчих околицях Ґолдшира.",["profession:Mining"]="Хоч копальня й кишить поганню, скелясті тунелі Фарґодіпу лишаються багатими на доступні мідні жили для шахтарів-початківців."},sec={{t="Втрачена жила",b="Копальня Фарґодіп колись давала сталий потік золота до скарбниці Стормвінда, та через дедалі меншу військову присутність королівства в Елвінні віддалені ресурси лишилися беззахисними. Кобольди швидко заполонили темні тунелі й облаштували під пагорбами гамірне кубло. Маршал Дуґан і місцева влада Ґолдшира дивляться на навалу з глибокою тривогою — не лише через втрачену руду, а й тому, що знахабнілі створіння тепер загрожують сусіднім садибам на кшталт володінь Стоунфілдів і Маклюрів."},{t="Глибини кубла",b="Копальня має кілька рівнів, а нижні штольні звиваються глибоко під лісовим ґрунтом. Кобольди-робітники та погань снують дерев'яними риштуваннями, люто боронячи свій зібраний віск і золотий пил. Глибше чаїться Золотозуб — особливо хитрий ватажок кобольдів, відомий тим, що збирає дрібнички, поцуплені в необачних мандрівників і навколишніх мешканців."}},faq={{q="Чому Стормвінд покинув Копальню Фарґодіп?",a="Копальню занедбали, коли сили Стормвінда розпорошилися по південних землях. Міська варта зосередилася на захисті Ґолдшира й головних доріг, тож підземні розробки лишилися без охорони, і туди вселилися й укріпилися в тунелях кобольди.",al={"чому покинули копальню","чому люди пішли з фарґодіпу","чия копальня фарґодіп"}},{q="Чому тутешні кобольди такі небезпечні для місцевих фермерів?",a="Копальня Фарґодіп лежить просто між фермами родин Стоунфілдів і Маклюрів. Кобольди вибираються з тунелів, щоб красти худобу, знаряддя й особисті речі, і непокоять кожного, хто підійде до входу в копальню.",al={"чому кобольди проблема","загроза кобольдів","кобольди кам'яного поля"}},{q="Хто такий Золотозуб?",a="Золотозуб — помітний кобольд, що гніздиться в глибині нижніх штреків Копальні Фарґодіп. Він горезвісний тим, що поцупив цінне родинне намисто тітоньки Берніс Стоунфілд.",al={"золотозуб","хто такий золотозуб","де золотозуб"}},{q="Чому мешканцям Ґолдшира потрібні речі з копальні?",a="Місцеві крамарі й мешканці бачать вигоду в очищенні копальні від шкідників: Ремі «Двічі» скуповує зібраний золотий пил, алхімік Вільям Пестл бере віск кобольдових свічок на реагенти, а Маршалові Дуґану треба стежити за навалою, щоб уберегти Елвінн.",al={"завдання фарґодіпу","навіщо збирати свічки","золотий пил"}}},fp="14,222,11.492.0,20.361.0,41.252.0,55.222.0,17.171.0,52.251.0"}
P.entries["subzone:farstrider-lodge"] = {n="Хутір Далекоходів",kw={"хутір далекоходів","далекоходи","високі ельфи","мисливці","телсамар","лох модан"},ang={["class:Hunter"]="Хутір Далекоходів — чудовий прихисток для мисливців: тут вас навчать і влучної стрільби, і приборкання звірів серед багатої дичини пагорбів Лох Модану."},sec={{t="Ельфійський прихисток у горах",b="Farstrider Lodge stands apart from the sturdy stone buildings typical of Khaz Modan. Its architecture suggests high elven craftsmanship. Vyrin Swiftwind is the only known high elf still residing here, alongside dwarves and humans. The lodge's founder and date of construction are not established."},{t="Перевалочна станція для диких країв",b="Situated in the southeastern hills of Loch Modan, the lodge serves hunters and travelers exploring the surrounding wilderness. Hunter and pet trainers work here alongside merchants and people seeking help with local wildlife."}},faq={{q="Звідки в Каз Модані ельфійський хутір?",a="The lodge's architecture suggests high elven origins, and Vyrin Swiftwind is its surviving high elven resident. Its founder, construction date, and original mission are not established.",al={"чому ельфійська будівля в лох модані","хто збудував хутір далекоходів","чому тут хутір високих ельфів"}},{q="Чи живуть тут ще високі ельфи?",a="Only a single high elf, Vyrin Swiftwind, currently resides at the lodge. The rest of the occupants are dwarven mountaineers and human huntsmen who maintain the lodge and trade with travelers.",al={"чи є тут високі ельфи","хто живе на хуторі далекоходів","вірін свіфтвінд"}},{q="Які послуги є на Хуторі Далекоходів?",a="The lodge provides hunter and pet trainers, merchants, and local requests involving the wilderness of Loch Modan.",al={"що на хуторі далекоходів","наставники мисливців лох модан"}}},fp="16,278,31.296.0,26.225.0,42.185.0,39.191.0,48.113.0"}
P.entries["subzone:feathermoon-stronghold"] = {n="Твердиня Перистого Місяця",s="Твердиня Перистого Місяця — головна військова база нічних ельфів на півдні Калімдора, надійно розташована на Острові Сардор біля Забутого Узбережжя Фераласу. Цією укріпленою заставою командує генерал Шандріс Фезермун: звідси Вартові тримають у шорах дикий ліс і пильнують усі загрози краю.",h="Твердиня Перистого Місяця — головна військова база нічних ельфів на півдні Калімдора, надійно розташована на...",kw={"твердиня перистого місяця","острів сардор","шандріс фезермун","вартові","нічні ельфи","фералас","альянс"},ang={["faction:Alliance"]="Для героїв Альянсу, що вирушають на південь Калімдора, Твердиня Перистого Місяця — це життєво важливі припаси, повітряні шляхи й осередок завдань посеред ворожих нетрів Фераласу.",["race:NightElf"]="Як головний табір Вартових на південь від Ашенвалю, ця фортеця втілює рішучість калдореїв боронити Калімдор під проводом генерала Шандріс Фезермун."},sec={{t="Південний оплот Вартових",b="Твердиня Перистого Місяця стоїть на Острові Сардор, через протоку від материкового Фераласу, і слугує головною стратегічною базою Вартових на півдні Калімдора. Фортецю звели серед прадавніх ельфійських гаїв, у ній є священний місячний колодязь, а лучниці, мисливиці та допоміжна залога служать під безпосереднім наглядом генерала Шандріс Фезермун. Із цього острівного прихистку нічні ельфи простягають свій вплив на зелені нетрі Фераласу, оберігаючи їх від демонічної скверни, лютого звіра й експедицій Орди, що підбираються дедалі ближче."},{t="Безпечна гавань серед диких земель",b="Материк Фераласу кишить лютими звірами, ограми Ґордунні та отруйними тінями Лютопащу, тож Острів Сардор — необхідний захисний буфер. Мандрівники з Альянсу перепливають поромом із Забутого Узбережжя до укріплених причалів, щоб полагодити спорядження й дізнатися новини. А присутність Шандріс Фезермун — названої доньки верховної жриці Тіранди Віспервінд і ветеранки Третьої війни — робить твердиню неприступним оплотом проти всіх ворогів калдореїв."}},faq={{q="Де Твердиня Перистого Місяця?",a="Твердиня Перистого Місяця стоїть на Острові Сардор біля Забутого Узбережжя на західному краю Фераласу. Щоб дістатися до острівної фортеці, мандрівникам треба перетнути ліс на захід до узбережжя й переплисти човном.",al={"розташування перистого місяця","де перистий місяць","як дістатися до твердині перистого місяця"}},{q="Хто командує Твердинею Перистого Місяця?",a="Твердинею командує Генерал Шандріс Фезермун — верховна командувачка війська Вартових і названа донька Верховної Жриці Тіранди Віспервінд. Із цієї застави вона керує всіма військовими діями калдореїв на півдні Калімдору.",al={"хто керує перистим місяцем","лідер перистого місяця","шандріс перистий місяць база"}},{q="Чому твердиня на острові, а не на материку?",a="Острів Сардор дає природний морський захист від численних небезпек материкового Фераласу, що кишить дикими звірами, ограми Ґордунні й рештками тайних і демонічних загроз. Фортеця на острові — надійний порт, що контролює прибережні води й тримає материкові загрози на відстані.",al={"чому острів сардор","чому перистий місяць на острові"}},{q="Чи є в Твердині Перистого Місяця місячний колодязь?",a="Так, у Твердині Перистого Місяця є священний місячний колодязь. Він дає духовне осердя, живлення й джерело святої води для гарнізону нічних ельфів, що стоїть далеко від рідного краю на півночі.",al={"місячний колодязь перистого місяця","чи є місячний колодязь у перистому місяці"}}},fp="22,307,29.554.0,25.535.0,40.242.0,36.250.0,67.310.0,44.218.0"}
P.entries["subzone:feathermoon-stronghold-classic"] = {n="Твердиня Перистого Місяця (класична версія)",s="Твердиня Перистого Місяця — укріплений оплот нічних ельфів на Острові Сардор біля західних берегів Фераласу. Заснувала її генерал Шандріс Фезермун, і тепер це головний плацдарм і військова опора Альянсу на півдні Калімдора.",h="Твердиня Перистого Місяця — укріплений оплот нічних ельфів на Острові Сардор біля західних берегів Фераласу.",kw={"твердиня перистого місяця","острів сардор","шандріс фезермун","вартові","гіпогрифи","фералас","альянс"},ang={["faction:Alliance"]="Твердиня Перистого Місяця — головний безпечний притулок, торговий пункт і плацдарм для всіх дій Альянсу в глибині південного Калімдора.",["race:NightElf"]="Твердиня — південний військовий осідок генерала Шандріс Фезермун і Вартових, надійний охоронець прадавніх диких земель."},sec={{t="Південний оплот Вартових",b="Твердиня Перистого Місяця стоїть на Острові Сардор неподалік Забутого Узбережжя — це важливий бастіон для нічних ельфів і всього Альянсу. Фортецю звели під проводом генерала Шандріс Фезермун, яка вже десять тисячоліть лишається довіреною соратницею Тіранди Віспервінд, і звідси сила Вартових сягає глибоко в південний Калімдор. Острівне розташування захищає твердиню від звірів, огрів і непроханих гостей з Орди, що нишпорять прадавніми джунглями материкового Фераласу."},{t="Рятівна нитка через хвилі",b="Через острівне розташування Перистий Місяць тримається насамперед на морських і повітряних шляхах. Невеликий пасажирський човен регулярно перевозить мандрівників через протоку між Островом Сардор і причалом на Забутому Узбережжі. Для далеких подорожей тут є сідало гіпогрифів, що пов'язує твердиню просто з головними осередками Альянсу — Таланааром на межі з Тисячею Голок, Мисом Ніджела на нагір'ях Пустограю та Обердайном на півночі."}},faq={{q="Як дістатися до Твердині Перистого Місяця з материкового Фераласу?",a="Мандрівники можуть сісти на пором, що відпливає від причалу на Забутому Узбережжі просто через протоку, або перепливти вузьку протоку до Острова Сардор. А члени Альянсу, знайшовши приборкувача летунів, можуть прилетіти на гіпогрифі.",al={"як дістатися до перистого місяця","човен до перистого місяця","шлях на острів сардор"}},{q="Хто командує Твердинею Перистого Місяця?",a="Заставою командує Генерал Шандріс Фезермун — високопоставлена очільниця Вартових, яка давно служить під проводом Верховної Жриці Тіранди Віспервінд.",al={"хто керує перистим місяцем","лідер перистого місяця","шандріс перистий місяць"}},{q="Чому твердиня на острові, а не на материку?",a="Острів Сардор дає природну відособленість і захист від численних загроз фералаських нетрів — агресивних звірів, первісних руїн і ворожих сил, — тож Вартові можуть утримувати неприступну твердиню.",al={"чому на острові сардор","чому острівна фортеця","розташування перистого місяця історія"}},{q="Куди ведуть повітряні шляхи з Перистого Місяця?",a="Приборкувач гіпогрифів Перистого Місяця підтримує маршрути по всьому західному Калімдору, зокрема до Обердайна на Темному Узбережжі, Мису Ніджела в Пустограї, Таланаара у Фераласі й Цитаделі Кенаріуса в Силітусі.",al={"майстер польотів перистого місяця","куди летять гіпогрифи з перистого місяця"}}},fp="32,252,29.474.0,25.443.0,62.243.0,36.175.0,67.226.0,47.198.0"}
P.entries["subzone:fel-rock"] = {n="Скеля Скверни",s="Скеля Скверни — уражена печера, схована в лісі одразу на північ від Доланаара на гіллі Тельдрассила. Колись тиха улоговина, вона занепала під впливом сатира Лорда Меленаса та його орди лютих ґреллів.",h="Скеля Скверни — уражена печера, схована в лісі одразу на північ від Доланаара на гіллі Тельдрассила.",kw={"скеля скверни","печера","сатир","лорд меленас","ґрелли","доланаар","тельдрассил"},ang={["class:Druid"]="Друїди Кола Кенарія бачать у Скелі Скверни гнійну рану на молодому Світовому Дереві, яку треба негайно вичистити, поки демонічна скверна не поширилася.",["race:NightElf"]="Для калдореїв присутність такого сатира, як Лорд Меленас, так близько до Доланаара — тривожна образа Тельдрассилу, що вимагає швидкої відплати."},sec={{t="Лігво скверни",b="Скеля Скверни в лісистих пагорбах на північ від Доланаара колись була звичайною мирною печерою, вирізьбленою в дереві й камені Тельдрассила. Сьогодні це тривожне нагадування про заразу, що підкрадається до Світового Дерева. Покручене коріння й неприродні тіні панують у нутрі печери, яку заполонили рої диких ґреллів і ґреллят."},{t="Твердиня сатира",b="Скверна в Скелі Скверни походить від Лорда Меленаса — лихого сатира, що зробив улоговину своєю твердинею. З глибини печери він керує поширенням злої зарази просто під пильним оком вартових нічних ельфів. Друїди з Доланаара, насамперед Таллонкай Свіфтрут, активно залучають здібних захисників очистити печеру й убити Меленаса, перш ніж його нечиста пошесть пошириться далі в довколишні ліси."}},faq={{q="Де Скеля Скверни?",a="Скеля Скверни — у центрі Тельдрассила, захована серед пагорбів просто на північ від поселення Доланаар.",al={"розташування скелі скверни","де скеля скверни","знайти скелю скверни"}},{q="Хто править Скелею Скверни?",a="Печерою керує Лорд Меленас — мерзенний сатир, що влаштував у Скелі Скверни своє лігво й зібрав зграю греллів, які виконують його накази.",al={"хто на скелі скверни","бос скелі скверни","де лорд меленас"}},{q="Чому друїдів непокоїть Скеля Скверни?",a="Сатир і зіпсовані Скверною грелли серед гілок Світового Дерева — пряма загроза природній рівновазі Тельдрассила. Друїди на кшталт Таллонкая Свіфтрута посилають шукачів пригод убити Лорда Меленаса й зупинити скверну.",al={"чому очищати скелю скверни","завдання скелі скверни","завдання таллонкай свіфтрут"}},{q="Які істоти живуть у печері?",a="У Скелі Скверни ви зустрінете агресивних греллів, грелленят і їхнього темного володаря — сатира Лорда Меленаса.",al={"монстри скелі скверни","що всередині скелі скверни","вороги скелі скверни"}}},fp="8,238,19.354.0,16.468.0,26.110.0,19.133.0,40.244.0,39.111.0"}
P.entries["subzone:felfire-hill"] = {n="Пагорб Вогню Скверни",s="Пагорб Вогню Скверни — сплюндроване, заполонене демонами узвишшя на сході Ашенвалю. Під час Третьої війни сюди падали інфернали, і зіпсована земля досі палає демонічною силою. Орда тримає укріплені пости на мостах, що ведуть до пагорба, щоб захистити свої ближні поселення.",h="Пагорб Вогню Скверни — сплюндроване, заполонене демонами узвишшя на сході Ашенвалю.",kw={"пагорб вогню скверни","інфернали","палаючий легіон","демони","орда","ашенваль"},ang={["class:Warlock"]="Сира енергія скверни, що лишилася там, де приземлилися інфернали Легіону, робить цей пошрамований пагорб предметом небезпечної цікавості для адептів темної магії.",["faction:Horde"]="Орда утримує укріплені мости довкола Пагорба Вогню Скверни, щоб захистити від демонічних набігів дорогу, яка з'єднує Заставу Розщепленого Дерева з Лісозаготівельним Табором Бойової Пісні."},sec={{t="Шрам Палаючого Легіону",b="Під час нищівного вторгнення Третьої війни на Калімдор сипалися вогняні метеори: Палаючий Легіон кидав у бій своїх грізних інферналів. Кілька тих вогняних велетнів ударили в цей пагорб в Ашенвалі, випаливши давній ліс і отруївши саму землю. Сьогодні випалений край досі просякнутий енергією скверни, і тут никають демони, що пережили поразку Легіону біля Гори Гіджал."},{t="Варта на переправах",b="Пагорб Вогню Скверни лежить на південний схід від Застави Розщепленого Дерева й на південний захід від Лісозаготівельного Табору Бойової Пісні — незатишно близько до важливих володінь Орди. Рештки демонів можуть вихлюпнутися в довколишній ліс, тож Орда звела укріплені барикади й вартові вежі на обох мостах до пагорба, замкнувши мерзенних створінь у їхньому сплюндрованому лігві."}},faq={{q="Чому Пагорб Вогню Скверни зіпсований?",a="Під час Третьої війни на цей пагорб із неба падали інфернали Палаючого Легіону. Удари й подальше отруєння Скверною випалили незайманий ельфійський ліс, лишивши поранене каміння й псувальну демонічну енергію, що так і не розвіялася.",al={"чому пагорб вогню скверни зелений","історія пагорба вогню скверни","що сталося з пагорбом вогню скверни"}},{q="Які істоти живуть на Пагорбі Вогню Скверни?",a="Пагорб займають уцілілі демони й інфернальні створіння, що лишилися після навали Легіону в Третій війні. Вони й досі ворожі до всіх смертних, що забрідають на їхні зіпсовані околиці.",al={"монстри пагорба вогню скверни","хто живе на пагорбі вогню скверни"}},{q="Чому Орда укріпила тут мости?",a="Пагорб Вогню Скверни лежить просто між Заставою Розщепленого Дерева й Лісозаготівельним Табором Бойової Пісні. Командири Орди укріпили обидва мости, щоб демони не вирвалися й не змели сусідні табори, обози з припасами й лісорубні.",al={"орда міст вартові скверни","чому орки охороняють пагорб вогню скверни"}},{q="Чи пов'язаний Пагорб Вогню Скверни з нічними ельфами?",a="Колись сам пагорб був частиною священного лісу Ашенвалю, а тепер він зловісно височіє на північний схід від Курганного Лігва Дор'Даніл. Демонічна скверна, що повзе довкола, і мандрівні потвори — постійна загроза для сусідніх місць сну й навколишніх нетрів.",al={"дор'даніл пагорб вогню скверни","демони курганного лігва"}}},fp="12,296,28.418.0,22.387.0,30.264.0,36.201.0,43.238.0,45.262.0"}
P.entries["subzone:felpaw-village"] = {n="Село Сквернолапих",s="Село Сквернолапих — осквернене поселення фурболгів на крайній півночі Сквернолісся, що стереже гірську стежку просто до Твердині Деревопащих. Тут живе занепале плем'я Мертволісся, а його хатини й місця зборів отруєні демонічним впливом і ворожі до всіх чужинців.",h="Село Сквернолапих — осквернене поселення фурболгів на крайній півночі Сквернолісся, що стереже гірську стежку...",kw={"село сквернолапих","фурболги","мертволісся","твердиня деревопащих","сквернолісся","деревопащі"},ang={["class:Druid"]="Для друїдів, відданих відновленню природного ладу, занепалі фурболги Мертволісся із Села Сквернолапих — трагічне нагадування про отруту Легіону, що досі лишається у священних лісах.",["race:NightElf"]="Колись нічні ельфи вважали фурболгів вірними союзниками, тож видовище безумства й обрядового занепаду Мертволісся в Селі Сквернолапих для них особливо гірке."},sec={{t="Твердиня скверни",b="Село Сквернолапих на північному краю Сквернолісся — головний північний прихисток занепалих фурболгів Мертволісся. Колись лагідні охоронці лісу, вони стали жертвами демонічної зарази, яку випустили в Третю війну, і впали в дике безумство. Тепер село — зачумлений анклав, повний грубих хатин, обрядових тотемів і ворожих воїнів, які нападають на кожного, хто забреде до входу в тунель до Твердині Деревопащих."},{t="Більмо на оці Твердині Деревопащих",b="Село Сквернолапих так близько до священного входу в Твердиню Деревопащих, що стало серйозною загрозою для небагатьох незіпсованих фурболгів, які ще лишилися в краї. Вартові Деревопащих, що стоять при північному виході зі Сквернолісся, дивляться на своїх занепалих родичів зі змішаним почуттям скорботи й пильності. Вони часто просять мандрівників прорідити лави Мертволісся, забрати їхні обрядові фетиші й не дати скверні просочитися крізь браму до Місячного Гаю та Вінтерспрінгу."}},faq={{q="Хто живе в Селі Сквернолапих?",a="Поселення належить фурболгам Мертволісся — місцевому племені, що цілком піддалося демонічній скверні, яка поширюється Сквернолісся.",al={"мешканці села сквернолапих","хто в селі сквернолапих","фурболги мертволісся північний скверноліс"}},{q="Чому тутешні фурболги ворожі?",a="Фурболгів Мертволісся довела до повного божевілля демонічна енергія, що отруює ґрунт, воду й звірів Сквернолісся. Усіх чужинців вони вважають ворогами, і з ними неможливо домовитися.",al={"чому мертволісся нападають","чи дружні сквернолапі фурболги","чому ведмеді злі в сквернолісі"}},{q="Де Село Сквернолапих?",a="Воно на крайньому півночі Сквернолісся, просто біля дороги, що веде до головного південного входу Твердині Деревопащих.",al={"розташування села сквернолапих на мапі","де село сквернолапих","як дістатися до сквернолапих"}},{q="Як Село Сквернолапих пов'язане з Твердинею Деревопащих?",a="Незіпсоване плем'я Деревопащих пильно стежить за Селом Сквернолапих зі своєї брами неподалік. Мертволісся загрожує безпеці проходу між Сквернолісся, Вінтерспрінгом і Місячним Гаєм, тож Деревопащі винагороджують чужинців, які проріджують ворожі лави села й здобувають обрядові пера Мертволісся.",al={"зв'язок із деревопащими","репутація деревопащих сквернолапі","деревопащі й мертволісся"}}},fp="14,293,26.455.0,29.465.0,28.152.0,34.187.0,32.124.0,49.295.0"}
P.entries["subzone:felstone-field"] = {n="Поле Скверного Каменю",s="Поле Скверного Каменю — спустошена ферма на північному заході Західних Чумних Земель. Колись це була квітуча частина хліборобських угідь Лордерону, але тепер її захопила Погибель і поставила тут чумний казан, що вивергає над зруйнованою землею отруйні випари.",h="Поле Скверного Каменю — спустошена ферма на північному заході Західних Чумних Земель.",kw={"поле скверного каменю","дженіс фелстоун","чумний казан","байлмо","багряний хрестовий похід","західні чумні землі"},ang={["faction:Alliance"]="Для вцілілих з Альянсу, що живуть у Стормвінді, такі місця, як Поле Скверного Каменю, — це втрачені родові землі й розкидана рідня, як-от Стара Емма, яка досі чіпляється за права на зруйновану північну спадщину.",["race:Undead"]="Зруйнована ферма суворо нагадує про життя, яке Відступники колись мали в Лордероні; особливо гостро це відчувають ті, хто, як Джеремая Пейсон, уцілів лише ціною нежиття."},sec={{t="Спустошена садиба",b="До Третьої війни Поле Скверного Каменю було мирною, щедрою родинною фермою, що годувала мешканців Лордерону. Коли північчю прокотилася чума, садиба швидко впала під натиском Культу Проклятих і Погибелі. Нині на полях замість зерна проростають мертві бур'яни й повзуча гниль. Посеред угідь стоїть величезний чумний казан, що безупинно випускає в небо смердючі випари під наглядом Володаря Казана Байлмо та цілих легіонів кістяних шкуродерів, чаклунів і ненажерливих гулів."},{t="Неупокоєні привиди й фанатики",b="Попри навалу нежиті, у руїнах досі лишаються сліди світу живих. У північно-східному будинку блукає привид Дженіс Фелстоун — у скорботі вона бродить порожньою оболонкою свого колишнього дому. А тим часом патрулі сусіднього Багряного Хрестового Походу нишпорять околицями угідь, жорстоко винищуючи всю нежить на своєму шляху й убиваючи кожного стороннього, хто надто наблизиться."}},faq={{q="Що робить казан посеред поля?",a="Казан — чумна машина Погибелі, що насичує навколишню землю й повітря пошестю, псує ґрунт і підіймає мерців. Його стереже могутній наглядач Погибелі, Володар Казана Байлмо, разом із прислужниками-кістяками й гулями.",al={"казан скверного каменю","чому тут казан","казан чуми скверного каменю"}},{q="Чий привид у хаті?",a="Привид — Дженіс Фелстоун, колишня господиня хутора, що загинула, коли край захопила Погибель. Не бажаючи чи не можучи знайти спокою, її дух лишається прикутим до руїн родинного дому.",al={"джанис скверний камінь","привид у хаті скверного каменю","хто в хаті"}},{q="Чому фермою патрулюють хрестоносці Багряного Походу?",a="Багряний Хрестовий Похід часто посилає в Західні Чумні Землі агресивні ударні загони нищити Погибель. Будь-яких мандрівників, що забредуть сюди, — з Орди чи з Альянсу — вони вважають можливими розносниками чуми чи ворогами й нападають на все, що бачать.",al={"багряний похід скверний камінь","хрестоносці на полі скверного каменю"}},{q="Кому насправді належить купча на Поле Скверного Каменю?",a="І Джеремая Пейсон в Андерсіті, і Стара Емма в Стормвінді стверджують, що отримали купчу від своєї сестри, Дженіс Фелстоун. Досі загадка, чи склали дві купчі, чи чумний безлад безнадійно заплутав спадок між живими й неживими членами родини.",al={"купча на поле скверного каменю","хто володіє скверним каменем","купча краще пізно ніж ніколи"}}},fp="14,254,20.508.0,28.408.1,54.264.0,38.204.0,52.246.0,45.291.1"}
P.entries["subzone:fenris-isle"] = {n="Острів Фенріс",s="Острів Фенріс — великий, оповитий туманом острів на Озері Лордамер біля східного краю Срібнолісся. Колись тут стояла гамірна військова твердиня Лордерона, а тепер острів у залізних лабетах гнилошкірих гнолів-нежиті й некроманта-ренегата з Погибелі.",h="Острів Фенріс — великий, оповитий туманом острів на Озері Лордамер біля східного краю Срібнолісся.",kw={"острів фенріс","фортеця фенріс","тул рейвенклов","гнилошкірі гноли","озеро лордамер","срібнолісся"},ang={["race:Undead"]="Для Відступників Острів Фенріс — нестерпний оплот Погибелі просто на власному подвір'ї, і треба безупинно бити по ньому, щоб гнилошкірі Тула Рейвенклова не заполонили східні води Срібнолісся."},sec={{t="Полегла твердиня на озері",b="До того як Третя війна спустошила північний Лордерон, Острів Фенріс був важливою заставою королівства, опорою якої була Фортеця Фенріс. Коли Погибель пройшлася королівством, гарнізон вирізали або ж він утік у вигнання, і острів дістався мерцям. Відтоді острів став твердинею гнилошкірих гнолів — мерзенних, уражених чумою створінь, що збудували грубу імперію на берегах озера. Відступники Срібнолісся пильно стежать за островом, вважаючи його вкорінених мешканців серйозною загрозою своїм північним землям."},{t="Господар Фортеці Фенріс",b="Гнилошкірі гноли діють не самі. У напівзруйнованих кам'яних залах Фортеці Фенріс живе Тул Рейвенклов — хитрий некромант, колись пов'язаний із Кірін-Тором, що звернувся до темних мистецтв Погибелі. Тул підкорив місцевих гнолів своїй волі, темним чаклунством піднімаючи їхніх полеглих родичів і укріплюючи острів від загарбників. Із цього відокремленого прихистку Тул пильнує переправи через озеро, тож розвідники Відступників і сили Орди завдають випереджальних ударів, щоб зламати його владу над островами."}},faq={{q="Що таке Острів Фенріс?",a="Острів Фенріс лежить на Озері Лордамер біля східного узбережжя Срібнолісся. До Третьої війни він був укріпленим притулком королівства Лордерон, а тепер кишить зачумленими гнолами й прислужниками Погибелі.",al={"де острів фенріс","острів фенріс історія","що це за острів"}},{q="Хто нині контролює Острів Фенріс?",a="The Rot Hide gnolls occupy the island and use Fenris Keep as their stronghold. Forsaken investigators seek to establish the source of their growing threat.",al={"хто керує островом фенріс","боси острова фенріс","хто живе на острові фенріс"}},{q="Що сталося з людьми, які тут жили?",a="Під час Третьої війни, коли Погибель захоплювала Лордерон, людей — захисників і мешканців Фортеці Фенріс — убили або прогнали. Фортеця стояла в руїнах, доки порожні мури не привласнили гноли й некроманти.",al={"що сталося з людьми фенріс-кіпу","хто збудував фортецю фенріс"}},{q="Чому Орда хоче напасти на острів?",a="The Forsaken consider the entrenched Rot Hide gnolls a threat to Silverpine Forest and the nearby ferry crossing. Their agents seek help investigating and disrupting the island's hostile forces.",al={"напад на острів фенріс","чому орда нападає на острів фенріс","відступники острів фенріс"}}},fp="11,266,31.583.0,25.525.1,20.258.0,35.155.0,50.229.0,52.194.0"}
P.entries["subzone:fenris-keep"] = {n="Фортеця Фенріс",s="Фортеця Фенріс — відокремлена кам'яна фортеця на Острові Фенріс посеред Озера Лордамер. Колись стратегічна твердиня, де стояли війська Лордерона, тепер вона в руках Погибелі під орудою мага-ренегата Тула Рейвенклова.",h="Фортеця Фенріс — відокремлена кам'яна фортеця на Острові Фенріс посеред Озера Лордамер.",kw={"фортеця фенріс","острів фенріс","тул рейвенклов","погибель","кірін-тор","озеро лордамер"},ang={["class:Mage"]="Господар Фортеці Фенріс, Тул Рейвенклов, — похмура зрада вчення Кірін-Тору: він обернув таємні знання Даларана на темні мистецтва Погибелі.",["faction:Horde"]="Для Орди — і особливо для Відступників — Фортеця Фенріс лишається твердинею Погибелі, яку треба знищити, щоб убезпечити Срібнолісся й водні шляхи Озера Лордамер."},sec={{t="Полеглий оплот Лордерона",b="До Третьої війни Фортеця Фенріс мала стратегічне значення для королівства Лордерон: тут стояв чималий загін, що охороняв Озеро Лордамер. Коли нежить Погибелі прокотилася краєм, острівна фортеця впала разом із рештою королівства. Замість обернутися на забуті руїни, її захопив Тул Рейвенклов — зрадник, колишній чарівник Кірін-Тору. Рейвенклов став союзником Погибелі, мерзенною некромантією підкорив місцевих гнолів, створивши ненажерливу зграю гнилошкірих, і окопався глибоко в кам'яних залах фортеці."},{t="Погибель на Лордамері",b="Сьогодні Фортеця Фенріс — осідок влади Рейвенклова й неминуча загроза для Відступників, що утримують Срібнолісся. З цього оплоту Тул керує легіонами гнилошкірих гнолів, які люто нападають на кожного, хто наважиться ступити на острів. Острів Фенріс лежить лише за кілька миль від кордону Тірісфалю, тож Відступники з Гробниці й Андерсіті постійно посилають героїв зламати оборону фортеці й покласти край некромантові-ренегату."}},faq={{q="Що таке Фортеця Фенріс?",a="Фортеця Фенріс — укріплений кам'яний замок на Острові Фенріс посеред Озера Лордамер. Колись військова твердиня полеглого королівства Лордерон, нині вона в руках Погибелі.",al={"фортеця фенріс історія","що таке фортеця фенріс","замок фенріс"}},{q="Хто нині править Фортецею Фенріс?",a="Фортецею править Тул Рейвенклов — колишній маг Кірін-Тору, що зрадив живих, щоб служити Погибелі. Із фортеці він командує військом гнилошкірих гнолів, отруєних нежиттям.",al={"хто контролює фортецю фенріс","бос фортеці фенріс","володар острова фенріс"}},{q="Чому в Фортеці Фенріс гноли?",a="Тул Рейвенклов підкорив місцевих гнолів темною магією й хворобою, перетворивши їх на гнилошкірих гнолів. Вони — вірні ударні загони й вартові Рейвенклова по всьому замку й острову.",al={"гноли гнильошкірі фенріс","чому гноли у фортеці","гноли фенріс"}},{q="Чому Відступникам важлива Фортеця Фенріс?",a="Фортеця Фенріс дає Погибелі зручну для оборони базу на Озері Лордамер, звідки вона прямо загрожує пересуванням Відступників сходом Срібнолісся й Галявинами Тірісфалю. Сили Сильвани не можуть лишити діючого командира Погибелі без нагляду так близько до своїх кордонів.",al={"чому відступники нападають на фенріс","відступники фортеця фенріс","андеркрайт фенріс"}}},fp="11,235,29.591.0,24.473.1,20.194.0,32.187.0,40.238.0,43.262.0"}
P.entries["subzone:feral-scar-vale"] = {n="Долина Дикого Шраму",s="Долина Дикого Шраму — кам'яниста ущелина, захована у Високих Хащах західного Фераласу. Її заполонили войовничі єті Дикого Шраму, і печерні ходи долини мають лиху славу серед мандрівників, які зійшли з зарослих лісових стежок.",h="Долина Дикого Шраму — кам'яниста ущелина, захована у Високих Хащах західного Фераласу.",kw={"долина дикого шраму","єті","високі хащі","фералас","печери","робот"},ang={["class:Hunter"]="Кремезні єті Дикого Шраму, що бродять цими скелями, — поважне випробування для слідопита й мисливця на велику дичину серед густого лісового намету Високих Хащ.",["profession:Engineering"]="У тунелях єті застряг гномський робот-самохід, що вміє повертатися додому, — щоб безпечно вивести його до цивілізації, знадобиться рука інженера й аварійний маяк."},sec={{t="Лігво єті",b="Серед густої зелені та стрімких скель Високих Хащ Долина Дикого Шраму стала головним лігвом лютих єті Дикого Шраму. Єті звичні для засніжених вершин Альтераку й Дун Мороґу, але ці первісні звірюки цілком пристосувалися до дикого вологого клімату Фераласу. Вони затято боронять печери долини, збирають кісткові трофеї й люто проганяють кожного, хто забреде в їхні мисливські угіддя."},{t="Дивовижі в печерах",b="Окрім первісної загрози від єті, у глибоких закутках Долини Дикого Шраму ховаються несподівані дивацтва. Сюди, у темні печери, не раз приводили сигнали лиха від гномських механізмів: загублені дослідницькі пристрої — як-от роботизовані курчата-розвідники — опинялися в пастці лютих звірів і чекали, доки їх увімкнуть і виведуть звідти."}},faq={{q="Які істоти живуть у Долині Дикого Шраму?",a="У долині панують єті Дикого Шраму — величезні хижаки на вершині харчового ланцюга, що ревно стережуть свої володіння, гніздяться в скелястих печерах і патрулюють навколишній ліс.",al={"монстри долини дикого шраму","що в долині дикого шраму","істоти долини"}},{q="Де Долина Дикого Шраму?",a="Долина Дикого Шраму лежить на заході Фераласу, у краї, відомому як Високі Хащі, на південь від головної дороги, що прорізає крони тропічного лісу.",al={"розташування долини дикого шраму","де долина дикого шраму","як знайти долину дикого шраму"}},{q="Звідки єті в пишному тропічному лісі?",a="Єті зазвичай пов'язують із засніженими горами, але в давніх, неприборканих нетрях Калімдору живуть окремі підвиди — як-от єті Дикого Шраму, — що поколіннями процвітають у густих лісових долинах.",al={"чому єті в фераласі","єті в джунглях","єті фераласу історія"}},{q="Що за механічна курка в печері?",a="Глибоко в одній із печер долини лежить Самонавідний Робот OOX-22/FE — автономна механічна курка-розвідниця, створена гномами-інженерами, що розбилася й застрягла в тилу єті.",al={"оокс-22/фе","механічна курка фералас","робот-курка долини дикого шраму"}}},fp="15,232,17.450.0,24.355.0,47.148.0,33.158.0,41.215.0,47.187.0"}
P.entries["subzone:field-of-giants"] = {n="Поле Велетнів",s="Поле Велетнів — широка рівнина на півдні Пусток між Табором Тауражо й Багном Пилоброду. Назву вона отримала від велетенських кодо, громоящерів та інших могутніх звірів, що пасуться в посушливих чагарниках, а останнім часом стала значно небезпечнішою через навалу силітидів.",h="Поле Велетнів — широка рівнина на півдні Пусток між Табором Тауражо й Багном Пилоброду.",kw={"поле велетнів","силітиди","кодо","громоящери","золотий шлях","пустки"},ang={["class:Hunter"]="Мандрівні стада громоящерів і велетенських кодо роблять Поле Велетнів одним із найкращих мисливських угідь Пусток для тих, хто шукає грізних звірів.",["faction:Horde"]="Поява вуликів силітидів так близько від дороги між Табором Тауражо й Багном Пилоброду загрожує шляхам сполучення, тож ватажки по всіх Пустках скликають розвідників."},sec={{t="Дике прикордоння на півдні",b="Поле Велетнів, що простягається вздовж південної ділянки Золотого Шляху, — віддалений, суворий і погано захищений край порівняно з північними Пустками. Дерев'яні сторожові вежі при дорозі здебільшого покинуті, але сама земля вирує життям. Величезні стада велетенських звірів Калімдору блукають безкраїми рівнинами, приваблюючи і мисливців, і дослідників природи. Проте безпеки тут не знайти: дворфи-копачі з Бель Модана завзято риють на півдні, а під землею почала прокладати ходи значно зловісніша загроза."},{t="Повзучий рій",b="Останнім часом по всьому Полю Велетнів із землі повиростали вулики комахоподібних силітидів — це найпівнічніше місце на Калімдорі, де помічали цих ненажерливих створінь. Дивні горби й агресивні рої стривожили Орду. Розвідники, як-от троль Корран із Перехрестя, і воїни-таурени, як-от Руґа Рейджтотем із Табору Тауражо, закликають шукачів пригод дослідити вулики й з'ясувати, що тягне цих підземних жахіть так далеко від глибоких пустель."}},faq={{q="Чому воно зветься Поле Велетнів?",a="Рівнина дістала назву через величезні розміри звірів, що тут блукають. Тут пасуться великі стада височенних кодо й громоящерів, панують над краєвидом разом з іншими велетенськими звірами Калімдору.",al={"походження назви поля велетнів","чому поле велетнів"}},{q="Що за купи комах у землі?",a="Це кургани силітидів. Ці комахоподібні хижаки прокопалися з глибин і створили найпівнічніші вулики, знайдені в Калімдорі. Їхня раптова поява — грізна загроза для мандрівників і місцевих звірів.",al={"купи комах пустовиська","комахи південних пустовиськ","що таке силітиди"}},{q="Хто живе біля Поля Велетнів?",a="На самій рівнині поселень мало, але за її межами пильнують помітні постаті. Шаман Брайн живе на південному хребті, а вигнанець Ґанн Стоунспайр стежить неподалік, замишляючи удар по дворфійських розкопках у Бель Модані.",al={"хто тут живе","нпс поля велетнів"}},{q="Чому вартові вежі вздовж дороги покинуті?",a="Військова присутність Орди зосереджена здебільшого вздовж північного Золотого Шляху довкола Перехрестя. Найпівденніші околиці патрулюють куди рідше, тож ці вежі занедбані серед дедалі ближчих загроз силітидів і агресивних звірів.",al={"покинуті вежі золотого шляху","вартові вежі південних пустовиськ"}}},fp="15,307,28.517.0,18.478.0,37.206.0,40.231.0,35.247.0,49.253.0"}
P.entries["subzone:fire-plume-ridge"] = {n="Хребет Вогняного Шлейфу",s="Хребет Вогняного Шлейфу — діючий вулкан, що здіймається просто посеред Кратера Ун'Ґоро. Його розпечені схили й підземні канали магми живлять гейзери та парові озерця кратера, а сам він — дім для лютих вогняних елементалів.",h="Хребет Вогняного Шлейфу — діючий вулкан, що здіймається просто посеред Кратера Ун'Ґоро.",kw={"хребет вогняного шлейфу","вулкан","ун'ґоро","вогняні елементалі","полум'яний бігун","торій","лава"},ang={["class:Shaman"]="Духи вогню несамовито палають на хребті, даючи яскраво відчути неспокійні стихійні сили, що вирують під земною корою Калімдору.",["profession:Mining"]="Скелі та загартовані жаром схили хребта багаті на відкриті поклади руд — зокрема на жили щільного торію, що утворилися під вулканічним тиском."},sec={{t="Вогнище кратера",b="Хребет Вогняного Шлейфу височіє над первісною западиною Ун'Ґоро й різко контрастує з буйними джунглями довкола. Лава неспинно стікає його обпаленими скелями, витворюючи краєвид із попелу й базальту. Від хребта під землею павутиною розходяться артерії магми, що живлять вируючі гейзери й гарячі джерела, розкидані по западині. Спека тут легендарна — якщо вірити гоблінським вимірювальним приладам, вона значно перевищує звичайні вулканічні температури, — тож погано спорядженим дослідникам небезпечно блукати тут без доброго запасу води й прихистку в тіні."},{t="Лігво елементалів",b="Вулкан — це стихійна піч, що аж кипить живим полум'ям. Живі спалахи й мандрівні вогняні елементалі патрулюють сяйливі потоки, приваблені скупченням чистого підземного жару. Глибоко в печері біля вершини вулкана живе Полум'яний бігун — незаперечний володар серед стихійних мешканців Ун'Ґоро. Хто наважиться піднятися високо на хребет, муситиме долати і смертельну спеку, і мінливих духів стихій, що люто боронять свої вогняні володіння."}},faq={{q="Що за вулкан посеред Кратера Ун'Ґоро?",a="Це Хребет Вогняного Шлейфу — діючий вулкан у самому центрі Кратера Ун'Ґоро. Його розплавлені русла дають тепло, що гріє навколишні джунглі й гарячі джерела.",al={"назва вулкана ун'ґоро","вулкан у центрі ун'ґоро","розташування хребта вогняного шлейфу"}},{q="Хто править елементалями на Хребті Вогняного Шлейфу?",a="У печері на вершині живе Полум'яний бігун — наймогутніший вогняний елементаль Кратера Ун'Ґоро.",al={"бос хребта вогняного шлейфу","де блейзранер","бос вогняних елементалів ун'ґоро"}},{q="Чому на хребті застряг дослідник?",a="Шукач пригод на ім'я Рінґо, союзник гоблінів, вирушив досліджувати вулкан, але знемігся від спеки в одній із південних печер і не може вибратися без допомоги.",al={"хто застряг на хребті вогняного шлейфу","рінґо ун'ґоро","загублений у вулкані"}},{q="Як вулкан впливає на решту Ун'Ґоро?",a="Неглибокі жили магми розходяться з-під Хребта Вогняного Шлейфу під усім дном кратера, зігріваючи землю й створюючи численні гейзери, гарячі розщілини й парні озерця по всій улоговині.",al={"чому в ун'ґоро так спекотно","геотермальна активність кратера","неглибокі жили магми ун'ґоро"}}},fp="16,228,24.574.0,19.446.0,52.167.0,45.96.0,51.187.0,48.205.0"}
P.entries["subzone:fire-scar-shrine"] = {n="Святилище Вогняного Шраму",s="Святилище Вогняного Шраму — сплюндроване святилище нічних ельфів у південно-західних лісах Ашенвалю. Колись тихе місце молитви, тепер воно осквернене демонічними силами й перетворилося на виразку скверни просто на порозі Астранаару.",h="Святилище Вогняного Шраму — сплюндроване святилище нічних ельфів у південно-західних лісах Ашенвалю.",kw={"святилище вогняного шраму","культ темного берега","рада тіней","ілкруд маґтрулл","аккрілус","ашенваль"},ang={["class:Warlock"]="Сліди скверни й некеровані демонічні виклики тут виразно свідчать про таємне проникнення Ради Тіней на Калімдор.",["race:NightElf"]="Осквернення Святилища Вогняного Шраму так близько від Астранаару — гірка образа, що вимагає швидкої відплати кожному демонові, який паплюжить ліс."},sec={{t="Пошесть у лісі",b="Святилище Вогняного Шраму, що лежить на південний захід від Астранаару й на захід від Руїн Зоряного Пилу, похмуро нагадує про отруту Палаючого Легіону, яка досі лишається в Ашенвалі. Святилище піддалося демонічній скверні, яку плекають слуги таємничого Культу Темного Берега та Ради Тіней. Магія скверни перетворила довколишню землю на випалений камінь, де тепер збираються демони, відкрито кидаючи виклик захисникам лісу."},{t="Тіні Темного Берега",b="Падіння святилища в темряву очолили такі агенти, як орк-чорнокнижник Ілкруд Маґтрулл, що діяв за наказом Атрікуса Нарассіна. Хоч скверну сюди принесли смертні чаклуни, тепер вівтарним камінням безкарно никають викликані ними демони. Ця прогалина в завісі між світами часом приваблює й страшніших потвор — серед них велетенського вартового загибелі Аккрілуса."}},faq={{q="Де Святилище Вогняного Шраму?",a="Святилище Вогняного Шраму — на південному заході Ашенвалю, просто на південний захід від осередку нічних ельфів Астранаару, на південь від Святилища Аессіни й трохи на захід від Руїн Зоряного Пилу.",al={"розташування святилища вогняного шраму","де святилище вогняного шраму","святилище вогняного шраму на мапі"}},{q="Чому в Святилищі Вогняного Шраму демони?",a="У святилище проникли й осквернили його агенти Ради Тіней і Культу Темного Берега, передусім орк-чорнокнижник Ілкруд Маґтрулл. Їхні темні обряди закликали демонів і просякли священну землю невгасимою скверною.",al={"чому тут демони","що осквернило святилище вогняного шраму","хто закликав демонів"}},{q="Хто такий Аккрілус?",a="Аккрілус — грізний вартовий загибелі, що часом з'являється довкола Святилища Вогняного Шраму, приваблений потужною демонічною енергією, яка скупчується біля осквернених каменів.",al={"аккрілус","володар скверни біля вогняного шраму","рідкісний демон святилища вогняного шраму"}},{q="Що пов'язує це місце з Культом Темного Берега?",a="Орк-чорнокнижник, що діяв тут, Ілкруд Маґтрулл, служив Атрікусові Нарассіну, ватажкові Культу Темного Берега. Вони використовували святилище як плацдарм для демонічних закликань і своїх темних задумів в Ашенвалі.",al={"культ темного берега вогняний шрам","зв'язок із темним берегом","атрікус нарассін вогняний шрам"}}},fp="16,241,22.447.0,26.372.0,34.181.0,41.238.0,16.163.0,68.226.0"}
P.entries["subzone:firewatch-ridge"] = {n="Хребет Вогняної Варти",s="Хребет Вогняної Варти — висока вулканічна круча на півночі Палючої Ущелини, один із головних таборів дворфів Темного Заліза. Хребет нависає просто над величезним кар'єром, відомим як Казан, і його пильно стережуть дворфійські вартові, механічні големи та вогняні павуки, що гніздяться серед скель. На північному заході зловісна мережа печер видає, що тут міцно окопався культ Молота Присмерку.",h="Хребет Вогняної Варти — висока вулканічна круча на півночі Палючої Ущелини, один із головних таборів дворфів...",kw={"хребет вогняної варти","палюча ущелина","темне залізо","молот присмерку","культ","печери"},ang={["race:Dwarf"]="Для дворфів Айронфорджа Хребет Вогняної Варти — похмуре нагадування про вкорінену злобу їхніх родичів із клану Темного Заліза, про їхню залізну промисловість і темні союзи в тіні Гори Блекрок."},sec={{t="Обпалена висота",b="Хребет Вогняної Варти, що здіймається над спустошеним промислом Казана, — важливий плацдарм для всіх задумів клану Темного Заліза в Палючій Ущелині. Скелями ходять дозором дворфійські вартові, інженери та големи з розпеченого металу. Вони люто боронять свої позиції разом з отруйними вогняними павуками, що споконвіку живуть серед тліючих каменів. З висоти дворфам Темного Заліза відкривається вільний огляд довколишніх попелястих рівнин, тож вони завчасно помічають будь-які вилазки суперників з Айронфорджа чи Братства Торію."},{t="Тінь культу",b="У північно-західній частині хребта ховається мережа підземних печер, яку захопив Молот Присмерку. Культисти діють у тіні табору Темного Заліза: правлять темні обряди й переховують під скелею могутніх добірних фанатиків. Те, що вони отаборилися так близько і до споруд Темного Заліза, і до Гори Блекрок, свідчить, як глибоко й підступно проникли стихійні та апокаліптичні культи у вогняне серце Палючої Ущелини."}},faq={{q="Що таке Хребет Вогняної Варти?",a="Хребет Вогняної Варти — підвищення в Палючій Ущелині, де дворфи Темного Заліза влаштували великий табір над розкопками Казана.",al={"що це за місце","хребет вогняної варти інформація","огляд хребта вогняної варти"}},{q="Які вороги живуть на Хребті Вогняної Варти?",a="На хребті — ворожі дворфи Темного Заліза, механічні големи й місцеві вогняні павуки, а печери на північному заході займають добірні члени культу Молота Присмерку.",al={"які моби тут","вороги вогняної варти","загрози хребта вогняної варти"}},{q="Чому тут Молот Присмерку?",a="Культ Молота Присмерку закріпився в північно-західних печерах хребта, щоб поклонятися стихіям і правити апокаліптичні обряди поблизу Гори Блекрок і вогняних елементалів, ув'язнених у краї.",al={"молот присмерку вогняна варта","культисти в печері","північно-західна печера вогняної варти"}},{q="Як Хребет Вогняної Варти пов'язаний із Казаном?",a="Хребет Вогняної Варти здіймається просто над Казаном, тож дворфи Темного Заліза мають укріплений оглядовий пункт, щоб наглядати за видобутком і боронити кар'єр від можливих ударів.",al={"вогняна варта й казан","огляд казана","чому видно казан"}}},fp="15,407,24.518.0,22.461.0,24.153.0,37.195.0,34.235.0,48.191.0"}
P.entries["subzone:flame-crest"] = {n="Полум'яний Гребінь",s="Полум'яний Гребінь — сувора нейтральна застава на скелястому виступі над вулканічними пустирями Палаючих Степів. До цього хиткого табору можна дістатися лише грубим мостом; він слугує передовим плацдармом проти Темної Орди, що окопалася в Горі Блекрок. Тут є важливі повітряні маршрути й прихисток для розвідників, збирачів звірів і стратегів.",h="Полум'яний Гребінь — сувора нейтральна застава на скелястому виступі над вулканічними пустирями Палаючих...",ang={["race:Orc"]="Для орків, вірних Траллові, цей табір — спостережний пункт над непокірним кланом Блекрок, чия присутність плямує гору."},sec={{t="Хиткий прихисток",b="Полум'яний Гребінь, що стоїть високо на відокремленому кам'яному виступі, пильно оглядає випалений попіл і лавові рівнини Палаючих Степів. Дістатися сюди можна лише вузьким хистким дерев'яним мостом, тож застава природно захищена від хижих звірів і орчих ватаг, що бродять пустирями. На висотах гніздяться вітрокрили, що зв'язують табір через кряж Редріджу з Карґатом, Стонардом і Торієвим Мисом."},{t="У тіні Блекроку",b="Полум'яний Гребінь — не просто гніздовище вітрокрилів, а й важливий передовий спостережний пункт над кланом Блекрок, що окопався в Шпилі Блекрок. Тут, глибоко на ворожій території, розвідники збирають відомості, будують плани, як розбити бунтівну Темну Орду, і торгують із дивакуватими відлюдниками на кшталт торговця вихованцями Кіблера з сусідньої печери."}},faq={{q="Що таке Полум'яний Гребінь?",a="Полум'яний Гребінь — нейтральний табір у Палаючих Степах. Збудований на вузькому скельному виступі, куди можна дістатися лише грубим мостом, він дає повітряне сполучення, прихисток для розвідників і припаси в цьому смертельно небезпечному краї.",al={"огляд полум'яного гребеня","що таке полум'яний гребінь","табір орди в палаючих степах"}},{q="Куди літає приборкувач летунів із Полум'яного Гребеня?",a="Сідало вітрогонів на Полум'яному Гребені має прямі повітряні шляхи до Карґата на Пустищах, Стонарда на Болоті Скорботи й нейтрального перевалочного пункту Торієвий Мис у Палючій Ущелині.",al={"польоти полум'яного гребеня","маршрут польоту з полум'яного гребеня","куди ведуть шляхи з полум'яного гребеня"}},{q="Чому Орда тримає заставу в Палаючих Степах?",a="Полум'яний Гребінь — нейтральний табір, а не фортеця Орди, хоча його вітрогони й возять мандрівників з Орди. З цієї висоти видно клан Блекрок, що окопався в Горі Блекрок. Темна Орда не корюється Вождеві Траллу й становить безпосередню загрозу краю, тож місцевий оглядовий пункт життєво важливий.",al={"чому орда в палаючих степах","призначення полум'яного гребеня","місія орди на полум'яному гребені"}},{q="Хто живе в печері на Полум'яному Гребені?",a="У печері в глибині виступу живе Кіблер зі своїм балакучим папугою Опусом. Кіблер — дивакуватий приборкувач, якого цікавлять рідкісні й небезпечні звірі навколишніх пусток і Шпиля Блекрок.",al={"печера кіблера","хто в печері полум'яного гребеня","папуга полум'яного гребеня"}},{q="Що Ейтріґґ робить на Полум'яному Гребені?",a="Ейтріґґа на Полум'яному Гребені немає. Бувалий орк служить поруч із Вождем Траллом в Оргріммарі, а Полум'яний Гребінь лишається нейтральним перепочинком для торгівців, розвідників і вітрогонів, що стежать за кланом Блекрок.",al={"ейтріґґ палаючі степи","чому ейтріґґ на полум'яному гребені","аріок і ейтріґґ"}}},fp="11,376,18.436.0,19.328.0,20.229.0,48.195.0,63.309.0,37.222.0,37.216.0"}
P.entries["subzone:foothold-citadel"] = {n="Цитадель Плацдарму",s="Цитадель Плацдарму — головні казарми й командний пункт Острова Терамор. Вона височить над укріпленим поселенням і дає притулок офіцерам і вартовим, що захищають головний бастіон Альянсу на півдні Калімдору.",h="Цитадель Плацдарму — головні казарми й командний пункт Острова Терамор.",kw={"цитадель плацдарму","острів терамор","альянс","ґарран ваймс","дейлін праудмур","рекссар","тралл"},ang={["faction:Alliance"]="Цитадель — головна військова опора Альянсу на півдні Калімдору: звідси координують оборону від болотяних звірів, мародерів Ґрімтотем і пильних розвідників Орди.",["faction:Horde"]="Для Орди Цитадель Плацдарму — місце, де Рекссар і Тралл поклали край мстивій кампанії великого адмірала Праудмура й так уберегли Дуротар."},sec={{t="Серце варти Терамору",b="Цитадель Плацдарму, що здіймається в укріплених кам'яних мурах Острова Терамор, — нервовий центр місцевої оборони Альянсу. Тут розміщене верховне командування охорони Терамору, зокрема Капітан Ґарран Ваймс і Командир Самаул, а також польові цілителі, офіцери постачання й інтенданти. Її суворі кам'яні зали гудуть від регулярних патрулів і муштри, що тримають сили Леді Джайни Праудмур напоготові проти загроз, які повзуть із навколишніх боліт."},{t="Відлуння падіння адмірала",b="Цитадель має похмуру історію, пов'язану з першими днями Терамору. Коли великий адмірал Дейлін Праудмур захопив місто, щоб вести власний хрестовий похід проти Орди, саме ця фортеця стала полем його останнього бою. Союзний ударний загін Тралла на чолі з воїном-мок'наталом Рекссаром прорвався до цитаделі й убив адмірала. Нині фортецю відбудовано, вона стоїть непохитно, та пам'ять про той кривавий конфлікт досі нависає над її кам'яними мурами."}},faq={{q="Для чого Цитадель Плацдарму?",a="Цитадель Плацдарму — штаб і казарми Варти Терамору. Тут розміщуються командири, тактики, навчальні приміщення й допоміжний люд — місцевий скарбник і медики.",al={"призначення цитаделі плацдарму","казарми терамору","що це за будівля"}},{q="Що тут сталося з Великим Адміралом Дейліном Праудмуром?",a="Під час протистояння після Третьої війни Великий Адмірал Дейлін Праудмур захопив Терамор, щоб воювати з молодою Ордою. Об'єднані сили на чолі зі звитяжцем Рекссаром штурмували цитадель і вбили Адмірала в його власному штабі.",al={"смерть дейліна","остання битва дейліна праудмура","хто вбив дейліна"}},{q="Хто нині головний у Цитаделі Плацдарму?",a="Безпосереднє командування гарнізоном лежить на офіцерах на кшталт Капітана Ґаррана Ваймса й Командира Самаула, що наглядають за щоденними патрулями й безпекою краю під верховною владою Леді Джайни Праудмур.",al={"хто очолює цитадель","командир варти терамору","лідер цитаделі"}},{q="Чи можна отримати лікування в цитаделі?",a="Так. У Цитаделі Плацдарму мешкає Доктор Ґустаф ВанГаузен, що доглядає поранених вартових і навчає мандрівників Альянсу вищої польової медицини й сортування поранених.",al={"лікар у цитаделі","медик терамору","наставник першої допомоги терамор"}}},fp="16,233,28.476.0,28.503.0,34.229.0,54.241.0,47.204.0,45.164.0"}
P.entries["subzone:forest-s-edge"] = {n="Узлісся",s="Узлісся — лісистий клин землі на південно-західному порубіжжі Лісу Елвінн, обабіч якого течуть річки в бік Вестфолу. З півночі його прикриває Гарнізон Вестбрук, та ці дикі землі небезпечно заполонили гноли Річколапи під проводом горезвісного Гоґґера.",h="Узлісся — лісистий клин землі на південно-західному порубіжжі Лісу Елвінн, обабіч якого течуть річки в бік...",kw={"узлісся","гоґґер","гноли","річколапи","вестфол","гарнізон вестбрук","ліс елвінн"},ang={["faction:Alliance"]="Для новобранців, розквартированих у Лісі Елвінн, зачистка Узлісся й перемога над Гоґґером — одне з перших великих випробувань, що доводять короні їхню бойову готовність.",["profession:Herbalism"]="Тихі береги й тінисті гаї Узлісся дають звичайні лісові трави, та збирати їх часто доводиться, ухиляючись від войовничих патрулів гнолів."},sec={{t="Спірне порубіжжя",b="Узлісся на південний захід від Стормвінда, між Садом Дзеркального Озера та річками на кордоні з Вестфолом, утворює природний лісистий півострів. Попри близькість Гарнізону Вестбрук, рідкі лави армії Стормвінда лишили цей край беззахисним перед дикими звірами й загонами нападників. Серед дерев і вздовж берегів блукають вепри, та справжня загроза — скупчення гнолів Річколапів, які зробили ці ліси своїм плацдармом."},{t="Твердиня Гоґґера",b="Ліси Узлісся — мисливські угіддя Гоґґера, величезного й жорстокого ватажка гнолів. Армія Стормвінда призначила за його голову чималу винагороду, а Гоґґер тим часом керує своєю зграєю, яка нападає на мандрівників і грабує сусідні ферми, перетворюючи те, що могло б бути мирним лісом, на смертельний полігон для молодих шукачів пригод Альянсу."}},faq={{q="Де саме Узлісся?",a="Узлісся — у південно-західному куті Лісу Елвінн. Воно лежить на південь від Гарнізону Вестбрук, межуючи із Садом Дзеркального Озера й водоймами, що ведуть до Вестфолу.",al={"розташування узлісся","де узлісся","узлісся на мапі"}},{q="Чому ця місцина така небезпечна?",a="Велика агресивна зграя гнолів Річколапів захопила ці ліси й загрожує подорожнім на південно-західному прикордонні. Найбільша загроза — їхній ватажок Гоґґер, надзвичайно лютий гнол, що никає цими лісами.",al={"чому узлісся небезпечне","що на узліссі","загрози узлісся"}},{q="Хто такий Гоґґер?",a="Гоґґер — горезвісний могутній ватажок гнолів, винний у жорстоких нападах на прикордоння Елвінна. Армія Стормвінда оголосила щедру нагороду за доказ його смерті й застерігає шукачів пригод не виходити проти нього поодинці.",al={"історія гоґґера","хто такий гоґґер","інформація про гоґґера"}},{q="Чому Гарнізон Вестбрук не очистив місцину?",a="Військо Стормвінда надзвичайно розпорошене по всьому королівству. Через заворушення у Вестфолі й загрози з усіх боків гарнізонові бракує людей, щоб очистити табори гнолів, тож це лягає на плечі шукачів пригод-добровольців.",al={"чому гарнізон вестбрук не чистить","чому стормвіндська варта не допомагає","варта вестбрука"}}},fp="13,287,20.464.0,19.341.0,31.181.0,30.221.0,14.212.0,47.232.0"}
P.entries["subzone:forest-song"] = {n="Лісова Пісня",s="Лісова Пісня — давні руїни нічних ельфів на північному сході Ашенвалю, неподалік від оскверненого лісу Сатирнаару та великого порталу в Тіні Віття. Нині тут майже безлюдно — лише пильний друїд Кейнет Стіллвінд стереже східний кордон від нових загроз.",h="Лісова Пісня — давні руїни нічних ельфів на північному сході Ашенвалю, неподалік від оскверненого лісу...",kw={"лісова пісня","кейнет стіллвінд","руїни","друїд","сатирнаар","ашенваль"},ang={["class:Druid"]="Тиха присутність Кейнета Стіллвінда підкреслює самотню варту Кола Кенарія в осквернених прикордонних землях — просто під тінистими кронами поблизу Великого Дерева Тіні Віття.",["faction:Alliance"]="Лісова Пісня — важлива самотня застава для шукачів пригод з Альянсу, що перетинають північно-східний Ашенваль на шляху до Азшари чи Сквернолісся."},sec={{t="Самотня варта на сході Ашенвалю",b="Лісова Пісня, що сховалася в густих лісах північно-східного Ашенвалю, колись була вишуканим поселенням калдореїв. Сьогодні білі кам'яні колони й напівзруйновані арки поросли плющем і дикою папороттю. Руїни лежать на північний схід від Сатирнаару й трохи на північ від Лісозаготівельного Табору Бойової Пісні, що дедалі розростається, і з них відкривається тихий, але важливий огляд на східні стежки до Азшари й Тіні Віття. Хоч довколишні ліси потерпають від демонічної скверни й вилазок Орди, у самих руїнах панує моторошний спокій."},{t="Вартовий кордону",b="Нині Лісову Пісню стереже лише друїд Кейнет Стіллвінд. Із цієї напівзруйнованої застави Стіллвінд пильно стежить за темними задумами ворогів, що проникають у дикі краї, зокрема за тривожною присутністю Відступників у східних лісах. Хоч святилище лежить далеко від Астранаару і не має ні гарнізону, ні укріплень, воно — важливий збірний пункт для мандрівників Альянсу, що прямують північною дорогою до Сквернолісся чи шукають джерела скверни, яка просочується крізь крони."}},faq={{q="Хто живе в Лісовій Пісні?",a="Нині в Лісовій Пісні живе друїд нічних ельфів Кейнет Стіллвінд, що самотньо вартує серед давніх руїн.",al={"хто в лісовій пісні","нпс лісової пісні","мешканці лісової пісні"}},{q="Які загрози поблизу Лісової Пісні?",a="Руїни небезпечно близько до Сатирнаару на південному заході, що кишить зіпсованими сатирами, і до Лісозаготівельного Табору Бойової Пісні на півдні. А на північному сході — Тінь Віття, де зелений драконячий рід стереже Велике Дерево, що веде до Смарагдового Сну.",al={"небезпеки лісової пісні","вороги біля лісової пісні"}},{q="Чому тут перебуває Кейнет Стіллвінд?",a="Кейнет стежить за пересуваннями ворогів у східних лісах і спрямовує союзників проти небезпек краю — зокрема проти лихих задумів і хвороб, які поширюють Відступники, що діють у цих місцях.",al={"чому тут кейнет","призначення кейнета стіллвінда"}},{q="Чи Лісова Пісня — велике поселення Альянсу?",a="Ні. На відміну від Астранаару, Лісова Пісня — здебільшого неукріплені руїни без діючого гарнізону, крамарів чи військових споруд; це лише самотній передовий спостережний пост.",al={"містечко альянсу лісова пісня","чи лісова пісня містечко"}}},fp="11,297,35.537.0,21.515.0,25.126.0,34.252.0,40.197.0,43.177.0"}
P.entries["subzone:forgotten-coast"] = {n="Забуте Узбережжя",s="Забуте Узбережжя — дикий західний берег Фераласу, де прадавній тропічний ліс сходиться з Прихованим Морем. Цим побитим хвилями берегом бродять важкі морські велетні й водяні елементалі.",h="Забуте Узбережжя — дикий західний берег Фераласу, де прадавній тропічний ліс сходиться з Прихованим Морем.",kw={"забуте узбережжя","фералас","приховане море","морські велетні","острів сардор","твердиня перистого місяця"},ang={["faction:Alliance"]="Узбережжя — життєво важливий шлях між материком Калімдора й Твердинею Перистого Місяця на Острові Сардор, тож тут треба пильнувати мандрівних морських велетнів.",["faction:Horde"]="Наближаючись до узбережжя, будьте обережні: південна стежка виводить до поромних пристаней нічних ельфів, тож безпечніше дістатися води північними лісовими дорогами."},sec={{t="Край тропічного лісу",b="Забуте Узбережжя тягнеться вздовж західної межі Фераласу — це обвітрений берег, що стоїть лицем до неозорого Прихованого Моря. На відміну від густого лісу в глибині краю, це прикордоння відкрите всім стихіям, і владарюють тут височенні морські велетні та мандрівні водяні елементалі, що походжають у прибої. Мандрівникам, які виходять із-під лісового намету, доводиться мати справу з цими первісними вартовими берега, шукаючи шлях до моря, — звідти пороми ходять до оплоту нічних ельфів на Острові Сардор."}},faq={{q="Які загрози чатують на Забутому Узбережжі?",a="Берегом блукають величезні морські велетні й неспокійні водяні елементалі, що виходять із Прихованого Моря.",al={"монстри забутого узбережжя","небезпеки забутого узбережжя","що на узбережжі"}},{q="Як звідси дістатися до Твердині Перистого Місяця?",a="Берег — головне місце відправлення з материка через протоку до Острова Сардор, де нічні ельфи тримають Твердиню Перистого Місяця. Невеликий поромний причал на узбережжі дає безпечну переправу подалі від небезпечних морських велетнів.",al={"як дістатися до перистого місяця","човен до перистого місяця","поромна переправа до перистого місяця"}},{q="Чи може Орда дістатися Забутого Узбережжя?",a="Так. Південна дорога веде просто до переправи нічних ельфів на Твердиню Перистого Місяця, але північніше до узбережжя спускається інша стежка, тож мандрівники Орди можуть дістатися берега, не натрапивши на вартових Альянсу.",al={"доступ орди до забутого узбережжя","як орді дістатися узбережжя","безпечна стежка орди до забутого узбережжя"}}},fp="15,180,22.489.0,40.108.0,50.253.0,47.250.0"}
P.entries["subzone:forgotten-pool"] = {n="Забутий Ставок",s="Забутий Ставок — затоплена печера, захована глибоко під залитими коридорами Чорноглибинних Печер. Цей тихий глухий кут за Руїнами Місячної Святині — водяне лігво страхітливих глибоководних хижаків, що чатують у підземній темряві.",h="Забутий Ставок — затоплена печера, захована глибоко під залитими коридорами Чорноглибинних Печер.",kw={"забутий ставок","старий серра'кіс","чорноглибинні печери","руїни місячної святині","підводне лігво"},ang={["faction:Horde"]="Розвідники Орди, що спускаються в Чорноглибинні Печери, можуть натрапити на Старого Серра'кіса, який чатує в затопленій темряві ставка, далеко від залів, де співають культисти."},sec={{t="Затоплене лігво",b="Щоб дістатися Забутого ставка, доведеться пірнути в затоплені підземні протоки, що тягнуться за Руїнами Місячної Святині. Відрізаний від суходолу, ставок — відокремлена печера зі стоячою водою, геть залита темними хвилями. Далеко від співу культистів Молота Присмерку й дозорів наг ця схованка стала лігвом давнього водяного жаху, відомого як Старий Серра'кіс, і ховає звіра в затопленій темряві."}},faq={{q="Де Забутий Ставок?",a="Забутий Ставок — цілком затоплена підводна печера глибоко в Чорноглибинних Печерах. Щоб дістатися до нього, дослідникам доведеться пропливти затопленими тунелями, що відгалужуються за Руїнами Місячної Святині.",al={"де забутий ставок","розташування забутого ставка","як знайти забутий ставок"}},{q="Що чаїться в Забутому ставку?",a="Печера — приховане лігво Старого Серра'кіса, давнього звіра глибоких вод, схожого на акулу-лисицю, що облаштувався в цьому відлюдному глухому куті.",al={"чудовисько забутого ставка","хто живе в забутому ставку","бос забутого ставка"}},{q="Чи веде Забутий Ставок кудись далі?",a="Ні. Ставок — підводний глухий кут без жодних інших ходів, просто відлюдне водяне гніздо.",al={"чи забутий ставок глухий кут","куди веде забутий ставок"}}},fp="14,254,16.435.0,36.203.0,37.147.0,43.112.0"}
P.entries["subzone:forgotten-pools"] = {n="Забуті ставки",s="Забуті ставки — найпівнічніша із зелених оаз, розкиданих посушливими Пустками, трохи на північний захід від Перехрестя. Цей яскравий куточок буйної зелені й води живлять підземні джерела, і за нього запекло змагаються місцеві звірі, кочові кентаври Колкари та Орда.",h="Забуті ставки — найпівнічніша із зелених оаз, розкиданих посушливими Пустками, трохи на північний захід від...",kw={"забуті ставки","оаза","колкари","девіантна риба","перехрестя","пустки"},ang={["class:Druid"]="Буйне розростання змінених рослин і Девіантна Риба довкола цих ставків — важливі докази для кенарійських дослідників, що вивчають неприродні зміни в Пустках.",["faction:Horde"]="Утримати ставки вкрай важливо для безпеки торгових шляхів, що розходяться від Перехрестя: не можна дозволити Колкарам перекрити західні шляхи постачання Орди."},sec={{t="Оаза серед пустки",b="Забуті ставки, що лежать біля західної дороги з Перехрестя, разюче контрастують із висохлими саванами довкола. Густий очерет, пальми й незвичайні рослини на кшталт Налитих Грибів тісняться біля прісного берега, приваблюючи степових довгоступів, черепах-хижощелепів і жевр з усієї округи. Та оаза аж ніяк не мирна. Кентаври Колкари постійно стоять табором на берегах, ревниво стережучи воду від мандрівників, і раз у раз сходяться в сутичках із подорожніми Орди з Перехрестя."},{t="Загадки природи",b="Окрім стратегічного значення як водопою, Забуті ставки мають дивні природні особливості. Це одна з рідкісних наземних водойм краю, де водиться загадкова Девіантна Риба, — натяк на глибші підземні зв'язки з дивними перетворювальними силами, що змінюють підземні води Пусток. Дослідники природи й розвідники Орди пильно стежать за водою та незвичними грибами на берегах, остерігаючись того, що може просочуватися в ґрунт."}},faq={{q="Де Забуті ставки?",a="Забуті ставки лежать на півночі Пусток, просто на північний захід від Перехрестя, трохи на північ від дороги, що відгалужується на захід до Гір Кам'яного Кігтя.",al={"розташування забутих ставків","де забуті ставки","знайти забуті ставки"}},{q="Чому тут кентаври Колкари?",a="У посушливих Пустках вода — це життя. Колкари агресивно захоплюють кожну оазу, до якої можуть дотягтися, щоб живити свої бойові ватаги й позбавити життєво важливих ресурсів каравани Орди й сусідні поселення.",al={"кентаври біля забутих ставків","чому тут колкари","колкари забуті ставки"}},{q="Чим незвичні тутешні риба й рослини?",a="Оаза — одне з небагатьох місць на поверхні, де можна впіймати Девіантну Рибу, і тут ростуть грона незвичних Обтяжених Грибів. Ці дивні мутації вказують на підземні збурення, що впливають на водоносні шари під Пустками.",al={"збочена риба забутих ставків","важкі гриби","чому риба дивна"}},{q="Чи проходив Тралл через цю оазу?",a="Жодні записи не кажуть, у яких оазах відпочивала Орда Тралла під час довгого походу через Пустки, тож чи були серед них Забуті ставки — невідомо.",al={"тралл забуті ставки","чи орки отаборилися тут","оаза з варкрафта 3"}}},fp="15,303,22.557.0,20.456.0,38.162.0,32.194.0,44.237.0,35.152.0"}
P.entries["subzone:forlorn-cavern"] = {n="Покинута Печера",s="Покинута Печера — тьмяно освітлений, усамітнений куточок на північному березі підземного озера Айронфорджа, далеко від гамірної Великої Кузні. Це похмурий прихисток, де злодії, кишенькові злодюжки й ті, хто практикує темні мистецтва, ведуть свої справи подалі від цікавих очей дворфійської варти.",h="Покинута Печера — тьмяно освітлений, усамітнений куточок на північному березі підземного озера Айронфорджа...",kw={"покинута печера","айронфордж","розбійники","чорнокнижники","отрути","підземне озеро"},ang={["class:Rogue"]="Печера — головний осередок розбійників Альянсу в Каз Модані: тут можна знайти отрути, особливі клинки й обережних наставників, що ховаються вздовж вогких кам'яних переходів."},sec={{t="Затінений куток Айронфорджа",b="While the rest of Ironforge clangs with anvil strikes and radiates heat from the Great Forge, the Forlorn Cavern is cold, damp, and hushed. Wrapping along the northern edge of the mountain's underground lake, the winding pathways sit comfortably out of sight between the Mystic Ward and the Hall of Explorers. Its gloom makes it an ideal gathering place for those who prefer to keep their affairs discreet. Rogues and warlocks train here alongside vendors serving them, while weapon merchants and fishermen also work beside the lake."}},faq={{q="Де в Айронфорджі Покинута Печера?",a="Печера — у північній частині Айронфорджа, біля підземного озера. Увійти до неї можна, рушивши на схід із Кварталу містиків або на захід тунелем від Зали Дослідників.",al={"розташування покинутої печери","як дістатися до покинутої печери","де покинута печера"}},{q="Чому тут збираються розбійники й чорнокнижники?",a="The cavern is naturally dark and secluded, making it a discreet meeting place. Rogue and warlock trainers and merchants serving both groups can be found here.",al={"чому тут чорнокнижники","чому розбійники в покинутій печері","темний квартал айронфорджа"}},{q="Які крамниці й послуги є в Покинутій Печері?",a="Окрім наставників розбійників і чорнокнижників, у печері є крамниця «Руни й Приречення Боунґріпа» для знавців темної магії, зброярня «Камінний Клинок» і тиха рибальська крамничка «Мандрівний Рибалка».",al={"торговці покинутої печери","крамниці покинутої печери"}}},fp="14,316,25.533.0,49.190.0,39.158.0,59.220.0"}
P.entries["subzone:forlorn-cloister"] = {n="Покинута Обитель",s="Покинута Обитель — кладовищенське крило Багряного Монастиря, де водиться нечисть. Тут члени Багряного Хрестового Походу у відчаї палять тіла полеглих братів, щоб ті не повстали нежиттю, а між гробницями блукають неспокійні духи й шкандибають мерці.",h="Покинута Обитель — кладовищенське крило Багряного Монастиря, де водиться нечисть.",kw={"покинута обитель","багряний монастир","маг крові талнос","кладовище","нежить","чума"},ang={["class:Priest"]="Прогулянка Покинутою Обителлю тверезо нагадує, що буває, коли святі місця підкоряються темряві: священні обряди поступаються гарячковим багаттям і змученим примарам.",["race:Undead"]="Відступники бачать у цій обителі похмуру іронію: ревні хрестоносці, які таврують усю нежить як чудовиськ, не можуть навіть завадити власним братам повставати в них під ногами."},sec={{t="Поглинута святість",b="Колись Покинута Обитель була мирним притулком, де жерці й паладини Лордерону ховали своїх шанованих мерців, а тепер стала похмурим цвинтарем-костницею. Попри фанатичну пильність Багряного Хрестового Походу, скверна чуми глибоко просочилася в землю. Хрестоносці зі смолоскипами патрулюють оповитий туманом цвинтар і гарячково палять рештки, щоб стримати гниття. Та попри все між склепами пропливають привиди, а мерці виповзають із могил, і всім тут править темна магія, що ховається в глибині цвинтаря."},{t="Володар гробниць",b="У глибині обителі чатує маг крові Талнос — садист-кат Багряних, чия жахлива доля втілює трагедію Монастиря. Заразившись чумою, Талнос повстав кістяною почварою й віддався темній некромантії: він сковує душі померлих і вбиває кожного, хто посміє вдертися на його осквернений цвинтар."}},faq={{q="Де Покинута Обитель?",a="Покинута Обитель — крило кладовища просто неба в Багряному Монастирі, у північно-східному куті Галявин Тірісфалю.",al={"розташування покинутої обителі","де обитель","цвинтарне крило"}},{q="Чому хрестоносці Багряного Походу тут спалюють тіла?",a="Хрестовий Похід спалює мерців у відчайдушній спробі не дати чумі Погибелі оживити полеглих товаришів. Ґрунт обителі вже отруєний, тож неспалені тіла швидко повстають безмозкими зомбі.",al={"чому палять тіла","палені тіла багряні","що роблять хрестоносці"}},{q="Хто панує в Покинутій Обителі?",a="На кладовищі панує маг крові Талнос — могутній заклинач-нежить, що командує мандрівними мерцями й нападає на будь-яких живих непроханих гостей.",al={"бос обителі","хто тут головний","бос цвинтаря"}},{q="Чому на кладовищі привиди, якщо Монастир тримає Багряний Хрестовий Похід?",a="Попри свій релігійний запал, хрестоносці втратили контроль над власним цвинтарем. Невпинна некромантична енергія, що прокочується Лордероном, сколихнула похованих мерців, і живий гарнізон опинився в пастці безкінечної боротьби з духами своїх колишніх побратимів.",al={"чому тут привиди","чому нежить у монастирі","чи цвинтар від погибелі"}}},fp="16,270,23.503.0,23.332.0,38.138.0,50.217.0,36.144.0,72.281.0"}
P.entries["subzone:forlorn-ridge"] = {n="Покинутий Хребет",s="Покинутий Хребет — високий гірський хребет, що нависає над південно-західною Азшарою. Його вигідна висота й широкий краєвид на узбережжя привернули увагу і Альянсу, і Орди, які звели на його схилах свої укріплення.",h="Покинутий Хребет — високий гірський хребет, що нависає над південно-західною Азшарою.",kw={"покинутий хребет","азшара","спірна територія","альянс","орда","вулкан"},ang={["faction:Alliance"]="Утримуючи висоти Покинутого Хребта, Альянс може завчасно помітити війська Орди, що сунуть на схід із Пусток і Ашенвалю, і стежити за ними.",["faction:Horde"]="Для Орди закріпитися на Покинутому Хребті — означає вберегти від вторгнень Альянсу скелясте прикордоння Азшари просто на північ від Дуротару."},sec={{t="Спірна висота",b="Покинутий Хребет, що круто здіймається над осінніми лісами західної Азшари, панує над усією місцевістю. Схожий на прадавній вулкан, що давно заснув, він дає з вершини широкий огляд прибережних підступів і зруйнованих ельфійських маєтків унизу. Хто тримає ці висоти, той панує в усьому краї, тож і Альянс, і Орда облаштували на гірських схилах табори й застави й насторожено стежать одні за одними через скелясті кручі."}},faq={{q="Що таке Покинутий Хребет?",a="Покинутий Хребет — помітне гірське утворення на південному заході Азшари, що височіє над місцевими нетрями й прибережними дорогами.",al={"де покинутий хребет","покинутий хребет ашара","що це за гора"}},{q="Чому Альянс і Орда воюють за цей хребет?",a="З хребта видно весь захід Азшари, як ні звідки. Хто тримає висоту, той стежить за пересуваннями військ між прибережними руїнами й внутрішніми перевалами, тож обидві фракції укріплюють позиції на його схилах.",al={"чому тут табори","хто контролює покинутий хребет","альянс проти орди на покинутому хребті"}},{q="Чи був Покинутий Хребет колись вулканом?",a="Своєрідна форма й суворий склад гори свідчать, що в далекому минулому вона, можливо, була вулканічним утворенням, хоча давно затихла й поросла.",al={"чи покинутий хребет вулкан","вулкан в ашарі"}}},fp="13,256,19.496.0,22.133.0,56.230.0,39.176.0"}
P.entries["subzone:forlorn-rowe"] = {n="Покинутий Ряд",s="Покинутий Ряд — зловісний темний пагорб на північній межі Цвинтаря Воронячого Пагорба в Сутінколіссі. Він сумно відомий як похмуре житло Морбента Фела — некроманта, чия зла магія піднімає неспокійних мерців по всьому лісу.",h="Покинутий Ряд — зловісний темний пагорб на північній межі Цвинтаря Воронячого Пагорба в Сутінколіссі.",kw={"покинутий ряд","морбент фел","некромант","цвинтар","сутінколісся"},ang={["class:Paladin"]="Темні обряди, сплетені в Покинутому Ряду, — образа для Святого Світла: щоб пробити захист некроманта, потрібні освячені реліквії та праведний гнів.",["faction:Alliance"]="Вигнати Морбента Фела з Покинутого Ряду конче потрібно, щоб повернути західному прикордонню Сутінколісся бодай подобу безпеки."},sec={{t="Осідок некромантії",b="Покинутий Ряд, що здіймається вздовж північного краю Цвинтаря Воронячого Пагорба, вічно огорнутий мороком. На вершині стоїть дім Морбента Фела — схожого на ліча некроманта, через якого довколишні нетрі заполонили ходячі мерці. Захищений мерзенними таємними чарами, господар пагорба звідси керує своїми слугами-скелетами, і весь північно-західний куток Сутінколісся стає небезпечним для мандрівників."},{t="Очищення пагорба",b="Владу Морбента Фела над Покинутим Рядом не зламати самою лише звичайною сталлю. Темні чари захищають його тіло від смертної зброї, доки його не послаблять особливі реліквії святої сили. Щоб здолати некроманта й розірвати його владу над лісом, шукачам пригод доведеться роздобути освячену зброю й ударити в саме серце прокляття, що душить цвинтар."}},faq={{q="Де Покинутий Ряд?",a="Покинутий Ряд — на північному заході Сутінколісся, просто на північному хребті над розлогим Цвинтарем Воронячого Пагорба.",al={"розташування покинутого ряду","де покинутий ряд","знайти покинутий ряд"}},{q="Хто живе в Покинутому Ряді?",a="Це лігво Морбента Фела — могутнього й лихого некроманта, що темними тайними обрядами підіймає легіони нежиті, які блукають Сутінколіссям, і командує ними.",al={"хто в покинутому ряді","бос покинутого ряду","будинок на пагорбі сутінколісся"}},{q="Чому з Морбентом Фелом тут так важко битися?",a="Морбент Фел захищається мерзенним чаклунством, тож звичайні удари майже марні, доки освячена реліквія, створена, щоб розвіяти його магію, не позбавить його темного захисту.",al={"щит морбента фела","морбент фел імунний","як убити морбента фела"}},{q="Чи Покинутий Ряд — частина цвинтаря?",a="Так, це підвищена круча на північній межі Цвинтаря Воронячого Пагорба, просто над могилами й склепами внизу.",al={"чи покинутий ряд крукопагорб","зв'язок із крукопагорбом"}}},fp="12,253,20.441.0,18.396.1,34.140.0,30.158.0,41.184.1,41.141.0"}
